(function(){var m=window.SITE_DATA_BY_DOMAIN=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]=m["multimodal"]||{};d["theory"]=[{"id":"th-vit-roofline","title":"视觉编码器 Roofline 界","direction":"dir-visual-token-compression","prereq":[],"plain":"视觉编码器在 Blackwell 上要么被 HBM 带宽卡住、要么被 Tensor Core 算力卡住，二者取小决定单张图像编码的延迟下限；分辨率越高越容易从带宽受限滑向算力受限。","definition":"视觉编码器在 Blackwell 上要么被 HBM 带宽卡住、要么被 Tensor Core 算力卡住，二者取小决定单张图像编码的延迟下限；分辨率越高越容易从带宽受限滑向算力受限。","formula":"$$T_{\\min}=\\max\\!\\left(\\frac{F_{\\text{enc}}}{\\eta_{\\text{TFLOPS}}\\cdot P_{\\text{peak}}},\\ \\frac{B_{\\text{enc}}}{\\eta_{\\text{BW}}\\cdot \\text{BW}_{\\text{HBM}}}\\right)$$","variables":[{"sym":"F_{\\text{enc}}","meaning":"单张图像编码所需浮点运算量（FLOPs），随分辨率与 patch 数增长"},{"sym":"B_{\\text{enc}}","meaning":"编码阶段必须从 HBM 搬运的字节数（权重+激活+输入像素）"},{"sym":"P_{\\text{peak}}","meaning":"Blackwell SM 在目标精度下的峰值算力（如 FP8/BF16 TFLOPS）"},{"sym":"\\text{BW}_{\\text{HBM}}","meaning":"HBM3e 峰值带宽（B200 约 8 TB/s 量级）"},{"sym":"\\eta_{\\text{TFLOPS}},\\ \\eta_{\\text{BW}}","meaning":"实测算力/带宽利用效率，通常 0.4–0.8"}],"derivation":"推导关键一步是把计算时间 $$F_{\\text{enc}}/(\\eta_{\\text{TFLOPS}}P_{\\text{peak}})$$ 与访存时间 $$B_{\\text{enc}}/(\\eta_{\\text{BW}}\\text{BW}_{\\text{HBM}})$$ 视为可完全重叠的两条流水，取 max 得到稳态下界，效率因子 0.4–0.8 吸收实测损耗。","example":"在容量决策中，该界用于判断给定分辨率下应优先扩带宽还是扩算力：若带宽项占优，增加 SM 无益，应提高 batch 或做 token 压缩；若算力项占优，则 FP8 量化与 Tensor Core 利用率成为关键杠杆。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["仅适用于计算与访存可完全重叠的稳态流水；小 batch 或 kernel launch 开销主导时实际延迟高于该下界","假设视觉编码器为 dense Transformer，若使用稀疏注意力或卷积混合结构，F_enc 与 B_enc 需按实际算子重算"],"system_note":"常见误用是把该下界当作实测延迟承诺，忽略 launch 开销与流水未填满阶段，导致小 batch 服务容量被高估；另一误用是对稀疏或混合结构直接套用 dense 的 FLOPs 计数，得出错误的瓶颈判断。","papers":["paper-an-image-is-worth-16x16-words-transf-2020"],"facts":["直觉上，视觉编码器在 Blackwell 上的单图延迟下限由 HBM 带宽与 Tensor Core 算力两条约束取较大者决定，分辨率升高会把瓶颈从带宽侧推向算力侧。","公式中 $$F_{\\text{enc}}$$ 是单图编码的浮点运算量，随分辨率与 patch 数增长；$$B_{\\text{enc}}$$ 是编码阶段必须从 HBM 搬运的字节数，含权重、激活与输入像素；$$P_{\\text{peak}}$$ 与 $$\\text{BW}_{\\text{HBM}}$$ 分别为目标精度峰值算力与 HBM3e 峰值带宽。","推导关键一步是把计算时间 $$F_{\\text{enc}}/(\\eta_{\\text{TFLOPS}}P_{\\text{peak}})$$ 与访存时间 $$B_{\\text{enc}}/(\\eta_{\\text{BW}}\\text{BW}_{\\text{HBM}})$$ 视为可完全重叠的两条流水，取 max 得到稳态下界，效率因子 0.4–0.8 吸收实测损耗。","适用边界是 dense Transformer 视觉编码器且计算与访存可完全重叠的稳态流水；小 batch 或 kernel launch 开销主导时实际延迟高于该下界，稀疏注意力或卷积混合结构需按实际算子重算 $$F_{\\text{enc}}$$ 与 $$B_{\\text{enc}}$$。","在容量决策中，该界用于判断给定分辨率下应优先扩带宽还是扩算力：若带宽项占优，增加 SM 无益，应提高 batch 或做 token 压缩；若算力项占优，则 FP8 量化与 Tensor Core 利用率成为关键杠杆。","常见误用是把该下界当作实测延迟承诺，忽略 launch 开销与流水未填满阶段，导致小 batch 服务容量被高估；另一误用是对稀疏或混合结构直接套用 dense 的 FLOPs 计数，得出错误的瓶颈判断。"],"anchors":["B200 约 8 TB/s 量级","效率 0.4–0.8"],"pitfalls":["用小 batch 实测延迟去反推 roofline 下界，会把 kernel launch 与流水填充开销误记为带宽或算力不足，导致扩容方向选错。","对采用稀疏注意力或卷积混合的视觉编码器直接套用 dense FLOPs，低估算力项或高估带宽项，得出与实际相反的瓶颈结论。","把效率因子 0.4–0.8 当成固定常数跨模型跨精度复用，忽略不同 kernel 实现下实际利用率差异，容量规划出现系统性偏差。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-1\">一 · 一句话直觉：两条流水取大者</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-2\">二 · 严格定义：下界而非承诺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-3\">三 · 为什么需要这个界：容量决策的方向盘</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-4\">四 · 常见误解之一：把下界当承诺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-5\">五 · 常见误解之二：对非 dense 结构套 dense 计数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-6\">六 · 常见误解之三：效率因子当常数跨模型复用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-7\">七 · 边界条件：这条下界在什么情况下会失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-8\">八 · 边界：Roofline 下界在什么条件下失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-9\">九 · 两个时间项的量纲对齐与物理含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-10\">十 · 取 max 的推导关键步：重叠流水假设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-11\">十一 · 效率因子 0.4–0.8 的离散化来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-12\">十二 · 失效条件的逐条推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-13\">十三 · 从公式到容量决策的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-14\">十四 · 当 max 失效：重叠假设、效率因子与算子重算的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-15\">十五 · 公式成立的三条隐含前提</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-16\">十六 · 小 batch 与 launch 开销：下界变成上界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-17\">十七 · 非 dense 结构：FLOPs 计数失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-18\">十八 · 效率因子的复用边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-19\">十九 · 规模上限：什么时候 roofline 不再是主导约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-20\">二十 · 失效条件的工程清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-21\">二十一 · 边界在哪里：从稳态流水到失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-22\">二十二 · 从下界到容量：批大小的可行域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-23\">二十三 · 定并行度：按瓶颈侧选切分维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-24\">二十四 · 定 KV 预算：编码器延迟与解码显存的时间-空间换算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-25\">二十五 · 定 SLO：下界是尾延迟的地板，不是均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-26\">二十六 · 算例：一个分辨率-批-并行的联合决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-27\">二十七 · 把下界换算成容量决策：何时该扩带宽、何时该扩算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-28\">二十八 · 误用一：把下界当承诺，小 batch 反推容量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-29\">二十九 · 误用二：对稀疏/混合结构套 dense FLOPs</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-30\">三十 · 误用三：效率因子当常数跨模型跨精度复用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-31\">三十一 · 反例：一次被误用的容量决策复盘</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-roofline-sec-32\">三十二 · 误用与反例：把下界当承诺、把 dense 计数当普适尺</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:533px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 532.8 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：视觉编码器在 Blackwell 上要么被 HBM 带宽卡住、要么…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$T_{\\min}=\\max\\!\\left(\\frac{F_{\\…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：仅适用于计算与访存可完全重叠的稳态流水；小 batch 或 ker…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-vit-roofline-sec-1\">一 · 一句话直觉：两条流水取大者</h3>\n<p>视觉编码器在 Blackwell 上的单图延迟，不是“算得快就快”，也不是“带宽大就快”，而是被两条独立流水同时约束：Tensor Core 把权重与激活乘加完所需的时间，和 HBM 把这些字节搬到 SM 所需的时间。稳态下这两条流水可以完全重叠，于是实际下限是两者中较大的那个——<strong>谁更慢，谁就是瓶颈</strong>。分辨率是把这个瓶颈从带宽侧推向算力侧的旋钮：patch 数增加使 $$F_{\\text{enc}}$$ 近似平方增长，而权重字节数基本不变，激活与输入像素字节线性增长，因此高分辨率图像几乎必然滑向算力受限。</p>\n<p>这个直觉的工程价值在于它给出了一个“先看哪一侧”的判断顺序。面对一个在 B200 上跑得不如预期的视觉编码器，第一件事不是盲目加 SM 或换精度，而是把 $$F_{\\text{enc}}$$ 与 $$B_{\\text{enc}}$$ 各自除以对应的峰值再乘效率因子，看哪一项更大。若带宽项占优，增加 SM 数量对延迟毫无帮助，因为 SM 都在等数据；此时提高并发 batch 让多次搬运摊薄、或做视觉 token 压缩才是正确杠杆。若算力项占优，则 FP8 量化、tcgen05 的 MMA 利用率、TMEM 驻留策略成为关键。</p>\n\n<h3 id=\"th-vit-roofline-sec-2\">二 · 严格定义：下界而非承诺</h3>\n<p>把直觉写成可计算的量。设单张图像编码所需浮点运算量为 $$F_{\\text{enc}}$$（随分辨率与 patch 数增长），编码阶段必须从 HBM 搬运的字节数为 $$B_{\\text{enc}}$$（含权重、激活与输入像素），目标精度下 Blackwell SM 的峰值算力为 $$P_{\\text{peak}}$$，HBM3e 峰值带宽为 $$\\text{BW}_{\\text{HBM}}$$（B200 约 8 TB/s 量级）。引入实测算力利用效率 $$\\eta_{\\text{TFLOPS}}$$ 与带宽利用效率 $$\\eta_{\\text{BW}}$$，二者通常落在 0.4–0.8。则单图编码的稳态延迟下界为：</p>\n<div class=\"formula\">$$T_{\\min}=\\max\\!\\left(\\frac{F_{\\text{enc}}}{\\eta_{\\text{TFLOPS}}\\cdot P_{\\text{peak}}},\\ \\frac{B_{\\text{enc}}}{\\eta_{\\text{BW}}\\cdot \\text{BW}_{\\text{HBM}}}\\right)$$</div>\n<p>推导的关键一步是把计算时间与访存时间视为两条可完全重叠的流水，取 max 得到稳态下界；效率因子吸收实测损耗，而不是把峰值当实际值。这个定义有三个必须同时成立的限定：其一，视觉编码器是 dense Transformer，$$F_{\\text{enc}}$$ 可按标准注意力与前馈的乘加计数；其二，计算与访存处于可完全重叠的稳态流水，流水已填满；其三，batch 足够大，kernel launch 开销不主导。三者任一不成立，$$T_{\\min}$$ 就只是下界，实测延迟会高于它。</p>\n<p>注意 $$B_{\\text{enc}}$$ 的口径：它包含权重、激活与输入像素三部分，而不是只算权重。低分辨率、小 batch 时权重字节占主导；高分辨率时激活与输入像素字节迅速上升，可能反过来压过权重。这也是为什么同一编码器在不同分辨率下瓶颈侧会翻转——不是模型变了，是 $$B_{\\text{enc}}$$ 的构成变了。</p>\n\n<h3 id=\"th-vit-roofline-sec-3\">三 · 为什么需要这个界：容量决策的方向盘</h3>\n<p>没有这个界，容量规划只能靠实测扫参：换分辨率、换 batch、换精度各跑一遍，成本高且无法外推。有了它，可以在给定分辨率下先判断“该扩带宽还是扩算力”。若带宽项占优，增加 SM 无益——SM 在等 HBM 数据，扩容只是增加闲置算力；正确动作是提高 batch 让权重搬运摊薄到多张图、或做视觉 token 压缩降低激活字节。若算力项占优，FP8 量化把 $$P_{\\text{peak}}$$ 抬高、Tensor Core 利用率成为关键杠杆，而堆带宽是浪费。</p>\n<p>具体例子：一个 dense 视觉编码器在低分辨率、小 batch 下服务，实测单图延迟明显高于按公式算出的下界。此时若误判为“带宽不足”而去增加 HBM 侧并发或换更高带宽配置，延迟不会改善——真正原因是 kernel launch 与流水填充开销主导，公式的稳态假设不成立。反过来，若在高分辨率、大 batch 下带宽项确实占优，却去做 FP8 量化，算力项被进一步压低但瓶颈仍在带宽侧，端到端延迟几乎不动。这两种误判都会让扩容方向选错，代价是采购与调优工时的双重浪费。</p>\n<p>该界还承担一个诊断功能：当实测延迟远高于 $$T_{\\min}$$ 时，差值本身就是“非稳态开销”的度量——launch 开销、流水未填满、kernel 实现低效。把差值归因清楚，才能决定是优化 kernel 还是调整 batch 结构。</p>\n\n<h3 id=\"th-vit-roofline-sec-4\">四 · 常见误解之一：把下界当承诺</h3>\n<p>最常见的误用是把 $$T_{\\min}$$ 当作实测延迟的承诺值。它是稳态流水下的下限，不是任何 batch 下都能达到的值。小 batch 服务中，kernel launch 开销与流水填充阶段占比高，实际延迟高于下界，若按 $$T_{\\min}$$ 估算单卡容量，会系统性高估吞吐、低估所需副本数。更隐蔽的失败模式是用小 batch 实测延迟去反推 roofline 下界：把 launch 与填充开销误记为“带宽不足”或“算力不足”，于是扩容方向选错——本该优化 kernel 启动与批结构，却去堆硬件。</p>\n<p>工程判断：用 $$T_{\\min}$$ 做容量规划时，必须同时给出适用的 batch 下限。低于该下限的请求应走另一套时延模型（连续批处理下的时延模型是另一条目的主题，此处只指路）。把 $$T_{\\min}$$ 与实测的差值按 batch 分层记录，能直接看出流水从何时开始填满。</p>\n\n<h3 id=\"th-vit-roofline-sec-5\">五 · 常见误解之二：对非 dense 结构套 dense 计数</h3>\n<p>第二个误用是对稀疏注意力或卷积混合结构的视觉编码器直接套用 dense 的 FLOPs 计数。稀疏注意力实际乘加量远低于 dense 计数，若仍按 dense 的 $$F_{\\text{enc}}$$ 代入，会高估算力项、低估算力受限的程度，得出“带宽受限”的错误结论；卷积混合结构中卷积的访存模式与 Transformer 差异大，$$B_{\\text{enc}}$$ 的激活字节口径也要重算。结论可能完全相反：实际是算力受限，却被判成带宽受限，于是去堆带宽而非做量化。</p>\n<p>正确做法是按实际算子重算 $$F_{\\text{enc}}$$ 与 $$B_{\\text{enc}}$$：稀疏注意力的实际参与 token 对数、卷积的权重复用与激活搬运量，都要按 kernel 实现口径统计，而不是按参数量粗略折算。这一步的误差直接决定瓶颈判断的方向。</p>\n\n<h3 id=\"th-vit-roofline-sec-6\">六 · 常见误解之三：效率因子当常数跨模型复用</h3>\n<p>第三个误用是把 $$\\eta_{\\text{TFLOPS}}$$ 与 $$\\eta_{\\text{BW}}$$ 的 0.4–0.8 当成固定常数，跨模型、跨精度直接复用。不同 kernel 实现下实际利用率差异显著：同一编码器在 BF16 与 FP8 下的 Tensor Core 利用率不同，不同注意力实现的带宽利用率也不同。把一组效率因子套到所有配置上，容量规划会出现系统性偏差——某些配置被高估、某些被低估，且偏差方向随模型变化而不固定。</p>\n<p>工程上应把效率因子视为需要标定的量：对目标模型与目标精度，用一组已知 $$F_{\\text{enc}}$$、$$B_{\\text{enc}}$$ 的输入实测延迟，反解出该配置下的有效效率，再用于外推。标定一次的成本远低于反复扫参，且能把“kernel 实现差”与“硬件不足”区分开。</p>\n<table class=\"mini\"><thead><tr><th>误解</th><th>错误动作</th><th>后果</th></tr></thead><tbody><tr><td>把下界当承诺</td><td>按 $$T_{\\min}$$ 估算小 batch 容量</td><td>高估吞吐，副本数不足</td></tr><tr><td>套 dense 计数</td><td>对稀疏/卷积混合用 dense FLOPs</td><td>瓶颈判断反向，扩容方向错</td></tr><tr><td>效率因子当常数</td><td>跨模型跨精度复用 0.4–0.8</td><td>容量规划系统性偏差</td></tr></tbody></table>\n<p>三种误解共享一个根源：把公式的适用边界当成普适真理。$$T_{\\min}$$ 的价值恰恰在于它明确标注了自己的失效条件——dense 结构、稳态流水、batch 足够大。守住这三条，它就是一个能在容量决策前快速定方向的工具；越过这三条，它给出的数字会比没有公式更危险，因为它带着“算过”的可信外观。</p>\n\n<h3 id=\"th-vit-roofline-sec-7\">七 · 边界条件：这条下界在什么情况下会失效</h3>\n<p>把 roofline 下界当成容量规划的输入，前提是它确实刻画了目标负载。失效的第一类情形是流水未填满：公式把计算时间与访存时间视为两条可完全重叠的流水并取 max，这要求编码器内部有足够多的独立工作让 DMA 与 Tensor Core 持续并行。当 batch 很小、单图 token 数又不足以把 SM 阵列喂满时，kernel launch 开销与流水填充/排空阶段会主导端到端延迟，此时实测值系统性高于 <span class=\"sym\">\\(T_{\\min}\\)</span>，差值不来自带宽不足也不来自算力不足，而来自调度粒度。工程上的判别方法是做 batch 扫描：若延迟随 batch 增大呈明显下降趋势而非持平，说明当前工作点落在下界之外，用该点反推瓶颈会得出错误结论——把 launch 开销误记为带宽或算力欠缺，进而选错扩容方向（加 SM 还是加带宽）。</p>\n<p>第二类失效来自算子构成假设。公式的 <span class=\"sym\">\\(F_{\\text{enc}}\\)</span> 与 <span class=\"sym\">\\(B_{\\text{enc}}\\)</span> 是按 dense Transformer 的矩阵乘与注意力计数得到的；若视觉编码器采用稀疏注意力、窗口注意力或卷积混合结构，实际浮点运算量与访存字节数需按真实算子重算，直接套用 dense 计数会同时扭曲分子与分母。稀疏注意力通常低估算力项、相对高估带宽项，从而把本已算力受限的工作点误判为带宽受限，得出与实际相反的瓶颈结论；卷积混合结构则改变了激活搬运的粒度与复用模式，<span class=\"sym\">\\(B_{\\text{enc}}\\)</span> 的构成不再是简单的权重加激活加像素。判断是否可套用，要看编码器中 dense GEMM 与注意力的 FLOPs 占比是否占绝对多数，占比不足时该界只能作量级参考。</p>\n<p>第三类偏差来自效率因子的跨配置复用。0.4–0.8 这个区间吸收的是实测损耗，它随 kernel 实现、精度路径与形状分布变化：同一模型在 BF16 与 FP8 下的 <span class=\"sym\">\\(\\eta_{\\text{TFLOPS}}\\)</span> 不同，不同 attention 后端下的 <span class=\"sym\">\\(\\eta_{\\text{BW}}\\)</span> 也不同。把某一配置下测得的效率因子当作常数迁移到另一模型或另一精度，容量规划会出现系统性偏差，且偏差方向不可预知。稳妥做法是对每个待规划配置单独标定两个效率因子，标定成本远低于按错误因子扩容的代价。</p>\n<table class=\"mini\"><thead><tr><th>情形</th><th>下界是否可用</th><th>系统代价表现</th></tr></thead><tbody><tr><td>大 batch、dense 编码器、稳态流水</td><td>可用，作为延迟下限</td><td>带宽项与算力项之一主导，扩容方向明确</td></tr><tr><td>小 batch、launch 开销主导</td><td>不可用，实测高于下界</td><td>延迟被调度开销占据，SM 与带宽均未饱和</td></tr><tr><td>稀疏/卷积混合结构</td><td>需重算 F、B 后才可用</td><td>瓶颈判断可能反转，扩容选错方向</td></tr><tr><td>效率因子跨配置复用</td><td>形式可用，数值失真</td><td>容量高估或低估，SLO 兑现出现偏差</td></tr></tbody></table>\n<p>因此这条界的正确用法是判向而非定量承诺：它回答“给定分辨率下该优先扩带宽还是扩算力”，不回答“实测延迟会是多少”。当带宽项占优时增加 SM 无益，应转向提高 batch 或做 token 压缩；当算力项占优时 FP8 量化与 Tensor Core 利用率才是杠杆。把判向结论直接写成延迟承诺，是小 batch 服务容量被高估的常见来源。</p>\n\n<h3 id=\"th-vit-roofline-sec-8\">八 · 边界：Roofline 下界在什么条件下失效</h3>\n<p>把 $T_{\\min}$ 当成“实测延迟承诺”是这一节要拆掉的第一块砖。公式的推导前提是计算流水与访存流水可完全重叠、且处于稳态：每个 tile 的 MMA 与下一次 HBM 预取在时间轴上咬合，没有气泡。这个前提在视觉编码器上并不总是成立——ViT 类编码器的 patch embedding 是极小的卷积或矩阵乘，随后是数十层 attention/MLP 交替，层间存在天然的同步点与归一化屏障，流水在每层边界都会被部分排空。当 batch 很小（单图或个位数），单次 kernel 的执行时间与 launch 开销同量级，此时实测延迟高于下界不是“带宽不够”也不是“算力不够”，而是根本没有进入稳态。用这种实测值去反推 roofline 斜率，会把 launch 与填充开销误记为硬件不足，进而把扩容预算投到错误的一侧。</p>\n<p>第二个失效条件来自算子结构。公式默认 $F_{\\text{enc}}$ 与 $B_{\\text{enc}}$ 可按 dense Transformer 逐层累加，但一旦编码器引入稀疏注意力、窗口化注意力或卷积混合主干，实际 FLOPs 与访存量必须按真实算子重算：稀疏注意力降低了 $F_{\\text{enc}}$ 的二次项却可能抬高访存的不规则性，卷积混合则把一部分计算从 Tensor Core 推向 CUDA Core，$\\eta_{\\text{TFLOPS}}$ 随之塌陷。此时若仍套用 dense 计数，会系统性地低估算力项、高估带宽项，得出与实际相反的瓶颈判断——本该量化权重的一方去加 SM，本该加 SM 的一方去做 token 压缩。</p>\n<p>第三个偏差源是效率因子本身。$\\eta_{\\text{TFLOPS}}$ 与 $\\eta_{\\text{BW}}$ 取 0.4–0.8 是对实测损耗的笼统吸收，但它随 kernel 实现、精度路径与形状分布漂移：同一模型在 BF16 与 FP8 下的 Tensor Core 利用率不同，同一精度在不同序列长度下的 HBM 有效带宽也不同。把这对因子当作跨模型跨精度复用的常数，容量规划会出现系统性偏移，且偏移方向随负载形状变化，无法用单一安全系数兜住。</p>\n<table class=\"mini\"><thead><tr><th>情形</th><th>下界是否可信</th><th>系统代价表现</th></tr></thead><tbody><tr><td>大 batch、dense 主干、稳态流水</td><td>可信，用于定瓶颈侧</td><td>延迟贴近 $\\max$ 项，扩容方向明确</td></tr><tr><td>小 batch、launch 主导</td><td>不可信，实测偏高</td><td>SM 空转，功耗与延迟双损</td></tr><tr><td>稀疏/卷积混合结构</td><td>需重算 $F_{\\text{enc}}$、$B_{\\text{enc}}$</td><td>瓶颈判断可能反向</td></tr></tbody></table>\n<p>工程判断因此落在“先确认稳态、再确认算子、最后才信下界”的顺序上：只有当日均 batch 足以填满流水、编码器主干确为 dense、且效率因子由本模型本精度的实测标定过，$T_{\\min}$ 才能作为容量决策的锚点；否则它只是一个方向性不等式，用来提示该往带宽侧还是算力侧看，而不是用来承诺 SLO。</p>\n<h3 id=\"th-vit-roofline-sec-9\">九 · 两个时间项的量纲对齐与物理含义</h3>\n<p>公式里的两个分式不是随手拼出来的，它们各自对应一条独立流水的时间下界。计算项 $F_{\\text{enc}}/(\\eta_{\\text{TFLOPS}}P_{\\text{peak}})$ 的分子是单图编码的浮点运算总量，分母是“目标精度峰值算力 × 实测效率”——单位是 FLOP/s，相除得秒。访存项 $B_{\\text{enc}}/(\\eta_{\\text{BW}}\\text{BW}_{\\text{HBM}})$ 的分子是必须从 HBM 搬运的字节数，分母是“峰值带宽 × 实测效率”，单位是 B/s，相除同样得秒。两项量纲一致，才能取 max。这一步看似平凡，却是整个推导成立的前提：如果 $B_{\\text{enc}}$ 里混入了本可驻留 SMEM 或 TMEM 的数据，或者 $F_{\\text{enc}}$ 里混入了被编译器折叠掉的冗余算子，两个时间项就不再可比。</p>\n<p>$B_{\\text{enc}}$ 的构成需要拆开看：权重字节、激活字节、输入像素字节三者相加。权重在稳态批处理下每张图都要重读一遍（除非整层权重能塞进 L2/SMEM，视觉编码器的层宽通常做不到），激活随 patch 数线性增长，输入像素则随分辨率平方增长。这就是为什么分辨率一升，$B_{\\text{enc}}$ 的增长比 $F_{\\text{enc}}$ 更陡的前半段会先让带宽项占优。反过来，patch 数增长带来的注意力矩阵运算让 $F_{\\text{enc}}$ 以更高的幂次上升，越过某个分辨率后算力项反超。两条曲线的交点就是瓶颈切换点，工程上判断“该扩带宽还是扩算力”全靠它。</p>\n<div class=\"formula\">$$T_{\\min}=\\max\\!\\left(\\frac{F_{\\text{enc}}}{\\eta_{\\text{TFLOPS}}\\cdot P_{\\text{peak}}},\\ \\frac{B_{\\text{enc}}}{\\eta_{\\text{BW}}\\cdot \\text{BW}_{\\text{HBM}}}\\right)$$</div>\n<p>代价侧的具体例子：B200 的 HBM3e 峰值带宽约 8 TB/s 量级，若某层权重加激活合计需搬运 8 MB，效率取 0.6，则访存项为 $8\\times10^6/(0.6\\times8\\times10^{12})\\approx1.7\\,\\mu s$；同一层若 FP8 算力峰值按数百 TFLOPS 量级、效率 0.5 计，算力项可能只有零点几微秒。此时该层被带宽卡住，加 SM 数量毫无收益，正确动作是提高 batch 让权重读取摊薄，或做视觉 token 压缩减少激活字节。</p>\n\n<h3 id=\"th-vit-roofline-sec-10\">十 · 取 max 的推导关键步：重叠流水假设</h3>\n<p>为什么是 max 而不是 sum？推导的关键一步是把计算与访存视为两条可完全重叠的流水：在稳态下，Tensor Core 在算第 $i$ 个 tile 的同时，HBM 在为第 $i+1$ 个 tile 预取数据。若两条流水完全独立且重叠，总时间由较慢的那条决定，即 max。这一步隐含三个条件：其一，kernel 内部有足够的双缓冲/多级流水让 DMA 与 MMA 并发；其二，tile 划分使得每块数据的计算时间不短于其搬运时间，否则流水会因等待而空转；其三，没有全局同步点强制两条流水串行。Blackwell 的 tcgen05 与 TMEM 设计正是为这种重叠服务的——矩阵乘的累加器驻留 TMEM，减少寄存器与 SMEM 往返，让 MMA 流水更容易填满。</p>\n<p>若条件不满足，max 退化为 sum 的下界之上的实际延迟。最典型的是小 batch：单图编码时权重读取无法被多图摊薄，kernel launch 开销与流水填充阶段占比上升，实际延迟显著高于 $T_{\\min}$。伪代码思路可写成：对每个算子 $k$，计算 $t^{\\text{comp}}_k$ 与 $t^{\\text{mem}}_k$，若算子间无依赖则并行累加取 max，若有依赖则串行累加；整网延迟是这条依赖图上关键路径的长度，而非简单对全网 $F_{\\text{enc}}$、$B_{\\text{enc}}$ 取一次 max。工程上把整网当一个黑盒套公式，只在算子间高度同构、流水充分时成立。</p>\n<p>吞吐代价的例子：连续批处理下，若把 batch 从 1 提到 16，权重字节被摊薄 16 倍，访存项近似降到 1/16，而算力项随 batch 线性上升，瓶颈迅速翻转到算力侧。这正是容量规划里“先加 batch 再谈扩容”的依据——在带宽占优区间，扩 batch 是免费的带宽放大器；进入算力占优区间后，batch 再大也只增加排队延迟。</p>\n\n<h3 id=\"th-vit-roofline-sec-11\">十一 · 效率因子 0.4–0.8 的离散化来源</h3>\n<p>$\\eta_{\\text{TFLOPS}}$ 与 $\\eta_{\\text{BW}}$ 不是拟合出来的魔数，它们各自吸收了一串离散化与近似损失。算力侧：MMA 指令的 tile 形状与实际问题矩阵维度不整除时产生尾部浪费；FP8 的缩放因子重算与量化/反量化指令占用发射槽；注意力 softmax 等非矩阵乘算子无法跑满 Tensor Core；occupancy 不足导致 warp 调度空隙。带宽侧：HBM 的 burst 长度与实际访问粒度不匹配造成部分带宽空转；L2 命中率波动使有效带宽偏离峰值；写回与读入争抢通道。0.4–0.8 这个区间正是这些损失叠加后的实测落点，低端对应算子碎片化严重、occupancy 低的实现，高端对应 tile 对齐良好、流水饱满的实现。</p>\n<p>离散化在哪：真实硬件的时间不是连续的，MMA 以固定周期发射，DMA 以固定 burst 搬运，kernel 以 grid 为单位调度。把连续公式套到离散执行上，等价于假设“足够多的 tile 让统计平均收敛到峰值比例”。当 tile 数很少（小分辨率、小 batch），离散误差主导，效率因子失效。因此公式的适用边界必须写明：稳态、大 batch、dense 结构。跨模型跨精度复用同一个 $\\eta$ 是系统性偏差的来源——FP8 与 BF16 的 MMA 吞吐不同，量化开销占比不同，同一个 0.6 套到两种精度上必然一边高估一边低估。</p>\n<p>显存代价的例子：效率因子偏低往往意味着中间激活被反复换出到 HBM。若某视觉编码器在 BF16 下 $\\eta_{\\text{BW}}$ 只有 0.4，说明有效带宽被大量非必要搬运吃掉，此时应检查是否有算子把本可融合的读写拆成了多次独立 kernel；融合后 $\\eta_{\\text{BW}}$ 上升，$T_{\\min}$ 的访存项直接下降，且不增加任何显存占用。</p>\n\n<h3 id=\"th-vit-roofline-sec-12\">十二 · 失效条件的逐条推导</h3>\n<p>第一条失效条件：计算与访存不可完全重叠。推导中 max 的前提是两条流水独立并发，若 kernel 实现是“先全量加载再计算”的串行模式，实际时间是两项之和。这在视觉编码器的某些归一化、位置编码注入算子上常见——它们需要全局统计量，强制同步。此时公式给出的是乐观下界，实测延迟高于它，且差距随同步点数量增长。</p>\n<p>第二条：小 batch 或 launch 开销主导。设单 kernel launch 开销为 $t_l$，算子数为 $N$，则固定开销 $N\\cdot t_l$ 不随 batch 缩小而消失。当 $T_{\\min}$ 降到与 $N\\cdot t_l$ 同量级时，公式已无预测力。用小 batch 实测延迟反推 roofline 下界，会把 launch 开销误记为带宽或算力不足，扩容方向选错——这是容量规划里最隐蔽的坑。</p>\n<p>第三条：非 dense 结构。稀疏注意力把 $F_{\\text{enc}}$ 中注意力部分的 $O(n^2)$ 降为 $O(n\\cdot k)$，卷积混合结构把部分矩阵乘换成访存密集的滑窗算子，$F_{\\text{enc}}$ 与 $B_{\\text{enc}}$ 的比例彻底改变。直接套 dense 计数会低估算力项或高估带宽项，得出与实际相反的瓶颈结论。正确做法是按实际算子重算两个量：逐算子统计 FLOPs 与字节数，再按依赖图求关键路径。</p>\n<p>延迟代价的量化例子：某编码器含 40 个算子，单 launch 开销按微秒量级计，小 batch 下固定开销可达数十微秒，而 $T_{\\min}$ 可能只有几微秒——公式预测的延迟下限被固定开销淹没，此时优化方向应是算子融合减少 launch 次数，而非扩带宽或扩算力。</p>\n\n<h3 id=\"th-vit-roofline-sec-13\">十三 · 从公式到容量决策的映射</h3>\n<p>公式的工程价值不在算出某个数，而在判断哪一项占优后给出唯一正确的杠杆。带宽项占优时：增加 SM 无益，因为瓶颈不在算力；有效动作是提高 batch 摊薄权重、做视觉 token 压缩减少激活字节、或把权重精度降到 FP8/NVFP4 直接缩小 $B_{\\text{enc}}$ 的权重分量。算力项占优时：FP8 量化把 $P_{\\text{peak}}$ 抬升、Tensor Core 利用率（tile 对齐、occupancy）成为关键杠杆，此时再压 token 数收益有限，因为瓶颈在乘加次数而非搬运。</p>\n<p>判断切换点需要知道 $F_{\\text{enc}}$ 与 $B_{\\text{enc}}$ 随分辨率的增长幂次：像素字节随分辨率平方增长，patch 数随平方增长进而注意力 FLOPs 以更高幂次增长，所以低分辨率区间带宽项先占优、高分辨率区间算力项反超。容量规划时对给定分辨率算出两项比值，比值接近 1 说明处在切换点附近，此时任何单侧扩容都只能带来边际收益，应同时评估量化（压算力项）与批处理（压带宽项）的组合。</p>\n<p>带宽代价的例子：若某分辨率下带宽项是算力项的 3 倍，则把权重从 BF16 降到 FP8 可使权重字节减半，访存项随之下降，$T_{\\min}$ 直接受益；而同分辨率下若算力项占优，同样的量化动作收益来自 $P_{\\text{peak}}$ 翻倍而非字节减半，两条路径的收益机制不同，不能混为一谈。</p>\n<p>最后落在具体机制上：把公式当成一张二维相图来用——横轴分辨率、纵轴 batch，相图里画出带宽占优区与算力占优区的分界，每个服务配置落在哪个区决定了优化清单的排序。分界线本身随 $\\eta$ 漂移，所以每次换 kernel 实现或换精度，都要重测 $\\eta_{\\text{TFLOPS}}$ 与 $\\eta_{\\text{BW}}$ 再重画相图，而不是把 0.4–0.8 当常数锁死。</p>\n\n<h3 id=\"th-vit-roofline-sec-14\">十四 · 当 max 失效：重叠假设、效率因子与算子重算的边界</h3>\n<p>该式的推导支点在于把 <span class=\"sym\">F_enc</span> 与 <span class=\"sym\">B_enc</span> 两条流水当作可完全重叠的稳态过程，于是单图延迟下界取二者之 max。这一步在 Blackwell 上成立的前提是：权重与激活的搬运已被 tcgen05 的异步拷贝与 TMEM 双缓冲掩盖，Tensor Core 在数据到达前不空转。一旦流水未填满——预填阶段首个 tile 的冷启动、视觉编码器层数不足以摊薄流水填充、或图像被切成过多小 tile 导致每次 MMA 的 K 维过短——max 就退化为两项之和，实际延迟高于下界。此时用实测延迟反推 roofline 会把流水填充开销误记为带宽不足或算力不足，扩容方向随之选错。工程上判断是否落入稳态，看的是单图编码的 MMA 指令数与 launch 数之比：比值低说明开销主导，该式只能当下界参考，不能当容量承诺。</p>\n<p>效率因子 <span class=\"sym\">η_TFLOPS</span>、<span class=\"sym\">η_BW</span> 取 0.4–0.8 是吸收实测损耗的粗粒度修正，但它不是跨模型跨精度可复用的常数。BF16 下 Tensor Core 利用率受累加器压力与指令发射节奏约束，切到 FP8 后峰值算力抬升，同样的 kernel 结构往往达不到同比的 η；带宽侧则受 HBM3e 访问粒度与激活张量布局影响，patch 嵌入若按非连续 stride 写入，有效带宽会明显低于 8 TB/s 量级。把 0.4–0.8 当固定值套到新模型上，容量规划会出现系统性偏差——偏乐观则 SLO 失守，偏保守则 SM 与带宽预算被过度预留。</p>\n<div class=\"formula\">$$\\text{bottleneck}=\\begin{cases}\\text{BW-bound}, &amp; \\dfrac{B_{\\text{enc}}}{\\eta_{\\text{BW}}\\text{BW}_{\\text{HBM}}}&gt;\\dfrac{F_{\\text{enc}}}{\\eta_{\\text{TFLOPS}}P_{\\text{peak}}}\\\\[4pt] \\text{compute-bound}, &amp; \\text{otherwise}\\end{cases}$$</div>\n<p>算子重算是另一处易崩的边界。该式假定视觉编码器为 dense Transformer，<span class=\"sym\">F_enc</span> 按注意力与 MLP 的标准计数累加。若编码器采用稀疏注意力或卷积混合结构，实际 FLOPs 随稀疏度与卷积核尺寸重分布，<span class=\"sym\">B_enc</span> 也因特征图复用模式改变而不同：卷积层的权重搬运占比高、激活复用强，稀疏注意力则可能把带宽压力从权重侧推向 KV 侧。直接套用 dense 计数，常出现低估算力项、高估带宽项的结果，得出与实际相反的瓶颈结论。正确做法是按实际算子逐层重算两项，再代入 max——这一步不做，roofline 只是纸面数字。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>公式行为</th><th>系统代价</th></tr></thead><tbody><tr><td>小 batch、launch 主导</td><td>max 退化为和，下界不达</td><td>延迟被 kernel 开销吃掉，吞吐随 batch 线性爬升前几乎无收益</td></tr><tr><td>稀疏/卷积混合编码器</td><td>F、B 计数失真</td><td>瓶颈判断反转，扩容选错方向</td></tr><tr><td>η 跨精度复用</td><td>峰值算力抬升但 η 未同步</td><td>FP8 收益被高估，SM 预算与功耗规划偏差</td></tr></tbody></table>\n<p>容量决策上，该式的正确用法是方向判断而非数值承诺：带宽项占优时增加 SM 无益，应提高 batch 摊薄权重搬运或做 token 压缩；算力项占优时 FP8 量化与 Tensor Core 利用率才是杠杆。分辨率升高会把瓶颈从带宽侧推向算力侧，这一迁移点正是该式在规划中最有价值的输出——它告诉你何时该换杠杆，而不是给你一个可写进 SLO 的毫秒数。</p>\n<h3 id=\"th-vit-roofline-sec-15\">十五 · 公式成立的三条隐含前提</h3>\n<p>roofline 下界之所以能写成两项取 max 的形式，靠的是三个没有写在公式里的假设，任何一条被破坏，数值就不再是下界。第一条是<strong>稳态流水</strong>：计算项与访存项必须能在时间轴上完全重叠，即当 Tensor Core 在算第 k 层时，HBM 已经在搬第 k+1 层的权重与激活。这要求编码器被切分成足够多的 tile，且每个 tile 的算术强度足以让 DMA 与 MMA 同时忙碌。第二条是<strong>dense 算子结构</strong>：$$F_{\\text{enc}}$$ 与 $$B_{\\text{enc}}$$ 的计数方式默认视觉编码器是标准 dense Transformer——每个 token 对所有 token 做注意力、每层做满秩投影。第三条是<strong>单图独立</strong>：公式把一张图当作孤立的工作负载，不考虑多图之间共享权重带来的摊薄，也不考虑跨图 batch 对访存项的放大。</p>\n<p>这三条前提对应三种不同的工程现实。稳态流水在预填阶段大批量、长序列时近似成立；dense 结构在 ViT 类主干上成立，但在窗口注意力、卷积 stem、混合 Mamba 结构上不成立；单图独立在离线批处理中不成立，因为权重只需搬一次就能服务整个 batch。把这三条前提当成普适真理，是容量规划出现系统性偏差的根源。</p>\n\n<h3 id=\"th-vit-roofline-sec-16\">十六 · 小 batch 与 launch 开销：下界变成上界</h3>\n<p>当 batch 很小、序列很短时，kernel launch 开销与流水填充阶段会主导实际延迟，此时实测值<em>高于</em>公式给出的下界，而且高出的部分与带宽、算力都无关。设单次 kernel launch 的固定开销为 $$t_{\\text{launch}}$$，编码器被切分为 $$N_k$$ 个 kernel，则实际延迟近似为</p>\n<div class=\"formula\">$$T_{\\text{real}} \\approx T_{\\min} + N_k \\cdot t_{\\text{launch}} + t_{\\text{fill}}$$</div>\n<p>其中 $$t_{\\text{fill}}$$ 是流水从空到满的爬坡时间。对一张 224×224、patch 14 的图，token 数约 256，单图 FLOPs 与访存量都落在毫秒量级以下，而一次 launch 的开销在微秒量级——当 $$N_k$$ 达到几十上百时，launch 项可以轻易超过 roofline 项。工程上的直接后果是：用小 batch 实测延迟去反推 roofline 下界，会把 launch 与填充开销误记为\"带宽不足\"或\"算力不足\"，进而选错扩容方向。判断方法是做 batch 扫描，看延迟随 batch 的增长曲线是否在某个点之后斜率贴近 roofline 预测值；斜率明显偏平的那一段就是 launch 主导区，不能用来校准效率因子。</p>\n<p>代价层面，这一失效条件直接影响服务容量：一个按 roofline 下界估算\"单卡可支撑 QPS\"的容量模型，在小 batch 低并发场景会把容量高估数倍。正确做法是把 launch 开销作为独立项建模，或者设定一个最小 batch 门槛，低于门槛时改用固定开销模型而非 roofline 模型。</p>\n\n<h3 id=\"th-vit-roofline-sec-17\">十七 · 非 dense 结构：FLOPs 计数失效</h3>\n<p>稀疏注意力、滑动窗口注意力、卷积混合主干（如 ConvNeXt 式 stem 加 Transformer 块）都会让 $$F_{\\text{enc}}$$ 与 $$B_{\\text{enc}}$$ 的解析计数偏离实际。以窗口注意力为例，若窗口大小为 $$w$$、序列长度为 $$n$$，注意力部分的 FLOPs 从 $$O(n^2 d)$$ 降为 $$O(n w d)$$，但访存模式从规整的大块读写变成大量小粒度、跨窗口边界的 gather，$$B_{\\text{enc}}$$ 的实际值反而可能上升。此时若直接套用 dense 的 $$n^2$$ 计数，会<strong>高估</strong>算力项、<strong>低估</strong>带宽项，得出\"算力受限\"的错误结论，而真实瓶颈在带宽侧。</p>\n<p>卷积混合结构的偏差方向相反：卷积层的算术强度通常低于同等 FLOPs 的矩阵乘，权重访存占比更高，且卷积核的复用依赖 im2col 或隐式 GEMM 的实现质量。若把卷积部分按 dense 矩阵乘的 FLOPs 折算，会低估实际访存字节数。工程判断的落点是：对任何非纯 dense 主干，必须按实际算子重算两项，而不是在 dense 公式上乘一个拍脑袋的系数。可操作的做法是逐算子列出 (FLOPs, bytes) 对，累加后再代入 roofline，并对 gather/scatter 类算子单独标注其有效带宽折损。</p>\n<p>这一失效条件在容量决策中的代价是方向性错误：扩 SM 对带宽受限的窗口注意力毫无帮助，而扩带宽对算力受限的 dense 主干同样无效。选错方向的扩容投入在 NVL72 这种整机柜粒度上意味着整批 GPU 的浪费。</p>\n\n<h3 id=\"th-vit-roofline-sec-18\">十八 · 效率因子的复用边界</h3>\n<p>$$\\eta_{\\text{TFLOPS}}$$ 与 $$\\eta_{\\text{BW}}$$ 取 0.4–0.8 是一个区间，不是一个常数。把区间中值当成固定系数跨模型、跨精度复用，会引入系统性偏差。利用率差异的来源有三类：其一，精度切换——FP8 路径的 Tensor Core 利用率与 BF16 路径不同，前者对累加器布局与缩放因子的处理更敏感，实测效率通常更低；其二，kernel 实现质量——同一层在不同框架（TensorRT-LLM 的融合 kernel 与 Triton 手写 kernel）下的实际吞吐可以相差显著，效率因子吸收的正是这部分损耗；其三，形状匹配——当序列长度或 head 维度不是 Tensor Core tile 的整数倍时，尾部浪费直接压低 $$\\eta_{\\text{TFLOPS}}$$。</p>\n<p>工程上正确的用法是把效率因子当作<strong>标定参数</strong>而非物理常数：在目标模型、目标精度、目标框架上做一次实测标定，得到该配置下的 $$\\eta$$ 值，再用于同配置的容量外推。跨配置外推时必须重新标定。代价体现在容量规划的置信区间上——用错效率因子会让预测容量偏离实际，且偏差方向随配置变化而不固定，无法用统一的安全系数掩盖。</p>\n\n<h3 id=\"th-vit-roofline-sec-19\">十九 · 规模上限：什么时候 roofline 不再是主导约束</h3>\n<p>公式在规模增大时逐渐失去解释力，有三个具体的上限点。第一是<strong>显存容量上限</strong>：当分辨率升高导致激活与 KV 侧缓存膨胀，单卡 HBM 容量先于带宽成为约束，此时延迟不再由 roofline 决定，而是由是否发生换出或重算决定。第二是<strong>多卡切分上限</strong>：当单图编码被切到多张 GPU 上做张量并行，卡间通信（NVLink 5 上的 all-reduce 或 all-gather）进入关键路径，roofline 的单卡模型不再适用，通信下界成为新的约束项——这一项由并行与通信部分展开，此处只指出它取代了单卡 roofline 的地位。第三是<strong>功耗与频率上限</strong>：持续高利用率下 SM 频率会因功耗墙回落，$$P_{\\text{peak}}$$ 的标称值不再可达，效率因子随之下降，且下降幅度随散热条件变化。</p>\n<p>判断是否触及上限的操作性准则是：先算 roofline 下界，再算显存占用是否超过单卡容量的安全水位，再算切分后的通信量是否与计算量同量级。三者中任何一个越界，roofline 就从\"延迟下界\"退化为\"局部参考值\"。在 NVL72 整机柜部署中，这个判断尤其重要：机柜级带宽与算力都很充裕，真正的约束往往落在显存容量与通信拓扑上，而不是单卡 roofline。</p>\n\n<h3 id=\"th-vit-roofline-sec-20\">二十 · 失效条件的工程清单</h3>\n<p>把上述边界整理成可执行的检查项，用于在容量决策前快速判定公式是否适用：</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>失效表现</th><th>替代做法</th></tr></thead><tbody>\n<tr><td>batch 是否低于 launch 主导门槛</td><td>实测延迟远高于下界且与 batch 弱相关</td><td>改用固定开销模型，或提高最小 batch</td></tr>\n<tr><td>主干是否为纯 dense Transformer</td><td>稀疏/窗口/卷积混合导致 FLOPs 与 bytes 计数偏离</td><td>逐算子重算两项，标注 gather 折损</td></tr>\n<tr><td>效率因子是否在同配置下标定</td><td>跨精度跨框架复用导致系统性偏差</td><td>目标配置实测标定，跨配置重新标定</td></tr>\n<tr><td>显存是否接近容量水位</td><td>换出或重算使延迟脱离 roofline</td><td>先做显存可行性判断，再看 roofline</td></tr>\n<tr><td>是否已切分到多卡</td><td>通信进入关键路径</td><td>改用通信下界与计算下界取 max</td></tr>\n<tr><td>持续负载下频率是否回落</td><td>$$P_{\\text{peak}}$$ 不可达，效率因子下降</td><td>按实测持续功耗下的算力标定</td></tr>\n</tbody></table>\n<p>这张表的用法不是逐项打分，而是找到第一个越界项即停止用 roofline 做外推。对一张高分辨率图（如 1024×1024、patch 14，token 数约 5k），算力项通常已经占优，此时 FP8 量化与 Tensor Core 利用率是主要杠杆；但若该图被切到多卡，通信项会立刻取代算力项成为约束——这正是 roofline 从\"下界\"退化为\"局部参考\"的典型转折。工程判断落在：先确认约束项的身份，再决定扩容方向，而不是把公式当作无条件成立的承诺。</p>\n\n<h3 id=\"th-vit-roofline-sec-21\">二十一 · 边界在哪里：从稳态流水到失效条件</h3>\n<p>该 roofline 界的成立依赖一个强假设：计算流水与访存流水在稳态下完全重叠，即 Tensor Core 在算的同时 HBM 一直在供数，两者取 max 才有意义。真实编码器并非处处处于这个稳态。单图编码的 kernel 序列包含 patch embedding、若干 attention/MLP 块、归一化与最后的投影，块与块之间存在依赖，流水在启动与收尾阶段填不满；当 batch 很小、每张图的算子链又短时，kernel launch 与同步开销会占据可观比例，此时实测延迟高于下界，而公式并不描述这部分。工程上判断是否落入适用区间的办法是看单图有效计算量能否把 launch 开销摊薄：把 batch 增大到访存项与算力项都远大于固定开销的量级，公式才重新具备预测力。反过来，若用这样的小 batch 实测延迟去反推 roofline 下界，就会把 launch 与流水填充开销误记为带宽或算力不足，扩容方向随之选错——这是容量规划中最常见的失败模式。</p>\n<p>第二个边界是算子结构。公式默认视觉编码器是 dense Transformer，$$F_{\\text{enc}}$$ 按稠密注意力的二次项与 MLP 的线性项累加，$$B_{\\text{enc}}$$ 按权重、激活与输入像素的字节数累加。一旦模型改用稀疏注意力、窗口注意力或卷积混合结构，实际 FLOPs 与访存字节都要按真实算子重算：稀疏注意力把注意力矩阵的有效计算量压下来，卷积混合则把一部分算力从 Tensor Core 转移到其他单元，两者都会让 dense 计数失真。直接套用 dense 的 $$F_{\\text{enc}}$$ 会低估算力项或高估带宽项，得出与实际相反的瓶颈结论。此时正确做法是逐算子统计有效 MACs 与必须落 HBM 的张量字节，而不是沿用块级估算。</p>\n<div class=\"formula\">$$\\text{有效下界}=\\max\\!\\left(\\frac{F_{\\text{enc}}^{\\text{eff}}}{\\eta_{\\text{TFLOPS}}P_{\\text{peak}}},\\ \\frac{B_{\\text{enc}}^{\\text{eff}}}{\\eta_{\\text{BW}}\\text{BW}_{\\text{HBM}}}\\right)+\\ T_{\\text{launch}}$$</div>\n<p>第三个边界是效率因子的可移植性。$$\\eta_{\\text{TFLOPS}}$$ 与 $$\\eta_{\\text{BW}}$$ 取 0.4–0.8，这个区间吸收的是实测损耗，但它随 kernel 实现、精度路径与形状而变化：同一模型在 BF16 与 FP8 下的 Tensor Core 利用率不同，注意力 kernel 在长序列与短序列下的带宽效率也不同。把 0.4–0.8 当成固定常数跨模型、跨精度复用，容量规划会出现系统性偏差。规模上限同样受此约束：分辨率继续升高时，$$F_{\\text{enc}}$$ 随 patch 数增长更快，瓶颈从带宽侧滑向算力侧，此时若仍按带宽项扩容 SM 便无收益，应转向 FP8 量化、提高 Tensor Core 利用率或做 token 压缩；反之带宽项占优时，增加 SM 无益，应提高 batch 或压缩 KV 与激活。判断当前处于哪一侧，正是这个界在容量决策中的唯一用途——它是分流工具，不是延迟承诺。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>公式行为</th><th>系统代价</th></tr></thead><tbody><tr><td>dense 编码器、大 batch 稳态</td><td>取 max 可预测下界</td><td>延迟受带宽或算力单侧约束</td></tr><tr><td>小 batch、launch 主导</td><td>下界偏低，实测更高</td><td>固定开销吃掉吞吐，容量被高估</td></tr><tr><td>稀疏/卷积混合结构</td><td>dense 计数失真</td><td>瓶颈判断反向，扩容方向错</td></tr><tr><td>效率因子跨精度复用</td><td>0.4–0.8 不再成立</td><td>规划出现系统性偏差</td></tr></tbody></table>\n<h3 id=\"th-vit-roofline-sec-22\">二十二 · 从下界到容量：批大小的可行域</h3>\n<p>把单图下界 <span class=\"formula-inline\">$$T_{\\min}$$</span> 当作一个服务单元的“最小服务时间”，批大小就不是拍脑袋定的，而是被两条约束夹出来的区间。设目标吞吐为 <span class=\"formula-inline\">$$R$$</span>（图/秒），单副本并发批大小为 <span class=\"formula-inline\">$$b$$</span>，则稳态吞吐近似为 <span class=\"formula-inline\">$$R \\approx b/T_{\\text{eff}}(b)$$</span>，其中 <span class=\"formula-inline\">$$T_{\\text{eff}}(b)$$</span> 在 <span class=\"formula-inline\">$$b$$</span> 足够大时趋近 <span class=\"formula-inline\">$$T_{\\min}$$</span>，在 <span class=\"formula-inline\">$$b$$</span> 小时被 kernel launch 与流水填充主导而显著高于下界。工程上要解的是：给定 <span class=\"formula-inline\">$$R$$</span> 与 SLO 的尾延迟上限 <span class=\"formula-inline\">$$T_{\\text{SLO}}$$</span>，求满足 <span class=\"formula-inline\">$$T_{\\text{eff}}(b)\\le T_{\\text{SLO}}$$</span> 且 <span class=\"formula-inline\">$$b/T_{\\text{eff}}(b)\\ge R$$</span> 的最小 <span class=\"formula-inline\">$$b$$</span>。注意这里的方向：<b>批大小不是越大越好</b>，它受 SLO 上界封顶；而吞吐下限又要求 <span class=\"formula-inline\">$$b$$</span> 不能太小，否则下界根本没被填满。可行域是一个区间，不是单调最优。</p>\n<p>具体机制上，判断该区间是否存在，只需看瓶颈侧。若带宽项占优，<span class=\"formula-inline\">$$T_{\\min}$$</span> 与 <span class=\"formula-inline\">$$b$$</span> 近似无关（权重搬运被摊薄后激活与输入像素随 <span class=\"formula-inline\">$$b$$</span> 线性增长，但总字节/总图数趋于常数），此时扩 <span class=\"formula-inline\">$$b$$</span> 对吞吐近乎线性增益，直到算力项接手；若算力项占优，<span class=\"formula-inline\">$$T_{\\min}$$</span> 随 <span class=\"formula-inline\">$$b$$</span> 线性上升，吞吐饱和，再加 <span class=\"formula-inline\">$$b$$</span> 只增加排队延迟而不增加吞吐——这正是容量规划里“加批无效”的信号。代价面：批大小直接决定激活显存与 KV 预算的占用峰值，<span class=\"formula-inline\">$$b$$</span> 翻倍意味着编码器中间激活近似翻倍，在多模态服务里会和语言侧 KV 抢同一块 HBM。</p>\n<p>例子：某服务要求 <span class=\"formula-inline\">$$R=40$$</span> 图/秒、尾延迟 <span class=\"formula-inline\">$$T_{\\text{SLO}}=120\\,\\text{ms}$$</span>。若实测 <span class=\"formula-inline\">$$b=8$$</span> 时 <span class=\"formula-inline\">$$T_{\\text{eff}}=90\\,\\text{ms}$$</span>，吞吐 <span class=\"formula-inline\">$$8/0.09\\approx 89$$</span> 图/秒已超需求，但尾延迟余量只有 30 ms；此时应下调 <span class=\"formula-inline\">$$b$$</span> 到 4–6 换取延迟余量，而不是继续加批。这个判断完全来自下界公式的瓶颈侧识别，而非实测曲线拟合。</p>\n\n<h3 id=\"th-vit-roofline-sec-23\">二十三 · 定并行度：按瓶颈侧选切分维度</h3>\n<p>并行度决策的本质是问：这个视觉编码器的 <span class=\"formula-inline\">$$T_{\\min}$$</span> 里，哪一项在主导？若带宽项主导，增加 SM 数量对 <span class=\"formula-inline\">$$T_{\\min}$$</span> 无益——因为 <span class=\"formula-inline\">$$\\text{BW}_{\\text{HBM}}$$</span> 是整卡共享的，切分张量并行只会把同一份权重搬运复制到更多卡上，反而放大总字节。此时正确的并行维度是<b>数据并行</b>：每卡独立跑不同图像，把 <span class=\"formula-inline\">$$b$$</span> 分摊到 <span class=\"formula-inline\">$$N$$</span> 卡，单卡 <span class=\"formula-inline\">$$b/N$$</span> 仍落在带宽主导区，总吞吐线性扩展。若算力项主导，则张量并行或序列并行才有意义，因为 <span class=\"formula-inline\">$$F_{\\text{enc}}$$</span> 可被切分到多卡 Tensor Core 上，代价是引入集合通信。</p>\n<p>伪代码思路：对每个候选并行方案 <span class=\"formula-inline\">$$(N_{\\text{tp}}, N_{\\text{dp}})$$</span>，重算有效峰值 <span class=\"formula-inline\">$$P_{\\text{eff}}=N_{\\text{tp}}\\cdot\\eta_{\\text{TFLOPS}}\\cdot P_{\\text{peak}}$$</span> 与有效带宽 <span class=\"formula-inline\">$$\\text{BW}_{\\text{eff}}=\\eta_{\\text{BW}}\\cdot\\text{BW}_{\\text{HBM}}$$</span>（张量并行不增加总带宽，只增加可用 SM），再代入下界公式比较两项。若 <span class=\"formula-inline\">$$N_{\\text{tp}}$$</span> 增大后算力项仍不成为 max，说明切分是白费的。这里的通信代价必须显式计入：张量并行每层两次 all-reduce，其下界由 NVLink 5 的集合通信带宽决定（该下界本身是另一条目的主题，此处只作约束引用）。代价面：张量并行把单图延迟的通信项从零抬到可观水平，在带宽主导区是纯亏损；数据并行则把显存占用按卡数摊薄，是带宽主导区的自然选择。</p>\n<p>例子：一个高分辨率视觉编码器在单卡上带宽项为 60 ms、算力项为 35 ms，瓶颈在带宽。此时把 <span class=\"formula-inline\">$$N_{\\text{tp}}$$</span> 从 1 加到 4，算力项降到约 9 ms，但带宽项仍是 60 ms，<span class=\"formula-inline\">$$T_{\\min}$$</span> 纹丝不动，还额外付出 all-reduce 延迟。正确做法是 <span class=\"formula-inline\">$$N_{\\text{dp}}=4$$</span>，四卡各跑独立图像，总吞吐约四倍，单图延迟不变。反之，若某低分辨率配置算力项 50 ms、带宽项 20 ms，则张量并行 2 路可把算力项压到 25 ms，<span class=\"formula-inline\">$$T_{\\min}$$</span> 从 50 ms 降到 25 ms，此时切分才划算。</p>\n\n<h3 id=\"th-vit-roofline-sec-24\">二十四 · 定 KV 预算：编码器延迟与解码显存的时间-空间换算</h3>\n<p>多模态服务里，视觉编码器的输出 token 会进入语言侧 KV cache。容量决策要回答的是：给定 HBM 总预算，多少留给视觉编码器激活、多少留给 KV？下界公式给出的不是显存数字，而是<b>时间换空间的汇率</b>：若编码器带宽项主导，说明瓶颈在搬运而非计算，那么压缩视觉 token 数（减少进入 KV 的 token）能同时降低编码字节与 KV 占用，是双赢杠杆；若算力项主导，压缩 token 数主要省 KV 显存，对编码延迟的改善有限，因为 <span class=\"formula-inline\">$$F_{\\text{enc}}$$</span> 的下降未必线性。</p>\n<p>定量上，设每图产生 <span class=\"formula-inline\">$$n_v$$</span> 个视觉 token，每 token 每层 KV 占 <span class=\"formula-inline\">$$2\\cdot d\\cdot s$$</span> 字节（<span class=\"formula-inline\">$$d$$</span> 为头维乘层数，<span class=\"formula-inline\">$$s$$</span> 为每元素字节），则批 <span class=\"formula-inline\">$$b$$</span> 的 KV 预算为 <span class=\"formula-inline\">$$M_{\\text{KV}}=b\\cdot n_v\\cdot 2ds$$</span>。把它与编码器激活 <span class=\"formula-inline\">$$M_{\\text{act}}(b)$$</span> 相加不得超过可用 HBM。于是批大小被显存二次约束：<span class=\"formula-inline\">$$b\\le (M_{\\text{HBM}}-M_{\\text{weight}})/(M_{\\text{act,unit}}+n_v\\cdot 2ds)$$</span>。这个上界与第一节的 SLO 上界取小，才是真正可用的 <span class=\"formula-inline\">$$b$$</span>。代价面：KV 预算挤压批大小，批大小又决定编码器能否填满流水；三者是一个耦合环，不能单独调一个。</p>\n<p>例子：某配置下单图视觉 token <span class=\"formula-inline\">$$n_v=1024$$</span>，KV 每 token 每图占用量化后为固定值，若把 <span class=\"formula-inline\">$$n_v$$</span> 压到 256，KV 占用降为四分之一，批大小上限随之抬高，编码器更容易进入带宽主导的稳态区——但前提是压缩不改变 <span class=\"formula-inline\">$$F_{\\text{enc}}$$</span> 的算子结构（稀疏注意力会破坏 dense 假设，需按第二节重算）。若压缩后编码器反而滑向算力主导（因为注意力算子变稀疏、Tensor Core 利用率下降），则延迟可能不降反升，这就是把压缩当免费午餐的典型误判。</p>\n\n<h3 id=\"th-vit-roofline-sec-25\">二十五 · 定 SLO：下界是尾延迟的地板，不是均值</h3>\n<p>SLO 通常约束尾延迟（如 P99），而下界公式给的是稳态均值地板。二者之间隔着排队、批内最慢样本、流水未填满三段。容量规划要把下界当作<b>不可逾越的地板</b>去反推可承诺的 SLO：若 <span class=\"formula-inline\">$$T_{\\min}$$</span> 已接近 <span class=\"formula-inline\">$$T_{\\text{SLO}}$$</span>，则任何排队都会击穿 SLO，此时只能降批或加副本；若 <span class=\"formula-inline\">$$T_{\\min}$$</span> 远低于 <span class=\"formula-inline\">$$T_{\\text{SLO}}$$</span>，余量可用来吸收批内抖动与突发流量。公式化地，可承诺的尾延迟近似为 <span class=\"formula-inline\">$$T_{P99}\\approx T_{\\min}+W_q+J_b$$</span>，其中 <span class=\"formula-inline\">$$W_q$$</span> 为排队等待、<span class=\"formula-inline\">$$J_b$$</span> 为批内最慢样本相对均值的偏差。容量决策就是确保 <span class=\"formula-inline\">$$T_{\\min}+W_q+J_b\\le T_{\\text{SLO}}$$</span> 在目标负载下成立。</p>\n<p>关键机制：<span class=\"formula-inline\">$$J_b$$</span> 随批大小增长，因为批内样本分辨率不一、token 数不一，最慢样本拖尾。带宽主导时 <span class=\"formula-inline\">$$J_b$$</span> 较小（搬运时间对样本差异不敏感），算力主导时 <span class=\"formula-inline\">$$J_b$$</span> 较大（FLOPs 随分辨率平方级增长）。所以 SLO 收紧时，优先在算力主导区降批，在带宽主导区可维持较大批而靠副本数吸收排队。代价面：为守住尾延迟而降批，直接损失吞吐，需要更多副本补偿，功耗与卡数上升——这是 SLO 与成本的直接兑换。</p>\n<p>例子：<span class=\"formula-inline\">$$T_{\\min}=40\\,\\text{ms}$$</span>、<span class=\"formula-inline\">$$T_{\\text{SLO}}=100\\,\\text{ms}$$</span>，余量 60 ms 足以覆盖排队与批内抖动，可维持中等批；若某配置 <span class=\"formula-inline\">$$T_{\\min}=85\\,\\text{ms}$$</span>，余量仅 15 ms，任何突发都会击穿 P99，此时应判定该分辨率+批组合不可承诺此 SLO，需降分辨率、降批或换并行方案。这个判断不需要实测尾延迟，只需下界与 SLO 的差值。</p>\n\n<h3 id=\"th-vit-roofline-sec-26\">二十六 · 算例：一个分辨率-批-并行的联合决策</h3>\n<p>设某视觉编码器 dense Transformer，单图 <span class=\"formula-inline\">$$F_{\\text{enc}}$$</span> 与 <span class=\"formula-inline\">$$B_{\\text{enc}}$$</span> 给定，B200 上 <span class=\"formula-inline\">$$\\text{BW}_{\\text{HBM}}\\approx 8\\,\\text{TB/s}$$</span> 量级，取 <span class=\"formula-inline\">$$\\eta_{\\text{BW}}=0.6$$</span>、<span class=\"formula-inline\">$$\\eta_{\\text{TFLOPS}}=0.5$$</span>。先算两项：带宽时间 <span class=\"formula-inline\">$$B_{\\text{enc}}/(0.6\\times 8\\,\\text{TB/s})$$</span>，算力时间 <span class=\"formula-inline\">$$F_{\\text{enc}}/(0.5\\times P_{\\text{peak}})$$</span>。假设低分辨率配置得带宽项 25 ms、算力项 12 ms，<span class=\"formula-inline\">$$T_{\\min}=25\\,\\text{ms}$$</span>，带宽主导；高分辨率配置得带宽项 70 ms、算力项 90 ms，<span class=\"formula-inline\">$$T_{\\min}=90\\,\\text{ms}$$</span>，算力主导。注意分辨率升高把瓶颈从带宽推向算力，这正是公式的核心行为。</p>\n<p>决策链：低分辨率配置带宽主导 → 并行选数据并行、批尽量大以摊薄权重搬运、token 压缩是双赢杠杆、SLO 余量大；高分辨率配置算力主导 → 并行选张量并行、FP8 量化与 Tensor Core 利用率是关键杠杆、批受 SLO 与 KV 双重封顶、token 压缩主要省显存而非省延迟。若高分辨率配置要求 <span class=\"formula-inline\">$$T_{\\text{SLO}}=120\\,\\text{ms}$$</span>，<span class=\"formula-inline\">$$T_{\\min}=90\\,\\text{ms}$$</span> 余量 30 ms，批内抖动与排队必须压在此内，否则不可承诺；若要求 <span class=\"formula-inline\">$$T_{\\text{SLO}}=100\\,\\text{ms}$$</span>，余量仅 10 ms，应直接判定该分辨率不可行，需降分辨率或上更强并行。</p>\n<p>失效校验必须做：小 batch 实测若远高于 <span class=\"formula-inline\">$$T_{\\min}$$</span>，不要反推为带宽或算力不足，那多半是 launch 开销与流水未填满；稀疏注意力或卷积混合结构不能套 dense 的 <span class=\"formula-inline\">$$F_{\\text{enc}}$$</span>，否则瓶颈判断可能反转；<span class=\"formula-inline\">$$\\eta$$</span> 的 0.4–0.8 不能跨模型跨精度当常数复用，不同 kernel 实现的利用率差异会让容量规划出现系统性偏差。工程判断落在这一句：<b>先把瓶颈侧定死，再谈批、并行、KV 与 SLO，四者中任何一个脱离瓶颈侧单独调，都会把容量决策带偏。</b></p>\n\n<h3 id=\"th-vit-roofline-sec-27\">二十七 · 把下界换算成容量决策：何时该扩带宽、何时该扩算力</h3>\n<p>把 $$T_{\\min}$$ 直接当作容量规划的输入，第一步不是代入数字，而是判断两项中哪一项占优——这决定了扩容杠杆的方向。设带宽项与算力项之比为 $$\\rho=\\dfrac{B_{\\text{enc}}/(\\eta_{\\text{BW}}\\text{BW}_{\\text{HBM}})}{F_{\\text{enc}}/(\\eta_{\\text{TFLOPS}}P_{\\text{peak}})}$$，当 $$\\rho&gt;1$$ 时单图延迟被 HBM 搬运卡住，此时增加 SM 数量、提高 Tensor Core 占用率对降低单图延迟没有收益，正确的动作是提高并发 batch 让权重读取被多图摊薄、做 token 压缩（更大 patch、通道剪枝）或把编码器权重常驻并复用；当 $$\\rho&lt;1$$ 时算力项占优，FP8 量化、提高 MMA 利用率、减少 padding 与无效 token 才是有效杠杆。分辨率升高会把 $$\\rho$$ 推向小于 1，因为 $$F_{\\text{enc}}$$ 随 patch 数近似平方增长而 $$B_{\\text{enc}}$$ 中的激活项增长更快但权重项被摊薄，这正是“从带宽受限滑向算力受限”的定量表达。工程上应先在目标分辨率上算出 $$\\rho$$ 的量级，再决定是买带宽还是买算力，而不是笼统地“加卡”。</p>\n<p>批大小的定法要区分两个目标。若目标是吞吐，单图延迟下界并不随 batch 线性恶化：带宽项中的权重字节被 batch 摊薄，故大 batch 下有效每图带宽成本下降，吞吐上限近似由 $$\\eta_{\\text{TFLOPS}}P_{\\text{peak}}/F_{\\text{enc}}$$ 与 $$\\eta_{\\text{BW}}\\text{BW}_{\\text{HBM}}/B_{\\text{enc}}^{\\text{act}}$$ 取小给出（$$B_{\\text{enc}}^{\\text{act}}$$ 为摊薄后的每图激活与像素字节）。若目标是 SLO 下的尾延迟，则必须承认下界不是承诺：小 batch 时 kernel launch 与流水填充主导，实测延迟显著高于 $$T_{\\min}$$，此时用 $$T_{\\min}$$ 反推可支撑的并发数会系统性高估容量。可操作的判据是设一个“填充阈值” batch——低于它时按实测延迟而非下界做容量规划，高于它时才允许用下界乘以安全系数。安全系数不应固定，而应按 kernel 实现分别标定，因为 $$\\eta_{\\text{TFLOPS}}$$ 与 $$\\eta_{\\text{BW}}$$ 在不同精度、不同 tile 配置下差异明显，把 0.4–0.8 当常数跨模型复用会造成系统性偏差。</p>\n<p>KV 预算与并行度的决策则要把视觉编码器与语言侧分开算。视觉编码器通常是一次性前向、无自回归 KV，其显存占用是权重加峰值激活，峰值激活由最大 batch 与最大分辨率共同决定，因此“定 KV 预算”在视觉侧实际是定激活预算：先由 $$T_{\\min}$$ 反推出满足 SLO 的最大 batch，再乘以单图激活字节得到激活上限，剩余显存才留给语言侧 KV。并行度方面，若 $$\\rho&gt;1$$（带宽受限），张量并行收益有限而数据并行更划算，因为每卡都要重复读取权重、TP 只会增加通信；若 $$\\rho&lt;1$$（算力受限），TP 能分摊 $$F_{\\text{enc}}$$ 并提高单卡 MMA 占用率，但需把 NVLink 5 上的 all-reduce 时间计入 SLO。分离式预填/解码架构中，视觉编码器落在预填侧，其 $$T_{\\min}$$ 决定预填池的实例数与排队上界，误用下界会把预填池配小、把尾延迟风险留给解码侧。</p>\n<p>算例（定性量级，不引用实测）：取 B200 级 $$\\text{BW}_{\\text{HBM}}\\approx 8$$ TB/s、$$\\eta_{\\text{BW}}=0.6$$，则带宽侧有效约 4.8 TB/s；取 $$\\eta_{\\text{TFLOPS}}=0.5$$。对同一编码器分别估算低分辨率与高分辨率两档：低分辨率档 $$B_{\\text{enc}}$$ 以权重为主、$$F_{\\text{enc}}$$ 较小，带宽项明显大于算力项，$$\\rho&gt;1$$，此时把 batch 从 1 提到 8 可使每图权重摊销降至约八分之一，吞吐近似线性上升而单图延迟基本不变——这是带宽受限下唯一正确的扩容方向；高分辨率档 patch 数上升使 $$F_{\\text{enc}}$$ 增长快于 $$B_{\\text{enc}}$$，$$\\rho$$ 翻转至小于 1，继续加 batch 只会拉长单图延迟而不提升吞吐上限，应转向 FP8 与提高 MMA 占用率。两档的边界点就是容量规划中“该扩带宽还是扩算力”的切换分辨率，应作为部署档位的分界写入容量表，而不是靠实测试错。若编码器为稀疏注意力或卷积混合结构，必须按实际算子重算 $$F_{\\text{enc}}$$ 与 $$B_{\\text{enc}}$$，直接套 dense 计数会得出与实际相反的瓶颈结论。</p>\n<h3 id=\"th-vit-roofline-sec-28\">二十八 · 误用一：把下界当承诺，小 batch 反推容量</h3>\n<p>Roofline 界给出的 $$T_{\\min}$$ 是稳态流水下的极限，不是服务等级承诺。工程上最常见的误用，是拿一条小 batch 实测延迟曲线去“校准”这个界：测出单图延迟明显高于公式值，于是断定带宽或算力不足，进而扩容。这个推断在因果上是反的。小 batch 时单图编码的 kernel 数量不变，但每个 kernel 的并行度极低，launch 开销、流水填充与尾部排空占主导，公式里那两条可完全重叠的流水根本没有建立起来。此时实测延迟高于下界是必然的，它反映的是调度开销而非硬件资源不足。</p>\n<p>识别方法很直接：把 batch 从 1 逐步拉到使编码器 SM 占用接近饱和，观察单图摊销延迟是否单调下降并趋于平台。若曲线在平台前陡降，说明此前测的是开销主导区，不能用它反推 roofline 瓶颈。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{若 } \\frac{T_{\\text{meas}}(b=1)}{T_{\\min}} &gt; \\frac{1}{\\eta_{\\text{pipe}}}\\ \\text{且 } T_{\\text{meas}}(b)\\ \\text{随 } b\\ \\text{显著下降，则判为开销主导，禁用反推}$$</div>\n<p>代价层面：这个误用直接导致容量规划系统性高估所需 SM 数。假设按小 batch 实测延迟做容量规划，会把本可由连续批处理吸收的并发量误判为需要更多副本，显存与功耗预算被无谓放大；反过来，若把下界当承诺写进 SLO，小 batch 请求的实际 P99 会稳定击穿该值，因为 launch 开销不随 batch 增大而消失，只是被摊销。具体例子：一个高分辨率视觉编码器在 batch=1 时单图延迟远高于公式下界，运维据此判定“带宽不够”并加卡，但把同一模型放进连续批处理、batch 拉到数十之后，单图摊销延迟落到接近下界，加卡完全没有必要——真正的杠杆是批调度而非硬件。</p>\n\n<h3 id=\"th-vit-roofline-sec-29\">二十九 · 误用二：对稀疏/混合结构套 dense FLOPs</h3>\n<p>公式的适用边界写明是 dense Transformer 视觉编码器。现实中不少视觉编码器采用稀疏注意力、窗口注意力或卷积混合结构，其 $$F_{\\text{enc}}$$ 与 $$B_{\\text{enc}}$$ 的构成与 dense 计数完全不同。误用者往往直接沿用 dense 的 FLOPs 估算——按 patch 数乘注意力与 MLP 的稠密矩阵规模累加——得出一个偏大的算力项，同时按稠密权重与全量激活估算访存项，得出一个与实际访存模式不符的带宽项。后果是瓶颈判断可能整体反转：稀疏注意力把算力项压低，却可能因索引、gather 与不规则访存把有效带宽项抬高，真实瓶颈落在带宽侧，而 dense 计数会告诉你算力侧占优。</p>\n<p>识别方法是按实际算子重算两项，而不是套模板。对稀疏注意力，算力项应按实际参与的 QK 对数量计，访存项要把索引结构与 gather 带来的额外字节计入；对卷积混合结构，卷积的算力与访存比与矩阵乘差异显著，需单独统计。判据可写成：</p>\n<div class=\"formula\">$$\\text{若 } \\frac{F_{\\text{enc}}^{\\text{dense}}}{F_{\\text{enc}}^{\\text{actual}}} \\gg 1\\ \\text{而 } B_{\\text{enc}}^{\\text{actual}} &gt; B_{\\text{enc}}^{\\text{dense}},\\ \\text{则 dense 计数会误判为算力受限}$$</div>\n<p>系统代价：按错误瓶颈方向扩容是纯浪费。若真实瓶颈在带宽侧而误判为算力侧，团队会去堆 SM、上更高精度 Tensor Core 路径，但增加 SM 对带宽受限的编码阶段毫无帮助，吞吐不涨、功耗照涨；反之若真实瓶颈在算力侧却被误判为带宽侧，团队会去做 token 压缩与提高 batch，压缩带来的访存节省无法转化为延迟下降，因为算力项才是约束。具体例子：一个采用窗口注意力的高分辨率编码器，dense 计数显示算力项远超带宽项，工程按算力受限去优化 FP8 路径，实测却发现提高 batch 与 token 压缩带来的收益远大于精度路径调整——真实约束是窗口边界处的重复访存与激活搬运，属于带宽侧。</p>\n\n<h3 id=\"th-vit-roofline-sec-30\">三十 · 误用三：效率因子当常数跨模型跨精度复用</h3>\n<p>$$\\eta_{\\text{TFLOPS}}$$ 与 $$\\eta_{\\text{BW}}$$ 取 0.4–0.8 是实测损耗的吸收项，不是物理常数。把它们当成固定值跨模型、跨精度、跨 kernel 实现复用，是容量规划出现系统性偏差的根源。不同视觉编码器的算子组合不同：注意力主导的模型与卷积混合模型的 Tensor Core 利用率差异很大；FP8 与 BF16 路径的峰值算力不同，实际可达利用率也不同，因为低精度路径对累加、缩放与数据布局的要求更苛刻，kernel 实现质量直接决定效率落点。带宽侧同理，连续大块搬运与不规则 gather 的实测带宽利用率不在同一档。</p>\n<p>正确做法是把效率因子当作需要标定的量：在目标模型、目标精度、目标 batch 区间上实测一次稳态吞吐，反解出该场景下的 $$\\eta$$，再用于同场景的容量外推。跨场景外推时必须重新标定，不能搬运。判据：</p>\n<div class=\"formula\">$$\\eta_{\\text{TFLOPS}}^{\\text{calib}} = \\frac{F_{\\text{enc}}}{T_{\\text{steady}} \\cdot P_{\\text{peak}}},\\quad \\text{仅在该模型/精度/batch 区间内有效}$$</div>\n<p>系统代价：效率因子取错档位会让容量规划整体偏移一个可观的倍数。取 0.8 去规划一个实际只能跑到 0.4 的 kernel，算出的所需副本数只有真实需求的一半，上线后 SLO 击穿；取 0.4 去规划一个实际能到 0.7 的场景，则过度采购，显存与功耗预算被锁死在低利用率配置上。具体例子：同一视觉编码器在 BF16 与 FP8 两条路径上，峰值算力不同，实测可达利用率也不同；若把 BF16 下标定的效率因子直接搬到 FP8 容量模型，算力项会被系统性低估或高估，扩容方向随之选错——这正是把 0.4–0.8 当常数的最典型后果。</p>\n\n<h3 id=\"th-vit-roofline-sec-31\">三十一 · 反例：一次被误用的容量决策复盘</h3>\n<p>构造一个反例把三类误用叠在一起。场景：一个高分辨率视觉编码器，采用窗口注意力加卷积混合结构，部署在 B200 上，团队要决定扩带宽还是扩算力。第一步，团队在 batch=1 下实测单图延迟，发现远高于按 dense 计数算出的下界，判定“硬件没跑满”，于是按小 batch 实测延迟反推所需算力，得出算力严重不足的结论。第二步，他们用 dense FLOPs 模板估算 $$F_{\\text{enc}}$$，窗口注意力被当作全注意力计数，算力项被显著高估；同时按稠密激活估算 $$B_{\\text{enc}}$$，忽略了窗口边界重复访存与卷积混合带来的额外搬运，带宽项被低估。第三步，效率因子直接取 0.8 这一档，未在目标精度与 batch 区间标定。三步叠加，结论是“算力受限，应扩 SM 并走低精度 Tensor Core 路径”。</p>\n<p>实际执行后吞吐几乎不涨，功耗上升。复盘时按正确方法重算：把 batch 拉到编码器 SM 占用接近饱和，单图摊销延迟落到平台，说明 batch=1 的实测属于开销主导区，不能反推；按窗口注意力实际参与的 QK 对数量重算算力项，dense 计数高估了算力；把窗口边界重复访存与卷积混合的额外字节计入访存项，带宽项被显著抬高，瓶颈实际落在带宽侧。效率因子在目标精度与 batch 区间重新标定后，带宽项占优的结论稳定成立。正确的杠杆应是提高 batch 与做 token 压缩，而不是扩 SM 或调精度路径。</p>\n<p>这个反例的可迁移教训是：三类误用不是独立的小偏差，而是会相互放大的组合错误——小 batch 反推把开销误记为资源不足，dense 计数把瓶颈方向拧反，常数效率因子把容量倍数算错，三者叠加足以让扩容决策完全背离真实约束。识别这类错误的工程判据是三条同时检查：实测延迟是否取自饱和 batch 区间；$$F_{\\text{enc}}$$ 与 $$B_{\\text{enc}}$$ 是否按实际算子重算；$$\\eta$$ 是否在同模型同精度同 batch 区间标定。三条中任一不满足，roofline 界给出的瓶颈判断就不可用于容量决策。落到具体机制上：视觉编码器的 roofline 界只在“稳态流水 + 实际算子计数 + 场景内标定效率”三者同时成立时才具备决策效力，缺一项就退化为一个好看的公式，而不是可执行的扩容依据。</p>\n\n<h3 id=\"th-vit-roofline-sec-32\">三十二 · 误用与反例：把下界当承诺、把 dense 计数当普适尺</h3>\n<p>最常见的误用是把 <span class=\"sym\">T<sub>min</sub></span> 当作实测延迟的承诺值。该式的前提是计算流水与访存流水完全重叠且已进入稳态，而服务侧真正跑的多是小 batch 或单图请求：此时 kernel launch 开销、流水填充与尾部排空主导时间轴，实测延迟系统性高于下界。用这种实测值去反推 roofline，会把 launch 与填充开销误记成“带宽不足”或“算力不足”，于是扩容方向选错——本该提高 batch 或做 token 压缩，却去加 SM；本该上 FP8 与提升 Tensor Core 利用率，却去堆 HBM 通道。识别方法很直接：固定模型与分辨率，把 batch 从 1 扫到能填满流水，若延迟随 batch 增大而显著下降（单图摊薄时间变小），说明此前测的是开销而非 roofline；只有当延迟曲线走平，测得的斜率才具备与下界比较的资格。</p>\n<p>第二个误用是对稀疏注意力或卷积混合结构的视觉编码器直接套用 dense Transformer 的 FLOPs 计数。这类结构的 <span class=\"sym\">F<sub>enc</sub></span> 与 <span class=\"sym\">B<sub>enc</sub></span> 必须按实际算子重算：稀疏注意力削减的是注意力矩阵乘的算力项，却可能因索引、掩码与 gather 引入额外访存；卷积混合把部分 GEMM 换成卷积，算力密度与数据复用模式都变了。直接沿用 dense 计数，通常低估算力项、高估带宽项，从而得出与实际相反的瓶颈结论——把算力受限误判为带宽受限，进而放弃 FP8 量化这条真正有效的杠杆。识别信号是：按 dense 公式算出的带宽项占优，但实测对 SM 数量或 Tensor Core 占用率敏感、对 HBM 带宽压测不敏感，说明计数模型已经失真。</p>\n<p>第三个误用是把效率因子 <span class=\"sym\">η<sub>TFLOPS</sub></span>、<span class=\"sym\">η<sub>BW</sub></span> 的 0.4–0.8 当成跨模型、跨精度复用的固定常数。不同 kernel 实现下实际利用率差异很大：同一编码器在 BF16 与 FP8 下的算力效率不同，融合程度不同的访存效率也不同。把它钉死成单一数值，容量规划会出现系统性偏差——按偏高的效率估容量会低估所需实例数，按偏低的效率估则过度采购。工程上应把效率因子当作需要实测标定的区间，而非公式里的常数。</p>\n<p>一个具体反例：某服务用 batch=1 的实测单图延迟去反推 roofline，发现延迟远高于按 8 TB/s 量级带宽与目标精度峰值算力估出的下界，于是判定“带宽被打满”，采购更高带宽的机型。实际上该 batch 下 kernel launch 与流水填充占了主要时间，把 batch 提到能填满流水后，单图摊薄延迟明显下降，且此时瓶颈落在算力项——正确动作是启用 FP8 并提升 Tensor Core 利用率，而非扩带宽。这个反例的教训是：roofline 界只回答“稳态下界在哪”，不回答“当前实测为何慢”；把两者混为一谈，扩容方向必然选错。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>F_{\\text{enc}}</td><td>单张图像编码所需浮点运算量（FLOPs），随分辨率与 patch 数增长</td></tr><tr><td>B_{\\text{enc}}</td><td>编码阶段必须从 HBM 搬运的字节数（权重+激活+输入像素）</td></tr><tr><td>P_{\\text{peak}}</td><td>Blackwell SM 在目标精度下的峰值算力（如 FP8/BF16 TFLOPS）</td></tr><tr><td>\\text{BW}_{\\text{HBM}}</td><td>HBM3e 峰值带宽（B200 约 8 TB/s 量级）</td></tr><tr><td>\\eta_{\\text{TFLOPS}},\\ \\eta_{\\text{BW}}</td><td>实测算力/带宽利用效率，通常 0.4–0.8</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-vit-roofline · 共 5 个片段</p>\n"},{"id":"th-vit-kv-cache","title":"多模态 KV cache 显存式","direction":"dir-vision-encoder-latency","prereq":[],"plain":"视觉 token 一旦进入 LLM 解码器就与文本 token 一样占据 KV cache，显存占用正比于视觉 token 数乘以层数乘以 KV 头维度；压缩视觉 token 直接线性削减 decode 阶段显存与带宽压力。","definition":"视觉 token 一旦进入 LLM 解码器就与文本 token 一样占据 KV cache，显存占用正比于视觉 token 数乘以层数乘以 KV 头维度；压缩视觉 token 直接线性削减 decode 阶段显存与带宽压力。","formula":"$$M_{\\text{KV}}=2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot (N_{\\text{vis}}+N_{\\text{txt}})\\cdot b_{\\text{kv}}\\cdot B_{\\text{batch}}$$","variables":[{"sym":"L","meaning":"LLM 解码器层数"},{"sym":"H_{\\text{kv}}","meaning":"KV 头数（GQA 下远小于 Q 头数）"},{"sym":"d_{\\text{head}}","meaning":"单头维度"},{"sym":"N_{\\text{vis}},\\ N_{\\text{txt}}","meaning":"视觉 token 数与文本 token 数"},{"sym":"b_{\\text{kv}}","meaning":"KV 每元素字节数（FP16=2，FP8=1）"},{"sym":"B_{\\text{batch}}","meaning":"并发序列数"}],"derivation":"推导关键一步是把每层每 token 的 KV 存储量写成 $$2\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot b_{\\text{kv}}$$，再乘层数、总 token 数与并发批大小，得到线性于视觉 token 数的显存式，从而把 token 压缩的收益直接换算为显存节省。","example":"在容量决策中，该式用于反推单卡可容纳的并发序列数：给定显存预算与文本长度，视觉 token 数直接决定 batch 上限，因此视觉 token 压缩比是提高并发密度的最直接杠杆。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["假设 MHA/GQA 的 KV 头数与层数固定；若采用 MLA 或跨层共享 KV，等效项需替换为压缩后的潜向量维度","未计入 PagedAttention 的块内碎片与页表开销，实际占用通常高出 5%–15%"],"system_note":"常见误用是只按公式算理论显存而不留 PagedAttention 碎片与页表余量，导致上线后 OOM；另一误用是在 MLA 结构上仍用 GQA 的 $$H_{\\text{kv}}\\cdot d_{\\text{head}}$$ 估算，严重高估显存占用。","papers":["paper-an-image-is-worth-16x16-words-transf-2020"],"facts":["直觉上，视觉 token 进入 LLM 解码器后与文本 token 同等占据 KV cache，显存正比于视觉 token 数乘层数乘 KV 头维度，压缩视觉 token 即线性削减 decode 显存与带宽。","公式中 $$L$$ 为解码器层数，$$H_{\\text{kv}}$$ 为 KV 头数（GQA 下远小于 Q 头数），$$d_{\\text{head}}$$ 为单头维度，$$N_{\\text{vis}}$$ 与 $$N_{\\text{txt}}$$ 为视觉与文本 token 数，$$b_{\\text{kv}}$$ 为每元素字节数（FP16=2、FP8=1），$$B_{\\text{batch}}$$ 为并发序列数，系数 2 对应 K 与 V 两份。","推导关键一步是把每层每 token 的 KV 存储量写成 $$2\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot b_{\\text{kv}}$$，再乘层数、总 token 数与并发批大小，得到线性于视觉 token 数的显存式，从而把 token 压缩的收益直接换算为显存节省。","适用边界是 MHA/GQA 且 KV 头数与层数固定；若采用 MLA 或跨层共享 KV，等效项需替换为压缩后的潜向量维度；公式未计入 PagedAttention 的块内碎片与页表开销，实际占用通常高出 5%–15%。","在容量决策中，该式用于反推单卡可容纳的并发序列数：给定显存预算与文本长度，视觉 token 数直接决定 batch 上限，因此视觉 token 压缩比是提高并发密度的最直接杠杆。","常见误用是只按公式算理论显存而不留 PagedAttention 碎片与页表余量，导致上线后 OOM；另一误用是在 MLA 结构上仍用 GQA 的 $$H_{\\text{kv}}\\cdot d_{\\text{head}}$$ 估算，严重高估显存占用。"],"anchors":["FP16=2","FP8=1","实际占用通常高出 5%–15%"],"pitfalls":["按公式精确分配显存而不预留 PagedAttention 块内碎片与页表开销，实际占用高出 5%–15%，高并发下直接触发 OOM。","在 MLA 或跨层共享 KV 的模型上沿用 GQA 的 KV 头维度估算，把压缩潜向量当成完整 KV，显存需求被高估数倍，浪费容量。","只压缩视觉 token 数却不检查压缩后 token 的语义保真度，decode 显存下降但重编码或重试请求增加，端到端容量反而变差。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-1\">一 · 一句话直觉与它的物理含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-2\">二 · 严格定义：从每 token 每层的字节数推起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-3\">三 · 为什么需要这个式子：容量反推与杠杆定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-4\">四 · 常见误解之一：把理论占用当预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-5\">五 · 常见误解之二：在 MLA 上沿用 GQA 的头维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-6\">六 · 工程判断：把式子当预算骨架而非答案</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-7\">七 · 多模态 KV cache 显存式的适用边界与代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-8\">八 · 显存式的适用边界与两类误算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-9\">九 · 逐项拆解：为什么系数 2 与 $H_{\\text{kv}}$ 是主杠杆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-10\">十 · 推导关键步：从“每层每 token”到“线性于视觉 token”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-11\">十一 · 失效条件的数学形态：MLA 与跨层共享如何改写等效项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-12\">十二 · 碎片与页表：5%–15% 的余量从哪来、怎么留</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-13\">十三 · 用式子做工程判断：三个可操作的换算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-14\">十四 · 容量反推与失效边界：这条显存式什么时候不能直接用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-15\">十五 · 线性假设的三条硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-16\">十六 · PagedAttention 开销：公式之外的那 5%–15%</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-17\">十七 · 压缩视觉 token 的语义保真度边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-18\">十八 · 批大小与显存预算的反推边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-19\">十九 · 何时该弃用公式改用实测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-20\">二十 · 公式成立的前提，以及它在哪里开始说谎</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-21\">二十一 · 从显存式反解批大小：把视觉 token 当作可调的自变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-22\">二十二 · 定并行度：TP 与 PP 的分界由 KV 项而非权重项决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-23\">二十三 · 定 KV 预算：把预算拆成 token 配额而非字节配额</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-24\">二十四 · 定 SLO：把首 token 与每 token 延迟拆到 KV 带宽上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-25\">二十五 · 算例：一次完整的容量反推</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-26\">二十六 · 容量反推的三个杠杆与两个陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-27\">二十七 · 容量反推的边界：什么时候这条式子会骗你</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-28\">二十八 · 误用一：把理论式当分配式，不留碎片余量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-29\">二十九 · 误用二：在 MLA 结构上沿用 GQA 的头维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-30\">三十 · 误用三：只压 token 数，不验语义保真</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-31\">三十一 · 反例：一次“精确分配”的上线事故</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-32\">三十二 · 误用与反例：从“算得准”到“跑得稳”之间的三处断点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vit-kv-cache-sec-33\">三十三 · 误用与反例：把线性式当精确预算的三个坑</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:492px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 491.9 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"409.9\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"409.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：视觉 token 一旦进入 LLM 解码器就与文本 token 一…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"409.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$M_{\\text{KV}}=2\\cdot L\\cdot H_{…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"409.9\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：假设 MHA/GQA 的 KV 头数与层数固定；若采用 MLA 或…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-vit-kv-cache-sec-1\">一 · 一句话直觉与它的物理含义</h3>\n<p>把一张图喂进 VLM，视觉编码器把图切成 patch、过 ViT、再经投影层塞进 LLM 解码器——从这一刻起，这些视觉 token 在解码器眼里与文本 token 没有任何区别：它们同样参与注意力，同样在每一层产生一份 K 和一份 V，同样要在整个 decode 生命周期里驻留在显存中。所谓“多模态 KV cache 显存式”，说的就是这件事的代价：视觉 token 不是免费的旁路信息，它们按 token 数线性地吃显存、吃带宽。压缩视觉 token 数，就是线性削减 decode 阶段的显存占用与 KV 读写带宽；这不是近似收益，而是结构性的线性关系。</p>\n<p>物理含义要说得更硬一点。decode 阶段每生成一个 token，注意力要对历史 KV 做一次读；KV 常驻显存，读它就要走 HBM 带宽。视觉 token 越多，历史 KV 越长，单步 decode 的带宽需求越高，而 decode 本身是带宽受限的（算术强度低）。因此视觉 token 数同时压在两个地方：显存容量决定 batch 上限，显存带宽决定单步延迟。这就是为什么视觉 token 压缩在多模态推理里是“一石二鸟”的杠杆，而不是单纯的显存优化。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-2\">二 · 严格定义：从每 token 每层的字节数推起</h3>\n<p>推导只有一步关键：把每层、每 token 的 KV 存储量写成 $$2\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot b_{\\text{kv}}$$。系数 2 对应 K 与 V 两份；$$H_{\\text{kv}}$$ 是 KV 头数，在 GQA 下远小于 Q 头数；$$d_{\\text{head}}$$ 是单头维度；$$b_{\\text{kv}}$$ 是每元素字节数，FP16 取 2、FP8 取 1。把这个量乘上解码器层数 $$L$$、总 token 数 $$(N_{\\text{vis}}+N_{\\text{txt}})$$、并发批大小 $$B_{\\text{batch}}$$，就得到完整的显存式：</p>\n<div class=\"formula\">$$M_{\\text{KV}}=2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot (N_{\\text{vis}}+N_{\\text{txt}})\\cdot b_{\\text{kv}}\\cdot B_{\\text{batch}}$$</div>\n<p>这个式子的严格性体现在它的线性结构上：$$M_{\\text{KV}}$$ 对 $$N_{\\text{vis}}$$ 是一阶线性的，没有隐藏的高阶项。因此“视觉 token 压缩比”与“KV 显存节省比”是同一个数——把 2000 个视觉 token 压到 500 个，KV 显存里视觉那部分就降到四分之一，decode 每步要读的 KV 字节数同样降到四分之一。工程上这意味着压缩比可以直接写进容量预算表，不需要拟合曲线。</p>\n<p>变量含义必须逐项钉死，否则后面所有估算都会漂移。<ul><li>$$L$$：LLM 解码器层数，与视觉编码器层数无关，别混用。</li><li>$$H_{\\text{kv}}$$：KV 头数，GQA 下是 Q 头数的一个分数，这是显存式里最容易被高估的一项。</li><li>$$d_{\\text{head}}$$：单头维度，通常固定。</li><li>$$N_{\\text{vis}}$$、$$N_{\\text{txt}}$$：视觉与文本 token 数，前者是压缩杠杆的作用对象。</li><li>$$b_{\\text{kv}}$$：每元素字节数，FP16=2、FP8=1，量化到 FP8 直接把整式砍半。</li><li>$$B_{\\text{batch}}$$：并发序列数，容量规划的反推目标。</li></ul></p>\n<p>适用边界同样要写进定义里，否则它就不是“严格定义”而是“理想化定义”：该式假设 MHA/GQA 且 KV 头数与层数固定；若模型采用 MLA 或跨层共享 KV，等效项必须替换为压缩后的潜向量维度，$$H_{\\text{kv}}\\cdot d_{\\text{head}}$$ 不再成立；该式也未计入 PagedAttention 的块内碎片与页表开销，实际占用通常高出 5%–15%。换句话说，公式给的是下界性质的理论占用，工程预算要在此基础上加安全余量。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-3\">三 · 为什么需要这个式子：容量反推与杠杆定位</h3>\n<p>需要它，是因为多模态推理的容量决策必须能反推。给定单卡显存预算与文本长度预算，把上式对 $$B_{\\text{batch}}$$ 求解，就得到单卡可容纳的并发序列数：</p>\n<div class=\"formula\">$$B_{\\text{batch}}^{\\max}=\\left\\lfloor \\frac{M_{\\text{budget}}-M_{\\text{weights}}-M_{\\text{act}}}{2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot (N_{\\text{vis}}+N_{\\text{txt}})\\cdot b_{\\text{kv}}} \\right\\rfloor$$</div>\n<p>这个反推把“视觉 token 数”从模型细节提升为容量参数：$$N_{\\text{vis}}$$ 出现在分母里，它直接决定 batch 上限。于是视觉 token 压缩比成为提高并发密度最直接的杠杆——不需要改调度器、不需要改并行策略，只要把 $$N_{\\text{vis}}$$ 降下来，分母就变小，batch 上限就抬上去。对在线服务而言，batch 上限抬升意味着在相同 SLO 下能吞下更多并发请求，这是吞吐收益；对长上下文场景而言，视觉 token 挤占文本预算，压缩视觉 token 等于把上下文窗口还给文本。</p>\n<p>具体例子：一个 70B 级解码器，$$L$$ 取数十层量级、$$H_{\\text{kv}}$$ 在 GQA 下取 8 个头、$$d_{\\text{head}}$$ 取 128、$$b_{\\text{kv}}$$ 取 FP16 的 2 字节，单 token 单层的 KV 字节数是 $$2\\times 8\\times 128\\times 2$$，即每层每 token 4 KB 量级；乘上几十层，单 token 的 KV 就在百 KB 量级。一张高分辨率图切出上千个视觉 token，单请求的视觉 KV 就是数百 MB 量级；并发数十路，视觉 KV 就吃掉数十 GB。此时把视觉 token 压到四分之一，省下的就是几十 GB——这正是能多开一批并发序列的显存。带宽侧同理：decode 每步要读的 KV 字节数按同一比例下降，单步延迟随之改善。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-4\">四 · 常见误解之一：把理论占用当预算</h3>\n<p>最常见的误用是只按公式算理论显存而不留 PagedAttention 碎片与页表余量。PagedAttention 按块管理 KV，块内未填满的部分是碎片，页表本身也要占显存；这些开销不在上式里，实际占用通常高出 5%–15%。按公式精确分配显存的后果是可预期的：高并发下直接触发 OOM。正确做法是把 5%–15% 作为结构性余量写进预算，先扣掉再反推 $$B_{\\text{batch}}^{\\max}$$，而不是先算出满打满算的 batch 再去撞墙。这个余量不是保守估计，而是分页机制的内生成本。</p>\n<p>第二个相关误解是忽略 $$b_{\\text{kv}}$$ 的动态性：以为 KV 一旦按 FP16 分配就固定不变。实际上 KV 量化到 FP8 会把整式砍半，容量翻倍，但量化误差会传播到注意力输出——这条链路是另一条条目的主题，此处只指出：$$b_{\\text{kv}}$$ 是显存式里唯一能“不改 token 数就改显存”的乘子，因此它和 $$N_{\\text{vis}}$$ 是两个独立杠杆，不能混为一谈。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-5\">五 · 常见误解之二：在 MLA 上沿用 GQA 的头维度</h3>\n<p>在 MLA 或跨层共享 KV 的模型上沿用 GQA 的 $$H_{\\text{kv}}\\cdot d_{\\text{head}}$$ 估算，会把压缩潜向量当成完整 KV，显存需求被高估数倍，直接浪费容量——本来能开更多并发，却因为估算虚高而自我限流。这类模型的 KV 以低秩潜向量形式缓存，等效项必须替换为压缩后的潜向量维度；上式在这种结构下不再是“严格定义”，而是一个失效的近似。判断方法很简单：看模型是否缓存完整 K/V 还是缓存潜向量，前者用原式，后者换等效项。</p>\n<p>第三个误解更隐蔽：只压缩视觉 token 数却不检查压缩后 token 的语义保真度。decode 显存确实下降了，但压缩导致信息丢失，模型需要重编码、重试请求甚至回退到更高分辨率重跑，端到端容量反而变差。显存式只描述“占用”，不描述“质量”；压缩比必须与保真度约束一起看，否则省下的显存会被重试流量吃掉。这条边界决定了视觉 token 压缩不能单独作为容量杠杆使用，必须与质量评估联动。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-6\">六 · 工程判断：把式子当预算骨架而非答案</h3>\n<p>落到工程上，这个式子的正确用法是三层：第一层用它定位杠杆——$$N_{\\text{vis}}$$ 与 $$b_{\\text{kv}}$$ 是仅有的两个线性乘子，前者靠 token 压缩，后者靠 KV 量化，二者收益可直接相加换算；第二层用它反推 batch 上限，但必须先扣掉权重、激活与 5%–15% 的分页余量；第三层用它做敏感性分析——视觉 token 数每降一成，视觉那部分 KV 显存与 decode 带宽需求就降一成，这个比例不随 batch 变化而变，因此可以作为容量规划的固定系数写进表格。真正的工程判断在于：当显存预算吃紧时，先问 $$N_{\\text{vis}}$$ 能不能压、$$b_{\\text{kv}}$$ 能不能降，而不是先去调调度器——因为调度器改变的是时间维度上的排布，而这个式子改变的是空间维度上的分母。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-7\">七 · 多模态 KV cache 显存式的适用边界与代价结构</h3>\n<p>这个式子之所以有用，是因为它把“视觉 token 压缩”这件在视觉编码器侧看起来模糊的事，直接换算成了解码器侧可结算的显存账。推导的关键一步是把每层每 token 的 KV 存储量写成 <span class=\"formula\">$$2\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot b_{\\text{kv}}$$</span>，再乘层数、总 token 数与并发批大小，得到线性于视觉 token 数的显存式。注意这里的线性不是近似，而是结构性的：视觉 token 与文本 token 在进入解码器之后走的是同一套 KV 分配路径，没有任何“视觉专用缓存”可以绕开层数与 KV 头维度这两个乘数。因此压缩视觉 token 的收益不是打折的，而是逐 token 线性兑现——这是本方案最硬的立论基础，也是它失效时最容易被误判的地方。</p>\n<p>边界条件必须写死在公式旁边，否则它会变成一张过度承诺的账单。适用前提是 MHA/GQA 且 KV 头数与层数固定；一旦模型采用 MLA 或跨层共享 KV，式中 <span class=\"formula\">$$H_{\\text{kv}}\\cdot d_{\\text{head}}$$</span> 这一项就不再是完整的 KV 头维度，而应替换为压缩后的潜向量维度。此时若仍沿用 GQA 的估算方式，等于把压缩潜向量当成完整 KV 来算，显存需求会被高估数倍，容量规划随之失真——这不是保守，而是浪费。另一条边界在字节宽度：<span class=\"formula\">$$b_{\\text{kv}}$$</span> 取 FP16 为 2、FP8 为 1，量化到 FP8 直接砍半，但这条收益与视觉 token 压缩是相乘而非相加的关系，二者叠加时的排序会改变最优压缩比。</p>\n<p>公式本身是理想占用，不是可分配占用。它未计入 PagedAttention 的块内碎片与页表开销，实际占用通常高出 5%–15%。这个比例在低并发时被余量吸收，在高并发下则直接决定是否触发 OOM：按公式精确分配显存、不留碎片与页表余量，是这套估算最典型的失败模式。工程上的正确用法是把它当作下界而非预算，容量决策时先扣掉这部分开销，再反推单卡可容纳的并发序列数——给定显存预算与文本长度，视觉 token 数直接决定 batch 上限，因此视觉 token 压缩比是提高并发密度的最直接杠杆，但这个杠杆的支点必须落在“实际可用显存”而不是“理论显存”上。</p>\n<p>还有一类失效不在显存侧，而在语义侧。只压缩视觉 token 数却不检查压缩后 token 的语义保真度，decode 阶段显存确实下降，但重编码或重试请求增加，端到端容量反而变差——省下的 KV 字节被额外的请求轮次吃掉。这类代价不会出现在上面的式子里，却会出现在 SLO 上。判断标准因此不能只看 <span class=\"formula\">$$M_{\\text{KV}}$$</span> 的下降幅度，而要看单位显存所能支撑的有效吞吐：压缩比提高时，若保真度损失导致重试率上升，等效并发密度可能不升反降。把这条约束和 5%–15% 的碎片余量一起写进容量模型，这个显存式才算真正可用。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-8\">八 · 显存式的适用边界与两类误算</h3>\n<p>这条显存式只在 MHA/GQA 结构下成立：层数固定、每层 KV 头数固定，每 token 每层的 KV 字节数就是 <span>2·H<sub>kv</sub>·d<sub>head</sub>·b<sub>kv</sub></span>，再乘层数、总 token 数与并发批大小。一旦模型改用 MLA 或跨层共享 KV，KV 不再按头展开，而是压成一个潜向量，等效项必须换成压缩后的潜向量维度乘层数；此时仍套用 <span>H<sub>kv</sub>·d<sub>head</sub></span> 会把显存需求高估数倍，容量规划随之失真。换言之，公式的变量集本身就是适用性声明，换结构就要换变量。</p>\n<div class=\"formula\">$$M_{\\text{KV}}=2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot (N_{\\text{vis}}+N_{\\text{txt}})\\cdot b_{\\text{kv}}\\cdot B_{\\text{batch}}$$</div>\n<p>第二个边界来自分配器而非模型：公式算的是有效载荷，PagedAttention 的块内碎片与页表本身要占地方，实际占用通常高出 5%–15%。按理论值精确切分显存、不留余量，单卡在低并发时看不出问题，一旦 batch 拉满就触发 OOM——这是上线阶段最常见的失败模式。工程做法是把预算写成 <span>M<sub>KV</sub>·(1+δ)</span>，δ 取覆盖碎片与页表的上界，再反推 batch 上限。</p>\n<table class=\"mini\"><thead><tr><th>情形</th><th>公式是否可直接用</th><th>系统代价</th></tr></thead><tbody><tr><td>MHA/GQA，层与 KV 头固定</td><td>可用，需加碎片余量</td><td>视觉 token 压缩比线性换取 decode 显存与带宽</td></tr><tr><td>MLA / 跨层共享 KV</td><td>需替换为潜向量维度</td><td>误用会高估需求数倍，浪费容量</td></tr><tr><td>仅压缩视觉 token 数</td><td>公式仍成立</td><td>显存降但语义保真度下降，重编码与重试增多，端到端容量反降</td></tr></tbody></table>\n<p>由此得到一条判断：视觉 token 压缩比是提高并发密度最直接的杠杆，但它不是免费的。压缩后 token 的语义保真度若不足，decode 阶段显存确实下降，可重编码请求与重试会把省下的容量吃回去，端到端吞吐反而变差。因此容量决策应把压缩比、保真度损失与碎片余量放在同一张预算表里核算，而不是只看公式给出的理论显存。</p>\n<h3 id=\"th-vit-kv-cache-sec-9\">九 · 逐项拆解：为什么系数 2 与 $H_{\\text{kv}}$ 是主杠杆</h3>\n<p>把公式拆成三层来看：单 token 单层的字节数、序列级总量、批级总量。最内层是 $2\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot b_{\\text{kv}}$。系数 2 不是可选常数，它对应 K 与 V 两份张量——decode 阶段每一步都要读完整的 K 与 V 才能算注意力，因此这两份都必须常驻，不能像某些权重那样按需换入。$H_{\\text{kv}}$ 在 GQA 下远小于 Q 头数，这正是现代解码器把 KV 显存压下来的第一手段：Q 头可以多（表达力），KV 头必须少（带宽与容量）。$d_{\\text{head}}$ 通常固定为 64 或 128，工程上几乎不可调，属于硬件/模型结构给定的常数。$b_{\\text{kv}}$ 是唯一可以直接用精度换容量的项：FP16 记 2 字节，FP8 记 1 字节，一次精度切换就把整条式子减半，代价是数值误差——这条误差链在量化误差传播界那一部分展开，此处只把它当作可用的乘法因子。</p>\n<p>把内层乘以 $L$ 得到单 token 跨所有层的字节数，再乘以 $(N_{\\text{vis}}+N_{\\text{txt}})$ 得到单序列字节数，最后乘以 $B_{\\text{batch}}$ 得到设备上的 KV 总量。这里有一个容易被忽略的次序问题：$B_{\\text{batch}}$ 是并发序列数，不是请求数；连续批处理下同一时刻活跃的序列才计入，排队中的请求不占 KV。因此这条式子的正确读法是“稳态并发下的驻留显存”，而不是“一段时间内处理过的请求总量”。</p>\n<p>具体例子：一个 $L=80$、$H_{\\text{kv}}=8$、$d_{\\text{head}}=128$ 的解码器，单 token 单层 KV 为 $2\\times 8\\times 128\\times 2=4096$ 字节（FP16），跨 80 层即 320 KB/token。若一条请求含 4096 个视觉 token 加 512 个文本 token，单序列 KV 约 1.4 GB；$B_{\\text{batch}}=8$ 时约 11 GB。这个量级说明：视觉 token 数在长视觉序列场景下已经与模型权重同阶，容量规划不能再把它当零头。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-10\">十 · 推导关键步：从“每层每 token”到“线性于视觉 token”</h3>\n<p>推导只有一步是真正关键的：把每层每 token 的 KV 存储量写成闭式 $2\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot b_{\\text{kv}}$，然后认定它对层、对 token、对批三个维度都是可乘的。可乘性来自三个假设：其一，每层都有独立的 K/V 投影，层间不共享；其二，每个 token 在每层都产生一对 K/V，位置不合并；其三，批内序列各自持有独立 KV，不交叉。三条都成立时，显存对 $N_{\\text{vis}}$ 是严格线性的，于是“压缩视觉 token 数”与“节省显存”之间是等比换算，压缩比 $r=N'_{\\text{vis}}/N_{\\text{vis}}$ 直接给出显存比。</p>\n<div class=\"formula\">$$M_{\\text{KV}}=2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot (N_{\\text{vis}}+N_{\\text{txt}})\\cdot b_{\\text{kv}}\\cdot B_{\\text{batch}}$$</div>\n<p>把式子改写成容量反推形式更有工程价值：给定单卡可用于 KV 的显存预算 $M_{\\text{budget}}$ 与文本长度 $N_{\\text{txt}}$，可容纳并发为</p>\n<div class=\"formula\">$$B_{\\text{batch}}^{\\max}=\\left\\lfloor \\frac{M_{\\text{budget}}}{2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot b_{\\text{kv}}\\cdot (N_{\\text{vis}}+N_{\\text{txt}})}\\right\\rfloor$$</div>\n<p>这个反推式暴露了视觉 token 的杠杆位置：分母里 $N_{\\text{vis}}$ 与 $N_{\\text{txt}}$ 是加法关系，当 $N_{\\text{vis}}\\gg N_{\\text{txt}}$ 时，$B_{\\text{batch}}^{\\max}$ 几乎完全由视觉 token 数决定。换言之，在多图、高分辨率、视频帧这类输入上，视觉 token 压缩比就是并发密度的直接倍数。代价也随之明确：压缩视觉 token 削减的是 decode 阶段的显存驻留与每步 KV 读取带宽，但预填阶段的计算量并不因此等比下降——预填的注意力计算仍与视觉 token 数相关，只是不再需要把全部视觉 KV 常驻。这就是预填/解码分离架构里两侧容量不对称的根源。</p>\n<p>离散化与近似发生在两处。第一处是 token 计数本身：视觉编码器输出的 patch 序列经投影、合并、池化后进入解码器的 token 数是离散整数，压缩方案（如相邻 token 合并、按显著性丢弃）给出的 $N'_{\\text{vis}}$ 是整数，压缩比只能取离散档位，不能连续调；容量反推得到的 $B_{\\text{batch}}^{\\max}$ 还必须向下取整，余量浪费在批边界上。第二处是分页：真实分配以块为单位，块大小固定，序列尾部必然产生块内碎片，页表本身也占显存。公式给的是“有效载荷”，实际占用要在此基础上加 5%–15%。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-11\">十一 · 失效条件的数学形态：MLA 与跨层共享如何改写等效项</h3>\n<p>公式的适用边界写在结构假设里：MHA/GQA 且层数与 KV 头数固定。一旦换成 MLA，KV 不再以“头 × 头维度”的完整张量驻留，而是压成低秩潜向量，缓存的是潜向量而非 K/V 本身。此时 $H_{\\text{kv}}\\cdot d_{\\text{head}}$ 这一项必须整体替换为压缩后的潜向量维度（潜维度加解耦的 RoPE 分量），不能沿用 GQA 的头维度去乘。误用的后果是方向性错误：把潜向量当成完整 KV，会把显存需求高估数倍，容量被白白浪费；反过来若在 GQA 模型上套用 MLA 的潜维度，则会低估并直接 OOM。</p>\n<p>跨层共享 KV 是另一种改写：若相邻若干层共用一份 K/V，则 $L$ 不再是有效层数，应替换为“独立 KV 组数”$L/g$，$g$ 为共享粒度。此时式子仍是线性的，但斜率变了。工程判断上，看到一个新模型结构，第一件事是确认它缓存的对象到底是什么：完整 K/V、潜向量、还是跨层共享的组表示。三者对应三种不同的等效项，混用是容量规划最常见的系统性错误。</p>\n<p>具体代价对比：同一 $L=80$、$H_{\\text{kv}}=8$、$d_{\\text{head}}=128$ 的模型，若改成潜维度 512 的 MLA 式缓存，单 token 单层从 4096 字节降到约 1 KB 量级（含 RoPE 分量），跨层与批乘完后整机 KV 预算可支撑的并发显著上升；但注意这是结构红利，不是压缩红利，两者不能叠加计算，否则重复折减。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-12\">十二 · 碎片与页表：5%–15% 的余量从哪来、怎么留</h3>\n<p>公式未计入 PagedAttention 的块内碎片与页表开销，实际占用通常高出 5%–15%。这 5%–15% 不是拍脑袋的安全系数，它有明确来源：块内碎片来自每条序列最后一个未填满的块，期望浪费约为半个块每序列，序列越短、并发越高，这部分占比越大；页表开销来自块到物理页的映射表，随块数线性增长，长序列、大并发时不可忽略。两者叠加，低并发长序列时偏下限，高并发短序列时偏上限。</p>\n<p>因此正确的容量分配不是“按公式精确切分显存”，而是先算有效载荷，再按并发形态留余量，最后才把剩余显存给权重与激活。失败模式很直接：按公式精确分配而不留余量，上线后在高并发下触发 OOM；这类 OOM 往往不在压测的稳态出现，而在流量尖峰、序列长度分布偏移时出现，因为碎片占比随序列长度分布变化。工程上的稳妥做法是把余量做成显式参数而非隐式假设，让容量规划器在 $B_{\\text{batch}}^{\\max}$ 上先打一次折再向下取整。</p>\n<p>另一个常被忽略的代价项是压缩本身的语义风险：只压缩 $N_{\\text{vis}}$ 而不检查压缩后 token 的语义保真度，decode 显存确实下降，但重编码或重试请求增加，端到端容量反而变差。这在式子里看不到，因为式子只统计驻留显存，不统计请求失败率。容量决策若只看这一条式子，就会把“压缩比”当成免费杠杆，而实际上它是有质量代价的杠杆——质量代价的界在视觉 token 压缩误差界那一部分给出。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-13\">十三 · 用式子做工程判断：三个可操作的换算</h3>\n<p>第一个换算：精度换容量。$b_{\\text{kv}}$ 从 2 降到 1，整条式子减半，这是不需要改模型结构的最大单项收益，代价是 KV 数值误差，需要与量化误差上界一起评估，不能单独决策。第二个换算：压缩比换并发。$N_{\\text{vis}}$ 降为 $r$ 倍，在 $N_{\\text{vis}}\\gg N_{\\text{txt}}$ 时 $B_{\\text{batch}}^{\\max}$ 近似升为 $1/r$ 倍，这是提高并发密度最直接的杠杆；但要注意预填侧计算量不随之等比下降，分离式架构下两侧要分别定容。第三个换算：层共享换斜率。跨层共享把 $L$ 换成 $L/g$，收益是结构性的，但会改变模型表达力，属于模型设计决策而非部署调参。</p>\n<p>具体例子：某部署给定 KV 预算 40 GB，模型为 $L=80$、$H_{\\text{kv}}=8$、$d_{\\text{head}}=128$、FP16，文本长度 512。单序列在 $N_{\\text{vis}}=4096$ 时约 1.4 GB，理论并发约 28；若视觉 token 压到 1024，单序列约 0.47 GB，理论并发约 85。再留 10% 碎片余量并向下取整，实际并发分别落到 25 与 76 量级。这个差距说明视觉 token 压缩比在容量规划里是数量级级别的变量，而不是微调项。</p>\n<p>最后落在机制上：这条式子的价值不在于算出一个精确数字，而在于它把“视觉 token 数”钉成了 decode 容量的唯一线性自变量，并把精度、头数、层共享三个结构选择显式化为可乘因子。工程上真正要守的是两件事——确认缓存对象与结构假设一致，以及在有效载荷之外显式预留碎片与页表余量；其余调参都只是在这条线性关系上选斜率。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-14\">十四 · 容量反推与失效边界：这条显存式什么时候不能直接用</h3>\n\n<p>把公式从“算占用”翻转为“定容量”，是它在工程上真正有用的形态：给定单卡可用于 KV 的显存预算 <span>M_budget</span> 与文本长度 <span>N_txt</span>，可容纳并发序列数由 <span>B_batch ≤ M_budget / [2·L·H_kv·d_head·b_kv·(N_vis+N_txt)]</span> 给出。分母中 <span>N_vis</span> 与 <span>N_txt</span> 是加法关系而非乘法，这意味着视觉 token 在分母中的权重与文本 token 完全等价——一张高分辨率图切出的视觉 token 数若与数千文本 token 同量级，它对 batch 上限的挤压就与一段长 prompt 无异。由此得到一个直接的工程判断：视觉 token 压缩比 <span>r = N_vis'/N_vis</span> 带来的并发提升近似为 <span>(N_vis+N_txt)/(r·N_vis+N_txt)</span>，当 <span>N_txt</span> 远小于 <span>N_vis</span> 时收益接近 <span>1/r</span>，而当文本上下文本身很长时，压缩视觉 token 的边际收益被迅速稀释。这条近似式决定了优化投入该往哪里放：短文本、多图、高并发的请求形态才值得为视觉 token 压缩付出精度代价。</p>\n\n<p>公式的失效条件必须写进容量规划文档，而不是留在推导注释里。第一类是结构失效：公式的 <span>2·H_kv·d_head</span> 项隐含 MHA/GQA 的“每层每 token 存完整 K 与 V”假设；MLA 把 KV 压成低秩潜向量、跨层共享 KV 则让多层复用同一份缓存，此时等效项应替换为压缩后的潜向量维度，若仍沿用 GQA 的头维度估算，会把显存需求高估数倍，直接浪费可售容量。第二类是开销失效：公式不含 PagedAttention 的块内碎片与页表本身，实际占用通常高出 5%–15%，按公式精确分配、不留余量，在高并发下就是 OOM 的充分条件。第三类是精度失效：<span>b_kv</span> 从 FP16 的 2 降到 FP8 的 1 确实让整式减半，但这是数值精度问题而非 token 数问题，KV 量化的误差传播与视觉 token 压缩的语义损失是两种不同性质的退化，不能互相替代。</p>\n\n<table class=\"mini\"><thead><tr><th>失效类型</th><th>触发条件</th><th>系统代价</th></tr></thead><tbody><tr><td>结构失配</td><td>MLA / 跨层共享 KV 上沿用 H_kv·d_head</td><td>容量被高估数倍，浪费显存预算</td></tr><tr><td>开销漏算</td><td>按公式精确分配、无碎片余量</td><td>实际占用高出 5%–15%，高并发 OOM</td></tr><tr><td>语义失真</td><td>只压 N_vis 不校验保真度</td><td>decode 显存降，重编码/重试上升，端到端容量变差</td></tr></tbody></table>\n\n<p>第三类失效最容易被忽视，因为它不在公式里。压缩 <span>N_vis</span> 只保证 decode 阶段的显存与带宽线性下降，却不保证压缩后的视觉 token 仍承载足够信息；一旦下游任务需要重编码、重试或回退到未压缩路径，这些额外请求会重新占用 prefill 算力与 KV 空间，端到端容量反而低于不压缩。因此这条式子的正确用法是把它当作“上界估算 + 余量修正”的工具：先用它反推理论 batch 上限，再按 5%–15% 的碎片开销打折，最后用压缩后 token 的语义保真度指标决定 <span>r</span> 能取到多小。三者缺一，公式给出的就只是一个在实验室成立、在生产环境失效的数字。</p>\n<h3 id=\"th-vit-kv-cache-sec-15\">十五 · 线性假设的三条硬约束</h3>\n<p>$$M_{\\text{KV}}=2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot (N_{\\text{vis}}+N_{\\text{txt}})\\cdot b_{\\text{kv}}\\cdot B_{\\text{batch}}$$ 之所以能作为容量决策的抓手，全靠它对视觉 token 数 $$N_{\\text{vis}}$$ 的线性。这个线性不是免费的，它建立在三条同时成立的约束上：其一，每个视觉 token 在每一层都生成一对完整的 K/V，且这份 K/V 在整个 decode 生命周期内常驻；其二，KV 头数与层数在请求存续期间不随序列位置变化；其三，批内每条序列的 KV 占用彼此独立、可加。任何一条被打破，公式的系数就不再是常数，反推 batch 上限的那一步随之失真。</p>\n<p>第一条约束在多模态场景里最容易被悄悄违反。视觉 token 在预填阶段一次性写入后确实常驻，但若系统对图像做了重编码、对视觉 token 做了动态重采样，或采用“先丢弃视觉 KV、需要时再重算”的策略，那么 $$N_{\\text{vis}}$$ 就不是一个静态量，而是随时间波动的占用量。此时公式给出的是峰值而非均值，用它做容量规划会系统性高估可容纳并发数。工程上要区分“分配上限”和“驻留均值”：前者按峰值算，后者才是决定 decode 带宽压力的量。</p>\n<p>第二条约束对应结构层面。MHA/GQA 下 $$H_{\\text{kv}}$$ 与 $$L$$ 是编译期常量，公式的乘积项可以直接查表。一旦模型改用 MLA 或跨层共享 KV，每 token 每层的实际存储从 $$2\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}$$ 变成压缩后的潜向量维度，量级差异可达数倍。沿用 GQA 的 $$H_{\\text{kv}}\\cdot d_{\\text{head}}$$ 去估算 MLA 模型，是把“完整 KV”当成“压缩潜向量”，显存需求被高估，容量被白白浪费；反过来，把 MLA 的低占用套到 GQA 模型上则会低估并触发 OOM。这一条不是精度问题，是结构识别问题——估算前必须先确认模型的 KV 组织方式。</p>\n<p>代价层面：线性假设失效的代价直接体现在并发密度上。以 FP16（$$b_{\\text{kv}}=2$$）为例，视觉 token 数翻倍意味着单序列 KV 显存翻倍，在固定显存预算下单卡可容纳的 $$B_{\\text{batch}}$$ 近似减半；若同时叠加 PagedAttention 的 5%–15% 额外占用，实际可容纳序列数还要再打折。这就是为什么容量规划不能只算理论值。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-16\">十六 · PagedAttention 开销：公式之外的那 5%–15%</h3>\n<p>公式把 KV 视为按 token 紧密排列的连续数组，而真实系统按块分配。PagedAttention 以固定大小的块为单位管理 KV，序列长度不是块大小的整数倍时，最后一个块内部产生碎片；同时每个序列维护页表，页表本身占显存。这两项都不在 $$M_{\\text{KV}}$$ 里，却实实在在地吃掉预算，实际占用通常高出 5%–15%。</p>\n<p>把这一项写成可计算的余量：设块大小为 $$S_{\\text{blk}}$$ 个 token，序列总 token 数 $$N=N_{\\text{vis}}+N_{\\text{txt}}$$，则块内碎片的上界约为每序列 $$(S_{\\text{blk}}-1)$$ 个 token 的 KV 空间，乘以每 token 每层字节数 $$2\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot b_{\\text{kv}}$$ 与层数 $$L$$。碎片比例随 $$N$$ 增大而衰减，因此在长视觉序列（$$N_{\\text{vis}}$$ 大）时碎片占比小，而在短文本、少视觉 token 的高并发场景里碎片占比反而显著——这正是“小请求高并发”最容易 OOM 的原因。</p>\n<p>工程判断上，容量决策应把公式结果乘以一个 1.05–1.15 的安全系数再反推 $$B_{\\text{batch}}$$，并把页表开销按序列数线性计入。一个具体例子：视觉 token 压缩把 $$N_{\\text{vis}}$$ 减半后，理论显存省下一半，但若压缩后序列变短、块内碎片占比上升，实际节省会小于理论值；此时若不做余量修正，压缩带来的并发提升会被碎片吃掉一部分。反过来，若压缩后序列仍远长于块大小，碎片影响可忽略，压缩收益接近线性兑现。</p>\n<p>代价：不留余量按公式精确分配，上线后在高并发下直接触发 OOM，这是最典型的失败模式；而过度预留又浪费容量。正确做法是把 5%–15% 作为随请求长度分布变化的函数来估，而不是拍一个固定百分比。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-17\">十七 · 压缩视觉 token 的语义保真度边界</h3>\n<p>公式把 $$N_{\\text{vis}}$$ 当作可自由缩减的自变量，压缩比越高显存越省。但这条线性只在“压缩后 token 仍承载同等信息”时成立。一旦压缩损失语义保真度，decode 显存确实下降，可重编码、重试、多轮追问的请求比例上升，端到端容量反而变差——省下的显存被额外的请求轮次抵消。</p>\n<p>把这一点形式化：设压缩比为 $$r=N_{\\text{vis}}'/N_{\\text{vis}}$$，单请求首次 decode 的 KV 显存按 $$r$$ 线性下降；但若保真度不足导致请求重试概率为 $$p(r)$$，则有效请求数变为原来的 $$1+p(r)$$ 倍，等效显存需求为 $$r\\cdot(1+p(r))$$ 倍原值。当 $$r\\cdot(1+p(r))&gt;1$$ 时，压缩在容量上净亏。这个不等式给出了压缩比的适用上界：压缩越激进，$$p(r)$$ 上升越快，存在一个最优点而非越压越好。</p>\n<p>具体机制上，视觉 token 压缩常通过重采样、池化或注意力聚合实现，这些操作对细粒度空间信息（小目标、文字、表格线）损伤最大。工程上应把压缩比与任务类型绑定：对文档理解、图表问答这类依赖细节的任务，压缩比要保守；对整体场景描述类任务可激进。判断依据不是公式，而是重试率与答案质量的在线监控。</p>\n<p>代价：压缩带来的显存节省是线性的、可预测的；保真度损失带来的重试成本是非线性的、任务相关的。容量规划若只信公式的线性收益，会低估后者。规模上限由此显现——压缩比存在一个由保真度决定的拐点，越过拐点后继续压缩不再提升有效并发。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-18\">十八 · 批大小与显存预算的反推边界</h3>\n<p>公式在容量决策中的用法是反推：给定显存预算 $$M_{\\text{budget}}$$ 与文本长度 $$N_{\\text{txt}}$$，解出 $$B_{\\text{batch}}=(M_{\\text{budget}})/(2LH_{\\text{kv}}d_{\\text{head}}(N_{\\text{vis}}+N_{\\text{txt}})b_{\\text{kv}})$$。这个反推的适用边界在于分母中的 $$N_{\\text{vis}}$$ 必须是该批次内所有序列的真实视觉 token 数之和，而不是单序列的典型值。</p>\n<p>多模态请求的视觉 token 数分布极不均匀：一张高分辨率图与一张缩略图的 $$N_{\\text{vis}}$$ 可能差一个数量级。若按均值反推 $$B_{\\text{batch}}$$，实际批内只要混入少数长视觉序列，总占用就会超过预算。正确做法是按分位数而非均值做容量规划，或采用按序列实际长度动态准入的调度——这正是连续批处理在多模态场景下必须与 KV 感知调度结合的原因。公式本身没错，错在把分布当成标量。</p>\n<p>规模上限还受另一侧约束：$$B_{\\text{batch}}$$ 增大到一定程度后，decode 阶段的 KV 带宽压力成为瓶颈，而非显存容量。此时公式给出的“还能再塞几条”失去意义，因为即便显存够，带宽也喂不饱。判断切换点的依据是 decode 每步需读取的 KV 字节数与可用带宽之比，而非剩余显存。工程上应同时监控显存水位与 KV 读取带宽利用率，两者任一触顶即为该配置的规模上限。</p>\n<p>代价：按均值反推导致的 OOM 是突发性的，往往在流量高峰、长图请求集中时爆发；按分位数规划则牺牲一部分平均并发密度换取稳定性。这是容量规划里典型的均值-峰值权衡，公式只提供骨架，分布决定填充。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-19\">十九 · 何时该弃用公式改用实测</h3>\n<p>公式的价值在于快速估算与敏感性分析，而非精确分配。当出现以下信号时，应停止用公式外推，转为实测：模型结构非 MHA/GQA（MLA、跨层共享、混合结构）；请求的视觉 token 数分布方差大且长尾显著；系统启用了视觉 KV 的动态驱逐或重算；压缩策略的保真度拐点尚未标定。这些情况下公式的系数不再是常数，外推误差会累积到不可接受。</p>\n<p>实测的抓手是分层的显存水位与请求级 KV 占用采样：按序列记录实际分配的块数与页表开销，反算出真实的有效每 token 字节数，再与公式的理论值对比，得到该部署下的经验修正系数。这个系数应随请求长度分布定期重标定，而不是一次性写死。工程判断上，公式用于设计期的容量上界与压缩收益预估，实测系数用于运行期的准入控制与扩缩容决策，两者分工明确。</p>\n<p>最后落在具体机制：多模态 KV cache 的显存式是一个线性骨架，它的适用边界由结构（KV 组织方式）、分配（块碎片与页表）、语义（压缩保真度）、分布（视觉 token 数方差）四条线共同划定。越过任一条线，公式从“估算工具”退化为“误导来源”。稳健的做法是把公式输出当作上界，把 5%–15% 的分配开销与保真度重试率当作必须显式建模的修正项，再用在线实测系数收敛——容量决策的可靠性来自修正项的诚实度，而非公式本身的整洁。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-20\">二十 · 公式成立的前提，以及它在哪里开始说谎</h3>\n<p>那条线性式只在一种结构下成立：每层独立持有 K/V，且 KV 头数、头维度、层数在整段解码过程中不变。它把每层每 token 的存储写成 <span class=\"formula\">$$2\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot b_{\\text{kv}}$$</span> 再乘层数、总 token 数与批大小，本质是假设 KV 是“稠密、逐层、逐 token 独立”的三维张量。一旦模型换成 MLA 或跨层共享 KV，这个假设就崩了——潜向量维度取代了 <span class=\"formula\">$$H_{\\text{kv}}\\cdot d_{\\text{head}}$$</span>，压缩后的潜向量远小于完整 KV，若仍沿用 GQA 的头维度去估，显存需求会被高估数倍，容量规划直接失真。工程判断很简单：先确认注意力结构，再决定用哪一套等效项，别把两种结构的公式混用。</p>\n<p>第二个失效点是页表与块内碎片。公式给出的是“有效载荷”显存，而 PagedAttention 按块分配，最后一个块往往填不满，页表本身也要占空间。实际占用通常比公式高出 5%–15%，这个比例在高并发、短序列、视觉 token 数不整齐的场景下更接近上限。若按公式精确分配显存而不留余量，上线后高并发直接触发 OOM——这不是估算误差，而是分配策略把安全边际压到了零。容量决策应把公式结果乘以一个碎片系数再反推 batch 上限，而不是把公式当成硬预算。</p>\n<p>第三个边界在语义侧：压缩视觉 token 数确实线性削减 decode 显存与带宽，但公式对“压缩后 token 是否还承载足够信息”完全无感。若压缩比拉高而语义保真度下降，重编码、重试、多轮追问的请求比例上升，端到端容量反而变差——decode 阶段省下的显存被上游重复计算吃掉。公式只描述稳态占用的下界，不描述请求分布的变化，因此它适合做并发密度的杠杆测算，不适合单独作为压缩策略的验收标准。</p>\n<table class=\"mini\"><thead><tr><th>假设</th><th>失效表现</th><th>系统代价</th></tr></thead><tbody><tr><td>MHA/GQA，逐层独立 KV</td><td>MLA/跨层共享时等效项错</td><td>显存高估数倍，容量浪费</td></tr><tr><td>无碎片、无页表开销</td><td>实际高出 5%–15%</td><td>高并发 OOM</td></tr><tr><td>压缩不损语义</td><td>重试与重编码增加</td><td>端到端吞吐下降</td></tr></tbody></table>\n<p>规模上限也由此划定：在给定显存预算与文本长度下，视觉 token 数直接决定 batch 上限，压缩比是最直接的杠杆；但杠杆的另一端是碎片系数与语义保真度，两者任一失控，公式给出的并发数就不再可达。真正可用的边界条件是“结构匹配 + 留足碎片余量 + 压缩后请求分布不恶化”，三者同时满足时，那条线性式才是可信的容量刻度。</p>\n<h3 id=\"th-vit-kv-cache-sec-21\">二十一 · 从显存式反解批大小：把视觉 token 当作可调的自变量</h3>\n<p>容量决策的第一步不是问“这张卡能放多少”，而是问“在给定显存预算下，视觉 token 数如何决定并发上限”。把公式改写为对 <span class=\"inline-math\">\\(B_{\\text{batch}}\\)</span> 的反解形式，是工程上最常用的一步：</p>\n<div class=\"formula\">$$B_{\\max}=\\left\\lfloor \\frac{M_{\\text{budget}}\\cdot(1-\\eta)}{2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot b_{\\text{kv}}\\cdot (N_{\\text{vis}}+N_{\\text{txt}})}\\right\\rfloor$$</div>\n<p>其中 <span class=\"inline-math\">\\(\\eta\\)</span> 是留给 PagedAttention 块内碎片与页表的余量系数，按给定事实取 5%–15% 区间，高并发长序列场景应取上限。分母中 <span class=\"inline-math\">\\((N_{\\text{vis}}+N_{\\text{txt}})\\)</span> 是唯一随请求内容变化的项，因此视觉 token 压缩比直接以倒数关系放大 <span class=\"inline-math\">\\(B_{\\max}\\)</span>：视觉 token 从 <span class=\"inline-math\">\\(N_{\\text{vis}}\\)</span> 压到 <span class=\"inline-math\">\\(N_{\\text{vis}}/k\\)</span>，在文本长度可忽略时批上限近似放大 <span class=\"inline-math\">k</span> 倍；文本长度占主导时收益被稀释，这正是“压缩视觉 token 对短 prompt 收益大、对长文档收益小”的定量来源。</p>\n<p>机制上要注意分母里 <span class=\"inline-math\">\\(L\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\)</span> 是模型常量，工程上应先把它算成一个“每 token 每序列字节数”的标量，再在调度器里以乘法而非逐层累加的方式估算，避免每个请求都做一次全层遍历。代价侧：这一步只算容量，不算带宽；批大小提高会线性抬高 decode 阶段每步的 KV 读取量，单步延迟随之上升，因此 <span class=\"inline-math\">\\(B_{\\max}\\)</span> 是显存上限而非吞吐最优解。具体例子：一个 GQA 结构的解码器，若每 token 每序列 KV 字节数为数千字节量级，把视觉 token 从数百压到数十，单卡并发序列数即可从个位数抬到十位数，这是容量规划里最直接的杠杆。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-22\">二十二 · 定并行度：TP 与 PP 的分界由 KV 项而非权重项决定</h3>\n<p>并行度决策常被误当成权重切分问题，但在长视觉上下文场景下，KV cache 往往先于权重触顶。张量并行（TP）把 <span class=\"inline-math\">\\(H_{\\text{kv}}\\)</span> 与 <span class=\"inline-math\">\\(d_{\\text{head}}\\)</span> 沿头维切分，每卡 KV 占用近似按 TP 度数线性下降；流水并行（PP）把 <span class=\"inline-math\">L</span> 切分，每卡只持有自己那段层的 KV，同样线性下降，但引入流水气泡与激活传输。判断分界的伪代码思路是：</p>\n<ul>\n<li>先按单卡权重显存算出剩余可用显存 <span class=\"inline-math\">\\(M_{\\text{free}}\\)</span>；</li>\n<li>用显存式估算单卡在目标 <span class=\"inline-math\">\\(B_{\\text{batch}}\\)</span> 与目标 <span class=\"inline-math\">\\(N_{\\text{vis}}\\)</span> 下的 KV 需求；</li>\n<li>若 KV 需求超过 <span class=\"inline-math\">\\(M_{\\text{free}}\\)</span>，优先增大 TP 度数（KV 与权重同时被切，通信在 NVLink 域内可承受），再考虑 PP；</li>\n<li>若模型层数少而 KV 头数多，TP 的切分粒度更细、负载更均衡；反之层数多、单层 KV 小，PP 更省通信。</li>\n</ul>\n<p>代价判断：TP 每层都要做 all-reduce，decode 阶段每步一次，序列越长、批越大，集合通信量随 <span class=\"inline-math\">\\(B_{\\text{batch}}\\)</span> 线性增长；PP 的代价是流水填充与排空，在 decode 这种每步只出一个 token 的形态下气泡占比高。因此在 NVL72 这类 NVLink 5 高带宽域内，TP 通常是首选，把 PP 留给跨节点或层数极深的模型。具体例子：当视觉 token 使单卡 KV 超出预算而权重仍宽裕时，加 TP 度数能同时缓解两者，是最省事的一步；若权重已接近满载，则只能靠压缩视觉 token 或降批，此时并行度不再是自由变量。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-23\">二十三 · 定 KV 预算：把预算拆成 token 配额而非字节配额</h3>\n<p>更稳的做法是把显存预算翻译成“token 配额”，让调度器以 token 为单位做准入控制。定义单序列每 token 的 KV 字节数：</p>\n<div class=\"formula\">$$c_{\\text{tok}}=2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot b_{\\text{kv}}$$</div>\n<p>则总 token 配额为 <span class=\"inline-math\">\\(T_{\\max}=\\lfloor M_{\\text{budget}}\\cdot(1-\\eta)/c_{\\text{tok}}\\rfloor\\)</span>，调度器只需维护“已占 token 数 + 新请求 token 数 ≤ <span class=\"inline-math\">\\(T_{\\max}\\)</span>”这一条不变式。这样做的好处是把视觉与文本统一计价：一个视觉 token 与一个文本 token 在 decode 阶段等价，压缩视觉 token 就是直接释放配额。机制上要配合分页分配，按块粒度（而非按序列）扣减配额，块内碎片由 <span class=\"inline-math\">\\(\\eta\\)</span> 吸收。</p>\n<p>精度维度上，<span class=\"inline-math\">\\(b_{\\text{kv}}\\)</span> 从 FP16 的 2 降到 FP8 的 1，配额直接翻倍，这是不改变模型结构就能拿到的容量增益；但量化误差会沿层传播，需与量化误差上界那部分对照评估，不能只看容量。代价侧：FP8 KV 降低读取带宽压力，decode 每步的 KV 读取量减半，单步延迟改善，但反量化开销与精度损失需实测。具体例子：同一张卡、同一模型，仅把 KV 从 FP16 换到 FP8，token 配额翻倍，若视觉 token 占序列大半，等效并发序列数也接近翻倍；若文本 token 占主导，收益按比例缩小。这就是为什么容量规划必须先测出 <span class=\"inline-math\">\\(N_{\\text{vis}}\\)</span> 与 <span class=\"inline-math\">\\(N_{\\text{txt}}\\)</span> 的实际分布，而不是拍一个平均值。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-24\">二十四 · 定 SLO：把首 token 与每 token 延迟拆到 KV 带宽上</h3>\n<p>SLO 决策要把延迟目标翻译成带宽约束。decode 阶段每生成一个 token，需读取全部历史 KV，单步 KV 读取量为 <span class=\"inline-math\">\\(c_{\\text{tok}}\\cdot(N_{\\text{vis}}+N_{\\text{txt}})\\)</span> 乘以批内并发序列数，因此每 token 延迟的下界近似为：</p>\n<div class=\"formula\">$$t_{\\text{step}}\\gtrsim \\frac{c_{\\text{tok}}\\cdot \\bar{N}\\cdot B_{\\text{active}}}{BW_{\\text{eff}}}$$</div>\n<p>其中 <span class=\"inline-math\">\\(\\bar{N}\\)</span> 为平均序列 token 数，<span class=\"inline-math\">\\(BW_{\\text{eff}}\\)</span> 为有效 HBM 带宽。这条式子说明：在带宽受限区，吞吐与延迟不可兼得，提高 <span class=\"inline-math\">\\(B_{\\text{active}}\\)</span> 会线性恶化每 token 延迟。定 SLO 的正确顺序是先用延迟目标反解允许的 <span class=\"inline-math\">\\(B_{\\text{active}}\\)</span>，再用显存式检查该批大小是否放得下；两者取小。若显存允许的批大于延迟允许的批，系统是带宽受限，压缩视觉 token 或降 KV 精度能同时改善两者；若显存允许的批更小，系统是容量受限，此时压缩视觉 token 是唯一不牺牲延迟的扩容手段。</p>\n<p>首 token 延迟（TTFT）由预填决定，视觉 token 在预填阶段要过视觉编码器并写入 KV，其代价已在预填/解码分离时延那部分展开，这里只强调一点：预填写入的 KV 就是 decode 要读的那份，因此 <span class=\"inline-math\">\\(N_{\\text{vis}}\\)</span> 同时进入 TTFT 与 TPOT 两条路径，压缩它是对两个 SLO 的同时改善。具体例子：当 TPOT 目标固定而实测超限时，先查 <span class=\"inline-math\">\\(B_{\\text{active}}\\)</span> 是否超过带宽反解值，若是则降批而非加卡；若降批后 TTFT 仍超限，则问题在预填侧，需回到视觉编码器与预填调度，而不是继续动 KV 预算。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-25\">二十五 · 算例：一次完整的容量反推</h3>\n<p>设某 GQA 解码器层数与 KV 头维度固定，单序列每 token KV 字节数 <span class=\"inline-math\">\\(c_{\\text{tok}}\\)</span> 已测得；显存预算扣除权重与激活后剩 <span class=\"inline-math\">\\(M_{\\text{budget}}\\)</span>，取 <span class=\"inline-math\">\\(\\eta=10\\%\\)</span>。请求画像为视觉 token 数百、文本 token 数十的量级。按第三节得 token 配额 <span class=\"inline-math\">\\(T_{\\max}\\)</span>，按第一节得批上限 <span class=\"inline-math\">\\(B_{\\max}=T_{\\max}/\\bar{N}\\)</span>。再按第四节用带宽反解延迟允许的批 <span class=\"inline-math\">\\(B_{\\text{slo}}\\)</span>，最终并发取 <span class=\"inline-math\">\\(\\min(B_{\\max},B_{\\text{slo}})\\)</span>。</p>\n<table class=\"mini\"><thead><tr><th>决策量</th><th>由什么决定</th><th>调整杠杆</th><th>代价</th></tr></thead><tbody>\n<tr><td>批大小上限</td><td>显存式反解，分母含 <span class=\"inline-math\">\\(N_{\\text{vis}}+N_{\\text{txt}}\\)</span></td><td>压缩视觉 token、降 <span class=\"inline-math\">\\(b_{\\text{kv}}\\)</span></td><td>压缩可能损语义保真度，量化损精度</td></tr>\n<tr><td>并行度</td><td>KV 项与权重项谁先触顶</td><td>TP 优先，PP 备选</td><td>TP 集合通信随批线性增长</td></tr>\n<tr><td>KV 预算</td><td>token 配额不变式</td><td>FP8 KV、分页块粒度</td><td>碎片余量 5%–15% 必须预留</td></tr>\n<tr><td>SLO 可达性</td><td>带宽反解的 <span class=\"inline-math\">\\(B_{\\text{slo}}\\)</span></td><td>降批、压缩视觉 token</td><td>降批直接损失吞吐</td></tr>\n</tbody></table>\n<p>算例的工程结论是：先算 <span class=\"inline-math\">\\(c_{\\text{tok}}\\)</span> 这个标量并固化到调度器，再以 token 配额做准入，最后用带宽反解校验 SLO。三个数一旦对齐，容量决策就从“试出来”变成“算出来”。需要警惕的失效模式有三条：按公式精确分配而不留 <span class=\"inline-math\">\\(\\eta\\)</span>，高并发下直接 OOM；在 MLA 或跨层共享 KV 的结构上沿用 GQA 的 <span class=\"inline-math\">\\(H_{\\text{kv}}\\cdot d_{\\text{head}}\\)</span>，把压缩潜向量当完整 KV，容量被高估数倍而浪费；只压 token 数不查语义保真度，decode 显存降了但重编码与重试请求增加，端到端容量反而变差。最后一条尤其隐蔽——它不会在显存曲线上暴露，只会在地理上表现为有效吞吐下降，因此容量评估必须把重试率作为与 <span class=\"inline-math\">\\(B_{\\max}\\)</span> 并列的输出指标。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-26\">二十六 · 容量反推的三个杠杆与两个陷阱</h3>\n<p>把公式倒过来用，才是它在容量决策中的真正位置。给定单卡可用于 KV 的显存预算 <span class=\"inline-math\">\\(M_{\\text{budget}}\\)</span>（总 HBM 减去权重、激活峰值、通信缓冲与框架预留），并发序列数上限直接解出：<span class=\"inline-math\">\\(B_{\\max}=\\lfloor M_{\\text{budget}}/(2LH_{\\text{kv}}d_{\\text{head}}(N_{\\text{vis}}+N_{\\text{txt}})b_{\\text{kv}})\\rfloor\\)</span>。这个式子里只有三个可动杠杆：<span class=\"inline-math\">\\(N_{\\text{vis}}\\)</span>（视觉 token 压缩比）、<span class=\"inline-math\">\\(b_{\\text{kv}}\\)</span>（FP16 降到 FP8 使分母减半）、<span class=\"inline-math\">\\(H_{\\text{kv}}\\)</span>（GQA 分组数，属模型结构不可在线更改）。因此工程上真正能调的只有前两个，而视觉 token 压缩的收益是线性的、无精度协议风险的，通常优先于 KV 量化——后者要在数值稳定性上付出代价，前者只付出语义保真度的代价。以 FP8 KV 为例，分母减半意味着同等显存下并发翻倍，但这是以每元素 1 字节的量化误差换来的；而把 <span class=\"inline-math\">\\(N_{\\text{vis}}\\)</span> 从 576 压到 144，分母中的视觉项缩为四分之一，若文本项为 512，则总 token 从 1088 降到 656，并发上限提升约 66%，且 decode 阶段每步读取的 KV 带宽同比例下降，直接反映为 TPOT 改善。</p>\n<p>定并行度时公式给出的是另一条约束。张量并行把 <span class=\"inline-math\">\\(H_{\\text{kv}}\\)</span> 按卡数切分，每卡 KV 占用近似为 <span class=\"inline-math\">\\(M_{\\text{KV}}/\\text{TP}\\)</span>，但注意力计算中的 all-reduce 与 KV 读取的带宽开销并不随 TP 线性下降；当 <span class=\"inline-math\">\\(N_{\\text{vis}}\\)</span> 很大时，单序列 KV 已经吃掉可观显存，TP 增大虽降低每卡占用却抬高了通信占比，收益递减点出现在 KV 带宽而非容量成为瓶颈之处。分离式预填/解码部署下这条式子的用法更细：预填节点不长期持有 KV，其瓶颈是算力与视觉编码器吞吐；解码节点才是 <span class=\"inline-math\">\\(B_{\\max}\\)</span> 的约束方，KV 预算应按解码池单独核算，并通过 KV 传输链路（NIXL 一类）把预填产生的块搬过去，此时页表与块元数据也要跨节点保持一致，否则碎片率上升。</p>\n<p>定 SLO 时把公式与延迟模型联立：decode 每步耗时近似由权重读取、KV 读取与集合通信三项构成，其中 KV 读取项正比于 <span class=\"inline-math\">\\(2LH_{\\text{kv}}d_{\\text{head}}(N_{\\text{vis}}+N_{\\text{txt}})b_{\\text{kv}}B_{\\text{batch}}\\)</span>，即与显存式同构。于是 TTFT 由预填的视觉 token 数决定（视觉编码器前向加 LLM 预填），TPOT 由上述带宽项除以有效 HBM 带宽决定。给定 TPOT 上限即可反解 <span class=\"inline-math\">\\(B_{\\text{batch}}\\)</span> 的可行区间，再与显存上限取交集，得到真正的容量窗口。若交集为空，说明该 SLO 下视觉 token 数或 KV 精度必须调整，而不是靠加卡解决。</p>\n<table class=\"mini\"><thead><tr><th>决策项</th><th>公式中的对应量</th><th>主要代价</th><th>失效信号</th></tr></thead><tbody><tr><td>批大小上限</td><td><span class=\"inline-math\">\\(B_{\\max}\\)</span> 由 <span class=\"inline-math\">\\(M_{\\text{budget}}\\)</span> 反解</td><td>碎片余量不足触发 OOM</td><td>高并发下显存爬升超出预算 5%–15%</td></tr><tr><td>并行度</td><td><span class=\"inline-math\">\\(H_{\\text{kv}}/\\text{TP}\\)</span> 分摊</td><td>通信占比上升、TPOT 不降反升</td><td>加卡后吞吐不增</td></tr><tr><td>KV 精度</td><td><span class=\"inline-math\">\\(b_{\\text{kv}}\\)</span> 2→1</td><td>量化误差影响长上下文一致性</td><td>重试率上升</td></tr><tr><td>视觉压缩比</td><td><span class=\"inline-math\">\\(N_{\\text{vis}}\\)</span></td><td>语义保真度下降、重编码请求增多</td><td>端到端容量反而变差</td></tr></tbody></table>\n<p>两个陷阱必须写进容量评审清单。其一，按公式精确分配而不预留 PagedAttention 块内碎片与页表开销，实际占用高出 5%–15%，高并发下直接 OOM——正确做法是把 <span class=\"inline-math\">\\(M_{\\text{budget}}\\)</span> 先打九折再代入。其二，在 MLA 或跨层共享 KV 的结构上沿用 GQA 的 <span class=\"inline-math\">\\(H_{\\text{kv}}d_{\\text{head}}\\)</span> 估算，把压缩潜向量当成完整 KV，显存需求被高估数倍，白白浪费容量、压低并发。还有一类隐性失效不在公式里：只压缩 <span class=\"inline-math\">\\(N_{\\text{vis}}\\)</span> 而不校验压缩后 token 的语义保真度，decode 显存确实下降，但重编码或重试请求增加，端到端容量反而变差——这说明容量决策必须以有效请求吞吐为终局指标，而非以 <span class=\"inline-math\">\\(B_{\\max}\\)</span> 为终局指标。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-27\">二十七 · 容量反推的边界：什么时候这条式子会骗你</h3>\n<p>把式子反过来用，才是它在工程上真正的位置：给定单卡可用于 KV 的显存预算 <span class=\"inline-math\">M_budget</span>，先扣掉权重、激活与通信缓冲，剩下的才是 KV 池，于是并发上限直接是 <div class=\"formula\">$$B_{\\text{batch}}^{\\max}=\\left\\lfloor \\frac{M_{\\text{budget}}}{2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot (N_{\\text{vis}}+N_{\\text{txt}})\\cdot b_{\\text{kv}}} \\right\\rfloor$$</div> 这个式子的价值在于它把“视觉 token 压缩比”与“并发密度”绑成一条直线：视觉 token 从 <span class=\"inline-math\">\\(N_{\\text{vis}}\\)</span> 压到 <span class=\"inline-math\">\\(N_{\\text{vis}}/k\\)</span>，在文本长度可忽略时批上限近似放大 <span class=\"inline-math\">k</span> 倍；若文本 token 占主导，放大倍数退化到 <span class=\"inline-math\">\\((N_{\\text{vis}}+N_{\\text{txt}})/(N_{\\text{vis}}/k+N_{\\text{txt}})\\)</span>，收益被文本项吃掉——这正是多模态长文档场景里压缩视觉 token 却换不来吞吐的根因。</p>\n<p>边界条件必须写进容量表而不是脚注。第一，式子只对 MHA/GQA 且层数与 KV 头数固定的结构成立；MLA 或跨层共享 KV 的模型上，等效项应替换为压缩后的潜向量维度，若仍套用 <span class=\"inline-math\">\\(H_{\\text{kv}}\\cdot d_{\\text{head}}\\)</span>，显存需求会被高估数倍，容量规划直接作废。第二，式子不含 PagedAttention 的块内碎片与页表开销，实际占用通常高出 5%–15%，因此预算侧要乘一个 <span class=\"inline-math\">\\(1/(1-\\delta)\\)</span> 的安全系数（<span class=\"inline-math\">\\(\\delta\\)</span> 取 5%–15%），而不是把 <span class=\"inline-math\">\\(M_{\\text{budget}}\\)</span> 精确切分给 KV 池。第三，<span class=\"inline-math\">\\(b_{\\text{kv}}\\)</span> 从 FP16 降到 FP8 只把系数从 2 变 1，对批上限是线性翻倍，但对数值稳定性与长上下文精度的影响不在式内，需单独做 SLO 侧的精度回归。</p>\n<p>算例：设某解码器 <span class=\"inline-math\">L=80</span>、GQA 下 <span class=\"inline-math\">\\(H_{\\text{kv}}=8\\)</span>、<span class=\"inline-math\">\\(d_{\\text{head}}=128\\)</span>，则每层每 token 的 KV 为 <span class=\"inline-math\">\\(2\\times 8\\times 128\\times b_{\\text{kv}}\\)</span> 字节，FP16 下即 4 KiB/token；单序列 <span class=\"inline-math\">\\(N_{\\text{vis}}=2048\\)</span>、<span class=\"inline-math\">\\(N_{\\text{txt}}=1024\\)</span> 时，每序列 KV 约 80×4 KiB×3072 ≈ 960 MiB。若单卡 KV 池按 40 GiB 规划并留 10% 碎片余量，则 <span class=\"inline-math\">\\(B_{\\text{batch}}^{\\max}\\approx 38\\)</span> 量级；把视觉 token 压到 512，每序列降到约 480 MiB，批上限翻到约 76——这就是压缩比直接换成并发密度的算术。反过来，若把 <span class=\"inline-math\">\\(b_{\\text{kv}}\\)</span> 切到 FP8，批上限再翻一倍，但此时必须核对 decode 带宽是否已成为新瓶颈：KV 读取量同样正比于批大小与 token 数，显存省下来的容量若不能转化为 SM 上的有效算力，扩容只是把 OOM 换成低利用率。</p>\n<p>失效模式集中在三处：按式子精确分配而不留碎片余量，高并发下直接 OOM；在 MLA 结构上沿用 GQA 维度估算，容量被虚报；以及只压 token 数不验语义保真度——decode 显存降了，但重编码与重试请求上升，端到端有效容量反而变差。因此这条式子只应作为容量决策的上界估计与压缩收益的换算器，最终批大小与并行度要由实测的 KV 池水位、页表开销与重试率共同收敛。</p>\n<h3 id=\"th-vit-kv-cache-sec-28\">二十八 · 误用一：把理论式当分配式，不留碎片余量</h3>\n<p>最常见也最致命的误用，是把 <span class=\"formula\">$$M_{\\text{KV}}$$</span> 的计算结果直接当作可分配的显存预算。公式本身是对的，但它描述的是“有效载荷”，不是“实际占用”。PagedAttention 把 KV cache 切成固定大小的块，块内最后一个未填满的块仍占整块显存；每个序列还要维护页表（block table），并发序列越多，页表项与元数据开销越大。工程上的正确做法是给公式结果乘一个安全系数，把 5%–15% 的碎片与页表开销显式预留出来，再反推 <span class=\"formula\">$$B_{\\text{batch}}$$</span>。</p>\n<p>识别方法很直接：在压测中把并发逐步抬到理论 batch 上限，观察 <span class=\"formula\">$$M_{\\text{KV}}$$</span> 实际水位与理论值的偏离。如果实际占用稳定高出理论值一个固定比例，且该比例随并发上升而扩大，那就是块内碎片与页表在起作用，而不是计算错误。此时不应去改公式，而应下调容量规划中的可用 batch 数。</p>\n<p>后果是延迟与吞吐同时恶化：OOM 触发后，调度器要么拒绝新请求（SLO 违约），要么抢占（preemption）已有序列、把 KV 换出到主机内存再换回。换出一次意味着一次 PCIe 往返，decode 阶段的单步延迟被拉长到不可接受的程度，而换入换出本身又消耗带宽。高并发场景下，这种抖动比直接拒绝更隐蔽——吞吐数字看起来还在，尾延迟已经崩了。</p>\n<p>具体例子：一个视觉 token 数较大的 VLM 服务，按公式算出单卡可容纳 <span class=\"formula\">$$B_{\\text{batch}}$$</span> 条序列，上线后并发达到该值的九成即开始周期性 OOM。把规划 batch 下调到理论值的 85% 左右，并把页表开销计入每条序列的固定成本，抖动消失。这不是公式错了，是公式的适用边界被越过了。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-29\">二十九 · 误用二：在 MLA 结构上沿用 GQA 的头维度</h3>\n<p>第二个高频误用出现在结构假设上。公式里的 <span class=\"formula\">$$2\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot b_{\\text{kv}}$$</span> 对应的是 MHA/GQA：每个 KV 头存完整的 K 与 V 向量。MLA（多头潜注意力）不存完整 KV，而是缓存压缩后的潜向量（latent），跨层共享 KV 的结构则进一步把多层压成一份。此时若仍用 GQA 的 <span class=\"formula\">$$H_{\\text{kv}}\\cdot d_{\\text{head}}$$</span> 去估算，等于把压缩潜向量当成完整 KV，显存需求被高估数倍。</p>\n<p>高估的代价不是 OOM，而是容量浪费——这同样是一种工程损失，只是方向相反。运维看到“显存还很宽裕”，于是不敢提高并发密度，单卡吞吐被人为压低；或者反过来，容量规划阶段按高估值采购，集群规模超出实际需要。两种结果都是把本可以承载的请求推给了更多机器。</p>\n<p>识别方法：核对模型的 config 中 KV 相关字段。若存在 latent 维度、KV 跨层共享标记或压缩比参数，就不能直接套用 <span class=\"formula\">$$H_{\\text{kv}}\\cdot d_{\\text{head}}$$</span>，而应把等效项替换为压缩后的潜向量维度，并确认该维度是否随层数变化。一个可靠的交叉验证是：用实测的单序列 KV 占用除以层数与 token 数，反推每层每 token 的字节数，再与 config 对照。若实测值显著小于 GQA 估算值，说明结构不是 GQA。</p>\n<p>具体例子：某服务在 MLA 类模型上按 GQA 公式规划，算出单卡 batch 上限很低，实际压测却发现显存远未用满。把等效项换成潜向量维度后重算，可承载并发显著提升，decode 吞吐随之改善。误用的代价在这里体现为“少赚”，而不是“亏本”，但同样是容量决策失误。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-30\">三十 · 误用三：只压 token 数，不验语义保真</h3>\n<p>第三个误用最隐蔽：把视觉 token 压缩当成纯显存优化，只盯着 <span class=\"formula\">$$N_{\\text{vis}}$$</span> 下降带来的线性收益，却不检查压缩后 token 的语义保真度。公式确实表明显存与带宽正比于视觉 token 数，压缩即线性削减 decode 压力；但压缩是有损的，被丢掉的信息不会因为显存省下来就自动补回。</p>\n<p>后果链条是这样的：视觉 token 减少 → decode 显存与带宽下降 → 单卡可容纳 batch 上升 → 但模型对图像细节的判别力下降 → 需要重编码（re-encode）或重试（retry）的请求比例上升。每一次重试都是一次完整的预填加解码，其代价远高于省下来的那点 KV 显存。端到端容量反而变差：名义并发上去了，有效吞吐下来了，而且尾延迟被重试请求拉长。</p>\n<p>识别方法不是看显存水位，而是看业务侧指标：单位请求的平均解码步数、重试率、以及需要人工介入的比例。若压缩比例提高后，这些指标同步恶化，说明压缩已经越过了保真度边界。另一个信号是同一请求在不同压缩配置下的输出不一致率——不一致率高，意味着压缩引入了不稳定的语义漂移，而不是稳定的信息损失。</p>\n<p>工程判断上，压缩比应当由“有效容量”而非“名义容量”决定。有效容量可以写成名义 batch 除以（1 + 重试率 × 单次重试的相对代价）。当重试率的上升速度超过 batch 的提升速度时，继续压缩就是负收益。这个判据不需要精确数字，只需要在压测中同时记录 batch 上限与重试率两条曲线，看它们的交叉点。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-31\">三十一 · 反例：一次“精确分配”的上线事故</h3>\n<p>构造一个反例把三条误用串起来。某多模态推理服务在容量规划时，用 <span class=\"formula\">$$M_{\\text{KV}}=2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot (N_{\\text{vis}}+N_{\\text{txt}})\\cdot b_{\\text{kv}}\\cdot B_{\\text{batch}}$$</span> 精确反解 <span class=\"formula\">$$B_{\\text{batch}}$$</span>，把算出的值直接写进调度器的并发上限，未留任何余量；同时该模型实际采用跨层共享 KV，但规划时沿用了 GQA 的头维度，导致估算值偏高；为了“补偿”这个偏高的估算，团队又激进地压缩了视觉 token 数，把 <span class=\"formula\">$$N_{\\text{vis}}$$</span> 砍到很低，且未做保真度验证。</p>\n<p>上线后的表现是三重叠加：并发上限设得比真实可承载值高（因为没留碎片余量），调度器持续把并发推到 OOM 边缘，触发抢占与换出，decode 尾延迟剧烈抖动；与此同时，被压缩的视觉 token 让模型在细节类请求上频繁给出错误答案，重试率上升，重试请求又进一步推高并发压力；而规划阶段因结构假设错误而高估的显存需求，让团队误以为“还有余量”，迟迟没有扩容。三个方向的误差没有相互抵消，而是同向叠加。</p>\n<p>这个反例的教训不在于某一个公式用错，而在于三条误用共享同一个根源：把公式当成精确的分配依据，而不是带边界条件的估算工具。公式的适用边界写明了两件事——结构假设（MHA/GQA、层数与 KV 头数固定）和开销假设（未计 PagedAttention 碎片与页表，实际高出 5%–15%）。越过任一条边界，公式的输出就不再是可分配的数字。</p>\n<p>可操作的识别流程是三步：第一步，核对结构，确认等效项是 <span class=\"formula\">$$H_{\\text{kv}}\\cdot d_{\\text{head}}$$</span> 还是压缩潜向量维度；第二步，给结果乘安全系数并显式计入每条序列的页表固定成本，再反推 batch；第三步，在压测中同时监控显存水位、重试率与尾延迟，三者任一恶化就回退压缩比或下调并发。把这三步固化成上线前的检查项，比事后调参更能避免同类事故。</p>\n\n<h3 id=\"th-vit-kv-cache-sec-32\">三十二 · 误用与反例：从“算得准”到“跑得稳”之间的三处断点</h3>\n\n<p>第一个断点是把公式当成分配契约。工程上最常见的动作是：给定单卡显存预算，反解出 <span class=\"formula-inline\">\\(B_{\\text{batch}}\\)</span> 的上限，然后直接把并发调度器配到这个上限。问题在于公式只描述“稳态驻留”，不描述“瞬时峰值”——PagedAttention 的块内碎片、页表本身、以及请求在 prefill 与 decode 之间切换时新旧块并存的窗口，都不在式子里。实际占用通常高出 5%–15%，这个比例在低并发时只是余量，在高并发时就是 OOM 的触发点。识别方法很直接：把调度器的并发上限按公式值配置，然后观察长视觉序列（高 <span class=\"formula-inline\">\\(N_{\\text{vis}}\\)</span>）与长文本混跑时的显存水位曲线，若峰值贴近预算线而稳态留有明显空隙，说明峰值项被漏算了。正确做法是把 5%–15% 作为硬性折减系数写进容量模型，而不是当作“安全边际”事后追加。</p>\n\n<p>第二个断点是结构误配：在 MLA 或跨层共享 KV 的模型上沿用 GQA 的 <span class=\"formula-inline\">\\(H_{\\text{kv}}\\cdot d_{\\text{head}}\\)</span> 估算。此时每层每 token 的真实驻留量是压缩后的潜向量维度，而非完整 K/V 两份头维度；照搬原式会把显存需求高估数倍，直接后果是容量被白白浪费——本该跑满的卡被保守配置压到半载，吞吐损失比 OOM 更隐蔽，因为它不报错。识别信号是“理论算出的并发上限远低于实测能稳定跑到的并发数”，且差距随层数增大而扩大。修正方式是把等效项替换为潜向量维度，并重新校准系数 2 是否仍然成立（压缩表示通常不再区分 K 与 V 两份）。</p>\n\n<div class=\"formula\">$$\\text{有效并发}\\ B_{\\max}\\approx\\frac{M_{\\text{budget}}\\cdot(1-\\delta)}{2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot b_{\\text{kv}}\\cdot \\bar{N}},\\quad \\delta\\in[0.05,\\,0.15]$$</div>\n\n<p>第三个断点，也是最容易被忽略的反例：只压 <span class=\"formula-inline\">\\(N_{\\text{vis}}\\)</span>，不校验压缩后 token 的语义保真度。设想一个多图文档问答服务，把每张图的视觉 token 从数百压到数十，decode 阶段显存与带宽按线性关系下降，单卡并发密度上升；但压缩后的视觉表示丢失了细粒度版面信息，模型在需要精确引用表格单元格或小字号标注时答错，触发上游重试与重编码。重试请求意味着同一份视觉输入被再次 prefill、再次占用 KV 块，端到端容量反而变差——账面上 decode 省下的显存，被重试路径的 prefill 峰值吃掉。识别这种失效不能只看显存曲线，要看“每成功请求的平均 KV 占用”与“重试率”的乘积：当压缩比提高而该乘积不降反升，压缩已经越过了语义边界。工程判断是给压缩比设一个由任务形态决定的上限，并把重试率纳入容量回归测试，而不是把压缩比当作可以单调调大的旋钮。</p>\n\n<table class=\"mini\"><thead><tr><th>误用</th><th>后果</th><th>识别信号</th></tr></thead><tbody><tr><td>按公式精确分配、不留碎片余量</td><td>高并发下 OOM</td><td>峰值贴近预算线、稳态有空隙</td></tr><tr><td>MLA 上沿用 GQA 头维度</td><td>显存高估数倍、容量浪费</td><td>理论并发上限远低于实测稳定值</td></tr><tr><td>只压 token 数、不验保真度</td><td>重试增加、端到端容量变差</td><td>压缩比升而“占用×重试率”不降</td></tr></tbody></table>\n\n<h3 id=\"th-vit-kv-cache-sec-33\">三十三 · 误用与反例：把线性式当精确预算的三个坑</h3>\n<p>最常见的误用是把 <span class=\"formula\">$$M_{\\text{KV}}=2\\cdot L\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot (N_{\\text{vis}}+N_{\\text{txt}})\\cdot b_{\\text{kv}}\\cdot B_{\\text{batch}}$$</span> 当成可直接写进容量配置文件的精确值。该式只描述“每层每 token 的 KV 存储量 = <span class=\"formula\">$$2\\cdot H_{\\text{kv}}\\cdot d_{\\text{head}}\\cdot b_{\\text{kv}}$$</span>”乘层数、总 token 数与并发批大小这一条线性链，并不包含 PagedAttention 的块内碎片与页表开销。按公式把显存预算切到最后一字节，块尾未填满的槽位与页表元数据会额外吃掉 5%–15%，高并发下直接触发 OOM。识别方法很直接：上线前用实测峰值显存除以公式理论值，若比值稳定落在 1.05–1.15 区间，说明预算里必须显式留出这条余量，而不是靠调度器在 OOM 后回退。</p>\n<p>第二个坑出现在结构假设上。公式的适用边界是 MHA/GQA 且 KV 头数与层数固定；一旦模型采用 MLA 或跨层共享 KV，每 token 的等效存储项应替换为压缩后的潜向量维度，而不是继续沿用 <span class=\"formula\">$$H_{\\text{kv}}\\cdot d_{\\text{head}}$$</span>。在 MLA 模型上照搬 GQA 口径，会把压缩潜向量当成完整 KV，显存需求被高估数倍，容量规划因此过度保守，白白压低并发密度。识别信号是：按公式反推的单卡并发上限远低于实测可跑值，且差距随层数放大——这时应先核对注意力结构，再决定是否替换等效项。</p>\n<p>第三个坑更隐蔽：只盯 <span class=\"formula\">$$N_{\\text{vis}}$$</span> 的压缩比，不检查压缩后视觉 token 的语义保真度。decode 阶段显存与带宽确实随视觉 token 数线性下降，但重编码或重试请求会随之增加，端到端容量反而变差。反例：某服务把每张图的视觉 token 从数百压到几十以抬高 batch 上限，公式算出的并发序列数翻倍，实际却因答案质量回退触发客户端重试，有效吞吐不升反降。判断准则应把重试率乘进有效并发：<span class=\"formula\">$$B_{\\text{eff}}=B_{\\text{batch}}\\cdot(1-r_{\\text{retry}})$$</span>，其中 <span class=\"formula\">$$r_{\\text{retry}}$$</span> 为重试比例；只有当压缩带来的 <span class=\"formula\">$$B_{\\text{batch}}$$</span> 增益显著超过重试折损时，视觉 token 压缩才真正转化为容量。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>后果</th><th>识别信号</th></tr></thead><tbody><tr><td>不留碎片与页表余量</td><td>高并发 OOM</td><td>实测/理论显存比 1.05–1.15</td></tr><tr><td>MLA 上沿用 GQA 头维度</td><td>显存高估数倍、并发被压低</td><td>反推并发上限远低于实测</td></tr><tr><td>只压 token 数不看保真度</td><td>重试增加、有效吞吐下降</td><td>重试率随压缩比上升</td></tr></tbody></table>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>L</td><td>LLM 解码器层数</td></tr><tr><td>H_{\\text{kv}}</td><td>KV 头数（GQA 下远小于 Q 头数）</td></tr><tr><td>d_{\\text{head}}</td><td>单头维度</td></tr><tr><td>N_{\\text{vis}},\\ N_{\\text{txt}}</td><td>视觉 token 数与文本 token 数</td></tr><tr><td>b_{\\text{kv}}</td><td>KV 每元素字节数（FP16=2，FP8=1）</td></tr><tr><td>B_{\\text{batch}}</td><td>并发序列数</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-vit-kv-cache · 共 5 个片段</p>\n"},{"id":"th-multimodal-batch-latency","title":"多模态批调度时延模型","direction":"dir-multimodal-quantization","prereq":[],"plain":"多模态请求的端到端时延由视觉预填、LLM 预填、逐 token 解码三段串联再加排队构成；视觉 token 数与输出长度共同决定哪一段成为瓶颈，批调度要在视觉预填与解码之间分配 SM。","definition":"多模态请求的端到端时延由视觉预填、LLM 预填、逐 token 解码三段串联再加排队构成；视觉 token 数与输出长度共同决定哪一段成为瓶颈，批调度要在视觉预填与解码之间分配 SM。","formula":"$$T_{\\text{e2e}}=\\underbrace{\\frac{N_{\\text{vis}}\\cdot c_{\\text{vis}}}{\\kappa_{\\text{vis}} B}}_{\\text{视觉预填}}+\\underbrace{\\frac{(N_{\\text{vis}}+N_{\\text{txt}})\\cdot c_{\\text{pre}}}{\\kappa_{\\text{pre}} B}}_{\\text{LLM 预填}}+\\underbrace{N_{\\text{out}}\\cdot\\frac{c_{\\text{dec}}(B)}{\\kappa_{\\text{dec}} B}}_{\\text{解码}}+W_q$$","variables":[{"sym":"N_{\\text{vis}}","meaning":"每请求视觉 token 数（含 patch 合并后）"},{"sym":"N_{\\text{out}}","meaning":"生成 token 数"},{"sym":"B","meaning":"并发批大小"},{"sym":"\\kappa_{\\text{vis}},\\ \\kappa_{\\text{pre}},\\ \\kappa_{\\text{dec}}","meaning":"各阶段单位 token 的吞吐系数（token/s per SM）"},{"sym":"W_q","meaning":"排队等待时间，由到达率与服务率决定"}],"derivation":"推导关键一步是把三段服务时间分别写成 token 数除以（吞吐系数乘批大小），再与排队项相加；$$c_{\\text{dec}}(B)$$ 显式依赖批大小，因为解码阶段 KV 带宽竞争随 batch 增大而加剧。","example":"在容量决策中，该模型用于在视觉预填与解码之间分配 SM：当 $$N_{\\text{vis}}$$ 大而 $$N_{\\text{out}}$$ 小时应倾斜视觉预填资源，反之倾斜解码，从而在给定 SLO 下最大化吞吐。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["假设各阶段串行不重叠；实际分离式部署中视觉预填可与解码并行，需用关键路径而非简单求和","c_dec(B) 随 batch 增大因 KV 带宽竞争而超线性上升，线性模型在 B 超过 SM 饱和点后低估时延"],"system_note":"常见误用是把三段时延简单相加而忽略分离式部署的并行重叠，高估时延并过度扩容；另一误用是在大 batch 下仍用线性 $$c_{\\text{dec}}(B)$$，低估解码段的 KV 带宽竞争，SLO 违约。","papers":["paper-an-image-is-worth-16x16-words-transf-2020"],"facts":["直觉上，多模态请求端到端时延由视觉预填、LLM 预填、逐 token 解码三段串联再加排队构成，视觉 token 数与输出长度共同决定哪一段成为瓶颈。","公式中 $$N_{\\text{vis}}$$ 为每请求视觉 token 数（含 patch 合并后），$$N_{\\text{out}}$$ 为生成 token 数，$$B$$ 为并发批大小，$$\\kappa_{\\text{vis}},\\kappa_{\\text{pre}},\\kappa_{\\text{dec}}$$ 为各阶段单位 token 吞吐系数（token/s per SM），$$W_q$$ 为排队等待时间。","推导关键一步是把三段服务时间分别写成 token 数除以（吞吐系数乘批大小），再与排队项相加；$$c_{\\text{dec}}(B)$$ 显式依赖批大小，因为解码阶段 KV 带宽竞争随 batch 增大而加剧。","适用边界是各阶段串行不重叠；分离式部署中视觉预填可与解码并行，需用关键路径而非简单求和；$$c_{\\text{dec}}(B)$$ 随 batch 增大超线性上升，线性模型在 B 超过 SM 饱和点后低估时延。","在容量决策中，该模型用于在视觉预填与解码之间分配 SM：当 $$N_{\\text{vis}}$$ 大而 $$N_{\\text{out}}$$ 小时应倾斜视觉预填资源，反之倾斜解码，从而在给定 SLO 下最大化吞吐。","常见误用是把三段时延简单相加而忽略分离式部署的并行重叠，高估时延并过度扩容；另一误用是在大 batch 下仍用线性 $$c_{\\text{dec}}(B)$$，低估解码段的 KV 带宽竞争，SLO 违约。"],"anchors":["未给出"],"pitfalls":["在视觉预填与解码分离部署时仍按串行求和估算时延，忽略关键路径重叠，容量规划过度保守，GPU 利用率偏低。","batch 超过 SM 饱和点后仍用线性解码吞吐系数，低估 KV 带宽竞争导致的超线性时延增长，线上尾延迟突破 SLO。","只按平均到达率估算排队项 $$W_q$$ 而不看突发到达，视觉请求的批量涌入使排队时间远超稳态估计，端到端时延失控。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-1\">一 · 一句话直觉与它为什么反直觉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-2\">二 · 严格定义：三段服务时间加排队项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-3\">三 · 为什么需要它：单请求基准与平均吞吐都不够</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-4\">四 · 常见误解之一：三段简单相加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-5\">五 · 常见误解之二：大 batch 下仍用线性解码系数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-6\">六 · 常见误解之三：只按平均到达率估排队项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-7\">七 · 串联假设的适用边界与两类失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-8\">八 · 三项服务时间的量纲对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-9\">九 · 推导关键步：从单请求到批的聚合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-10\">十 · c_dec(B) 的非线性从哪来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-11\">十一 · 离散化与近似发生在哪三处</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-12\">十二 · 用公式做 SM 分配决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-13\">十三 · 三段串联假设的边界：关键路径、饱和点与突发到达</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-14\">十四 · 串行假设的边界：重叠从哪里开始失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-15\">十五 · c_dec(B) 的超线性：线性模型在饱和点之后失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-16\">十六 · 排队项 W_q 的稳态假设与突发到达</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-17\">十七 · 规模上限：SM 配额、显存与通信的三重约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-18\">十八 · 误用模式与校验清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-19\">十九 · 串行假设的裂缝：重叠、饱和与突发</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-20\">二十 · 把时延式反解成批大小</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-21\">二十一 · 定并行度：SM 在视觉预填与解码之间的切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-22\">二十二 · 定 KV 预算：批大小与序列长度的乘积约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-23\">二十三 · 定 SLO：把排队项从稳态估计改成突发估计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-24\">二十四 · 算例：一次完整的容量决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-25\">二十五 · 容量决策中的误用边界与代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-26\">二十六 · 定容决策的边界：串行假设、超线性解码与突发排队</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-27\">二十七 · 误用一：把三段串联当成可加，忽略关键路径重叠</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-28\">二十八 · 误用二：大 batch 下沿用线性解码系数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-29\">二十九 · 误用三：用平均到达率估排队项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-30\">三十 · 反例：一次把三个误用叠在一起的容量决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-31\">三十一 · 识别清单：把误用挡在决策之前</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-batch-latency-sec-32\">三十二 · 落在调度器上的一条硬约束</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:597px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 597.1 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：多模态请求的端到端时延由视觉预填、LLM 预填、逐 token 解…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$T_{\\text{e2e}}=\\underbrace{\\fra…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：假设各阶段串行不重叠；实际分离式部署中视觉预填可与解码并行，需用关…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-multimodal-batch-latency-sec-1\">一 · 一句话直觉与它为什么反直觉</h3>\n<p>多模态请求的端到端时延，不是“把图片喂进去然后等文字出来”这样一个黑盒耗时，而是由视觉预填、LLM 预填、逐 token 解码三段串联、再叠加排队等待构成的<strong>分段服务时间之和</strong>；而真正决定哪一段吃掉时延预算的，是视觉 token 数 $$N_{\\text{vis}}$$ 与输出长度 $$N_{\\text{out}}$$ 的比值。这句话听起来平淡，反直觉之处在于：它把“模型有多快”这个笼统问题，替换成了“这一批请求里，SM 的时间被谁占走了”。一张高分辨率图经过 patch 合并后仍可能产生可观的视觉 token，这些 token 在视觉编码器与 LLM 预填里各走一遍，却只换来几十个输出 token；反过来，一段纯文本长回答可能视觉 token 为零，解码段却拖出上千步。同一个批里混着这两类请求，端到端时延的瓶颈位置就随批内构成而迁移——这正是批调度必须显式建模、而不能靠单请求基准测试外推的原因。</p>\n<p>工程上的直接后果是：任何以“平均每请求毫秒数”表述的容量结论，在多模态混合负载下都会失真。因为三段服务时间对 $$N_{\\text{vis}}$$ 与 $$N_{\\text{out}}$$ 的敏感度完全不同，批内构成一变，加权平均的服务时间就变，而排队项 $$W_q$$ 又反过来被服务时间的方差放大。直觉在这里必须被定义接管。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-2\">二 · 严格定义：三段服务时间加排队项</h3>\n<p>本系列采用的时延模型把单请求端到端时延写成四项之和：</p>\n<div class=\"formula\">$$T_{\\text{e2e}}=\\underbrace{\\frac{N_{\\text{vis}}\\cdot c_{\\text{vis}}}{\\kappa_{\\text{vis}} B}}_{\\text{视觉预填}}+\\underbrace{\\frac{(N_{\\text{vis}}+N_{\\text{txt}})\\cdot c_{\\text{pre}}}{\\kappa_{\\text{pre}} B}}_{\\text{LLM 预填}}+\\underbrace{N_{\\text{out}}\\cdot\\frac{c_{\\text{dec}}(B)}{\\kappa_{\\text{dec}} B}}_{\\text{解码}}+W_q$$</div>\n<p>逐项定义必须精确到可直接写进容量表格：$$N_{\\text{vis}}$$ 是每请求视觉 token 数，<em>含 patch 合并之后</em>——这一点不能含糊，因为合并率直接改变这一项的分子；$$N_{\\text{txt}}$$ 是文本侧输入 token 数；$$N_{\\text{out}}$$ 是生成 token 数；$$B$$ 是并发批大小；$$\\kappa_{\\text{vis}},\\kappa_{\\text{pre}},\\kappa_{\\text{dec}}$$ 是各阶段单位 token 的吞吐系数，量纲为 token/s per SM，即每个 SM 每秒能推进的 token 数；$$c_{\\text{vis}},c_{\\text{pre}}$$ 是各阶段每 token 的计算代价系数，$$c_{\\text{dec}}(B)$$ 则显式依赖批大小；$$W_q$$ 是排队等待时间，由到达率与服务率共同决定。</p>\n<p>推导的关键一步是把三段服务时间分别写成“token 数除以（吞吐系数乘批大小）”。这个写法隐含了一个约定：批内请求共享同一批 SM，服务时间随 $$B$$ 线性摊薄。于是模型的形状不是拟合出来的，而是从资源分配假设里长出来的——这也解释了为什么它的失效条件同样来自这个假设，而不是来自数据。</p>\n<p>把变量按“谁决定瓶颈”归类，比按阶段归类更有用：$$N_{\\text{vis}}$$ 同时出现在前两项，是唯一横跨两个阶段的变量；$$N_{\\text{out}}$$ 只出现在第三项且乘上了 $$c_{\\text{dec}}(B)$$，是唯一与批大小发生非线性耦合的变量；$$B$$ 出现在所有三项的分母，却在第三项里通过 $$c_{\\text{dec}}(B)$$ 部分抵消自己带来的收益。这三条结构关系，就是后面所有调度判断的定义基础。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-3\">三 · 为什么需要它：单请求基准与平均吞吐都不够</h3>\n<p>需要这个模型，是因为工程上真正要回答的三个问题它都能给出结构化的答案，而另外两种常用手段给不出。</p>\n<p>第一个问题是<strong>瓶颈定位</strong>。给定一批请求的 $$N_{\\text{vis}}$$ 与 $$N_{\\text{out}}$$ 分布，哪一段占据主导？把三项服务时间分别算出并比较，答案立刻显现：视觉 token 多、输出短的请求，前两项之和压过第三项；输出长的请求则相反。没有这个分解，团队只能看到“端到端变慢了”，却无法判断该加视觉编码器的并行度还是该改解码的批策略。</p>\n<p>第二个问题是<strong>SM 分配</strong>。在容量决策中，该模型用于在视觉预填与解码之间分配 SM：当 $$N_{\\text{vis}}$$ 大而 $$N_{\\text{out}}$$ 小时应倾斜视觉预填资源，反之倾斜解码，从而在给定 SLO 下最大化吞吐。注意这里的措辞是“给定 SLO 下最大化吞吐”，而不是“最小化时延”——因为倾斜资源必然让另一段变慢，模型的作用是让这个交换在数字上可见，而不是凭感觉调参。</p>\n<p>第三个问题是<strong>排队项的可见性</strong>。$$W_q$$ 是四项里唯一不由单请求属性决定的项，它由到达率与服务率的关系决定。多模态负载的到达往往成簇——一批图片同时上传、一个文档集合被批量提交——此时即使平均到达率低于服务率，瞬时排队也会远超稳态估计。把 $$W_q$$ 显式写进公式，等于强迫容量规划者去问“突发到达下服务时间的分布是什么形状”，而不是只算一个平均值。</p>\n<p>代价层面，这个模型的“成本”是它要求按阶段采集 $$\\kappa$$ 与 $$c$$ 系数，而这些系数随硬件形态、精度路径、并行策略变化。相比直接测端到端，建模的前期投入更高；但一旦建立，任何批构成变化都能在纸面上先算一遍，避免用线上扩容去试探。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-4\">四 · 常见误解之一：三段简单相加</h3>\n<p>最常见的误用是把三段时延简单相加而忽略分离式部署的并行重叠，结果是高估时延并过度扩容。模型的适用边界写得很清楚：各阶段串行不重叠。一旦采用分离式预填/解码部署，视觉预填与解码可以在不同资源池上并行推进，此时端到端时延由<strong>关键路径</strong>决定，而不是三项之和。把串行公式直接套到分离式部署上，等于假设视觉预填期间解码资源完全空闲——这个假设在工程上几乎从不成立，于是估算出的时延偏大，容量规划随之过度保守，GPU 利用率偏低。</p>\n<p>正确做法是把三项画成依赖图，找出从请求到达到最后一个输出 token 的最长路径。举例：一个 $$N_{\\text{vis}}$$ 很大、$$N_{\\text{out}}$$ 中等的请求进入分离式系统，视觉预填在池 A 上跑，LLM 预填与解码在池 B 上跑；若池 A 的视觉预填时间短于池 B 完成 LLM 预填所需的时间，则视觉段完全被隐藏，端到端时延等于池 B 的关键路径加排队。此时继续按三项之和扩容池 A，纯属浪费。判断依据不是“视觉段有多长”，而是“视觉段是否落在关键路径上”。</p>\n<p>这个误解还有一个变体：把重叠当成免费的。重叠只隐藏非关键路径上的工作，关键路径上的段一点也不会变快；如果视觉预填恰好在关键路径上，分离式部署带来的收益就只是排队结构的改善，而非服务时间的缩短。模型在这里的价值是逼你把“哪段在关键路径上”写成显式判断，而不是默认并行就等于加速。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-5\">五 · 常见误解之二：大 batch 下仍用线性解码系数</h3>\n<p>第二个误用是在大 batch 下仍用线性 $$c_{\\text{dec}}(B)$$，从而低估解码段的 KV 带宽竞争，最终以 SLO 违约收场。公式里 $$c_{\\text{dec}}(B)$$ 显式依赖批大小，原因写得很直白：解码阶段每步都要读整批的 KV cache，批越大，单步要搬运的 KV 字节越多，带宽竞争越激烈，$$c_{\\text{dec}}(B)$$ 随 batch 增大而<strong>超线性上升</strong>。线性模型在 $$B$$ 超过 SM 饱和点后系统性低估时延。</p>\n<p>具体机制是这样的：解码每生成一个 token，需要为批内每个请求读取其历史 KV；当 $$B$$ 增大到 KV 总字节数逼近可用带宽的饱和区间时，单步时间不再随 $$B$$ 线性摊薄，而是被带宽钳住。此时公式第三项的分母里 $$\\kappa_{\\text{dec}} B$$ 的增长被 $$c_{\\text{dec}}(B)$$ 的上升吃掉一部分，实际服务时间高于线性外推值。工程上的表现是：离线压测在中等 batch 下曲线漂亮，线上把 batch 拉大后尾延迟突然突破 SLO，而按线性模型算出的余量看起来还很充裕。</p>\n<p>应对方式不是把模型丢掉，而是把 $$c_{\\text{dec}}(B)$$ 当作分段函数或查表量：在 SM 饱和点以下用线性段，以上用实测的超线性段。容量决策时，先确定目标 SLO 对应的最大可接受 $$B$$，再检查该 $$B$$ 是否落在饱和点之上；若是，则必须用非线性段重算，或者改用更小的批加更多副本。这里的判断是定性的但可执行：饱和点由硬件带宽与 KV 字节规模共同决定，不给出具体数值也应能定位到“该测哪条曲线”。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-6\">六 · 常见误解之三：只按平均到达率估排队项</h3>\n<p>第三个误用是只按平均到达率估算 $$W_q$$ 而不看突发到达，视觉请求的批量涌入使排队时间远超稳态估计，端到端时延失控。$$W_q$$ 在公式里是加号后面的独立项，容易被当成小修正；但在多模态场景里它经常是最大的一项。原因在于视觉请求的到达具有簇发性：一批图片上传、一个文档集合提交、一次评测任务下发，都会在短时间内把到达率推到远高于均值的水平，而服务时间本身又因 $$N_{\\text{vis}}$$ 分布很宽而方差很大。</p>\n<p>排队论的基本结论在这里适用：等待时间由到达过程与服务时间分布共同决定，而不只由均值决定。当服务时间的方差大（同一批里既有重视觉请求又有纯文本请求），即使平均利用率不高，瞬时排队也会显著。工程含义是：容量规划必须按<strong>突发窗口内的到达率</strong>而非日均到达率来算 $$W_q$$，并且要把批内构成的最坏组合（最大 $$N_{\\text{vis}}$$ 配最大 $$N_{\\text{out}}$$）作为压力点。</p>\n<p>一个可执行的判断：如果 $$W_q$$ 在稳态估计中占比很小，但在突发窗口的压力测试中占比过半，那么瓶颈不在三段服务时间，而在调度器的准入与排队策略——此时增加 SM 的边际收益低于改进入队规则与批构成控制的收益。这条判断把模型从“算时延”变成了“决定往哪儿投工程资源”，也正是它值得被写成严格定义而非口头直觉的理由。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-7\">七 · 串联假设的适用边界与两类失效</h3>\n<p>这个模型的全部价值建立在一个可证伪的前提上：三段服务时间可以相加。它成立的条件是视觉预填、LLM 预填、解码三段在同一组 SM 上串行执行，且批内请求同步推进。一旦部署形态变成视觉编码器与语言模型分离（例如视觉塔独占若干 GPU、LLM 侧独立做连续批处理），视觉预填就与解码在时间轴上重叠，此时端到端时延是<strong>关键路径</strong>而非三段之和：$$T_{\\text{e2e}}=\\max\\big(T_{\\text{vis}},\\,T_{\\text{pre}}+T_{\\text{dec}}\\big)+W_q$$。按求和估算会系统性高估时延，容量规划随之过度保守——为一条根本不存在的串行链多买 GPU，利用率却停在低位。这是该模型最典型的失效模式：公式没错，错在把它套到了非串行的拓扑上。</p>\n<p>第二个失效点藏在 $$c_{\\text{dec}}(B)$$ 里。解码阶段每步都要读全部 KV，batch 增大时 KV 带宽竞争加剧，单 token 成本随 B 超线性上升，而线性模型假定它恒定。当 B 越过 SM 饱和点，模型给出的解码时延会低于实测，SLO 在纸面上达标、线上尾延迟却突破阈值。工程上应把 $$c_{\\text{dec}}$$ 标定为 B 的分段函数或查表，而不是一个常数。</p>\n<p>第三个边界是排队项 $$W_q$$。它由到达率与服务率共同决定，但多模态请求的到达是突发的——一批图像同时涌入时，瞬时到达率远超稳态均值，$$W_q$$ 被严重低估，端到端时延失控。因此该模型只适合做稳态容量分配，不适合作为突发场景的时延预测器。</p>\n<table class=\"mini\"><thead><tr><th>假设</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>三段串行相加</td><td>视觉预填与解码分离部署</td><td>高估时延，过度扩容，GPU 利用率低</td></tr><tr><td>$$c_{\\text{dec}}$$ 线性于 B</td><td>B 超过 SM 饱和点</td><td>低估 KV 带宽竞争，尾延迟违约</td></tr><tr><td>稳态 $$W_q$$</td><td>视觉请求批量突发</td><td>排队时间被低估，时延失控</td></tr></tbody></table>\n<h3 id=\"th-multimodal-batch-latency-sec-8\">八 · 三项服务时间的量纲对齐</h3>\n<p>公式的每一项都必须落在“秒”这个量纲上，否则相加毫无意义。视觉预填项 <span class=\"inline-math\">N_vis·c_vis/(κ_vis·B)</span> 里，<span class=\"inline-math\">N_vis</span> 是每请求视觉 token 数（patch 合并之后），<span class=\"inline-math\">c_vis</span> 是每个视觉 token 折算成的计算量（以 SM 周期或等效 FLOP 计），<span class=\"inline-math\">κ_vis</span> 是单位 token 吞吐系数，量纲为 token/s per SM，乘以批大小 <span class=\"inline-math\">B</span> 后得到整批的 token/s，再被总 token 数除，得到该批视觉预填占用的时间。这里的关键在于 <span class=\"inline-math\">κ_vis</span> 不是硬件峰值，而是“在给定 tile 形状、给定 TMEM 占用下，单个 SM 每秒能推过多少个视觉 token”的实测折算值；它把 tcgen05 MMA 的吞吐、patch 合并的额外访存、以及视觉编码器在 SM100 上的实际占用率一并吸收进去。LLM 预填项同理，只是 token 数变成 <span class=\"inline-math\">N_vis+N_txt</span>，因为视觉 token 进入 LLM 后要和文本 token 一起走一遍因果注意力预填。解码项 <span class=\"inline-math\">N_out·c_dec(B)/(κ_dec·B)</span> 的写法与其他两项不同：<span class=\"inline-math\">c_dec</span> 显式写成 <span class=\"inline-math\">B</span> 的函数，这是全式唯一一处非线性来源，也是推导中最需要小心的地方。</p>\n<p>量纲对齐的直接工程后果是：任何一项的系数估错，误差会按该项在总时延中的占比线性放大。举例，一个请求 <span class=\"inline-math\">N_vis</span> 很大而 <span class=\"inline-math\">N_out</span> 很小（单图问答、OCR 抽取），视觉预填项占比高，<span class=\"inline-math\">κ_vis</span> 估高 20% 就意味着端到端低估近 20%；反之长输出场景里解码项主导，<span class=\"inline-math\">c_dec(B)</span> 的形状比 <span class=\"inline-math\">κ_dec</span> 的绝对值更重要。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-9\">九 · 推导关键步：从单请求到批的聚合</h3>\n<p>推导的起点是单请求服务时间 <span class=\"inline-math\">s_i = N_i·c_i/κ_i</span>（单 SM、无并发）。第一步把单 SM 推广到 <span class=\"inline-math\">B</span> 个请求共享一批 SM：若该阶段分配了 <span class=\"inline-math\">m</span> 个 SM，则整批吞吐为 <span class=\"inline-math\">m·κ</span>，批内每个请求的平均服务时间近似为 <span class=\"inline-math\">N·c/(κ·m)</span>。公式里把 <span class=\"inline-math\">m</span> 折叠进 <span class=\"inline-math\">B</span>，等价于约定“批大小与分配 SM 数同比例增长”，即 <span class=\"inline-math\">m ∝ B</span>。这一步是近似的核心：它假设 SM 分配随批线性伸缩，而真实调度器在 SM 饱和后无法继续线性加 SM，于是 <span class=\"inline-math\">κ</span> 实际会随 <span class=\"inline-math\">B</span> 下降。第二步是把三段串行相加，这一步只在“同一批请求依次经过三个阶段且阶段间无重叠”时成立。第三步加入排队项 <span class=\"inline-math\">W_q</span>，它由到达率 <span class=\"inline-math\">λ</span> 与服务率 <span class=\"inline-math\">μ=1/T_service</span> 决定；在稳态 M/D/1 近似下 <span class=\"inline-math\">W_q ≈ ρ/(2μ(1-ρ))</span>，<span class=\"inline-math\">ρ=λ/μ</span>。注意 <span class=\"inline-math\">W_q</span> 对 <span class=\"inline-math\">ρ</span> 是非线性的，<span class=\"inline-math\">ρ</span> 逼近 1 时爆炸，这正是突发视觉请求涌入时尾延迟失控的数学根源。</p>\n<div class=\"formula\">$$T_{\\text{e2e}}=\\frac{N_{\\text{vis}}c_{\\text{vis}}}{\\kappa_{\\text{vis}}B}+\\frac{(N_{\\text{vis}}+N_{\\text{txt}})c_{\\text{pre}}}{\\kappa_{\\text{pre}}B}+N_{\\text{out}}\\frac{c_{\\text{dec}}(B)}{\\kappa_{\\text{dec}}B}+W_q$$</div>\n<p>把三步串起来看，聚合推导隐含了一个“批内同质”假设：同一批里所有请求的 <span class=\"inline-math\">N_vis</span>、<span class=\"inline-math\">N_out</span> 相同。真实连续批处理中批内请求长度参差，正确做法是对批内取最大或分桶，否则短请求被长请求拖尾，公式给出的是批的平均值而非任一请求的实际时延。这一点在容量规划里必须显式处理，否则平均值达标而 P99 违约。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-10\">十 · c_dec(B) 的非线性从哪来</h3>\n<p><span class=\"inline-math\">c_dec(B)</span> 显式依赖批大小，是全式唯一不能靠“除以 B”消掉的项。解码每步要为批内每个请求读取全部 KV cache，KV 读取量与 <span class=\"inline-math\">B</span> 成正比，而 HBM 带宽是固定的；当 <span class=\"inline-math\">B</span> 增大到 KV 带宽成为瓶颈，每 token 的有效计算时间不再被 MMA 吞吐决定，而被 KV 搬运时间决定，于是 <span class=\"inline-math\">c_dec</span> 随 <span class=\"inline-math\">B</span> 超线性上升。可以把它写成两段拼接：小 <span class=\"inline-math\">B</span> 时 <span class=\"inline-math\">c_dec ≈ c_0</span>（计算受限，常数），大 <span class=\"inline-math\">B</span> 时 <span class=\"inline-math\">c_dec ≈ c_0 + β·B</span>（带宽受限，线性于 B）。代回公式，解码项从 <span class=\"inline-math\">N_out·c_0/(κ_dec·B)</span>（随 B 反比下降，批越大越省）变成 <span class=\"inline-math\">N_out·β/κ_dec</span>（与 B 无关，批再大也不省），这就是“批大小收益饱和”的解析表达。SM 饱和点就是这两段的交点。</p>\n<p>工程代价很直接：在饱和点之前扩批，解码段摊薄，吞吐上升、单请求时延下降；越过饱和点继续扩批，解码段不再摊薄，反而因 KV 带宽竞争使每 token 时间上升，尾延迟恶化。一个长输出、大 batch 的对话场景若按线性 <span class=\"inline-math\">c_dec</span> 规划容量，会算出“扩批仍线性增益”的假象，实际部署时 SLO 在批大小越过交点后立刻违约。正确做法是把 <span class=\"inline-math\">c_dec(B)</span> 当作分段函数代入，在容量搜索时对 <span class=\"B</span> 做离散扫描而非解析求导。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-11\">十一 · 离散化与近似发生在哪三处</h3>\n<p>第一处是 SM 分配的连续化：公式把 <span class=\"inline-math\">m ∝ B</span> 当作连续比例，而真实 SM 分配是整数、按 SM 组（2-SM MMA 对）粒度切分，且视觉预填与解码往往分属不同 SM 池。离散化误差在 <span class=\"B</span> 较小时显著，因为 <span class=\"inline-math\">m</span> 只能取整，<span class=\"inline-math\">κ·m</span> 的实际值在整数台阶上跳变，公式给出的是台阶的线性插值。第二处是串行假设：公式把三段相加，而分离式部署中视觉预填在独立池上运行、可与解码池并行，端到端时延应取关键路径 <span class=\"inline-math\">max(视觉预填, LLM 预填+解码)</span> 而非求和。求和式在并行重叠时系统性高估，导致过度扩容；这是公式最常被误用的地方。第三处是排队项的稳态近似：<span class=\"inline-math\">W_q</span> 用平均到达率算出的是稳态期望，而视觉请求常成批到达（一次上传多图、一次批量标注），瞬时 <span class=\"inline-math\">λ</span> 远超均值，<span class=\"inline-math\">ρ</span> 短时逼近 1，实际排队远超稳态估计。</p>\n<table class=\"mini\"><thead><tr><th>近似点</th><th>公式假设</th><th>真实系统</th><th>偏差方向</th></tr></thead><tbody><tr><td>SM 分配</td><td>m ∝ B 连续</td><td>整数 SM 组、分池</td><td>小 batch 下跳变</td></tr><tr><td>阶段关系</td><td>三段串行相加</td><td>分离式可并行</td><td>高估时延</td></tr><tr><td>排队项</td><td>稳态平均到达率</td><td>突发成批到达</td><td>低估尾延迟</td></tr><tr><td>c_dec(B)</td><td>线性于 B</td><td>饱和后超线性</td><td>大 batch 低估</td></tr></tbody></table>\n<p>三处近似的方向并不一致：串行假设高估、c_dec 线性假设低估、排队稳态假设低估。这意味着不能靠“统一打个折扣系数”来修正，必须逐项判断当前工作点落在哪个近似失效区。容量规划的正确姿势是先确定瓶颈段（<span class=\"inline-math\">N_vis</span> 与 <span class=\"inline-math\">N_out</span> 谁主导），再只对该段启用更精确的子模型，其余段保留线性近似以控制搜索复杂度。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-12\">十二 · 用公式做 SM 分配决策</h3>\n<p>公式的实用价值不在预测绝对时延，而在比较“把 SM 给视觉预填还是给解码”的边际收益。对 <span class=\"inline-math\">m_vis</span> 求偏导，视觉预填段时间对 <span class=\"inline-math\">m_vis</span> 的敏感度是 <span class=\"inline-math\">-N_vis·c_vis/(κ_vis·m_vis²)</span>，解码段对 <span class=\"inline-math\">m_dec</span> 的敏感度是 <span class=\"inline-math\">-N_out·c_dec(B)/(κ_dec·m_dec²)</span>。两者相等时达到给定 SLO 下的最优分配。直观结论：<span class=\"inline-math\">N_vis</span> 大而 <span class=\"inline-math\">N_out</span> 小，视觉预填的敏感度高，应倾斜视觉预填 SM；反之长输出场景倾斜解码。但倾斜的前提是两段确实串行；若已分离部署且可并行，则应把 SM 分配给关键路径那一侧，另一侧只需保证不成为新的关键路径。举例，一个文档理解服务 <span class=\"inline-math\">N_vis</span> 数千、<span class=\"inline-math\">N_out</span> 数十，视觉预填是绝对瓶颈，把 SM 从解码池挪向视觉池能在 SLO 不变下提升吞吐；而同一集群里的长文摘要服务 <span class=\"inline-math\">N_out</span> 数百，解码段主导，两个服务混部时必须按各自瓶颈段分池，否则公式给出的“平均最优”对两者都不最优。</p>\n<p>决策的代价维度是显存与功耗而非仅延迟：视觉预填池的 SM 占用推高瞬时功耗，解码池的 KV cache 占用推高显存。公式只覆盖时间维度，SM 分配还要受显存容量与功耗墙约束，因此实际搜索是在“时延满足 SLO”的可行域内最小化 SM 总数，而非单纯最小化时延。这一点决定了公式在容量规划中的角色是约束而非目标函数。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-13\">十三 · 三段串联假设的边界：关键路径、饱和点与突发到达</h3>\n<p>该公式的成立依赖一个强假设：视觉预填、LLM 预填、解码三段在时间上严格串行、互不重叠。在单实例、单请求的朴素执行路径上这近似成立，但在分离式部署（视觉编码器独立成池、LLM 预填与解码分置不同 GPU 组）中，视觉预填与解码可以并行推进，端到端时延由关键路径而非三段之和决定。此时正确的写法是 <span class=\"formula\">$$T_{\\text{e2e}}=\\max\\bigl(T_{\\text{vis}},\\,T_{\\text{pre}}+T_{\\text{dec}}\\bigr)+W_q$$</span> 之类的路径结构，其中视觉段的完成只需早于 LLM 预填的输入就绪点，而非早于整条请求结束。误用串行求和会把时延高估，直接后果是容量规划过度保守：按三段之和反推所需 SM 数，会多配资源、压低 GPU 利用率，在给定 SLO 下损失本可承载的吞吐。判断依据很具体——看部署拓扑里视觉编码器是否与解码 worker 共享同一批 SM；若已分离，串行公式只能作为上界参考，不能作为扩容依据。</p>\n<p>第二个边界在解码项的分母。公式把解码服务时间写成 <span class=\"formula\">$$N_{\\text{out}}\\cdot c_{\\text{dec}}(B)/(\\kappa_{\\text{dec}}B)$$</span>，其中 <span class=\"formula\">$$c_{\\text{dec}}(B)$$</span> 被显式标注为依赖批大小，原因是解码每步都要为整个 batch 读取 KV cache，KV 带宽竞争随 B 增大而加剧，单 token 的有效成本超线性上升。线性模型隐含 <span class=\"formula\">$$c_{\\text{dec}}(B)\\propto B^{0}$$</span> 或至多线性摊薄，这在 B 未超过 SM 饱和点时成立；一旦越过饱和点，实际每 token 时延的增长快于 1/B 的摊薄收益，模型开始系统性低估解码段。工程上的表现是：离线压测按线性外推算出的大 batch 配置上线后，尾延迟突破 SLO，而平均延迟看似正常——因为饱和点之后受损最重的是长输出请求的尾部。修正方式不是给公式加一个笼统系数，而是把 <span class=\"formula\">$$c_{\\text{dec}}(B)$$</span> 标定为分段函数：在饱和点以下用实测斜率，饱和点以上按 KV 带宽占用率建模，并把饱和点本身作为调度器的硬约束（连续批处理的最大在飞 token 数）。</p>\n<p>第三个失效条件藏在排队项 <span class=\"formula\">$$W_q$$</span>。公式只写“由到达率与服务率决定”，这在稳态泊松到达下可用排队论近似，但多模态请求的到达具有明显的批量涌入特征：同一批图像/视频帧往往成组到达（例如一批文档解析任务、一轮多图问答），瞬时到达率远超均值。此时按平均到达率估算的 <span class=\"formula\">$$W_q$$</span> 会严重低估真实排队时间，端到端时延失控。可用一个粗粒度判据：若到达过程的变异系数显著大于 1，稳态排队公式给出的 <span class=\"formula\">$$W_q$$</span> 只能作为下界。调度侧的对策是把视觉 token 数作为准入控制的第一维度——对 <span class=\"formula\">$$N_{\\text{vis}}$$</span> 极大的请求做前置限流或降采样（patch 合并更激进），避免单个请求在视觉预填段长时间占用 SM 而把后续请求全部推入长队列。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>模型偏差方向</th><th>系统代价</th><th>工程对策</th></tr></thead><tbody><tr><td>分离式部署仍按串行求和</td><td>高估时延</td><td>过度扩容、GPU 利用率低</td><td>改用关键路径结构，视觉段只约束输入就绪点</td></tr><tr><td>B 超过 SM 饱和点仍用线性 c_dec(B)</td><td>低估解码段</td><td>尾延迟突破 SLO</td><td>分段标定 c_dec(B)，把饱和点设为在飞 token 上限</td></tr><tr><td>只按平均到达率估 W_q</td><td>低估排队</td><td>突发涌入时端到端失控</td><td>按 N_vis 做准入限流与降采样</td></tr></tbody></table>\n<p>把这三条边界合起来看，公式的真正用途不是给出一个可代入的绝对时延，而是给出资源倾斜的方向判据：当 <span class=\"formula\">$$N_{\\text{vis}}$$</span> 大而 <span class=\"formula\">$$N_{\\text{out}}$$</span> 小时，视觉预填项主导，应把 SM 向视觉编码池倾斜；反之解码项主导，应向解码 worker 倾斜。但这一判据只有在 <span class=\"formula\">$$c_{\\text{dec}}(B)$$</span> 已按饱和点分段、且 <span class=\"formula\">$$W_q$$</span> 已按突发到达校正后才可信。换言之，模型的适用域是“稳态、未饱和、串行或已正确建模重叠”的区间；一旦越过饱和点或遭遇批量涌入，公式退化为方向性参考，调度器必须切换到基于实测关键路径与在飞 token 数的闭环控制，而不是继续用解析式外推做容量决策。</p>\n<h3 id=\"th-multimodal-batch-latency-sec-14\">十四 · 串行假设的边界：重叠从哪里开始失效</h3>\n<p>公式把视觉预填、LLM 预填、解码三段写成相加，前提是这三段在同一组 SM 上顺序执行、互不重叠。这个前提在单实例聚合式部署里基本成立：一个请求进来，视觉编码器先占满一批 SM，编完把视觉 token 交给 LLM 预填，预填完再进解码循环。三段共享同一资源池，时间自然累加。但一旦把视觉预填拆到独立实例（分离式预填/解码的常见形态），串行假设立刻破裂——视觉预填在 A 池跑的同时，B 池的解码循环仍在为其他请求吐 token，两个阶段在时间轴上并行。此时端到端时延不是三段之和，而是关键路径：</p>\n<div class=\"formula\">$$T_{\\text{e2e}}^{\\text{disagg}}=\\max\\!\\left(T_{\\text{vis}}+T_{\\text{pre}},\\;T_{\\text{queue}}+T_{\\text{dec}}\\right)+W_q'$$</div>\n<p>关键在于，视觉预填与 LLM 预填仍必须串行（后者依赖前者的输出 token），但整条预填链可以与解码链并行。若沿用求和式估算，会把本可重叠的那段时间重复计入，得到偏高的时延估计。工程后果不是算错一个数，而是容量决策系统性偏保守：按高估的时延去扩容，GPU 利用率被压低，而真实 SLO 余量被浪费。判断边界的方法很直接——看部署拓扑。聚合式（视觉编码器与 LLM 同池）用求和式；分离式用关键路径式，并且要显式建模两条链的资源独立性，否则 max 里的两项其实仍在抢同一批 SM。</p>\n<p>还有一个更隐蔽的失效点：即使拓扑是分离式，若视觉预填实例与解码实例共享 NVLink 域内的同一批 GPU 切片，或共享同一套 KV cache 显存池，并行度会被资源争用吃掉。此时既不是纯串行也不是纯并行，而是“部分重叠”——重叠比例取决于两池的 SM 配额划分。公式本身没有这个参数，必须外挂一个重叠系数，按实际配额比折算。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-15\">十五 · c_dec(B) 的超线性：线性模型在饱和点之后失效</h3>\n<p>推导里把解码段写成 $$N_{\\text{out}}\\cdot c_{\\text{dec}}(B)/(\\kappa_{\\text{dec}}B)$$，其中 $$c_{\\text{dec}}(B)$$ 显式依赖批大小。这个依赖不是装饰：解码每步要为 B 条序列各读一遍 KV cache，KV 带宽需求随 B 线性增长，而可用 HBM 带宽是固定的。B 小的时候，带宽有余量，每 token 成本近似常数，除以 B 后单请求分摊下降，吞吐随 B 上升——这是线性模型成立的区间。B 越过 SM 饱和点后，KV 读取开始互相挤占带宽，有效带宽按序列分摊后每 token 的实际耗时上升，$$c_{\\text{dec}}(B)$$ 呈超线性。此时若仍用线性系数外推，会低估解码段时延。</p>\n<p>量化这个转折点需要两个量：单 SM 的 KV 读取带宽上限，以及每 token 的 KV 字节数（层数 × 头数 × head_dim × 2 字节 × 精度折算）。当 $$B\\cdot \\text{KV bytes per token}$$ 超过可用带宽乘以一步的时间窗，就进入竞争区。工程上的做法不是去拟合一条精确曲线，而是在容量规划时给解码段留一个随 B 增长的惩罚因子，或者直接把 B 限制在饱和点以下、用更多实例横向扩展。后者在 NVL72 这种高带宽域内更划算：横向扩展吃的是 NVLink 5 的集合通信余量，而不是让单实例在饱和区硬扛。</p>\n<p>失效的代价是尾延迟。平均时延可能只涨一点，但 KV 带宽竞争对长序列请求的惩罚远大于短序列，尾部的 P99 会先破 SLO。用线性模型做容量规划，等于假设尾部与均值同比例增长，这个假设在饱和区不成立。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-16\">十六 · 排队项 W_q 的稳态假设与突发到达</h3>\n<p>$$W_q$$ 由到达率与服务率决定，标准写法来自排队论稳态解。但多模态请求的到达不是泊松式的平滑流：视觉请求常成批涌入——一批图像审核任务、一次多图问答会话、一个批量文档解析作业，到达率在秒级尺度上剧烈起伏。稳态公式给出的是长期平均排队时间，对突发窗口严重低估。突发期间瞬时到达率可以是均值的数倍，而服务率受限于视觉预填的 SM 配额，队列迅速堆积，$$W_q$$ 远超稳态估计。</p>\n<p>边界条件因此是：公式适用于到达率方差小的场景（交互式单请求、稳定 API 流量），不适用于批量作业与突发会话。对后者，要么在调度层做准入控制把突发削峰，要么把 $$W_q$$ 换成基于瞬时队列长度的动态估计。一个可操作的判据是看队列长度的自相关时间——若队列在几十毫秒内就能从空涨到满，稳态假设已经失效，此时排队项应由当前队列深度乘以平均服务时间近似，而不是由长期到达率算出。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-17\">十七 · 规模上限：SM 配额、显存与通信的三重约束</h3>\n<p>公式里的 $$\\kappa$$ 是“每 SM 每 token 吞吐系数”，隐含假设 SM 数量可以任意缩放、缩放是线性的。这个假设在三个维度上先后撞墙。第一是 SM 配额：视觉预填与解码要在同一批 SM 上分配，配额比一旦固定，两段的 $$\\kappa$$ 就不再独立——给视觉多分 SM，解码的 $$\\kappa_{\\text{dec}}$$ 就下降，公式里两个系数变成耦合变量，不能分别调参。第二是显存：B 增大意味着 KV cache 占用线性上升，视觉 token 也占激活显存，当 B 逼近显存上限，调度器被迫降低并发或做 KV 换出，服务率骤降，$$W_q$$ 跳变。第三是通信：分离式部署跨实例传 KV 与视觉特征，走 NVLink 5 或 NIXL，传输时延随 B 与序列长度增长，在大 B 下成为关键路径上的新项，公式里根本没有这一项。</p>\n<p>规模上限因此不是一个数，而是一条随部署形态移动的线。聚合式部署的上限由单实例显存与 SM 饱和点决定；分离式部署的上限由跨实例带宽与两池配额平衡决定。超过上限后，公式的每一项都还在，但项与项之间的独立性消失，相加不再有意义。工程判断是：先用公式做粗粒度容量估算，再用实测的饱和点校准 $$\\kappa$$ 与 $$c_{\\text{dec}}(B)$$，把公式当成一阶近似而非精确预测器。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-18\">十八 · 误用模式与校验清单</h3>\n<p>两类误用最伤。其一，分离式部署仍按串行求和，高估时延、过度扩容、利用率偏低——这是把可并行的两段当成串行付了两次钱。其二，大 batch 下仍用线性 $$c_{\\text{dec}}(B)$$，低估 KV 带宽竞争，线上尾延迟破 SLO——这是把饱和区的超线性当成了线性。两者方向相反，但根因相同：公式的假设条件没有被显式检查就套用。</p>\n<p>落地时给公式配一张校验清单，比调参更有用：</p>\n<ul>\n<li>拓扑检查：视觉预填与解码是否同池？同池用求和，异池用关键路径，共享资源时加重叠系数。</li>\n<li>饱和检查：当前 B 是否低于实测 SM 饱和点？低于则线性 $$c_{\\text{dec}}$$ 可用，高于则换惩罚因子或横向扩展。</li>\n<li>到达检查：到达率方差是否小？突发场景禁用稳态 $$W_q$$，改用瞬时队列深度估计。</li>\n<li>显存检查：B 对应的 KV cache 加视觉激活是否逼近显存上限？逼近则服务率非线性下降，公式失效。</li>\n<li>通信检查：分离式部署的跨实例传输是否进入关键路径？进入则需在公式中补一项传输时延。</li>\n</ul>\n<p>这张清单的价值在于把“公式是否成立”从直觉判断变成可执行的检查项。每一项对应一个具体的资源约束，检查不通过就说明该段的模型形式需要替换，而不是继续用同一个公式外推。对容量规划而言，最稳的做法是把公式当作分配 SM 配额的相对依据——比较倾斜视觉预填与倾斜解码两种方案的时延差——而不是当作绝对时延的预测器；相对比较对系数误差不敏感，绝对预测则对饱和点极其敏感。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-19\">十九 · 串行假设的裂缝：重叠、饱和与突发</h3>\n<p>这套时延模型最脆弱的地方不在公式本身，而在它默认三段服务时间可以相加。串行假设在单实例共置部署下近似成立：视觉编码、LLM 预填、解码共享同一批 SM，前一段不释放资源后一段就无法推进。但在分离式预填/解码部署中，视觉预填跑在独立的视觉 worker 上，它的输出（合并后的视觉 token 嵌入）通过 NVLink 或 NIXL 传给解码实例，此时视觉预填与上一批请求的解码在时间轴上重叠。真正决定端到端时延的是关键路径：$$T_{\\text{e2e}}^{\\text{disagg}}=\\max\\!\\big(T_{\\text{vis}}+T_{\\text{pre}},\\;T_{\\text{dec}}\\big)+W_q$$，而非三项之和。把分离式部署硬套串行公式，会系统性地高估时延，进而触发过度扩容——这是容量规划中最常见的浪费来源，GPU 利用率被压低的根因往往就写在这一个错误的加法上。判断依据很直接：看视觉 worker 与解码 worker 是否共享 SM 与 HBM 带宽；共享则串行近似可用，不共享则必须走关键路径。</p>\n<p>第二个失效条件是解码吞吐系数对批大小的线性假设。模型中 $$c_{\\text{dec}}(B)$$ 被写成随 B 线性变化，实际解码每步都要为全部活跃序列读取 KV cache，B 增大时 KV 带宽需求线性上升，而 HBM 带宽是固定预算，于是单位 token 的有效吞吐在 B 超过 SM 饱和点后转为次线性，等效的 $$c_{\\text{dec}}(B)$$ 呈超线性上升。此时线性模型给出的解码时间是乐观下界，线上表现为平均时延尚可、尾延迟却突破 SLO。工程上的修正不是换一个更复杂的解析式，而是在饱和点附近用分段系数：以实测的 $$c_{\\text{dec}}(B)$$ 曲线在若干批大小上打点，插值成表，公式只负责外推未测区间。饱和点的位置由模型层数、KV 头数与每 token 字节数决定，与视觉 token 数无关，因此可以离线标定一次、在线按 B 查表。</p>\n<p>第三个边界是排队项 $$W_q$$ 的稳态假设。$$W_q$$ 由到达率与服务率决定，公式默认到达过程平稳；但多模态流量天然成簇——同一用户的连拍图片、文档批量上传、视频抽帧请求会在短窗口内集中到达，视觉 token 数 $$N_{\\text{vis}}$$ 也随之抬升，服务率瞬时下降。稳态排队公式在突发窗口内严重低估等待时间，端到端时延失控的现场事故多属此类。可用一个粗粒度的判据：设突发窗口内到达率为稳态的 $$g$$ 倍，则排队项近似放大 $$g/(1-\\rho)$$ 倍（$$\\rho$$ 为服务强度），当 $$\\rho$$ 逼近 1 时该放大因子发散，说明此时任何基于平均值的容量决策都不可信，必须引入准入控制或视觉请求的降采样（减少抽帧数、降低分辨率）来压 $$N_{\\text{vis}}$$。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>公式偏差方向</th><th>系统代价</th><th>工程对策</th></tr></thead><tbody><tr><td>分离式部署仍串行求和</td><td>高估时延</td><td>过度扩容、GPU 利用率低</td><td>改用关键路径 max 形式</td></tr><tr><td>B 超饱和点仍用线性 $$c_{\\text{dec}}$$</td><td>低估解码段</td><td>尾延迟破 SLO</td><td>分段系数查表</td></tr><tr><td>突发到达按稳态估 $$W_q$$</td><td>低估排队</td><td>端到端时延失控</td><td>准入控制、视觉降采样</td></tr></tbody></table>\n<p>规模上限同样值得写清：模型把每阶段的成本写成 token 数除以吞吐系数乘批大小，隐含假设 SM 数量可按比例线性扩展、通信开销可忽略。当并行度跨过单节点、进入 NVL72 机柜级或跨机柜 EP/TP 时，all-to-all 与集合通信进入关键路径，$$\\kappa_{\\text{pre}}$$ 不再是常数而是并行度的函数，公式中的分母需要替换为有效吞吐，否则在超大规模下会低估预填时间。因此该模型的可靠区间是单实例到单机柜、批大小在饱和点以下、到达过程可近似平稳；越过任一条件，公式退化为量级估算工具，容量决策必须让位于实测曲线与在线反馈。</p>\n<h3 id=\"th-multimodal-batch-latency-sec-20\">二十 · 把时延式反解成批大小</h3>\n<p>容量决策的第一步不是“能跑多大 batch”，而是“给定 SLO，batch 的上界在哪里”。把端到端时延式对 <span class=\"sym\">B</span> 做反解，前提是承认三段中至少一段是线性于 <span class=\"sym\">1/B</span> 的，而解码段的 <span class=\"sym\">c_dec(B)</span> 不是常数。工程上可行的做法是分段反解：先忽略 <span class=\"sym\">W_q</span>，令 <span class=\"sym\">T_e2e = T_slo</span>，得到</p>\n<div class=\"formula\">$$B_{\\text{lin}}=\\frac{1}{T_{\\text{slo}}}\\left(\\frac{N_{\\text{vis}}c_{\\text{vis}}}{\\kappa_{\\text{vis}}}+\\frac{(N_{\\text{vis}}+N_{\\text{txt}})c_{\\text{pre}}}{\\kappa_{\\text{pre}}}+\\frac{N_{\\text{out}}c_{\\text{dec}}}{\\kappa_{\\text{dec}}}\\right)$$</div>\n<p>这个 <span class=\"sym\">B_lin</span> 只是乐观上界，因为 <span class=\"sym\">c_dec</span> 被当成与 <span class=\"sym\">B</span> 无关。真正的批大小必须再叠一层解码段的饱和约束：当 <span class=\"sym\">B</span> 越过 SM 饱和点，KV 带宽竞争使 <span class=\"sym\">c_dec(B)</span> 超线性上升，此时 <span class=\"sym\">N_out·c_dec(B)/(κ_dec·B)</span> 不再随 <span class=\"sym\">B</span> 单调下降，而是出现一个极小点，该极小点对应的 <span class=\"sym\">B</span> 才是解码段的最优批。工程判断是：把 <span class=\"sym\">B_lin</span> 与解码段实测的“时延-批大小”曲线拐点取小者，作为 SLO 约束下的批上界；两者差距越大，说明系统越受 KV 带宽而非算力约束。</p>\n<p>具体机制上，这要求调度器维护一张按 <span class=\"sym\">N_vis</span> 分档的批上界表，而不是一个全局常数。视觉 token 数在 patch 合并后差异可达数量级，同一 <span class=\"sym\">B</span> 对轻视觉请求是欠载、对重视觉请求已越拐点。代价体现在显存：批上界直接决定 KV 预算的下限，若按最重档定 <span class=\"sym\">B</span>，轻档请求的 KV 空间被浪费；若按平均档定，重档请求在突发时突破 SLO。折中是分档预留加动态回收，代价是调度器复杂度与一次额外的显存重分配延迟。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-21\">二十一 · 定并行度：SM 在视觉预填与解码之间的切分</h3>\n<p>并行度决策的本质是把固定的 SM 总数切成 <span class=\"sym\">S_vis</span> 与 <span class=\"sym\">S_dec</span> 两份（LLM 预填通常与视觉预填共享或单独一档），使给定 SLO 下吞吐最大。由时延式可见，两段的敏感度不同：视觉预填项正比于 <span class=\"sym\">N_vis/κ_vis</span>，解码项正比于 <span class=\"sym\">N_out·c_dec(B)/κ_dec</span>。当 <span class=\"sym\">N_vis</span> 大而 <span class=\"sym\">N_out</span> 小时，瓶颈在视觉预填，应把 SM 向 <span class=\"sym\">κ_vis</span> 倾斜；反之 <span class=\"sym\">N_out</span> 主导时向解码倾斜。可写成拉格朗日式的边际判断：在两段时延对 SM 的偏导数相等处切分最优，</p>\n<div class=\"formula\">$$\\frac{\\partial T_{\\text{vis}}}{\\partial S_{\\text{vis}}}=\\frac{\\partial T_{\\text{dec}}}{\\partial S_{\\text{dec}}},\\quad S_{\\text{vis}}+S_{\\text{dec}}=S_{\\text{total}}$$</div>\n<p>注意这里的偏导数不是常数：<span class=\"sym\">κ_vis</span> 随 <span class=\"sym\">S_vis</span> 增长会因视觉编码器的访存受限而递减，<span class=\"sym\">κ_dec</span> 随 <span class=\"sym\">S_dec</span> 增长受 KV 带宽共享制约。因此切分点必须用实测的 SM 扩展曲线，而不是线性外推。推理系统代价直接体现在吞吐与尾延迟的权衡：切分偏向视觉预填会拉长解码段的 token 间隔，使流式输出的首字节后抖动变大；切分偏向解码则让重视觉请求的预填排队变长，<span class=\"sym\">W_q</span> 上升。</p>\n<p>一个具体例子：同一集群同时承载文档理解（<span class=\"sym\">N_vis</span> 大、<span class=\"sym\">N_out</span> 小）与图表问答（<span class=\"sym\">N_vis</span> 中等、<span class=\"sym\">N_out</span> 中等偏大）。若按单一比例切分 SM，文档类请求在视觉预填段排队，图表类请求在解码段排队，两类 SLO 同时被侵蚀。可行做法是按请求类型做两级调度：为文档类预留更高的 <span class=\"sym\">S_vis</span> 份额，为图表类保留解码 SM 下限，代价是两类都无法吃满全部 SM，峰值吞吐低于单一负载。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-22\">二十二 · 定 KV 预算：批大小与序列长度的乘积约束</h3>\n<p>KV 预算不是独立变量，它被批大小和每请求的 KV 长度共同锁定。多模态请求的 KV 长度包含视觉 token 与文本 token 两部分，因此预算式为</p>\n<div class=\"formula\">$$M_{\\text{kv}}\\ge B\\cdot (N_{\\text{vis}}+N_{\\text{txt}}+N_{\\text{out}})\\cdot s_{\\text{kv}}$$</div>\n<p>其中 <span class=\"sym\">s_kv</span> 是每 token 每层的 KV 字节数。这条约束把时延式的 <span class=\"sym\">B</span> 与显存容量直接耦合：时延反解给出的 <span class=\"sym\">B</span> 若使上式越界，则真实批大小被显存而非 SLO 卡住。工程上要区分两种情形：算力受限时 <span class=\"sym\">B</span> 由时延式定，显存受限时 <span class=\"sym\">B</span> 由预算式定，调度器应取两者较小值并记录是哪一侧生效。这个记录本身就是容量信号——若长期显存受限，说明该加卡或该做 KV 压缩；若长期算力受限，说明切分比例不对。</p>\n<p>机制上，视觉 token 的 KV 占用是预算的主要不确定项：<span class=\"sym\">N_vis</span> 在 patch 合并后仍可能远大于 <span class=\"sym\">N_txt</span>，使同一 <span class=\"sym\">B</span> 下重视觉请求的 KV 占用是轻请求的数倍。因此按平均 <span class=\"sym\">N_vis</span> 定预算会在突发时触发抢占式驱逐，被驱逐请求重算预填，端到端时延出现尖峰。代价是显存碎片与重算算力：预留按最重档做，显存利用率下降；按分档做，需要一套能按请求类型回收与重分配的 KV 池管理，其本身消耗调度周期。</p>\n<p>具体例子：一个批里混入若干高分辨率图像请求，其 <span class=\"sym\">N_vis</span> 使该批 KV 需求越过预算线，调度器若仍按原 <span class=\"sym\">B</span> 接纳，只能驱逐部分请求的 KV。被驱逐者重新走视觉预填与 LLM 预填，等于把已付的预填成本再付一次，端到端时延远超时延式的预测值——这正是预算式与时延式必须联立求解的原因。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-23\">二十三 · 定 SLO：把排队项从稳态估计改成突发估计</h3>\n<p>时延式里的 <span class=\"sym\">W_q</span> 常被按平均到达率与服务率做稳态估算，这是最隐蔽的失效点。多模态请求的到达不是泊松式的平滑流，视觉请求常成批涌入（同一文档的多页、同一相册的多图），瞬时到达率远超均值。稳态排队公式给出的 <span class=\"sym\">W_q</span> 在这种突发下严重偏低，端到端时延失控。工程做法是把 <span class=\"sym\">W_q</span> 拆成两部分：稳态项加突发惩罚项，后者由到达率的方差与批上界共同决定。SLO 的设定因此不能只看均值，要按分位数定：给定 <span class=\"sym\">T_slo</span> 是 P99 还是 P50，直接改变可接纳的 <span class=\"sym\">B</span> 与 SM 切分。</p>\n<p>具体机制是准入控制与批上界联动：当瞬时排队长度超过阈值，调度器降低新请求的接纳批大小，把 SM 从视觉预填临时划给解码以清空队列，代价是这段时间内新到的重视觉请求预填变慢。这是一个显式的时延-吞吐交换：牺牲短时吞吐换取尾延迟不越线。推理系统代价体现在 GPU 利用率上，准入控制期间 SM 有空转，利用率下降，但 SLO 违约率下降。</p>\n<p>另一个误用是把三段时延简单相加而忽略分离式部署的并行重叠。分离式部署中视觉预填与解码可在不同 SM 池上并行，真实时延是关键路径而非求和，简单相加会高估时延并导致过度扩容、GPU 利用率偏低。正确的 SLO 核算应沿关键路径取最大值加排队，而不是三段相加。判断依据是部署形态：若视觉预填与解码共享 SM 池，串行求和近似成立；若分离，必须改用关键路径。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-24\">二十四 · 算例：一次完整的容量决策</h3>\n<p>设某部署的 SLO 为端到端时延上限 <span class=\"sym\">T_slo</span>，两类请求混合：A 类 <span class=\"sym\">N_vis</span> 大、<span class=\"sym\">N_out</span> 小，B 类 <span class=\"sym\">N_vis</span> 中等、<span class=\"sym\">N_out</span> 大。步骤一，对每类分别用线性反解得 <span class=\"sym\">B_lin</span>，再用解码段实测曲线找拐点 <span class=\"sym\">B_knee</span>，取 <span class=\"sym\">B=min(B_lin, B_knee)</span>。步骤二，用 KV 预算式校验该 <span class=\"sym\">B</span> 是否越界，越界则下调并标记显存受限。步骤三，按两类请求的 <span class=\"sym\">N_vis/N_out</span> 比例切分 <span class=\"sym\">S_vis</span> 与 <span class=\"sym\">S_dec</span>，用边际偏导数相等处定切点。步骤四，按突发到达率而非均值估算 <span class=\"sym\">W_q</span>，若 P99 时延越线则启用准入控制。</p>\n<p>这个算例的关键判断在于：A 类请求的 <span class=\"sym\">B_lin</span> 受视觉预填项主导，数值偏小，说明 A 类天然是低并发高预填成本的负载；B 类受解码项主导，<span class=\"sym\">B_knee</span> 更早生效，说明 B 类的批上界由 KV 带宽而非算力决定。两类混跑时，若统一用一个 <span class=\"sym\">B</span>，必然一类欠载一类过载。可行解是分池调度：A 类池配高 <span class=\"sym\">S_vis</span> 份额、小 <span class=\"sym\">B</span>，B 类池配高 <span class=\"sym\">S_dec</span> 份额、<span class=\"sym\">B</span> 卡在拐点。代价是两池都无法在对方空闲时借用 SM，峰值利用率低于统一池，但两类 SLO 同时满足。</p>\n<p>算例暴露的工程判断是：时延式给出的不是单一数字，而是一组联立约束——批大小受时延反解与 KV 预算双重夹逼，SM 切分受边际偏导数与扩展曲线共同决定，SLO 受突发排队与关键路径形态修正。任何一处用线性外推或稳态估计替代实测，都会在某一类请求上表现为 SLO 违约或过度扩容。真正可落地的做法是把这三组约束写进调度器的决策循环，每次接纳新请求时重算一次，而不是离线定一次参数长期沿用。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-25\">二十五 · 容量决策中的误用边界与代价核算</h3>\n<p>把该时延模型直接搬进容量规划，最容易踩的坑是把三段服务时间当成可加项。在分离式预填/解码部署中，视觉预填由独立 worker 承担，与解码 worker 的关键路径并行重叠，端到端时延应取关键路径而非简单求和：$$T_{\\text{e2e}}^{\\text{disagg}}=\\max\\left(\\frac{N_{\\text{vis}}c_{\\text{vis}}}{\\kappa_{\\text{vis}}B_{\\text{vis}}},\\ \\frac{N_{\\text{out}}c_{\\text{dec}}(B_{\\text{dec}})}{\\kappa_{\\text{dec}}B_{\\text{dec}}}\\right)+\\frac{(N_{\\text{vis}}+N_{\\text{txt}})c_{\\text{pre}}}{\\kappa_{\\text{pre}}B_{\\text{pre}}}+W_q$$。若仍按串行公式估算，会把时延高估到接近两段之和，进而按最坏情况扩容，GPU 利用率被压低、SM 预算被浪费在并不存在的串行段上。判断是否已分离部署，是选择求和式还是关键路径式的前置条件，而不是可选的优化项。</p>\n<p>第二个边界在解码段的 $$c_{\\text{dec}}(B)$$。线性模型假设解码吞吐随 batch 线性增长，但 KV cache 带宽竞争使单 token 解码代价随 B 超线性上升；一旦 B 越过 SM 饱和点，真实时延高于线性预测，尾延迟率先突破 SLO。工程上应把解码段写成 $$T_{\\text{dec}}=N_{\\text{out}}\\cdot\\frac{c_{\\text{dec}}(B)}{\\kappa_{\\text{dec}}B}$$ 并在 B 接近饱和点时改用实测曲线或分段线性化，而不是继续外推。定批大小时，先测出饱和点对应的 B*，把在线批大小钳制在 B* 以内，超出部分交给排队或额外副本，而不是硬塞进同一 batch 换取名义吞吐。</p>\n<p>排队项 $$W_q$$ 的失效条件是只看平均到达率。多模态请求常成批涌入（同一用户连发多图、同一文档多页切分），瞬时到达率远高于稳态均值，按平均值算出的 $$W_q$$ 会严重低估真实等待。容量决策应以突发到达下的排队上界为准，并留出预填 worker 的弹性副本。下表给出同一模型在两种部署形态下的决策取向：</p>\n<table class=\"mini\"><thead><tr><th>决策项</th><th>串行共置</th><th>分离式部署</th></tr></thead><tbody><tr><td>时延估算</td><td>三段求和</td><td>关键路径 + 预填段</td></tr><tr><td>SM 分配</td><td>按瓶颈段倾斜</td><td>预填与解码独立配比</td></tr><tr><td>批大小上限</td><td>受饱和点约束</td><td>两段各自饱和点</td></tr><tr><td>KV 预算</td><td>与预填共享</td><td>仅解码侧计入</td></tr></tbody></table>\n<p>算例：某请求 $$N_{\\text{vis}}$$ 大、$$N_{\\text{out}}$$ 小，按模型应把 SM 倾斜给视觉预填；若误用串行求和并把解码段按线性外推，会把扩容预算错配到解码副本上，而真正的瓶颈仍在预填队列，SLO 依旧违约。定 KV 预算时同理：分离式下 KV 只压在解码 worker，按共置模型预留会超额占用显存、压低可并发批数。结论落在机制上——先判定部署形态选公式，再测饱和点定 B，最后用突发到达校准 $$W_q$$，三者任一缺失，模型给出的批大小与并行度都不可信。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-26\">二十六 · 定容决策的边界：串行假设、超线性解码与突发排队</h3>\n<p>把该时延模型用于定批大小、定并行度、定 KV 预算时，第一道边界是<strong>串行假设</strong>。公式把视觉预填、LLM 预填、解码三段直接相加，只在单实例共卡、阶段间无重叠时成立。一旦采用分离式部署，视觉预填的 GPU 池与解码池并行工作，端到端时延应取关键路径：<div class=\"formula\">$$T_{\\text{e2e}}^{\\text{disagg}}=\\max\\!\\left(\\frac{N_{\\text{vis}}c_{\\text{vis}}}{\\kappa_{\\text{vis}}B_{\\text{vis}}},\\ \\frac{(N_{\\text{vis}}+N_{\\text{txt}})c_{\\text{pre}}}{\\kappa_{\\text{pre}}B_{\\text{pre}}}\\right)+\\frac{N_{\\text{out}}c_{\\text{dec}}(B_{\\text{dec}})}{\\kappa_{\\text{dec}}B_{\\text{dec}}}+W_q$$</div>若仍按三段求和估算，容量规划会系统性高估时延，进而过度扩容、GPU 利用率偏低。工程判断是：先确认部署形态，再选求和式或关键路径式，两者不可混用。</p>\n<p>第二道边界在解码段的 $$c_{\\text{dec}}(B)$$。它随批大小超线性上升，因为解码每步都要读全部请求的 KV，KV 带宽竞争随 batch 加剧。线性模型在 B 越过 SM 饱和点后低估时延，线上表现为尾延迟突破 SLO。因此定批大小时不能只解“平均时延 ≤ SLO”，而要在饱和点附近做分段拟合，并对 B 设硬上限。定 KV 预算同理：KV 预算决定了可容纳的 B，而 B 又反过来抬高 $$c_{\\text{dec}}$$，二者需联立求解而非各自拍板。</p>\n<p>第三道边界是排队项 $$W_q$$。它由到达率与服务率决定，但视觉请求常成批涌入，稳态平均到达率会严重低估瞬时排队。仅按均值定并行度，突发时端到端时延失控。可行做法是把 $$W_q$$ 按峰值到达率而非均值估算，或在调度层对视觉请求做准入与错峰。下表给出三种误用与对应代价：</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>系统代价</th><th>纠正</th></tr></thead><tbody><tr><td>分离式部署仍串行求和</td><td>过度扩容，利用率低</td><td>改用关键路径式</td></tr><tr><td>大 batch 沿用线性 $$c_{\\text{dec}}$$</td><td>低估 KV 带宽竞争，SLO 违约</td><td>饱和点分段拟合并设 B 上限</td></tr><tr><td>按均值估 $$W_q$$</td><td>突发下排队失控</td><td>按峰值到达率估算并准入控制</td></tr></tbody></table>\n<p>算例思路：当 $$N_{\\text{vis}}$$ 大而 $$N_{\\text{out}}$$ 小时，瓶颈在视觉预填，应把 SM 倾斜给视觉池并压低解码批；反之倾斜解码。但倾斜后若解码 B 抬高越过饱和点，$$c_{\\text{dec}}$$ 的超线性项会吃掉收益，此时应优先扩 KV 预算或拆分解码池，而不是继续加批。</p>\n<h3 id=\"th-multimodal-batch-latency-sec-27\">二十七 · 误用一：把三段串联当成可加，忽略关键路径重叠</h3>\n<p>最常见的误用是把公式里的三项直接相加，得到一个\"总时延\"，然后拿这个数去定容量。问题在于公式的适用边界写得很清楚：各阶段串行不重叠。一旦部署形态是分离式预填/解码，视觉预填跑在预填实例上、解码跑在解码实例上，两段在时间轴上就发生重叠——视觉预填处理第 i+1 个请求的同时，解码实例正在吐第 i 个请求的 token。此时端到端时延由关键路径决定，而不是三段服务时间之和。</p>\n<p>用伪代码表达两种估算的差别：</p>\n<div class=\"formula\">$$\\begin{aligned}\nT_{\\text{serial}} &amp;= t_{\\text{vis}} + t_{\\text{pre}} + t_{\\text{dec}} + W_q \\\\\nT_{\\text{critical}} &amp;= \\max\\big(t_{\\text{vis}} + t_{\\text{pre}},\\; t_{\\text{dec}}\\big) + W_q + t_{\\text{handoff}}\n\\end{aligned}$$</div>\n<p>其中 $$t_{\\text{handoff}}$$ 是视觉 embedding 或 KV 从预填实例传到解码实例的代价，在 NVL72 域内由 NVLink 5 承担，跨节点则要过 RDMA，量级不同。串行估算把 $$t_{\\text{vis}}+t_{\\text{pre}}$$ 与 $$t_{\\text{dec}}$$ 都算进总账，等于假设解码必须等预填全部完成才能开始——这只有在单实例、单请求、无流水的情况下成立。</p>\n<p>后果是系统性的高估。假设某请求 $$N_{\\text{vis}}=4096$$、$$N_{\\text{out}}=64$$，视觉预填与 LLM 预填合计占服务时间的大头，解码段相对短。串行估算会把两段相加，得出一个远大于实际关键路径的数；容量规划据此扩容，GPU 利用率被压在低位，而线上真实尾延迟并没有那么差。识别方法很直接：把线上 trace 的预填完成时刻与首 token 发出时刻对齐，若两者在时间上交错（预填实例在处理新请求时解码实例仍在吐旧请求的 token），就说明串行假设已失效，估算必须换成关键路径形式。更细的识别信号是预填实例与解码实例的 SM 利用率曲线是否呈现互补的相位——若两条曲线此起彼伏而非同涨同落，重叠确实在发生。</p>\n<p>工程判断上，串行模型只应作为上界使用：它给出\"最坏情况不会超过多少\"，用于保守兜底；真正的容量决策要用关键路径模型，并且把 $$t_{\\text{handoff}}$$ 显式计入。若 handoff 走的是跨节点链路，这一项可能不可忽略，尤其在视觉 token 数量大、embedding 张量宽的场景下，传输量与 $$N_{\\text{vis}}$$ 成正比。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-28\">二十八 · 误用二：大 batch 下沿用线性解码系数</h3>\n<p>第二个误用更隐蔽：把 $$c_{\\text{dec}}(B)$$ 当成常数，或至少当成随 B 线性变化的量。公式里这个符号显式写成 $$c_{\\text{dec}}(B)$$，就是为了提醒它依赖批大小。解码阶段每个 token 都要读一遍 KV cache，batch 增大时多个请求的 KV 读取在同一组 SM 上竞争 HBM 带宽，单 token 的有效吞吐系数不再线性增长，而是随 B 增大出现超线性上升的服务时间——也就是每 token 的边际成本递增。</p>\n<p>用伪代码描述线性假设与真实行为的偏差：</p>\n<div class=\"formula\">$$\\begin{aligned}\nT_{\\text{dec}}^{\\text{lin}} &amp;= N_{\\text{out}}\\cdot\\frac{c_{\\text{dec}}^{\\text{const}}}{\\kappa_{\\text{dec}} B} \\\\\nT_{\\text{dec}}^{\\text{real}} &amp;= N_{\\text{out}}\\cdot\\frac{c_{\\text{dec}}(B)}{\\kappa_{\\text{dec}} B},\\quad \\frac{\\partial c_{\\text{dec}}}{\\partial B}&gt;0\n\\end{aligned}$$</div>\n<p>线性假设在 B 小于 SM 饱和点时误差可控，因为此时 KV 带宽尚未成为瓶颈，增加 batch 主要是在填满空闲的算力。一旦 B 越过饱和点，KV 带宽竞争开始主导，$$c_{\\text{dec}}(B)$$ 的超线性项被激活，线性模型系统性低估解码段时延。后果是 SLO 违约：容量规划按线性模型算出\"这个 batch 下解码段只要 X 毫秒\"，实际跑起来是 X 的若干倍，尾延迟突破阈值，而扩容决策已经按错误的数做完。</p>\n<p>识别方法有三条。其一，做 batch 扫描：固定 $$N_{\\text{vis}}$$、$$N_{\\text{out}}$$，把 B 从 1 逐步拉高，记录每 token 解码时间，画出的曲线若在某个 B 之后斜率变陡，饱和点就在那里。其二，看 KV cache 带宽占用率与 SM 利用率的比值：解码阶段若带宽占用率先于 SM 利用率饱和，说明瓶颈已从算力转向带宽，线性模型不再成立。其三，比对线上 P99 与模型预测的偏差随 B 的变化——若偏差随 B 单调放大，就是超线性项在起作用。工程上应把 $$c_{\\text{dec}}(B)$$ 做成一张按 B 分段的查找表或分段函数，而不是一个常数；在 B 接近饱和点时主动限流，把 batch 控制在饱和点以下，用略低的吞吐换稳定的尾延迟。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-29\">二十九 · 误用三：用平均到达率估排队项</h3>\n<p>第三个误用出在 $$W_q$$ 上。排队项由到达率与服务率决定，很多实现只拿稳态平均到达率代入，得到一个平滑的排队估计。但多模态请求的到达不是泊松式的均匀流：视觉请求常以批量形式涌入——一批用户同时上传图片、一个批处理任务一次性提交上千条带图请求、某个前端页面触发一轮集中调用。突发到达下，瞬时到达率远超均值，排队时间被放大到远超稳态估计的水平。</p>\n<p>机制上，排队时间对到达率的敏感度是非线性的。用 $$λ$$ 表示到达率、$$μ$$ 表示服务率，利用率 $$ρ=λ/μ$$，在接近饱和时排队项随 $$ρ$$ 急剧上升：</p>\n<div class=\"formula\">$$W_q \\;\\propto\\; \\frac{ρ}{1-ρ}\\quad\\text{（稳态近似）}$$</div>\n<p>当 $$ρ$$ 从 0.7 抬到 0.9，$$ρ/(1-ρ)$$ 从约 2.3 涨到 9，排队时间放大近四倍。突发到达把瞬时 $$ρ$$ 推得更高，$$W_q$$ 的估计若只用平均 $$λ$$，就会把这段放大完全漏掉。后果是端到端时延失控：模型预测\"排队几十毫秒\"，线上实际是几百毫秒甚至更多，且集中在突发窗口内，表现为周期性的尾延迟尖峰。</p>\n<p>识别方法是看排队时间的分布而非均值：把线上 $$W_q$$ 的 P50 与 P99 拉出来对比，若 P99 远高于 P50 且尖峰与请求到达的批处理节奏对齐，就说明平均到达率假设失效。工程对策是在模型里引入到达过程的二阶特征——至少区分稳态流与突发流两种模式，对突发模式用峰值到达率而非均值估算 $$W_q$$，并在调度层面对视觉请求做入口整形（令牌桶或漏桶），把突发削平后再进批调度器。整形会牺牲一点入口延迟，但换来的是可预测的排队上界。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-30\">三十 · 反例：一次把三个误用叠在一起的容量决策</h3>\n<p>构造一个反例，把上面三个误用叠在一起，看后果如何级联。场景：某服务部署了分离式预填/解码，视觉预填实例与解码实例各占一组 SM，请求以批处理任务形式到达，每批一次性提交大量带图请求，每请求 $$N_{\\text{vis}}$$ 大、$$N_{\\text{out}}$$ 小。</p>\n<p>规划者的做法是：用串行公式估算单请求时延，把视觉预填、LLM 预填、解码三段相加；解码系数取一个小 batch 下测得的常数；排队项用日平均到达率代入。三个假设各自都\"看起来合理\"，叠在一起却全部指向同一个方向——低估。</p>\n<ul>\n<li>串行相加高估了单请求服务时间，但因为忽略了重叠，规划者误以为需要更多预填实例才能压住时延，把 SM 大量倾斜到视觉预填，解码实例反而配置不足。</li>\n<li>解码系数取常数，低估了解码段在大 batch 下的真实耗时；而由于解码实例配置不足，实际运行时解码 batch 被迫拉得更大，正好落进超线性区间，尾延迟进一步恶化。</li>\n<li>排队项用日均到达率，完全没看到批处理任务的突发节奏；每次批量提交都把瞬时 $$ρ$$ 推高，$$W_q$$ 尖峰出现，而模型预测里根本没有这一项。</li>\n</ul>\n<p>结果是三重偏差同向叠加：预填侧过度配置、解码侧配置不足、排队被低估。线上表现为解码实例持续高负载、尾延迟周期性突破 SLO，而预填实例利用率偏低。规划者看到预填利用率低，第一反应是\"再砍预填、加解码\"，但因为串行模型仍在使用，砍预填后单请求估算时延上升，又被误读为\"不能砍\"，陷入来回摇摆。</p>\n<p>正确的做法是把三个假设逐个拆掉：用关键路径模型替代串行求和，把 $$t_{\\text{handoff}}$$ 计入；用按 B 分段的 $$c_{\\text{dec}}(B)$$ 替代常数，并在饱和点附近限流；用峰值到达率或到达过程的二阶特征估算 $$W_q$$，并在入口做整形。三者拆完后，容量决策的方向会反过来：预填资源可以适度回收，解码资源需要补足，且解码 batch 要设上限。这个反例的价值在于说明误用不是孤立的——它们往往同向叠加，让估算偏差被放大而不是相互抵消，因此识别时要三个假设一起查，而不是逐个修补。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-31\">三十一 · 识别清单：把误用挡在决策之前</h3>\n<p>把识别动作固化成一份可在容量评审时逐条过的清单，比事后追查尾延迟更省成本。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>检查项</th><th>失效信号</th><th>替代做法</th></tr>\n</thead>\n<tbody>\n<tr><td>部署形态是否分离</td><td>预填与解码 SM 利用率曲线相位互补</td><td>改用关键路径模型，计入 handoff</td></tr>\n<tr><td>解码系数是否随 B 变化</td><td>带宽占用率先于 SM 利用率饱和</td><td>按 B 分段建表，饱和点附近限流</td></tr>\n<tr><td>排队项是否用均值</td><td>$$W_q$$ 的 P99 远高于 P50 且与批处理节奏对齐</td><td>用峰值到达率，入口整形</td></tr>\n<tr><td>模型预测与线上 P99 偏差</td><td>偏差随 B 或随突发强度单调放大</td><td>定位是哪一项假设在放大偏差</td></tr>\n</tbody>\n</table>\n<p>这张表的关键在于最后一行：单看某一项假设很难判断它是否失效，但把模型预测与线上 P99 的偏差按 B、按到达突发强度做二维切片，偏差的放大方向会直接指向失效的那一项。若偏差随 B 放大，查解码系数；若偏差随突发强度放大，查排队项；若偏差在两个维度上都不放大但绝对值始终偏高，查串行假设。这个诊断顺序把\"哪个假设错了\"从猜测变成可观测的推断。</p>\n<p>代价方面，做这套检查本身要花工程时间：batch 扫描要占用测试资源，trace 对齐要埋点，入口整形要改调度路径。但相比按错误模型扩容后线上尾延迟违约、再回头返工的成本，这笔投入是划算的。尤其在多模态场景下，视觉 token 数跨度大、输出长度跨度大，单一常数模型几乎必然在某段区间失效，分段建模是绕不开的工程选择。</p>\n\n<h3 id=\"th-multimodal-batch-latency-sec-32\">三十二 · 落在调度器上的一条硬约束</h3>\n<p>所有误用最终都会落到同一个工程判断上：批调度器不能只按一个标量时延目标做决策，它必须知道自己所处的工作区间。具体机制是，调度器在每次组批时读取当前 B 与饱和点的关系、当前到达流的突发标记、以及部署形态是否分离，据此选择用哪一套时延估算——分离部署走关键路径，B 接近饱和点走分段解码系数，突发窗口走峰值排队估计。这三者不是三套模型，而是同一个公式在不同区间取不同参数与不同路径组合。</p>\n<p>把这条约束写成调度器的一条伪代码判断：</p>\n<div class=\"formula\">$$\\text{est}(B)=\\begin{cases}\n\\max(t_{\\text{vis}}+t_{\\text{pre}},\\,t_{\\text{dec}}(B))+W_q^{\\text{peak}}, &amp; \\text{分离部署且突发窗口}\\\\\nt_{\\text{vis}}+t_{\\text{pre}}+t_{\\text{dec}}(B)+W_q, &amp; \\text{单实例串行}\\\\\n\\text{限流至 }B&lt;B_{\\text{sat}}, &amp; B\\ge B_{\\text{sat}}\n\\end{cases}$$</div>\n<p>这条判断的代价是调度器要多维护几个状态量：饱和点 $$B_{\\text{sat}}$$ 的在线估计、突发标记、部署拓扑。收益是时延估算不再系统性偏向某一侧，容量决策有了可解释的依据。落在具体机制上，这就是把\"误用识别\"从评审阶段前移到运行时——调度器自己知道自己站在哪个区间，而不是等线上尾延迟违约后再回头查模型。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>N_{\\text{vis}}</td><td>每请求视觉 token 数（含 patch 合并后）</td></tr><tr><td>N_{\\text{out}}</td><td>生成 token 数</td></tr><tr><td>B</td><td>并发批大小</td></tr><tr><td>\\kappa_{\\text{vis}},\\ \\kappa_{\\text{pre}},\\ \\kappa_{\\text{dec}}</td><td>各阶段单位 token 的吞吐系数（token/s per SM）</td></tr><tr><td>W_q</td><td>排队等待时间，由到达率与服务率决定</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-multimodal-batch-latency · 共 5 个片段</p>\n"},{"id":"th-vlm-quant-error","title":"VLM 量化误差上界","direction":"dir-multimodal-batching","prereq":[],"plain":"把视觉编码器与 LLM 分别量化到 b 比特时，输出误差可分解为权重舍入误差与激活离群值误差之和；视觉 token 的动态范围远大于文本，激活量化误差往往主导，需要 per-channel 或 SmoothQuant 式缩放。","definition":"把视觉编码器与 LLM 分别量化到 b 比特时，输出误差可分解为权重舍入误差与激活离群值误差之和；视觉 token 的动态范围远大于文本，激活量化误差往往主导，需要 per-channel 或 SmoothQuant 式缩放。","formula":"$$\\|\\hat{y}-y\\|_2\\ \\le\\ \\|W\\|_2\\cdot\\Delta_W\\cdot\\|x\\|_2+\\|W\\|_2\\cdot\\Delta_x\\cdot\\|x\\|_2+\\varepsilon_{\\text{cal}}$$","variables":[{"sym":"\\Delta_W","meaning":"权重量化步长，约等于 max|W|/(2^{b-1}-1)"},{"sym":"\\Delta_x","meaning":"激活量化步长，受视觉 token 离群值支配"},{"sym":"\\|W\\|_2","meaning":"权重矩阵谱范数"},{"sym":"\\varepsilon_{\\text{cal}}","meaning":"校准集不匹配引入的额外偏差"}],"derivation":"推导关键一步是用算子范数把量化扰动传播到输出：权重扰动项 $$\\|W\\|_2\\Delta_W\\|x\\|_2$$ 与激活扰动项 $$\\|W\\|_2\\Delta_x\\|x\\|_2$$ 相加，再加校准偏差，得到误差上界；因此缩小 $$\\Delta_x$$ 需 per-channel 或 SmoothQuant 式缩放。","example":"在容量决策中，该上界用于判断视觉侧能否安全降到 FP8 或更低：若激活项主导，则必须保留较高精度或引入通道缩放，否则精度损失会迫使回退到 BF16 并抵消显存收益。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["上界基于算子范数，实际误差可能因误差抵消而远低于该界，不能直接当作精度预测","假设量化噪声与信号不相关；视觉 token 中存在强离群通道时该假设失效，需先做通道缩放"],"system_note":"常见误用是把上界当作精度预测直接决定量化位宽，实际误差远低于上界时过度保守；另一误用是忽略视觉 token 离群通道直接做 per-tensor 激活量化，激活误差主导导致输出崩坏。","papers":["paper-an-image-is-worth-16x16-words-transf-2020"],"facts":["直觉上，视觉编码器与 LLM 分别量化到 b 比特后，输出误差可分解为权重舍入误差与激活离群值误差之和，视觉 token 动态范围远大于文本，激活量化误差往往主导。","公式中 $$\\Delta_W$$ 为权重量化步长，约等于 $$\\max|W|/(2^{b-1}-1)$$；$$\\Delta_x$$ 为激活量化步长，受视觉 token 离群值支配；$$\\|W\\|_2$$ 为权重矩阵谱范数；$$\\varepsilon_{\\text{cal}}$$ 为校准集不匹配引入的额外偏差。","推导关键一步是用算子范数把量化扰动传播到输出：权重扰动项 $$\\|W\\|_2\\Delta_W\\|x\\|_2$$ 与激活扰动项 $$\\|W\\|_2\\Delta_x\\|x\\|_2$$ 相加，再加校准偏差，得到误差上界；因此缩小 $$\\Delta_x$$ 需 per-channel 或 SmoothQuant 式缩放。","适用边界是量化噪声与信号不相关；视觉 token 存在强离群通道时该假设失效，需先做通道缩放；上界基于算子范数，实际误差可能因误差抵消远低于该界，不能直接当作精度预测。","在容量决策中，该上界用于判断视觉侧能否安全降到 FP8 或更低：若激活项主导，则必须保留较高精度或引入通道缩放，否则精度损失会迫使回退到 BF16 并抵消显存收益。","常见误用是把上界当作精度预测直接决定量化位宽，实际误差远低于上界时过度保守；另一误用是忽略视觉 token 离群通道直接做 per-tensor 激活量化，激活误差主导导致输出崩坏。"],"anchors":["FP16=2","FP8=1","未给出"],"pitfalls":["把算子范数上界当作实际精度预测来选量化位宽，误差抵消使真实误差远低于上界，量化收益被无谓放弃。","对视觉 token 直接做 per-tensor 激活量化而不处理离群通道，激活误差项主导，输出质量断崖式下降。","校准集与线上视觉分布不匹配导致 $$\\varepsilon_{\\text{cal}}$$ 偏大，离线指标正常但线上精度漂移，且难以归因到量化。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-1\">一 · 一句话直觉与它为什么成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-2\">二 · 严格定义：上界是什么、不是什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-3\">三 · 为什么推理系统必须持有这个界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-4\">四 · 常见误解之一：把上界当精度预测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-5\">五 · 常见误解之二：per-tensor 激活量化直接上视觉 token</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-6\">六 · 界的适用边界与工程判断落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-7\">七 · 上界不是精度预测：算子范数界的适用边界与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-8\">八 · 三项分解：上界从哪里长出来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-9\">九 · 算子范数：把扰动传到输出的关键一步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-10\">十 · 离散化与近似：三处不严谨的地方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-11\">十一 · 缩放如何改写上界：SmoothQuant 式的通道搬移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-12\">十二 · 校准项与容量决策的接口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-13\">十三 · 上界的边界：算子范数放大、噪声不相关假设与视觉离群通道</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-14\">十四 · 算子范数传播链的隐含前提</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-15\">十五 · 不相关假设在离群通道上的崩塌</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-16\">十六 · 校准偏差 ε_cal 的规模依赖</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-17\">十七 · 规模上限：批次、序列与并行维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-18\">十八 · 什么情况下公式不再成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-19\">十九 · 边界不在公式里，在假设里：算子范数上界何时失去解释力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-20\">二十 · 把上界翻译成可执行的容量约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-21\">二十一 · KV 预算与误差预算的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-22\">二十二 · 用上界定 SLO：延迟与质量的联合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-23\">二十三 · 算例：从误差预算反推部署参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-24\">二十四 · 误用模式与工程护栏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-25\">二十五 · 把上界换算成批大小、并行度与 KV 预算的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-26\">二十六 · 误用一：把范数界当精度预测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-27\">二十七 · 误用二：per-tensor 激活量化不处理离群通道</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-28\">二十八 · 误用三：校准集不匹配，ε_cal 悄悄吃掉预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-29\">二十九 · 一个反例：端到端崩坏的全过程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-30\">三十 · 工程判断：三条可执行的检查线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-quant-error-sec-31\">三十一 · 误用与反例：把上界当精度预测、把离群通道当噪声</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:597px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 597.1 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：把视觉编码器与 LLM 分别量化到 b 比特时，输出误差可分解为权…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\|\\hat{y}-y\\|_2\\ \\le\\ \\|W\\|_2\\c…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：上界基于算子范数，实际误差可能因误差抵消而远低于该界，不能直接当作…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-vlm-quant-error-sec-1\">一 · 一句话直觉与它为什么成立</h3>\n<p>把视觉编码器和 LLM 都量化到 b 比特之后，你看到的输出偏差不是一团混沌，而是两项可加的量：一项来自权重被舍入到网格上，另一项来自视觉激活被压进量化区间时越界或截断。视觉 token 的动态范围远大于文本 token，所以第二项常常比第一项大一个量级——这就是“激活主导”的直觉来源。它成立的物理基础很直接：权重的分布由训练决定，量化前可以做 per-channel 缩放把它压得比较规整；而视觉激活的分布由输入图像决定，一张高对比度照片里少数通道的幅值可以是其余通道的几十倍，per-tensor 一个步长根本盖不住。</p>\n<p>把这个直觉写成可计算的量，才有工程价值。设某一层权重矩阵为 <span class=\"sym\">W</span>、输入激活为 <span class=\"sym\">x</span>，量化后的输出偏差满足</p>\n<div class=\"formula\">$$\\|\\hat{y}-y\\|_2\\ \\le\\ \\|W\\|_2\\cdot\\Delta_W\\cdot\\|x\\|_2+\\|W\\|_2\\cdot\\Delta_x\\cdot\\|x\\|_2+\\varepsilon_{\\text{cal}}$$</div>\n<p>两项结构完全对称，都是“算子范数 × 量化步长 × 输入范数”。差别只在 <span class=\"sym\">\\(\\Delta_W\\)</span> 和 <span class=\"sym\">\\(\\Delta_x\\)</span> 谁更大：前者约等于 <span class=\"sym\">\\(\\max|W|/(2^{b-1}-1)\\)</span>，由权重极值决定；后者由视觉 token 的离群通道决定，且没有 per-channel 缩放时它取的是整个张量的极值。这就是为什么同一套 b 比特配置在纯文本上安然无事，接到视觉塔上就出问题。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-2\">二 · 严格定义：上界是什么、不是什么</h3>\n<p>这个不等式是一个<em>算子范数传播界</em>，不是误差的期望值，也不是方差估计。推导的关键一步是把量化视为对输入的加性扰动 <span class=\"sym\">\\(\\delta x\\)</span> 与对权重的扰动 <span class=\"sym\">\\(\\delta W\\)</span>，然后用谱范数把扰动放大到输出空间：<span class=\"sym\">\\(\\|W\\delta x\\|_2 \\le \\|W\\|_2\\|\\delta x\\|_2\\)</span>，而 <span class=\"sym\">\\(\\|\\delta x\\|_2\\)</span> 又被步长与输入范数的乘积所界住。逐层复合即得全局界。它成立需要三个前提：量化噪声与信号不相关（否则交叉项不为零）、扰动幅值被步长一致地界住（即没有饱和截断之外的非线性失真）、以及校准统计量覆盖线上分布。</p>\n<p>因此它的语义是“最坏情况下的偏差天花板”，而不是“你会观测到的偏差”。工程上必须区分两个用途：用作<strong>可行性判据</strong>时它是可靠的——如果连上界都小到可以接受，那这条路径一定安全；用作<strong>位宽选择依据</strong>时它是危险的——真实误差常因层间误差抵消而远低于界，按界选位宽会系统性地过度保守。第三个前提里的 <span class=\"sym\">\\(\\varepsilon_{\\text{cal}}\\)</span> 是校准集不匹配引入的额外偏差，它不在范数传播的框架内，是纯粹的数据分布项：校准用的图文对与线上流量若在分辨率、长宽比、色彩分布上不同，这一项就会单独抬头，且无法通过调 b 比特消除。</p>\n<p>代价维度上，这个界本身不消耗任何运行时资源，但它的三个输入量都有代价含义。<span class=\"sym\">\\|W\\|_2</span> 的估计需要一次谱范数计算，在百亿参数模型上是一次可观的离线开销；<span class=\"sym\">\\(\\Delta_x\\)</span> 的准确估计要求在校准阶段跑一遍视觉塔的前向并记录逐通道极值，这会把校准从“跑几十个 batch”变成“跑一遍完整视觉编码器”，显存峰值上升，因为要保留中间激活统计。而 <span class=\"sym\">\\(\\varepsilon_{\\text{cal}}\\)</span> 只能靠线上采样回灌来压，属于持续运维成本。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-3\">三 · 为什么推理系统必须持有这个界</h3>\n<p>容量规划的核心问题是：视觉侧能不能安全地降到 FP8 甚至更低。FP16 到 FP8 是每元素字节数减半，直接换算成显存与带宽收益；但收益是否兑现，取决于激活项是否可控。若 <span class=\"sym\">\\(\\|W\\|_2\\Delta_x\\|x\\|_2\\)</span> 在总界中占主导，那么降位宽不会带来可用的精度，反而会因为精度损失迫使回退到 BF16，把显存收益原路抵消——这是最典型的“量化了个寂寞”场景。反过来，如果权重项主导，说明瓶颈在权重舍入，此时 per-channel 权重量化或更高比特的权重保留才是正确杠杆，动激活精度是白费力气。</p>\n<p>这个界还承担一个归因功能。线上出现精度漂移时，三项分别指向三种不同的修复动作：权重项大 → 调权重缩放粒度；激活项大 → 上通道缩放；<span class=\"sym\">\\(\\varepsilon_{\\text{cal}}\\)</span> 大 → 换校准集。没有这个分解，工程师只能靠试。举例来说，一个视觉问答服务在换用 FP8 后离线评测正常、线上长尾图片答错率上升，若把三项拆开看，权重项与激活项都稳定，唯独 <span class=\"sym\">\\(\\varepsilon_{\\text{cal}}\\)</span> 因校准集里缺少极端长宽比样本而偏大，修复动作就非常明确，不需要回退整个量化方案。</p>\n<p>在批调度层面它也有间接作用：量化位宽决定每层激活的字节数，进而决定视觉预填阶段的显存带宽压力。激活项主导意味着你必须保留较高精度，也就意味着预填阶段的带宽占用无法压缩，连续批处理中视觉请求与文本请求混排时的显存水位会更高。这个链条把“一个数学界”与“一个调度参数”连了起来。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-4\">四 · 常见误解之一：把上界当精度预测</h3>\n<p>最普遍的误用是把不等式的右端直接当成“量化后精度会掉这么多”，据此选位宽。问题在于算子范数界对最坏方向取放大，而真实网络里相邻层的扰动经常反号相消：一层的激活被系统性高估、下一层的权重舍入又把它拉回，净效应远小于逐层界的简单相加。这在视觉塔里尤其明显，因为 ViT 类的残差结构与 LayerNorm 会把幅值重新归一化，抑制扰动的累积。</p>\n<p>后果是量化收益被无谓放弃：本来 FP8 完全够用的视觉塔，因为界看起来吓人而被留在 BF16，显存与带宽双输。正确的用法是把界当作<strong>筛选器</strong>而非<strong>预测器</strong>——先用它排除明显不安全的配置（例如 per-tensor 激活量化加 4 比特），再在小规模校准集上实测候选配置的真实误差，用实测值做最终决策。界负责保证你不会踩进坑里，实测负责告诉你坑有多远。</p>\n<p>还有一个变体误用：把界里的 <span class=\"sym\">\\|x\\|_2</span> 用校准集的平均范数代入，得到一个偏小的数值，误以为激活项不主导。视觉输入的范数分布是重尾的，平均值远低于长尾样本，用均值代入等于把最坏情况藏起来。要么用分位数，要么承认这个界在重尾分布下会低估。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-5\">五 · 常见误解之二：per-tensor 激活量化直接上视觉 token</h3>\n<p>第二个高频错误是不处理离群通道就对视觉 token 做 per-tensor 激活量化。视觉 token 的通道间动态范围差异极大：某些通道承载高频纹理或强边缘信息，幅值远超其余通道。per-tensor 一个步长意味着 <span class=\"sym\">\\(\\Delta_x\\)</span> 被最大通道的极值钉死，其余通道的有效比特数被严重浪费，等效于用很粗的网格去表示大部分信息。此时激活项 <span class=\"sym\">\\(\\|W\\|_2\\Delta_x\\|x\\|_2\\)</span> 直接主导总界，输出质量断崖式下降，表现为细粒度识别、小目标定位、文字 OCR 类任务首先崩坏。</p>\n<p>修复路径就是缩小 <span class=\"sym\">\\(\\Delta_x\\)</span>：per-channel 缩放给每个通道独立的步长，把离群通道单独隔离；SmoothQuant 式缩放则把激活的离群幅值按比例迁移到权重上，使两侧的量化难度均衡。这两种手段都在不改变比特数的前提下把激活项压下来，代价是额外的缩放因子存储与逐通道乘加——在视觉塔的通道数规模上，这部分开销相对矩阵乘可以忽略，但它会打断原本融合的算子，增加一次额外的读写，属于典型的“用带宽换精度”。</p>\n<p>这里还有一个与失效条件直接相关的判断：一旦做了通道缩放，量化噪声与信号不相关的假设就更容易成立，因为缩放把离群通道的量化误差从“与信号强相关”变成了“近似均匀分布”。反过来说，如果你观察到缩放后误差并未如预期下降，往往说明离群不是通道级的而是 token 级的（例如个别图像整体过曝），此时需要的是 per-token 或分组量化，而不是继续在通道维度上加粒度。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-6\">六 · 界的适用边界与工程判断落点</h3>\n<p>把三条边界记住，这个界就不会被误用。第一，噪声与信号不相关是前提，视觉 token 存在强离群通道时该假设失效，必须先做通道缩放再谈界；第二，界基于算子范数，是天花板不是预测，误差抵消会让真实值远低于它；第三，<span class=\"sym\">\\(\\varepsilon_{\\text{cal}}\\)</span> 是分布项，与比特数无关，校准集与线上视觉分布不匹配时它会单独抬头，离线指标正常而线上漂移，且难以归因到量化本身。</p>\n<p>落到工程判断上，一个可操作的决策顺序是：先测三项的相对大小，若激活项主导则先上通道缩放再考虑降比特，若权重项主导则调权重粒度，若 <span class=\"sym\">\\(\\varepsilon_{\\text{cal}}\\)</span> 显著则先修校准集再谈位宽。这个顺序的价值在于它把“要不要降精度”从一次赌博变成一次分解——每一项都对应一个具体的、代价可估的修复动作，而不是笼统地回退到 BF16。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-7\">七 · 上界不是精度预测：算子范数界的适用边界与代价</h3>\n<p>本节的落点不是重复误差分解，而是回答一个工程问题：这个界在什么条件下能用、什么时候会骗人、以及为收紧它要付出什么代价。上界由三项相加构成：权重扰动项、激活扰动项与校准偏差项，其中激活项受视觉 token 离群值支配，是视觉侧量化能否降到 FP8 及以下的主导判据。关键在于，该界通过算子范数把量化扰动线性放大到输出，属于最坏情况包络，而非期望误差。</p>\n<div class=\"formula\">$$\\|\\hat{y}-y\\|_2\\ \\le\\ \\|W\\|_2\\cdot\\Delta_W\\cdot\\|x\\|_2+\\|W\\|_2\\cdot\\Delta_x\\cdot\\|x\\|_2+\\varepsilon_{\\text{cal}}$$</div>\n<p>失效条件有三类，必须逐条核对。其一，推导假设量化噪声与信号不相关；视觉 token 存在强离群通道时该假设破裂，per-tensor 激活量化的误差不再均匀分布，此时必须先做通道缩放再谈上界。其二，误差在真实网络中存在抵消，实际偏差可远低于该界，因此拿上界直接选位宽会系统性过度保守——FP8 相对 FP16 的显存收益是二比一，若因上界偏大而回退 BF16，收益归零。其三，校准集与线上视觉分布不匹配会抬高校准偏差项，离线指标正常而线上漂移，且难以归因到量化本身。</p>\n<table class=\"mini\"><thead><tr><th>收紧手段</th><th>作用项</th><th>系统代价</th></tr></thead><tbody><tr><td>per-channel 权重量化</td><td>权重项</td><td>反量化开销上升，MMA 前的重排增加延迟</td></tr><tr><td>SmoothQuant 式通道缩放</td><td>激活项</td><td>需校准统计与额外逐通道乘，占用带宽</td></tr><tr><td>扩大校准集覆盖</td><td>校准偏差项</td><td>离线标定时间与显存占用增加</td></tr></tbody></table>\n<p>工程判断应落在容量决策上：先测激活项与权重项的相对量级，若激活项主导，则视觉侧不能只靠降位宽，必须保留较高精度或引入通道缩放，否则精度损失会迫使回退并抵消显存收益；若权重项主导，per-channel 权重缩放是低代价选项。上界的正确用法是作为可行性筛子——它能否定一条量化路径，但不能肯定某位宽的实际精度。</p>\n<h3 id=\"th-vlm-quant-error-sec-8\">八 · 三项分解：上界从哪里长出来</h3>\n<p>把视觉编码器与 LLM 分别量化到 b 比特后，输出误差写成三项相加，是这套推导的骨架。第一项是权重舍入误差，第二项是激活量化误差，第三项是校准偏差。三项并非并列的独立来源，而是按扰动传播路径排列：权重与激活的量化扰动先各自在算子内部被放大，再叠加到输出，最后加上校准集与线上分布不一致带来的系统偏移。写成式子就是</p>\n<div class=\"formula\">$$\\|\\hat{y}-y\\|_2\\ \\le\\ \\|W\\|_2\\cdot\\Delta_W\\cdot\\|x\\|_2+\\|W\\|_2\\cdot\\Delta_x\\cdot\\|x\\|_2+\\varepsilon_{\\text{cal}}$$</div>\n<p>逐项读：$$\\Delta_W$$ 是权重量化步长，由权重张量的最大绝对值与位宽共同决定，$$\\Delta_W \\approx \\max|W|/(2^{b-1}-1)$$，位宽每降一档，步长翻倍，这一项线性膨胀。$$\\Delta_x$$ 是激活量化步长，它不由位宽单独决定，而由视觉 token 的动态范围支配——同一个 b 比特，文本激活的步长可以很小，视觉激活的步长却可能大出一个量级。$$\\|W\\|_2$$ 是权重矩阵的谱范数，它充当扰动到输出的增益系数：谱范数越大，同样的量化步长被放大得越狠。$$\\varepsilon_{\\text{cal}}$$ 是校准集不匹配引入的额外偏差，它不随位宽变化，但在分布漂移时成为主导项。</p>\n<p>这个分解的工程含义在于：三项的相对大小决定了量化策略的方向。若第一项主导，说明权重侧动态范围大，需要 per-channel 权重量化或分组缩放；若第二项主导，说明激活侧离群值严重，per-tensor 激活量化必然失效，必须上通道缩放。视觉 token 恰恰落在后一种情形——它的动态范围远大于文本，激活项往往压过权重项。以 FP16 到 FP8 的一档降位为例，位宽从 2 的有效精度档降到 1，$$\\Delta_W$$ 与 $$\\Delta_x$$ 同步翻倍，但视觉激活的 $$\\Delta_x$$ 基数本就更大，翻倍后激活项直接吃掉上界的主要份额，这就是“视觉侧降精度先崩”的公式来源。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-9\">九 · 算子范数：把扰动传到输出的关键一步</h3>\n<p>推导的核心动作是把量化扰动从算子内部搬到输出端，用的工具是算子范数。设某一层的输入为 x、权重为 W，量化后得到 $$\\hat{W}=W+\\delta_W$$、$$\\hat{x}=x+\\delta_x$$，则输出扰动为</p>\n<div class=\"formula\">$$\\|\\hat{W}\\hat{x}-Wx\\|_2=\\|W\\delta_x+\\delta_W x+\\delta_W\\delta_x\\|_2\\le\\|W\\|_2\\|\\delta_x\\|_2+\\|\\delta_W\\|_2\\|x\\|_2+\\|\\delta_W\\|_2\\|\\delta_x\\|_2$$</div>\n<p>关键步有两处。其一，把 $$\\|\\delta_W\\|_2$$ 用步长 $$\\Delta_W$$ 界定：量化误差的每个元素落在 $$[-\\Delta_W/2,\\Delta_W/2]$$ 内，其谱范数不超过 $$\\Delta_W$$ 乘以矩阵维度的平方根因子，在推导中被吸收进常数，于是得到 $$\\|\\delta_W\\|_2\\le\\Delta_W$$ 的粗界。其二，把 $$\\|\\delta_x\\|_2$$ 用 $$\\Delta_x\\|x\\|_2$$ 界定，这一步隐含了“量化噪声与信号不相关”的假设——只有当噪声均匀散布、不与信号结构耦合时，才能把相对误差写成步长与信号范数的乘积。二阶项 $$\\|\\delta_W\\|_2\\|\\delta_x\\|_2$$ 在 b 较大时是高阶小量，被并入 $$\\varepsilon_{\\text{cal}}$$ 或直接忽略，这就是上界中只剩两个一阶项的原因。</p>\n<p>这一步的代价体现在两个方向。算子范数界是保守的：它假设最坏情况下所有扰动沿同一奇异方向对齐，而实际量化误差在通道间往往部分抵消，真实误差可以远低于这个界。工程上这意味着按上界选位宽会过度保守，放弃本可拿到的显存收益。另一方向是计算代价：$$\\|W\\|_2$$ 需要做奇异值分解或幂迭代，对每一层、每一个量化配置都算一遍谱范数，在容量规划阶段是可接受的离线开销，但若想在运行时动态选位宽，这个开销就不可忽略。实践中通常离线算一次谱范数表，按层缓存，运行时只查表乘步长。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-10\">十 · 离散化与近似：三处不严谨的地方</h3>\n<p>这条上界不是严格等式链，推导中有三处离散化或近似，每一处都对应一个失效条件。第一处是步长近似：$$\\Delta_W\\approx\\max|W|/(2^{b-1}-1)$$ 假设量化区间对称且均匀，实际对称量化的步长由最大绝对值决定，一旦权重分布长尾，少数极大值会把步长撑大，使绝大多数权重的有效精度远低于名义位宽。第二处是噪声不相关假设：把 $$\\|\\delta_x\\|_2$$ 写成 $$\\Delta_x\\|x\\|_2$$ 要求量化噪声在统计上与信号独立，视觉 token 中存在强离群通道时，这些通道的量化误差与信号强相关，假设失效，上界不再成立——此时必须先做通道缩放，把离群通道的能量搬到缩放因子上，再量化。第三处是校准偏差的建模：$$\\varepsilon_{\\text{cal}}$$ 被当作加性常数，但它实际是分布偏移的函数，校准集与线上视觉分布不匹配时它会随输入变化，用固定常数估计会低估线上漂移。</p>\n<p>三处近似叠加，决定了这条界的定位：它是安全判据，不是精度预测。用它判断“视觉侧能否安全降到 FP8”是合适的——若激活项在上界中占主导，说明即便考虑误差抵消，激活量化的风险仍然集中在视觉侧，必须保留较高精度或引入通道缩放；但用它反推“FP8 下精度会掉多少个百分点”就超出了它的能力。一个具体的工程判断：当 $$\\Delta_x\\|x\\|_2$$ 项超过 $$\\Delta_W\\|x\\|_2$$ 项一个量级以上时，per-tensor 激活量化直接出局，此时要么上 per-channel 缩放，要么把视觉编码器留在 BF16 而只量化 LLM 侧，用混合精度换取稳定。反过来，若两项量级接近，说明权重侧也有压缩空间，可以尝试分组权重量化而不动激活。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-11\">十一 · 缩放如何改写上界：SmoothQuant 式的通道搬移</h3>\n<p>缩小 $$\\Delta_x$$ 的手段不是降位宽，而是通道缩放。SmoothQuant 式做法引入一个对角缩放矩阵 S，把激活的离群能量搬到权重侧：$$x'=xS^{-1}$$、$$W'=SW$$，量化在缩放后的张量上进行。缩放后激活的步长变为 $$\\Delta_x'=\\Delta_x/s_{\\max}$$，而权重的谱范数变为 $$\\|SW\\|_2$$，上界随之改写为</p>\n<div class=\"formula\">$$\\|\\hat{y}-y\\|_2\\ \\le\\ \\|SW\\|_2\\cdot\\Delta_W'\\cdot\\|xS^{-1}\\|_2+\\|SW\\|_2\\cdot\\frac{\\Delta_x}{s_{\\max}}\\cdot\\|xS^{-1}\\|_2+\\varepsilon_{\\text{cal}}$$</div>\n<p>这个改写揭示了一个权衡：缩放把激活项压下去，同时把权重的谱范数抬起来，两项此消彼长。最优缩放因子要让两项之和最小，实践中按通道统计量做解析求解或网格搜索。代价在工程侧：per-channel 缩放意味着每个通道一套缩放因子，量化 kernel 要支持逐通道反量化，反量化在矩阵乘之前插入一次逐元素乘，对带宽敏感的解码阶段是额外开销；若缩放因子在运行时动态计算，还要一次归约。视觉编码器的通道数相对固定，缩放因子可以离线固化进权重，运行时只做激活侧的乘，这个开销通常可被吸收。</p>\n<p>一个具体例子：视觉 token 的某些通道在 patch 边界处出现极大响应，per-tensor 量化时这些通道把全局步长撑大，其余通道的有效位数被压缩到接近零，输出崩坏；改为 per-channel 缩放后，离群通道的缩放因子接近 1，平坦通道的缩放因子放大，全局步长回落，激活项从上界的主导位置退居次席。这正是“先做通道缩放再谈位宽”的公式依据。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-12\">十二 · 校准项与容量决策的接口</h3>\n<p>$$\\varepsilon_{\\text{cal}}$$ 是三项中最容易被忽略、也最难归因的一项。它不随位宽变化，因此在降位宽时它的相对份额上升；当位宽降到足够低、前两项被缩放压下去之后，校准偏差反而成为上界的主要贡献。工程上的表现是：离线校准集上指标正常，线上视觉分布漂移（分辨率变化、域外图像、新的预处理管线）后精度下滑，且下滑无法通过调位宽修复——因为问题不在量化步长，而在校准统计量与线上统计量的错配。诊断手段是对比线上激活的通道统计与校准时的统计，若离群通道的位置或幅度发生迁移，$$\\varepsilon_{\\text{cal}}$$ 已经偏大。</p>\n<p>容量决策中，这条上界的用法是分档判断而非连续预测。第一档：激活项主导且缩放后仍主导，视觉侧不能低于 FP8，显存收益只能来自 LLM 侧与 KV cache 侧；第二档：缩放后两项量级接近，视觉侧可尝试 FP8 并保留回退路径，回退成本是重新加载 BF16 权重与一次精度复核；第三档：校准项主导，此时降位宽无意义，应先解决校准集覆盖问题。把上界当作精度预测直接选位宽是常见误用——误差抵消使真实误差远低于界，按界选档会系统性偏保守，量化收益被无谓放弃；而忽略离群通道直接做 per-tensor 激活量化则是反向误用，激活项主导导致输出断崖式下降，且因为离线指标正常而难以在部署前发现。</p>\n<p>落到具体机制上：把上界的三项做成离线表，按层记录 $$\\Delta_W$$、$$\\Delta_x$$、$$\\|W\\|_2$$ 与校准偏差估计，部署时按视觉分布的变化触发重校准而非重选位宽，是这条公式在推理系统里最稳的用法。</p>\n\n\n<h3 id=\"th-vlm-quant-error-sec-13\">十三 · 上界的边界：算子范数放大、噪声不相关假设与视觉离群通道</h3>\n\n<p>该上界在工程上真正有用的地方不是数值本身，而是它把误差拆成了可归因的三项：权重项、激活项与校准项。推导的关键一步是用谱范数把逐层扰动传播到输出，即把量化视为对权重与激活的加性扰动，再用 <span>‖W‖₂</span> 对扰动做最坏情况放大。问题在于，算子范数取的是矩阵对向量长度的最大拉伸比，而真实前向中每个 token 的激活向量几乎不会恰好落在 <span>W</span> 的主奇异方向上。因此权重项与激活项相加得到的界，是一个“任意输入方向都成立”的保守包络；实际误差常因不同通道、不同 token 的舍入误差正负抵消而显著低于该界。把它当作精度预测去选位宽，等于用最坏情况替平均情况做决策，代价是放弃本可安全落地的 FP8 显存与带宽收益——在 KV cache 与视觉 token 同时吃显存的解码阶段，这种保守会直接压缩可承载的并发批大小。</p>\n\n<p>第二个边界是“量化噪声与信号不相关”这一假设。它成立的前提是舍入误差在统计上近似白噪声、与激活幅值无关。视觉 token 恰恰破坏这个前提：patch embedding 与位置编码叠加后，部分通道的动态范围远大于文本隐状态，per-tensor 量化下 <span>Δ_x</span> 被最大离群值撑大，等价于给所有正常通道注入了一个与其幅值强相关的粗粒度噪声，相关性假设失效，激活项不再是被高估而是被低估。此时必须先做通道缩放（SmoothQuant 式把激活难度迁移到权重侧）或 per-channel 量化，把 <span>Δ_x</span> 压回与通道动态范围匹配的量级，否则上界的结构仍然成立但各项比例失真，工程判断会误以为权重项主导而错配优化方向。</p>\n\n<div class=\"formula\">$$\\Delta_x \\approx \\frac{\\max_{c}|x_c|}{2^{b-1}-1},\\qquad \\text{err}_{\\text{act}} \\propto \\|W\\|_2\\cdot\\Delta_x\\cdot\\|x\\|_2$$</div>\n\n<p>第三个失效点是 <span>ε_cal</span>。校准集与线上视觉分布不匹配时，这一项不是小残差而是系统性偏差：离线校准用的分辨率、长宽比、图文配比与线上流量不同，导致 <span>max|x|</span> 估计偏低，<span>Δ_x</span> 被截断，离线指标正常而线上精度漂移，且难以归因——因为漂移被误记为模型本身而非量化。系统代价体现在排查成本与回退成本上：一旦线上触发回退到 BF16，显存占用翻倍、单卡可驻留的视觉 token 数与批大小同步下降，吞吐收益归零。可行的工程做法是把 <span>ε_cal</span> 当作容量规划中的显式裕量，用线上分布的分位数而非最大值定标，并在服务侧保留按请求切换精度的开关，使上界只用于判断“视觉侧能否安全降到 FP8”，而不是用于逐层选位宽。</p>\n\n<table class=\"mini\"><thead><tr><th>失效来源</th><th>机制</th><th>系统代价</th></tr></thead><tbody><tr><td>范数包络过保守</td><td>误差抵消，真实误差远低于界</td><td>无谓放弃 FP8，显存与带宽收益损失</td></tr><tr><td>离群通道破坏不相关假设</td><td>per-tensor 下 Δ_x 被最大值撑大</td><td>激活项主导，输出质量断崖</td></tr><tr><td>校准集漂移</td><td>ε_cal 偏大且难归因</td><td>线上回退 BF16，批大小与吞吐下降</td></tr></tbody></table>\n<h3 id=\"th-vlm-quant-error-sec-14\">十四 · 算子范数传播链的隐含前提</h3>\n<p>上界之所以能写成闭式，靠的是把量化扰动当作加性噪声、再用算子范数做一次 Lipschitz 式传播：<span class=\"sym\">‖Δy‖ ≤ ‖W‖₂·‖Δx‖ + ‖ΔW‖·‖x‖</span> 的合并形式。这一步在数学上无可指摘，但它默认了三件事同时成立，而这三件事在多模态推理里没有一件是自动成立的。第一，量化误差必须与输入信号统计独立，否则 <span class=\"sym\">E[Δx·x]</span> 不为零，交叉项无法被范数不等式吸收；第二，权重扰动与激活扰动必须可分离地各自取到最坏方向，否则两项相加是高估；第三，算子范数必须是该层实际诱导的增益，而不是全局谱范数——视觉编码器里注意力的 softmax 与 LayerNorm 都是非扩张但非线性的，谱范数给出的增益在归一化之后往往被显著放大。工程含义很直接：这个界是“最坏方向对齐”的界，它回答的是“误差最大能有多大”，而不是“误差通常有多大”。把它当容量决策的护栏是合法的，把它当精度预测器是越界使用。</p>\n<p>具体机制上，视觉侧最容易被忽略的是 LayerNorm 之后的重缩放。设某视觉 block 的输出经 LN 后进入 MLP，LN 的仿射参数 <span class=\"sym\">γ</span> 会按通道放大信号，若 <span class=\"sym\">γ</span> 的某几个通道数值远高于其余通道，则 <span class=\"sym\">‖W‖₂</span> 捕捉不到这种逐通道增益，界会系统性偏松。代价体现在决策上：一个偏松的界会推动工程师选择更高的位宽，直接吃掉显存收益——在 NVL72 这类以 KV cache 与权重驻留为主要显存压力的系统里，视觉塔从 FP8 退回 BF16 意味着权重与激活双份显存回涨，进而压缩可并发序列数，吞吐按批大小线性下滑。例子：一个 ViT 主干在 per-tensor FP8 下界值报得很宽，团队据此保留 BF16，结果显存预算被视觉塔占去一块，解码侧 KV 分页被迫减小 block 数，长序列请求的 prefill 排队变长。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-15\">十五 · 不相关假设在离群通道上的崩塌</h3>\n<p>推导的关键一步是把 <span class=\"sym\">Δx</span> 与 <span class=\"sym\">x</span> 解耦，从而把激活项写成 <span class=\"sym\">‖W‖₂·Δ_x·‖x‖₂</span>。这一步在文本上勉强成立，因为文本激活接近零均值、分布相对集中；视觉 token 不是这样。图像 patch 嵌入经过位置编码与若干注意力层后，会出现少数通道数值极大、其余通道接近零的“尖峰”结构，这些通道的量化步长 <span class=\"sym\">Δx = max|x|/(2^{b-1}-1)</span> 被尖峰支配，而绝大多数通道的有效步长远小于此。此时 per-tensor 量化的误差不再是各通道独立同分布的加性噪声，而是集中在少数通道上的系统性偏置，与信号强相关——不相关假设失效，界里的激活项既低估了尖峰通道的破坏力，又高估了平坦通道的贡献。</p>\n<p>失效的判别不需要复杂工具：统计视觉 token 各通道的 <span class=\"sym\">max|x|/std(x)</span>，若存在若干通道该比值显著高于其余通道，则 per-tensor 激活量化必然让激活项主导。修复路径是通道缩放，即 SmoothQuant 式地把激活的离群幅度迁移到权重侧：对通道 <span class=\"sym\">j</span> 取缩放因子 <span class=\"sym\">s_j = max|x_j|^α / max|W_{:,j}|^{1-α}</span>，等价变换 <span class=\"sym\">W' = W·diag(s)^{-1}</span>、<span class=\"sym\">x' = diag(s)·x</span>，使两侧动态范围均衡后再量化。代价是缩放因子需要按校准集统计，且 <span class=\"sym\">s_j</span> 本身要存成额外向量、在推理时做一次逐通道乘——这在 Blackwell 的 tcgen05 MMA 流水里意味着一次额外的 TMEM 读改写或前置的 elementwise kernel，增加的是启动开销而非稳态算力，对大批次可摊薄，对小批次解码步则可能成为可见延迟。例子：视觉塔某层通道 37 的幅值是其余通道的数十倍，per-tensor FP8 下该通道量化台阶粗到无法表示细节，输出特征图出现块状伪影；引入通道缩放后同一层在 FP8 下恢复，且权重侧因吸收了缩放而仍在 FP8 动态范围内。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-16\">十六 · 校准偏差 ε_cal 的规模依赖</h3>\n<p><span class=\"sym\">ε_cal</span> 是界里唯一不随位宽单调下降的项，它衡量校准集分布与线上视觉分布的距离。它的行为与规模强相关：校准集覆盖的分辨率、长宽比、图像域（自然图像、文档扫描、医学影像、遥感）越窄，<span class=\"sym\">ε_cal</span> 越小；线上流量越多样，<span class=\"sym\">ε_cal</span> 越大。这带来一个反直觉的结论——量化位宽越低，<span class=\"sym\">ε_cal</span> 在总界中的占比越不可忽略，因为 <span class=\"sym\">Δ_W</span>、<span class=\"sym\">Δ_x</span> 随比特数指数收缩，而 <span class=\"sym\">ε_cal</span> 不收缩。当 b 从 FP16 降到 FP8 时，前两项大致减半，<span class=\"sym\">ε_cal</span> 不变，于是界的构成从“量化主导”转为“校准主导”。</p>\n<p>工程上的失效模式是离线指标正常、线上精度漂移且难以归因：校准用的是标准分辨率图，线上来了大量超高分辨率或极端长宽比输入，视觉 token 的动态范围整体偏移，激活步长 <span class=\"sym\">Δ_x</span> 按旧统计设定，实际溢出或截断发生在推理时。这类漂移不会在离线评测里暴露，因为离线评测用的正是校准同分布数据。判别手段是监控量化前后的逐层相对误差，而非只看端到端任务指标；一旦某层误差在线上显著高于离线，优先怀疑 <span class=\"sym\">ε_cal</span> 而非位宽不足。容量决策上，这意味着视觉侧降精度必须配套校准集的持续更新机制，否则省下的显存会被回退重跑的成本抵消。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-17\">十七 · 规模上限：批次、序列与并行维度</h3>\n<p>界本身与批次大小无关，但界的可用性随规模变化。小批次解码时，激活张量的统计量由单个请求决定，<span class=\"sym\">Δ_x</span> 的估计方差大，界的置信度低；大批次 prefill 时，激活被多请求混合，离群通道被平均掉一部分，per-tensor 量化的实际误差反而可能低于小批次——这与“大批次更难量化”的直觉相反，原因是混合降低了单请求尖峰的相对权重。因此在连续批处理系统里，同一个量化配置在不同批组成下的真实误差并不恒定，界只能给出跨批组成的包络。</p>\n<p>序列维度上，视觉 token 数量随分辨率平方增长，<span class=\"sym\">‖x‖₂</span> 随 token 数增长，界中的两项都随之线性放大，但真实误差因误差抵消并不按同比例增长，界随规模变松。并行维度上，张量并行把 <span class=\"sym\">W</span> 切分到多卡，每卡的 <span class=\"sym\">‖W‖₂</span> 小于全局谱范数，逐卡计算的界相加会高于单卡全局界——这是切分带来的界松弛，不是精度真的变差。工程判断：在 NVL72 这类多卡紧耦合物理域里做视觉塔张量并行时，不要用逐卡界之和做位宽决策，应以全局谱范数估算再按切分折算。例子：视觉塔按 2 卡张量并行切分后，逐卡界之和比单卡界高出可观比例，若据此把视觉塔锁在 BF16，等于用通信与显存换一个并不存在的精度收益。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-18\">十八 · 什么情况下公式不再成立</h3>\n<p>把失效条件收敛成可操作的判据，有四类。其一，量化噪声与信号相关——视觉 token 存在强离群通道且未做通道缩放，此时界的两项分解失去意义，必须先缩放再谈界。其二，算子范数不是实际增益——层内含 softmax、LN、GELU 等非线性且其雅可比谱范数偏离权重谱范数时，界的传播链断裂，界退化为一个宽松的启发式。其三，校准分布漂移使 <span class=\"sym\">ε_cal</span> 不可估——离线校准与线上流量不同分布，界里的常数项变成未知量。其四，误差抵消显著——真实误差远低于界，此时界仍成立（它是上界），但作为决策依据会系统性过度保守，量化收益被无谓放弃。</p>\n<p>对应的工程动作是分场景选工具：需要“能不能安全降到 FP8”的二值判断时，用界做护栏，配合离群通道检测与通道缩放；需要“降到位宽后精度掉多少”的定量预测时，界不可用，应改用逐层量化前后相对误差的实测剖面。表格给出判据与动作的对应。</p>\n<table class=\"mini\"><thead><tr><th>判据</th><th>界的状态</th><th>工程动作</th></tr></thead><tbody><tr><td>离群通道比高、未缩放</td><td>不成立</td><td>先做 per-channel / SmoothQuant 缩放，再评估</td></tr><tr><td>层内非线性雅可比偏离权重谱范数</td><td>退化为启发式</td><td>以实测逐层误差替代界</td></tr><tr><td>校准与线上分布不一致</td><td>ε_cal 不可估</td><td>建在线误差监控，更新校准集</td></tr><tr><td>误差抵消显著</td><td>成立但过松</td><td>不据此锁高位宽，按实测剖面定档</td></tr></tbody></table>\n<p>最后落在机制上：界的价值不在数值本身，而在它把决策拆成“激活项是否主导”这一个可测问题。测法是对视觉塔逐层统计激活量化误差与权重量化误差的比值，比值大于一时激活项主导，此时唯一有效的动作是通道缩放或保留更高激活精度，而不是整体回退位宽；比值小于一时权重项主导，界的松弛主要来自谱范数高估，可放心按实测剖面降档。这个比值是连接公式与容量决策的唯一可操作接口，其余一切用法都是在把上界当预测。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-19\">十九 · 边界不在公式里，在假设里：算子范数上界何时失去解释力</h3>\n<p>这套上界真正的适用范围由三条隐含假设划定，而不是由公式形式划定。第一条是量化噪声与信号不相关：推导把权重扰动与激活扰动当作独立项线性相加，一旦视觉 token 的某个通道被系统性放大（例如 ViT 中 LayerNorm 后的少数通道幅值远高于其余通道），舍入误差就与信号强相关，两项不再可加，上界本身失去意义。第二条是算子范数传播：<span class=\"formula\">$$\\|\\hat{y}-y\\|_2\\ \\le\\ \\|W\\|_2\\cdot\\Delta_W\\cdot\\|x\\|_2+\\|W\\|_2\\cdot\\Delta_x\\cdot\\|x\\|_2+\\varepsilon_{\\text{cal}}$$</span> 用谱范数把最坏方向放大到输出，这对单个线性层成立，但跨层复合时每层都取最坏方向，累积出的界随深度指数式膨胀，到 LLM 深层已远离任何可观测误差。第三条是校准集代表性：<span class=\"formula\">$$\\varepsilon_{\\text{cal}}$$</span> 只在离线视觉分布与线上一致时可忽略。</p>\n<p>失效条件的工程判据可以写成一个比值检查，而不是去算绝对误差。定义激活项与权重项之比 <span class=\"formula\">$$\\rho=\\Delta_x/\\Delta_W$$</span>，在视觉侧 <span class=\"formula\">$$\\Delta_x$$</span> 由离群通道的 <span class=\"formula\">$$\\max|x|$$</span> 支配，<span class=\"formula\">$$\\rho$$</span> 通常显著大于 1，此时上界几乎全部由激活项贡献，公式退化为“离群通道幅值决定精度”这一条经验。反之若 <span class=\"formula\">$$\\rho\\ll 1$$</span>，说明该层视觉 token 动态范围已被缩放压平，per-tensor 激活量化才可能安全。这个比值不需要标定实验即可从权重与激活的极值统计中估出，是判断公式是否还成立的廉价前置检查。</p>\n<p>规模上限体现在两处。其一是 token 数：视觉 token 数量随分辨率与 patch 策略增长，而 <span class=\"formula\">$$\\|x\\|_2$$</span> 随 token 数增长，上界随之线性放大，但真实误差因通道间误差抵消增长得更慢，于是界与实际精度的差距随分辨率拉大——高分辨率输入下用该界选位宽会系统性过度保守。其二是批规模：连续批处理把不同图像的视觉 token 拼进同一 GEMM，per-channel 缩放若按单图统计，跨图拼接后通道极值被重新定义，缩放因子失配，<span class=\"formula\">$$\\Delta_x$$</span> 实际变大而离线界未反映，这是分离式预填/解码部署中常见的隐性漂移。</p>\n<p>系统代价必须和边界一起看。若判定激活项主导而回退到 BF16，视觉编码器显存占用相对 FP8 翻倍，直接吃掉 KV cache 的容量预算；若坚持 FP8 但引入 per-channel 或 SmoothQuant 式缩放，则多出缩放因子的读写与逐通道反量化，编码器 GEMM 的有效带宽利用率下降，预填阶段延迟上升。校准集不匹配导致的 <span class=\"formula\">$$\\varepsilon_{\\text{cal}}$$</span> 偏大是第三种代价：离线指标正常、线上精度漂移，且无法从量化位宽归因，只能靠线上视觉分布抽样重校准来收敛。工程判断应落在“先测 <span class=\"formula\">$$\\rho$$</span> 与离群通道数，再决定是缩放还是保精度”，而不是把上界当精度预测去反推位宽。</p>\n<h3 id=\"th-vlm-quant-error-sec-20\">二十 · 把上界翻译成可执行的容量约束</h3>\n<p>误差上界本身不是一个数，而是一个随部署参数变化的函数。要把 $$\\|\\hat{y}-y\\|_2\\le\\|W\\|_2\\Delta_W\\|x\\|_2+\\|W\\|_2\\Delta_x\\|x\\|_2+\\varepsilon_{\\text{cal}}$$ 用在容量决策上，第一步是把它改写成“给定精度配置，输出误差预算还剩多少”的形式。做法是把右端三项各自除以 $$\\|W\\|_2\\|x\\|_2$$，得到相对误差界 $$\\Delta_W+\\Delta_x+\\varepsilon_{\\text{cal}}/(\\|W\\|_2\\|x\\|_2)$$。这个归一化很关键：它把绝对误差界变成了与输入尺度无关的量，从而可以在不同 batch、不同分辨率、不同视觉 token 数之间横向比较。工程上把它记作 $$\\rho$$，即“每单位信号允许的量化扰动”。容量规划时先由业务侧给出可接受的 $$\\rho_{\\max}$$（例如由离线评测确定的质量红线反推），再让量化配置满足 $$\\Delta_W+\\Delta_x\\le\\rho_{\\max}-\\varepsilon_{\\text{cal}}/(\\|W\\|_2\\|x\\|_2)$$。这样，精度选择就从“试 FP8 行不行”变成了一道有明确约束的分配问题：权重项与激活项共享同一份预算，谁占得多，另一个就必须更保守。</p>\n<p>第二步是把 $$\\Delta_x$$ 与批大小挂钩。视觉 token 的激活步长由该 batch 内所有视觉 token 的通道极值决定，per-tensor 量化下 $$\\Delta_x=\\max_{b,t,c}|x_{b,t,c}|/(2^{b-1}-1)$$，其中 $$b$$ 是 batch 维。批越大，越可能抽到极值更大的样本，$$\\Delta_x$$ 单调不减，于是 $$\\rho$$ 随 batch 上升而恶化。这给出一条直接的批大小上限：解 $$\\Delta_x(N)\\le\\rho_{\\max}-\\Delta_W-\\varepsilon_{\\text{cal}}/(\\|W\\|_2\\|x\\|_2)$$ 得到最大批 $$N_{\\max}$$。注意这里的代价是双向的：批太小则 GPU 利用率与吞吐上不去，批太大则激活项吃掉预算、迫使回退到 BF16，显存与带宽收益归零。因此容量决策的正确姿势不是先定批再定量化，而是把两者放在同一个不等式里联立求解。</p>\n<p>第三步是把并行度纳入。张量并行把 $$W$$ 切成 $$p$$ 份，每份的谱范数约为 $$\\|W\\|_2/\\sqrt{p}$$（随机切分下的典型缩放），权重项随之下降；但激活项里的 $$\\|W\\|_2$$ 与 $$\\Delta_x$$ 并不随切分同步缩小，因为视觉 token 的离群通道在切分后仍集中在少数 rank 上，$$\\Delta_x$$ 由全局极值决定而非局部极值。结果是并行度提高对权重项友好、对激活项几乎无益。这解释了为什么视觉侧激活主导时，加大 TP 并不能挽救低比特量化的精度，只能靠通道缩放把 $$\\Delta_x$$ 压下来。</p>\n<div class=\"formula\">$$\\Delta_x^{\\text{pc}}=\\frac{\\max_{t}|x_{t,c}|}{2^{b-1}-1},\\qquad \\Delta_x^{\\text{eff}}=\\max_c \\Delta_x^{\\text{pc}}\\cdot s_c^{-1}$$</div>\n<p>其中 $$s_c$$ 是 per-channel 或 SmoothQuant 式缩放因子。缩放把通道间的动态范围差异搬到权重侧吸收，使有效激活步长 $$\\Delta_x^{\\text{eff}}$$ 显著小于 per-tensor 的 $$\\Delta_x$$。工程代价是缩放因子需要校准、要在 kernel 里多做一次乘加，且缩放后的权重动态范围变大、$$\\Delta_W$$ 略微上升——这是一次预算在两项之间的重新分配，而非免费午餐。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-21\">二十一 · KV 预算与误差预算的耦合</h3>\n<p>多模态 KV cache 的显存占用与视觉 token 数线性相关，而视觉 token 数又受分辨率与 patch 策略支配。把 KV 预算记为 $$M_{\\text{KV}}$$，单 token 每层 KV 字节数为 $$2\\cdot d\\cdot b_{\\text{kv}}/8$$（$$d$$ 为头维乘层数，$$b_{\\text{kv}}$$ 为 KV 位宽），则可容纳的序列长度 $$L_{\\max}=M_{\\text{KV}}/(2db_{\\text{kv}}/8)$$。表面上看，压低 $$b_{\\text{kv}}$$ 直接放大 $$L_{\\max}$$，是显存收益最直接的杠杆。但 KV 量化同样受上界约束：KV 激活的离群通道与视觉 token 的通道结构同源，若不做通道缩放，$$\\Delta_x$$ 主导会使解码输出漂移，表现为长上下文下注意力分布偏移、生成重复或答非所问。于是 KV 位宽的选择必须与视觉侧激活量化策略一致：视觉侧做了通道缩放，KV 侧才敢同步降到 FP8；视觉侧仍是 per-tensor，KV 侧降位宽就是把两个未处理的离群源叠加。</p>\n<p>更细的耦合在于预算的“时间维度”。预填阶段视觉 token 一次性写入 KV，其量化误差在后续所有解码步被反复读取放大；解码阶段新写入的文本 KV 动态范围小，误差贡献低。因此 KV 预算应当按“视觉段”和“文本段”分开核算：视觉段的位宽由 $$\\rho$$ 约束决定，文本段可以更激进。工程上表现为分层或分段量化策略——对视觉段保留 FP8 甚至 BF16，对文本段用更低比特。代价是 kernel 需要按段切换反量化路径，增加分支与寄存器压力，吞吐略降，但换来的是在同等 $$M_{\\text{KV}}$$ 下更长的可用上下文。</p>\n<p>算例：设某 VLM 单卡 KV 预算 24 GB，每 token 每层 KV 为 2×8 KB（FP16 口径），共 32 层，则 FP16 下可容纳约 24 GB/(2×8 KB×32)≈46k token。若视觉段占 4k token、文本段预算 42k，把视觉段降到 FP8 只省下 4k token 的一半空间，收益有限；真正的大头在文本段。这说明 KV 预算优化的优先级应由 token 构成决定，而不是无差别压位宽。反过来，若某任务视觉 token 占 30k、文本仅 2k，则视觉段位宽就是主战场，此时 $$\\Delta_x$$ 的处理直接决定能否把 $$L_{\\max}$$ 翻倍。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-22\">二十二 · 用上界定 SLO：延迟与质量的联合约束</h3>\n<p>SLO 通常写成“P99 首 token 延迟 ≤ T、吞吐 ≥ Q、质量 ≥ 阈值”。量化上界的作用是把质量这一维从“事后评测”变成“事前约束”。具体做法：由离线评测建立 $$\\rho$$ 与质量指标（如 VQA 准确率、OCR 字符错误率）的映射曲线，取质量红线对应的 $$\\rho_{\\max}$$，再把它代入第一节的不等式，得到允许的 $$(\\Delta_W,\\Delta_x)$$ 组合。这样 SLO 就变成了三维可行域：延迟约束给出批大小与并行度的下限（批太小延迟高、批太大排队久），吞吐约束给出上限，质量约束通过 $$\\rho_{\\max}$$ 切断某些低比特配置。三个约束的交集才是可部署配置。</p>\n<p>延迟侧的关键机制是：批大小影响 $$\\Delta_x$$，而 $$\\Delta_x$$ 影响是否触发回退。若某配置在批 $$N$$ 下 $$\\rho&gt;\\rho_{\\max}$$，系统要么降批、要么提精度，两者都推高单位 token 成本。因此在 SLO 求解时不能把批大小当自由变量随意拉满，而应把 $$N_{\\max}(\\rho_{\\max})$$ 作为硬上限参与排队论计算。举例：若单卡解码吞吐随批近似线性上升至 $$N_{\\max}$$ 后饱和，而 $$N_{\\max}$$ 由误差预算卡在远低于硬件饱和点的位置，则系统的实际吞吐天花板由精度而非算力决定——这是量化误差上界在容量规划中最容易被忽视的一条结论。</p>\n<p>另一个机制是预填/解码分离下的预算分配。预填节点处理视觉 token，激活离群最严重，$$\\Delta_x$$ 主导；解码节点处理文本 KV，权重项相对更重要。分离部署允许两边用不同的量化配置：预填侧保留 FP8 加通道缩放，解码侧可尝试更低比特权重。代价是两套 kernel 与两套校准集，运维复杂度上升，且跨节点的 KV 传输需要统一位宽或做在线转换，转换本身引入额外延迟与一次舍入。工程判断是：只有当预填侧误差预算确实成为瓶颈时，分离量化才值得这套复杂度。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-23\">二十三 · 算例：从误差预算反推部署参数</h3>\n<p>设某 OCR 类 VLM，视觉编码器与 LLM 均计划量化到 FP8（$$b=8$$），权重 per-tensor、激活 per-tensor。已知视觉 token 动态范围远大于文本，实测（定性）激活项主导。取 $$\\rho_{\\max}=0.02$$（由质量红线反推的相对误差预算），$$\\Delta_W$$ 在 FP8 下约为 $$2^{-7}$$ 量级，即约 0.008；若 $$\\Delta_x$$ 在批 $$N=1$$ 时约 0.006，则两项之和 0.014，尚在预算内，$$\\varepsilon_{\\text{cal}}$$ 项需控制在 0.006 以内。随着批增大，$$\\Delta_x$$ 因极值抽样上升，设 $$N=8$$ 时升至 0.012，两项之和 0.020，恰好触顶；$$N=16$$ 时升至 0.018，总和 0.026 超预算。于是 $$N_{\\max}\\approx 8$$。</p>\n<p>此时若想提到 $$N=32$$ 以拉吞吐，有两条路。其一是引入 per-channel 激活缩放，把 $$\\Delta_x$$ 压回 0.006 量级，代价是 $$\\Delta_W$$ 因权重重缩放升至约 0.010，总和 0.016，仍有余量，$$N_{\\max}$$ 可推到 32 以上；代价是 kernel 多一次缩放乘加、校准集需覆盖通道统计，且缩放因子本身引入 $$\\varepsilon_{\\text{cal}}$$ 的额外不确定性。其二是把视觉侧回退到 BF16，$$\\Delta_x$$ 降到可忽略，但显存翻倍、带宽需求翻倍，KV 预算被挤压，$$L_{\\max}$$ 下降，长文档场景直接受损。两条路的取舍取决于该业务是吞吐敏感还是上下文长度敏感。</p>\n<p>再看并行度：若把 LLM 切到 TP=4，权重项按 $$1/\\sqrt{4}=1/2$$ 下降至 0.004，但激活项不变仍为 0.012（全局极值），总和 0.016，$$N_{\\max}$$ 可略升。这说明 TP 对激活主导场景的收益有限，真正有效的是通道缩放。若同时做通道缩放与 TP=4，总和约 0.005+0.006=0.011，预算充裕，可把批推到硬件饱和点，此时吞吐天花板重新由算力而非精度决定——这正是容量规划想要的结果。</p>\n<p>最后核对 KV：若该配置下视觉 token 平均 2k、文本 6k，FP8 KV 使 $$L_{\\max}$$ 相对 FP16 翻倍，但视觉段若未做通道缩放，KV 量化误差在长上下文下累积，表现为检索类问题准确率下滑。因此 KV 降位宽必须与视觉侧缩放策略绑定，否则省下的显存被质量损失抵消。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-24\">二十四 · 误用模式与工程护栏</h3>\n<p>第一种误用是把算子范数上界当作精度预测。上界假设量化噪声与信号不相关且取最坏传播方向，实际误差常因抵消远低于界。若直接用 $$\\rho$$ 反推位宽，会在真实误差远小于界时过度保守，放弃本可安全采用的低比特配置，显存与带宽收益被无谓牺牲。护栏是：用上界做可行性筛选（排除必然失败的配置），用实测校准曲线做最终选型，两者分工明确。</p>\n<p>第二种误用是忽略视觉 token 离群通道直接 per-tensor 激活量化。此时 $$\\Delta_x$$ 由极少数通道的极值支配，激活项主导，输出质量断崖式下降，且离线小批量评测可能因抽样未命中极值而显示正常，上线后批量增大立刻暴露。护栏是：在校准阶段显式统计通道极值分布，若某通道极值/中位数比超过阈值，强制启用通道缩放；并把该统计纳入 CI，防止换模型或换分辨率后静默失效。</p>\n<p>第三种误用是校准集与线上分布不匹配导致 $$\\varepsilon_{\\text{cal}}$$ 偏大。离线指标正常、线上精度漂移，且难以归因——因为漂移被误认为模型问题而非量化问题。护栏是：把 $$\\varepsilon_{\\text{cal}}$$ 作为独立监控项，用线上采样的视觉输入周期性重算校准偏差，超过预算占比即告警。工程上这比事后排查便宜得多。</p>\n<p>三条护栏共同指向一个判断：误差上界的价值不在于给出一个精确数字，而在于把“精度是否够”从主观试错变成可分解、可监控、可归因的预算分配问题。真正决定部署成败的，是 $$\\Delta_x$$ 这一项有没有被通道缩放压住——它既是上界里最活跃的变量，也是容量决策里最容易被低估的杠杆。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-25\">二十五 · 把上界换算成批大小、并行度与 KV 预算的工程判据</h3>\n<p>上界在容量决策里不是精度预测器，而是一个<b>否决器</b>：它只回答“视觉侧能不能安全降到 FP8 或更低”。把公式拆成两项比值即可操作化——记激活项与权重项之比 $$\\rho=\\Delta_x/\\Delta_W$$（两者同乘 $$\\|W\\|_2\\|x\\|_2$$，故比值与范数无关）。$$\\rho\\gg1$$ 说明激活离群值主导，此时降位宽的显存收益会被回退到 BF16 抵消；$$\\rho\\ll1$$ 才允许激进量化。工程上先在小校准集上量出 $$\\Delta_x$$ 与 $$\\Delta_W$$，再决定视觉编码器与 LLM 是否采用不同位宽，而不是对整条链路统一压到同一比特数。这一步的代价是一次离线标定，换掉的是线上反复回退的抖动。</p>\n<p>批大小与并行度的定法随之改变。设单卡可用于激活与 KV 的显存为 $$M$$，单请求视觉 token 数为 $$n_v$$、文本 KV 长度为 $$n_t$$，则可行批大小近似受 $$B\\le M/(n_v\\cdot s_v+n_t\\cdot s_t)$$ 约束，其中 $$s_v,s_t$$ 为每 token 字节数。量化把 $$s_v$$ 从 FP16 的 2 降到 FP8 的 1，理论上批大小翻倍；但若 $$\\rho$$ 大，激活项迫使视觉分支保留高精度，实际只有文本侧 KV 受益，批大小提升远小于 2 倍。并行度同理：张量并行切分权重矩阵会降低单卡 $$\\|W\\|_2$$，上界随之收紧，但通信量上升，NVLink 5 上的 all-reduce 延迟会吃掉收益——所以并行度应依据“上界收紧后仍满足 SLO”的最小切分数来定，而非按显存缺口硬切。</p>\n<p>KV 预算与 SLO 的耦合点在校准偏差 $$\\varepsilon_{\\text{cal}}$$。视觉分布随场景漂移（分辨率、长宽比、域偏移），$$\\varepsilon_{\\text{cal}}$$ 会缓慢增大，表现为离线指标正常而线上精度漂移，且难以归因到量化。判据是给 $$\\varepsilon_{\\text{cal}}$$ 设一个随线上采样滚动更新的阈值：一旦它使上界越过可接受误差，就触发重标定或局部回退，而不是等 SLO 违约。算例：某服务视觉 token 每请求 1024 个、文本 KV 2048 个，FP16 下每 token 2 字节，单卡预算 40 GB 量级时批大小被 KV 而非权重卡住；若测得 $$\\rho\\approx 5$$，则视觉侧降到 FP8 后激活项仍主导，实际批大小只按文本 KV 减半获益，此时正确决策是保留视觉 BF16、只压文本 KV，并把并行度维持在能满足首 token 延迟的最小值。</p>\n<table class=\"mini\"><thead><tr><th>判据</th><th>观测</th><th>决策</th></tr></thead><tbody><tr><td>$$\\rho=\\Delta_x/\\Delta_W$$</td><td>$$\\gg1$$</td><td>视觉保留高精度或先做通道缩放</td></tr><tr><td>$$\\varepsilon_{\\text{cal}}$$ 漂移</td><td>线上采样上升</td><td>重标定，勿归因于位宽</td></tr><tr><td>上界 vs 实测误差</td><td>实测远低</td><td>勿据此放弃量化收益</td></tr></tbody></table>\n<h3 id=\"th-vlm-quant-error-sec-26\">二十六 · 误用一：把范数界当精度预测</h3>\n<p>最常见的误用，是把 <span class=\"inline\">‖ŷ−y‖₂ ≤ ‖W‖₂·Δ_W·‖x‖₂ + ‖W‖₂·Δ_x·‖x‖₂ + ε_cal</span> 这个不等式直接当成“量化到 b 比特后精度会掉多少”的预测器。这在工程上会立刻产生一个可观测的后果：决策表里出现“视觉侧只能停在 FP8、不能下探到更低精度”的结论，而实际部署中视觉编码器在更低精度下的输出余弦相似度仍然可用。原因在于算子范数界是**最坏情况**：它把每一层的量化扰动都按谱范数同向叠加，而真实网络里相邻层的扰动大量反号抵消，残差连接与 LayerNorm 又把误差重新归一化。界是“上确界”，不是“期望”。</p>\n<p>识别方法很直接：在同一校准集上同时记录<b>实测输出误差</b>与<b>界值</b>，看两者的比值。若实测误差比界低一到两个数量级，且该比值在不同 batch、不同图像分辨率下稳定，说明误差抵消是结构性的而非偶然，此时用界选位宽就是过度保守。代价体现在显存与带宽上：视觉编码器权重从 FP16 降到 FP8 省一半权重带宽，若因误判而回退 BF16，预填阶段视觉塔的权重读取时间与 KV 侧显存预算同时被吃掉，而换来的精度余量在端到端指标上根本测不出来。</p>\n<p>正确的用法是把界当作<b>可行性筛子</b>而非<b>预测器</b>：界不满足时一定不能降精度；界满足时仍需实测确认。判断激活项是否主导，只需比较 <span class=\"inline\">Δ_W·‖x‖₂</span> 与 <span class=\"inline\">Δ_x·‖x‖₂</span> 的量级——两者共享 <span class=\"inline\">‖W‖₂·‖x‖₂</span> 因子，所以比值就是 <span class=\"inline\">Δ_W/Δ_x</span>。视觉 token 的动态范围远大于文本，<span class=\"inline\">Δ_x</span> 常比 <span class=\"inline\">Δ_W</span> 大出可观倍数，激活项主导是常态而非例外。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-27\">二十七 · 误用二：per-tensor 激活量化不处理离群通道</h3>\n<p>第二个误用更致命：对视觉 token 直接做 per-tensor 激活量化。<span class=\"inline\">Δ_x</span> 由 <span class=\"inline\">max|x|/(2^{b−1}−1)</span> 决定，而视觉 token 的通道分布是重尾的——少数通道的幅值比中位数高出若干数量级（patch embedding 后的高频响应、位置编码叠加处尤为明显）。per-tensor 用一个全局 max 定步长，等于让绝大多数通道的有效位数被那几个离群通道吃掉，量化信噪比断崖式下跌。</p>\n<p>后果不是“轻微掉点”，而是输出崩坏：视觉塔输出的 patch 特征整体偏移，LLM 侧接收到的是系统性偏置的视觉前缀，表现为描述错乱、计数错误、空间关系颠倒，且这种崩坏在离线小样本上不一定暴露——因为崩坏是分布性的，单条样本的困惑度可能只轻微上升。识别信号是<b>逐通道量化误差谱</b>：把每通道的 <span class=\"inline\">|x−x_q|</span> 均值画出来，若误差集中在少数通道且这些通道恰是幅值最大的通道，就是典型的 per-tensor 失效。</p>\n<p>修法是通道缩放，把离群通道在量化前除以一个 per-channel scale、量化后再乘回，等价于把 <span class=\"inline\">Δ_x</span> 从“全局 max 决定”改成“每通道 max 决定”，从而把激活项压下来。SmoothQuant 式做法更进一步，把缩放因子折进权重（<span class=\"inline\">W·diag(s)</span> 与 <span class=\"inline\">x/diag(s)</span>），推理时零额外开销。代价是校准阶段要多一遍通道统计，以及权重需要离线重参数化；收益是激活项从主导项退回次要项，视觉侧才真正具备降到 FP8 的条件。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-28\">二十八 · 误用三：校准集不匹配，ε_cal 悄悄吃掉预算</h3>\n<p>第三个误用不体现在公式的前两项上，而体现在 <span class=\"inline\">ε_cal</span>。校准集若只覆盖文档截图、不含自然图像，或只覆盖单一分辨率，则 per-channel scale 与激活范围都是在错误分布上估的。离线评测用的是同一批校准分布，指标自然正常；上线后视觉输入分布漂移，<span class=\"inline\">ε_cal</span> 变大，精度漂移出现，而工程师往往先去怀疑算子或框架，迟迟归因不到量化。</p>\n<p>识别手段是<b>分布探针</b>：在服务端对视觉 token 的通道幅值做在线直方图，与校准时的直方图做对比，若分位数偏移超过阈值即告警。工程代价是每批多一次轻量统计，但换来的是可归因性——没有这个探针，量化漂移与模型本身的分布外失效无法区分。容量决策上，<span class=\"inline\">ε_cal</span> 应作为独立预算项显式留出：当激活项已被通道缩放压到次要位置时，剩下的误差预算主要就是校准偏差，此时扩校准集的边际收益高于继续压位宽。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-29\">二十九 · 一个反例：端到端崩坏的全过程</h3>\n<p>设某多模态服务把视觉编码器与 LLM 都量化到 FP8，视觉侧采用 per-tensor 激活量化，校准集取自文档截图。上线后自然图像请求出现描述错乱。复盘链条如下：</p>\n<ul>\n<li>视觉 token 通道幅值重尾，per-tensor 的 <span class=\"inline\">Δ_x</span> 被少数离群通道抬高，激活项 <span class=\"inline\">‖W‖₂·Δ_x·‖x‖₂</span> 在界中占主导；</li>\n<li>校准集不含自然图像，per-channel scale 未覆盖高动态范围场景，<span class=\"inline\">ε_cal</span> 在线上被放大；</li>\n<li>两项叠加，实际误差不再享受误差抵消的红利——因为离群通道的扰动是同向的、结构性的，恰好破坏了“噪声与信号不相关”这一适用边界；</li>\n<li>端到端表现为视觉前缀系统性偏移，LLM 侧无法通过上下文纠偏，输出质量断崖式下降。</li>\n</ul>\n<p>这个反例的关键教训是：<b>界的失效条件与误用条件是同一件事的两面</b>。界假设量化噪声与信号不相关；离群通道造成的扰动恰恰与信号强相关，于是界既不能预测误差、实际误差也不再被抵消压低。此时正确的动作不是回退到 BF16（那会抵消全部显存收益），而是先做通道缩放把扰动去相关，再重新测界与实测误差的比值。</p>\n\n<h3 id=\"th-vlm-quant-error-sec-30\">三十 · 工程判断：三条可执行的检查线</h3>\n<p>把上述误用收敛成三条检查线，直接嵌进量化上线流程。第一条，<b>主导项判定</b>：算 <span class=\"inline\">Δ_W/Δ_x</span>，若激活项主导则禁止 per-tensor，必须先上通道缩放，否则不允许进入位宽下探评估。第二条，<b>界与实测比值</b>：在同分布校准集上记录比值，比值稳定偏大说明误差抵消结构性存在，界只能当筛子；比值接近 1 说明界紧，此时界可以作为保守预测使用。第三条，<b>ε_cal 探针</b>：在线统计视觉 token 通道分位数并与校准直方图比对，把校准偏差变成可观测指标而非隐式风险。</p>\n<p>三条线各自的系统代价不同：第一条几乎零成本，只是一次离线统计；第二条需要一次完整评测，代价是评测吞吐；第三条是常驻的在线开销，摊到每请求上很小但需要存储直方图状态。容量规划上，把这三条线的结论写进位宽决策表，比把界值直接填进表里要可靠得多——前者告诉你“能不能降”，后者只告诉你“最坏能坏到哪”，而最坏情况在真实网络里几乎不会发生。</p>\n<p>最后落到一个具体机制上：当视觉侧确认激活项主导且离群通道显著时，量化流程的顺序应当是<b>先通道缩放、再重参数化权重、最后才选位宽</b>。顺序颠倒——先选位宽再补救——就会复现上面的反例：位宽已经按 per-tensor 的乐观估计定死，通道缩放只能在推理时加开销，显存收益被在线缩放算子抵消。把缩放折进权重是唯一能让激活项下降而不增加解码路径开销的做法，这也是判断一次视觉量化是否真正“省下来”的硬标准。</p>\n\n\n<h3 id=\"th-vlm-quant-error-sec-31\">三十一 · 误用与反例：把上界当精度预测、把离群通道当噪声</h3>\n\n<p>本方案在工程落地中最常见的第一类误用，是把算子范数上界直接当成精度预测来选量化位宽。上界 $$\\|\\hat{y}-y\\|_2\\ \\le\\ \\|W\\|_2\\cdot\\Delta_W\\cdot\\|x\\|_2+\\|W\\|_2\\cdot\\Delta_x\\cdot\\|x\\|_2+\\varepsilon_{\\text{cal}}$$ 的推导只用了一次三角不等式与算子范数的次乘性，它给出的是最坏情况包络，而不是期望误差。真实网络里权重舍入误差与激活量化误差在通道间、token 间往往部分反号，误差抵消使实测偏差远低于该界。若工程师拿这个界去卡“视觉侧必须留在 BF16”，就会在激活项并未主导的层上无谓放弃 FP8 的显存与带宽收益——FP16 占 2 字节、FP8 占 1 字节，权重与 KV 的常驻占用直接翻倍，解码阶段的显存带宽压力随之抬升，吞吐被显存而非算力卡住。识别方法很直接：分别实测纯权重量化与纯激活量化的输出偏差，若两者之和显著大于联合量化的实测偏差，说明抵消确实存在，此时上界只能用作“是否必须做通道缩放”的判据，不能用作位宽决策。反例：某视觉编码器在 per-tensor 激活量化下上界算出的偏差量级足以判定“不可用”，但逐层实测发现中间层偏差被后续归一化与残差吸收，端到端指标几乎不动；团队据此回退到 BF16，白白丢掉了本可拿到的显存收益，而真正的瓶颈其实只在少数离群通道上。</p>\n\n<p>第二类误用更隐蔽：对视觉 token 直接做 per-tensor 激活量化而不处理离群通道。视觉 token 的动态范围远大于文本 token，少数通道的极大值会把 per-tensor 的 $$\\Delta_x$$ 整体抬高，于是绝大多数正常通道被压进极粗的量化格点，激活误差项 $$\\|W\\|_2\\cdot\\Delta_x\\cdot\\|x\\|_2$$ 主导总误差，输出质量出现断崖式下降——不是缓慢退化，而是某些图文样本直接答错。这里的失效条件正是上界推导所假设的“量化噪声与信号不相关”：强离群通道使噪声与信号强相关，算子范数传播的前提被破坏。正确做法是先做 per-channel 或 SmoothQuant 式缩放，把离群能量从激活搬到权重侧，使 $$\\Delta_x$$ 回落到与文本 token 同量级，再谈位宽。系统代价体现在两处：缩放因子引入额外的逐通道乘加，在预填阶段对视觉 token 数量线性增长的计算开销；以及缩放后权重侧动态范围变大，若权重仍用 per-tensor 量化，$$\\Delta_W$$ 反而上升，需要在权重侧也切到 per-channel 才能闭合。识别信号是分层统计激活的 max/median 比值，比值畸高的层就是必须先缩放的层。</p>\n\n<p>第三类误用是校准集与线上视觉分布不匹配，让 $$\\varepsilon_{\\text{cal}}$$ 悄悄变大。离线校准常用固定分辨率的公开图像，线上却是任意长宽比、含大量截图与文档的混合流量，激活统计的分位数整体偏移，离线评测指标正常而线上精度漂移，且因为漂移是渐进的，很难归因到量化本身。这类问题的代价不是单次延迟，而是容量规划失真：按离线指标定的量化位宽在线上不成立，被迫在高峰期回退精度，显存与带宽预算瞬间失效。工程上应把 $$\\varepsilon_{\\text{cal}}$$ 当作独立可测量项，用线上采样的小校准集周期性重算缩放因子，并把“校准集覆盖率”纳入发布门禁。下表给出三类误用的识别与处置对照。</p>\n\n<table class=\"mini\"><thead><tr><th>误用</th><th>识别信号</th><th>后果</th><th>处置</th></tr></thead><tbody><tr><td>上界当精度预测</td><td>联合量化实测偏差远小于两项之和</td><td>过度保守，放弃 FP8 显存收益</td><td>上界仅作通道缩放判据</td></tr><tr><td>per-tensor 激活量化</td><td>分层 max/median 比值畸高</td><td>激活项主导，输出断崖式下降</td><td>per-channel / SmoothQuant 缩放</td></tr><tr><td>校准集失配</td><td>离线正常、线上漂移且难归因</td><td>容量预算失真，被迫回退</td><td>线上采样重算 $$\\varepsilon_{\\text{cal}}$$</td></tr></tbody></table>\n\n<p>把这三类误用收束成一条工程判断：上界的正确用途是判断“激活项是否主导”，而不是预测“精度会掉多少”。当 $$\\Delta_x$$ 由离群通道支配时，任何不先做通道缩放的位宽下调都是在赌噪声与信号不相关这个假设成立，而视觉 token 恰恰是最容易让该假设失效的输入形态。反过来，当实测显示误差抵消显著时，坚持用上界卡位宽就是把最坏情况当成了常态，用显存和带宽为保守买单。真正稳的做法是把上界、分层实测偏差与线上校准漂移三者并列监控，让位宽决策落在“激活项已缩放、$$\\varepsilon_{\\text{cal}}$$ 已收敛”之后，而不是落在公式给出的那个数字上。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>\\Delta_W</td><td>权重量化步长，约等于 max|W|/(2^{b-1}-1)</td></tr><tr><td>\\Delta_x</td><td>激活量化步长，受视觉 token 离群值支配</td></tr><tr><td>\\|W\\|_2</td><td>权重矩阵谱范数</td></tr><tr><td>\\varepsilon_{\\text{cal}}</td><td>校准集不匹配引入的额外偏差</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-vlm-quant-error · 共 5 个片段</p>\n"},{"id":"th-nvl72-comm-lower-bound","title":"NVL72 通信下界","direction":"dir-multimodal-serving","prereq":[],"plain":"在 GB200/GB300 NVL72 上做视觉编码器张量并行或分离式预填/解码时，跨 GPU 的 all-reduce/all-to-all 数据量除以 NVLink 带宽给出通信时间下界；视觉 token 数越多，all-to-all 越大，通信越容易成为瓶颈。","definition":"在 GB200/GB300 NVL72 上做视觉编码器张量并行或分离式预填/解码时，跨 GPU 的 all-reduce/all-to-all 数据量除以 NVLink 带宽给出通信时间下界；视觉 token 数越多，all-to-all 越大，通信越容易成为瓶颈。","formula":"$$T_{\\text{comm}}\\ \\ge\\ \\frac{2\\,(N-1)}{N}\\cdot\\frac{S}{\\text{BW}_{\\text{NVLink}}}+\\tau_{\\text{lat}}$$","variables":[{"sym":"N","meaning":"参与集合通信的 GPU 数"},{"sym":"S","meaning":"单次通信的消息字节数（如视觉 token 激活或 KV 分片）"},{"sym":"\\text{BW}_{\\text{NVLink}}","meaning":"单 GPU NVLink 聚合带宽（GB200 约 1.8 TB/s 量级）"},{"sym":"\\tau_{\\text{lat}}","meaning":"kernel 启动与协议固定延迟"}],"derivation":"推导关键一步：环状 all-reduce 分 reduce-scatter 与 all-gather 两阶段，每阶段每卡搬运 $$\\frac{N-1}{N}S$$ 字节，合计 $$\\frac{2(N-1)}{N}S$$，再除以单卡 NVLink 带宽即得带宽项下界，最后叠加与消息大小无关的固定延迟 $$\\tau_{\\mathrm{lat}}$$。","example":"容量决策用途：给定视觉 token 数 S 与并行度 N，可反解出通信时间随 N 的变化，判断张量并行或分离式预填/解码在哪个 N 上通信项开始超过单卡计算项，从而决定视觉编码器是否值得跨卡切分、批大小上限以及是否改用 token 压缩降低 S。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["仅建模单次 all-reduce 的带宽项；实际多模态流水含多次 all-to-all，需按拓扑累加并考虑拥塞","NVLink 带宽为双向峰值，环状 all-reduce 的有效带宽通常只有峰值的 60%–80%"],"system_note":"常见误用：把 GB200 约 1.8 TB/s 的峰值带宽直接当作有效带宽代入，忽略环状算法 60%–80% 的效率折损与多轮 all-to-all 的累加，导致容量规划偏乐观；另一误用是只算一次通信而漏掉流水中的重复集合通信，实测时延可达下界的数倍。","papers":["paper-an-image-is-worth-16x16-words-transf-2020"],"facts":["直觉：把一次集合通信要搬运的字节数除以单卡 NVLink 聚合带宽，就得到通信时间的物理下限；视觉 token 越多，all-to-all 搬运量越大，该下限越容易压过计算时间成为端到端瓶颈。","公式第一项 $$\\frac{2(N-1)}{N}\\cdot\\frac{S}{\\mathrm{BW}_{\\mathrm{NVLink}}}$$ 中，$$S$$ 是单次通信的消息字节数（视觉 token 激活或 KV 分片），$$\\frac{2(N-1)}{N}$$ 是环状 all-reduce 的带宽放大因子：每卡需收发约两倍于自身分片的数据，随 N 增大趋近 2；$$\\tau_{\\mathrm{lat}}$$ 是 kernel 启动与协议固定延迟。","推导关键一步：环状 all-reduce 分 reduce-scatter 与 all-gather 两阶段，每阶段每卡搬运 $$\\frac{N-1}{N}S$$ 字节，合计 $$\\frac{2(N-1)}{N}S$$，再除以单卡 NVLink 带宽即得带宽项下界，最后叠加与消息大小无关的固定延迟 $$\\tau_{\\mathrm{lat}}$$。","适用边界：该式只建模单次 all-reduce 的带宽项；真实多模态流水含多次 all-to-all（如视觉 token 分发、专家路由、序列并行），需按拓扑逐次累加并计入拥塞；NVLink 标称带宽为双向峰值，环状 all-reduce 的有效带宽通常只有峰值的 60%–80%，直接代入峰值会低估时延。","容量决策用途：给定视觉 token 数 S 与并行度 N，可反解出通信时间随 N 的变化，判断张量并行或分离式预填/解码在哪个 N 上通信项开始超过单卡计算项，从而决定视觉编码器是否值得跨卡切分、批大小上限以及是否改用 token 压缩降低 S。","常见误用：把 GB200 约 1.8 TB/s 的峰值带宽直接当作有效带宽代入，忽略环状算法 60%–80% 的效率折损与多轮 all-to-all 的累加，导致容量规划偏乐观；另一误用是只算一次通信而漏掉流水中的重复集合通信，实测时延可达下界的数倍。"],"anchors":["GB200 约 1.8 TB/s","有效带宽通常只有峰值的 60%–80%"],"pitfalls":["把 NVLink 双向峰值带宽当作环状 all-reduce 的有效带宽，忽略 60%–80% 的效率折损，容量规划系统性偏乐观。","只按单次 all-reduce 估算，漏算多模态流水中的多次 all-to-all 与专家路由通信，实测端到端时延远超下界。","视觉 token 数增大后仍按计算时间做并行度决策，未重算通信项，导致张量并行度选得过高、通信反而成为主瓶颈。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-1\">一 · 一句话直觉与它到底在说什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-2\">二 · 严格定义：下界、变量与推导的那一步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-3\">三 · 为什么需要这个下界：三个工程决策点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-4\">四 · 常见误解：峰值带宽、单次通信、静态并行度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-5\">五 · 一个具体例子：ViT 张量并行下的交叉点估算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-6\">六 · 失效条件与工程判断的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-7\">七 · 下界成立的前提，以及它在哪里失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-8\">八 · 带宽放大因子从哪来：两阶段搬运的账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-9\">九 · 有效带宽折损：为什么不能直接代峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-10\">十 · 固定延迟项 τ_lat 的构成与量级判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-11\">十一 · 从单次 all-reduce 到流水累加：离散化的第二个落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-12\">十二 · 反解并行度：公式作为容量决策工具</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-13\">十三 · 失效条件的工程读法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-14\">十四 · 带宽项之外的三个折损因子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-15\">十五 · 带宽项的适用前提：单次、单环、无拥塞</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-16\">十六 · 有效带宽折损：峰值不是分母</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-17\">十七 · 多轮累加：流水中的第 k 次通信</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-18\">十八 · 规模上限：N 增大后公式的退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-19\">十九 · 失效条件的识别与替代判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-20\">二十 · 边界在哪里：从单次 all-reduce 到多模态流水拓扑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-21\">二十一 · 从下界到决策变量：把不等式改写成可解的预算式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-22\">二十二 · 定批大小：用通信项给 batch 设上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-23\">二十三 · 定并行度：交点两侧的取舍与“切不切”的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-24\">二十四 · 定 KV 预算：把通信下界折算成显存配额</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-25\">二十五 · 定 SLO：把下界当作容量承诺的硬底</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-26\">二十六 · 算例：一次完整的反解过程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-27\">二十七 · 把下界变成决策变量：反解 N、S 与批大小</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-28\">二十八 · 把下界换算成决策量：反解 N、批上限与 KV 预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-29\">二十九 · 误用一：把峰值带宽当有效带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-30\">三十 · 误用二：只算一次通信，漏掉流水中的重复集合通信</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-31\">三十一 · 误用三：token 数增大后不重算通信项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-32\">三十二 · 一个反例：把下界当成上界的规划</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-33\">三十三 · 识别清单与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-comm-lower-bound-sec-34\">三十四 · 峰值带宽不是有效带宽：三个把下界算成幻觉的误用</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:521px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 521.1 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"439.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"439.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：在 GB200/GB300 NVL72 上做视觉编码器张量并行或分…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"439.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$T_{\\text{comm}}\\ \\ge\\ \\frac{2\\,…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"439.1\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：仅建模单次 all-reduce 的带宽项；实际多模态流水含多次 …</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-nvl72-comm-lower-bound-sec-1\">一 · 一句话直觉与它到底在说什么</h3>\n<p>把一次集合通信必须搬运的字节数，除以单卡 NVLink 聚合带宽，得到的就是通信时间的物理下限。这句话听起来像同义反复，但它的分量在于“必须”二字：无论你用 TensorRT-LLM 的插件、vLLM 的 custom all-reduce、还是 NCCL 的 ring/tree 实现，只要数据要从一张卡的 HBM 走到另一张卡的 HBM，跨过 NVLink 的那一段字节数就摆在那里，带宽就摆在那里，商就是下限。视觉 token 越多，这个商越大，它越容易压过单卡计算时间，成为端到端瓶颈。</p>\n<p>在 GB200/GB300 NVL72 上做视觉编码器张量并行，或者做分离式预填/解码时，跨 GPU 的 all-reduce 与 all-to-all 是流水里绕不开的动作。ViT 的 patch 激活要按 token 维切分到多卡，注意力层的输出投影要 all-reduce 回来；分离式部署里 prefill 实例产出的 KV 分片要 all-to-all 送到 decode 实例。这些动作的字节量随视觉 token 数线性增长，而单卡算力是固定的，于是存在一个交叉点：在此之前计算主导，在此之后通信主导。下界公式的价值就是让你在写第一行调度代码之前，先把交叉点算出来。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-2\">二 · 严格定义：下界、变量与推导的那一步</h3>\n<p>本系列讨论的下界，指在给定并行度 N、给定单次消息字节数 S、给定单卡 NVLink 聚合带宽 BW<sub>NVLink</sub> 的前提下，一次环状 all-reduce 在理想无拥塞、无协议开销之外的纯带宽约束下所需时间的最小值。它不是实测时延的预测器，而是实测时延不可逾越的地板。形式化为：</p>\n<div class=\"formula\">$$T_{\\text{comm}}\\ \\ge\\ \\frac{2\\,(N-1)}{N}\\cdot\\frac{S}{\\text{BW}_{\\text{NVLink}}}+\\tau_{\\text{lat}}$$</div>\n<p>变量含义需要钉死：N 是参与该次集合通信的 GPU 数，不是整个 NVL72 机柜的 72，也不是单机 NVLink 域的 4 或 8——这一点在后文拓扑累加时会反复用到；S 是单次通信的消息字节数，典型取值是视觉 token 激活（batch × 视觉 token 数 × 隐藏维 × 精度字节）或 KV 分片；BW<sub>NVLink</sub> 是单 GPU 的 NVLink 聚合带宽，GB200 上约 1.8 TB/s 量级；τ<sub>lat</sub> 是 kernel 启动与协议固定延迟，与 S 无关，因此在小消息场景下它反而主导。</p>\n<p>推导的关键一步在于环状 all-reduce 的两阶段结构。它拆成 reduce-scatter 与 all-gather：reduce-scatter 阶段每卡把自己的分片发给下游并累加，搬运量为 (N−1)/N·S；all-gather 阶段把归约好的分片广播回去，搬运量同样是 (N−1)/N·S。两阶段合计 2(N−1)/N·S，再除以单卡带宽即得带宽项。系数 2(N−1)/N 就是带宽放大因子：每卡实际收发的数据约为自身分片的两倍，N 增大时趋近 2 但永不达到，N=2 时为 1，N=8 时为 1.75。这个因子解释了为什么“数据量除以带宽”不能直接当成答案——它漏掉了环状算法固有的这份放大。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-3\">三 · 为什么需要这个下界：三个工程决策点</h3>\n<p>第一个决策点是视觉编码器是否值得跨卡切分。ViT 的计算量随 token 数增长，但它的层内 all-reduce 字节量也随 token 数增长。给定 S 与 N，公式可反解出通信时间随 N 的变化曲线：N 小时带宽项低但单卡计算项高，N 大时计算项被摊薄而通信项按 (N−1)/N 上升并叠加 τ<sub>lat</sub>。两条曲线的交点就是切分的经济边界。工程判断落在这里：如果视觉 token 数已经很大，把 ViT 切到 8 卡未必比 4 卡快，因为多出来的 4 卡带来的计算收益被 all-reduce 的字节搬运吃掉。</p>\n<p>第二个决策点是批大小上限。批大小直接放大 S，而 S 放大带宽项。当 decode 阶段的 KV 分片需要跨卡 all-to-all 时，批大小翻倍意味着通信时间翻倍，而单卡计算时间只翻倍在算力饱和区才成立；在算力未饱和区，通信项的增长快于计算项，批大小上限由通信下界而非显存容量决定。这与“显存够就能加批”的直觉相反，是分离式预填/解码部署里最常见的容量误判来源。</p>\n<p>第三个决策点是是否改用 token 压缩降低 S。视觉 token 压缩（如 patch 合并、token 剪枝）在精度侧有独立的误差界，但在通信侧它的收益可以直接用本公式量化：S 减半，带宽项减半，交叉点右移。这条路径的代价是精度损失，收益是通信下界下降，两者之间的取舍需要把公式和误差界并排放才能做。这也是为什么本卷把通信下界与量化/压缩误差界分开成条——它们回答的是同一个容量问题的两个侧面。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-4\">四 · 常见误解：峰值带宽、单次通信、静态并行度</h3>\n<p>最普遍的误用是把 GB200 约 1.8 TB/s 的峰值带宽直接代入分母。NVLink 标称带宽是双向峰值，而环状 all-reduce 的有效带宽通常只有峰值的 60%–80%。直接代入峰值会让下界系统性偏低，容量规划随之系统性偏乐观——你以为还有余量，实测已经撞墙。正确做法是把有效带宽写成峰值乘以效率折损系数，并把折损系数当作拓扑与算法共同决定的量，而不是一个可以忽略的常数。</p>\n<p>第二个误解是只算一次通信。真实多模态流水含多次 all-to-all：视觉 token 分发、专家路由（MoE 层）、序列并行中的激活重分布，每一次都有自己的 N 与 S。公式只建模单次 all-reduce 的带宽项，多轮通信必须按拓扑逐次累加，并且要计入拥塞——多轮通信在同一组链路上叠加时，有效带宽进一步下降。只按单次估算的结果，实测端到端时延可达下界的数倍，这不是公式错了，而是公式的适用边界被越过了。</p>\n<p>第三个误解是并行度决策静态化。视觉 token 数在推理过程中并非恒定：高分辨率输入、多帧视频、动态 patch 策略都会让 S 在请求之间波动。若按最小 S 选定张量并行度，遇到大 S 请求时通信项骤增，张量并行度显得过高，通信反成主瓶颈；若按最大 S 选定，小请求时又浪费了本可用于更大批的算力。工程上的正解是把 N 做成随 S 调整的量，或者用 token 压缩把 S 的方差压下来，而不是一次性拍定并行度。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-5\">五 · 一个具体例子：ViT 张量并行下的交叉点估算</h3>\n<p>设视觉编码器在 GB200 上做张量并行，N=8，单次 all-reduce 的消息是某层的输出激活。取 S 为 batch 与视觉 token 数之积乘以隐藏维与精度字节；定性地说，当视觉 token 数从数百量级升到数千量级时，S 随之线性上升。带宽项按公式为 2×7/8×S/1.8 TB/s，若再乘 0.7 的有效带宽折损，分母实际按约 1.26 TB/s 计。此时每 GB 量级的 S 对应的带宽项在毫秒量级，而 τ<sub>lat</sub> 在微秒量级——大 S 时带宽项主导，小 S 时 τ<sub>lat</sub> 不可忽略。</p>\n<p>把这个估算与单卡计算时间并排：单卡计算时间随 S 线性增长但斜率由算力决定，通信时间随 S 线性增长但斜率由 1/BW 决定。两条直线的斜率之比就是交叉点的位置。工程含义很直接：如果视觉 token 数已经让通信斜率超过计算斜率，那么增加 N 只会让带宽放大因子从 1.75 缓慢趋近 2，收益递减；此时正确的动作是降低 S（token 压缩）或改变切分维度（沿 batch 而非 token 切分，减少 all-reduce 频次），而不是继续加卡。</p>\n<table class=\"mini\"><thead><tr><th>量</th><th>符号</th><th>在本例中的角色</th><th>工程影响</th></tr></thead><tbody><tr><td>并行度</td><td>N</td><td>决定放大因子 2(N−1)/N</td><td>N=8 时因子 1.75，继续加卡收益递减</td></tr><tr><td>消息字节</td><td>S</td><td>随视觉 token 数线性增长</td><td>压缩 S 是降下界最直接的杠杆</td></tr><tr><td>峰值带宽</td><td>BW<sub>NVLink</sub></td><td>GB200 约 1.8 TB/s</td><td>须乘 60%–80% 折损再代入</td></tr><tr><td>固定延迟</td><td>τ<sub>lat</sub></td><td>kernel 启动与协议开销</td><td>小 S 场景下主导，不可省</td></tr></tbody></table>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-6\">六 · 失效条件与工程判断的落点</h3>\n<p>公式的失效条件必须写在明面上：它只建模单次 all-reduce 的带宽项。一旦流水里出现多次 all-to-all、专家路由、序列并行激活重分布，就必须按拓扑累加并考虑拥塞；一旦消息小到 τ<sub>lat</sub> 与带宽项同量级，固定延迟项就必须保留；一旦把峰值带宽当作有效带宽，整个下界就失去约束力。这三条失效条件对应三种失败模式：容量规划偏乐观、实测时延远超下界、并行度选得过高导致通信反成主瓶颈。</p>\n<p>工程判断的落点因此不是“记住公式”，而是“知道公式在哪一步停止有效”。在单次 all-reduce、大消息、无拥塞的理想段，公式给出的是硬地板，任何实现都不可能低于它，此时优化空间只在 τ<sub>lat</sub> 与效率折损上；在多轮 all-to-all 叠加的真实流水段，公式给出的是逐轮地板之和的下界，实际时延由拓扑与拥塞决定，优化空间在通信调度与拓扑映射上。把这两段分开对待，才不会用单次公式去解释多轮实测，也不会用实测去否定公式——它们描述的是不同粒度的事实。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-7\">七 · 下界成立的前提，以及它在哪里失效</h3>\n<p>这个下界之所以有用，恰恰因为它是一个“不可能更快”的陈述：任何实测通信时间低于该式给出的值，只可能是测量口径错了（比如只计了 kernel 时间而漏掉协议栈），而不是硬件突破了物理。但它的严格性有明确边界。第一，它假设通信是<strong>单次、无竞争、拓扑理想</strong>的集合操作：环状 all-reduce 的带宽放大因子 <span>2(N−1)/N</span> 来自 reduce-scatter 与 all-gather 两阶段各搬运 <span>(N−1)S/N</span> 字节的对称结构，一旦换成 all-to-all（视觉 token 分发、专家路由）或树形/双二叉树算法，放大因子与阶段数都要重写。第二，它把 <span>τ_lat</span> 当作与消息大小无关的常数叠加，这在 <span>S</span> 小到与单条消息粒度相当时会主导结果——此时下界退化为“延迟下界”而非“带宽下界”，继续用带宽项做容量规划就失去意义。第三，它默认 <span>BW_NVLink</span> 是可持续的有效带宽，而 GB200 约 1.8 TB/s 是双向峰值，环状算法实际只能取到峰值的 60%–80%，把峰值直接代入等于系统性低估时延。</p>\n<div class=\"formula\">$$T_{\\text{comm}}^{\\text{eff}}\\ \\ge\\ \\frac{2(N-1)}{N}\\cdot\\frac{S}{\\eta\\cdot \\text{BW}_{\\text{NVLink}}}+\\tau_{\\text{lat}},\\quad \\eta\\in[0.6,\\,0.8]$$</div>\n<p>失效条件可以归成三类，工程上必须分开处理。其一是<strong>流水多次性</strong>：多模态预填里视觉 token 要经历编码器张量并行的 all-reduce、跨卡 token 重排的 all-to-all、以及分离式预填/解码之间的 KV 分片传输，每一轮都贡献一个独立的下界项，端到端下界应按拓扑逐次累加而非取最大值，实测时延达到单次下界的数倍属于正常而非异常。其二是<strong>拥塞与拓扑非对称</strong>：NVL72 机柜内 NVLink 域并非全互联等价，跨 NVLink 交换机的流量与同托盘内流量代价不同，按单一 <span>BW</span> 建模会把最坏路径藏起来。其三是<strong>并行度决策的静态性</strong>：视觉 token 数 <span>S</span> 随分辨率与帧数增长，若仍按计算时间选张量并行度 <span>N</span>，会在 <span>S</span> 增大后使通信项反超计算项，此时正确动作是降低 <span>N</span>、压缩 token 或改走分离式部署，而不是继续加卡。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>后果</th><th>修正</th></tr></thead><tbody><tr><td>代入 1.8 TB/s 峰值</td><td>时延低估约 1/η 倍</td><td>乘 0.6–0.8 效率折损</td></tr><tr><td>只算一次 all-reduce</td><td>端到端偏乐观数倍</td><td>按流水逐轮累加</td></tr><tr><td>S 增大后不重算</td><td>N 选得过高，通信成主瓶颈</td><td>反解 N 的拐点</td></tr></tbody></table>\n<p>因此这个下界的正确用法是<strong>反解而非正算</strong>：给定 <span>S</span> 与候选 <span>N</span>，解出使 <span>T_comm</span> 恰好等于单卡计算时间 <span>T_comp</span> 的临界并行度，超过它就该停止切分。代价在于，这个反解对 <span>η</span> 与 <span>τ_lat</span> 的取值高度敏感——<span>τ_lat</span> 随 kernel 融合程度与协议实现变化，<span>η</span> 随消息大小与并发流数变化，二者都不是硬件常数而是部署参数。把下界当作 SLA 容量规划的输入时，必须把这两个量当作需要实测标定的区间，而不是查表得到的定值；否则下界会从“保守的物理约束”退化为“乐观的营销数字”。</p>\n<h3 id=\"th-nvl72-comm-lower-bound-sec-8\">八 · 带宽放大因子从哪来：两阶段搬运的账</h3>\n<p>公式第一项 $$\\frac{2(N-1)}{N}\\cdot\\frac{S}{\\mathrm{BW}_{\\mathrm{NVLink}}}$$ 里的系数不是拟合出来的经验常数，而是环状 all-reduce 两阶段搬运量的精确记账。把 <code>N</code> 张卡排成逻辑环，每卡持有 <code>S</code> 字节消息的一个等分片 <code>S/N</code>。reduce-scatter 阶段，每卡沿环向下游推送 <code>N-1</code> 次，每次推 <code>S/N</code> 字节，累计发出 $$\\frac{N-1}{N}S$$；同时上游推来的数据被接收并归约，接收量相同。all-gather 阶段把归约完成的各分片再沿环传播一圈，搬运量又是一份 $$\\frac{N-1}{N}S$$。两阶段相加即得系数 <code>2(N-1)/N</code>。</p>\n<p>这个系数的物理含义是：每卡实际收发的字节数相对于“只搬自己那一份”的放大倍数。N=2 时为 1，N=8 时为 1.75，N=72 时为 1.972。它随 N 单调上升并趋近 2，说明大并行度下带宽项几乎等于“把整条消息搬两遍”。工程判断上，这意味着把视觉编码器的张量并行度从 8 提到 72，单卡承担的搬运量并没有按 1/N 缩小，而是停在约 2S/N 的量级——并行度带来的收益在带宽项上被这个趋近 2 的因子吃掉一半。</p>\n<p>推导的关键步不在系数本身，而在“每阶段每卡只搬 <code>(N-1)/N·S</code>”这一句：它假定了环上无阻塞、无重传、每跳都是满带宽的点对点传输。这一步把拓扑抽象成了均匀环，代价是丢掉了真实 NVL72 机柜内非均匀跳数、跨 NVLink Switch 域与同域通信的差异。因此公式给出的是下界，不是预测值。</p>\n<div class=\"formula\">$$T_{\\text{comm}}\\ \\ge\\ \\frac{2\\,(N-1)}{N}\\cdot\\frac{S}{\\text{BW}_{\\text{NVLink}}}+\\tau_{\\text{lat}}$$</div>\n<p>具体例子：视觉编码器在 N=8 上做张量并行，单次 all-reduce 的消息量 S 取 64 MB（一批视觉 token 激活的量化后规模），代入 1.8 TB/s 峰值得带宽项约 1.75×64 MB / 1.8 TB/s ≈ 62 μs。若同一批的编码器计算在单卡上耗时低于此值，切分就失去了意义——这是容量规划里最直接的一次反解。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-9\">九 · 有效带宽折损：为什么不能直接代峰值</h3>\n<p>公式分母写的是 <code>BW_NVLink</code>，但 GB200 约 1.8 TB/s 是双向聚合峰值，环状 all-reduce 的有效带宽通常只有峰值的 60%–80%。折损来自三处：环上每一跳的收发必须同时占用两个方向的链路，协议头与流控开销吃掉一部分；reduce-scatter 与 all-gather 之间存在阶段切换的同步点，环内各卡的进度差异造成空转；NVL72 内跨 NVLink Switch 的流量与同域直连流量共享物理通道，拥塞时有效带宽进一步下降。</p>\n<p>把折损写进公式的方式不是修改系数，而是替换分母：令 $$\\mathrm{BW}_{\\text{eff}}=\\eta\\cdot\\mathrm{BW}_{\\text{NVLink}},\\ \\eta\\in[0.6,0.8]$$，则带宽项变为 $$\\frac{2(N-1)}{N}\\cdot\\frac{S}{\\eta\\,\\mathrm{BW}_{\\mathrm{NVLink}}}$$。这一替换使下界上移 25%–67%，且 N 越大、环越长、阶段切换次数越多，η 越靠近区间下沿。工程上应把 η 当作与拓扑和消息大小相关的函数而非常数：小消息（KB 级）时协议开销占比高，η 偏低；大消息（MB 级以上）时 η 趋近上沿。</p>\n<p>系统代价直接体现在容量规划的方向性上：用峰值带宽算出的通信时间会系统性偏乐观，导致在“通信项尚未超过计算项”的错误判断下把张量并行度选高。一个可操作的校准方法是，在同一 NVL72 域内用固定 S 做一次实测 all-reduce，反解出该拓扑下的 η，再代回公式。这比任何标称参数都可靠，因为 η 同时吸收了拥塞与协议实现差异。</p>\n<p>例子：同样 S=64 MB、N=8，若 η 取 0.7，带宽项从 62 μs 升至约 89 μs，接近 1.4 倍。对于解码阶段每 token 都要做一次 all-reduce 的流水，这个差值会按层数累乘，直接改变端到端 token 间隔的估算。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-10\">十 · 固定延迟项 τ_lat 的构成与量级判断</h3>\n<p><code>τ_lat</code> 被写成与消息大小无关的常数项，这是公式里最需要警惕的近似。它的物理构成包括 kernel 启动开销、集合通信库的协议握手、以及环建立与同步屏障的固定成本。在 NVL72 这种单域内，τ_lat 的量级通常在微秒级，对 MB 级消息可以忽略，但对 KB 级消息——例如专家路由的 token 分发、序列并行中的小分片 KV 交换——τ_lat 可能压过带宽项成为主导。</p>\n<p>判断何时可以丢掉 τ_lat：令带宽项等于 τ_lat，解出临界消息量 $$S^{*}=\\frac{\\tau_{\\text{lat}}\\,\\eta\\,\\mathrm{BW}_{\\mathrm{NVLink}}\\,N}{2(N-1)}$$。当 S 远大于 S* 时公式退化为纯带宽下界；当 S 接近或小于 S* 时，τ_lat 必须保留，否则下界会低于物理可实现值，失去“下界”的意义。这一步是推导中离散化/近似的第一个落点：把连续变化的启动开销压缩成一个常数，只在 S ≫ S* 的区间成立。</p>\n<p>系统代价上，τ_lat 对延迟敏感型负载（分离式解码、投机解码的验证轮）影响显著：每轮多次小 all-reduce 时，固定延迟按次数线性累加，而带宽项几乎不增长。这解释了为什么小消息高频通信的流水不能靠提高并行度来加速——加卡只缩小带宽项，τ_lat 不变。</p>\n<p>例子：专家路由把一批 token 按专家分散到 N=72 张卡，单卡分片仅数百 KB。此时带宽项约 2×0.3 MB / (0.7×1.8 TB/s) ≈ 0.5 μs，而 τ_lat 在微秒级，两者同量级，公式必须保留第二项才能作为有效下界。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-11\">十一 · 从单次 all-reduce 到流水累加：离散化的第二个落点</h3>\n<p>公式只建模一次 all-reduce，而真实多模态流水含多次集合通信：视觉 token 从编码器卡分发到语言模型卡（all-to-all）、专家路由（all-to-all）、序列并行中的激活归约（all-reduce）、以及分离式预填/解码之间的 KV 分片传输。把单次下界当作端到端下界，是把一个离散序列近似成了单点。</p>\n<p>正确的累加方式是按拓扑逐次求和，并对每次通信取各自的 N、S、η：</p>\n<div class=\"formula\">$$T_{\\text{pipe}}\\ \\ge\\ \\sum_{k}\\left[\\frac{2(N_k-1)}{N_k}\\cdot\\frac{S_k}{\\eta_k\\,\\mathrm{BW}_{\\mathrm{NVLink}}}+\\tau_{\\text{lat},k}\\right]$$</div>\n<p>这里的近似在于：求和假定各次通信串行、互不重叠。实际流水可以通过通信与计算重叠、不同通信流走不同链路来压缩总时间，因此串行求和给出的是偏保守的上界式下界——它保证实际时间不会低于此值，但可能远高于真正可达的最优。工程上应把该和式当作“无重叠假设下的下界”，再用重叠机会去解释实测与它的差距。</p>\n<p>离散化的代价还体现在消息大小的取整上：视觉 token 数乘以每 token 激活字节得到 S，但实际分片必须按对齐粒度切分，尾部填充使有效 S 略大于理论值；当 token 数不能被 N 整除时，环上各卡负载不均，最慢一卡决定阶段时间，等效于把 S 向上取整到 N 的倍数。这一效应在小 batch、大 N 时不可忽略。</p>\n<p>例子：一条视觉问答流水含视觉 token 分发（all-to-all，S 较大）、语言侧逐层 all-reduce（每层 S 为隐藏维激活）、以及专家路由（小 S 高频）。逐项累加后，若视觉分发项占比过半，则优化重点应放在降低视觉 token 数 S 上，而不是提高语言侧并行度——这是公式逐项拆解后才能做出的判断。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-12\">十二 · 反解并行度：公式作为容量决策工具</h3>\n<p>公式的实用价值在于可反解。给定单卡计算时间 <code>T_comp</code>（与 N 近似成反比，受单卡算力上限约束）与通信下界，令两者相等可解出通信开始主导的临界并行度：</p>\n<div class=\"formula\">$$N^{*}\\ \\text{满足}\\ \\frac{T_{\\text{comp,1}}}{N^{*}}\\ \\approx\\ \\frac{2(N^{*}-1)}{N^{*}}\\cdot\\frac{S}{\\eta\\,\\mathrm{BW}_{\\mathrm{NVLink}}}+\\tau_{\\text{lat}}$$</div>\n<p>由于带宽项随 N 趋近饱和（系数趋近 2，而 1/N 的收益消失），而计算项持续按 1/N 下降，两条曲线必在某个 N* 相交；超过 N* 后继续加卡只会增加通信占比而不缩短端到端时间。这个交点就是“视觉编码器是否值得跨卡切分”的判据：若单卡已能容纳编码器且 T_comp 低于单次通信下界，切分无益。</p>\n<p>决策还牵动批大小上限：增大 batch 会同时抬高 S 与 T_comp，但 S 的增长通常快于计算的有效增长（激活字节随 token 数线性增长，而算力利用在大 batch 下趋于饱和），因此大 batch 下通信项更容易越界。反过来，降低 S 的手段——视觉 token 压缩、KV 分片量化——直接按比例压低带宽项，是比调并行度更有效的杠杆。</p>\n<p>系统代价的量化方式：把 N* 代回公式得到该点的通信时间，与单卡计算时间对比，差值即为切分带来的净损失或净收益。若净损失为正，说明该并行度下通信已成主瓶颈，应回退并行度或改用 token 压缩。</p>\n<p>例子：视觉编码器单卡计算 200 μs、S=64 MB、η=0.7，代入得 N=8 时通信约 89 μs 仍低于计算，N=16 时通信项因系数趋近 2 而几乎不降、计算项降至 100 μs 以下，交点落在十余卡量级；再往上加卡，通信占比反超，切分失去意义。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-13\">十三 · 失效条件的工程读法</h3>\n<p>公式的三条失效条件对应三类系统性误判，每类都有明确的修正动作。第一类是把双向峰值当有效带宽：修正动作是引入 η 并用实测反解，而非查标称参数。第二类是只算单次通信：修正动作是按流水拓扑列出全部集合通信并逐项累加，特别检查专家路由与序列并行这类易被漏掉的小消息高频项。第三类是视觉 token 数增大后未重算通信项：修正动作是把 S 作为随 batch 与分辨率变化的变量，在每次批调度决策时重跑反解，而不是沿用上一次的并行度。</p>\n<p>这三类误判的共同根源是公式的线性化假设：它把带宽项写成 S 的线性函数、把延迟写成常数、把多次通信写成一次。真实系统在这些维度上都是非线性的——η 随 S 与拓扑变化，τ_lat 随消息数累加，拥塞随并发流数量上升。因此公式的正确用法不是预测绝对时延，而是给出方向性判据：通信项是否已经压过计算项、加卡是否还有收益、降低 S 是否比调 N 更划算。</p>\n<p>工程判断落在最后一个具体机制上：在 NVL72 上做视觉编码器切分或分离式预填/解码时，先测该拓扑下目标消息大小的 η，再按流水逐项累加得到 T_pipe 下界，最后与单卡计算时间比较决定 N。任何跳过 η 实测、跳过逐项累加、跳过 S 随 batch 重算的容量规划，都会把下界当成预测值使用，从而在通信已成瓶颈时仍误判为计算受限。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-14\">十四 · 带宽项之外的三个折损因子</h3>\n<p>公式里的 $$\\frac{2(N-1)}{N}$$ 只刻画了环状算法本身的搬运量放大，它随 N 增大迅速饱和到 2，所以并行度从 8 提到 16 时这一项几乎不变——真正让下界失效的不是算法因子，而是把峰值带宽当成有效带宽。GB200 单卡 NVLink 聚合带宽约 1.8 TB/s 是双向峰值，环状 all-reduce 的 reduce-scatter 与 all-gather 两阶段各自只能跑单向流量，实测有效带宽通常落在峰值的 60%–80%。这意味着直接代入 1.8 TB/s 得到的下界系统性偏乐观，容量规划里应当把分母写成 $$\\text{BW}_{\\text{eff}} = \\eta \\cdot \\text{BW}_{\\text{NVLink}},\\ \\eta \\in [0.6, 0.8]$$，并把 $$\\eta$$ 当作随拓扑规模劣化的量而非常数：N 越大、跨的 NVLink 域越多，拥塞与路由跳数把 $$\\eta$$ 推向区间下沿。</p>\n<p>第二个折损来自流水中的通信次数。视觉编码器张量并行只做一次 all-reduce，但分离式预填/解码的多模态流水至少含视觉 token 分发、专家路由、序列并行三处 all-to-all，每一次都有自己的 S 与 N。正确的下界是逐次累加而非取最大值：</p>\n<div class=\"formula\">$$T_{\\text{comm}} \\ge \\sum_{k} \\left[ \\frac{2(N_k-1)}{N_k}\\cdot\\frac{S_k}{\\eta_k\\,\\text{BW}_{\\text{NVLink}}} + \\tau_{\\text{lat},k} \\right]$$</div>\n<p>其中下标 k 遍历流水中的每一次集合通信。漏掉任何一项，实测端到端时延都会达到单次下界的数倍——这正是“只算一次通信”这类误用的代价来源。$$\\tau_{\\text{lat}}$$ 在小消息场景下不可忽略：视觉 token 分片被压缩到几十 KB 量级时，带宽项趋近于零，kernel 启动与协议握手成为主项，此时提高并行度只会增加 $$\\tau_{\\text{lat}}$$ 的累加次数。</p>\n<p>第三个折损是离散化：token 数必须按并行度切分对齐，S 不能连续取值。设视觉 token 数为 V、隐藏维为 d、每 token 字节为 b，则单次 all-to-all 的实际消息量为 $$S = \\lceil V/N \\rceil \\cdot N \\cdot d \\cdot b$$，向上取整带来的浪费在 V 不能被 N 整除时可达一个分片的量级。工程判断因此落在两点：当 $$\\eta$$ 取 0.6、流水含三次 all-to-all 时反解出的临界 N 往往比按峰值单次估算的低一半，视觉编码器跨卡切分在 N 超过该临界点后不再划算；此时改用 token 压缩降低 S，比继续加卡更能压低端到端时延。</p>\n<h3 id=\"th-nvl72-comm-lower-bound-sec-15\">十五 · 带宽项的适用前提：单次、单环、无拥塞</h3>\n<p>公式里的带宽项 $$\\frac{2(N-1)}{N}\\cdot\\frac{S}{\\mathrm{BW}_{\\mathrm{NVLink}}}$$ 成立，依赖三个未写进式子的隐含假设：其一，通信是<strong>单次</strong>集合操作，而不是流水中的第 k 次；其二，参与通信的 N 张卡构成<strong>单一环</strong>，每卡只与两个邻居交换；其三，链路上<strong>没有其他流量</strong>竞争，即该 all-reduce 独占 NVLink。工程上这三条几乎不会同时为真。视觉编码器的张量并行往往与数据并行的梯度桶、KV 分片的 all-to-all 共享同一条 NVLink 链路；NVL72 的机柜内拓扑是分层交换而非扁平全互联，跨 NVLink 域与域内的有效带宽并不相同。一旦链路被复用，分母上的 $$\\mathrm{BW}_{\\mathrm{NVLink}}$$ 就不再是单卡可用带宽，而是被按流量比例切分后的残余带宽，此时公式给出的是“独占条件下的下界”，实测时延必然高于它——这不是公式错了，而是把下界当成了预测值。</p>\n<p>判断公式是否还处在适用区，可以用一个简单的比值做闸门：令 $$\\rho = T_{\\text{comm}}^{\\text{lower}} / T_{\\text{comp}}$$，其中 $$T_{\\text{comp}}$$ 是该并行度下单卡承担的计算时间。当 $$\\rho \\ll 1$$ 时通信被计算掩盖，公式的误差无关紧要；当 $$\\rho$$ 接近或超过 1 时，通信项成为端到端时延的主项，此时公式中未建模的拥塞、多轮累加、有效带宽折损都会被放大到与主项同量级，公式从“紧下界”退化为“乐观下界”。容量规划真正需要的是后者失效的临界点，而不是公式在理想区的精确值。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-16\">十六 · 有效带宽折损：峰值不是分母</h3>\n<p>GB200 单卡 NVLink 聚合带宽约 1.8 TB/s 量级，这是双向峰值。环状 all-reduce 的每一阶段，每卡同时向一个邻居发送、从另一个邻居接收，单向链路上的实际吞吐受协议开销、报文切分、以及 reduce-scatter 与 all-gather 之间的同步屏障影响，有效带宽通常只有峰值的 60%–80%。把 1.8 TB/s 直接代入分母，等于把下界再往下压了 20%–40%，规划结果系统性偏乐观。正确的做法是引入效率因子 $$\\eta \\in [0.6, 0.8]$$，写成</p>\n<div class=\"formula\">$$T_{\\text{comm}}\\ \\ge\\ \\frac{2(N-1)}{N}\\cdot\\frac{S}{\\eta\\cdot \\mathrm{BW}_{\\mathrm{NVLink}}}+\\tau_{\\text{lat}}$$</div>\n<p>并明确 $$\\eta$$ 是拓扑与算法相关的经验折损，不是物理常数。举例：视觉编码器以 N=8 做张量并行，单个视觉 token 激活分片 S 取到 MB 量级时，带宽项已进入数十微秒量级；若误用峰值带宽，估算值会比按 0.7 折损后的值低三成，而这三成恰好可能是一次 all-to-all 与一次 all-gather 的差距。折损因子还随 N 变化：N 越大，环越长，同步屏障的等待占比越高，$$\\eta$$ 越靠近区间下沿。因此不能在全 N 范围内用同一个 $$\\eta$$，否则在 N 较大时又会低估时延。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-17\">十七 · 多轮累加：流水中的第 k 次通信</h3>\n<p>公式只描述一次 all-reduce。真实多模态推理流水至少包含：视觉 token 从编码器卡向语言模型卡的 all-to-all 分发、序列并行下的 all-gather、MoE 专家路由的 all-to-all、以及分离式预填/解码之间 KV 分片的搬运。每一次都是一次独立的集合通信，且消息大小 S 各不相同。总通信时间不是单次下界的倍数，而是按拓扑逐次累加：</p>\n<div class=\"formula\">$$T_{\\text{comm}}^{\\text{total}}\\ \\ge\\ \\sum_{k=1}^{K}\\left[\\frac{2(N_k-1)}{N_k}\\cdot\\frac{S_k}{\\eta_k\\cdot \\mathrm{BW}_{\\mathrm{NVLink}}}+\\tau_{\\text{lat},k}\\right]$$</div>\n<p>这里 $$N_k$$ 是第 k 次通信的参与卡数，$$S_k$$ 是第 k 次的消息字节数。累加的关键在于 $$N_k$$ 并不恒定：视觉 token 分发可能只在编码器子组内做 all-to-all（$$N_k$$ 小），而 KV 分片搬运跨越整个 NVL72 域（$$N_k$$ 大）。漏算任何一项，实测端到端时延都会达到下界的数倍。工程判断上，应当先列出流水中的全部集合通信点，标注各自的 N、S 与是否与其他流量重叠，再决定哪一项是主项。视觉 token 数增大时，最先膨胀的是视觉 token 分发那一项的 $$S_k$$，而不是 KV 分片项——这也是 token 压缩能直接压低总通信下界的原因。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-18\">十八 · 规模上限：N 增大后公式的退化</h3>\n<p>带宽放大因子 $$\\frac{2(N-1)}{N}$$ 随 N 单调趋近 2，看似 N 越大越“划算”，但这是单次通信视角的错觉。真实系统里，N 增大带来三重退化。第一，$$\\eta$$ 随环长下降，跨 NVLink 域的长环要经过更多交换级，有效带宽进一步折损。第二，$$\\tau_{\\text{lat}}$$ 虽然与消息大小无关，却随参与卡数增加而增加：更多卡意味着更长的同步屏障与更复杂的协议握手，固定延迟项在 N 大时不再可忽略。第三，多轮通信的项数 K 往往随并行度上升而增加（序列并行度提高会引入更多 all-gather）。因此存在一个规模上限 $$N^{\\star}$$，超过它之后通信项的增长快于计算项的下降，张量并行不再划算。反解 $$\\rho(N)=1$$ 得到的就是这个临界并行度；但反解时必须用折损后的 $$\\eta(N)$$ 与累加后的总通信项，否则解出的 $$N^{\\star}$$ 会偏高，导致并行度选得过大、通信反成主瓶颈。</p>\n<table class=\"mini\"><thead><tr><th>退化来源</th><th>随 N 的变化</th><th>对下界的影响</th><th>工程后果</th></tr></thead><tbody><tr><td>环长与交换级</td><td>$$\\eta$$ 下降</td><td>分母变小，下界抬高</td><td>峰值带宽代入更失真</td></tr><tr><td>同步屏障</td><td>$$\\tau_{\\text{lat}}$$ 上升</td><td>固定项占比增大</td><td>小消息时延被低估</td></tr><tr><td>并行维度增加</td><td>K 增大</td><td>累加项数增多</td><td>漏算风险上升</td></tr></tbody></table>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-19\">十九 · 失效条件的识别与替代判据</h3>\n<p>公式失效不是二值的，而是连续退化。可操作的识别方法是做“项占比审计”：分别计算带宽项、固定延迟项、以及未建模的拥塞余量各自在实测时延中的占比。若带宽项占比低于一半，说明公式处在适用区，可用于容量反解；若固定延迟项或拥塞余量占比超过带宽项，公式已不能作为预测工具，只能作为“绝不可能低于此值”的硬下界。此时应改用基于实测微基准的有效带宽曲线，或直接以拓扑感知的通信模型替代解析式。另一个失效信号是消息大小 S 落入“小消息区”：当 S 小到带宽项与 $$\\tau_{\\text{lat}}$$ 同量级时，公式对 S 的线性依赖不再成立，延迟由协议固定开销主导，此时降低 S（如 token 压缩）对总时延的收益远小于公式预示的收益。</p>\n<p>具体例子：分离式预填/解码场景下，预填节点向解码节点搬运 KV 分片，S 由序列长度与层数决定，N 为跨节点参与卡数。若只按单次 all-to-all 估算，会得出“通信可被计算掩盖”的结论；但实际流水里还有视觉 token 分发与专家路由两次通信，且跨节点链路的有效带宽低于机柜内，三项累加后通信项压过计算项。工程判断应落在：先确认视觉 token 数是否已通过压缩降低 S，再确认并行度是否停在 $$N^{\\star}$$ 以内，最后才用公式做容量反解——顺序颠倒就会得到偏乐观的批大小上限。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-20\">二十 · 边界在哪里：从单次 all-reduce 到多模态流水拓扑</h3>\n<p>这个下界成立的前提非常窄：它只描述一次环状 all-reduce 的带宽项。真实的多模态推理流水并不只做一次集合通信——视觉 token 分发、专家路由、序列并行切分、分离式预填与解码之间的 KV 分片搬运，各自都是一次独立的 all-to-all 或 all-reduce，且拓扑形状不同（有的走全连接环，有的走分层或分组交换）。正确的做法是按流水顺序逐次累加：$$T_{\\text{pipe}}\\ \\ge\\ \\sum_{k}\\left[\\frac{2(N_k-1)}{N_k}\\cdot\\frac{S_k}{\\text{BW}_{\\text{eff},k}}+\\tau_{\\text{lat},k}\\right]+\\sum_{j}T_{\\text{congest},j}$$，其中每个 $k$ 对应一轮通信，$N_k$ 是该轮的参与集合，$\\text{BW}_{\\text{eff},k}$ 是该拓扑下的有效带宽。工程上最容易犯的错是把第一轮的 $N$ 和 $S$ 套到整条流水上，得出一个漂亮的下界，然后在实测中看到数倍于它的端到端时延。累加时还要注意：不同轮的通信可能部分重叠（例如视觉编码与语言模型预填并行），重叠部分的实际下界是各轮时间的最大值而非总和，但重叠能否发生取决于调度器是否把通信与计算放进不同的流，这一点不能靠公式假设，必须看框架的实际执行图。</p>\n<p>第二个失效条件是带宽口径。GB200 的 NVLink 标称约 1.8 TB/s 是双向聚合峰值，而环状 all-reduce 的 reduce-scatter 与 all-gather 两阶段中，每卡在每个阶段只沿环的一个方向收发，有效带宽通常只有峰值的 60%–80%。直接把 1.8 TB/s 代入分母，等于系统性低估时延 25%–67%，容量规划随之偏乐观。更隐蔽的是，当 $S$ 很小时带宽项不再是主导，$\\tau_{\\text{lat}}$ 的固定开销（kernel 启动、协议握手、同步屏障）会吃掉大部分时间，此时公式退化为一个近似常数，继续用“除以带宽”的直觉去优化毫无意义——小消息场景该优化的是融合通信轮次、减少 kernel 数量，而不是提高并行度。反过来，当 $S$ 增大到视觉 token 数成千上万时，带宽项线性增长，通信项迅速压过单卡计算项，这时公式才真正具备决策价值。</p>\n<p>第三个边界是规模上限与拥塞。公式隐含“无拥塞、全互联、单跳”的理想拓扑假设。NVL72 机柜内 NVLink 域确实接近全互联，但一旦并行度跨出机柜、进入多机柜或多 Pod，流量要经过更少的链路和更复杂的路由，有效带宽进一步下降，且 all-to-all 的配对模式会产生热点链路，拥塞项 $T_{\\text{congest}}$ 不可忽略。此时公式给出的只是一个乐观下界，不能作为 SLO 承诺的依据。判断公式是否仍然适用的实用准则是：先算出带宽项与 $\\tau_{\\text{lat}}$ 的比值，若比值远大于一且并行度完全落在单个 NVLink 域内，公式可信；若比值接近一或并行度跨域，就必须用实测的 all-to-all 微基准替代解析下界。下表给出三种典型情形的适用性判断。</p>\n<table class=\"mini\"><thead><tr><th>情形</th><th>公式是否可信</th><th>主要偏差来源</th><th>系统代价表现</th></tr></thead><tbody><tr><td>单次 all-reduce，N 在单机柜内，S 大</td><td>可信，作下界用</td><td>有效带宽折损 60%–80%</td><td>带宽受限，时延随 S 线性增长</td></tr><tr><td>多轮 all-to-all 流水（视觉分发+专家路由）</td><td>需逐轮累加后才可信</td><td>漏算轮次与重叠判断</td><td>实测时延可达单轮下界的数倍</td></tr><tr><td>并行度跨机柜，或 S 极小</td><td>不可信</td><td>拥塞、跨域链路、固定延迟主导</td><td>热点链路排队，$\\tau_{\\text{lat}}$ 吃掉主要时间</td></tr></tbody></table>\n<p>由此得到一个具体的工程判断：并行度决策不能只做一次。视觉 token 数 $S$ 在预处理阶段就已知（分辨率、patch 大小、是否做 token 压缩），应把它作为输入反解通信项随 $N$ 的变化曲线，找到通信项开始超过单卡计算项的拐点 $N^\\*$，并把张量并行度压在拐点之下；一旦为了吞吐把 $N$ 推过拐点，增加的分片只会让 all-to-all 的消息数和轮次同时上升，通信成为主瓶颈而计算单元反而闲置。若业务上必须提高 $N$，正确的替代手段是降低 $S$——token 压缩、视觉侧降采样、把视觉编码器改为分离式预填并在独立资源池上消化——而不是继续加卡。这也解释了为什么在 NVL72 上做视觉编码器张量并行时，容量规划的第一问不是“能切多少卡”，而是“每轮通信搬多少字节、搬几轮、有效带宽按峰值的几折算”。</p>\n<h3 id=\"th-nvl72-comm-lower-bound-sec-21\">二十一 · 从下界到决策变量：把不等式改写成可解的预算式</h3>\n<p>前两部分把 <span class=\"formula-inline\">T_comm ≥ 2(N−1)/N · S/BW + τ_lat</span> 当作一个“判据”来用；在容量规划里它要更进一步，变成一个可反解的预算式。做法是把端到端时延目标拆成三段：单卡计算项 <span class=\"formula-inline\">T_comp = C/BW_c</span>（C 为该阶段浮点或访存工作量）、通信项下界、以及不可压缩的固定开销。给定 SLO 的每 token 时延预算 <span class=\"formula-inline\">T_slo</span>，决策问题写成：</p>\n<div class=\"formula\">$$\\frac{C(N)}{F_{\\text{eff}}(N)}+\\frac{2(N-1)}{N}\\cdot\\frac{S}{\\eta\\,\\text{BW}_{\\text{NVLink}}}+\\tau_{\\text{lat}}\\ \\le\\ T_{\\text{slo}}$$</div>\n<p>这里引入了两个前文没有显式出现的量：<span class=\"formula-inline\">η</span> 是环状算法的有效带宽折损（0.6–0.8），<span class=\"formula-inline\">F_eff(N)</span> 是切分后的有效算力——它随 N 增长但通常亚线性，因为切分带来额外的同步与流水气泡。工程上真正要解的是 <span class=\"formula-inline\">N</span>：左边第一项随 N 递减、第二项随 N 递增（<span class=\"formula-inline\">2(N−1)/N</span> 单调上升并趋近 2），两条曲线交点就是“通信开始压过计算”的并行度阈值。这个交点不是解析解，因为 <span class=\"formula-inline\">F_eff(N)</span> 是实测曲线；但交点两侧的斜率可以定性判断：若 <span class=\"formula-inline\">S</span> 大（视觉 token 多），第二项上升快，交点左移，意味着应当尽早停止加卡、转向降低 S。</p>\n<p>代价层面必须点明：把 <span class=\"formula-inline\">η</span> 从 1 改成 0.7，通信项直接放大 1.43 倍，在 S 较大时这一项往往就是主导项，容量规划会从“加卡能提速”翻转成“加卡更慢”。一个具体例子：某视觉编码器阶段单卡计算约 3 ms、S 取使带宽项在 N=8 时约 2 ms 的量级，若按峰值带宽估算会认为 N=16 仍有余量，按 0.7 折损重算后 N=16 的通信项已逼近 4 ms，超过计算项的下降幅度，结论从“扩到 16 卡”改为“维持 8 卡并压缩 token”。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-22\">二十二 · 定批大小：用通信项给 batch 设上限</h3>\n<p>批大小的直觉是“越大越省”，但在张量并行下这条直觉有硬顶。设每请求视觉 token 数为 <span class=\"formula-inline\">s</span>，批大小为 <span class=\"formula-inline\">B</span>，则单次 all-reduce 的消息量 <span class=\"formula-inline\">S = B·s·b_elem</span>（<span class=\"formula-inline\">b_elem</span> 为每 token 激活字节数，NVFP4/FP8 下差异显著）。代入下界得：</p>\n<div class=\"formula\">$$T_{\\text{comm}}(B)\\ \\ge\\ \\frac{2(N-1)}{N}\\cdot\\frac{B\\,s\\,b_{\\text{elem}}}{\\eta\\,\\text{BW}_{\\text{NVLink}}}+\\tau_{\\text{lat}}$$</div>\n<p>关键判断是通信项与计算项谁随 B 增长得更快。计算项在算力饱和前近似与 B 成正比（<span class=\"formula-inline\">T_comp ≈ B·c</span>，c 为每请求计算时间），通信项也近似与 B 成正比，因此比值 <span class=\"formula-inline\">T_comm/T_comp</span> 在饱和区内近似恒定——这意味着“加大 batch 不会让通信占比恶化”只在计算已饱和时成立；而在未饱和区，计算项被固定开销摊薄得更快，通信占比反而上升。真正的上限来自显存与 SLO 的联合约束：批越大，KV 与激活占用越高，且单批时延随 B 线性增长，一旦 <span class=\"formula-inline\">B·(c + t_comm)</span> 超过 <span class=\"formula-inline\">T_slo</span>，就必须在“降 B 保时延”和“降 N 保带宽”之间二选一。</p>\n<p>工程判断：先按 <span class=\"formula-inline\">η=0.7</span> 估出 <span class=\"formula-inline\">t_comm</span> 的单请求分量，再解 <span class=\"formula-inline\">B_max = ⌊(T_slo − τ_lat)/(c + t_comm_per_req)⌋</span>。举例：若每请求计算 1.2 ms、通信分摊 0.8 ms、<span class=\"formula-inline\">T_slo</span> 给 20 ms，则 <span class=\"formula-inline\">B_max ≈ 10</span>；把 <span class=\"formula-inline\">b_elem</span> 从 FP16 降到 FP8 使通信分摊降到 0.4 ms，<span class=\"formula-inline\">B_max</span> 升到 12——精度选择在这里直接换来批容量，而不是靠加卡。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-23\">二十三 · 定并行度：交点两侧的取舍与“切不切”的判据</h3>\n<p>并行度决策的本质是问：把视觉编码器切开，省下的计算时间是否大于新增的通信时间。设不切分时单卡计算为 <span class=\"formula-inline\">T_0</span>，切到 N 卡后计算降为 <span class=\"formula-inline\">T_0/κ(N)</span>（κ 为实测加速比，通常小于 N），则净收益为：</p>\n<div class=\"formula\">$$\\Delta(N)=\\frac{T_0}{\\kappa(N)}-\\frac{T_0}{1}-T_{\\text{comm}}(N)$$</div>\n<p><span class=\"formula-inline\">Δ(N) &lt; 0</span> 即“不值得切”。由于 <span class=\"formula-inline\">T_comm</span> 的带宽项随 N 趋近饱和（<span class=\"formula-inline\">2(N−1)/N → 2</span>），而 <span class=\"formula-inline\">κ(N)</span> 的增长越来越慢，<span class=\"formula-inline\">Δ(N)</span> 通常在某个 N 之后转负。这个转折点对 S 极其敏感：S 翻倍，通信项翻倍，转折点左移。因此并行度决策不能只看模型规模，必须把当前批的视觉 token 总量带进公式。分离式预填/解码场景下同理，只是 all-reduce 换成跨节点的 all-to-all，<span class=\"formula-inline\">τ_lat</span> 因跨机架跳数上升，转折点更早到来。</p>\n<p>代价视角：并行度过高的失败模式不是“慢一点”，而是通信项吃掉整条流水的主导权，此时 GPU 算力利用率与功耗效率同时恶化——卡在等数据，功耗却按满载计。具体例子：视觉 token 分发与专家路由两轮 all-to-all 串联时，若每轮按单次下界估 1.5 ms，实际因两轮累加与拥塞可达 3–4 ms 量级，此时 N=8 的切分收益已被抹平，正确动作是回到 N=4 并把 token 压缩作为主杠杆。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-24\">二十四 · 定 KV 预算：把通信下界折算成显存配额</h3>\n<p>KV 预算与通信下界通过“分片”耦合：序列并行或张量并行把 KV 切成 N 份，每卡显存占用降为 <span class=\"formula-inline\">M_kv/N</span>，但每次注意力相关的集合通信消息量 S 正是这些分片。于是存在一条显存—带宽的交换曲线：</p>\n<div class=\"formula\">$$M_{\\text{kv}}^{\\text{per-card}}=\\frac{M_{\\text{kv}}}{N},\\qquad T_{\\text{comm}}\\ \\ge\\ \\frac{2(N-1)}{N}\\cdot\\frac{M_{\\text{kv}}/N\\cdot r}{\\eta\\,\\text{BW}_{\\text{NVLink}}}+\\tau_{\\text{lat}}$$</div>\n<p>其中 r 为单位时间内的分片搬运次数（与解码步频、层数相关）。这条式子说明：为了省显存而提高 N，通信项并不按 <span class=\"formula-inline\">1/N</span> 下降，而是被 <span class=\"formula-inline\">2(N−1)/N</span> 抵消掉大半，净效果是“显存省了，带宽没省多少”。因此 KV 预算的正确做法是先定 SLO 允许的通信时间上限 <span class=\"formula-inline\">T_comm^max</span>，反解出可接受的 N 上限，再用 <span class=\"formula-inline\">M_kv/N</span> 得到每卡配额；若配额仍不够，杠杆应转向 KV 量化或 token 压缩，而不是继续加 N。举例：某解码阶段每步 KV 分片搬运在 N=8 时已占单步时延的可观比例，此时把 N 提到 16 只能把每卡 KV 减半，却让通信项几乎不变甚至上升，容量规划会误判为“显存够了所以能扩”，实际是拿时延换显存。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-25\">二十五 · 定 SLO：把下界当作容量承诺的硬底</h3>\n<p>SLO 承诺（如 P99 每 token 时延）在容量规划中必须建立在物理下界之上，否则承诺不可兑现。做法是把 <span class=\"formula-inline\">T_comm</span> 作为不可压缩项从 SLO 预算中先行扣除，剩余部分才分配给计算、调度与排队：</p>\n<div class=\"formula\">$$T_{\\text{slo}}^{\\text{usable}}=T_{\\text{slo}}-T_{\\text{comm}}^{\\text{lb}}(N,S,\\eta)-\\tau_{\\text{lat}}-T_{\\text{queue}}$$</div>\n<p>这个式子的工程含义是：通信下界是“无论怎么优化 kernel 都省不掉”的部分，把它放在预算最前面扣，能立刻暴露容量缺口。若 <span class=\"formula-inline\">T_slo^usable</span> 为负，说明当前 N 与 S 组合在物理上就不可能满足 SLO，任何调度技巧都无效，必须改拓扑或降 S。多轮 all-to-all 场景下要按拓扑逐次累加，把每轮的 <span class=\"formula-inline\">τ_lat</span> 也计入，因为固定延迟在小消息下占比极高。具体例子：视觉 token 分发、专家路由、序列并行三轮通信，若每轮带宽项 1 ms、固定延迟 0.2 ms，则下界合计约 3.6 ms；若 SLO 给 15 ms，可用预算只剩约 11 ms 减去排队，容量规划据此反推最大并发批数，而不是先拍一个批数再验证。</p>\n<p>误用防线：容量评审时把 <span class=\"formula-inline\">η</span> 显式写进表格、把轮数显式写进表格，任何“按峰值带宽、按单轮”的估算一律打回。这是把前文的失效条件转成流程约束——下界不是用来证明系统够快，而是用来证明某些配置根本不可能够快。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-26\">二十六 · 算例：一次完整的反解过程</h3>\n<p>设某视觉编码器阶段单卡计算 <span class=\"formula-inline\">T_0 = 6</span> ms（定性量级，用于演示流程），每请求视觉 token 激活 <span class=\"formula-inline\">s·b_elem</span> 使 N=4 时带宽项为 1.2 ms，<span class=\"formula-inline\">τ_lat = 0.3</span> ms，<span class=\"formula-inline\">η = 0.7</span>，SLO 每请求预算 20 ms。按公式逐 N 估算：N=4 时 <span class=\"formula-inline\">2(N−1)/N = 1.5</span>，通信项 ≈ 1.2/0.7×1.5/1.5 ≈ 1.7 ms（按同一 S 折算），加固定延迟约 2.0 ms；N=8 时放大因子升到 1.75，且 κ(8) 实测仅约 5 倍，计算降至 1.2 ms，通信项升至约 2.4 ms，合计 3.6 ms——仍优于 N=4 的 6+2.0=8.0 ms，故 N=8 值得切。N=16 时放大因子 1.875、κ(16) 约 7 倍，计算 0.86 ms，通信项约 2.8 ms，合计 3.7 ms，与 N=8 持平，说明交点已到，再加卡无收益。</p>\n<p>接着定批大小与 KV：单请求时延约 3.6 ms，SLO 20 ms 下理论批上限约 5（留排队余量取 4）；若把激活精度从 FP16 降到 FP8，S 减半使通信项降到约 1.4 ms，单请求 2.6 ms，批上限升到 7。KV 侧按 N=8 分片，每卡配额为总量的 1/8，若仍不足则优先 KV 量化而非提到 N=16。最终决策组合是：N=8、批 4–7、FP8 激活、KV 分片 8 路，并把 <span class=\"formula-inline\">η=0.7</span> 与三轮通信累加写进容量表。整个流程没有用到任何实测绝对值，只用了公式结构与给定锚点（1.8 TB/s 量级、60%–80% 折损），这正是下界在容量决策中的正确用法：它给出方向与硬底，而不是精确预测。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-27\">二十七 · 把下界变成决策变量：反解 N、S 与批大小</h3>\n<p>容量规划里真正有用的不是“通信要多久”，而是“通信项什么时候压过计算项”。把单卡计算时间记作 <span class=\"inline\">T<sub>comp</sub></span>（视觉编码器一层或一个分片的 kernel 时间），决策条件就是 <span class=\"inline\">T<sub>comm</sub>(N,S) ≤ T<sub>comp</sub>/N</span> 是否成立——切分到 N 卡后每卡计算量降为 1/N，但通信项随 N 单调趋近 2S/BW 而不再下降。于是存在一个拐点并行度：把公式第一项与 <span class=\"inline\">T<sub>comp</sub>/N</span> 联立，得到 <span class=\"inline\">N* ≈ T<sub>comp</sub>·BW<sub>eff</sub> / (2S)</span>（忽略 τ<sub>lat</sub> 的粗解），超过 N* 再加卡只增加通信不减少关键路径。这就是“视觉编码器是否值得跨卡切分”的定量判据：S 越大 N* 越小，高分辨率、多裁剪、长视频帧采样把 S 推上去之后，张量并行度必须相应调低，或者反过来用 token 压缩、pixel-shuffle、时序合并把 S 压下来换回并行空间。</p>\n<p>批大小上限同样由这个下界给出。分离式预填/解码里，预填充侧的视觉 token 激活要 all-to-all 分发到各解码实例，端到端每 token 预算为 SLO 的倒数，即 <span class=\"inline\">T<sub>budget</sub> = 1/λ<sub>req</sub></span> 摊到每个请求；单请求通信下界乘以流水中的集合通信轮数 k（视觉分发、序列并行、专家路由各算一轮），必须满足 <span class=\"inline\">k·T<sub>comm</sub> ≤ T<sub>budget</sub> − T<sub>comp</sub></span>，否则批再大也只是把排队时间换成通信时间。反解出 <span class=\"inline\">S<sub>max</sub> ≤ (T<sub>budget</sub> − T<sub>comp</sub>)·BW<sub>eff</sub> / (2k(N−1)/N)</span>，它直接约束单批可容纳的视觉 token 总量，也就约束了批大小与图像分辨率的上限。KV 预算同理：KV 分片在序列并行下按 S 搬运，KV 预算不能只按显存容量算，还要留出“每步 KV 集合通信时间 ≤ 解码步预算”的约束，长上下文场景下这一项往往先于显存触顶。</p>\n<p>算例：GB200 单卡 NVLink 聚合带宽按 1.8 TB/s 峰值计，环状 all-reduce 有效带宽取峰值的 60%–80%，即约 1.1–1.4 TB/s。设一次视觉 all-to-all 的消息量 S = 64 MB、N = 8，带宽放大因子 2(N−1)/N = 1.75，则带宽项为 1.75×64 MB / 1.2 TB/s ≈ 93 µs；若流水含 4 轮此类通信（视觉分发、两层专家路由、序列并行各一轮），累加约 0.37 ms，再叠加每轮 τ<sub>lat</sub> 的 kernel 启动与协议开销。若 SLO 给单请求预填充的预算是 1 ms 量级、计算项占 0.5 ms，则通信已吃掉剩余预算的大半，此时正确动作不是把 N 从 8 提到 16（放大因子仅从 1.75 升到 1.875，带宽项几乎不变而 τ<sub>lat</sub> 轮数翻倍），而是降 S 或减少通信轮数。</p>\n<table class=\"mini\"><thead><tr><th>决策</th><th>受哪个量支配</th><th>失效表现</th></tr></thead><tbody><tr><td>张量并行度 N</td><td>N* ≈ T<sub>comp</sub>·BW<sub>eff</sub>/(2S)</td><td>N 超过拐点，通信成主瓶颈</td></tr><tr><td>批大小 / 视觉 token 上限</td><td>S<sub>max</sub> 与轮数 k</td><td>批增大后排队转为通信阻塞</td></tr><tr><td>KV 预算</td><td>每步 KV 集合通信 ≤ 解码步预算</td><td>显存够但步时超 SLO</td></tr></tbody></table>\n<p>边界必须写清楚：该式只给单次 all-reduce 的带宽项下界，多模态流水里的多次 all-to-all 要按拓扑逐次累加并计入拥塞，实测端到端时延可达下界的数倍；把 1.8 TB/s 峰值直接代入而忽略 60%–80% 折损，会让容量规划系统性偏乐观，批大小和并行度都定得过大。工程判断是：先用有效带宽和轮数 k 算出保守下界，再拿它去卡 SLO 预算，只有当计算项明显大于 k·T<sub>comm</sub> 时才值得继续加卡；否则优先动 S——降分辨率、减帧、合并 token，比调并行度更直接地移动瓶颈位置。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-28\">二十八 · 把下界换算成决策量：反解 N、批上限与 KV 预算</h3>\n<p>这个下界在容量决策里的正确用法不是“算出一个时间”，而是把它与单卡计算项并列，反解出临界并行度。设单卡处理一份视觉 token 激活的计算时间为 <span class=\"formula\">$$T_{\\text{calc}}$$</span>，则切分收益为正的条件是 <span class=\"formula\">$$\\frac{2(N-1)}{N}\\cdot\\frac{S}{\\text{BW}_{\\text{eff}}}+\\tau_{\\text{lat}} &lt; T_{\\text{calc}}\\left(1-\\frac{1}{N}\\right)$$</span>，其中 <span class=\"formula\">$$\\text{BW}_{\\text{eff}}$$</span> 必须取峰值 1.8 TB/s 的 60%–80%，而不是标称值。把 <span class=\"formula\">$$\\text{BW}_{\\text{eff}}$$</span> 代入峰值会系统性高估可切分规模：同一 S 下临界 N 被抬高，工程上表现为“规划时认为 8 卡切分划算、上线后通信项反超”。这条不等式还说明 N 增大时左式趋近 <span class=\"formula\">$$2S/\\text{BW}_{\\text{eff}}$$</span> 而不再下降，右式的计算收益却继续被 1/N 稀释——所以视觉编码器的张量并行度存在硬上限，超过它加卡只增加通信与同步代价。</p>\n<p>批大小与 KV 预算由此被同一约束绑定。视觉 token 数 S 随图像分辨率与 patch 数线性增长，而解码阶段的 KV 分片在分离式部署中同样走 all-to-all，于是“批上限”应写成 <span class=\"formula\">$$B_{\\max}\\approx\\frac{T_{\\text{SLO}}-T_{\\text{prefill}}-T_{\\text{decode}}^{\\text{calc}}}{T_{\\text{comm}}^{\\text{per-batch}}}$$</span> 的形式：分子是 SLO 扣掉计算与固定开销后的通信预算，分母是单批通信下界。当 S 翻倍，分母翻倍，批上限近似减半；此时若仍按计算时间扩容 KV 池，就会出现显存够、SLO 不够的错配。降低 S（token 压缩、降分辨率、视觉侧提前池化）比加卡更直接，因为它同时压缩了分母与 KV 分片体积。</p>\n<p>算例：取 S 使 <span class=\"formula\">$$S/\\text{BW}_{\\text{eff}}$$</span> 为 1 个单位时间，N=8 时放大因子 <span class=\"formula\">$$2(N-1)/N=1.75$$</span>，通信项为 1.75 单位加 <span class=\"formula\">$$\\tau_{\\text{lat}}$$</span>；N=2 时因子为 1.0。若单卡计算项为 2 单位，N=2 净收益为正，N=8 则因 <span class=\"formula\">$$\\tau_{\\text{lat}}$$</span> 与拥塞余量而落入负收益区。这正是“视觉编码器不宜高并行度切分”的定量依据。</p>\n<p>边界与代价必须写进决策文档：该式只覆盖单次 all-reduce 的带宽项，多模态流水中的视觉 token 分发、专家路由、序列并行是多次 all-to-all，需按拓扑逐次累加，实测端到端时延可达下界的数倍；<span class=\"formula\">$$\\tau_{\\text{lat}}$$</span> 在小消息下主导，使“多切一点以降低单卡计算”的策略失效。工程判断是：先用有效带宽算出通信项，再与计算项比较决定 N，最后用 S 的压缩而非加卡去换批上限——把峰值带宽当有效带宽代入，是这套容量规划最常见的系统性偏乐观来源。</p>\n<h3 id=\"th-nvl72-comm-lower-bound-sec-29\">二十九 · 误用一：把峰值带宽当有效带宽</h3>\n<p>这是 NVL72 通信下界在工程落地中最常见、后果也最直接的一类误用。GB200 单卡 NVLink 聚合带宽标称约 1.8 TB/s，这个数字出现在几乎所有硬件规格表的第一页，于是被顺手写进容量模型的分母。问题在于，这个 1.8 TB/s 是双向峰值，而环状 all-reduce 的 reduce-scatter 与 all-gather 两阶段里，每卡在任一时刻主要是在单向链路上推进，链路利用率受协议开销、报文切分、路由仲裁与对端处理节奏的共同制约，有效带宽通常只有峰值的 60%–80%。把峰值直接代入，等于在分母上系统性放大 1.25 到 1.67 倍，通信时间下界被同比例压低。</p>\n<p>识别方法很直接：看模型里 <span>BW</span> 这个符号的来源。如果它取自规格表而非实测的环状 all-reduce 有效带宽，就应立刻打上折损系数。一个可操作的判别是拿一次已知消息大小的 all-reduce 做标定，用实测时间反解有效带宽，再与峰值比对；若比值落在 0.6–0.8 之外，说明拓扑或报文配置有问题，而不是公式有问题。代价层面，这个误用不会让单次调用出错，却会让整份容量规划偏乐观：以视觉编码器张量并行为例，当 S 较大时带宽项主导，分母被放大 1.5 倍意味着规划者认为可以在更小的 N 上获得同样时延，实际部署后通信项反超计算项，端到端延迟超出预期，而排查方向往往被误导到 kernel 效率上。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-30\">三十 · 误用二：只算一次通信，漏掉流水中的重复集合通信</h3>\n<p>公式本身只建模单次 all-reduce 的带宽项，这一点在适用边界里写得很清楚，但工程实践中极易被忽略。真实的多模态推理流水不是一次集合通信就结束：视觉 token 从编码器输出分发到语言模型各卡是一次 all-to-all；序列并行或专家路由（MoE 层）在每个前向里还要再做 all-to-all；分离式预填/解码架构下，KV 分片在预填池与解码池之间搬运又是一轮。这些通信按拓扑逐次累加，且在不同阶段可能共享同一组链路而产生拥塞。</p>\n<p>后果是实测时延可达下界的数倍，而规划者以为已经拿到了“物理下限”，于是把余量全部押在计算侧优化上。识别这类误用的办法是把流水画成通信事件序列，对每个事件标注 S、N 与所在链路，逐项套用同一公式再求和，而不是挑最大的一次代入。举例：一个视觉 token 数较多的请求，在编码器张量并行段做一次 all-reduce，进入解码段后每层 MoE 路由再做 all-to-all，若只按编码器那一次估算，得到的下界与端到端实测之间会留下一条无法解释的鸿沟。工程判断上，应当把“流水内集合通信次数”作为一个显式参数写进容量模型，次数增加时下界线性上升，这比事后调 kernel 更能解释延迟。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-31\">三十一 · 误用三：token 数增大后不重算通信项</h3>\n<p>第三类误用发生在并行度决策环节。视觉 token 数 S 增大时，计算项与通信项同时增长，但两者的斜率不同：计算项随 S 线性增长且可被更多 SM 分摊，通信项的带宽部分随 S 线性增长却只随 N 以 (N−1)/N 的方式趋近饱和，也就是说增加 N 对通信项的边际改善迅速衰减，而对计算项仍有收益。于是存在一个交叉点，超过它以后继续提高张量并行度，通信反而成为主瓶颈。</p>\n<div class=\"formula\">$$T_{\\text{comm}}\\ \\ge\\ \\frac{2\\,(N-1)}{N}\\cdot\\frac{S}{\\text{BW}_{\\text{NVLink}}}+\\tau_{\\text{lat}}$$</div>\n<p>误用的典型形态是：模型在早期用较小的 S 标定过一次并行度，之后视觉分辨率提高或视频帧数增加导致 S 变大，却没有回头重算通信项，仍按旧的 N 部署。识别信号是并行度提升后端到端延迟不降反升，或提升幅度远小于计算项的预期收益。此时应反解上式，找出通信项开始压过单卡计算项的 N，把并行度钉在交叉点附近，而不是一味加大。代价体现在两个方向：N 选得过高，通信成为主瓶颈且链路功耗上升；N 选得过低，单卡计算项无法被分摊。对视觉编码器而言，另一条出路是降低 S 本身——token 压缩或分辨率裁剪——因为压缩直接缩小分子，比在分母上做拓扑优化更彻底。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-32\">三十二 · 一个反例：把下界当成上界的规划</h3>\n<p>设某团队要在 GB200 NVL72 上部署一个视觉编码器加语言模型的分离式预填/解码服务，视觉 token 数为 S，计划用 N 卡做张量并行。规划文档里写下：通信时间下界 = 2(N−1)/N · S / 1.8 TB/s，代入峰值带宽，取 N 较大时系数趋近 2，得到“通信仅占端到端时延的一小部分”，据此把批大小上限调高、把并行度调高，并认为无需做 token 压缩。</p>\n<p>这个反例的错误链条有三环。第一环，分母用了 1.8 TB/s 峰值而非 60%–80% 的有效带宽，下界被低估。第二环，只算了编码器段的一次 all-reduce，漏掉解码段每层专家路由的 all-to-all 与预填/解码之间的 KV 分片搬运，实际流水里集合通信事件是多次而非一次。第三环，把“下界”误读为“预期时延”——下界是物理地板，真实时延在地板之上还要叠加拥塞、协议固定延迟 τ_lat 的多次累加以及流水气泡。三环叠加后，实测端到端时延远超文档里的数字，而团队最初把差距归因于 kernel 未调优，直到把通信事件逐项列出、用有效带宽重算，才发现规划本身偏乐观。</p>\n<p>正确的做法是把反例倒过来用：先枚举流水中的每一次集合通信，对每次取有效带宽（峰值乘 0.6–0.8 的折损），逐项求下界并求和，再把 τ_lat 按事件次数累加，得到的是一个“不可能低于”的总量；然后用实测时延与之比对，差值就是拥塞与气泡的份额，这才是优化对象。若这个总量已经接近 SLO 预算，说明并行度或 S 的选择本身需要改，而不是继续在 kernel 层面挤牙膏。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-33\">三十三 · 识别清单与工程判断</h3>\n<p>把上述误用收敛成一张可执行的检查表，用于任何一次基于该下界的容量决策：</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>误用形态</th><th>识别信号</th><th>后果</th></tr></thead><tbody><tr><td>带宽取值</td><td>直接代入 1.8 TB/s 峰值</td><td>分母无折损系数，未做标定</td><td>下界低估，规划偏乐观</td></tr><tr><td>通信次数</td><td>只算一次 all-reduce</td><td>流水图未列全 all-to-all 与 KV 搬运</td><td>实测达下界数倍，归因错误</td></tr><tr><td>并行度重算</td><td>S 变大后沿用旧 N</td><td>提高 N 后延迟不降反升</td><td>通信成主瓶颈，链路功耗上升</td></tr><tr><td>下界语义</td><td>把下界当预期时延</td><td>文档把地板写成目标值</td><td>余量被高估，SLO 失守</td></tr></tbody></table>\n<p>这张表的核心判断是：下界只在“分母取有效带宽、分子按拓扑累加、语义上承认它是地板”三个条件同时成立时才有决策价值。任一条件缺失，它给出的就不是保守估计而是乐观估计，而乐观估计在容量规划里比没有估计更危险，因为它会关闭本该保留的余量。工程上更稳妥的做法是把下界乘以一个由实测标定出的“地板到实测”比值，把这个比值当作经验系数纳入模型，并随拓扑与流水变化定期重标。</p>\n<p>最后一个具体机制层面的判断落在 τ_lat 上。固定延迟与消息大小无关，因此在 S 较小、通信事件却很多的流水里，τ_lat 的累加可能反超带宽项成为主导。此时提高 N 或优化带宽都无济于事，唯一有效的动作是减少通信事件次数——合并 all-to-all、把专家路由的通信与序列并行通信对齐到同一轮、或在预填/解码之间减少 KV 分片的往返。识别这一点的方法是把每次事件的 τ_lat 单独列出求和，与带宽项比较量级；若 τ_lat 项占优，优化方向就从带宽转向事件合并，这是该下界在工程上最容易被忽略、也最能解释“带宽明明够、延迟就是下不来”的一类现场。</p>\n\n<h3 id=\"th-nvl72-comm-lower-bound-sec-34\">三十四 · 峰值带宽不是有效带宽：三个把下界算成幻觉的误用</h3>\n<p>最普遍的误用是把 GB200 约 1.8 TB/s 的 NVLink 聚合带宽直接代入公式第一项，把下界当成可达时延。环状 all-reduce 分 reduce-scatter 与 all-gather 两阶段，每卡每阶段搬运 $$\\frac{N-1}{N}S$$ 字节，而 NVLink 标称值是双向峰值，环状算法的有效带宽通常只有峰值的 60%–80%。这意味着真实带宽项应写成 $$\\frac{2(N-1)}{N}\\cdot\\frac{S}{\\eta\\cdot \\mathrm{BW}_{\\mathrm{NVLink}}}$$，其中 $$\\eta\\in[0.6,0.8]$$。以视觉编码器张量并行为例：N=8、单次 all-to-all 消息 S 取视觉 token 激活量级时，按峰值算出的下界与按 0.7 折算后的值相差近三成；若容量规划据此设定批大小上限，系统在真实负载下会持续贴着 SLO 边界抖动，而账面余量看起来还很充裕。识别方法很直接：任何只出现 $$\\mathrm{BW}_{\\mathrm{NVLink}}$$ 而不出现效率因子的时延估算，都应视为乐观下界而非预算值。</p>\n<p>第二个误用是只算一次集合通信。公式只建模单次 all-reduce 的带宽项，而真实多模态流水里视觉 token 分发、专家路由、序列并行各自都是一轮 all-to-all，且拓扑不同、拥塞状态不同。正确做法是按流水逐轮累加：$$T_{\\text{comm}}^{\\text{pipe}}\\ \\ge\\ \\sum_{k}\\frac{2(N_k-1)}{N_k}\\cdot\\frac{S_k}{\\eta_k\\cdot \\mathrm{BW}_{\\mathrm{NVLink}}}+\\sum_{k}\\tau_{\\text{lat},k}$$，其中每一轮的参与集合 N_k 与消息量 S_k 都可能不同。漏算的直接后果是实测端到端时延可达单次下界的数倍——这个“数倍”不是抖动，而是结构性缺口。工程上可观测的识别信号是：单卡计算时间随批大小近似线性增长，而端到端时延在某个批大小后突然上翘，说明流水中的某一轮 all-to-all 已经压过计算项；此时继续加批只会放大通信项，不会提升吞吐。</p>\n<p>第三个误用是并行度决策不随视觉 token 数重算。视觉 token 越多，S 越大，通信项越容易压过单卡计算项，但很多团队在模型定型时按当时的 token 数选定张量并行度 N，之后提高输入分辨率或增加视频帧数却不再复核。反例：某分离式预填/解码部署在视觉编码器上取 N=8 做张量并行，上线初期 token 数较小、通信项远低于计算项，扩容时把输入分辨率提高一档，S 随之增大，通信项按 $$\\frac{2(N-1)}{N}\\cdot\\frac{S}{\\eta\\cdot \\mathrm{BW}}$$ 线性上升而单卡计算项基本不变，结果预填阶段被 all-to-all 卡住，解码端因 KV 分片等待而空转。此时正确的动作不是继续加卡，而是降低 N、改用 token 压缩降低 S，或把视觉编码器留在单卡而只对解码侧做分离式部署。判断阈值可以写成：当 $$\\frac{2(N-1)}{N}\\cdot\\frac{S}{\\eta\\cdot \\mathrm{BW}_{\\mathrm{NVLink}}}&gt;\\frac{C_{\\text{per-GPU}}}{N}$$（C 为单卡计算时间）时，通信已成本瓶颈，继续提高 N 只会让不等式更成立。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>后果</th><th>识别信号</th></tr></thead><tbody><tr><td>峰值带宽直接代入</td><td>容量规划系统性偏乐观</td><td>估算中无效率因子 η</td></tr><tr><td>只算单次 all-reduce</td><td>实测时延达下界数倍</td><td>批大小增大后端到端时延上翘</td></tr><tr><td>并行度不随 S 重算</td><td>张量并行度过高、通信成主瓶颈</td><td>加卡后吞吐不升、解码端空转</td></tr></tbody></table>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>N</td><td>参与集合通信的 GPU 数</td></tr><tr><td>S</td><td>单次通信的消息字节数（如视觉 token 激活或 KV 分片）</td></tr><tr><td>\\text{BW}_{\\text{NVLink}}</td><td>单 GPU NVLink 聚合带宽（GB200 约 1.8 TB/s 量级）</td></tr><tr><td>\\tau_{\\text{lat}}</td><td>kernel 启动与协议固定延迟</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-nvl72-comm-lower-bound · 共 5 个片段</p>\n"},{"id":"th-diffusion-steps-quality","title":"扩散采样步数-质量界","direction":"dir-crossmodal-alignment","prereq":[],"plain":"多模态生成中扩散/流匹配采样步数与感知质量之间存在收益递减：步数增加带来的误差下降大致按 1/K 衰减，超过某点后 FID 改善被量化与调度误差淹没，Blackwell 上应优先用少步蒸馏而非堆步数。","definition":"多模态生成中扩散/流匹配采样步数与感知质量之间存在收益递减：步数增加带来的误差下降大致按 1/K 衰减，超过某点后 FID 改善被量化与调度误差淹没，Blackwell 上应优先用少步蒸馏而非堆步数。","formula":"$$\\mathcal{L}(K)\\ \\approx\\ \\mathcal{L}_\\infty+\\frac{C}{K^{\\alpha}},\\qquad \\frac{\\partial \\mathcal{L}}{\\partial K}=-\\frac{\\alpha C}{K^{\\alpha+1}}$$","variables":[{"sym":"K","meaning":"采样步数（NFE）"},{"sym":"\\mathcal{L}(K)","meaning":"感知质量损失（如 FID 或 CLIP 分数差）"},{"sym":"\\alpha","meaning":"衰减指数，通常 0.5–1.5"},{"sym":"C","meaning":"与调度器和模型相关的常数"}],"derivation":"推导关键一步：对 $$\\frac{C}{K^{\\alpha}}$$ 求导得 $$\\frac{\\partial\\mathcal{L}}{\\partial K}=-\\frac{\\alpha C}{K^{\\alpha+1}}$$，说明边际收益随步数单调递减且按幂律收缩；据此可令边际收益等于单步推理成本，解出性价比最优的步数而非取最大步数。","example":"容量决策用途：用拟合出的 $$\\alpha$$ 与 $$C$$ 估算把步数从 K 降到 K/2 时质量损失增量，与 Blackwell 上单步前向的算力/显存代价对比，决定是否用蒸馏模型替换多步采样，以及为满足延迟 SLA 应把 NFE 压到多少。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["幂律拟合仅在中等步数区间成立；极少步（K<4）时离散化误差主导，幂律失效","L_∞ 与 C 依赖采样器与模型，换用 DPM-Solver 或流匹配后需重新标定"],"system_note":"常见误用：把幂律外推到 $$K<4$$ 的极少步区间，据此认为继续减步几乎无损，实际离散化误差会使质量骤降；另一误用是换采样器后沿用旧拟合参数做容量规划，导致步数预算与实际质量曲线错位。","papers":["paper-an-image-is-worth-16x16-words-transf-2020"],"facts":["直觉：扩散或流匹配采样中，增加步数带来的感知质量收益按 $$1/K^{\\alpha}$$ 衰减，超过某点后 FID 改善被量化误差与调度误差淹没，因此在 Blackwell 上应优先采用少步蒸馏而非盲目堆叠采样步数。","公式 $$\\mathcal{L}(K)\\approx\\mathcal{L}_\\infty+\\frac{C}{K^{\\alpha}}$$ 中，$$K$$ 是采样步数即 NFE 次数，$$\\mathcal{L}(K)$$ 是感知质量损失（如 FID 或 CLIP 分数差），$$\\mathcal{L}_\\infty$$ 是步数趋于无穷时的残余损失，$$C$$ 是与调度器和模型相关的常数，$$\\alpha$$ 是衰减指数，通常落在 0.5–1.5。","推导关键一步：对 $$\\frac{C}{K^{\\alpha}}$$ 求导得 $$\\frac{\\partial\\mathcal{L}}{\\partial K}=-\\frac{\\alpha C}{K^{\\alpha+1}}$$，说明边际收益随步数单调递减且按幂律收缩；据此可令边际收益等于单步推理成本，解出性价比最优的步数而非取最大步数。","适用边界：幂律拟合只在中等步数区间成立；极少步（$$K<4$$）时离散化误差主导，幂律失效；$$\\mathcal{L}_\\infty$$ 与 $$C$$ 依赖采样器与模型，换用 DPM-Solver 或流匹配后必须重新标定，不能跨采样器复用同一组参数。","容量决策用途：用拟合出的 $$\\alpha$$ 与 $$C$$ 估算把步数从 K 降到 K/2 时质量损失增量，与 Blackwell 上单步前向的算力/显存代价对比，决定是否用蒸馏模型替换多步采样，以及为满足延迟 SLA 应把 NFE 压到多少。","常见误用：把幂律外推到 $$K<4$$ 的极少步区间，据此认为继续减步几乎无损，实际离散化误差会使质量骤降；另一误用是换采样器后沿用旧拟合参数做容量规划，导致步数预算与实际质量曲线错位。"],"anchors":["衰减指数通常 0.5–1.5","极少步 K<4"],"pitfalls":["把幂律外推到 K<4 的极少步区间，误判减步几乎无损，实际离散化误差主导导致生成质量骤降。","更换采样器（如改用 DPM-Solver 或流匹配）后沿用旧拟合的 α 与 C 做步数预算，质量曲线与实际错位。","只按最大步数堆叠采样而忽略单步推理成本，在 Blackwell 上浪费算力却换不到可测的 FID 改善。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-1\">一 · 一句话直觉：步数不是免费的质量旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-2\">二 · 严格定义：损失函数、残余项与衰减指数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-3\">三 · 为什么需要这条界：三个工程决策都靠它</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-4\">四 · 常见误解：三类系统性误判</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-5\">五 · 定义落地：标定流程与代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-6\">六 · 幂律的适用边界：何时这条曲线不再可信</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-7\">七 · 逐项拆解：$\\mathcal{L}_\\infty$、$C$、$\\alpha$ 各自在推理栈里对应什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-8\">八 · 推导关键步：从边际收益到最优步数的闭式判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-9\">九 · 离散化与近似发生在哪：幂律为何只在中等步数成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-10\">十 · 标定流程与换采样器的重标定代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-11\">十一 · 把公式接进容量决策：降步与蒸馏的等价换算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-12\">十二 · 边际收益与单步成本：幂律公式在容量决策中的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-13\">十三 · 幂律拟合的适用边界与系统代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-14\">十四 · 幂律拟合的适用区间：中等步数的“窗口”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-15\">十五 · 极少步失效：K&lt;4 时离散化误差接管</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-16\">十六 · 采样器与模型切换：参数不可跨用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-17\">十七 · 规模上限：量化与调度误差构成 $$\\mathcal{L}_\\infty$$ 地板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-18\">十八 · 与单步成本联立时的边界：成本模型也要成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-19\">十九 · 失效条件的工程清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-20\">二十 · 边界在哪里：幂律失效的三种情形与容量决策的误用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-21\">二十一 · 幂律的适用域：从 K≥4 到采样器换代的重新标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-22\">二十二 · 把质量曲线折成“每步预算”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-23\">二十三 · 定批大小：步数预算与显存墙的联立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-24\">二十四 · 定并行度：把 NFE 折算成集合通信次数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-25\">二十五 · 定 KV 预算：扩散轨迹缓存与自回归 KV 的分账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-26\">二十六 · 定 SLO：把质量损失写成时延约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-27\">二十七 · 标定纪律与跨采样器迁移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-28\">二十八 · 把幂律塞进容量模型：步数预算怎么变成批大小、并行度与 SLO</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-29\">二十九 · 把幂律嵌进容量模型：步数预算与并行度的联立求解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-30\">三十 · 误用一：把幂律外推到 K&amp;lt;4 的极少步区间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-31\">三十一 · 误用二：换采样器后沿用旧拟合参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-32\">三十二 · 误用三：只堆最大步数，忽略单步成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-33\">三十三 · 一个反例：把 K=2 写进 SLA 的容量模型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-34\">三十四 · 识别清单与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-35\">三十五 · 幂律外推的两处塌陷：K&amp;lt;4 与换采样器</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:591px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 591.3 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"509.3\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"509.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：多模态生成中扩散/流匹配采样步数与感知质量之间存在收益递减：步数增…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"509.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\mathcal{L}(K)\\ \\approx\\ \\mathc…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"509.3\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：幂律拟合仅在中等步数区间成立；极少步（K&lt;4）时离散化误差主导，幂…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-diffusion-steps-quality-sec-1\">一 · 一句话直觉：步数不是免费的质量旋钮</h3>\n<p>在扩散与流匹配生成里，采样步数 K 就是模型前向的次数，也就是 NFE（number of function evaluations）。工程上最容易被误读的一点，是把 K 当成一个“越大越好”的质量旋钮：直觉上多算几步总该更接近真实分布，于是把 K 拉到调度器允许的上限。真实曲线不是这样。感知质量的收益随 K 单调递减，且衰减近似按幂律收缩——把步数翻倍，误差并不会减半，而是按 <span class=\"formula-inline\">$$1/K^{\\alpha}$$</span> 的量级缩水。当这部分残余收益小到被量化误差（NVFP4/FP8 的舍入）与调度误差（离散化、时间步网格、求解器阶数）淹没时，继续加步数在 Blackwell 上只是把 SM 的算力换成不可测的 FID 改善。一句话：<strong>步数的边际收益递减，且递减速度由幂律指数决定；超过某个拐点，堆步数不如换少步蒸馏模型。</strong></p>\n<p>这句话的工程含义比它的字面更硬。它不是说“步数无用”，而是说步数存在一个<em>性价比最优区间</em>，而这个区间的位置由三件事共同决定：采样器的收敛阶、模型本身的残余误差下限、以及目标精度下量化与调度噪声的幅度。三者中任何一项变化，最优 K 都会移动。所以在容量规划里，K 不是一个可以拍脑袋定的超参，而是一个需要标定的、与硬件精度策略耦合的决策变量。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-2\">二 · 严格定义：损失函数、残余项与衰减指数</h3>\n<p>把上面的直觉写成可拟合、可用于容量决策的形式，定义感知质量损失 <span class=\"formula-inline\">$$\\mathcal{L}(K)$$</span> 为生成样本相对参考分布的感知距离，典型取 FID，或取 CLIP 分数差这类与人类感知更相关的度量。注意 <span class=\"formula-inline\">$$\\mathcal{L}$$</span> 是<em>关于步数的函数</em>，不是单次采样的随机变量；它是在固定模型、固定采样器、固定精度策略下，对一批样本统计出来的期望量。定义采样步数 <span class=\"formula-inline\">$$K$$</span> 为 NFE 次数，对一阶求解器 K 即时间网格点数，对多阶求解器 K 与 NFE 不再一一对应，这一点在跨采样器比较时必须显式对齐。</p>\n<div class=\"formula\">$$\\mathcal{L}(K)\\ \\approx\\ \\mathcal{L}_\\infty+\\frac{C}{K^{\\alpha}},\\qquad \\frac{\\partial \\mathcal{L}}{\\partial K}=-\\frac{\\alpha C}{K^{\\alpha+1}}$$</div>\n<p>三项各有明确物理含义。<span class=\"formula-inline\">$$\\mathcal{L}_\\infty$$</span> 是步数趋于无穷时的残余损失：它是模型容量、训练数据覆盖、以及<em>数值精度地板</em>共同决定的不可约误差——即便 NFE 无限大，NVFP4 的权重量化与激活舍入仍会留下一个误差底。若把精度从 FP8 换到 NVFP4，<span class=\"formula-inline\">$$\\mathcal{L}_\\infty$$</span> 会抬升，曲线整体上移。<span class=\"formula-inline\">$$C$$</span> 是与调度器和模型相关的常数，量纲上吸收了离散化误差的绝对尺度。<span class=\"formula-inline\">$$\\alpha$$</span> 是衰减指数，通常落在 0.5–1.5；<span class=\"formula-inline\">$$\\alpha$$</span> 越大，说明该采样器在该模型上收敛越快，加步数的收益越早耗尽。</p>\n<p>对 <span class=\"formula-inline\">$$C/K^{\\alpha}$$</span> 求导得到边际收益 <span class=\"formula-inline\">$$-\\alpha C/K^{\\alpha+1}$$</span>：它随 K 单调递减，且按幂律收缩。这一步是整套方法的关键——它把“要不要加一步”变成一个可比较的量：单步的边际质量收益，对比单步的推理成本。后者在 Blackwell 上是可测的：一次 DiT 前向的算力、一次 KV/激活的显存占用、以及在给定 batch 下的延迟增量。令边际收益等于单步成本，解出的 K 就是性价比最优点，而不是调度器允许的最大步数。</p>\n<p>必须强调定义域。幂律拟合只在<strong>中等步数区间</strong>成立。极少步（<span class=\"formula-inline\">$$K&lt;4$$</span>）时离散化误差主导，一阶求解器的时间网格粗到无法近似连续轨迹，幂律失效，曲线会陡降而非平滑外推。<span class=\"formula-inline\">$$\\mathcal{L}_\\infty$$</span> 与 <span class=\"formula-inline\">$$C$$</span> 依赖采样器与模型：换用 DPM-Solver 或流匹配后必须重新标定，不能跨采样器复用同一组参数。这条边界不是保守，而是数学事实——不同求解器的局部截断误差阶数不同，<span class=\"formula-inline\">$$\\alpha$$</span> 的物理来源就不同。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-3\">三 · 为什么需要这条界：三个工程决策都靠它</h3>\n<p>第一条用途是<strong>延迟 SLA 反推 NFE 预算</strong>。给定端到端延迟目标与单步前向耗时，可用的 K 上限被直接锁死；此时问题变成“在这个 K 下质量损失是多少、是否可接受”。用拟合出的 <span class=\"formula-inline\">$$\\alpha$$</span> 与 <span class=\"formula-inline\">$$C$$</span>，可以估算把 K 从当前值降到 K/2 时 <span class=\"formula-inline\">$$\\mathcal{L}$$</span> 的增量，再与 SLA 允许的质量退化对比，决定是压步数还是加算力。没有这条曲线，压步数就是盲赌。</p>\n<p>第二条用途是<strong>蒸馏与多步采样的取舍</strong>。少步蒸馏模型（把 K 压到个位数）与多步采样（K 取几十）在 Blackwell 上的成本结构完全不同：前者单次前向更重但 NFE 极少，后者单次前向轻但 NFE 多，且多步采样还要承担每步的调度开销与显存驻留。幂律给出的 <span class=\"formula-inline\">$$\\mathcal{L}_\\infty$$</span> 恰好是判断依据——如果多步采样的 <span class=\"formula-inline\">$$\\mathcal{L}_\\infty$$</span> 已经接近蒸馏模型的可达损失，那么继续堆步数毫无意义，应直接换蒸馏模型。反过来，如果 <span class=\"formula-inline\">$$\\mathcal{L}_\\infty$$</span> 明显高于蒸馏模型，说明多步采样在中等 K 区间仍有真实收益，压步数要谨慎。</p>\n<p>第三条用途是<strong>精度策略与步数的联合标定</strong>。Blackwell 上 NVFP4 与 FP8 的误差地板不同，<span class=\"formula-inline\">$$\\mathcal{L}_\\infty$$</span> 随精度切换而移动。若在 FP8 下标定出最优 K，直接搬到 NVFP4 上会错位：地板抬高后，中等 K 区间的收益更早被淹没，最优 K 反而应下调。这条界因此不是纯理论工具，而是精度-步数联合容量规划的共同语言。</p>\n<p>具体例子：一条文生图服务，端到端延迟预算固定，单步 DiT 前向在目标 batch 下耗时已知。若当前 K 处于幂律有效区间且 <span class=\"formula-inline\">$$\\alpha$$</span> 偏大（接近 1.5），把 K 减半带来的损失增量很小，延迟却直接减半，这是明确的正收益；若 <span class=\"formula-inline\">$$\\alpha$$</span> 偏小（接近 0.5），减半步数的损失增量显著，此时应优先考虑蒸馏而非砍步数。同一个延迟目标，两种 <span class=\"formula-inline\">$$\\alpha$$</span> 给出相反的工程结论。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-4\">四 · 常见误解：三类系统性误判</h3>\n<p><strong>误解一：把幂律外推到 K&lt;4。</strong>这是最危险的误用。在极少步区间，离散化误差主导，曲线不再服从 <span class=\"formula-inline\">$$1/K^{\\alpha}$$</span>，而是陡降。据此认为“继续减步几乎无损”，实际部署时质量骤降，且这种骤降在离线小样本评估里往往被均值掩盖。工程判断：任何 K&lt;4 的决策都必须用真实分布上的小批量在线评估兜底，不能靠外推。</p>\n<p><strong>误解二：换采样器后沿用旧参数。</strong>把在 DDIM 上标定的 <span class=\"formula-inline\">$$\\alpha$$</span> 与 <span class=\"formula-inline\">$$C$$</span> 直接用于 DPM-Solver 或流匹配的步数预算，会导致预算与实际质量曲线错位——多阶求解器在相同 NFE 下误差阶数不同，<span class=\"formula-inline\">$$\\alpha$$</span> 的物理含义已变。工程判断：采样器是标定单元，换求解器即换一组参数，标定成本必须计入上线流程。</p>\n<p><strong>误解三：只按最大步数堆叠，忽略单步成本。</strong>在 Blackwell 上把 K 拉到调度器上限，算力被消耗在边际收益已趋零的区间，换不到可测的 FID 改善，同时挤占了本可用于更大 batch 或更高并发的 SM 与显存预算。这类误判的根源是把 <span class=\"formula-inline\">$$\\mathcal{L}(K)$$</span> 当成单调无界的下降曲线，而忽略了 <span class=\"formula-inline\">$$\\mathcal{L}_\\infty$$</span> 这个地板的存在。工程判断：步数预算应显式包含“地板是否已触及”的检查项，触及即停止加步。</p>\n<p>还有一类隐性误解值得单列：把 <span class=\"formula-inline\">$$\\mathcal{L}(K)$$</span> 当作确定性函数用于单样本决策。它其实是期望量，单次采样的方差可能远大于相邻 K 之间的期望差。因此在低 K 区间做 A/B 比较时，样本量不足会把噪声读成信号，误判最优 K 的位置。这条界给出的是统计意义上的最优，不是逐样本的最优。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-5\">五 · 定义落地：标定流程与代价核算</h3>\n<p>把定义变成可执行流程，需要三步。第一步，固定模型、采样器与精度策略，在中等步数区间（避开 K&lt;4）取若干 K 点，测 <span class=\"formula-inline\">$$\\mathcal{L}(K)$$</span>，用最小二乘拟合 <span class=\"formula-inline\">$$\\mathcal{L}_\\infty$$</span>、<span class=\"formula-inline\">$$C$$</span>、<span class=\"formula-inline\">$$\\alpha$$</span>。第二步，核算单步推理成本：在目标 batch 与序列长度下，测一次前向的算力占用、激活显存峰值与延迟增量；这三项共同构成“加一步”的价格。第三步，令边际收益 <span class=\"formula-inline\">$$\\alpha C/K^{\\alpha+1}$$</span> 等于单步成本的价格，解出最优 K，并与 SLA 约束取交集。</p>\n<p>代价核算里有一个容易被忽略的项：调度误差不是常数，它随 K 变化。K 越大，时间网格越密，单步的调度开销（时间步嵌入、系数计算、条件注入）在总延迟中的占比上升；这部分开销不产生质量收益，却实实在在占用 SM 周期。因此在延迟敏感的部署里，最优 K 往往比纯质量最优 K 更小——这条界与调度开销的耦合，是容量规划必须显式建模的部分。</p>\n<p>具体例子：一条视频生成流水线，单帧 DiT 前向在 NVFP4 下有明显量化地板。标定发现 <span class=\"formula-inline\">$$\\mathcal{L}_\\infty$$</span> 已接近可接受质量阈值，<span class=\"formula-inline\">$$\\alpha$$</span> 落在 0.5–1.5 的中段。此时把 K 从高位砍到中等区间，损失增量在统计上不可辨，但每帧 NFE 减半直接释放出可用于提高并发或加长序列的算力。这就是“地板已触及”信号的实际用法：不是继续优化 K，而是把省下的算力投向别的瓶颈。</p>\n<p>最后落到一个工程判断上：这条界的价值不在于给出一个精确的 K 值，而在于把“步数”从直觉旋钮变成<strong>带地板的、可标定的、与精度策略耦合的成本函数</strong>。任何步数决策，只要没有同时报告 <span class=\"formula-inline\">$$\\mathcal{L}_\\infty$$</span>、<span class=\"formula-inline\">$$\\alpha$$</span> 与单步成本三项，就不是可复现的容量规划，而是凭感觉调参。在 Blackwell 上，算力与显存都足够昂贵，这种凭感觉的代价会直接体现在每 token、每帧的推理成本里。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-6\">六 · 幂律的适用边界：何时这条曲线不再可信</h3>\n<p>把 <span class=\"formula\">$$\\mathcal{L}(K)\\approx\\mathcal{L}_\\infty+\\frac{C}{K^{\\alpha}}$$</span> 当成全局规律是这套方法最危险的用法。它只是中等 NFE 区间上的局部拟合：在 <span class=\"formula\">$$K&lt;4$$</span> 的极少步区间，离散化误差开始主导，单步积分截断误差不再随步数平滑收缩，曲线出现拐折甚至反向抬升，幂律形式本身失效。工程含义很直接——容量规划时若把 <span class=\"formula\">$$\\alpha$$</span>、<span class=\"formula\">$$C$$</span> 外推到 2 步、3 步去论证“再减一步几乎无损”，得到的步数预算会系统性偏乐观，实际部署时质量骤降却找不到原因。正确做法是把拟合区间与决策区间分开：用中等步数的实测点标定参数，对 <span class=\"formula\">$$K&lt;4$$</span> 一律走实测或改用蒸馏模型，不做解析外推。</p>\n<p>第二层边界在采样器。衰减指数 <span class=\"formula\">$$\\alpha$$</span> 通常落在 0.5–1.5，残余损失 <span class=\"formula\">$$\\mathcal{L}_\\infty$$</span> 与常数 <span class=\"formula\">$$C$$</span> 都由调度器的高阶项与模型自身的误差底噪共同决定，换用 DPM-Solver 或流匹配后必须重新标定，不能跨采样器复用同一组参数。跨采样器复用参数做容量决策，会让步数预算与实际质量曲线错位——预算按旧曲线算出“够用”，新采样器的误差底噪却更高或更低，SLA 要么被浪费要么被击穿。</p>\n<p>系统代价决定了这条曲线不能只看质量轴。单步前向在 Blackwell 上的代价是算力、显存带宽与功耗的合成量，边际质量收益 <span class=\"formula\">$$\\left|\\partial\\mathcal{L}/\\partial K\\right|=\\alpha C/K^{\\alpha+1}$$</span> 随步数单调收缩，而单步成本近似恒定，于是存在一个性价比拐点：令边际收益等于单步推理成本即可解出最优 NFE，而非取最大步数。举例来说，把步数从 K 降到 K/2，质量损失增量可由 <span class=\"formula\">$$C\\left(K^{-\\alpha}-(K/2)^{-\\alpha}\\right)$$</span> 估算，再与省下的单步算力、显存占用对比，才能判断该用少步蒸馏替换多步采样，还是维持原步数。只按最大步数堆叠、忽略单步成本，在 Blackwell 上是典型的算力浪费：FID 改善已被量化误差与调度误差淹没，测不出来，却实打实付出了延迟与功耗。</p>\n<table class=\"mini\"><thead><tr><th>区间/条件</th><th>幂律是否可信</th><th>工程动作</th></tr></thead><tbody><tr><td>中等步数</td><td>成立，可拟合 α、C</td><td>用于步数预算与蒸馏决策</td></tr><tr><td>K&lt;4</td><td>失效，离散化误差主导</td><td>实测或直接换蒸馏模型</td></tr><tr><td>换采样器后</td><td>参数不可复用</td><td>重新标定再规划</td></tr></tbody></table>\n<h3 id=\"th-diffusion-steps-quality-sec-7\">七 · 逐项拆解：$\\mathcal{L}_\\infty$、$C$、$\\alpha$ 各自在推理栈里对应什么</h3>\n<p>公式 $\\mathcal{L}(K)\\approx\\mathcal{L}_\\infty+\\frac{C}{K^{\\alpha}}$ 只有三个自由参数，但每一项在 Blackwell 推理栈上都有明确的物理对应物，不能当成纯拟合系数看待。$\\mathcal{L}_\\infty$ 是 $K\\to\\infty$ 时的残余损失，它由三部分叠加而成：模型本身的能力上限（训练分布覆盖度）、数值精度引入的偏置（NVFP4/FP8 量化后权重与激活的舍入误差在去噪轨迹上累积）、以及采样器离散格式的系统性偏差。这三者都不随 $K$ 增大而消失，因此 $\\mathcal{L}_\\infty$ 是容量规划中真正的地板——把 NFE 从 30 堆到 100 也跨不过它。$C$ 是收敛速度的尺度因子，量纲上等于“第一步带来的可消除损失”，它与调度器的时间步离散方案强相关：同一模型换用不同 $\\sigma$ 排布或不同求解器阶数，$C$ 会整体平移。$\\alpha$ 决定曲线的弯曲程度，落在 0.5–1.5 区间，$\\alpha$ 越大说明前期步数收益越陡、后期越快饱和。</p>\n<p>工程含义在于：只有 $C/K^{\\alpha}$ 这一项是“可以用算力买回来”的，$\\mathcal{L}_\\infty$ 只能靠换模型、换精度策略或换采样器降低。因此在 B200 上做步数预算时，先测 $\\mathcal{L}_\\infty$（用极大步数跑一批样本取损失下限），再拟合 $C$ 与 $\\alpha$，才能判断继续加步是否有意义。若 $\\mathcal{L}_\\infty$ 已接近业务可接受阈值，堆步数的边际算力全部浪费。</p>\n<div class=\"formula\">$$\\mathcal{L}(K)\\ \\approx\\ \\mathcal{L}_\\infty+\\frac{C}{K^{\\alpha}},\\qquad \\frac{\\partial \\mathcal{L}}{\\partial K}=-\\frac{\\alpha C}{K^{\\alpha+1}}$$</div>\n\n<h3 id=\"th-diffusion-steps-quality-sec-8\">八 · 推导关键步：从边际收益到最优步数的闭式判据</h3>\n<p>推导的核心不是拟合本身，而是对 $C/K^{\\alpha}$ 求导得到边际收益 $-\\alpha C/K^{\\alpha+1}$，再把它与单步推理成本对齐。设单步前向在目标硬件上的代价为 $c_{\\text{step}}$（以延迟计，或折算成算力/显存带宽占用），则总代价 $T(K)=K\\cdot c_{\\text{step}}$，单位代价的质量改善为 $\\frac{-\\partial \\mathcal{L}/\\partial K}{c_{\\text{step}}}=\\frac{\\alpha C}{c_{\\text{step}}K^{\\alpha+1}}$。这个量随 $K$ 单调下降，说明“每多花一毫秒换来的 FID 改善”必然递减——这正是收益递减的数学形式，而非经验观察。</p>\n<p>若业务给定质量目标 $\\mathcal{L}^\\star&gt;\\mathcal{L}_\\infty$，可直接反解：$K^\\star=\\left(\\frac{C}{\\mathcal{L}^\\star-\\mathcal{L}_\\infty}\\right)^{1/\\alpha}$。这个闭式解的价值在于把“该跑多少步”从调参变成算术：给定 $\\alpha=1$、$C$ 与 $\\mathcal{L}_\\infty$ 由标定得到，目标损失一旦确定，$K^\\star$ 立刻算出。若目标不可达（$\\mathcal{L}^\\star\\le\\mathcal{L}_\\infty$），公式直接告诉你堆步数无解，必须动模型或精度。</p>\n<p>更实用的判据是拉格朗日形式：在延迟 SLA 约束 $K\\cdot c_{\\text{step}}\\le T_{\\text{SLA}}$ 下最小化 $\\mathcal{L}(K)$，由于 $\\mathcal{L}$ 对 $K$ 单调递减，最优解总落在约束边界 $K=T_{\\text{SLA}}/c_{\\text{step}}$——除非该点已进入 $\\mathcal{L}_\\infty$ 主导区，此时应把预算转投蒸馏或降精度。这一步推导把“堆步数”与“换更快的单步”放在同一坐标系里比较：降低 $c_{\\text{step}}$（如用 FP8 替代 BF16、用 2-SM MMA 提升单步吞吐）等价于在相同 SLA 下抬高 $K$，但只要 $\\alpha$ 不变，抬高的 $K$ 带来的收益仍按幂律缩水，所以降单步成本与减步数蒸馏是两条不同量级的杠杆。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-9\">九 · 离散化与近似发生在哪：幂律为何只在中等步数成立</h3>\n<p>公式是连续时间去噪过程的近似，离散化误差在两处进入。第一处是时间步离散：把连续 SDE/ODE 切成 $K$ 段，每段用一阶或二阶格式推进，局部截断误差随步长 $h=1/K$ 的幂次缩放，一阶格式为 $O(h^2)$、二阶为 $O(h^3)$，但全局误差在轨迹上累积后表现为 $C/K^{\\alpha}$ 形式的经验律，$\\alpha$ 并不严格等于格式阶数——它混合了格式阶、轨迹曲率与调度器排布。第二处是数值精度离散：NVFP4 的 4 位尾数与 FP8 的 3 位尾数在每步的矩阵乘与归一化中引入舍入，这些误差不随 $K$ 缩小，反而随步数累积（每步都注入一次），因此它们被吸收进 $\\mathcal{L}_\\infty$ 而非 $C/K^{\\alpha}$ 项。</p>\n<p>这解释了失效边界：$K&lt;4$ 时步长过大，一阶格式的截断误差量级已与信号本身可比，幂律的“平滑衰减”假设破裂，实际曲线出现陡降而非按 $1/K^{\\alpha}$ 缓降。此时离散化误差主导，$\\alpha$ 的拟合值失去意义。另一侧，$K$ 很大时 $C/K^{\\alpha}$ 已小于 $\\mathcal{L}_\\infty$ 的测量噪声，曲线走平，拟合出的 $\\alpha$ 会被噪声拉偏。因此标定必须在中等区间做：经验上取 $K$ 覆盖 8–30 这类区间，避开两端。</p>\n<p>推理系统代价在这里体现得很直接：B200 上单步去噪的延迟由 U-Net/DiT 的矩阵乘主导，NFE 翻倍即延迟翻倍，而质量改善按 $1/K^{\\alpha}$ 缩水；若 $\\alpha\\approx1$，从 15 步加到 30 步只换来约一半的可消除损失，延迟却翻倍。GB200 NVL72 上跨卡并行能压低单步延迟，但不改变 $\\alpha$——它只挪动 $c_{\\text{step}}$，幂律形状不动。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-10\">十 · 标定流程与换采样器的重标定代价</h3>\n<p>标定不是拟合一条曲线就完事，而是分三步的工程流程。第一步固定模型与精度策略（如 BF16 或 FP8），在中等 $K$ 区间跑网格，记录每档的感知损失；第二步用最小二乘拟合 $\\mathcal{L}_\\infty$、$C$、$\\alpha$，同时检查残差是否呈系统性弯曲——若弯曲明显说明区间跨过了失效边界，需收缩区间重拟合；第三步做留出验证，在未参与拟合的 $K$ 上预测损失并与实测比对，偏差超过阈值则判定幂律不适用。</p>\n<p>换采样器必须重标定，原因是 $\\alpha$ 与 $C$ 同时依赖求解器阶数与时间步排布。DPM-Solver 的多步格式与流匹配的直线轨迹在相同 $K$ 下的截断误差结构不同，$\\alpha$ 可从一阶格式的偏大值移到更接近线性的值；沿用旧参数做容量规划，会把步数预算算错一档。工程上应把 $(\\alpha,C,\\mathcal{L}_\\infty)$ 作为采样器配置的一部分随模型版本一起归档，而不是全局常量。</p>\n<table class=\"mini\"><thead><tr><th>参数</th><th>物理来源</th><th>是否随 $K$ 变化</th><th>换采样器是否需重标</th></tr></thead><tbody><tr><td>$\\mathcal{L}_\\infty$</td><td>模型能力 + 量化偏置 + 格式系统偏差</td><td>否</td><td>是（格式偏差变）</td></tr><tr><td>$C$</td><td>调度器时间步排布、首步可消除损失</td><td>否（拟合常数）</td><td>是</td></tr><tr><td>$\\alpha$</td><td>离散格式阶数 + 轨迹曲率</td><td>否（区间内）</td><td>是</td></tr></tbody></table>\n<p>代价侧：一次完整标定需要在目标硬件上跑数十档 $K$ 的采样批次，每档若干样本，B200 上单档若用 1024 张 1024×1024 图，NFE 从 8 到 30 的网格意味着可观的前向总算力；但相比盲目把线上 NFE 翻倍所浪费的持续推理成本，这次性标定开销可以忽略。真正昂贵的是换采样器后忘记重标——质量曲线错位导致的 SLA 违约或过度配置，代价远高于重跑一次网格。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-11\">十一 · 把公式接进容量决策：降步与蒸馏的等价换算</h3>\n<p>公式的直接用途是估算“把 $K$ 降到 $K/2$ 损失多少质量”：$\\Delta\\mathcal{L}=\\mathcal{L}(K/2)-\\mathcal{L}(K)=C\\left(2^{\\alpha}-1\\right)K^{-\\alpha}$。这个增量与单步成本对比，就得到是否值得用蒸馏模型替换多步采样的判据。设蒸馏模型单步成本为 $c_{\\text{distill}}$、质量为 $\\mathcal{L}_{\\text{distill}}$，则替换的净收益为 $\\mathcal{L}(K)-\\mathcal{L}_{\\text{distill}}$ 对比延迟节省 $(K c_{\\text{step}}-c_{\\text{distill}})$；当 $\\mathcal{L}_{\\text{distill}}&lt;\\mathcal{L}(K/2)$ 且 $c_{\\text{distill}}&lt;c_{\\text{step}}$ 时，蒸馏在两个维度同时占优，堆步数没有立足点。</p>\n<p>在 Blackwell 上这个判据尤其锋利，因为单步成本的可压缩空间有限：FP8 相对 BF16 提升吞吐但不改变 $\\alpha$，2-SM MMA 与 TMEM 优化压低的是 $c_{\\text{step}}$ 而非幂律形状；而少步蒸馏直接改写 $\\mathcal{L}_\\infty$ 与 $\\alpha$ 的组合，把整条曲线往下压。因此容量规划的顺序应是：先用标定得到 $(\\alpha,C,\\mathcal{L}_\\infty)$，算出满足 SLA 的 $K^\\star$，再看 $K^\\star$ 是否落在 $K&lt;4$ 的失效区——若是，说明该模型在目标 SLA 下不可行，必须换蒸馏模型，而不是继续在幂律外推上做预算。</p>\n<p>最后一个工程判断落在精度与步数的耦合上：NVFP4 把 $\\mathcal{L}_\\infty$ 抬高，等效于把整条曲线向上平移，此时即使 $K$ 很大也达不到原 BF16 的质量地板；反过来，若业务容忍较高 $\\mathcal{L}_\\infty$，则低精度加少步是自洽组合。公式不能告诉你该选哪个精度，但它能告诉你：一旦 $\\mathcal{L}_\\infty$ 被量化误差抬高到超过目标损失，任何步数增加都是无效算力，此时唯一有效的动作是降精度换吞吐并把省下的预算投到蒸馏上。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-12\">十二 · 边际收益与单步成本：幂律公式在容量决策中的失效边界</h3>\n<p>把 <span class=\"formula\">$$\\mathcal{L}(K)\\approx\\mathcal{L}_\\infty+\\frac{C}{K^{\\alpha}}$$</span> 真正用于工程决策，关键不在拟合本身，而在把导数 <span class=\"formula\">$$\\frac{\\partial\\mathcal{L}}{\\partial K}=-\\frac{\\alpha C}{K^{\\alpha+1}}$$</span> 与单步推理代价对齐。单步前向在 Blackwell 上的代价可写成 <span class=\"formula\">$$c_{\\text{step}}=t_{\\text{launch}}+t_{\\text{MMA}}(K_{\\text{tok}})+t_{\\text{mem}}$$</span>，其中 <span class=\"formula\">$$t_{\\text{launch}}$$</span> 是 kernel 启动与调度开销，<span class=\"formula\">$$t_{\\text{MMA}}$$</span> 随 token 数与 tcgen05 的 MMA 形状变化，<span class=\"formula\">$$t_{\\text{mem}}$$</span> 是 KV/激活读写带宽项。最优步数满足 <span class=\"formula\">$$\\frac{\\alpha C}{K^{\\alpha+1}}=\\lambda\\,c_{\\text{step}}$$</span>，<span class=\"formula\">$$\\lambda$$</span> 是把质量损失折算成延迟预算的影子价格。这个等式暴露了第一个失效条件：当 <span class=\"formula\">$$K$$</span> 很小时 <span class=\"formula\">$$K^{\\alpha+1}$$</span> 分母骤降，左边急剧放大，说明减步的边际质量代价已远超省下的那点单步开销——此时继续压 NFE 在经济上不划算，即便账面算力看似富余。</p>\n<p>第二个失效点来自 <span class=\"formula\">$$\\mathcal{L}_\\infty$$</span> 与 <span class=\"formula\">$$C$$</span> 的采样器依赖性。DPM-Solver 的高阶展开与流匹配的直线轨迹在离散化误差结构上完全不同，同一组 <span class=\"formula\">$$\\alpha,C$$</span> 跨采样器复用会让步数预算与实际质量曲线错位。工程上应把标定做成随采样器版本走的配置项，而不是全局常量。第三个失效点是 <span class=\"formula\">$$K&lt;4$$</span> 区间：离散化误差主导，幂律不再成立，外推会得出“继续减步几乎无损”的错误结论，实际质量骤降。这一区间恰好是少步蒸馏的主战场，因此蒸馏模型的评估不能借用多步采样的幂律参数。</p>\n<table class=\"mini\"><thead><tr><th>区间</th><th>主导误差</th><th>幂律可用性</th><th>系统取舍</th></tr></thead><tbody><tr><td>K&lt;4</td><td>离散化误差</td><td>失效</td><td>用蒸馏模型，不靠减步</td></tr><tr><td>中等 K</td><td>截断+调度</td><td>成立</td><td>按边际等式定 NFE</td></tr><tr><td>大 K</td><td>量化/调度误差</td><td>收益被淹没</td><td>堆步数换不到 FID</td></tr></tbody></table>\n<p>系统代价还体现在批调度维度：连续批处理下增大 <span class=\"formula\">$$K$$</span> 会拉长单请求占用 SM 的时间窗，降低 batch 内 token 复用率，显存侧的中间激活随步数线性增长，在 GB200 NVL72 的高带宽下带宽不再是瓶颈而调度抖动成为主项。因此容量规划应先用拟合的 <span class=\"formula\">$$\\alpha,C$$</span> 估算从 <span class=\"formula\">$$K$$</span> 降到 <span class=\"formula\">$$K/2$$</span> 的质量损失增量，再与蒸馏替换的算力节省对比；若损失增量落在 SLO 容忍带内且单步开销中 <span class=\"formula\">$$t_{\\text{launch}}$$</span> 占比高，减步优于堆步，反之应转向少步蒸馏而非在幂律尾部徒劳加步。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-13\">十三 · 幂律拟合的适用边界与系统代价核算</h3>\n<p>该公式的工程价值不在拟合本身，而在把“边际质量收益”折算成“边际算力成本”。对 <span class=\"formula\">$$C/K^{\\alpha}$$</span> 求导得到 <span class=\"formula\">$$-\\alpha C/K^{\\alpha+1}$$</span>，其绝对值即第 K 步带来的损失下降量；令它等于单步前向在目标硬件上的等效代价 <span class=\"formula\">$$c_{\\text{step}}$$</span>（以延迟 SLA 或每 token 功耗预算折算），可解出 <span class=\"formula\">$$K^{*}=(C\\alpha/c_{\\text{step}})^{1/(\\alpha+1)}$$</span>。这个解的意义是：当 <span class=\"formula\">$$\\alpha$$</span> 偏大（接近 1.5）时，<span class=\"formula\">$$K^{*}$$</span> 对 <span class=\"formula\">$$c_{\\text{step}}$$</span> 不敏感，堆步数尚有余地；当 <span class=\"formula\">$$\\alpha$$</span> 偏小（接近 0.5）时，曲线过早走平，继续加步只会放大调度与量化误差，此时应转向少步蒸馏而非调采样器参数。</p>\n<p>边界条件必须写进容量规划文档：幂律只在中等步数区间成立，<span class=\"formula\">$$K&lt;4$$</span> 时离散化误差主导，<span class=\"formula\">$$\\mathcal{L}_\\infty$$</span> 与 <span class=\"formula\">$$C$$</span> 不再是稳定常数，外推会系统性低估损失。更隐蔽的失效是跨采样器复用参数——DPM-Solver 与流匹配的误差结构不同，沿用旧 <span class=\"formula\">$$\\alpha$$</span>、<span class=\"formula\">$$C$$</span> 做步数预算，会让实际质量曲线与规划错位，表现为 SLA 达标但感知质量不达标。</p>\n<table class=\"mini\"><thead><tr><th>区间</th><th>主导误差</th><th>系统代价特征</th><th>工程动作</th></tr></thead><tbody><tr><td>K<4</td><td>离散化误差</td><td>单步延迟占比高，NFE 压缩收益被质量骤降抵消</td><td>改用蒸馏模型，不做幂律外推</td></tr><tr><td>中等 K</td><td>幂律衰减项</td><td>每步算力线性增长，质量按 <span class=\"formula\">$$1/K^{\\alpha}$$</span> 递减</td><td>按 <span class=\"formula\">$$K^{*}$$</span> 定 NFE 预算</td></tr><tr><td>大 K</td><td>量化与调度误差</td><td>FID 改善被淹没，功耗与显存带宽持续上升</td><td>停止加步，转精度/调度优化</td></tr></tbody></table>\n<p>落到 Blackwell 上，单步代价不只是 MMA 周期：NFE 翻倍意味着 KV/激活驻留与 TMEM 复用窗口被切得更碎，连续批处理的有效批尺寸下降，端到端吞吐的边际收益进一步缩水。因此把步数从 K 降到 K/2 时，必须同时核算质量损失增量 <span class=\"formula\">$$\\Delta\\mathcal{L}=C[(2/K)^{\\alpha}-(1/K)^{\\alpha}]$$</span> 与单步算力、显存带宽的节省量，二者对比后才决定是压 NFE 还是换蒸馏模型；只按最大步数堆叠采样，是在浪费算力却换不到可测的 FID 改善。</p>\n<h3 id=\"th-diffusion-steps-quality-sec-14\">十四 · 幂律拟合的适用区间：中等步数的“窗口”</h3>\n<p>$$\\mathcal{L}(K)\\approx\\mathcal{L}_\\infty+\\frac{C}{K^{\\alpha}}$$ 这组参数不是模型的物理常数，而是一段采样轨迹上的局部拟合。它的成立依赖一个隐含前提：每一步离散化带来的截断误差与步长呈稳定比例，且相邻步的误差贡献近似可加。这个前提在中等 NFE 区间（大致从个位数中段到几十步）最接近真实，因为此时 ODE/SDE 求解器的局部截断项尚未被高阶项主导，调度器给出的时间网格也足够密，单步误差随 $$K^{-(\\alpha+1)}$$ 平滑收缩。一旦离开这个窗口，拟合残差会系统性偏离：低步端由离散化主导，高步端由数值噪声与量化误差主导。工程含义是，$$\\alpha$$ 与 $$C$$ 只能在标定区间内插值使用，向两端外推都是没有依据的。具体例子：同一套流匹配模型在 8–32 步区间拟合出 $$\\alpha\\approx1.0$$，若拿这组参数去预测 2 步的质量，预测值会明显优于实测，因为 2 步时求解器已退化为近似欧拉一步跨越半个概率流，截断误差不再服从幂律。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-15\">十五 · 极少步失效：K<4 时离散化误差接管</h3>\n<p>当 $$K&lt;4$$，时间网格上相邻节点的间距与概率流曲率同量级，泰勒展开的一阶截断项不再是小量，误差主项从“每步误差累加”切换为“单步跨越导致的轨迹偏离”。此时 $$\\partial\\mathcal{L}/\\partial K$$ 的幂律形状被破坏，曲线出现陡降而非平滑收缩。判据可以写成：若单步时间步长 $$\\Delta t$$ 满足 $$\\|\\nabla^2 x\\| \\Delta t^2$$ 与 $$\\|\\nabla x\\|$$ 同阶，则幂律假设失效——这正是 K 很小时的典型情形。系统代价上，这一段的失败不是“质量略降”，而是分布层面的崩塌：CFG 引导下的少步采样容易出现饱和伪影、结构重复，FID 相对中等步数区间出现量级跳变。具体例子：把 4 步蒸馏模型与 2 步原始采样器混用同一组 $$\\alpha,C$$ 做容量规划，会得出“再减一半步数只损失一点质量”的结论，而实测 2 步的 CLIP 分数差远大于拟合外推值。正确做法是把 K<4 视为独立区间，用蒸馏或专门的小步求解器单独标定，而不是让幂律去覆盖它。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-16\">十六 · 采样器与模型切换：参数不可跨用</h3>\n<p>$$C$$ 与 $$\\alpha$$ 同时编码了调度器的时间离散策略和模型自身的得分场平滑度。换用 DPM-Solver（多步高阶）或从 DDPM 切到流匹配，误差随步数的收缩阶数会变：高阶求解器的局部误差是 $$O(\\Delta t^{p+1})$$，映射到 $$\\mathcal{L}(K)$$ 上表现为更大的有效 $$\\alpha$$；流匹配的直线化轨迹则改变 $$C$$ 的量级。因此跨采样器复用旧拟合参数做步数预算，等价于用错误的斜率去解“边际收益=单步成本”的方程，解出的最优 NFE 会系统性偏移。工程判断：每次更换求解器、更换模型版本、甚至更换 guidance scale 档位，都应重新在目标区间采 5–8 个步数点做拟合，把 $$\\alpha,C$$ 当作版本化配置项而非全局常量。具体例子：同一底模从 DDIM 换到 DPM-Solver++ 后，若沿用旧 $$\\alpha$$ 估算“K 减半的质量损失”，会低估高阶求解器在中等步数下的优势，从而过早触发蒸馏替换，浪费了本可保留的原始采样路径。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-17\">十七 · 规模上限：量化与调度误差构成 $$\\mathcal{L}_\\infty$$ 地板</h3>\n<p>幂律的残余项 $$\\mathcal{L}_\\infty$$ 不是零，它由与步数无关的误差源构成：NVFP4/FP8 量化的权重与激活舍入、KV/中间激活的存储精度、批调度引入的 padding 与 kernel 启动抖动、以及 CFG 批拼接带来的数值路径差异。这些误差不随 $$K$$ 增大而下降，因此当 $$\\frac{C}{K^{\\alpha}}$$ 降到与 $$\\mathcal{L}_\\infty$$ 同量级时，继续加步数的边际收益被淹没。令两者相等可解出收益饱和点：$$K_{\\text{sat}}\\approx\\left(C/\\mathcal{L}_\\infty\\right)^{1/\\alpha}$$。这不是精确阈值，而是判断“再加步数是否值得”的标尺。系统代价上，饱和点之后每增加一步都要付出一次完整前向的算力与显存带宽（Blackwell 上即一次 tcgen05 MMA 与 TMEM 往返），却换不到可测的 FID 改善——这是典型的算力浪费。具体例子：在 FP8 量化路径下，$$\\mathcal{L}_\\infty$$ 被量化噪声抬高，饱和点前移；此时把 NFE 从 32 堆到 64，实测 FID 差异落在测量噪声内，而单步延迟与功耗照常线性增长。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-18\">十八 · 与单步成本联立时的边界：成本模型也要成立</h3>\n<p>用 $$\\frac{\\partial\\mathcal{L}}{\\partial K}=-\\frac{\\alpha C}{K^{\\alpha+1}}$$ 等于单步推理成本来解最优步数，隐含第二个假设：单步成本对 $$K$$ 是常数。这个假设在连续批处理与分离式预填/解码下并不总成立——批内序列长度分布、KV cache 命中率、TMEM 占用随批组成变化，单步的有效成本是随负载波动的。当单步成本本身随 $$K$$ 或批形态漂移时，令边际质量收益等于一个固定成本值会给出错误的 NFE。工程上应把成本项写成随批形态变化的函数，或至少在容量规划时用目标 SLO 下的实测单步延迟而非空载延迟。具体例子：在 NVL72 上做多副本部署时，解码副本的单步成本受集合通信与批调度影响，若用空载单步延迟代入方程，会低估成本、高估最优步数，最终把 NFE 定得偏高，挤压了本可用于提高并发的时间预算。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-19\">十九 · 失效条件的工程清单</h3>\n<p>把上述边界收敛成可执行的检查项，避免把幂律当成无条件定律：</p>\n<ul>\n<li>标定区间必须覆盖实际部署的 NFE 范围，外推只允许向高步方向做保守估计，禁止向 K<4 外推。</li>\n<li>更换求解器、模型、guidance 档位、量化精度后，$$\\alpha,C,\\mathcal{L}_\\infty$$ 全部重标，参数随版本入库。</li>\n<li>先用 $$K_{\\text{sat}}\\approx(C/\\mathcal{L}_\\infty)^{1/\\alpha}$$ 判断饱和点，再决定是否堆步数；饱和点之后优先考虑少步蒸馏而非加步。</li>\n<li>成本项用目标负载下的实测单步延迟，不用空载值；批形态变化大时按分位数而非均值代入。</li>\n<li>质量指标要区分测量噪声地板：当 FID 差异落在噪声内，视为无改善，不进入步数预算。</li>\n</ul>\n<p>这套清单的核心判断是：幂律是一个有定义域的局部模型，它的价值在于给出“减步损失多少、加步换来多少”的可比斜率，而不是提供一个可以无限外推的质量预言机。在 Blackwell 上做容量决策时，先确认当前 NFE 落在标定窗口内、$$\\mathcal{L}_\\infty$$ 未被量化噪声抬高、单步成本与批形态匹配，再解边际方程；任一条件不满足，结论就应退回实测扫描而非公式外推。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-20\">二十 · 边界在哪里：幂律失效的三种情形与容量决策的误用</h3>\n<p>把 <span class=\"formula\">$$\\mathcal{L}(K)\\approx\\mathcal{L}_\\infty+\\frac{C}{K^{\\alpha}}$$</span> 当成一条可以任意外推的曲线，是这套步数-质量界最容易出问题的地方。幂律本身来自数值积分误差在中等步数区间的渐近行为，它成立的前提是：离散化误差随步长缩小而平滑下降、调度器给出的时间网格足够细、每一步的模型评估未被数值精度截断。一旦这些前提被破坏，拟合出的 <span class=\"formula\">$$\\alpha$$</span> 与 <span class=\"formula\">$$C$$</span> 就不再描述真实的质量曲线。工程上要盯住三类失效：极少步区间、采样器/模型切换、以及量化与调度误差成为主导项。三者对应三种不同的系统代价——前者是质量骤降，中者是预算错位，后者是算力空转。</p>\n<p>第一类是极少步区间。<span class=\"formula\">$$K&lt;4$$</span> 时，幂律失效，离散化误差主导。原因在于：当 NFE 只有 2–3 次时，求解器对概率流 ODE 的近似已经粗糙到无法用“误差 ∝ 步长幂次”来描述，误差不再随 <span class=\"formula\">$$K$$</span> 平滑收缩，而是被单步截断误差、调度器端点处理、以及采样起点/终点的边界条件共同支配。此时把 <span class=\"formula\">$$\\partial\\mathcal{L}/\\partial K=-\\alpha C/K^{\\alpha+1}$$</span> 外推到 <span class=\"formula\">$$K=2$$</span>，会得到一个“再减一步几乎无损”的错误结论，实际却是质量断崖。系统代价很直接：在 Blackwell 上把 NFE 从 4 压到 2，单步前向的算力省了一半，但生成结果的 FID 与 CLIP 分数差可能远超容量规划预留的余量，SLO 里的质量门槛被击穿。正确做法是把 <span class=\"formula\">$$K\\ge4$$</span> 作为幂律拟合的有效下界，极少步区间改用少步蒸馏模型单独标定，而不是拿同一条曲线外推。</p>\n<p>第二类是采样器与模型切换。<span class=\"formula\">$$\\mathcal{L}_\\infty$$</span> 与 <span class=\"formula\">$$C$$</span> 依赖采样器与模型：换用 DPM-Solver 或流匹配后，必须重新标定，不能跨采样器复用同一组参数。这一点在容量决策里最容易被忽略——团队在一种采样器上拟合出 <span class=\"formula\">$$\\alpha\\approx1$$</span>、<span class=\"formula\">$$C$$</span> 较小，据此把 NFE 预算压到某个值；换采样器后质量曲线整体平移，旧的步数预算与实际曲线错位，表现为“按计划压了步数，质量却没达标”或“明明还有质量余量却不敢减步”。系统代价是规划失真：Blackwell 的算力与显存被按错误的 NFE 假设分配，连续批处理的 batch 上限、KV/激活显存预留、以及延迟 SLA 的余量全部建立在过时的 <span class=\"formula\">$$(\\alpha,C)$$</span> 上。工程判断是：把 <span class=\"formula\">$$(\\alpha,C)$$</span> 当作与采样器绑定的标定产物，随采样器版本一起纳入配置管理，换采样器即触发重标定，而不是沿用旧值做跨版本容量规划。</p>\n<p>第三类是量化与调度误差淹没收益。步数增加带来的误差下降按 <span class=\"formula\">$$1/K^{\\alpha}$$</span> 衰减，但当 <span class=\"formula\">$$K$$</span> 增大到某点后，FID 改善被量化误差与调度误差淹没——此时继续堆步数，边际收益 <span class=\"formula\">$$-\\alpha C/K^{\\alpha+1}$$</span> 已经小于单步推理成本，甚至小于 NVFP4/FP8 数值精度引入的固定误差底噪。系统代价是算力与功耗的纯浪费：在 B200/GB200 上多跑的每一步都是一次完整的 2-SM MMA 与 TMEM 读写，吞吐下降、功耗上升，却换不到可测的 FID 改善。容量决策的正确用法是令边际质量收益等于单步推理成本，解出性价比最优的 <span class=\"formula\">$$K^{*}$$</span>，而不是取最大步数；当拟合显示 <span class=\"formula\">$$\\mathcal{L}_\\infty$$</span> 已接近量化底噪时，应转向少步蒸馏而非继续堆叠采样步数。</p>\n<table class=\"mini\"><thead><tr><th>失效情形</th><th>触发条件</th><th>系统代价</th><th>工程处置</th></tr></thead><tbody><tr><td>极少步外推</td><td><span class=\"formula\">$$K&lt;4$$</span>，离散化误差主导</td><td>质量断崖，SLO 质量门槛被击穿</td><td>以 <span class=\"formula\">$$K\\ge4$$</span> 为拟合下界，极少步单独标定</td></tr><tr><td>采样器切换</td><td>改用 DPM-Solver 或流匹配</td><td>步数预算与实际质量曲线错位，算力/显存分配失真</td><td><span class=\"formula\">$$(\\alpha,C)$$</span> 随采样器版本重标定</td></tr><tr><td>误差淹没</td><td>量化/调度误差超过 <span class=\"formula\">$$1/K^{\\alpha}$$</span> 收益</td><td>吞吐下降、功耗上升，FID 无可测改善</td><td>解 <span class=\"formula\">$$K^{*}$$</span>，转向少步蒸馏</td></tr></tbody></table>\n\n<h3 id=\"th-diffusion-steps-quality-sec-21\">二十一 · 幂律的适用域：从 K≥4 到采样器换代的重新标定</h3>\n<p>公式 $$\\mathcal{L}(K)\\approx\\mathcal{L}_\\infty+C/K^{\\alpha}$$ 的成立前提是离散化误差已进入可控区间，即求解器每步的局部截断误差小于调度器引入的分数阶噪声。当 NFE 落到 K&lt;4 时，这一前提被打破：单步跨越的噪声水平差过大，隐式或显式求解器的泰勒展开不再收敛，误差由离散化项主导而非 $$C/K^{\\alpha}$$ 项，幂律外推会系统性低估损失。工程上的直接后果是：按拟合曲线把步数从 8 压到 2 时预测的质量损失增量可能只有零点几个 FID 点，实测却出现结构崩坏——这正是容量规划里最危险的一类误判，因为它在 SLA 预算表上看起来“免费”。</p>\n<p>第二个边界是参数的可迁移性。$$\\alpha$$ 与 $$C$$ 并非模型固有属性，而是“模型 × 采样器 × 调度器”三元组的联合拟合量：换用 DPM-Solver 的多步高阶变体或流匹配的直线化轨迹后，误差随 K 的收缩速率改变，旧的 $$\\alpha$$ 直接套用会让步数预算与实际质量曲线错位。判定是否可复用的操作准则是：在同一模型上取 3–4 个中等步数点重拟合，若 $$\\alpha$$ 的漂移超过区间宽度（0.5–1.5 的跨度）的一半，则必须整组重标定，不能只调 $$C$$。</p>\n<table class=\"mini\"><thead><tr><th>区间</th><th>主导误差项</th><th>幂律可用性</th><th>系统代价特征</th></tr></thead><tbody><tr><td>K&lt;4</td><td>离散化/截断误差</td><td>失效，禁止外推</td><td>单步算力占比高，质量不可控</td></tr><tr><td>中等 K</td><td>$$C/K^{\\alpha}$$ 调度误差</td><td>成立，可拟合</td><td>NFE 线性推高延迟与功耗</td></tr><tr><td>大 K</td><td>量化与调度残差 $$\\mathcal{L}_\\infty$$</td><td>饱和，边际趋零</td><td>算力换不到可测 FID 改善</td></tr></tbody></table>\n<p>规模上限还体现在 $$\\mathcal{L}_\\infty$$ 的物理来源上：它不只是采样器残差，还叠加了 NVFP4/FP8 激活量化误差与 TMEM 累加精度损失。当 $$C/K^{\\alpha}$$ 项被压到与量化噪声同量级时，继续加步数等于用 2-SM MMA 的算力去对抗一个与 K 无关的偏置——导数 $$-\\alpha C/K^{\\alpha+1}$$ 趋近于零，而每步前向的显存带宽与功耗开销恒定。此时正确动作不是调步数，而是换数值精度档位或改用少步蒸馏模型；把 NFE 压到 SLA 允许的最低中等步数点，再用蒸馏补足质量，才是 Blackwell 上收益与代价匹配的路径。</p>\n<h3 id=\"th-diffusion-steps-quality-sec-22\">二十二 · 把质量曲线折成“每步预算”</h3>\n<p>容量决策的第一步不是选批大小，而是把幂律曲线转成一张可查询的边际成本表。对 <span class=\"formula\">$$\\mathcal{L}(K)\\approx\\mathcal{L}_\\infty+\\frac{C}{K^{\\alpha}}$$</span> 求导得到 <span class=\"formula\">$$\\frac{\\partial\\mathcal{L}}{\\partial K}=-\\frac{\\alpha C}{K^{\\alpha+1}}$$</span>，这个导数的绝对值就是“再多走一步换来的质量”。工程上要把它和“多走一步的代价”放在同一量纲上比较：单步代价在 Blackwell 上表现为一次完整 NFE 的算力占用、TMEM 驻留时间与激活显存峰值，在分离式部署里还叠加一次跨节点往返的时延。于是性价比最优步数由</p>\n<div class=\"formula\">$$\\frac{\\alpha C}{K^{\\alpha+1}}=\\lambda\\cdot c_{\\text{step}}(B,\\,P)$$</div>\n<p>解出，其中 <span class=\"formula\">$$c_{\\text{step}}$$</span> 是单步代价，<span class=\"formula\">$$\\lambda$$</span> 是把质量损失折算成时延/成本的价格系数，<span class=\"formula\">$$B$$</span> 是批大小、<span class=\"formula\">$$P$$</span> 是并行度。注意 <span class=\"formula\">$$c_{\\text{step}}$$</span> 本身随 <span class=\"formula\">$$B$$</span> 变化：批越大，单步的权重加载被摊薄，单步代价下降，于是最优 <span class=\"formula\">$$K$$</span> 反而变大——这是“大 batch 容忍更多步数”的定量来源，也是连续批处理下不同请求可以共享步数预算的前提。反过来，当 <span class=\"formula\">$$\\alpha$$</span> 接近 1.5 时，导数衰减极快，把 <span class=\"formula\">$$K$$</span> 从 32 压到 16 只损失很小的质量，容量规划应果断砍步数；当 <span class=\"formula\">$$\\alpha$$</span> 接近 0.5 时，砍步数的质量代价明显，此时更该转向少步蒸馏而不是硬压 NFE。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-23\">二十三 · 定批大小：步数预算与显存墙的联立</h3>\n<p>扩散推理的显存占用由三块构成：权重、单步激活、以及按 <span class=\"formula\">$$K$$</span> 累积的中间缓存（若做轨迹复用或参考图对齐）。批大小 <span class=\"formula\">$$B$$</span> 的可行域由激活项线性约束：<span class=\"formula\">$$B\\le \\frac{M_{\\text{free}}-M_{\\text{weight}}-M_{\\text{kv}}}{M_{\\text{act}}(K)}$$</span>，其中 <span class=\"formula\">$$M_{\\text{act}}(K)$$</span> 随 <span class=\"formula\">$$K$$</span> 增大而增大（缓存条目数正比于 NFE）。把这条约束和上一节的边际条件联立，就得到“给定显存与 SLO 下的最优 <span class=\"formula\">$$(B,K)$$</span>”：<span class=\"formula\">$$K$$</span> 越大，单请求时延越长、<span class=\"formula\">$$M_{\\text{act}}$$</span> 越高，<span class=\"formula\">$$B$$</span> 被迫缩小，吞吐下降；<span class=\"formula\">$$K$$</span> 越小，质量损失上升但 <span class=\"formula\">$$B$$</span> 可放大，吞吐上升。一个具体例子：若拟合得 <span class=\"formula\">$$\\alpha=1.0$$</span>、<span class=\"formula\">$$C$$</span> 使 <span class=\"formula\">$$K=32$$</span> 时 <span class=\"formula\">$$C/K^{\\alpha}$$</span> 项贡献的损失为基准单位 1，则 <span class=\"formula\">$$K=16$$</span> 时该项翻倍为 2，<span class=\"formula\">$$K=8$$</span> 时为 4——决策者据此判断“砍一半步数换双倍批”是否值得，而不是凭感觉。若 <span class=\"formula\">$$\\mathcal{L}_\\infty$$</span> 本身已接近可接受阈值，则 <span class=\"formula\">$$C/K^{\\alpha}$$</span> 的绝对增量才是关键，必须用标定后的绝对数值而非相对倍数做判断。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-24\">二十四 · 定并行度：把 NFE 折算成集合通信次数</h3>\n<p>并行度决策里，<span class=\"formula\">$$K$$</span> 直接乘在通信量上。张量并行每步要做两次 all-reduce（前向一次、反向不需要，但扩散推理只前向），序列/专家并行在每步边界插入 all-to-all；于是单请求的总通信次数正比于 <span class=\"formula\">$$K$$</span>，总通信字节正比于 <span class=\"formula\">$$K\\cdot B\\cdot S\\cdot d$$</span>（<span class=\"formula\">$$S$$</span> 为序列长度、<span class=\"formula\">$$d$$</span> 为隐藏维）。在 NVL72 域内 NVLink 5 带宽充裕，通信代价可被计算掩盖；一旦跨域走 NIXL/IB，单步通信时延抬升，<span class=\"formula\">$$c_{\\text{step}}$$</span> 显著变大，边际条件给出的最优 <span class=\"formula\">$$K$$</span> 随之下降——这就是“跨节点部署应更激进地压步数”的定量依据。反过来，若把并行度从 2 提到 4，单步计算时延减半但通信次数不变、单次通信规模减半，<span class=\"formula\">$$c_{\\text{step}}$$</span> 的净变化取决于计算/通信比；在 <span class=\"formula\">$$\\alpha$$</span> 较小的模型上，提并行度换来的时延收益会被额外步数需求抵消，需按上式重新解 <span class=\"formula\">$$K$$</span> 而不能沿用旧预算。伪代码思路：对每个候选 <span class=\"formula\">$$(B,P)$$</span>，先由 roofline 估 <span class=\"formula\">$$c_{\\text{step}}$$</span>，代入边际方程解 <span class=\"formula\">$$K^{*}$$</span>，再检查 <span class=\"formula\">$$K^{*}\\ge 4$$</span> 且落在幂律有效区间，否则标记该配置不可信、退回标定区间内的最小可行步数。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-25\">二十五 · 定 KV 预算：扩散轨迹缓存与自回归 KV 的分账</h3>\n<p>多模态生成里，扩散头与自回归主干常共存：主干产出条件嵌入，扩散头按 <span class=\"formula\">$$K$$</span> 步迭代。KV 预算要在两者间分账。主干的 KV cache 按并发请求数线性增长，与 <span class=\"formula\">$$K$$</span> 无关；扩散侧的轨迹缓存（保存每步 latent 以支持中断续算、参考图对齐或分类器引导复用）则正比于 <span class=\"formula\">$$K$$</span>。设总预算 <span class=\"formula\">$$M_{\\text{kv}}$$</span>，则 <span class=\"formula\">$$N_{\\text{req}}\\cdot M_{\\text{ar}} + N_{\\text{req}}\\cdot K\\cdot M_{\\text{latent}}\\le M_{\\text{kv}}$$</span>，解出并发上限 <span class=\"formula\">$$N_{\\text{req}}\\le M_{\\text{kv}}/(M_{\\text{ar}}+K M_{\\text{latent}})$$</span>。可见 <span class=\"formula\">$$K$$</span> 是并发的除数：把 <span class=\"formula\">$$K$$</span> 从 50 降到 25，在 <span class=\"formula\">$$M_{\\text{latent}}$$</span> 与 <span class=\"formula\">$$M_{\\text{ar}}$$</span> 同量级时并发可提升近一倍，而质量损失按 <span class=\"formula\">$$C/K^{\\alpha}$$</span> 只增 <span class=\"formula\">$$2^{\\alpha}-1$$</span> 倍（<span class=\"formula\">$$\\alpha=1$$</span> 时即翻倍该项）。工程判断是：当 <span class=\"formula\">$$M_{\\text{latent}}$$</span> 占比高、且 <span class=\"formula\">$$\\mathcal{L}_\\infty$$</span> 已满足 SLO 时，砍 <span class=\"formula\">$$K$$</span> 换并发几乎总是正收益；反之若 <span class=\"formula\">$$M_{\\text{ar}}$$</span> 主导，压 <span class=\"formula\">$$K$$</span> 对并发的杠杆很小，应把优化投向主干 KV 的分页与量化，而不是步数。注意轨迹缓存可按需丢弃（只保留最近一步），此时 <span class=\"formula\">$$K$$</span> 不进入显存式，预算回到与 <span class=\"formula\">$$K$$</span> 无关的形态，代价是失去中断续算能力——这是显存与鲁棒性的直接交换。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-26\">二十六 · 定 SLO：把质量损失写成时延约束</h3>\n<p>SLO 通常是“P99 时延 ≤ T、质量不低于阈值”。单请求时延近似 <span class=\"formula\">$$T_{\\text{req}}\\approx K\\cdot t_{\\text{step}}(B,P)+t_{\\text{comm}}(K)+t_{\\text{overhead}}$$</span>，其中 <span class=\"formula\">$$t_{\\text{comm}}(K)$$</span> 在跨域部署时不可忽略。给定 <span class=\"formula\">$$T$$</span>，可解出步数上限 <span class=\"formula\">$$K_{\\max}$$</span>；再用幂律算出该步数下的质量损失 <span class=\"formula\">$$\\mathcal{L}(K_{\\max})$$</span>，与质量阈值比较。若 <span class=\"formula\">$$\\mathcal{L}(K_{\\max})$$</span> 超阈值，说明当前采样器/模型组合在该 SLO 下不可行，必须换少步蒸馏模型或降低分辨率/序列长度，而不是继续调批大小。算例：设 <span class=\"formula\">$$t_{\\text{step}}=2$$</span> 单位、<span class=\"formula\">$$t_{\\text{overhead}}=4$$</span> 单位、<span class=\"formula\">$$T=44$$</span> 单位，则 <span class=\"formula\">$$K_{\\max}=20$$</span>；若拟合 <span class=\"formula\">$$\\alpha=1$$</span>、<span class=\"formula\">$$C$$</span> 标定为 <span class=\"formula\">$$K=20$$</span> 时 <span class=\"formula\">$$C/K=0.5$$</span> 个损失单位、<span class=\"formula\">$$\\mathcal{L}_\\infty=0.2$$</span>，则 <span class=\"formula\">$$\\mathcal{L}(20)=0.7$$</span>；质量阈值若为 0.6，则超限，需把 <span class=\"formula\">$$K$$</span> 提到 40 才得 <span class=\"formula\">$$0.2+0.25=0.45$$</span>，但 40 步时延 84 单位远超 <span class=\"formula\">$$T$$</span>——结论是该 SLO 只能靠蒸馏模型达成，堆步数无解。这正是幂律曲线在容量规划中的真正用途：它把“质量不达标”翻译成“该换模型而非该调参”。同时要守住 <span class=\"formula\">$$K\\ge 4$$</span> 的边界，若 <span class=\"formula\">$$K_{\\max}&lt;4$$</span>，幂律外推失效，必须实测离散化误差，不能拿公式当挡箭牌。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-27\">二十七 · 标定纪律与跨采样器迁移</h3>\n<p>上述所有决策都依赖 <span class=\"formula\">$$(\\alpha,C,\\mathcal{L}_\\infty)$$</span> 这组标定参数，而它们与采样器绑定。换用 DPM-Solver 或流匹配后，<span class=\"formula\">$$C$$</span> 与 <span class=\"formula\">$$\\alpha$$</span> 必须重测：同一模型在不同采样器下的衰减指数可以相差一个区间，沿用旧参数做步数预算会让质量曲线与实际错位，表现为“按公式算该达标、实测却不达标”。标定流程应是：在中等步数区间取若干 <span class=\"formula\">$$K$$</span> 测 <span class=\"formula\">$$\\mathcal{L}$$</span>，拟合 <span class=\"formula\">$$\\alpha$$</span> 与 <span class=\"formula\">$$C$$</span>，记录拟合残差；残差大说明该区间不服从幂律，决策应退回保守的实测表而非外推。另一条纪律是：容量规划只在该采样器的有效区间内插值，绝不外推到 <span class=\"formula\">$$K&lt;4$$</span>。工程上把标定参数连同采样器版本、模型版本一起写进容量配置，换版本即触发重标定，避免“参数漂移导致的 SLO 违约”。最后，当 <span class=\"formula\">$$\\alpha$$</span> 与 <span class=\"formula\">$$C$$</span> 的标定显示边际收益在目标 <span class=\"formula\">$$K$$</span> 处已低于单步成本的 <span class=\"formula\">$$\\lambda$$</span> 倍，正确的动作是切换至少步蒸馏模型并把省下的算力投向批大小与并发，而不是在同一模型上继续堆 NFE——这是幂律曲线给出的、可直接执行的工程判断。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-28\">二十八 · 把幂律塞进容量模型：步数预算怎么变成批大小、并行度与 SLO</h3>\n<p>容量决策的正确姿势不是先定步数再算吞吐，而是把步数当成一个可优化的连续变量，与单步成本一起进同一个目标函数。设单步前向在给定分辨率与批大小下的耗时为 <span>t<sub>step</sub></span>，端到端延迟预算为 <span>T<sub>SLO</sub></span>，则单请求可用的 NFE 上限为 <span>K<sub>max</sub> = T<sub>SLO</sub> / t<sub>step</sub></span>；而质量侧由 <span>L(K) ≈ L<sub>∞</sub> + C/K<sup>α</sup></span> 给出。把两者接起来的判据是「边际质量收益 = 边际时间成本」：令 <span>−∂L/∂K = αC/K<sup>α+1</sup></span> 等于单位步数在批内摊薄后的时间价值 λ，解出 <span>K* = (αC/λ)<sup>1/(α+1)</sup></span>。这个式子给出的不是「最大步数」，而是「值得买的步数」。工程含义很直接：λ 随批大小上升而下降（单步被更多请求摊薄），所以大 batch 会把 K* 往上推；反之在小 batch、低延迟场景，λ 很大，K* 被压得很低——此时幂律外推就危险了，因为 K* 一旦落进 K<4 区间，公式本身失效，必须改用蒸馏模型而不是继续减步。</p>\n<p>并行度与 KV 预算的定法要跟着 K 走，而不是跟着模型参数量走。扩散/流匹配推理的显存大头不是 KV cache（自回归解码那套连续批处理与 PagedAttention 在这里不适用，见本卷 KV 与批调度条目），而是每步激活、注意力的中间张量与多步之间复用的潜变量缓冲；步数越多，调度器需要保留的状态与重排次数越多，主机侧调度开销随 K 线性增长。因此定并行度时应以「单步前向的算力密度」为粒度做张量并行切分，而把 K 作为串行维度放在流水线里：TP 度决定单步延迟，K 决定串行长度，二者相乘才是端到端时间。若把 K 也拿去做并行（多步流水），通信量按 NVLink 5 上的激活交换次数翻倍，收益却受限于步间依赖，属于典型的用带宽换不到延迟。容量规划上更稳的做法是固定 TP 度、用 K 调节 SLO，把 K 的余量留给长尾请求。</p>\n<p>下表给出一个算例的决策骨架（数值为结构性示例，非实测）：同一模型、同一分辨率，α=1.0、C 归一化为 1，λ 由批大小与 SLO 共同决定。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>批大小 / 延迟预算</th><th>λ（相对）</th><th>解出的 K*</th><th>决策</th></tr></thead><tbody><tr><td>在线低延迟</td><td>小批、紧 SLO</td><td>高</td><td>落入 K&lt;4</td><td>幂律失效，改用少步蒸馏模型</td></tr><tr><td>在线常规</td><td>中等批</td><td>中</td><td>中等步数区间</td><td>按 K* 定 NFE，TP 度按单步延迟定</td></tr><tr><td>离线批量</td><td>大批、宽松 SLO</td><td>低</td><td>偏大但仍在拟合区间</td><td>不越过拟合上界，超出部分换蒸馏而非堆步</td></tr></tbody></table>\n<p>这张表的边界条件必须写进容量模型：幂律只在中等步数区间可拟合，K&lt;4 时离散化误差主导，公式给出的「减步几乎无损」是假象；L<sub>∞</sub> 与 C 绑定采样器与模型，换用 DPM-Solver 或流匹配后必须重新标定，旧参数直接拿来做步数预算会让质量曲线与实际错位。系统代价方面还有一层常被忽略：多步采样在 Blackwell 上每步都要重读模型权重与调度器系数，权重带宽占用随 K 线性叠加，功耗与显存带宽成为隐性上限；当 K 增大到 FID 改善被量化误差（NVFP4/FP8 路径下的舍入）与调度误差淹没时，继续加步只是烧带宽。因此容量决策的落点应是：用拟合出的 α 与 C 估算 K→K/2 的质量损失增量，与单步前向的算力/显存代价对比，若损失增量小于 SLO 允许的质量裕度，就减步或换蒸馏模型；若已逼近 K&lt;4，则停止外推，直接切换到少步蒸馏路线，把省下的算力转投批大小与并行度，而不是继续在步数维度上加码。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-29\">二十九 · 把幂律嵌进容量模型：步数预算与并行度的联立求解</h3>\n<p>把 $$\\mathcal{L}(K)$$ 直接当成目标函数做容量规划会漏掉一半代价：质量损失是感知侧的，而步数预算是系统侧的。工程上正确的做法是把边际收益与单步边际成本放在同一量纲上比较。设单步前向在给定批大小 $$B$$、分辨率与并行度下的耗时为 $$t_{\\text{step}}(B)$$，则每单位质量改善所对应的时延代价为 $$\\frac{\\partial \\mathcal{L}/\\partial K}{t_{\\text{step}}(B)}$$。令其等于 SLO 允许的单位时延质量弹性 $$\\lambda$$，解出 $$K^{*}=\\left(\\frac{\\alpha C}{\\lambda\\, t_{\\text{step}}(B)}\\right)^{1/(\\alpha+1)}$$。这个式子把三件事绑在一起：$$\\alpha$$ 越小（衰减越慢），$$K^{*}$$ 越大；单步越贵（$$t_{\\text{step}}$$ 大，例如高分辨率、大 batch、跨节点并行引入通信开销），$$K^{*}$$ 越小。注意 $$K^{*}$$ 与批大小通过 $$t_{\\text{step}}(B)$$ 耦合——批大小翻倍时单步时间并非线性增长（Blackwell 上大 batch 能摊薄权重加载与 tcgen05 的启动开销），因此不能先定批大小再定步数，必须联立。</p>\n<p>并行度决策的边界在于：步数降低会改变计算形态。当 $$K$$ 被压到很少步时，单次前向的计算密度上升、序列/空间维度的并行切分收益变化，原本为多步长流水设计的张量并行切分可能不再划算，通信占比上升反而拖慢单步。此时应把并行度按“单步时延最小”而非“吞吐最大”重新搜索，并把省下的步数预算换成更大的批或更高的分辨率。KV 预算在扩散采样里不是自回归意义上的 KV cache，而是每步保留的中间潜变量与条件嵌入；步数减少直接线性压缩这部分显存占用，使更大批或更长序列成为可能，这是少步蒸馏在显存侧的隐性收益。</p>\n<p>算例：某流匹配模型拟合得 $$\\alpha=1.0$$、$$C=0.8$$，当前 $$K=32$$ 时 $$\\mathcal{L}\\approx \\mathcal{L}_\\infty+0.025$$。若把 $$K$$ 降到 16，损失增量为 $$0.8/16-0.8/32=0.025$$，即质量损失翻倍于原残差项。假设单步时延 6 ms、SLO 要求端到端 120 ms，则 16 步占 96 ms，余量仅够一次条件编码与解码；若换用少步蒸馏模型把有效步数压到 4，虽落在幂律失效区（$$K&lt;4$$ 离散化误差主导，不能外推上式），但蒸馏模型自身已把该区间的误差压回可用范围，此时应改用蒸馏模型的实测曲线而非旧拟合参数。反之，若沿用旧 $$\\alpha,C$$ 去规划 4 步预算，会低估质量骤降的风险。</p>\n<table class=\"mini\"><thead><tr><th>决策项</th><th>依赖量</th><th>失效条件</th></tr></thead><tbody><tr><td>批大小</td><td>$$t_{\\text{step}}(B)$$ 与 $$K^{*}$$ 联立</td><td>批过大导致单步时延非线性上升</td></tr><tr><td>并行度</td><td>单步时延最小化</td><td>少步时通信占比反超计算</td></tr><tr><td>步数预算</td><td>$$\\alpha,C,\\lambda$$</td><td>$$K&lt;4$$ 或换采样器未重标定</td></tr></tbody></table>\n<p>这套方案的硬边界是标定成本：每次换采样器（DPM-Solver、流匹配）或换模型都必须重拟合 $$\\alpha$$ 与 $$C$$，跨采样器复用参数会让步数预算与真实质量曲线错位，容量规划随之失真。工程判断上，把幂律当作“中等步数区间的局部线性化工具”，用它回答“减半步数要付多少质量代价、这笔代价换来的时延余量能否换成更大批或更高分辨率”，而不是当作全局真理去外推极少步区间。</p>\n<h3 id=\"th-diffusion-steps-quality-sec-30\">三十 · 误用一：把幂律外推到 K&lt;4 的极少步区间</h3>\n<p>最常见的误用，是把 $$\\mathcal{L}(K)\\approx\\mathcal{L}_\\infty+C/K^{\\alpha}$$ 这条拟合曲线当成全域成立的物理定律，然后向 K 减小的方向一路外推。工程上这几乎必然发生：容量规划时想知道“如果 NFE 从 20 压到 4、再压到 2，延迟能省多少、质量掉多少”，最省事的做法就是拿现成的 $$\\alpha$$ 与 $$C$$ 代入公式算。问题在于，幂律描述的是中等步数区间内截断误差随步长收缩的渐近行为；当 K 掉到 4 以下，单步积分步长已经大到离散化误差（一阶/二阶采样器的局部截断项）成为主导项，误差不再按 $$K^{-\\alpha}$$ 平滑收缩，而是出现台阶式跳变。此时公式给出的“再减一半步数只损失一点点”是纯粹的数学幻觉。</p>\n<p>机制上可以这样看：以 DDIM 或 Euler 类一阶求解器为例，单步局部截断误差量级为 $$O(h^{p+1})$$，$$h=1/K$$ 为归一化步长，$$p$$ 为求解器阶数；当 $$h$$ 接近 1（即 K 接近 1）时，高阶项不再是小量，泰勒展开的前提崩掉，误差累积从“平滑幂律”切换为“结构性失真”——生成样本出现明显的高频伪影、语义漂移、色彩块状崩坏，而不是 FID 缓慢爬升。流匹配的 ODE 求解同理：少步区间里速度场的非线性在单个大步长内无法被线性近似捕获。</p>\n<p>系统代价非常具体。假设某团队在 Blackwell 上以 K=20 标定出 $$\\alpha=1.0$$、$$C$$ 使 FID 从 20 步的基线下降若干，然后按公式把 NFE 压到 2，预期 FID 只上升约一个 $$C/2$$ 与 $$C/20$$ 之差的可控量。实际部署后，单步前向的算力确实省了 90%，但生成质量骤降，下游判别器或人工审核环节的返工率上升，端到端有效吞吐反而下降——省下的 GPU 时间被重采样与后处理吃掉。更隐蔽的代价在显存与调度侧：少步采样常被用来缩短单请求延迟以塞进更紧的 SLA，一旦质量不达标需要回退到多步，批调度器的连续批处理窗口被打乱，预填/解码分离架构里解码阶段的步数抖动会传导为 KV cache 复用率下降。</p>\n<p>识别方法：在标定区间之外做“留出步数验证”，至少在 K=2、3、4 三个点实测 FID 或 CLIP 分数差，画出实测曲线与拟合曲线的残差；若残差在低 K 端单调放大且出现拐点，即判定幂律失效。工程判断是：把 K&lt;4 视为禁区，除非有少步蒸馏模型（如把多步教师蒸馏到 1–4 步学生）单独标定的曲线，否则不得用同一组 $$\\alpha$$、$$C$$ 做预算。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-31\">三十一 · 误用二：换采样器后沿用旧拟合参数</h3>\n<p>第二个高频误用发生在采样器切换时。团队先在 DPM-Solver 上标定出一组 $$\\alpha$$、$$C$$，后来为了少步性能换成流匹配（或反向从流匹配换回 DPM-Solver），却直接把旧参数抄进容量模型。公式本身没错，错在 $$\\mathcal{L}_\\infty$$ 与 $$C$$ 是采样器与模型联合决定的量：不同求解器的离散化结构、对速度场/分数场的近似阶数、以及是否使用二阶修正，都会改变残余损失 $$\\mathcal{L}_\\infty$$ 的位置和幂律常数 $$C$$。跨采样器复用参数，等于假设两个求解器在同一 K 下产生同一误差曲线，这个假设没有任何依据。</p>\n<p>机制层面：DPM-Solver 系列通过指数积分器与多步外推降低截断误差，其误差随 K 的衰减往往比一阶 Euler 更陡（$$\\alpha$$ 偏大）；流匹配的 ODE 右端是回归出的速度场，其误差还叠加了网络拟合误差，$$\\mathcal{L}_\\infty$$ 通常更高。因此同一个 K 下两条曲线的交点位置不同，用旧 $$\\alpha$$ 估算“K 减半的损失增量”会系统性偏乐观或偏悲观。偏乐观的后果最危险：按旧参数把 NFE 压到 SLA 下限，实测质量不达标，触发线上回滚，回滚窗口内的请求全部走多步路径，延迟尖峰打穿 SLO。</p>\n<p>系统代价体现在容量规划的错位：以 $$\\alpha$$ 估算的“每减一步的 FID 代价”若比真实值小，调度器会把步数预算设得过低，GPU 侧看似算力充裕、实际有效吞吐被质量返工抵消；若比真实值大，则保守地堆步数，在 Blackwell 上白白消耗单步前向的算力与功耗，却换不到可测的 FID 改善——这正是“只按最大步数堆叠”的另一种表现形式。识别方法：换采样器后强制重新标定，至少在三个 K 点（如 8、16、32）重跑 FID/CLIP，比较新旧 $$\\alpha$$ 的置信区间是否重叠；不重叠即说明参数不可迁移。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-32\">三十二 · 误用三：只堆最大步数，忽略单步成本</h3>\n<p>第三类误用是把“步数越多质量越好”当成单调真理，在容量决策里直接取最大可用 NFE，而不去令边际收益等于单步推理成本。公式的导数 $$\\partial\\mathcal{L}/\\partial K=-\\alpha C/K^{\\alpha+1}$$ 已经把这件事说清楚：边际质量收益随 K 单调递减且按幂律收缩，而单步推理成本（一次前向的算力、显存带宽、功耗）近似恒定。最优步数应满足边际收益等于边际成本，超过该点后继续加步数是用线性增长的成本换幂律衰减的收益。</p>\n<p>在 Blackwell 上这个代价被放大：单步前向涉及 tcgen05 MMA 与 TMEM 的占用、权重与激活的显存带宽往返，NFE 翻倍意味着这些资源占用翻倍，而 FID 改善在超过某点后被量化误差（NVFP4/FP8 的舍入）与调度误差（批内不同请求步数不一致导致的 padding 与同步开销）淹没。也就是说，堆步数不仅收益递减，还会把系统推入“量化噪声主导”的区间——此时再多步数也无法突破精度地板。</p>\n<p>具体例子：一个多模态生成服务在 GB200 NVL72 上以 K=50 运行，SLO 允许的 p99 延迟尚有裕量，团队于是把 NFE 提到 100 期望 FID 再降。实测 FID 改善落在噪声范围内，而单请求 GPU 时间翻倍，连续批处理的批大小被迫减半，吞吐下降，NVL72 内 NVLink 5 上的集合通信（如张量并行 all-reduce）频次随步数增加而上升，通信开销占比抬升。识别方法：对 K 做扫描并同时记录 FID 与单步成本，画出“每单位成本的质量增益”曲线，当该曲线穿过零或进入噪声带即停止加步。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-33\">三十三 · 一个反例：把 K=2 写进 SLA 的容量模型</h3>\n<p>给出一个完整的反例。某团队要为一个图像生成接口定容量：SLA 要求 p99 延迟不超过阈值，GPU 池按 NVL72 机架规划。他们已有 K=16 到 K=64 区间的标定数据，拟合得 $$\\alpha\\approx1.0$$、$$\\mathcal{L}_\\infty$$ 与 $$C$$ 已知，据此推算 K=2 时质量损失仅比 K=16 高一个可控增量，于是把 NFE=2 写进容量模型，按此配置批大小与机架数，并对外承诺质量指标。</p>\n<p>上线后实测：K=2 的样本出现结构性伪影，FID 相对 K=16 的劣化远超公式预测，CLIP 分数差同样跳变；原因是 K=2 落在 K&lt;4 的离散化误差主导区，幂律前提不成立。后果是双重的：一是质量返工使有效吞吐低于规划值，机架数按公式算出的“够用”实际不够；二是为补救而临时把部分请求切回 K=16，批内步数不一致导致调度器频繁重排批次，预填/解码分离架构中解码侧的步数抖动传导为 KV cache 复用率下降与显存碎片上升。最终该团队不得不回滚容量模型，改用少步蒸馏学生模型单独标定的曲线，并为 K&lt;4 区间建立独立的实测质量表。</p>\n<p>这个反例的可迁移教训是：容量模型里每一个 K 都必须有实测支撑，公式只负责在标定区间内插值，不负责外推。把“公式算出来的乐观值”直接写进 SLA，等于把数学假设当成工程事实。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-34\">三十四 · 识别清单与工程判断</h3>\n<p>把上述误用收敛成可执行的识别清单：其一，检查步数预算是否落在标定区间内，任何 K&lt;4 的取值必须有独立实测或蒸馏模型标定；其二，检查 $$\\alpha$$、$$C$$ 的标定采样器与当前部署采样器是否一致，不一致即重新标定；其三，检查容量模型是否包含单步成本项，若只优化质量不约束成本，必然滑向堆步数；其四，检查 FID 改善是否已进入量化与调度噪声带，用重复测量的方差界定“可测改善”的门槛。</p>\n<p>工程判断落在一句话上：在 Blackwell 上，步数预算的正确形态是“标定区间内的插值 + 少步蒸馏的独立曲线”，而不是“一条幂律外推到零”。当边际收益 $$\\alpha C/K^{\\alpha+1}$$ 已经小于单步前向的算力与带宽代价时，继续加 K 是用确定性的系统成本换不可测的质量噪声；当 K 已逼近离散化误差主导区时，正确动作是换蒸馏学生模型，而不是在公式里继续减步。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-35\">三十五 · 幂律外推的两处塌陷：K&lt;4 与换采样器</h3>\n<p>最典型的误用是把 <span class=\"formula\">$$\\mathcal{L}(K)\\approx\\mathcal{L}_\\infty+\\frac{C}{K^{\\alpha}}$$</span> 当成全域成立的定律，向 <span class=\"formula\">$$K&lt;4$$</span> 的极少步区间做外推，得出“再减几步几乎无损”的结论，并据此把 NFE 预算压到 2 或 3 步。失效机理是清楚的：幂律描述的是截断误差随步长收缩的渐近行为，而在极少步时主导项换成离散化误差——单步积分跨度过大，采样轨迹无法落在概率流的主流形上，误差不再按 <span class=\"formula\">$$1/K^{\\alpha}$$</span> 平滑衰减，而是阶跃式抬升。此时 <span class=\"formula\">$$\\frac{\\partial\\mathcal{L}}{\\partial K}=-\\frac{\\alpha C}{K^{\\alpha+1}}$$</span> 给出的边际收益被严重高估，用它去和单步推理成本做等价比较，等于拿一条已经不成立的曲线做容量决策。识别方法很直接：在目标区间实测两三个点（例如 K=2、3、4）的 FID 或 CLIP 分数差，若实测值显著高于拟合曲线预测，就说明已越出拟合的有效区间，任何基于该曲线的减步论证都应作废。</p>\n<p>第二处塌陷发生在采样器替换。$$\\alpha$$ 与 $$C$$ 同时编码了调度器形状与模型score 场的尺度，换用 DPM-Solver 或流匹配后，误差随步数的收缩路径改变，旧参数不再可迁移。沿用旧拟合做步数预算的后果是质量曲线与实际错位：规划时以为 K=12 已进入平台区，实际可能仍在陡降段，SLA 内的质量承诺落空；反之也可能过度保守，白白多付 NFE。工程上应把 ($$\\alpha$$, $$C$$, $$\\mathcal{L}_\\infty$$) 视为绑定到“模型 + 采样器 + 分辨率”三元组的标定产物，随采样器变更强制重标，并把重标成本计入模型迭代流程。</p>\n<p>反例：某多模态生成服务在旧采样器上拟合得 $$\\alpha$$ 偏大，判断 K=8 已接近 $$\\mathcal{L}_\\infty$$，于是把线上 NFE 从 20 压到 8，单次请求的 UNet/DiT 前向次数下降过半，单卡吞吐随之抬升。随后为追质量换用另一族采样器，却直接复用旧 $$\\alpha$$、$$C$$ 继续按 K=8 排容量，结果实测质量明显低于预测，团队误判为“模型退化”而回滚模型，真正的问题是步数预算建立在失效的拟合上。正确做法是换采样器后先在 K=4、8、16 三点重标，再决定 NFE 上限。</p>\n<p>第三类误用是只朝最大步数堆叠：在 Blackwell 上把 NFE 拉到远超平台区，单步前向的算力与显存带宽代价线性增长，而 FID 改善已被量化误差与调度误差淹没，等于用吞吐和功耗换一个测不出的指标。判断依据是边际收益与单步成本的比较——当 <span class=\"formula\">$$\\frac{\\alpha C}{K^{\\alpha+1}}$$</span> 折算出的质量增益已小于一步前向的时延代价时，继续加步就是负收益，此时应转向少步蒸馏而非堆步数。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>K</td><td>采样步数（NFE）</td></tr><tr><td>\\mathcal{L}(K)</td><td>感知质量损失（如 FID 或 CLIP 分数差）</td></tr><tr><td>\\alpha</td><td>衰减指数，通常 0.5–1.5</td></tr><tr><td>C</td><td>与调度器和模型相关的常数</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-diffusion-steps-quality · 共 5 个片段</p>\n"},{"id":"th-visual-token-rate-distortion","title":"视觉 token 率-失真界","direction":"dir-visual-token-compression","prereq":[],"plain":"视觉 token 压缩本质是率-失真问题：保留 r 比例 token 时，重建/任务失真下界随 r 下降而上升；Blackwell 上应把压缩预算花在信息量高的 token 上，使实际失真贴近该下界而非均匀裁剪。","definition":"视觉 token 压缩本质是率-失真问题：保留 r 比例 token 时，重建/任务失真下界随 r 下降而上升；Blackwell 上应把压缩预算花在信息量高的 token 上，使实际失真贴近该下界而非均匀裁剪。","formula":"$$D(r)\\ \\ge\\ D_0\\cdot\\exp\\!\\left(-\\beta\\, r\\right),\\qquad r=\\frac{N_{\\text{keep}}}{N_{\\text{vis}}}$$","variables":[{"sym":"r","meaning":"保留 token 比例"},{"sym":"N_{\\text{keep}},\\ N_{\\text{vis}}","meaning":"保留与原始视觉 token 数"},{"sym":"D(r)","meaning":"任务失真（如答案准确率下降或重建误差）"},{"sym":"\\beta","meaning":"压缩效率系数，由选择策略（注意力/熵/低秩）决定"}],"derivation":"推导关键一步：把 token 选择视为按信息量排序的贪心分配，每多保留一个高信息 token 带来的失真下降与其信息量成正比，积分后得到失真随保留比例指数衰减的下界；$$\\beta$$ 越大说明选择策略越能挑出高信息 token，曲线越陡。","example":"容量决策用途：给定延迟或显存预算反解所需 r，再用 $$\\beta$$ 判断当前选择策略离下界还有多少余量；若实测失真远高于下界，说明选择策略低效，应换用注意力或熵引导的合并而非均匀下采样，以在同等 r 下换取更低失真。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["指数界假设 token 信息独立同分布；视觉 token 存在强空间相关，实际曲线在低 r 处更陡","D_0 与 β 依赖任务（OCR、VQA、视频理解差异大），跨任务不可直接复用"],"system_note":"常见误用：把均匀裁剪当作达到下界，忽略高信息 token 被误删导致 OCR 与小目标识别失真骤增；另一误用是把某任务标定的 $$\\beta$$ 直接搬到另一任务做容量规划，低估低 r 区间的失真上升速度。","papers":["paper-an-image-is-worth-16x16-words-transf-2020"],"facts":["直觉：视觉 token 压缩是率-失真问题，保留比例 r 越低失真下界越高；应把压缩预算花在信息量高的 token 上（注意力、熵或低秩选择），使实际失真贴近指数下界，而不是均匀裁剪。","公式 $$D(r)\\ge D_0\\cdot\\exp(-\\beta r)$$ 中，$$r=\\frac{N_{\\mathrm{keep}}}{N_{\\mathrm{vis}}}$$ 是保留 token 比例，$$N_{\\mathrm{keep}}$$ 与 $$N_{\\mathrm{vis}}$$ 分别为保留与原始视觉 token 数，$$D(r)$$ 是任务失真（答案准确率下降或重建误差），$$D_0$$ 是零压缩时的基准失真，$$\\beta$$ 是由选择策略决定的压缩效率系数。","推导关键一步：把 token 选择视为按信息量排序的贪心分配，每多保留一个高信息 token 带来的失真下降与其信息量成正比，积分后得到失真随保留比例指数衰减的下界；$$\\beta$$ 越大说明选择策略越能挑出高信息 token，曲线越陡。","适用边界：指数界假设 token 信息独立同分布；视觉 token 存在强空间相关，实际曲线在低 r 处比指数界更陡；$$D_0$$ 与 $$\\beta$$ 依赖任务，OCR、VQA、视频理解差异大，跨任务不可直接复用同一组参数。","容量决策用途：给定延迟或显存预算反解所需 r，再用 $$\\beta$$ 判断当前选择策略离下界还有多少余量；若实测失真远高于下界，说明选择策略低效，应换用注意力或熵引导的合并而非均匀下采样，以在同等 r 下换取更低失真。","常见误用：把均匀裁剪当作达到下界，忽略高信息 token 被误删导致 OCR 与小目标识别失真骤增；另一误用是把某任务标定的 $$\\beta$$ 直接搬到另一任务做容量规划，低估低 r 区间的失真上升速度。"],"anchors":["未给出"],"pitfalls":["用均匀裁剪替代信息量引导的 token 选择，高信息 token 被误删，OCR 与小目标识别失真远超指数下界。","把某任务标定的 β 直接迁移到另一任务做压缩预算，忽略空间相关与任务差异，低 r 区间失真被低估。","只按 r 做容量规划而不校验实际失真与下界的差距，选择策略低效却误以为已接近理论最优。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-1\">一 · 一句话直觉与它的物理含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-2\">二 · 严格定义：三个变量与一个不等式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-3\">三 · 为什么推理系统必须要有这个界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-4\">四 · 常见误解之一：均匀裁剪等于达到下界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-5\">五 · 常见误解之二：β 可以跨任务搬运</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-6\">六 · 常见误解之三：把 r 当容量指标而不校验间隙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-7\">七 · 指数界的适用边界与误用代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-8\">八 · 逐项拆解：D₀、β 与 r 各自的物理含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-9\">九 · 推导关键步：贪心排序如何积分成指数下界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-10\">十 · 离散化与近似落在哪里：三处必须交代的误差源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-11\">十一 · 失效条件的系统含义：跨任务不可复用 β</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-12\">十二 · 用公式做工程判断：反解 r 与校验余量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-13\">十三 · 指数界的适用半径：空间相关、任务标定与选择策略的余量核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-14\">十四 · 独立同分布假设与空间相关的真实落差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-15\">十五 · D₀ 与 β 的任务依赖性：跨任务不可复用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-16\">十六 · 选择策略低效时公式退化为上界而非可达界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-17\">十七 · 规模上限：N_vis 增大时界的渐近失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-18\">十八 · 失效条件的工程清单与校验动作</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-19\">十九 · 指数界的适用半径：i.i.d. 假设破裂之后</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-20\">二十 · 把失真界翻译成可解的容量方程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-21\">二十一 · 用 r 反解批大小与并行度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-22\">二十二 · 定 KV 预算：把 r 写进分页与驱逐策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-23\">二十三 · 定 SLO：延迟分解里 r 的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-24\">二十四 · 一个联立算例与校验回路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-25\">二十五 · 把率-失真界嵌进容量决策：反解 r、校验 β、锁定 SLO 余量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-26\">二十六 · 率-失真界在容量决策中的反解与校验</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-27\">二十七 · 把“下界”当成“可达值”：均匀裁剪的隐性代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-28\">二十八 · 跨任务搬运 β：低 r 区间的失真被系统性低估</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-29\">二十九 · 只看 r 不看差距：选择策略低效却被当成已逼近最优</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-30\">三十 · 一个反例：文档 OCR 流水线的“最优压缩”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-rate-distortion-sec-31\">三十一 · 误用与反例：当“贴近下界”被读成“均匀裁剪即最优”</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:515px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 515.3 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：视觉 token 压缩本质是率-失真问题：保留 r 比例 toke…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$D(r)\\ \\ge\\ D_0\\cdot\\exp\\!\\left(…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：指数界假设 token 信息独立同分布；视觉 token 存在强空…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-visual-token-rate-distortion-sec-1\">一 · 一句话直觉与它的物理含义</h3>\n<p>把视觉 token 压缩看成一次“预算分配”而非“删减”：原始视觉 token 数为 <span class=\"sym\">N<sub>vis</sub></span>，你只允许保留 <span class=\"sym\">N<sub>keep</sub></span> 个送进语言主干，保留比例 <span class=\"sym\">r = N<sub>keep</sub>/N<sub>vis</sub></span> 就是你的预算。率-失真视角断言一件事：<strong>失真下界随 r 下降而指数上升，且这个下界只由“你挑 token 挑得多准”决定，不由“你删得多狠”决定</strong>。换句话说，同样保留 10% 的 token，均匀下采样与注意力引导的合并处在两条完全不同的曲线上，前者离下界很远，后者可以贴近下界。Blackwell 上的工程含义因此非常直接：压缩的算力预算不该花在“多删”，而该花在“算清哪个 token 信息量高”——打分、排序、合并这三步才是 SM100 上真正要加速的部分。</p>\n<p>这个直觉之所以在推理系统里有分量，是因为它把两个原本分开的账合并了。视觉编码器侧的账是算力与带宽（见视觉编码器 Roofline 界），语言主干侧的账是 KV cache 与注意力时延（见多模态 KV cache 显存式）。率-失真界是这两本账之间的汇率：你每多保留一个 token，就多付一份 KV 显存与一份注意力带宽，换回来的失真下降量由该 token 的信息量决定。当某个 token 的信息量低于“每 token 系统代价 ÷ 失真收益”的临界值时，保留它就是纯亏损。这个临界判断必须逐 token 做，而不是逐图做。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-2\">二 · 严格定义：三个变量与一个不等式</h3>\n<p>定义域要先钉死，否则后面所有讨论都会漂。设一张（或一段视频的若干帧）经视觉编码器与投影层后得到 <span class=\"sym\">N<sub>vis</sub></span> 个视觉 token 嵌入，选择策略 <span class=\"sym\">S</span> 是一个从这 <span class=\"sym\">N<sub>vis</sub></span> 个 token 中挑出 <span class=\"sym\">N<sub>keep</sub></span> 个的子集选择算子（可以是 top-k 注意力、熵阈值、低秩子空间投影后的残差排序，或它们的组合）。失真 <span class=\"sym\">D(r)</span> 定义为在该选择下，下游任务指标相对全 token 基线的退化量：对生成式任务取答案准确率下降，对重建类任务取重建误差。基准失真 <span class=\"sym\">D<sub>0</sub></span> 是零压缩（r=1）时的失真，工程上通常取 0 或由量化/数值精度引入的固有偏置（见 VLM 量化误差上界）。</p>\n<div class=\"formula\">$$D(r)\\ \\ge\\ D_0\\cdot\\exp\\!\\left(-\\beta\\, r\\right),\\qquad r=\\frac{N_{\\text{keep}}}{N_{\\text{vis}}}$$</div>\n<p>这里 <span class=\"sym\">β</span> 不是拟合参数，而是<strong>选择策略的效率系数</strong>：它度量 <span class=\"sym\">S</span> 在多大概率上把信息量最高的那批 token 排到了前面。β 越大，曲线越陡，同样的 r 换来的失真越低。严格地说，这个不等式是“最优选择器”的下界陈述：任何选择器都不可能比按信息量排序的贪心分配做得更好，因此实测曲线必然位于该下界之上；而下界本身随 r 指数衰减，是因为贪心分配下每多保留一个 token 的边际失真收益正比于其信息量，对信息量分布积分即得指数形式。</p>\n<p>把定义落到系统量上：给定一个 SLO 要求的端到端时延预算与显存预算，可以反解出允许的 <span class=\"sym\">N<sub>keep</sub></span>，从而得到 r；再用 <span class=\"sym\">β</span> 预测该 r 下的失真下界，与实际测量值比较。<strong>下界与实测之间的间隙就是选择策略的低效额度</strong>，这个间隙是容量规划里唯一值得投入工程去压缩的东西。只按 r 做规划而不校验间隙，等于假设自己的选择器已经最优，这是最常见的规划错误。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-3\">三 · 为什么推理系统必须要有这个界</h3>\n<p>没有这个界，视觉 token 压缩在工程上只能靠试：改一版选择器，跑一遍评测，看指标掉多少。这种做法在单卡单任务上尚可，在 NVL72 这种 72 卡域、多任务混跑的部署里不可行，因为每个任务、每个 r 都要重测，评测成本与时延调优成本叠加。率-失真界提供的是一个<strong>可迁移的判据</strong>：它把“这个选择器好不好”从绝对指标问题变成相对间隙问题——实测失真减去下界，剩下的部分才是选择器的锅，其余部分是 r 本身决定的、任何选择器都逃不掉的代价。</p>\n<p>它同时给出容量决策的方向性结论。假设某部署要在固定显存下把并发批大小翻倍，直觉做法是把 r 减半；但由不等式，失真上升量是 <span class=\"sym\">exp(-βr)</span> 在低 r 区间的斜率所决定的，若 <span class=\"sym\">β</span> 小（选择器差），减半 r 的失真代价远大于 β 大的情形。于是正确的工程顺序是：先把 β 做大（换注意力/熵引导的合并），再动 r。这与“先扩并发再优化质量”的常见顺序相反，但在 SLO 约束下前者更省总算力，因为 β 的提升是一次性的选择器改造成本，而 r 的下降是每次请求都要付的失真税。</p>\n<ul>\n<li><strong>延迟代价</strong>：选择器本身要在视觉编码器输出上做打分与排序，这是一次 O(N<sub>vis</sub>) 的轻量算子；若用注意力分数则需复用编码器最后一层的注意力图，避免二次前向。</li>\n<li><strong>吞吐代价</strong>：r 下降直接减少语言主干的 prefill token 数与 KV 写入量，吞吐近似按 r 线性受益；但选择器的固定开销不随 r 缩小，低 r 时其占比上升。</li>\n<li><strong>显存代价</strong>：KV cache 随 N<sub>keep</sub> 线性下降，这是压缩最主要的收益来源；视觉编码器侧的激活显存不随 r 变化。</li>\n<li><strong>带宽代价</strong>：跨卡传输的视觉 token 数随 r 下降，在分离式预填/解码部署里直接减轻 NVLink 上的 token 搬运量（见 NVL72 通信下界）。</li>\n</ul>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-4\">四 · 常见误解之一：均匀裁剪等于达到下界</h3>\n<p>最普遍的误解是把“保留 r 比例”当成“均匀保留 r 比例”。均匀下采样（等间隔取帧、等步长取 patch）在信息分布均匀时确实接近最优，但视觉 token 的信息量分布是重尾的：文档 OCR 里文字笔画所在的 patch、小目标检测里目标边界所在的 patch，其信息量比大片背景 patch 高出若干量级。均匀裁剪会以与信息量无关的概率误删这些 token，导致失真曲线在低 r 处骤然抬升，远超指数下界。</p>\n<p>机制上可以这样看：设第 i 个 token 的信息量为 <span class=\"sym\">w<sub>i</sub></span>，均匀选择器保留每个 token 的概率都是 r，则期望保留的信息量为 <span class=\"sym\">r·Σw<sub>i</sub></span>；而按信息量排序的贪心选择器保留的是 top-r 分位的 <span class=\"sym\">w<sub>i</sub></span>，在重尾分布下这个和显著大于前者。两者之差就是均匀裁剪相对于下界的间隙。工程判断很干脆：<strong>只要任务的失真对少数关键 token 敏感（OCR、小目标、表格结构），均匀裁剪就不可用于低 r 区间</strong>；它只适合 r 较高、且任务对局部细节不敏感的粗粒度场景。</p>\n<p>代价层面，均匀裁剪看似零成本（不需要打分），但它把成本转移到了失真上：为了达到与信息引导选择相同的失真，均匀裁剪必须用更高的 r，也就是更多的 KV 显存与更长的 prefill。这笔账在多并发部署里会被放大——省下的选择器算力远小于多保留 token 带来的显存与带宽开销。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-5\">五 · 常见误解之二：β 可以跨任务搬运</h3>\n<p>第二个误解是把在一个任务上标定出的 <span class=\"sym\">β</span> 直接用于另一个任务的容量规划。事实是 <span class=\"sym\">D<sub>0</sub></span> 与 <span class=\"sym\">β</span> 都依赖任务：OCR 的失真对文字 token 的误删极度敏感，β 在信息引导下可以很大，但一旦选择器退化为均匀，曲线立刻变缓；VQA 的失真对全局语义更敏感，单 token 信息量分布较平，β 相对小；视频理解的失真还叠加时间维度的相关性，token 间不再独立，指数界的假设本身就开始失效。</p>\n<p>更隐蔽的问题是低 r 区间的斜率。指数界假设 token 信息独立同分布，而视觉 token 存在强空间相关：相邻 patch 高度冗余，这意味着在中等 r 区间，删掉冗余 token 几乎不掉失真，实测曲线比指数界更平；但一旦 r 低到开始触碰“每个空间区域仅剩一个代表 token”的临界点，相关性带来的冗余耗尽，曲线会比指数界更陡。因此跨任务搬运 β 的系统性后果是<strong>在低 r 区间低估失真上升速度</strong>，规划出的并发数在纸面上达标、在实测中击穿 SLO。正确做法是每个任务族单独标定一组 (D<sub>0</sub>, β)，并在低 r 区间留出安全裕度，裕度大小由该任务的空间相关强度决定。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-6\">六 · 常见误解之三：把 r 当容量指标而不校验间隙</h3>\n<p>第三个误解出现在容量规划环节：把 r 当成唯一的压缩档位参数，按 r 排布并发与显存，却从不测量实测失真与下界的间隙。这等于默认选择器已经最优。实际后果是：选择器低效（β 小）时，系统在同样的 r 下失真远高于下界，但规划者以为“已经按理论最优配置”，于是把 SLO 击穿归因于模型能力而非选择策略，错过了换用注意力或熵引导合并的机会。</p>\n<p>可操作的校验流程是：对每个任务族，在若干 r 点上同时记录实测失真与由标定 (D<sub>0</sub>, β) 算出的下界，画出间隙曲线。若间隙随 r 下降而扩大，说明选择器在低 r 处失效（典型是打分算子在高压缩下丢失了细粒度信息），应改用保留空间结构的合并而非纯 top-k 丢弃；若间隙基本恒定，说明选择器效率已稳定，此时再降 r 是安全的容量手段。这个流程把“压缩预算花在信息量高的 token 上”从口号变成可测量的工程判据，也是本卷后续讨论具体选择算子与 Blackwell 实现时的基准线。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-7\">七 · 指数界的适用边界与误用代价</h3>\n<p>指数界不是无条件成立的承诺，而是一张“理想选择器”的成绩单：它把 token 选择视为按信息量排序的贪心分配，每多保留一个高信息 token 的失真下降与其信息量成正比，积分后得到 <span class=\"formula-inline\">$$D(r)\\ge D_0\\exp(-\\beta r)$$</span>。推导成立的前提是 token 信息独立同分布，而视觉 token 恰恰是强空间相关的——相邻 patch 大量冗余，低 r 区间一旦删到关键结构（文字笔画、小目标轮廓），失真曲线会比指数界更陡。因此这条界只保证“不会更好”，不保证“能达到”；把界当预测值做容量规划，等于默认选择器已经最优。</p>\n<p>更隐蔽的失效来自参数迁移。<span class=\"formula-inline\">$$D_0$$</span> 与 <span class=\"formula-inline\">$$\\beta$$</span> 都依赖任务：OCR 的失真对笔画完整性极度敏感，VQA 对全局语义更宽容，视频理解还要叠加时序冗余。在 OCR 上标定的 <span class=\"formula-inline\">$$\\beta$$</span> 搬到 VQA 做预算，会系统性低估低 r 区间的失真上升速度。工程上应把 <span class=\"formula-inline\">$$\\beta$$</span> 当作“选择策略效率”的度量而非任务常数：<span class=\"formula-inline\">$$\\beta$$</span> 越大说明注意力/熵/低秩选择越能挑出高信息 token，曲线越陡；实测失真远高于下界，说明策略低效，应换用信息量引导的合并而非均匀下采样。</p>\n<p>系统代价体现在三处。其一，信息量引导的选择本身要算注意力或熵分数，在 Blackwell 上这是一次额外的前向开销，压缩比越高、省下的 KV 与带宽越多，这笔开销才摊得平；低 r 时省下的显存与 NVLink 传输量可观，但选择器的算力与延迟必须计入 SLO。其二，均匀裁剪看似零成本，却把高信息 token 误删，OCR 与小目标识别的失真骤增，为补回精度只能提高 r，反而吃掉压缩收益。其三，只按 r 做容量规划而不校验实测失真与下界的差距，会把低效选择器误判为接近理论最优，容量预留过多或过少都无人察觉。</p>\n<table class=\"mini\"><thead><tr><th>情形</th><th>失真表现</th><th>系统后果</th></tr></thead><tbody><tr><td>均匀裁剪替代信息量选择</td><td>高信息 token 被误删，OCR/小目标失真远超指数界</td><td>需提高 r 补偿，显存与带宽收益缩水</td></tr><tr><td>跨任务搬用 β</td><td>低 r 区间失真被低估</td><td>容量规划偏乐观，SLO 抖动</td></tr><tr><td>只按 r 规划不校验差距</td><td>策略低效却误认为贴近下界</td><td>预留失准，吞吐与延迟双输</td></tr></tbody></table>\n<h3 id=\"th-visual-token-rate-distortion-sec-8\">八 · 逐项拆解：D₀、β 与 r 各自的物理含义</h3>\n<p>公式 $$D(r)\\ \\ge\\ D_0\\cdot\\exp\\!\\left(-\\beta\\, r\\right)$$ 的三项不是三个可调旋钮，而是三种不同来源的约束。$$D_0$$ 是零压缩时的基准失真，它由视觉编码器本身、分辨率、任务定义共同决定——OCR 的 $$D_0$$ 来自字符笔画在 patch 化后的固有模糊，VQA 的 $$D_0$$ 来自语义粒度不足，二者量纲都不同，因此 $$D_0$$ 不可跨任务比较。$$\\beta$$ 是压缩效率系数，它只由 token 选择策略决定：注意力引导、熵排序、低秩合并各自对应不同的 $$\\beta$$，同一任务下换策略只改 $$\\beta$$ 不改 $$D_0$$。$$r=N_{\\mathrm{keep}}/N_{\\mathrm{vis}}$$ 是预算变量，工程上唯一可直接控制的一项。把三者分开看，容量规划才有意义：先固定 $$D_0$$（选编码器与任务），再评估 $$\\beta$$（选策略），最后反解 $$r$$（定预算）。混在一起调，会把“策略低效”误判为“预算不足”。</p>\n<p>一个具体例子：同一张票据图像，$$N_{\\mathrm{vis}}=1024$$，OCR 任务下 $$D_0$$ 由字符高度决定；若用均匀下采样，$$\\beta$$ 接近零，曲线几乎是平的，砍到 $$r=0.25$$ 时失真骤升；若用注意力引导保留数字区域 token，$$\\beta$$ 显著为正，同样 $$r=0.25$$ 时失真仍贴近下界。系统代价体现在显存与带宽：$$r$$ 从 1 降到 0.25，视觉 KV 占用按比例下降，但若 $$\\beta$$ 低，省下的显存换来的是任务不可用——省显存不等于省得对。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-9\">九 · 推导关键步：贪心排序如何积分成指数下界</h3>\n<p>推导的起点是把 token 选择写成按信息量排序的贪心分配。设第 $$i$$ 个 token 的信息量为 $$w_i$$，按 $$w_1\\ge w_2\\ge\\cdots\\ge w_{N_{\\mathrm{vis}}}$$ 排序后保留前 $$N_{\\mathrm{keep}}$$ 个。关键假设是：每多保留一个 token，失真下降量与该 token 的信息量成正比，即 $$\\Delta D_i \\propto w_i$$。于是总失真下降为 $$\\sum_{i\\le N_{\\mathrm{keep}}} w_i$$ 的累积，而失真本身是“未被保留的信息量”的单调函数。把离散求和写成连续形式，令 $$x=N_{\\mathrm{keep}}/N_{\\mathrm{vis}}=r$$，信息量随排序位置的衰减若近似为线性（$$w(x)\\propto 1-x$$ 或指数形式），积分后即得 $$D(r)\\ge D_0 e^{-\\beta r}$$。这一步的实质是：指数下界不是凭空假设，而是“信息量按排序位置衰减 + 贪心保留”两个条件积分出来的结果；$$\\beta$$ 正是这个衰减速率与选择精度的乘积。</p>\n<p>伪代码思路：对每个视觉 token 计算打分 $$s_i$$（注意力权重、熵、或低秩重构残差），降序排序，取前 $$\\lceil rN_{\\mathrm{vis}}\\rceil$$ 个送入后续层；失真代理量用被丢弃 token 的打分和 $$\\sum_{i&gt;N_{\\mathrm{keep}}} s_i$$ 估计，它与 $$D(r)$$ 单调对应。工程代价在打分本身：注意力打分需要一次前向的注意力图，熵打分需要 logits 统计，低秩合并需要 SVD 或矩阵乘——这些都在预填阶段发生，直接抬高首 token 延迟。以 1024 个视觉 token、隐藏维 1024 为例，低秩打分的矩阵运算量与一次小 GEMM 同量级，但若在每层都做，预填延迟按层数线性放大；因此打分通常只在编码器末层或跨模态注意力入口做一次。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-10\">十 · 离散化与近似落在哪里：三处必须交代的误差源</h3>\n<p>公式是连续的，实现是离散的，误差来自三处。第一处是排序的离散化：$$N_{\\mathrm{keep}}$$ 必须是整数，$$\\lceil rN_{\\mathrm{vis}}\\rceil$$ 的取整在低 $$r$$ 时相对误差大——$$N_{\\mathrm{vis}}=256$$、$$r=0.1$$ 时取整误差可达 4%，直接改变实际保留比例。第二处是打分近似：注意力权重是 softmax 后的相对值，不等于真实信息量；熵是局部不确定性，不等于任务相关性。用这些代理量排序，等价于把 $$\\beta$$ 打了个折，实际曲线低于理论下界对应的 $$\\beta$$。第三处是空间相关的破坏：指数界假设 token 独立，而视觉 token 在 2D 网格上强相关，丢弃一个 token 会同时损失其邻居的部分信息，使低 $$r$$ 区间实际曲线比指数界更陡。三处误差叠加的方向一致——实际失真高于下界，这正是“下界”二字的含义：它不可被达到，只能被逼近。</p>\n<p>具体机制上，空间相关带来的修正可以写成对 $$\\beta$$ 的有效折减：若相邻 token 相关性为 $$\\rho$$，则有效信息量约为 $$w_i(1-\\rho)$$ 加上邻居贡献，等效 $$\\beta_{\\mathrm{eff}}&lt;\\beta$$。工程判断是：在低 $$r$$ 区间不要相信外推的指数曲线，必须用实测点校准。代价体现在容量规划上：按理论 $$\\beta$$ 反解的 $$r$$ 会偏小，实际部署时显存省了但精度掉了，返工成本高于预留余量。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-11\">十一 · 失效条件的系统含义：跨任务不可复用 β</h3>\n<p>指数界的三条失效条件各自对应一种工程误判。独立同分布假设失效，意味着低 $$r$$ 处曲线更陡，容量规划若按指数外推会低估失真上升速度；$$D_0$$ 与 $$\\beta$$ 的任务依赖性，意味着 OCR 标定的参数搬到 VQA 上会系统性偏差——OCR 的高信息 token 是笔画边缘，VQA 的高信息 token 是语义对象，两者的排序几乎不重叠，$$\\beta$$ 不可迁移。跨任务复用参数的代价是隐性的：显存预算按旧任务算，新任务上失真超标却找不到原因，因为 $$\\beta$$ 错了而 $$r$$ 看起来“合理”。正确做法是每个任务独立标定一组 $$(D_0,\\beta)$$，标定点至少覆盖高、中、低三个 $$r$$ 值，用实测失真拟合而非理论外推。</p>\n<p>一个具体例子：视频理解任务中，帧间冗余使 token 空间相关远强于单图 OCR，同一 $$\\beta$$ 下低 $$r$$ 区间失真上升更快；若把单图标定的 $$\\beta$$ 用于视频，按 $$r=0.15$$ 规划容量，实际失真会远超预期。系统代价是解码阶段的 KV 带宽：视觉 token 少了，但若失真导致模型反复重看、生成更长思维链，端到端延迟反而上升——省 token 不等于省时延。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-12\">十二 · 用公式做工程判断：反解 r 与校验余量</h3>\n<p>公式的工程用法是双向的。正向：给定选择策略的 $$\\beta$$ 与任务允许的失真上限 $$D_{\\max}$$，反解 $$r\\ge \\frac{1}{\\beta}\\ln\\frac{D_0}{D_{\\max}}$$，得到最小保留比例，再乘以 $$N_{\\mathrm{vis}}$$ 得显存与带宽预算。反向：给定延迟或显存预算得到 $$r$$，代入公式得理论下界，再与实测失真比较；若实测远高于下界，说明选择策略低效，应换注意力或熵引导的合并而非均匀下采样，以在同等 $$r$$ 下换取更低失真。这个“实测减下界”的差值就是策略余量，是容量规划里最该监控的量。</p>\n<p>校验余量的具体机制：在预填阶段记录被丢弃 token 的打分和作为失真代理，与离线标定的 $$D(r)$$ 曲线对照；若代理量偏离曲线超过阈值，触发策略切换。代价是每次预填多一次打分统计，量级为 $$O(N_{\\mathrm{vis}})$$ 的归约，相对注意力主计算可忽略，但需要额外的标定数据与离线拟合流程。工程判断落在最后一句：只按 $$r$$ 做容量规划而不校验实际失真与下界的差距，等于假设自己的选择策略已经最优——而均匀裁剪恰恰是 $$\\beta\\to 0$$ 的极端，此时指数界退化为常数，任何 $$r$$ 都不省失真。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-13\">十三 · 指数界的适用半径：空间相关、任务标定与选择策略的余量核算</h3>\n<p>该指数下界在工程上真正有用的地方，不是给出一个可被达到的目标值，而是给出一个“不可低于”的参照系，用来判断当前 token 选择策略浪费了多少压缩预算。推导的关键一步是把 token 选择写成按信息量排序的贪心分配：设第 i 个 token 的信息量为 w_i，保留它带来的失真下降正比于 w_i，则保留前 k 个 token 的累计失真下降近似为 Σw_i 的积分形式，在信息量分布近似均匀时积分给出 exp(−βr) 形态。这一步的隐含前提是 token 之间信息可加、互不覆盖——也就是独立同分布假设。视觉 token 恰恰违反它：相邻 patch 高度冗余，一个被保留的 token 所携带的信息会部分“代表”其邻居，因此贪心排序的边际收益在低 r 区间并不衰减得那么快，实测曲线比指数界更陡。这意味着指数界在 r 较高（轻度压缩）时是紧的参照，在 r 很低时则偏松，用它做容量规划会低估失真上升速度。</p>\n<p>失效条件可以归纳为三类，每一类都对应一种具体的系统代价。第一类是选择策略失效：均匀裁剪（等间隔丢 token 或固定网格池化）把高信息 token 与冗余 token 同等对待，OCR 的小字区域、检测任务的小目标、视频中的快速运动区域会被整片误删，此时实测失真远超下界，差距不是几个百分点而是任务性质的退化——OCR 从可读变为不可读。这类失效在系统上表现为“显存与带宽省下来了，但答案准确率断崖”，即省下的 KV cache 与视觉编码算力被失真惩罚抵消。第二类是参数迁移失效：D_0 与 β 依赖任务，OCR 的 β 与视频理解的 β 不可互换，把某任务标定的 β 搬到另一任务反解 r，会在低 r 区间系统性低估失真。第三类是核算失效：只按 r 做容量规划而不校验实测失真与下界的差距，会把一个低效选择策略误判为已接近理论最优，从而停止优化。</p>\n<p>把这三类失效折算成工程判断，需要一个可操作的余量指标。定义选择效率 η = (D_measured − D_0) / (D_bound(r) − D_0)，其中 D_bound(r) 由标定后的 D_0、β 代入指数界得到。η 接近 1 说明策略已贴近下界，继续投入选择算法的收益有限，应转向 KV cache 量化或批调度；η 显著大于 1 说明选择策略低效，同等 r 下还有可换取的失真下降，应改用注意力引导或熵引导的 token 合并而非均匀下采样。这个核算的代价是一次离线标定：对目标任务在若干 r 点上测失真，拟合 D_0 与 β，之后在线只需按 r 查表。表 1 给出三类任务在同一 r 下的定性差异，用于判断 β 能否复用。</p>\n<table class=\"mini\"><thead><tr><th>任务形态</th><th>信息分布特征</th><th>低 r 区间曲线行为</th><th>β 可迁移性</th></tr></thead><tbody><tr><td>OCR / 文档</td><td>信息高度集中于文字笔画区域，空间相关弱于自然图像</td><td>误删即不可读，失真阶跃式上升</td><td>不可迁移至自然图像任务</td></tr><tr><td>VQA / 自然图像</td><td>信息弥散，存在大量冗余背景 token</td><td>曲线较平缓，指数界较紧</td><td>仅可迁移至同分布图像任务</td></tr><tr><td>视频理解</td><td>时间维强相关，帧间冗余极高</td><td>低 r 处比指数界更陡，时间冗余被低估</td><td>不可迁移至单帧任务</td></tr></tbody></table>\n<p>系统代价的落点在带宽与显存两侧。视觉 token 数 N_vis 直接决定预填阶段视觉编码器的输出张量规模与跨模态注意力的 KV 占用，r 下降线性削减这部分显存与 HBM 读写；但若选择策略低效（η 大），省下的带宽换来的是任务失真，等效于用准确率买吞吐，在 SLO 以答案质量为约束的部署里不可接受。反过来，若 η 已接近 1，继续压低 r 的边际失真上升由 β 决定，此时应把压缩预算转向 KV cache 的数值精度（FP8/NVFP4）而非继续删 token，因为后者已触及信息论边界。判断依据是：给定延迟预算反解 r 后，先算 D_bound(r)，再看实测 D_measured 落在何处；两者差距大就换选择策略，差距小就换压缩维度。</p>\n<h3 id=\"th-visual-token-rate-distortion-sec-14\">十四 · 独立同分布假设与空间相关的真实落差</h3>\n<p>指数界的推导把 token 选择写成按信息量排序的贪心分配：每多保留一个 token，失真下降量正比于该 token 的信息量，对排序后的信息量积分即得 <span class=\"formula-inline\">$$D(r)\\ge D_0\\exp(-\\beta r)$$</span>。这一步的隐含前提是 token 之间信息可加、互不重叠——即独立同分布。视觉 token 恰恰违反它：ViT 的 patch 序列经自注意力后，相邻 patch 的表征高度冗余，一张文档图像里同一行文字的多个 patch 携带近乎相同的笔画信息，一个物体被数十个 patch 共同覆盖。此时\"信息量排序\"不再是良定义的单调序列，删掉一个 patch 的边际失真取决于它的邻居是否被保留。</p>\n<p>后果是双向的。在低 <span class=\"formula-inline\">$$r$$</span> 区间，一旦某个空间簇被整体裁掉，失真不是平滑上升而是阶跃式跳变，实测曲线比指数界更陡；在中高 <span class=\"formula-inline\">$$r$$</span> 区间，冗余 token 被删反而几乎无损，曲线比指数界更平。因此这条界只能当作下界使用——它给出\"最好情况能到哪\"，不能反解出\"给定 r 一定有多少失真\"。工程上判断是否落入适用区间的直接办法是测 <span class=\"formula-inline\">$$D(r)$$</span> 曲线的二阶差分：若在某个 <span class=\"formula-inline\">$$r$$</span> 处出现明显拐点，说明空间相关开始主导，指数拟合在该点以下失效。</p>\n<p>代价层面，空间相关意味着选择策略必须做簇级决策而非 token 级决策。注意力引导的合并（merge 而非 drop）在 Blackwell 上要多一次相似度矩阵计算与 scatter 写回，TMEM 中保留的中间张量尺寸上升，单层视觉编码的额外开销落在 SM 的 MMA 与 TMEM 带宽上；换来的收益是在同等 <span class=\"formula-inline\">$$r$$</span> 下失真贴近下界。若为省这次合并而退回均匀下采样，省下的是编码器前段的算力，付出的是 OCR 与小目标识别在低 <span class=\"formula-inline\">$$r$$</span> 处的失真骤增——这类失真无法通过增加解码侧算力挽回。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-15\">十五 · D₀ 与 β 的任务依赖性：跨任务不可复用</h3>\n<p>公式里两个参数都不是硬件的函数，而是任务与选择策略的函数。<span class=\"formula-inline\">$$D_0$$</span> 是零压缩基准失真，它由任务本身的判别难度决定：OCR 在零压缩下失真接近零（字符可完全恢复），VQA 在零压缩下仍受语言模型与视觉对齐误差限制，视频理解还要叠加时序聚合误差。<span class=\"formula-inline\">$$\\beta$$</span> 则由选择策略决定——注意力打分、熵排序、低秩投影三种策略在同一任务上给出不同的 <span class=\"formula-inline\">$$\\beta$$</span>，<span class=\"formula-inline\">$$\\beta$$</span> 越大说明策略越能挑出高信息 token。</p>\n<p>把某任务标定的 <span class=\"formula-inline\">$$\\beta$$</span> 搬到另一任务做容量规划是典型误用。OCR 的信息高度集中在文字笔画所在 patch，注意力策略能给出很大的 <span class=\"formula-inline\">$$\\beta$$</span>，曲线陡峭；同一策略搬到自然图像 VQA，信息弥散在全局语义，<span class=\"formula-inline\">$$\\beta$$</span> 显著变小，低 <span class=\"formula-inline\">$$r$$</span> 区间的失真上升速度被严重低估。视频理解更极端：帧间冗余使有效信息量随帧数亚线性增长，<span class=\"formula-inline\">$$r$$</span> 的定义本身要从\"每帧保留比例\"改为\"跨帧联合保留比例\"，否则公式里的 <span class=\"formula-inline\">$$N_{\\text{vis}}$$</span> 失去意义。</p>\n<p>工程判断：容量规划必须以任务为单位标定 <span class=\"formula-inline\">$$(\\beta, D_0)$$</span>，且标定点要落在实际部署的 <span class=\"formula-inline\">$$r$$</span> 附近——在 <span class=\"formula-inline\">$$r=0.5$$</span> 处拟合的 <span class=\"formula-inline\">$$\\beta$$</span> 外推到 <span class=\"formula-inline\">$$r=0.1$$</span> 会系统性低估失真。多任务混合部署时，取各任务 <span class=\"formula-inline\">$$\\beta$$</span> 的最小值做保守预算，而不是平均值。显存侧代价随之而来：保守预算意味着更高的 <span class=\"formula-inline\">$$r$$</span>，KV cache 中视觉部分的占用上升，连续批处理能容纳的并发请求数下降，吞吐与 SLO 的权衡点整体右移。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-16\">十六 · 选择策略低效时公式退化为上界而非可达界</h3>\n<p>公式是下界，不是可达界。它回答\"存在某种最优选择时失真至少是多少\"，不回答\"当前策略能做到多少\"。当选择策略低效——比如按位置均匀下采样、按固定步长抽帧、按通道均值裁剪——实际失真可能高出下界数倍，此时公式失去容量决策价值：按它反解出的 <span class=\"formula-inline\">$$r$$</span> 在实测中根本达不到目标失真。</p>\n<p>判别方法很直接：在同一 <span class=\"formula-inline\">$$r$$</span> 下比较实测失真与代入标定参数算出的下界，比值接近 1 说明策略已贴近最优，比值显著大于 1 说明还有策略改进空间，此时正确的动作是换策略而非降 <span class=\"formula-inline\">$$r$$</span>。注意力引导的合并、熵排序、低秩子空间选择都能提升 <span class=\"formula-inline\">$$\\beta$$</span>；在 Blackwell 上，这些策略的额外开销主要落在视觉编码器前段的注意力打分与 TMEM 读写，而非解码侧，因此对解码延迟几乎无影响，只影响预填阶段的吞吐。</p>\n<p>一个具体判断链：若目标是在给定显存预算下维持 VQA 准确率，先测当前策略的实测失真-<span class=\"formula-inline\">$$r$$</span> 曲线，与标定下界比对；若差距大，换注意力合并策略重测，观察 <span class=\"formula-inline\">$$\\beta$$</span> 是否上升；只有当策略已贴近下界、差距小于可接受阈值时，才用公式反解 <span class=\"formula-inline\">$$r$$</span> 做容量规划。跳过前两步直接反解，等于把理论最优当成工程现实。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-17\">十七 · 规模上限：N_vis 增大时界的渐近失效</h3>\n<p>公式对 <span class=\"formula-inline\">$$N_{\\text{vis}}$$</span> 的依赖是隐含的：<span class=\"formula-inline\">$$r=N_{\\text{keep}}/N_{\\text{vis}}$$</span> 把绝对数量归一化掉了，但失真对绝对数量的敏感度并非尺度不变。当 <span class=\"formula-inline\">$$N_{\\text{vis}}$$</span> 很小时（低分辨率图像、短视频片段），保留少数几个 token 就能覆盖主要信息，指数界偏保守；当 <span class=\"formula-inline\">$$N_{\\text{vis}}$$</span> 很大时（高分辨率文档、长视频、多图输入），信息量随面积或时长增长但注意力感受野有限，远端 token 与查询的相关性衰减，选择策略的打分精度下降，<span class=\"formula-inline\">$$\\beta$$</span> 实际随 <span class=\"formula-inline\">$$N_{\\text{vis}}$$</span> 增大而下降。</p>\n<p>这意味着在大规模输入上，公式给出的下界越来越松，按它做的容量规划越来越乐观。更麻烦的是，<span class=\"formula-inline\">$$N_{\\text{vis}}$$</span> 增大直接推高预填阶段的注意力计算量与 KV cache 占用，Blackwell 上的视觉编码器 Roofline 约束开始主导——此时瓶颈从\"选哪些 token\"转移到\"能不能在延迟预算内处理完所有 token\"，率-失真界退居次要。规模上限的工程含义是：当 <span class=\"formula-inline\">$$N_{\\text{vis}}$$</span> 超过某个阈值，压缩策略的首要目标从逼近失真下界变为控制预填时延，两者可能冲突。</p>\n<p>应对方式是把大输入分块后再做率-失真决策：对每个空间块独立标定局部 <span class=\"formula-inline\">$$\\beta$$</span>，块内做信息量引导选择，块间按任务重要性分配保留预算。这避免了全局打分在远端 token 上的精度衰减，代价是块边界处的信息割裂，需要在块间保留少量重叠 token。显存上，分块使峰值中间张量尺寸可控，避免一次性物化全部视觉 token 的注意力矩阵。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-18\">十八 · 失效条件的工程清单与校验动作</h3>\n<p>把上述边界收敛成可执行的校验清单，避免把公式用在它不成立的地方。</p>\n<table class=\"mini\"><thead><tr><th>假设</th><th>失效信号</th><th>校验动作</th><th>系统代价</th></tr></thead><tbody><tr><td>token 信息独立同分布</td><td><span class=\"formula-inline\">$$D(r)$$</span> 曲线出现拐点或阶跃</td><td>测二阶差分，定位拐点 <span class=\"formula-inline\">$$r$$</span></td><td>簇级合并增加 TMEM 读写与 MMA 开销</td></tr><tr><td><span class=\"formula-inline\">$$\\beta$$</span> 跨任务可复用</td><td>换任务后实测失真偏离预测</td><td>按任务在部署 <span class=\"formula-inline\">$$r$$</span> 附近重新标定</td><td>保守预算推高 <span class=\"formula-inline\">$$r$$</span>，KV cache 占用上升、并发下降</td></tr><tr><td>策略贴近下界</td><td>实测/下界比值显著大于 1</td><td>换注意力或熵引导合并后重测 <span class=\"formula-inline\">$$\\beta$$</span></td><td>预填阶段算力上升，解码延迟基本不变</td></tr><tr><td><span class=\"formula-inline\">$$N_{\\text{vis}}$$</span> 尺度不变</td><td>大输入下 <span class=\"formula-inline\">$$\\beta$$</span> 实测下降</td><td>分块标定局部 <span class=\"formula-inline\">$$\\beta$$</span>，块间分配预算</td><td>块边界重叠 token 增加少量显存与带宽</td></tr></tbody></table>\n<p>清单里每一项都对应一次实测，而不是一次推导。公式的价值在于给出比较基准：实测失真与下界的差距告诉你策略还有多少改进空间，实测 <span class=\"formula-inline\">$$\\beta$$</span> 随 <span class=\"formula-inline\">$$N_{\\text{vis}}$$</span> 的漂移告诉你规模是否已越过适用上限。当差距收敛到阈值以内、<span class=\"formula-inline\">$$\\beta$$</span> 稳定时，公式才可以进入容量规划环节；否则它只是一个诊断工具。</p>\n<p>最后落在具体机制上：在 Blackwell 上做视觉 token 压缩的工程闭环，是把率-失真界当作标尺而非答案——先用注意力或熵引导的合并把实测曲线压到贴近下界，再在部署的 <span class=\"formula-inline\">$$r$$</span> 与 <span class=\"formula-inline\">$$N_{\\text{vis}}$$</span> 区间内标定 <span class=\"formula-inline\">$$\\beta$$</span>，最后才用公式反解容量。任何跳过\"实测贴近下界\"这一步、直接拿公式做预算的规划，都会在低 <span class=\"formula-inline\">$$r$$</span> 与大规模输入两处系统性低估失真，而这正是 OCR 与小目标识别最先崩掉的地方。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-19\">十九 · 指数界的适用半径：i.i.d. 假设破裂之后</h3>\n<p>把 $D(r)\\ge D_0 e^{-\\beta r}$ 当作容量规划的依据，前提是 token 的信息量可以按独立同分布排序后做贪心分配——推导里每多保留一个高信息 token，失真下降正比于其信息量，积分才收敛成指数形状。视觉侧恰恰违反这一条：patch token 之间存在强空间相关，相邻 token 携带的是同一块纹理或同一条边缘的冗余描述，信息量排序在局部高度共线。后果是低 $r$ 区间实际曲线比指数界更陡，而不是更平：一旦保留比例压到把某个空间连通域整体裁掉，失真不是线性叠加而是阶跃式跳升，指数界给出的乐观外推在这里系统性偏低。工程含义很直接——用 $\\beta$ 反解 $r$ 得到的显存或延迟预算，在低 $r$ 段必须留出安全余量，不能把界当作可达目标。</p>\n<p>失效的第二个来源是 $D_0$ 与 $\\beta$ 的任务依赖性。OCR 的失真由字符级召回主导，一个被误删的小目标 token 可能让整行文本判错；VQA 的失真由语义证据是否保留主导，冗余背景 token 裁掉几乎无损；视频理解还要叠加时间轴上的相关结构。三者的 $\\beta$ 不在同一量纲上可比，把 OCR 场景标定的 $\\beta$ 搬到视频理解做容量规划，等于假设两者的信息密度分布同形，低 $r$ 区间的失真上升速度会被低估。跨任务复用同一组参数是这套界最常见的误用，正确做法是每个任务形态各自标定 $(D_0,\\beta)$，并把标定点落在实际部署的 $r$ 附近而非高 $r$ 端。</p>\n<p>第三个失效条件是选择策略本身。界描述的是“按信息量贪心排序”能达到的下界，而均匀裁剪、等步长下采样并不执行这个排序，它等价于随机丢弃，高信息 token 被误删的概率与低信息 token 相同。此时实测失真可以远超指数界，OCR 与小目标识别的退化尤其剧烈。判断策略是否低效有一个可操作的校验：给定预算反解 $r$，比较实测失真与 $D_0 e^{-\\beta r}$ 的差距，若差距随 $r$ 下降而扩大，说明选择器没有挑出高信息 token，应换成注意力引导或熵引导的 token 合并，而不是继续调 $r$。这条校验必须在容量决策里显式执行，只按 $r$ 排布 batch 与 KV 预算而不回测失真，会把策略低效误读成已逼近理论最优。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>破裂后的表现</th><th>系统代价落点</th></tr></thead><tbody><tr><td>token 信息 i.i.d.</td><td>低 $r$ 段实际曲线更陡，界偏乐观</td><td>显存预算不足，KV 峰值溢出触发重算</td></tr><tr><td>$\\beta$ 跨任务可迁移</td><td>低 $r$ 失真上升速度被低估</td><td>延迟预算达标但准确率跌破 SLO</td></tr><tr><td>选择器执行信息量排序</td><td>均匀裁剪使实测失真远离下界</td><td>同等 $r$ 下多花算力却换不到精度</td></tr></tbody></table>\n<p>规模上限还有一层与硬件耦合的约束：$r$ 压得越低，单次前向里视觉 token 占用的 MMA 与 TMEM 周期越少，但选择器本身（注意力打分、熵估计、低秩投影）的算力占比随之上升，在 Blackwell 上这部分开销走的是与主算力不同的流水线，压缩收益会被选择开销部分抵消。存在一个 $r$ 的下限，越过它之后端到端延迟不再随 $r$ 下降而改善，此时继续压缩只是把预算从主算力搬到选择器上。容量规划应把这个拐点与失真界的低 $r$ 陡升段一起标在曲线上，两个约束取交集才是可部署的 $r$ 区间。</p>\n<h3 id=\"th-visual-token-rate-distortion-sec-20\">二十 · 把失真界翻译成可解的容量方程</h3>\n<p>推理侧真正要回答的不是“界是多少”，而是“给定预算，r 该取多少”。做法是把界从不等式改写成等式约束，再对它取对数：把 $$D(r)\\ge D_0 e^{-\\beta r}$$ 在容量规划中当作紧约束使用，即令目标失真 $$D_{\\text{target}}$$ 满足 $$D_0 e^{-\\beta r}=D_{\\text{target}}$$，解得</p>\n<div class=\"formula\">$$r^\\star=\\frac{1}{\\beta}\\ln\\frac{D_0}{D_{\\text{target}}}$$</div>\n<p>这一步把“保留多少 token”变成了三个可测量量的函数：零压缩基准失真 $$D_0$$、选择策略效率 $$\\beta$$、SLO 允许的失真上限 $$D_{\\text{target}}$$。注意 $$r^\\star$$ 对 $$\\beta$$ 是反比、对失真比是正比对数——这意味着当 $$\\beta$$ 翻倍时，达到同一失真所需的保留比例减半，视觉 token 数、KV 显存、预填算力同步减半。工程含义很直接：<strong>提升选择策略的 $$\\beta$$ 比调低 r 更安全</strong>，因为前者在同等失真下压缩了预算，后者只是把失真推高。若实测失真明显高于 $$D_0 e^{-\\beta r}$$，说明当前策略的有效 $$\\beta$$ 低于标定值，此时按 $$r^\\star$$ 排出的容量计划是虚的，必须先换选择器（注意力引导、熵排序或低秩合并）再重解方程。</p>\n<p>算例：某 OCR 任务标定 $$D_0=0.02$$（零压缩时 2% 的字符错误率基线），$$\\beta=3.0$$（以保留比例为单位），SLO 要求错误率不超过 5%，即允许失真增量 $$D_{\\text{target}}=0.03$$。代入得 $$r^\\star=\\frac{1}{3}\\ln(0.02/0.03)$$ 为负——说明该 SLO 比零压缩基线还宽松，无需压缩即可满足，压缩预算应全部让给吞吐。若把 SLO 收紧到 2.5%（$$D_{\\text{target}}=0.005$$），则 $$r^\\star=\\frac{1}{3}\\ln 4\\approx 0.46$$，即需保留约 46% 的视觉 token。这个数字直接进入下一节的批大小计算。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-21\">二十一 · 用 r 反解批大小与并行度</h3>\n<p>视觉 token 数进入两个显存项：预填阶段的激活与注意力工作集，以及解码阶段常驻的视觉 KV。设原始视觉 token 数 $$N_{\\text{vis}}$$、每 token 每层 KV 字节数 $$b_{\\text{kv}}$$、层数 $$L$$、每序列文本 KV 字节数 $$K_{\\text{txt}}$$，则单序列视觉 KV 为 $$r N_{\\text{vis}} b_{\\text{kv}} L$$。给定单卡可用于 KV 的显存 $$M_{\\text{kv}}$$，可容纳的并发序列数为</p>\n<div class=\"formula\">$$B_{\\max}=\\left\\lfloor \\frac{M_{\\text{kv}}}{r N_{\\text{vis}} b_{\\text{kv}} L+K_{\\text{txt}}}\\right\\rfloor$$</div>\n<p>把第一节的 $$r^\\star$$ 代入即得“满足 SLO 的最大批”。这里的关键判断是：视觉 KV 与文本 KV 不是同一量级，多图或视频输入下 $$rN_{\\text{vis}}b_{\\text{kv}}L$$ 常主导分母，因此批大小对 r 近似线性敏感——r 从 0.46 降到 0.23，批大小约翻倍。这正是“压缩预算换吞吐”的定量形式，而不是定性口号。</p>\n<p>并行度决策则走另一条路。张量并行（TP）把每层 KV 按头切分，单卡 KV 需求降为 $$1/t_{\\text{tp}}$$，但每 token 的集合通信量上升；专家并行与序列并行对视觉 KV 的切分方式不同，需按框架实际布局核对。工程判据是：当 $$B_{\\max}$$ 在 TP=1 下已低于目标并发，且单卡显存被视觉 KV 占满时，优先降 r 而非加 TP——因为降 r 同时削减预填算力与解码带宽，加 TP 只削显存却增加通信。反之，若 r 已贴近失真界下限（再降会突破 $$D_{\\text{target}}$$），则只能加 TP 或换更长上下文的分块预填。</p>\n<p>算例延续上节：设 $$N_{\\text{vis}}=4096$$、$$b_{\\text{kv}}L$$ 合计每 token 视觉 KV 为固定字节量、$$K_{\\text{txt}}$$ 为文本部分。在 $$r=0.46$$ 时视觉 KV 项约为 $$r=0.23$$ 时的两倍，故同一 $$M_{\\text{kv}}$$ 下批大小减半。若目标并发是 32 而当前只能到 20，把 r 降到 0.35（对应失真略高于 SLO 但仍在容差内）可把批大小拉回 30 以上；若 SLO 不允许，则改 TP=2 并接受每 token 通信开销上升带来的解码延迟增加。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-22\">二十二 · 定 KV 预算：把 r 写进分页与驱逐策略</h3>\n<p>KV 预算不只是“留多少显存”，而是分页粒度与驱逐顺序。视觉 KV 的块大小若按固定 token 数分配，r 的取值必须与块对齐，否则尾部浪费会吃掉压缩收益：有效保留比例变为 $$\\lceil rN_{\\text{vis}}/P\\rceil P/N_{\\text{vis}}$$（$$P$$ 为块 token 数），在 r 较小、$$N_{\\text{vis}}$$ 不大时偏差显著。工程上应让分页器按“视觉块”与“文本块”分池，视觉池按 r 动态扩缩，文本池保持稳定，避免视觉压缩挤占文本 KV 导致长上下文退化。</p>\n<p>驱逐顺序同样受界约束。既然界假设按信息量排序保留，驱逐就应反向执行：先丢信息量最低的 token，而不是按位置 FIFO。注意力分数或熵排序给出的重要性可用于驱逐优先级，使实际失真贴近下界。代价是排序本身要算力——在预填阶段顺带产出重要性分数几乎免费，但在解码阶段重排会引入额外 kernel 与同步，通常只在块级驱逐时做粗排序。</p>\n<p>容量判断：若视觉 KV 占单卡显存的比例超过文本 KV，且 r 已接近 $$r^\\star$$ 下限，则 KV 预算的瓶颈在视觉侧，此时提升 $$\\beta$$（更好的选择器）比扩大显存更划算；反之若文本 KV 主导，压缩视觉 token 对总预算的边际收益递减，应把优化投向文本侧的分页与前缀复用。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-23\">二十三 · 定 SLO：延迟分解里 r 的位置</h3>\n<p>端到端时延可拆为预填、首 token、解码三段，r 主要作用于前两段。预填算力随视觉 token 数线性下降（注意力为二次项但被分块与 Flash 类内核摊平），首 token 延迟近似</p>\n<div class=\"formula\">$$T_{\\text{ttft}}\\approx \\frac{c_{\\text{pre}}\\cdot rN_{\\text{vis}}}{F_{\\text{eff}}}+T_{\\text{fixed}}$$</div>\n<p>其中 $$c_{\\text{pre}}$$ 为每视觉 token 的预填算力系数，$$F_{\\text{eff}}$$ 为有效算力，$$T_{\\text{fixed}}$$ 为与视觉长度无关的固定开销（调度、权重加载、文本前缀）。解码段每步要读视觉 KV，带宽项随 $$rN_{\\text{vis}}b_{\\text{kv}}L$$ 增长，故 r 也压低每 token 解码时间。SLO 若以 TTFT 为主约束，则 r 的可行域由上式反解；若以吞吐（tokens/s per GPU）为主约束，则 r 通过批大小间接起作用，需与第二节的 $$B_{\\max}$$ 联立。</p>\n<p>关键工程判断：当 $$T_{\\text{fixed}}$$ 占 TTFT 的比例较高时，继续降 r 的边际收益迅速衰减——此时压缩视觉 token 对 SLO 帮助有限，应转向调度与权重加载优化。反之若预填项主导，r 是最直接的杠杆。算例：若某配置下预填项占 TTFT 的七成，把 r 从 0.46 降到 0.30 可使预填项降约三分之一，TTFT 总降幅约两成；若固定开销占七成，同样降 r 只带来不足一成的 TTFT 改善，不值得承担失真上升。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-24\">二十四 · 一个联立算例与校验回路</h3>\n<p>把四节串起来：给定 $$D_0$$、$$\\beta$$、$$D_{\\text{target}}$$ 解出 $$r^\\star$$；代入 $$B_{\\max}$$ 得批大小；用 $$T_{\\text{ttft}}$$ 式校验 SLO；若批大小或 TTFT 不达标，按“先提 $$\\beta$$、再降 r 至下限、最后加并行度”的顺序调整。校验回路的核心是<strong>实测失真与界的差距</strong>：若实测失真远高于 $$D_0e^{-\\beta r}$$，说明选择策略低效，此时任何基于该 $$\\beta$$ 的容量计划都不可信，必须先换注意力或熵引导的合并，再重跑整条链路。</p>\n<p>两个必须防的失效模式：其一，用均匀裁剪冒充达到下界——均匀下采样会误删高信息 token，OCR 与小目标识别的失真骤增，远超指数界预测，使按 $$r^\\star$$ 排出的批大小在质量上不成立；其二，把某任务标定的 $$\\beta$$ 搬到另一任务做容量规划——视觉 token 强空间相关使低 r 区间实际曲线比指数界更陡，跨任务复用 $$\\beta$$ 会系统性低估失真上升速度，导致 SLO 在低 r 处被击穿。正确做法是每个任务族单独标定 $$\\beta$$ 与 $$D_0$$，并在低 r 区间留出安全裕度，把 $$r^\\star$$ 向上取整到分页块对齐后的值。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-25\">二十五 · 把率-失真界嵌进容量决策：反解 r、校验 β、锁定 SLO 余量</h3>\n<p>工程上真正要回答的不是“这条界有多漂亮”，而是“给定显存与延迟预算，我该保留多少视觉 token，以及我离这条界还差多远”。做法是把界当作<b>反解器</b>与<b>体检仪</b>两用。反解侧：设单请求视觉 token 的显存与算力代价近似线性于 N_keep，则每请求视觉侧 KV/激活预算 B_vis ≈ N_keep · s（s 为每 token 的字节与 FLOP 折算系数），延迟预算 T_vis 同理正比于 N_keep。给定 B_vis 与 T_vis，可得允许的保留上限 r_max = min(B_vis, T_vis 折算) / (N_vis · s)，再要求 D(r_max) ≤ D_SLO 才算可行。把界代入即得可行性判据：</p>\n<div class=\"formula\">$$r_{\\max}\\ \\ge\\ \\frac{1}{\\beta}\\ln\\!\\frac{D_0}{D_{\\text{SLO}}},\\qquad N_{\\text{keep}}^{\\text{req}}=\\left\\lceil r_{\\max}\\cdot N_{\\text{vis}}\\right\\rceil$$</div>\n<p>这个式子的工程含义很直接：SLO 越严（D_SLO 越小），所需 r 越大，且随 ln(1/D_SLO) 线性增长——失真目标收紧一个数量级，保留比例要多出约 2.3/β。批大小则由 r 反向锁定：单卡可容纳的并发请求数 n_batch ≈ (M_vis − M_fixed) / (N_vis · r · s)，其中 M_fixed 为权重与运行时固定占用。可见批大小对 r 是双曲敏感的：r 减半，批大小近似翻倍，但 D(r) 抬升。容量规划因此不是“先定批再定压缩”，而是沿 (r, n_batch, D) 三元曲面找同时满足吞吐与 SLO 的点。举例：某视频理解服务若把 r 从 0.5 压到 0.25 换取双倍并发，必须验证 D(0.25) 是否仍在 SLO 内；若 β 偏小（选择策略弱），这一步往往直接击穿 SLO，表现为长视频问答准确率断崖。</p>\n<p>体检侧才是这套方法真正的价值所在，也是它最容易失效的地方。<b>β 不是硬件的属性，而是选择策略与任务联合标定的量</b>，它决定了“同样的 r 能换到多少失真下降”。工程判据是：实测失真 D_meas 与界预测 D(r) 的比值 κ = D_meas / D(r) 应作为常规监控指标；κ 接近 1 说明注意力/熵/低秩选择已逼近贪心最优，继续调 r 才有意义；κ 显著大于 1 说明瓶颈在选择策略而非预算，此时正确动作是换用信息量引导的合并（而非均匀下采样），在同等 r 下压低失真，而不是继续加 token。反过来，若 κ < 1，多半是标定的 D_0 或 β 取自别的任务，界已失去约束力——这正是跨任务搬运参数的典型症状。失效条件必须写进决策流程：指数界假设 token 信息独立同分布，而视觉 token 存在强空间相关，实际曲线在低 r 处比指数界更陡，因此低 r 区间的容量反解必须留保守余量，不能拿高 r 段的拟合外推。OCR 与小目标识别对“误删高信息 token”极其敏感，均匀裁剪会把失真推到界之上很远；视频理解则受时间冗余影响，β 的标定口径与单帧 VQA 完全不同。</p>\n<table class=\"mini\"><thead><tr><th>决策量</th><th>由界导出的关系</th><th>主要系统代价</th><th>失效信号</th></tr></thead><tbody><tr><td>批大小 n_batch</td><td>∝ 1/(N_vis·r·s)</td><td>显存与 KV 带宽随并发线性上涨</td><td>r 下调后 κ 骤升</td></tr><tr><td>并行度（TP/DP 切分）</td><td>按 N_keep 峰值定分片</td><td>通信量与 NVLink 占用上升</td><td>分片后 r 被迫再降</td></tr><tr><td>KV/激活预算 B_vis</td><td>r_max ≥ ln(D_0/D_SLO)/β</td><td>占用挤占权重与运行时空间</td><td>β 跨任务复用导致低估失真</td></tr><tr><td>SLO 余量</td><td>D_SLO 收紧 → r 线性增</td><td>吞吐下降、功耗上升</td><td>实测 D 长期高于界</td></tr></tbody></table>\n<p>并行度决策同样受这条界牵制，且代价不在单卡而在通信。视觉 token 峰值 N_vis·r 决定单卡显存下界，进而决定 TP 切分数；切分越细，每层 all-reduce 的通信量越大，NVLink 5 上的带宽占用与尾延迟随之上升。工程上应先用界反解出满足 SLO 的最小 r，再据此定最小可行切分，而不是先按算力切分、再被迫把 r 压到 SLO 之外。功耗侧亦然：r 与批大小共同决定 SM 占用与 tcgen05 MMA 的发射密度，激进压 r 换并发会把系统推到高占用低失真的反面——高占用但失真超标。最终落点是一个工程判断：<b>把 β 与 D_0 当作按任务、按选择策略分别标定的运行时常量，把 κ 当作上线门禁指标，把低 r 区间的空间相关性当作必须留出的保守余量</b>；三者缺一，率-失真界就只是纸面下界，无法支撑批大小、并行度、KV 预算与 SLO 的联合定标。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-26\">二十六 · 率-失真界在容量决策中的反解与校验</h3>\n<p>把 $$D(r)\\ge D_0\\exp(-\\beta r)$$ 用于定批大小、定并行度、定 KV 预算与定 SLO，关键动作是“反解 r、再校验余量”，而不是把 r 当性能旋钮直接扫。给定显存或延迟预算，先算出可承受的视觉 token 数 $$N_{\\text{keep}}$$，得到 $$r=N_{\\text{keep}}/N_{\\text{vis}}$$，再用本任务标定的 $$\\beta$$ 反解允许的失真上限：$$r \\le \\frac{1}{\\beta}\\ln\\frac{D_0}{D_{\\text{target}}}$$。这个式子把“每帧保留多少视觉 token”从经验参数变成由 SLO 失真目标倒推的容量约束；批大小与并行度随之由 $$N_{\\text{keep}}$$ 与 KV 预算共同夹逼，而不是先定 batch 再补压缩。</p>\n<p>边界在于：指数界假设 token 信息独立同分布，而视觉 token 存在强空间相关，低 r 区间的实际曲线比指数界更陡，因此反解出的 r 只是乐观上界，必须留出校验余量。$$D_0$$ 与 $$\\beta$$ 依赖任务，OCR、VQA、视频理解差异大，跨任务不可直接复用同一组参数；把某任务标定的 $$\\beta$$ 搬到另一任务做容量规划，会系统性低估低 r 区间的失真上升速度。工程上的做法是：每个任务族单独标定一组 $$(D_0,\\beta)$$，并在低 r 侧额外做一次实测失真与下界的差距校验。</p>\n<table class=\"mini\"><thead><tr><th>决策项</th><th>反解量</th><th>失效信号</th></tr></thead><tbody><tr><td>批大小</td><td>由 $$N_{\\text{keep}}$$ 与 KV 预算夹逼</td><td>实测失真远高于下界</td></tr><tr><td>并行度</td><td>按 $$N_{\\text{keep}}$$ 切分视觉序列</td><td>低 r 处曲线陡于指数界</td></tr><tr><td>SLO</td><td>由 $$D_{\\text{target}}$$ 反解 r 上限</td><td>跨任务复用 $$\\beta$$</td></tr></tbody></table>\n<p>系统代价落在两处：一是校验开销，实测失真与下界的差距需要额外评测流量，不能只靠离线标定；二是选择策略的算力，注意力或熵引导的 token 合并比均匀下采样贵，但同等 r 下换来的失真更低。若实测失真远高于下界，说明选择策略低效，应换用注意力或熵引导的合并而非均匀裁剪——均匀裁剪会把高信息 token 误删，OCR 与小目标识别的失真骤增，远超指数下界。只按 r 做容量规划而不校验差距，是最隐蔽的误用：策略低效却被误认为已贴近理论最优。</p>\n<h3 id=\"th-visual-token-rate-distortion-sec-27\">二十七 · 把“下界”当成“可达值”：均匀裁剪的隐性代价</h3>\n<p>最常见的误用是把 $$D(r)\\ge D_0\\exp(-\\beta r)$$ 这条不等式读成等式，进而认为只要把保留比例压到某个 r，失真就“应该”落在曲线附近。不等式只说明任何选择策略都不可能优于该下界，它不承诺存在一个廉价策略能达到它。均匀裁剪（等间隔抽帧、等步长下采样 patch、按网格隔行丢弃 token）恰恰是最远离下界的策略：它把压缩预算平均分配给信息量差异极大的 token，高信息 token 与背景 token 获得同等保留概率。</p>\n<p>机制上可以这样看：设第 i 个 token 的信息量为 $$I_i$$，贪心选择按 $$I_i$$ 降序保留，则第 k 个被保留 token 的边际失真下降正比于 $$I_{(k)}$$，积分给出指数型下界；均匀裁剪的保留集合是随机子集，其边际收益正比于全体 token 的平均信息量 $$\\bar I$$，而非排序后的上分位。二者差距由信息量分布的偏度决定——OCR 场景中文字笔画 token 的信息量远高于页边空白，偏度极大，均匀裁剪的实际失真因此显著高于下界，且随 r 下降而扩大。</p>\n<p>系统代价落在端到端延迟与有效吞吐上：视觉编码器与预填阶段的 FLOPs 与 KV 写入量随 $$N_{\\text{keep}}$$ 线性下降，均匀裁剪确实省下了这部分成本；但被误删的文字或小目标 token 无法在解码阶段被“补回来”，模型只能给出错误答案，重试、重排或回退到更高分辨率重跑的概率上升，把省下的预填时间又还了回去。工程上识别这类误用的方法很直接：在同一 r 下对比均匀裁剪与注意力/熵引导选择的实测失真，若前者明显偏离后者且差距随 r 单调扩大，说明预算分配机制而非预算总量是瓶颈。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-28\">二十八 · 跨任务搬运 β：低 r 区间的失真被系统性低估</h3>\n<p>第二个高频误用是把在一个任务上标定出的 $$\\beta$$ 直接搬去做另一个任务的容量规划。$$\\beta$$ 不是硬件的属性，也不是编码器的属性，它由选择策略与 token 信息分布共同决定；而视觉 token 存在强空间相关，指数界的独立同分布假设在低 r 处失效，实际曲线比指数界更陡。用高 r 区间拟合出的 $$\\beta$$ 外推到低 r，等于用一条平缓的直线去预测一段加速下坠的曲线。</p>\n<p>伪代码式的误用路径是：在 VQA 上以 r=0.5、0.6、0.7 三点拟合 $$\\beta$$，得到一条看似温和的衰减曲线，然后据此反解“r=0.2 时失真仍可接受”，把压缩预算压到 20%。问题在于 VQA 的答案往往由少量显著区域决定，空间相关性使冗余 token 极多，高 r 区间曲线平缓；而 OCR 的失真由字符级细节决定，一旦 r 低于某个阈值，整行文字被删，失真呈阶跃式上升，指数形式根本拟合不住。视频理解又是另一种形态：时间轴上的相邻帧高度相关，均匀抽帧在低 r 处丢失的是动作的关键相位而非冗余帧。</p>\n<p>后果体现在容量规划上：按低估的失真反解出的 r 被写进部署配置，服务在正常负载下勉强达标，一旦输入分辨率上升或文档类请求占比升高，失真骤增而调度层没有任何预警信号——因为规划阶段从未校验过“实测失真与下界的差距”。识别方法是做任务分层的标定：对每个任务族单独拟合 $$\\beta$$，并强制在目标 r 附近而非高 r 区间采样；若某任务在低 r 处实测曲线斜率明显大于拟合值，说明空间相关已使指数界失效，应改用分段或饱和型模型做预算反解。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-29\">二十九 · 只看 r 不看差距：选择策略低效却被当成已逼近最优</h3>\n<p>第三类误用更隐蔽：容量决策流程只记录 r 与端到端指标，从不计算实测失真与同 r 下界的差值。于是当选择策略低效时，团队看到的是“r 已经压得很低、显存和预填延迟都达标”，却看不到失真本可以更低。下界的作用不是给出目标值，而是给出诊断量：$$\\Delta(r)=D_{\\text{实测}}(r)-D_0\\exp(-\\beta r)$$ 衡量选择策略的余量，$$\\Delta$$ 大意味着预算花错了地方，而不是预算不够。</p>\n<p>机制上，注意力引导的选择用视觉编码器最后一层的跨模态注意力分数排序，熵引导的选择用 token 特征分布的熵排序，低秩方法则在投影空间里保留主成分方向对应的 token。三者都在做同一件事：提高有效 $$\\beta$$。均匀下采样不改变 $$\\beta$$ 的量级，只是等比缩小 $$N_{\\text{keep}}$$，因此它的实测点始终平行于下界上方一段距离；而注意力引导能把这段距离压窄。工程判断因此变成：在固定 r 下比较不同选择策略的 $$\\Delta$$，若换策略后 $$\\Delta$$ 显著收窄而延迟几乎不变，说明瓶颈在排序质量而非预算规模。</p>\n<p>系统代价上，注意力引导的选择需要额外的打分与排序开销，通常在视觉编码器输出后、预填之前插入一个轻量打分核；这部分开销与省下的 KV 写入和预填 FLOPs 相比是否划算，取决于 r 与序列长度。识别误用的信号是：压缩率提升带来的吞吐收益已经饱和，但失真仍随 r 单调恶化且 $$\\Delta$$ 不收敛——此时继续压 r 是错的方向，应转而更换选择策略。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-30\">三十 · 一个反例：文档 OCR 流水线的“最优压缩”</h3>\n<p>设一条文档 OCR 推理流水线，输入为高分辨率扫描页，视觉 token 数 $$N_{\\text{vis}}$$ 很大，预填阶段是延迟主项。团队按容量决策流程反解出 r=0.25 可满足 SLO，采用等步长网格下采样实现，上线后显存与预填延迟均达标。随后财务票据类请求占比上升，字符识别错误率骤增，而监控面板上 r 与延迟曲线毫无变化。</p>\n<p>用本部分的框架复盘：该流水线犯了三个叠加的误用。其一，把 r=0.25 当作“达到下界”的配置，实际均匀下采样使实测失真远高于同 r 下界，$$\\Delta$$ 从未被测量。其二，$$\\beta$$ 是在通用 VQA 数据上标定的，搬到 OCR 上后低 r 区间的失真上升速度被低估，规划阶段的失真预测本身就不成立。其三，网格下采样对文字行是结构性破坏：等步长丢弃会整段删掉笔画 token，而票据的关键字段恰恰是稀疏分布的小目标，空间相关性在这里表现为“整行同生共死”，指数界的平滑衰减假设彻底失效。</p>\n<p>修正路径不是继续调 r，而是换选择机制：用跨模态注意力或字符区域熵引导保留，把预算集中到文字笔画与小目标区域，在同等 r 下把 $$\\Delta$$ 压下来；同时对 OCR 任务族单独标定 $$\\beta$$，并在目标 r 附近采样校验。若换策略后同 r 下失真明显下降，说明原配置的问题从来不是压缩率太高，而是压缩预算分配错了位置。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>机制根源</th><th>可观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>均匀裁剪当下界</td><td>保留集合为随机子集，边际收益取平均信息量</td><td>同 r 下失真显著高于注意力引导选择，差距随 r 扩大</td><td>预填省下的时间被重试与回退吃掉</td></tr><tr><td>跨任务搬运 β</td><td>空间相关使低 r 处曲线更陡，指数界失效</td><td>目标 r 附近实测斜率大于拟合斜率</td><td>容量配置在负载结构变化时失真骤增且无预警</td></tr><tr><td>只看 r 不算 Δ</td><td>选择策略低效未进入决策回路</td><td>吞吐收益饱和但 Δ 不收敛</td><td>额外打分开销无法被压缩收益抵消</td></tr></tbody></table>\n<p>识别这三类误用的共同工程动作，是在压缩配置里强制携带两个字段：标定该 $$\\beta$$ 的任务族标识，以及目标 r 附近实测失真与下界的差值 $$\\Delta$$。缺任一个字段的配置，都不应被当作容量规划的输入。</p>\n\n<h3 id=\"th-visual-token-rate-distortion-sec-31\">三十一 · 误用与反例：当“贴近下界”被读成“均匀裁剪即最优”</h3>\n<p>最常见的误用不是公式写错，而是把 $$D(r)\\ge D_0\\cdot\\exp(-\\beta r)$$ 当成一条“只要把 r 压到某个值就能拿到对应失真”的查表曲线。这条不等式只给出下界，且下界成立的前提是 token 选择按信息量排序做贪心分配——每多保留一个高信息 token，失真下降与其信息量成正比，积分后才得到指数衰减。均匀裁剪（等步长下采样、固定网格丢 token）并不执行这个排序，它等价于把 β 强行压到接近零：保留的 token 里混入大量低信息冗余，同时把高信息 token 按位置而非按重要性删掉。此时实测失真会显著高于同 r 下的下界，而容量规划者看到 r 达标就以为预算已花在刀刃上。识别方法很直接：在同一 r 上对比“均匀裁剪”与“注意力/熵引导选择”的实测失真，若前者明显偏离下界而后者贴近，说明瓶颈在选择策略而非 r 本身。</p>\n<p>第二个误用是跨任务搬运 β。β 由选择策略决定，但 $$D_0$$ 与 β 同时依赖任务：OCR 的失真对字符级 token 的误删极其敏感，小目标识别依赖少数高分辨率局部 token，视频理解则受时序冗余与跨帧相关影响，三者的曲线形状不同。把在 VQA 上标定的 β 直接用于 OCR 的压缩预算，会系统性低估低 r 区间的失真上升速度——因为指数界假设 token 信息独立同分布，而视觉 token 存在强空间相关，实际曲线在低 r 处比指数界更陡。工程上的判别信号是：当 r 继续下降时，实测失真出现“拐点式”跳变而非平滑指数下滑，就说明该任务的真实曲线已脱离标定参数所描述的区间，继续按原 β 反解 r 会给出过于乐观的容量结论。</p>\n<p>第三个误用是只按 r 做容量规划而不校验“实测失真与下界的差距”。给定延迟或显存预算反解所需 r 只是第一步；第二步必须用 β 判断当前选择策略离下界还有多少余量。若实测失真远高于下界，说明选择策略低效，应换用注意力或熵引导的合并而非均匀下采样，在同等 r 下换取更低失真。这里的系统代价是双向的：提高选择精度（如逐层注意力打分、token 合并）会增加预填阶段的算力与带宽开销，而降低 r 又直接压缩 KV cache 与视觉编码器的显存占用、提升解码吞吐。反例：某 OCR 流水线为压显存把 r 降到很低并采用均匀网格裁剪，显存与吞吐指标达标，但字符级答案准确率骤降，且实测失真远高于按标定 β 反解出的预期值——根因不是 r 太小，而是高信息 token 被误删、β 实际远低于标定值。正确做法是保留注意力峰值处的文本区域 token、对其余区域做合并，用略高的选择开销换取失真贴近下界。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>识别信号</th><th>系统后果</th></tr></thead><tbody><tr><td>均匀裁剪当作达界</td><td>同 r 下失真明显高于引导选择</td><td>显存/吞吐达标但任务精度不达标</td></tr><tr><td>跨任务搬 β</td><td>低 r 处失真拐点式跳变</td><td>容量规划过于乐观，SLO 失守</td></tr><tr><td>只看 r 不校验差距</td><td>实测失真长期悬在下界之上</td><td>选择策略低效被误判为已接近最优</td></tr></tbody></table>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>r</td><td>保留 token 比例</td></tr><tr><td>N_{\\text{keep}},\\ N_{\\text{vis}}</td><td>保留与原始视觉 token 数</td></tr><tr><td>D(r)</td><td>任务失真（如答案准确率下降或重建误差）</td></tr><tr><td>\\beta</td><td>压缩效率系数，由选择策略（注意力/熵/低秩）决定</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-visual-token-rate-distortion · 共 5 个片段</p>\n"},{"id":"th-multimodal-kv-cache","title":"多模态 KV cache 显存式","direction":"dir-vision-encoder-latency","prereq":[],"plain":"多模态请求的 KV cache 显存等于视觉 token 与文本 token 之和乘以每 token 每层 KV 字节数，视觉 token 因分辨率放大常成为显存主项，直接决定并发批大小上限。","definition":"多模态请求的 KV cache 显存等于视觉 token 与文本 token 之和乘以每 token 每层 KV 字节数，视觉 token 因分辨率放大常成为显存主项，直接决定并发批大小上限。","formula":"$$M_{\\mathrm{KV}} \\;=\\; 2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,\\bigl(N_{\\mathrm{vis}} + N_{\\mathrm{txt}}\\bigr)\\,\\cdot\\, B_{\\mathrm{conc}}$$","variables":[{"sym":"\\ell","meaning":"LLM 解码器层数"},{"sym":"d_{\\mathrm{kv}}","meaning":"每层 KV 头维度总和（num_kv_heads × head_dim）"},{"sym":"b","meaning":"每元素字节数（FP16 为 2，INT8 为 1）"},{"sym":"N_{\\mathrm{vis}}","meaning":"每请求视觉 token 数"},{"sym":"N_{\\mathrm{txt}}","meaning":"每请求文本 token 数"},{"sym":"B_{\\mathrm{conc}}","meaning":"并发批大小"}],"derivation":"推导关键一步：把单请求 KV 字节数按层展开为 $2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})$，再乘以并发批大小 $B_{\\mathrm{conc}}$，得到稳态显存占用；视觉 token 数随分辨率平方增长，故高分辨率图像请求的 $N_{\\mathrm{vis}}$ 常压过 $N_{\\mathrm{txt}}$ 成为主项。","example":"用途：在容量决策中，给定 HBM 容量减去权重与激活后的余量，可直接反解 $B_{\\mathrm{conc}} = M_{\\mathrm{avail}} / (2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}}))$，据此设定多模态服务的最大并发批与准入控制阈值。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["假设 KV 以 FP16/BF16 存储且无分页碎片；若采用 PagedAttention 分页或 INT8 KV 量化，b 与有效占用率需替换为实测值","视觉 token 在 prefill 后可被剪枝/合并，若推理中动态压缩视觉 KV，则 N_vis 应取压缩后稳态值而非输入值","未计入视觉编码器激活与跨模态注意力的临时缓冲，显存峰值可能高于该稳态式"],"system_note":"常见误用：直接用输入图像切出的视觉 token 数代入 $N_{\\mathrm{vis}}$ 而不计推理中剪枝/合并后的稳态值，会高估显存、低估可并发数；反之忽略视觉编码器激活与跨模态注意力临时缓冲，显存峰值会高于该稳态式并触发 OOM。","papers":["paper-an-image-is-worth-16x16-words-transf-2020"],"facts":["直觉：多模态请求的 KV cache 显存等于视觉 token 与文本 token 之和乘以每 token 每层 KV 字节数，视觉 token 因分辨率放大常成为显存主项，直接决定并发批大小上限。","公式 $$M_{\\mathrm{KV}} = 2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}} + N_{\\mathrm{txt}})\\,\\cdot\\, B_{\\mathrm{conc}}$$ 中，系数 2 对应 K 与 V 两份缓存，$\\ell$ 为解码器层数，$d_{\\mathrm{kv}}$ 为每层 KV 头维度总和（num_kv_heads × head_dim），$b$ 为每元素字节数（FP16 为 2，INT8 为 1），$N_{\\mathrm{vis}}$ 与 $N_{\\mathrm{txt}}$ 为每请求视觉与文本 token 数，$B_{\\mathrm{conc}}$ 为并发批大小。","推导关键一步：把单请求 KV 字节数按层展开为 $2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})$，再乘以并发批大小 $B_{\\mathrm{conc}}$，得到稳态显存占用；视觉 token 数随分辨率平方增长，故高分辨率图像请求的 $N_{\\mathrm{vis}}$ 常压过 $N_{\\mathrm{txt}}$ 成为主项。","适用边界：假设 KV 以 FP16/BF16 存储且无分页碎片；若采用 PagedAttention 分页或 INT8 KV 量化，$b$ 与有效占用率需替换为实测值；视觉 token 在 prefill 后可被剪枝/合并，若推理中动态压缩视觉 KV，则 $N_{\\mathrm{vis}}$ 应取压缩后稳态值而非输入值。","用途：在容量决策中，给定 HBM 容量减去权重与激活后的余量，可直接反解 $B_{\\mathrm{conc}} = M_{\\mathrm{avail}} / (2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}}))$，据此设定多模态服务的最大并发批与准入控制阈值。","常见误用：直接用输入图像切出的视觉 token 数代入 $N_{\\mathrm{vis}}$ 而不计推理中剪枝/合并后的稳态值，会高估显存、低估可并发数；反之忽略视觉编码器激活与跨模态注意力临时缓冲，显存峰值会高于该稳态式并触发 OOM。"],"anchors":["FP16 为 2","INT8 为 1"],"pitfalls":["把输入阶段视觉 token 数当作稳态 $N_{\\mathrm{vis}}$ 代入公式，忽略推理中动态压缩，导致并发上限被低估、GPU 利用率不足。","只按稳态式分配显存而不预留视觉编码器激活与跨模态注意力临时缓冲，长分辨率请求下峰值显存超出预算触发 OOM。","在启用 PagedAttention 或 INT8 KV 量化后仍沿用 $b=2$ 与理想占用率，实际分页碎片与量化开销使可用并发低于计算值。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-1\">一 · 一句话直觉与它的物理来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-2\">二 · 严格定义：什么叫“多模态 KV cache 显存式”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-3\">三 · 为什么需要这条式子：三个工程决策都挂在它上面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-4\">四 · 常见误解：三类系统性错算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-5\">五 · 适用边界与它的“失效条件”清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-6\">六 · 稳态式之外：多模态 KV 显存式的适用边界与两类失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-7\">七 · 逐项拆解：系数 2 与 \\(\\ell\\) 的乘法次序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-8\">八 · 推导关键步：从单请求到稳态占用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-9\">九 · 离散化与近似：分辨率平方增长如何进入公式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-10\">十 · 失效条件的数学形态：分页、压缩与峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-11\">十一 · 反解式的工程用法与误用对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-12\">十二 · 稳态式的三处失真：压缩、分页与峰值缓冲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-13\">十三 · 稳态式成立的三条隐含假设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-14\">十四 · 分页与量化的联合侵蚀</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-15\">十五 · 动态视觉压缩让 $N_{\\mathrm{vis}}$ 变成时变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-16\">十六 · 未计入的临时缓冲与峰值失守</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-17\">十七 · 规模上限：公式在什么量级上先崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-18\">十八 · 边界不在公式里，在公式没写的那几项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-19\">十九 · 从显存余量反解并发上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-20\">二十 · 用 SLO 反推批大小与并行度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-21\">二十一 · KV 预算的分档与准入阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-22\">二十二 · 算例：一个高分辨率请求档的容量推演</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-23\">二十三 · 把公式接进调度器与容量看板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-24\">二十四 · 反解批大小的三个修正项：压缩稳态、分页碎片与峰值缓冲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-25\">二十五 · 误用一：把输入侧视觉 token 数当作稳态 \\(N_{\\mathrm{vis}}\\)</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-26\">二十六 · 误用二：只按稳态式分配，不留峰值缓冲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-27\">二十七 · 误用三：分页与量化后仍沿用理想参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-28\">二十八 · 一个反例：按输入 token 数做容量规划的全链路失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-kv-cache-sec-29\">二十九 · 误用与反例：稳态式当输入式、峰值当均值</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:492px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 491.9 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"409.9\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"409.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：多模态请求的 KV cache 显存等于视觉 token 与文本 …</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"409.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$M_{\\mathrm{KV}} \\;=\\; 2\\,\\ell\\,…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"409.9\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：假设 KV 以 FP16/BF16 存储且无分页碎片；若采用 Pa…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-multimodal-kv-cache-sec-1\">一 · 一句话直觉与它的物理来源</h3>\n<p>多模态请求的 KV cache 显存，等于视觉 token 与文本 token 之和乘以每 token 每层 KV 字节数；视觉 token 因分辨率放大常成为主项，直接决定并发批大小上限。这句话不是比喻，而是把 HBM 里真实驻留的字节数按层摊开后的结果：解码器每一层都要为每个已见 token 保留一份 K 和一份 V，视觉 token 一旦进入 LLM 的上下文，就和文本 token 一样逐层占位，且不会因为“它来自图像”而变小。</p>\n<p>把它写成稳态式就是本卷反复引用的那条：</p>\n<div class=\"formula\">$$M_{\\mathrm{KV}} \\;=\\; 2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,\\bigl(N_{\\mathrm{vis}} + N_{\\mathrm{txt}}\\bigr)\\,\\cdot\\, B_{\\mathrm{conc}}$$</div>\n<p>系数 2 对应 K 与 V 两份缓存，$\\ell$ 是解码器层数，$d_{\\mathrm{kv}}$ 是每层 KV 头维度总和（num_kv_heads × head_dim），$b$ 是每元素字节数，$N_{\\mathrm{vis}}$、$N_{\\mathrm{txt}}$ 是每请求的视觉与文本 token 数，$B_{\\mathrm{conc}}$ 是并发批大小。推导只有一步值得强调：先把单请求字节数按层展开为 $2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})$，再乘并发批大小，得到的是“稳态”——所有在飞请求都已 prefill 完、KV 已全部落盘时的占用。视觉 token 数随分辨率平方增长，所以一张高分辨率图切出的 $N_{\\mathrm{vis}}$ 经常压过整段提示词的 $N_{\\mathrm{txt}}$，这就是“视觉成为主项”的算术来源，而不是经验之谈。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-2\">二 · 严格定义：什么叫“多模态 KV cache 显存式”</h3>\n<p>严格地说，这个式子定义的是一个**容量约束**，不是性能模型。它回答的问题是：给定 HBM 中扣除权重、运行时激活与框架保留区之后的余量 $M_{\\mathrm{avail}}$，最多能同时容纳多少个“已 prefill、正在解码”的请求。反解即得准入控制的硬阈值：</p>\n<div class=\"formula\">$$B_{\\mathrm{conc}} \\;=\\; \\frac{M_{\\mathrm{avail}}}{2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})}$$</div>\n<p>注意三个定义上的取舍。其一，$N_{\\mathrm{vis}}$ 与 $N_{\\mathrm{txt}}$ 是**每请求**的量，不是全局量；不同请求的图像分辨率不同，所以真实系统里 $B_{\\mathrm{conc}}$ 不是一个标量，而是一个按请求向量求和的背包约束——调度器每接收一个请求，就要从余量里扣掉它那一份。其二，$d_{\\mathrm{kv}}$ 是 KV 头维度总和而非注意力头总数，GQA/MQA 下它远小于 $d_{\\mathrm{model}}$，这正是多模态长上下文能落地的前提之一。其三，式子的量纲是字节，与延迟、带宽无关；它只告诉你“装不装得下”，不告诉你“跑得多快”。把容量式误当性能式，是工程上最常见的越界使用。</p>\n<p>代价侧的直接推论：在固定 $M_{\\mathrm{avail}}$ 下，$N_{\\mathrm{vis}}$ 翻倍意味着 $B_{\\mathrm{conc}}$ 近似减半，而解码阶段的吞吐几乎正比于并发批大小，于是显存主项直接转化为吞吐上限。反过来，若把 $b$ 从 FP16 的 2 降到 INT8 的 1，同一块 HBM 能容纳的并发请求数翻倍——这是 KV 量化在多模态场景里比纯文本场景更诱人的原因：主项被压缩，收益被放大。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-3\">三 · 为什么需要这条式子：三个工程决策都挂在它上面</h3>\n<p>第一是**准入控制**。多模态服务的请求分辨率分布极宽，同一时刻可能混着 336×336 的小图与长边数千像素的文档扫描件。没有这条式子，调度器只能用平均 token 数估算，结果是高分辨率请求集中到达时集体 OOM，或者为防 OOM 把并发压到极低、GPU 空转。按请求逐个扣减余量，才能把“装得下”变成可判定的准入条件。</p>\n<p>第二是**批大小与 SLO 的耦合**。连续批处理下，$B_{\\mathrm{conc}}$ 既是显存约束的解，也是时延约束的输入；前者由本式给出上界，后者由批调度时延模型给出下界，两者夹出的可行区间才是可运营的批大小。视觉 token 主项化会把上界压得很低，于是多模态服务常常先撞显存墙、再撞时延墙——这个顺序决定了优化该往哪边走。</p>\n<p>第三是**容量规划的反解**。采购或切分 GPU 时，给定模型权重占用，余量除以单请求 KV 字节数就得到“每卡可支撑的并发请求数”，再乘以每请求的 token 吞吐，就是粗粒度的服务容量。视觉分辨率是这里最敏感的输入：分辨率平方增长意味着容量对图像尺寸的弹性远大于对文本长度的弹性。一个具体例子：同一台机器上，纯文本请求每请求 $N_{\\mathrm{txt}}$ 数千 token，而一张高分辨率图切出的 $N_{\\mathrm{vis}}$ 可达同等量级甚至更多，于是“多模态请求更吃显存”不是模型更大，而是单请求的 token 账本里多了一笔按面积计费的账。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-4\">四 · 常见误解：三类系统性错算</h3>\n<p><strong>误解一：拿输入阶段的视觉 token 数当稳态 $N_{\\mathrm{vis}}$。</strong>视觉 token 在 prefill 之后可以被剪枝或合并，若推理中动态压缩视觉 KV，稳态占用远低于输入值。直接用切图数代入会高估显存、低估可并发数，结果是并发上限被人为压低、GPU 利用率不足。正确做法是取压缩后的稳态值，并且注意压缩发生在 prefill 之后，峰值仍可能短暂触及输入值。</p>\n<p><strong>误解二：只按稳态式分配，不预留临时缓冲。</strong>式子未计入视觉编码器激活与跨模态注意力的临时缓冲。视觉编码器在处理高分辨率输入时自身的激活量可观，跨模态注意力在拼接视觉与文本序列时也会短暂放大工作集。只按稳态式卡满显存，长分辨率请求下峰值会超出预算并触发 OOM。工程判断是：稳态式给出的是地板，预算必须在地板之上留出与最大分辨率成正比的余量。</p>\n<p><strong>误解三：启用分页或量化后仍沿用 $b=2$ 与理想占用率。</strong>PagedAttention 分页会带来块内碎片与块表开销，INT8 KV 量化除 $b$ 变为 1 外还有缩放因子与分组粒度的额外字节。此时 $b$ 与有效占用率都必须替换为实测值，否则算出的 $B_{\\mathrm{conc}}$ 系统性偏高，实际可用并发低于计算值，表现为“按公式排了批却仍然 OOM”。这条误用的危害在于它发生在优化之后——恰恰是最容易放松核算的时刻。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>偏差方向</th><th>工程后果</th></tr></thead><tbody><tr><td>输入 token 数当稳态 $N_{\\mathrm{vis}}$</td><td>高估显存</td><td>并发上限被低估，利用率不足</td></tr><tr><td>不预留编码器/跨模态缓冲</td><td>低估峰值</td><td>长分辨率请求下 OOM</td></tr><tr><td>分页/量化后沿用 $b=2$</td><td>高估可用并发</td><td>按公式排批仍 OOM</td></tr></tbody></table>\n\n<h3 id=\"th-multimodal-kv-cache-sec-5\">五 · 适用边界与它的“失效条件”清单</h3>\n<p>这条式子的适用边界必须和式子一起交付，否则它会被当成万能公式。前提是 KV 以 FP16/BF16 存储且无分页碎片；一旦引入 PagedAttention 或 INT8 KV 量化，$b$ 与有效占用率需替换为实测值。视觉 token 在 prefill 后可被剪枝/合并，若推理中动态压缩视觉 KV，$N_{\\mathrm{vis}}$ 应取压缩后稳态值而非输入值。式子未计入视觉编码器激活与跨模态注意力的临时缓冲，显存峰值可能高于该稳态式。这三条不是脚注，而是使用前必须核对的清单。</p>\n<p>还有一个隐含边界值得点明：式子假设所有在飞请求都处于解码态。真实系统里 prefill 与解码混跑，prefill 中的请求尚未产生完整 KV，但视觉编码器激活正处高位，两类占用在时间上错峰、在空间上叠加。因此容量决策要按“稳态 KV + 峰值临时缓冲”两段核算，而不是单一数字。这也解释了为什么分离式预填/解码在多模态场景里格外有价值——把编码器激活与 KV 稳态拆到不同资源池，两个账本就不再互相挤压。</p>\n<p>最后落在机制上：任何一次多模态容量核算，第一步都应是按请求列出 $(N_{\\mathrm{vis}}, N_{\\mathrm{txt}})$ 并确认 $N_{\\mathrm{vis}}$ 是输入值还是压缩后稳态值，第二步确认 $b$ 与占用率是否已被分页或量化改写，第三步在稳态和之上叠加与最大分辨率成正比的临时缓冲。三步缺一，$B_{\\mathrm{conc}}$ 就只是一个纸面数字。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-6\">六 · 稳态式之外：多模态 KV 显存式的适用边界与两类失效</h3>\n<p>这个式子之所以好用，恰恰因为它是一个<strong>稳态式</strong>：它描述的是所有请求都已完成 prefill、进入自回归解码、KV 不再增长的那个时刻的显存占用。工程上真正危险的从来不是这个式子算错，而是把它当成一个全时段成立的等式。它成立需要三个前提同时为真：KV 以 FP16/BF16 稠密存储、视觉 token 数在解码期间保持不变、且只统计 KV 本身而不含任何临时缓冲。任何一个前提被打破，式子给出的 $B_{\\mathrm{conc}}$ 就不再是准入控制的正确阈值——注意方向，多数情况下不是高估而是低估可用并发，或者反过来在峰值处直接撞上 OOM。区分这两种偏差的方向，比记住公式本身更重要。</p>\n<p>第一个失效条件是<strong>视觉 token 的稳态值不等于输入值</strong>。高分辨率图像经切块与投影后，$N_{\\mathrm{vis}}$ 随分辨率平方增长，轻易压过 $N_{\\mathrm{txt}}$ 成为主项；但不少多模态推理栈会在 prefill 之后对视觉 KV 做剪枝或跨层合并，把冗余的视觉位置压掉。此时若仍用输入阶段切出的视觉 token 数代入，式子会系统性高估单请求占用，反解出的并发上限偏低，GPU 被白白闲置——这是利用率问题而非稳定性问题，因此往往不会被监控发现，只会表现为“这台机器明明显存还有余量却不肯多接一个请求”。正确做法是取压缩后的稳态 $N_{\\mathrm{vis}}$，并且要意识到这个值依赖于压缩策略的触发条件（分辨率阈值、层选择），不同分辨率档位对应不同的有效值，容量规划必须按档位分别反解，而不是取一个全局平均。</p>\n<p>第二个失效条件方向相反：<strong>峰值高于稳态</strong>。式子只计 KV，不计视觉编码器（ViT 类主干）在前向中的激活，也不计跨模态注意力在拼接视觉与文本序列时产生的临时缓冲。这些缓冲的生命周期短，但幅值不小，且与分辨率强相关；当一批请求同时处于 prefill 阶段、而另一批已在解码时，稳态 KV 与瞬时激活叠加，峰值可能越过预算。工程上的处理不是把式子改复杂，而是在 $M_{\\mathrm{avail}}$ 里显式扣掉一块“峰值准备金”，其大小按最长分辨率档位的实测激活峰值设定，再拿剩余部分反解 $B_{\\mathrm{conc}}$。这意味着准入控制要区分 prefill 与 decode 两种资源画像，而不是用一个批大小上限通吃。</p>\n<p>第三个失效条件是<strong>存储格式与占用率的替换</strong>。启用 PagedAttention 后，$b$ 仍是每元素字节数（FP16 为 2、INT8 为 1），但“有效占用率”不再是 1：分页带来块内尾部浪费与碎片，量化则引入 scale/zero-point 的额外开销与可能的按组对齐填充。此时若沿用 $b=2$ 加理想占用率，算出的并发会高于实际可达值，表现为调度器认为还能塞下请求、实际却在分配 KV 块时失败。可操作的判据是把式子改写成带有效系数的形式：</p>\n<div class=\"formula\">$$B_{\\mathrm{conc}}^{\\mathrm{eff}} \\;=\\; \\left\\lfloor \\frac{M_{\\mathrm{avail}} - M_{\\mathrm{peak}}}{\\bigl(2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}^{\\mathrm{steady}} + N_{\\mathrm{txt}})\\bigr)\\big/\\eta} \\right\\rfloor$$</div>\n<p>其中 $\\eta$ 是分页与量化的实测有效占用率，$M_{\\mathrm{peak}}$ 是视觉编码器激活与跨模态临时缓冲的准备金，$N_{\\mathrm{vis}}^{\\mathrm{steady}}$ 是压缩后的稳态视觉 token 数。三个量都必须来自实测而非默认值：$\\eta$ 随块大小与序列长度分布变化，$M_{\\mathrm{peak}}$ 随分辨率档位变化，$N_{\\mathrm{vis}}^{\\mathrm{steady}}$ 随压缩策略变化。举个具体的工程场景：一个服务同时接收低分辨率截图与高分辨率文档扫描件，前者的 $N_{\\mathrm{vis}}$ 远小于 $N_{\\mathrm{txt}}$，后者相反；若用单一平均 $N_{\\mathrm{vis}}$ 做容量规划，低分辨率请求会被过度限制、高分辨率请求会在峰值处触发 OOM。可行做法是按分辨率分桶、每桶独立反解 $B_{\\mathrm{conc}}$ 并在准入层做桶间配额，把“一个全局批大小”换成“一组带准备金的分桶阈值”。</p>\n<table class=\"mini\"><thead><tr><th>前提</th><th>被打破时的偏差方向</th><th>工程处置</th></tr></thead><tbody><tr><td>视觉 token 解码期不变</td><td>高估占用、低估并发（利用率损失）</td><td>取压缩后稳态 $N_{\\mathrm{vis}}$，按分辨率档位分桶</td></tr><tr><td>只计 KV 不计临时缓冲</td><td>低估峰值、OOM</td><td>从 $M_{\\mathrm{avail}}$ 扣 $M_{\\mathrm{peak}}$ 准备金</td></tr><tr><td>稠密存储、占用率 1</td><td>高估可达并发、分配失败</td><td>以实测 $\\eta$ 替换理想占用率</td></tr></tbody></table>\n<p>把这张表读成一句话：式子的价值不在于给出一个数，而在于它把多模态显存问题拆成了四个可独立测量的量——$\\ell$ 与 $d_{\\mathrm{kv}}$ 由模型结构固定，$b$ 由精度策略固定，真正需要工程判断的是 $N_{\\mathrm{vis}}$ 的稳态取值、$\\eta$ 的实测值以及 $M_{\\mathrm{peak}}$ 的准备金大小。这三者中任何一个用默认值糊过去，反解出的并发上限就只是一个纸面数字。</p>\n<h3 id=\"th-multimodal-kv-cache-sec-7\">七 · 逐项拆解：系数 2 与 \\(\\ell\\) 的乘法次序</h3>\n<p>公式 \\(M_{\\mathrm{KV}} = 2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}} + N_{\\mathrm{txt}})\\cdot B_{\\mathrm{conc}}\\) 的每一项都不是装饰。系数 2 是 K 与 V 两份缓存，这一点在多模态场景里尤其值得强调：跨模态注意力层往往对 K 与 V 的访问模式不对称——视觉 K 被所有文本 query 反复读取，视觉 V 只在输出聚合时被取用一次，但缓存本身仍必须成对驻留，不能因为访问频次低就省掉 V。\\(\\ell\\) 是解码器层数，它与 \\(d_{\\mathrm{kv}}\\) 的乘积决定了「每 token 每层」的字节基数；把 \\(\\ell\\) 放在 \\(d_{\\mathrm{kv}}\\) 之前只是书写顺序，真正的推导关键是把单请求字节数按层展开：每一层都独立持有一份形状为 \\((N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\times d_{\\mathrm{kv}}\\) 的 K 和一份同形状的 V，层与层之间不共享，因此层数直接线性放大显存。</p>\n<p>这里有一个容易被忽略的次序问题：\\(d_{\\mathrm{kv}}\\) 是「每层 KV 头维度总和」，即 num_kv_heads × head_dim，而不是注意力头总数乘以 head_dim。在 GQA/MQA 结构下，num_kv_heads 远小于 query 头数，这一项因此比朴素估计小一个量级；但视觉 token 的加入让 \\(N_{\\mathrm{vis}}+N_{\\mathrm{txt}}\\) 这一因子变大，两者相乘后，KV 头压缩带来的节省会被视觉 token 的膨胀部分抵消。工程判断是：先确认 \\(d_{\\mathrm{kv}}\\) 取的是 KV 头而非 Q 头，否则整条容量反解会系统性高估数倍。</p>\n<p>代价层面，\\(\\ell\\cdot d_{\\mathrm{kv}}\\cdot b\\) 构成「每 token 每层」的固定税率，它与 batch 大小无关，只与模型结构有关；因此对同一模型，显存压力完全由 token 总量与并发数驱动。举例：一个视觉 token 预算为数千、文本 token 为数百的请求，其 \\(N_{\\mathrm{vis}}\\) 项在求和里占绝对多数，此时即便把文本侧做极致压缩，对 \\(M_{\\mathrm{KV}}\\) 的削减也微乎其微——这解释了为什么多模态容量规划必须把优化火力集中在视觉 token 数上，而不是文本侧。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-8\">八 · 推导关键步：从单请求到稳态占用</h3>\n<p>推导分三步，每一步都引入一个可检验的假设。第一步，单层单请求：K 缓存字节数为 \\(N\\cdot d_{\\mathrm{kv}}\\cdot b\\)，V 同理，合计 \\(2\\,d_{\\mathrm{kv}}\\,b\\,N\\)，其中 \\(N=N_{\\mathrm{vis}}+N_{\\mathrm{txt}}\\)。这一步的隐含假设是 KV 以连续稠密张量存放、无对齐填充；真实分配器按页对齐，实际占用是向上取整后的页数乘以页大小，因此这一步给出的是下界而非精确值。第二步，按层累加：\\(\\ell\\) 层互不共享，得单请求 \\(2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,N\\)。第三步，乘以并发批大小 \\(B_{\\mathrm{conc}}\\)，得到稳态占用 \\(M_{\\mathrm{KV}}\\)。</p>\n<p>第三步是全部推导中最脆弱的一环。它假设所有并发请求的 KV 同时驻留且长度相同，而连续批处理下请求的到达与完成是异步的，实际驻留量是各请求长度的和而非「平均长度 × 批大小」。正确的写法应是 \\(M_{\\mathrm{KV}} = 2\\,\\ell\\,d_{\\mathrm{kv}}\\,b \\sum_{i=1}^{B_{\\mathrm{conc}}} N^{(i)}\\)，公式中的乘法形式只有在各请求 token 数可视为同分布时才成立。对多模态服务，这一同分布假设经常破裂：同一批里可能混有低分辨率短请求与高分辨率长请求，用平均值代入会低估峰值。</p>\n<div class=\"formula\">$$B_{\\mathrm{conc}}^{\\max} \\;=\\; \\left\\lfloor \\frac{M_{\\mathrm{avail}}}{2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})} \\right\\rfloor$$</div>\n<p>这个反解式是容量决策的直接工具：\\(M_{\\mathrm{avail}}\\) 为 HBM 容量减去权重与运行时激活后的余量，向下取整是因为批大小必须为整数且要留出安全边际。代价体现在延迟侧：\\(B_{\\mathrm{conc}}\\) 越大，单次解码步的 KV 读取带宽需求越高，解码从带宽受限滑向更严重的带宽受限；因此在带宽固定的前提下，提高并发与降低单请求延迟是一对硬约束下的取舍，而非可以同时优化的两个目标。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-9\">九 · 离散化与近似：分辨率平方增长如何进入公式</h3>\n<p>\\(N_{\\mathrm{vis}}\\) 不是自由变量，它由视觉编码器的切图策略离散决定。以常见的 patch 切分为例，图像被划为 \\(P\\times P\\) 个 patch，每个 patch 映射为一个视觉 token，则 \\(N_{\\mathrm{vis}} \\approx (H/P)\\cdot(W/P)\\)，即随分辨率平方增长。这里的离散化有两层：一是 patch 网格的整数取整，图像边长不能被 P 整除时产生边缘补齐，实际 token 数略高于连续估计；二是切图数量本身是整数，高分辨率图像被切成若干子图后，子图间还可能插入分隔 token，使 \\(N_{\\mathrm{vis}}\\) 出现阶跃式跳变而非平滑增长。</p>\n<p>把平方增长代入公式，得到 \\(M_{\\mathrm{KV}}\\) 对分辨率的二次依赖：分辨率翻倍，视觉 token 数约变为四倍，KV 显存随之约四倍。这一近似在中等分辨率区间成立，但在极高分辨率下会被切图上限截断——编码器通常设有最大子图数，超过后改为降采样，于是 \\(N_{\\mathrm{vis}}\\) 从平方增长转为线性甚至饱和。工程上必须知道当前服务落在哪一段：落在平方段时，分辨率是显存的第一驱动；落在饱和段时，继续提分辨率不再线性推高 KV，但视觉细节的损失开始显现。</p>\n<p>另一个近似藏在 \\(b\\) 上。公式默认 \\(b=2\\)（FP16）或 \\(b=1\\)（INT8），这是把每元素字节数当作常数。实际量化 KV 时，除数据本身外还有缩放因子、零点等元数据，每页或每组共享一份，摊到每 token 上使有效 \\(b\\) 略高于标称值；分组越细，元数据开销占比越高。因此在 INT8 KV 下，用 \\(b=1\\) 反解出的并发数是乐观上界，真实可用并发要按实测有效字节数折减。这一折减不是误差修正，而是量化方案设计时必须前置考虑的容量税。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-10\">十 · 失效条件的数学形态：分页、压缩与峰值</h3>\n<p>公式的适用边界可以写成三个不等式。第一，无分页碎片要求 \\(M_{\\mathrm{KV}}\\) 恰好等于分配器实际占用，而 PagedAttention 下占用为 \\(\\lceil N/s \\rceil \\cdot s \\cdot 2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\)，其中 \\(s\\) 为页内 token 数；当 \\(N\\) 不是 \\(s\\) 的整数倍时，每个请求浪费至多半页，短请求多时浪费比例显著。第二，静态 \\(N_{\\mathrm{vis}}\\) 要求视觉 KV 在 prefill 后不被改写；若推理中执行视觉 token 剪枝或合并，稳态 \\(N_{\\mathrm{vis}}\\) 应取压缩后的值，此时公式右侧应写成 \\(N_{\\mathrm{vis}}^{\\mathrm{steady}}\\)，而输入阶段的 \\(N_{\\mathrm{vis}}^{\\mathrm{input}}\\) 只影响 prefill 瞬时峰值。第三，稳态式不含临时缓冲，峰值显存为 \\(M_{\\mathrm{KV}} + M_{\\mathrm{enc}} + M_{\\mathrm{xattn}}\\)，其中视觉编码器激活与跨模态注意力临时张量在长分辨率请求下不可忽略。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>公式形态变化</th><th>系统代价</th></tr></thead><tbody><tr><td>PagedAttention 分页</td><td>\\(N\\) 向上取整到页边界，有效占用率 &lt; 1</td><td>短请求多时显存浪费，可用并发低于反解值</td></tr><tr><td>INT8 KV 量化</td><td>\\(b\\) 由 2 降为 1，另加元数据开销</td><td>带宽减半、容量翻倍，但解码需反量化，增加计算与延迟</td></tr><tr><td>视觉 KV 动态压缩</td><td>\\(N_{\\mathrm{vis}}\\) 取稳态值而非输入值</td><td>prefill 峰值仍按输入值计，压缩本身消耗算力</td></tr><tr><td>忽略临时缓冲</td><td>峰值 \\(=M_{\\mathrm{KV}}+M_{\\mathrm{enc}}+M_{\\mathrm{xattn}}\\)</td><td>长分辨率请求下 OOM 风险，需预留 headroom</td></tr></tbody></table>\n<p>把这三条失效条件合起来看，公式给出的 \\(M_{\\mathrm{KV}}\\) 是一个「理想稳态下界」，而工程上真正约束并发的是「峰值上界」。两者之间的差额就是必须预留的安全边际：分页碎片、量化元数据、压缩前后的瞬时差、编码器激活，每一项都在把可用并发往下拉。一个具体的判断是：当服务混合了长短差异极大的多模态请求时，按平均 \\(N_{\\mathrm{vis}}\\) 反解出的 \\(B_{\\mathrm{conc}}\\) 应再乘一个小于 1 的折减系数，折减幅度由最长请求的 \\(N_{\\mathrm{vis}}\\) 与页大小的比值决定。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-11\">十一 · 反解式的工程用法与误用对照</h3>\n<p>反解式 \\(B_{\\mathrm{conc}} = M_{\\mathrm{avail}} / (2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}}))\\) 在准入控制里应作为「每请求显存配额」的倒数使用：调度器为每个新请求预估其 \\(N_{\\mathrm{vis}}+N_{\\mathrm{txt}}\\)，乘以单 token 字节基数得到配额，再从剩余显存中扣除。这比按固定批大小准入更稳，因为多模态请求的 token 数方差远大于纯文本。代价是调度器需要前置知道每个请求的视觉 token 数，而这依赖图像分辨率与切图策略的确定性——若切图策略随内容自适应，预估本身就有误差，配额需按上界取。</p>\n<p>误用有两种典型形态，方向相反。其一，用输入阶段切出的视觉 token 数直接代入 \\(N_{\\mathrm{vis}}\\)，忽略推理中的剪枝与合并，结果高估显存、低估可并发数，GPU 利用率被压在低位；这在启用视觉 KV 压缩的服务里尤其常见，因为压缩后的稳态值可能只有输入值的一小部分。其二，只按稳态式分配而不预留编码器激活与跨模态注意力临时缓冲，稳态算得刚好、峰值一来就 OOM；长分辨率请求是触发这种失败的高危输入。两种误用的共同根源是把公式当成精确等式而非带条件的近似，工程上正确的姿态是：用公式定基线，用实测有效占用率与峰值余量做修正，再据此设定准入阈值。</p>\n<p>最后落到一个具体机制上：把 \\(M_{\\mathrm{avail}}\\) 拆成「稳态配额」与「峰值储备」两部分，稳态配额按反解式分配，峰值储备按最长请求的编码器激活与跨模态缓冲单独预留，两者不互相挪用。这样公式的每一项都有了明确归属，\\(b\\) 的量化折减、\\(N_{\\mathrm{vis}}\\) 的压缩稳态值、页对齐的取整损失各自落在稳态配额里被显式扣除，而临时缓冲不再挤占稳态容量——这是把一条近似公式变成可运维容量策略的关键一步。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-12\">十二 · 稳态式的三处失真：压缩、分页与峰值缓冲</h3>\n<p>该式给出的是<strong>稳态占用</strong>，而多模态推理的显存曲线在时间轴上并不平坦。视觉 token 在 prefill 完成后可被剪枝或合并，此时 $N_{\\mathrm{vis}}$ 必须取压缩后的稳态值，而非输入切块数。若把输入阶段的视觉 token 数直接代入，单请求字节数被系统性高估，反解出的 $B_{\\mathrm{conc}}$ 偏小，准入控制过保守，GPU 批维利用率被压低——这是多模态服务最常见的容量误判方向。反之，若压缩确实发生却仍按输入值预留，浪费的是本可分配给更多并发的 HBM。</p>\n<p>第二处失真来自存储形态。式中的 $b$ 与“无碎片”假设只在 KV 连续存放且为 FP16/BF16 时成立；启用 PagedAttention 后，块内尾部浪费与块表开销使有效占用率低于 1，启用 INT8 KV 量化后 $b$ 应取 1，但同时引入 scale/zero-point 的旁路字节与反量化算力开销。工程上应把式改写为 $M_{\\mathrm{KV}} = 2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\,B_{\\mathrm{conc}} / \\eta$，其中 $\\eta$ 为实测有效占用率，由分页块大小与序列长度分布共同决定，短请求占比高的负载下 $\\eta$ 下降更明显。</p>\n<p>第三处失真在峰值。稳态式不含视觉编码器激活与跨模态注意力的临时缓冲，而这两项随分辨率上升而非线性增长。容量规划应写成 $M_{\\mathrm{avail}} \\ge M_{\\mathrm{KV}}^{\\mathrm{steady}} + M_{\\mathrm{peak}}^{\\mathrm{enc}}$，先由峰值约束反解并发上限，再用稳态式校验长时占用。高分辨率请求集中到达时，峰值项先于稳态项触顶，OOM 往往发生在 prefill 阶段而非解码阶段。</p>\n<table class=\"mini\"><thead><tr><th>失真来源</th><th>代入量修正</th><th>系统代价</th></tr></thead><tbody><tr><td>视觉 KV 动态压缩</td><td>$N_{\\mathrm{vis}}$ 取压缩后稳态值</td><td>并发上限被低估，批维空转</td></tr><tr><td>分页/量化</td><td>$b$ 与 $\\eta$ 取实测值</td><td>可用并发低于计算值</td></tr><tr><td>编码器与跨模态缓冲</td><td>追加峰值项</td><td>prefill 阶段触发 OOM</td></tr></tbody></table>\n<h3 id=\"th-multimodal-kv-cache-sec-13\">十三 · 稳态式成立的三条隐含假设</h3>\n<p>公式 $M_{\\mathrm{KV}} = 2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}} + N_{\\mathrm{txt}})\\cdot B_{\\mathrm{conc}}$ 之所以能写成一行闭式，靠的是三条没有写在纸面上的假设，任何一条被打破，反解出的 $B_{\\mathrm{conc}}$ 就不再是可用并发数。第一条是<strong>存储格式恒定</strong>：全部 KV 元素以同一 $b$ 字节存储，且没有额外元数据；第二条是<strong>占用率理想</strong>：分配器给出的显存块被完全填满，不存在分页粒度造成的内部碎片；第三条是<strong>token 数静态</strong>：$N_{\\mathrm{vis}}$ 与 $N_{\\mathrm{txt}}$ 在一次请求生命周期内不随时间变化，且视觉 token 在 prefill 之后原样驻留。这三条在教科书式的连续批处理里近似成立，但在真实的多模态服务栈里几乎同时被侵蚀。工程上判断公式是否还能用，本质是判断这三条假设的偏离量是否落在容量预算的余量之内。</p>\n<p>把偏离量显式化，可以把公式改写为带修正因子的形式：</p>\n<div class=\"formula\">$$M_{\\mathrm{KV}}^{\\mathrm{real}} \\;=\\; \\frac{2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}^{\\mathrm{ss}} + N_{\\mathrm{txt}})\\cdot B_{\\mathrm{conc}}}{\\eta_{\\mathrm{pack}}}\\,\\cdot\\,\\kappa_{\\mathrm{q}}$$</div>\n<p>其中 $N_{\\mathrm{vis}}^{\\mathrm{ss}}$ 是压缩后的稳态视觉 token 数，$\\eta_{\\mathrm{pack}}$ 是分页分配的实际填充率，$\\kappa_{\\mathrm{q}}$ 是量化引入的每元素字节比（INT8 时 $b=1$，但缩放因子与分组元数据使 $\\kappa_{\\mathrm{q}}$ 略大于 1）。这三个量都不是常数，而是随请求形态、批组成、调度策略漂移的随机变量，因此闭式解只能当作上界估计而非精确配额。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-14\">十四 · 分页与量化的联合侵蚀</h3>\n<p>PagedAttention 把 KV 切成固定大小的 block 按需分配，代价是每个请求最后一个 block 通常填不满。设 block 大小为 $P$ 个 token，单请求的期望浪费约为 $P/2$ 个 token 的 KV 字节，当 $B_{\\mathrm{conc}}$ 较大且请求长度参差时，总浪费近似正比于 $B_{\\mathrm{conc}}\\cdot P$，与 $N_{\\mathrm{vis}}+N_{\\mathrm{txt}}$ 无关——这意味着<strong>短请求占比越高，分页碎片对并发上限的侵蚀越显著</strong>。一个视觉 token 数很少、文本极短的请求，其 KV 占用可能有一半耗在未填满的尾块上。此时若仍用理想占用率反解 $B_{\\mathrm{conc}}$，实际可并发数会被系统性高估，表现为调度器接受了超过物理容量的批，触发抢占与重算。</p>\n<p>INT8 KV 量化把 $b$ 从 2 降到 1，看似直接把容量翻倍，但分组量化需要 per-group 缩放因子，且反量化在注意力计算路径上引入额外带宽与指令开销。更关键的是，量化后的 KV 往往需要保留一份高精度副本用于某些敏感层或敏感头，或者按层混合精度，此时 $b$ 不再是全局常数，公式中的 $b$ 必须替换为按层加权平均的有效字节数。工程判断是：<strong>只要量化策略不是全局均匀的，就不要用单一 $b$ 代入闭式，而应按层累加 $2\\,d_{\\mathrm{kv}}\\,b_i$ 后再乘 token 数</strong>。这一步在容量规划脚本里通常被省略，是并发上限估算偏乐观的常见来源。</p>\n<p>代价层面，分页与量化共同作用的结果是：显存容量上升，但有效带宽利用率下降。注意力核在读取量化 KV 时需要额外的反量化步骤，decode 阶段的每 token 延迟对 KV 带宽敏感，因此量化带来的容量收益必须与 decode 吞吐的损失一起权衡，而不能只看 $M_{\\mathrm{KV}}$ 变小就断定并发可以同比例放大。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-15\">十五 · 动态视觉压缩让 $N_{\\mathrm{vis}}$ 变成时变量</h3>\n<p>视觉 token 在 prefill 之后可被剪枝或合并，这是多模态推理区别于纯文本推理的核心特征。若推理中动态压缩视觉 KV，$N_{\\mathrm{vis}}$ 应取压缩后的稳态值而非输入切出的 token 数。问题在于压缩比不是常数：它取决于图像内容、跨模态注意力分布、以及压缩策略的触发阈值。高信息密度图像（密集文字、复杂图表）的视觉 token 难以合并，稳态 $N_{\\mathrm{vis}}$ 接近输入值；低信息密度图像（纯色背景、简单物体）可压缩到很小。于是同一批内不同请求的稳态 $N_{\\mathrm{vis}}$ 差异可达数倍，用单一平均值代入公式会在批组成偏向高密度图像时低估显存。</p>\n<p>更微妙的失效发生在压缩时机上。若压缩发生在 prefill 之后、decode 之前，则峰值显存出现在压缩前的瞬间，稳态式描述的是压缩后的占用，两者之间的差额就是压缩窗口内的临时峰值。容量规划若只按稳态式预留，压缩窗口内的峰值可能击穿预算。工程做法是把压缩窗口的峰值单独建模为 $M_{\\mathrm{KV}}^{\\mathrm{pre}} = 2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}^{\\mathrm{in}} + N_{\\mathrm{txt}})\\cdot B_{\\mathrm{conc}}^{\\mathrm{active}}$，其中 $B_{\\mathrm{conc}}^{\\mathrm{active}}$ 是同时处于压缩窗口内的请求数——这个数由调度器的批推进节奏决定，而不是由稳态并发上限决定。两个数必须分别校验。</p>\n<p>反过来，忽略动态压缩则走向另一个失败模式：直接用输入视觉 token 数代入，高估显存、低估可并发数，GPU 利用率不足。这在视觉 token 压缩率高的服务里尤为明显，表现为显存明明有余量、调度器却拒绝接纳新请求。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-16\">十六 · 未计入的临时缓冲与峰值失守</h3>\n<p>稳态式只覆盖 KV 本身，不含视觉编码器激活与跨模态注意力的临时缓冲。视觉编码器（ViT 类）在前向过程中产生的激活量与输入分辨率、patch 数、编码器宽度相关，其峰值出现在编码器最后一层附近，量级可与中等长度请求的 KV 占用相比。跨模态注意力在拼接视觉与文本序列时，注意力矩阵或分块计算的中间结果同样是瞬时大头。这些缓冲的生命周期短，但峰值高，且与 KV 稳态占用在时间上重叠于 prefill 阶段。</p>\n<p>因此显存预算的正确写法是分段校验而非单点校验：prefill 阶段的峰值由「权重 + 编码器激活 + 跨模态临时缓冲 + 当前批已驻留 KV」构成，decode 阶段的稳态由「权重 + KV 稳态 + 少量激活」构成。两个阶段各自有约束，前者常被后者掩盖。长分辨率请求（大图、多图、视频帧序列）会把 prefill 峰值推高，若只按稳态式分配显存而不预留这部分，OOM 就发生在 prefill 而非 decode——这与纯文本推理的 OOM 位置完全不同，排查时容易误判为权重或框架开销问题。</p>\n<p>工程上的量化判断是：把「KV 稳态占用 / 可用显存」控制在明显低于 1 的比例，留出的余量要能覆盖单批内最大分辨率请求的编码器激活峰值。这个余量不是固定百分比，而应随服务的最长边分辨率与最大批内图像数缩放；分辨率翻倍时视觉 token 数按平方增长，编码器激活也随之增长，余量需求同步抬升。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-17\">十七 · 规模上限：公式在什么量级上先崩</h3>\n<p>闭式解在小规模、同质请求下几乎精确；随着规模上升，三类偏离按不同速率累积。分页碎片随 $B_{\\mathrm{conc}}$ 线性增长，在批大小达到数百量级时成为可观项；动态压缩的方差随批内请求异质性增长，在混合分辨率、混合模态（图、视频、文档）的流量下迅速放大；prefill 峰值与稳态的差额随最长边分辨率增长，在支持高分辨率输入的服务里最先触顶。三者叠加的结果是：<strong>公式给出的 $B_{\\mathrm{conc}}$ 在大规模异构流量下是上界，且上界与真实值的差距随规模单调扩大</strong>。</p>\n<p>规模上限的另一个维度是准入控制的粒度。按请求级反解 $B_{\\mathrm{conc}}$ 隐含假设所有请求占用相同 KV，实际应按 token 级配额做准入：新请求的稳态 KV 字节数（含压缩后 $N_{\\mathrm{vis}}^{\\mathrm{ss}}$）加上当前已驻留总量不超过预算才放行。token 级准入把公式从「批大小上限」退化为「单请求准入判据」，反而在异构流量下更稳，因为它不依赖批组成的平均值假设。代价是调度器需要维护每个请求的实时 KV 占用估计，并在压缩发生后更新，这引入了估计误差与更新延迟，但误差方向可控（偏保守），不会导致 OOM。</p>\n<p>最后一条边界是时间维度：公式描述的是某一时刻的占用，而连续批处理下请求不断进出，KV 占用是随时间波动的随机过程。容量规划若只看期望值，会在波动峰值处失守；正确做法是按分位数（而非均值）设定预算，并让调度器在接近分位阈值时主动降低接纳速率。这一步把静态公式转化为动态控制回路，是公式在规模上限之外仍能指导工程的唯一方式。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-18\">十八 · 边界不在公式里，在公式没写的那几项</h3>\n<p>稳态式只在“KV 是唯一显存消耗者、且其字节数可被输入 token 数线性预测”时成立。真实多模态推理里至少有三类项被该式省略，它们不是修正系数，而是独立失效通道。第一类是视觉编码器自身的激活：ViT 在高分辨率下前向的中间张量随 patch 数平方级膨胀，且这部分显存在 prefill 阶段瞬时占用、解码阶段释放，稳态式完全看不到它。第二类是跨模态注意力的临时缓冲，图像特征与文本隐状态对齐时产生的拼接/重排缓冲在长序列下不可忽略。第三类是分页与量化带来的有效占用率偏离，PagedAttention 的块内碎片与 INT8 KV 的 scale/zero-point 元数据都使实际每 token 字节数高于名义 $b$。因此判断公式是否适用，先问一句：当前请求的显存峰值出现在 prefill 还是 decode？峰值在 prefill，稳态式只能做下界。</p>\n<p>失效条件可以整理成一张判据表，工程上按“是否触发”逐项核对，而不是笼统地说“近似”。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>公式行为</th><th>系统代价</th></tr></thead><tbody><tr><td>KV 以 FP16/BF16 存储、无分页</td><td>$b=2$，占用率按 1 计</td><td>基线，容量反解可信</td></tr><tr><td>启用 PagedAttention</td><td>$b$ 不变但有效占用率&lt;1</td><td>块碎片使可用并发低于反解值</td></tr><tr><td>INT8 KV 量化</td><td>$b=1$ 加元数据开销</td><td>带宽降、精度与反量化延迟升</td></tr><tr><td>推理中动态压缩视觉 KV</td><td>$N_{\\mathrm{vis}}$ 应取压缩后稳态值</td><td>用输入值会高估显存、低估并发</td></tr><tr><td>长分辨率、编码器激活未预留</td><td>稳态式不含该项</td><td>峰值超预算触发 OOM</td></tr></tbody></table>\n<p>规模上限由反解式给出，但它对 $N_{\\mathrm{vis}}$ 极其敏感，因为视觉 token 随分辨率平方增长。设可用显存余量为 $M_{\\mathrm{avail}}$，则</p>\n<div class=\"formula\">$$B_{\\mathrm{conc}}^{\\max} \\;=\\; \\frac{M_{\\mathrm{avail}}}{2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})}$$</div>\n<p>把 $N_{\\mathrm{vis}}$ 从输入值换成压缩后稳态值，分母缩小，$B_{\\mathrm{conc}}^{\\max}$ 上升——这正是“高估显存、低估并发”的失败模式：准入控制按输入 token 数卡阈值，GPU 实际能跑更多请求却被人为限流，利用率不足。反过来，若只按稳态式分配而不预留编码器激活，长分辨率请求下峰值显存越过预算，OOM 发生在 prefill 而非 decode，监控上表现为“短请求正常、高分辨率请求批量失败”。工程判断是：容量规划用稳态式定并发上限，但准入控制必须叠加一条峰值约束——对 $N_{\\mathrm{vis}}$ 超过某阈值的请求单独限流或串行化，把编码器激活与跨模态缓冲作为独立预算项从 $M_{\\mathrm{avail}}$ 中先扣除，剩余部分才代入反解式。这一步不做，公式在长分辨率场景下不再是容量工具，而是 OOM 的诱因。</p>\n<h3 id=\"th-multimodal-kv-cache-sec-19\">十九 · 从显存余量反解并发上限</h3>\n<p>容量决策的第一步不是算单请求要多少显存，而是算<strong>还剩多少显存可以给 KV</strong>。给定一张 B200 的 HBM 容量，先扣掉权重常驻部分、框架运行时开销、CUDA graph 与 workspace、以及为视觉编码器激活预留的峰值缓冲，剩下的 $M_{\\mathrm{avail}}$ 才是 KV 预算。反解式写成：</p>\n<div class=\"formula\">$$B_{\\mathrm{conc}}^{\\max} \\;=\\; \\left\\lfloor \\frac{M_{\\mathrm{avail}}}{2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})} \\right\\rfloor$$</div>\n<p>这个式子的工程含义是：分母是单请求稳态 KV 字节数，分子是可用预算，商向下取整即为准入控制的上限。注意 $B_{\\mathrm{conc}}^{\\max}$ 是<strong>按最坏请求形态</strong>算出来的——如果服务混入高分辨率图像，$N_{\\mathrm{vis}}$ 会按分辨率平方增长，分母随之膨胀，同一个 $M_{\\mathrm{avail}}$ 下并发上限骤降。因此生产上不能只算一个全局批大小，而要按请求形态分档：低分辨率档、标准档、高分辨率档各自维护一个 $B_{\\mathrm{conc}}^{\\max}$，准入控制器按请求实际 token 数查档放行。这比“先到先服务、超了就排队”的粗放策略更能守住 SLO，因为高分辨率请求不会挤占低分辨率请求的并发额度。</p>\n<p>代价侧要盯住的是<strong>显存带宽与解码步延迟的耦合</strong>：批越大，每步解码要读的 KV 越多，单步延迟随批近似线性上升（在带宽受限区），吞吐上升但尾延迟恶化。所以 $B_{\\mathrm{conc}}^{\\max}$ 只是显存维度的硬上限，真正的运行批大小还要被延迟约束二次裁剪，见下一节。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-20\">二十 · 用 SLO 反推批大小与并行度</h3>\n<p>显存给的是上限，SLO 给的是<strong>可用区间</strong>。设解码阶段每步要读取的 KV 字节为 $2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\cdot B_{\\mathrm{conc}}$，HBM 有效带宽为 $\\mathrm{BW}_{\\mathrm{eff}}$，则单步 KV 读取时间下界为：</p>\n<div class=\"formula\">$$t_{\\mathrm{step}} \\;\\gtrsim\\; \\frac{2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\cdot B_{\\mathrm{conc}}}{\\mathrm{BW}_{\\mathrm{eff}}}$$</div>\n<p>把 SLO 的 TPOT 目标代进去，就得到延迟允许的最大批：$B_{\\mathrm{conc}}^{\\mathrm{SLO}} = \\lfloor \\mathrm{TPOT}_{\\mathrm{target}}\\cdot \\mathrm{BW}_{\\mathrm{eff}} / (2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})) \\rfloor$。实际运行批取 $\\min(B_{\\mathrm{conc}}^{\\max}, B_{\\mathrm{conc}}^{\\mathrm{SLO}})$。这一步把“显存能装多少”和“延迟允许多少”两个约束合并成一个可执行的批大小，是容量规划里最常被跳过、也最容易出问题的一环——很多服务按显存上限拉满批，结果 TPOT 超标，SLO 违约率飙升。</p>\n<p>并行度决策则从这个式子反向走：当单卡 $B_{\\mathrm{conc}}^{\\mathrm{SLO}}$ 太小、吞吐上不去时，说明单卡带宽已成瓶颈，此时应增加 TP 度把 KV 与权重切分到多卡，用 NVLink 5 的集合通信换带宽。判断依据是<strong>每卡 KV 字节数除以每卡带宽</strong>是否仍主导单步时间；若主导，加卡有效；若单步时间已被通信或调度开销占据，加卡只会摊薄收益。对多模态请求尤其要注意：视觉 token 让分母变大，单卡能撑的批更小，TP 的收益窗口比纯文本服务更早打开。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-21\">二十一 · KV 预算的分档与准入阈值</h3>\n<p>把 $M_{\\mathrm{avail}}$ 一次性全部分给 KV 是危险的，因为稳态式不含视觉编码器激活与跨模态注意力的临时缓冲。工程做法是<strong>三段式预算</strong>：固定预留（权重 + 运行时 + 视觉编码器峰值缓冲）、KV 稳态池、动态余量。KV 稳态池按分档并发上限分配，动态余量用于吸收长分辨率请求的峰值溢出与分页碎片。准入阈值就落在 KV 稳态池上：当已占用 KV 字节加上新请求的稳态字节超过池容量时拒绝或排队，而不是等到 OOM 才被动驱逐。</p>\n<p>分档的关键参数是 $N_{\\mathrm{vis}}$ 的取值口径。若推理链路对视觉 KV 做剪枝或合并，$N_{\\mathrm{vis}}$ 必须取<strong>压缩后的稳态值</strong>而非输入切出的 token 数；用输入值代入会高估单请求显存、低估可并发数，GPU 利用率被白白压掉。反过来，若不做压缩，就必须把输入值原样代入，并额外为压缩算法本身的中间缓冲留余量。这个口径不统一，分档表就是错的，准入控制也就失去意义。</p>\n<p>启用 PagedAttention 或 INT8 KV 量化后，$b$ 与有效占用率都要换成实测值：INT8 下 $b=1$，理论显存减半，但分页碎片与量化 scale 的额外存储会让有效占用率低于 1，实际可用并发达不到按 $b=1$ 算出的两倍。容量表必须用实测占用率回填，而不是沿用理想值。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-22\">二十二 · 算例：一个高分辨率请求档的容量推演</h3>\n<p>取一个具体形态做推演，只做符号运算不引入外部数字。设某 VLM 解码器 $\\ell$ 层、$d_{\\mathrm{kv}}$ 为每层 KV 头维度总和、KV 以 FP16 存储（$b=2$）。一个高分辨率图像请求切出 $N_{\\mathrm{vis}}$ 个视觉 token，文本提示 $N_{\\mathrm{txt}}$ 个 token，且 $N_{\\mathrm{vis}} \\gg N_{\\mathrm{txt}}$，视觉项主导分母。单请求稳态 KV 字节为 $2\\ell d_{\\mathrm{kv}}\\cdot 2\\cdot(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})$。若该卡扣除固定预留后 $M_{\\mathrm{avail}}$ 给定，则 $B_{\\mathrm{conc}}^{\\max} = \\lfloor M_{\\mathrm{avail}} / (4\\ell d_{\\mathrm{kv}}(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})) \\rfloor$。</p>\n<p>把这个结果与纯文本档对比：同一 $M_{\\mathrm{avail}}$ 下，纯文本档的 $N_{\\mathrm{vis}}=0$，分母只剩文本项，并发上限高出数倍。这就是多模态服务容量规划的核心矛盾——<strong>视觉 token 把分母抬高一个量级，并发上限被压到文本服务的几分之一</strong>。若再把 TPOT 约束叠上去，$B_{\\mathrm{conc}}^{\\mathrm{SLO}}$ 可能比 $B_{\\mathrm{conc}}^{\\max}$ 更小，实际批大小由延迟而非显存决定，此时加 TP 度是唯一能同时抬升两个上限的手段。</p>\n<p>算例的工程结论有三条：其一，容量表必须按请求形态分档，单一全局批大小必然在某一档上违约；其二，视觉 token 的稳态口径（压缩前还是压缩后）直接决定分档表的正确性，口径错了整张表作废；其三，固定预留里必须显式包含视觉编码器激活峰值，否则长分辨率请求会在稳态式之外触发 OOM，而这种 OOM 往往发生在批已满、驱逐已无空间可退的时刻，恢复代价最高。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-23\">二十三 · 把公式接进调度器与容量看板</h3>\n<p>公式要真正起作用，必须变成调度器里的<strong>准入判定函数</strong>和容量看板上的<strong>实时余量指标</strong>。调度器在每个请求入队时计算其稳态 KV 字节，与当前 KV 池占用相加，超过阈值则排队或降档（降分辨率、降视觉 token 数）；看板则持续输出三个量：KV 池占用率、按当前请求形态分布推算的 $B_{\\mathrm{conc}}^{\\max}$、以及实测 TPOT 与 SLO 目标的比值。三者联动才能在请求形态漂移时提前发现容量缺口，而不是等违约率上升才反应。</p>\n<p>一个容易被忽略的细节是<strong>视觉 KV 的动态压缩会改变占用曲线</strong>：压缩前占用高、压缩后回落，若准入只看压缩前峰值，会过度保守；若只看压缩后稳态，又会在压缩尚未完成时短暂超限。正确做法是按压缩完成的时间窗口设定一个过渡余量，让准入阈值在窗口内略高于稳态值。这个余量的量级由压缩算法的执行位置（prefill 后同步压缩还是解码中异步压缩）决定，属于必须实测标定的参数，不能从稳态式直接推出。</p>\n<p>最终落在工程判断上：$M_{\\mathrm{KV}}$ 式不是一张静态容量表，而是一个<strong>随请求形态、压缩策略、分页与量化配置实时变化的约束面</strong>。容量决策的正确姿势是把这个约束面接进准入控制与并行度调节回路，让批大小和 TP 度跟着实测占用率与 TPOT 走，而不是在部署时算一次就锁死。多模态服务的请求形态方差远大于纯文本，静态容量表在形态漂移面前几乎必然失效。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-24\">二十四 · 反解批大小的三个修正项：压缩稳态、分页碎片与峰值缓冲</h3>\n<p>容量决策的第一步不是套公式，而是判断公式里的量该取哪个时刻的值。$M_{\\mathrm{avail}}$ 是 HBM 减去权重与运行时激活后的余量，反解 $B_{\\mathrm{conc}} = M_{\\mathrm{avail}} / \\bigl(2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\bigr)$ 得到的只是一个理想上限。真正落到准入控制上，必须把分母拆成三项分别修正：稳态视觉 token、有效字节与占用率、以及峰值临时缓冲。视觉 token 在 prefill 之后可以被剪枝或合并，若推理栈中启用了动态视觉 KV 压缩，$N_{\\mathrm{vis}}$ 应取压缩后的稳态值而非输入切出的 token 数；用输入值代入会系统性高估单请求占用，把可并发数算低，GPU 被打不满。反过来，只按稳态式分配显存、不预留视觉编码器激活与跨模态注意力的临时缓冲，高分辨率长请求下峰值会越过预算直接 OOM。这两个方向的误差不会互相抵消，因为它们作用在不同的时间尺度上：前者是稳态偏差，后者是瞬态尖峰。</p>\n<p>把修正写成可执行的判据，设压缩比为 $\\rho = N_{\\mathrm{vis}}^{\\mathrm{steady}} / N_{\\mathrm{vis}}^{\\mathrm{input}} \\le 1$，分页与量化的有效占用率为 $\\eta \\le 1$（PagedAttention 的块内碎片、INT8 KV 的元数据与 scale 开销都折进 $\\eta$），峰值缓冲系数为 $\\kappa &gt; 1$，则工程上应使用</p>\n<div class=\"formula\">$$B_{\\mathrm{conc}}^{\\mathrm{safe}} \\;=\\; \\left\\lfloor \\frac{M_{\\mathrm{avail}}}{\\kappa \\cdot 2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,\\bigl(\\rho N_{\\mathrm{vis}}^{\\mathrm{input}} + N_{\\mathrm{txt}}\\bigr)\\,/\\,\\eta} \\right\\rfloor$$</div>\n<p>三个系数里，$\\rho$ 由视觉压缩策略决定，$\\eta$ 由分页块大小与量化方案决定，$\\kappa$ 由编码器激活峰值与跨模态注意力临时张量决定。三者都不是从公式推出来的，只能实测：$\\rho$ 取压缩后稳态 token 计数，$\\eta$ 用实际块占用率统计，$\\kappa$ 用长分辨率请求的显存峰值采样。任何一项沿用理想值（$\\rho=1$、$\\eta=1$、$\\kappa=1$），$B_{\\mathrm{conc}}^{\\mathrm{safe}}$ 都会高于真实可承载并发，表现为运行一段时间后 OOM 或调度器频繁抢占。</p>\n<p>算例：某多模态服务，$M_{\\mathrm{avail}}$ 给定为可容纳 KV 的余量，$\\ell$ 与 $d_{\\mathrm{kv}}$ 由模型结构固定，$b=2$（FP16）。单请求文本 $N_{\\mathrm{txt}}$ 较小，输入图像切出的 $N_{\\mathrm{vis}}^{\\mathrm{input}}$ 因分辨率放大成为主项。若直接按输入值反解，得到并发上限 $B_1$；实测压缩后 $\\rho$ 明显小于 1，则分母缩小，理论上可支持更多并发，但分页碎片使 $\\eta$ 小于 1、峰值缓冲使 $\\kappa$ 大于 1，两者把分母重新抬高。最终 $B_{\\mathrm{conc}}^{\\mathrm{safe}}$ 与 $B_1$ 的差距取决于 $\\rho$ 与 $\\kappa/\\eta$ 谁占优：压缩收益大而峰值缓冲小的栈，安全并发高于朴素估算；压缩收益被碎片与尖峰吃掉时，安全并发反而低于朴素估算。这就是为什么不能只调一个系数，必须三项同测。</p>\n<table class=\"mini\"><thead><tr><th>决策量</th><th>取值来源</th><th>失效表现</th></tr></thead><tbody><tr><td>$\\rho$ 稳态视觉 token 比</td><td>压缩后 token 计数实测</td><td>取输入值：并发上限被低估，利用率不足</td></tr><tr><td>$\\eta$ 有效占用率</td><td>分页块占用与量化开销统计</td><td>沿用 $b=2$ 与理想占用：实际并发低于计算值</td></tr><tr><td>$\\kappa$ 峰值缓冲系数</td><td>长分辨率请求显存峰值采样</td><td>不预留：峰值越预算，触发 OOM</td></tr></tbody></table>\n<p>这套判据同时约束并行度与 SLO。张量并行把 $\\ell$ 与 $d_{\\mathrm{kv}}$ 按卡切分，单卡分母下降、$M_{\\mathrm{avail}}$ 也下降，$B_{\\mathrm{conc}}^{\\mathrm{safe}}$ 未必随卡数线性增长；分离式预填/解码把 prefill 的视觉编码器激活峰值挪到另一组卡上，$\\kappa$ 在解码侧可调低，但跨节点传输视觉 KV 会引入带宽代价，等效于抬高 $\\eta$ 的损失。定 SLO 时，把 $B_{\\mathrm{conc}}^{\\mathrm{safe}}$ 当作硬上限，准入控制按 $\\rho$、$\\eta$、$\\kappa$ 的实时估计动态收紧，而不是按输入 token 数一刀切；视觉 token 占比高的请求单独排队，避免其峰值缓冲挤占文本请求的稳态配额。最终落在工程判断上：多模态 KV 预算的可靠性不取决于公式精度，而取决于三个修正系数是否被持续测量并写进调度器的准入逻辑。</p>\n<h3 id=\"th-multimodal-kv-cache-sec-25\">二十五 · 误用一：把输入侧视觉 token 数当作稳态 \\(N_{\\mathrm{vis}}\\)</h3>\n<p>这是多模态 KV 显存核算里最高频的错误，也是最隐蔽的一个。工程上做容量规划时，最顺手的做法是拿图像预处理后的 patch 数直接代入公式：一张高分辨率图切出多少视觉 token，就填多少 \\(N_{\\mathrm{vis}}\\)，乘上 \\(B_{\\mathrm{conc}}\\) 得到稳态占用。问题在于，公式描述的是<strong>解码期间的稳态 KV 占用</strong>，而输入侧的视觉 token 数只是 prefill 时刻的瞬时规模。若推理链路里存在视觉 KV 的动态剪枝或跨层合并——例如在 prefill 结束后按注意力显著性丢弃低贡献视觉 token、或把相邻视觉 token 的 KV 做均值合并——那么解码阶段真正驻留在 HBM 里的视觉 KV 条目数，是压缩后的稳态值，而不是输入值。</p>\n<p>用输入值代入的后果是单向的：算出来的 \\(M_{\\mathrm{KV}}\\) 偏大，反解出的 \\(B_{\\mathrm{conc}}\\) 偏小。工程上表现为准入控制阈值设得过紧，调度器在还有大量空闲 HBM 的情况下拒绝新请求，GPU 的 SM 利用率与解码吞吐都上不去。识别方法很直接：在服务里挂一个按层采样的 KV 占用探针，比较 prefill 结束瞬间与解码若干步之后的视觉 KV 条目数，若两者出现稳定差值，说明链路中存在压缩，此时公式里的 \\(N_{\\mathrm{vis}}\\) 必须换成实测稳态值。判据是差值是否在解码步上收敛——收敛到某个平台值才叫稳态，仍在单调下降说明压缩尚未结束，取平台值而非瞬时值。</p>\n<p>举个具体形态：一个请求输入侧视觉 token 规模远大于文本 token，若按输入值核算，单请求 KV 字节数被高估，容量规划给出的并发上限明显低于实际可承载量；换成压缩后稳态值重算，同样的 HBM 余量能容纳的并发批显著上升。这不是精度问题，是数量级上的容量误判。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-26\">二十六 · 误用二：只按稳态式分配，不留峰值缓冲</h3>\n<p>公式的适用边界写得很清楚：它不计入视觉编码器激活与跨模态注意力的临时缓冲。但工程实现里，很多团队把 \\(M_{\\mathrm{KV}}\\) 当作显存预算的全部，用 HBM 总量减去权重、减去这个稳态值，剩下的全部分给 KV 池。这在短请求、低分辨率负载下能跑通，一旦遇到长分辨率请求就崩。</p>\n<p>机制上，视觉编码器在前向过程中持有自己的激活张量，跨模态注意力层在做视觉-文本对齐时还要构造额外的中间缓冲，这些都不是 KV cache 的组成部分，却在时间上与 KV 分配重叠。峰值显存的形态是：稳态 KV 占用 + 编码器激活 + 跨模态临时缓冲，三者同时在场。若预算只覆盖第一项，峰值就会越界。</p>\n<div class=\"formula\">$$M_{\\mathrm{peak}} \\;\\ge\\; M_{\\mathrm{KV}} + A_{\\mathrm{enc}} + A_{\\mathrm{xmodal}}$$</div>\n<p>这里 \\(A_{\\mathrm{enc}}\\) 与 \\(A_{\\mathrm{xmodal}}\\) 是随请求分辨率与批内最大分辨率变化的量，不是常数。工程代价体现在两个方向：预留过多，稳态期 HBM 闲置，并发上限被人为压低；预留不足，长分辨率请求触发 OOM，服务直接失败而非降级。识别手段是把显存峰值采样与请求分辨率分布对齐——若 OOM 集中出现在分辨率分布的高分位段，而稳态 KV 占用在该段并未显著抬升，基本可以判定是临时缓冲没被预算覆盖。</p>\n<p>具体例子：批内混入一张超高分辨率图像时，该请求的视觉编码器激活规模远超同批其他请求，跨模态注意力的临时缓冲也随之放大，峰值显存在这一步冲高；若准入控制只看稳态式给出的平均占用，这张图就会成为整批的 OOM 触发点。正确的做法是按批内最大分辨率而非平均分辨率预留峰值缓冲，或者对超高分位请求做单独路由。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-27\">二十七 · 误用三：分页与量化后仍沿用理想参数</h3>\n<p>第三个误用发生在启用了 PagedAttention 或 INT8 KV 量化之后：公式里的 \\(b\\) 仍填 2，占用率仍按理想值 1 计算。这两项在真实系统里都不成立。分页带来块内碎片与块间未用槽位，有效占用率低于 1；INT8 KV 量化虽然把 \\(b\\) 从 2 降到 1，但量化本身引入额外的缩放因子存储与可能的反量化临时缓冲，且分页粒度与量化块粒度不一致时会进一步放大碎片。</p>\n<p>后果是双向偏差叠加：\\(b\\) 填大了高估显存，占用率填高了低估实际可用容量，两个误差方向不一定抵消，最终算出的 \\(B_{\\mathrm{conc}}\\) 与实测可承载并发之间出现系统性偏离。识别方法是做一次标定实验：在固定批大小下实测 KV 池的实际占用字节数，反解出等效的 \\(b_{\\mathrm{eff}}\\) 与 \\(\\eta_{\\mathrm{eff}}\\)（有效占用率），把这两个实测值代回公式，而不是继续用教科书参数。</p>\n<div class=\"formula\">$$B_{\\mathrm{conc}}^{\\mathrm{eff}} \\;=\\; \\frac{M_{\\mathrm{avail}}\\cdot\\eta_{\\mathrm{eff}}}{2\\,\\ell\\,d_{\\mathrm{kv}}\\,b_{\\mathrm{eff}}\\,(N_{\\mathrm{vis}}^{\\mathrm{steady}}+N_{\\mathrm{txt}})}$$</div>\n<p>工程代价落在吞吐与 SLO 上：若 \\(B_{\\mathrm{conc}}^{\\mathrm{eff}}\\) 被高估，调度器会放行超出实际容量的批，触发抢占或 OOM 重试，尾延迟抬升；若被低估，则 HBM 带宽与算力都喂不饱，解码吞吐上不去。分页碎片在长序列、多请求混合的场景下尤其明显，因为块分配的不规则性随批内序列长度方差增大而放大。</p>\n<p>具体例子：同一套硬件上，FP16 无分页与 INT8 分页两种配置，若都用 \\(b=2\\)、\\(\\eta=1\\) 代入，得到的并发上限完全一致，但实测可承载并发在两种配置下并不相同——量化把每 token 字节数减半，理论上应提升并发，分页碎片又把提升吃掉一部分。不做标定就无法知道净效应是正是负，容量决策就成了拍脑袋。</p>\n\n<h3 id=\"th-multimodal-kv-cache-sec-28\">二十八 · 一个反例：按输入 token 数做容量规划的全链路失效</h3>\n<p>把三个误用串起来看一个反例。某多模态服务做容量规划，取一张典型图像切出的视觉 token 数作为 \\(N_{\\mathrm{vis}}\\)，取 \\(b=2\\)、\\(\\eta=1\\)，算出单请求 KV 字节数，再用 HBM 余量反解 \\(B_{\\mathrm{conc}}\\)，把结果直接写进准入控制。上线后出现两个症状：低分辨率负载下并发上不去，GPU 利用率长期偏低；高分辨率请求偶发 OOM。</p>\n<p>拆解原因：低分辨率段的并发被低估，是因为链路里存在视觉 KV 合并，稳态 \\(N_{\\mathrm{vis}}\\) 小于输入值，公式高估了单请求占用；高分辨率段的 OOM，是因为预算没留编码器激活与跨模态缓冲，峰值越界。两个症状指向同一个根因——公式被当成了输入侧的瞬时核算工具，而不是解码稳态加峰值包络的规划工具。</p>\n<p>修正路径分三步。第一步，在服务里实测稳态 \\(N_{\\mathrm{vis}}\\)，用解码若干步后的收敛值替换输入值。第二步，按批内最大分辨率而非典型分辨率预留峰值缓冲，把 \\(A_{\\mathrm{enc}}+A_{\\mathrm{xmodal}}\\) 显式计入预算。第三步，做一次标定实验反解 \\(b_{\\mathrm{eff}}\\) 与 \\(\\eta_{\\mathrm{eff}}\\)，代回公式重算 \\(B_{\\mathrm{conc}}^{\\mathrm{eff}}\\)，并以此设定准入阈值。三步都做完，容量规划才与真实系统对齐。</p>\n<p>这个反例的工程判断价值在于：公式本身没错，错在把它用在它不适用的时刻与参数上。多模态 KV 显存核算的正确姿势是——稳态值取压缩后收敛值，预算取峰值包络，参数取实测标定值。三者缺一，容量决策就会在利用率与稳定性之间反复横跳，而工程上真正要守的是那条峰值包络线，不是稳态式给出的漂亮数字。</p>\n\n\n<h3 id=\"th-multimodal-kv-cache-sec-29\">二十九 · 误用与反例：稳态式当输入式、峰值当均值</h3>\n<p>最常见的误用不是公式写错，而是把公式里的 <em>N</em><sub>vis</sub> 当成“输入图像切出的视觉 token 数”直接代入。这个量是 prefill 阶段的瞬时规模，不是解码期的稳态规模。视觉 KV 在跨模态注意力完成后可被剪枝或合并，稳态 <em>N</em><sub>vis</sub> 往往显著小于输入值；若照输入值反解 <em>B</em><sub>conc</sub>，容量规划会把并发上限压得过低，准入控制提前拒绝请求，GPU 的解码批次长期填不满，SM 与 HBM 带宽利用率双低。识别信号很直接：实测解码期每请求 KV 字节数明显低于按输入 token 数算出的值，且批次规模在显存尚有可观余量时就被限流。此时应把 <em>N</em><sub>vis</sub> 换成压缩后的稳态值重算，而不是去调大显存预算。</p>\n<p>反向误用同样致命：只按稳态式分配显存，不预留视觉编码器激活与跨模态注意力的临时缓冲。视觉编码器在 prefill 时对高分辨率输入产生的激活量随分辨率与 patch 数增长，跨模态注意力还要额外的中间张量，这些都不在 <em>M</em><sub>KV</sub> 里。稳态式描述的是解码期的均值占用，而调度器面对的是峰值。若把 <em>M</em><sub>avail</sub> 全部按稳态式切给 KV 块，长分辨率请求一到，峰值瞬间越过预算，触发 OOM 或迫使框架回退、重调度，已入批请求的解码被打断。识别方式是盯住 prefill 阶段的显存水位曲线：稳态段平缓、prefill 段尖峰，尖峰高度与输入分辨率正相关。工程对策是在 <em>M</em><sub>avail</sub> 中显式扣除一个随最大分辨率标定的峰值储备，再反解并发。</p>\n<div class=\"formula\">$$B_{\\mathrm{conc}}^{\\mathrm{safe}} \\;=\\; \\frac{M_{\\mathrm{avail}} - M_{\\mathrm{peak}}^{\\mathrm{vis}} - M_{\\mathrm{frag}}}{2\\,\\ell\\,d_{\\mathrm{kv}}\\,b\\,(N_{\\mathrm{vis}}^{\\mathrm{steady}} + N_{\\mathrm{txt}})}$$</div>\n<p>第三个误用出现在启用 PagedAttention 或 INT8 KV 量化之后仍沿用 <em>b</em>=2 与理想占用率。分页带来块内尾部浪费与块表开销，量化带来 scale/zero-point 的附加字节与反量化路径的额外带宽；实际可用并发低于按 <em>b</em>=2、占用率 1 算出的值。识别信号是分配器报告的“已分配块数 × 块容量”持续高于逻辑 KV 字节数，且该比值随请求长度分布变宽而上升。此时 <em>b</em> 与占用率都必须替换为实测值，而不是继续用公式的理论值做准入判断。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>代入的错误量</th><th>系统后果</th><th>识别信号</th></tr></thead><tbody><tr><td>输入 token 当稳态</td><td><em>N</em><sub>vis</sub> 取输入值</td><td>并发上限低估、批次填不满</td><td>解码期实测 KV 远低于计算值</td></tr><tr><td>稳态当峰值</td><td>不扣视觉激活缓冲</td><td>prefill 尖峰 OOM、请求被打断</td><td>显存水位呈尖峰、随分辨率升高</td></tr><tr><td>沿用理论 <em>b</em></td><td><em>b</em>=2、占用率 1</td><td>实际并发低于计算值</td><td>分配块容量/逻辑字节比偏高</td></tr></tbody></table>\n<p>给一个反例：某多模态服务按输入分辨率切出的视觉 token 数配置并发上限，同时把 HBM 余量全部划给 KV 块。上线后短文本、低分辨率请求的批次长期只有计算值的一小部分，利用率不足；而一旦有高分辨率请求进入 prefill，显存尖峰越过预算，触发 OOM 并连带打断同批其他请求的解码。根因不是公式错，而是两处代入错：<em>N</em><sub>vis</sub> 用了输入值而非稳态值，<em>M</em><sub>avail</sub> 没有扣除峰值储备。修正路径是把稳态式用于容量反解、把峰值项单独列为准入约束，两者分开管理，而不是用一个数字同时承担均值与峰值两种职责。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>\\ell</td><td>LLM 解码器层数</td></tr><tr><td>d_{\\mathrm{kv}}</td><td>每层 KV 头维度总和（num_kv_heads × head_dim）</td></tr><tr><td>b</td><td>每元素字节数（FP16 为 2，INT8 为 1）</td></tr><tr><td>N_{\\mathrm{vis}}</td><td>每请求视觉 token 数</td></tr><tr><td>N_{\\mathrm{txt}}</td><td>每请求文本 token 数</td></tr><tr><td>B_{\\mathrm{conc}}</td><td>并发批大小</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-multimodal-kv-cache · 共 5 个片段</p>\n"},{"id":"th-vlm-batch-latency","title":"多模态批调度时延模型","direction":"dir-multimodal-quantization","prereq":[],"plain":"多模态请求的端到端时延由视觉编码、prefill 与逐 token 解码三段串行叠加，批调度需在视觉段与解码段之间做流水重叠，否则视觉编码的固定开销会直接抬高尾延迟。","definition":"多模态请求的端到端时延由视觉编码、prefill 与逐 token 解码三段串行叠加，批调度需在视觉段与解码段之间做流水重叠，否则视觉编码的固定开销会直接抬高尾延迟。","formula":"$$T_{\\mathrm{e2e}} \\;=\\; \\underbrace{\\frac{F_{\\mathrm{vis}}}{P_{\\mathrm{eff}}}}_{T_{\\mathrm{enc}}} \\;+\\; \\underbrace{\\frac{2\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\,\\ell\\,d}{P_{\\mathrm{eff}}}}_{T_{\\mathrm{prefill}}} \\;+\\; N_{\\mathrm{out}}\\,\\underbrace{\\frac{M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}}{P_{\\mathrm{eff}}}}_{T_{\\mathrm{dec}}}$$","variables":[{"sym":"F_{\\mathrm{vis}}","meaning":"视觉编码器前向浮点运算量"},{"sym":"N_{\\mathrm{out}}","meaning":"生成输出 token 数"},{"sym":"M_{\\mathrm{KV}}","meaning":"单请求 KV cache 字节数"},{"sym":"P_{\\mathrm{eff}}","meaning":"Blackwell 实测有效算力"}],"derivation":"推导关键一步：解码段按带宽受限建模，每生成一个 token 需读取 $M_{\\mathrm{KV}}$ 字节 KV，故单 token 时间为 $M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$，乘以 $N_{\\mathrm{out}}$ 得解码总时延；prefill 段按算力受限计，视觉段独立成项。","example":"用途：调度器可用该式比较“先编码后批 prefill”与“视觉段与解码段流水重叠”两种策略的尾延迟差，决定是否把视觉编码放入独立 CUDA 流并与上一批解码重叠，以压低 P99。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["解码段按带宽受限的 KV 读取建模，当 batch 大到转为算力受限时 T_dec 需改用算力项，模型会低估大 batch 时延","假设视觉编码与 LLM prefill 串行执行；若采用分离式预填/解码或跨阶段并行（如 Nova 式流水），需减去重叠节省项","未建模排队时延，SLO 尾延迟需叠加调度器队列等待与抢占开销"],"system_note":"常见误用：忽略排队时延，仅用三段串行和估计 SLO 尾延迟，实际调度器队列等待与抢占开销使 P99 显著高于模型值；在大 batch 下仍用带宽受限项，低估解码时延。","papers":["paper-an-image-is-worth-16x16-words-transf-2020"],"facts":["直觉：多模态请求的端到端时延由视觉编码、prefill 与逐 token 解码三段串行叠加，批调度需在视觉段与解码段之间做流水重叠，否则视觉编码的固定开销会直接抬高尾延迟。","公式 $$T_{\\mathrm{e2e}} = \\frac{F_{\\mathrm{vis}}}{P_{\\mathrm{eff}}} + \\frac{2\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\,\\ell\\,d}{P_{\\mathrm{eff}}} + N_{\\mathrm{out}}\\,\\frac{M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}}{P_{\\mathrm{eff}}}$$ 中，$F_{\\mathrm{vis}}$ 为视觉编码器前向浮点运算量，$P_{\\mathrm{eff}}$ 为 Blackwell 实测有效算力，$N_{\\mathrm{out}}$ 为生成输出 token 数，$M_{\\mathrm{KV}}$ 为单请求 KV cache 字节数，$\\mathrm{BW}_{\\mathrm{HBM}}$ 为显存带宽。","推导关键一步：解码段按带宽受限建模，每生成一个 token 需读取 $M_{\\mathrm{KV}}$ 字节 KV，故单 token 时间为 $M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$，乘以 $N_{\\mathrm{out}}$ 得解码总时延；prefill 段按算力受限计，视觉段独立成项。","适用边界：解码段按带宽受限的 KV 读取建模，当 batch 大到转为算力受限时 $T_{\\mathrm{dec}}$ 需改用算力项，模型会低估大 batch 时延；假设视觉编码与 LLM prefill 串行执行；若采用分离式预填/解码或跨阶段并行（如 Nova 式流水），需减去重叠节省项。","用途：调度器可用该式比较“先编码后批 prefill”与“视觉段与解码段流水重叠”两种策略的尾延迟差，决定是否把视觉编码放入独立 CUDA 流并与上一批解码重叠，以压低 P99。","常见误用：忽略排队时延，仅用三段串行和估计 SLO 尾延迟，实际调度器队列等待与抢占开销使 P99 显著高于模型值；在大 batch 下仍用带宽受限项，低估解码时延。"],"anchors":["Blackwell 实测有效算力","Nova 式流水"],"pitfalls":["只按串行三段和设定 SLO，未叠加调度器队列等待与抢占开销，上线后 P99 尾延迟系统性超标。","在大 batch 场景仍用带宽受限解码项估算，忽略转为算力受限后单 token 时间上升，容量规划偏乐观。","未实现视觉编码与解码的流水重叠，视觉段固定开销逐批串行累加，长视频请求下尾延迟被显著抬高。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-1\">一 · 一句话直觉与它真正想约束的东西</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-2\">二 · 为什么需要这个模型：三段受限资源不同</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-3\">三 · 各变量的工程含义与取值纪律</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-4\">四 · 常见误解：把串行和当成尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-5\">五 · 失效条件与它在调度决策中的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-6\">六 · 边界在哪里：串行三段和的成立条件与三类失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-7\">七 · 三项各自的量纲与“谁除谁”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-8\">八 · 解码项为何按带宽受限推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-9\">九 · 离散化：从“一个请求”到“一个 batch”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-10\">十 · 失效条件的数学来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-11\">十一 · 一个具体例子：长视频请求的尾延迟拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-12\">十二 · 近似边界与工程用法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-13\">十三 · 三段串行式的适用边界：从带宽受限到算力受限的切换点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-14\">十四 · 边界条件：公式在什么情况下会骗你</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-15\">十五 · 串行三段假设的适用域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-16\">十六 · 解码段带宽受限建模的失效点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-17\">十七 · 未建模的排队与抢占开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-18\">十八 · 规模上限：batch、序列与显存三重约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-19\">十九 · 失效条件的工程判别清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-20\">二十 · 公式失效的四个断点：从带宽受限到算力受限、串行假设、重叠项与排队时延</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-21\">二十一 · 从时延式反解批大小：带宽受限区的闭式解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-22\">二十二 · 定并行度：用 prefill 项切分 TP 与 PP</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-23\">二十三 · 定 KV 预算：把 SLO 翻译成字节配额</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-24\">二十四 · 定 SLO：串行和只是下界，尾延迟要加队列项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-25\">二十五 · 算例：一条长视频请求的容量决策链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-26\">二十六 · 决策顺序与模型失效的自检</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-27\">二十七 · 把三段串行式当作容量决策工具时的边界与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-28\">二十八 · 把串行三段和当成 SLO 承诺：排队项缺席的后果</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-29\">二十九 · 大 batch 下沿用带宽受限解码项：容量规划的乐观偏差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-30\">三十 · 视觉段与解码段不重叠：固定开销逐批累加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-31\">三十一 · 一个反例：把三段和当容量公式的调度器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-32\">三十二 · 把串行三段和当成 SLO 承诺：三类典型误用与一个反例</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-vlm-batch-latency-sec-33\">三十三 · 把串行和当 SLO：三类误用与一条反例</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:533px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 532.8 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：多模态请求的端到端时延由视觉编码、prefill 与逐 token…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$T_{\\mathrm{e2e}} \\;=\\; \\underbr…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：解码段按带宽受限的 KV 读取建模，当 batch 大到转为算力受…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-vlm-batch-latency-sec-1\">一 · 一句话直觉与它真正想约束的东西</h3>\n<p>多模态请求的端到端时延由视觉编码、prefill 与逐 token 解码三段串行叠加，批调度需在视觉段与解码段之间做流水重叠，否则视觉编码的固定开销会直接抬高尾延迟。这句话的重点不在“三段相加”这个算术事实，而在最后半句：视觉段是一个与输出长度无关的固定开销，而解码段是一个与输出长度成正比的线性开销，两者在调度器里争夺同一块 SM 资源时，固定开销会以“每批一次”的频率反复插入解码流，把本可连续的 token 间隔切成碎片。所谓“时延模型”，本质是把这三段各自的受限资源写清楚，从而判断哪一段该被重叠、哪一段该被推迟、哪一段该被拆出去。</p>\n<p>严格定义：对单个多模态请求 $r$，记其视觉输入产生的编码器前向浮点量为 $F_{\\mathrm{vis}}$，视觉 token 数为 $N_{\\mathrm{vis}}$，文本 token 数为 $N_{\\mathrm{txt}}$，生成输出 token 数为 $N_{\\mathrm{out}}$，单请求 KV cache 字节数为 $M_{\\mathrm{KV}}$，Blackwell 实测有效算力为 $P_{\\mathrm{eff}}$，显存带宽为 $\\mathrm{BW}_{\\mathrm{HBM}}$。则串行三段时延模型为：</p>\n<div class=\"formula\">$$T_{\\mathrm{e2e}} \\;=\\; \\underbrace{\\frac{F_{\\mathrm{vis}}}{P_{\\mathrm{eff}}}}_{T_{\\mathrm{enc}}} \\;+\\; \\underbrace{\\frac{2\\,(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\,\\ell\\,d}{P_{\\mathrm{eff}}}}_{T_{\\mathrm{prefill}}} \\;+\\; N_{\\mathrm{out}}\\,\\underbrace{\\frac{M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}}{P_{\\mathrm{eff}}}}_{T_{\\mathrm{dec}}}$$</div>\n<p>这个定义把“时延”限定为单请求在无排队、无抢占、三段严格串行条件下的设备占用时间。它不是 SLO 尾延迟，也不是吞吐的倒数。任何把它直接当成 P99 使用的做法，都已经越出了定义域。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-2\">二 · 为什么需要这个模型：三段受限资源不同</h3>\n<p>需要它的第一个理由是三段的瓶颈资源根本不同，不能用同一个“每 token 成本”去折算。视觉段 $T_{\\mathrm{enc}}$ 由 $F_{\\mathrm{vis}}/P_{\\mathrm{eff}}$ 决定，是纯算力受限项，与 batch 内其他请求的解码进度无关；prefill 段按算力受限计，正比于 $N_{\\mathrm{vis}}+N_{\\mathrm{txt}}$ 与层数 $\\ell$、隐藏维 $d$ 的乘积；解码段则按带宽受限建模，每生成一个 token 需读取 $M_{\\mathrm{KV}}$ 字节 KV，故单 token 时间为 $M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$，乘以 $N_{\\mathrm{out}}$ 得解码总时延。三段里两项吃 SM 的 MMA 吞吐，一项吃 HBM 带宽，把它们混成一个系数就会在容量规划时系统性偏差。</p>\n<p>第二个理由是它给出了调度策略的可比较量。调度器可用该式比较“先编码后批 prefill”与“视觉段与解码段流水重叠”两种策略的尾延迟差，决定是否把视觉编码放入独立 CUDA 流并与上一批解码重叠，以压低 P99。工程上这一步很具体：在 Blackwell 上把视觉编码器放到一条独立 CUDA stream，与另一批请求的解码 kernel 并发，视觉段占用部分 SM 与 TMEM，解码段继续按带宽受限推进，重叠节省项近似为 $\\min(T_{\\mathrm{enc}},\\,T_{\\mathrm{dec}}^{\\text{prev batch}})$。没有这个式子，工程师只能凭“感觉视觉编码很快”来做决定，而长视频请求下 $F_{\\mathrm{vis}}$ 随帧数线性上升，感觉会失效。</p>\n<p>第三个理由是它把“固定开销”与“可变开销”分开记账。设批内请求数为 $B$，若视觉段不与解码重叠，则每个调度周期都被插入一次 $T_{\\mathrm{enc}}$，解码流被打断 $B$ 次量级的次数；若重叠，则这部分被吸收进上一批的解码窗口。对一个 $N_{\\mathrm{out}}$ 较小、$F_{\\mathrm{vis}}$ 较大的图生文请求，$T_{\\mathrm{enc}}$ 可能占据端到端时延的可观份额，此时“是否重叠”直接决定 P99 是落在解码段还是落在视觉段。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-3\">三 · 各变量的工程含义与取值纪律</h3>\n<table class=\"mini\"><thead><tr><th>符号</th><th>含义</th><th>取值纪律</th></tr></thead><tbody>\n<tr><td>$F_{\\mathrm{vis}}$</td><td>视觉编码器前向浮点运算量</td><td>随分辨率、帧数、patch 划分变化，是固定开销的来源</td></tr>\n<tr><td>$N_{\\mathrm{vis}}$</td><td>视觉 token 数</td><td>进入 prefill 的长度项，与 $N_{\\mathrm{txt}}$ 同权</td></tr>\n<tr><td>$N_{\\mathrm{out}}$</td><td>生成输出 token 数</td><td>解码段线性因子，长输出请求的主导项</td></tr>\n<tr><td>$M_{\\mathrm{KV}}$</td><td>单请求 KV cache 字节数</td><td>决定单 token 读取量，是带宽受限建模的核心</td></tr>\n<tr><td>$P_{\\mathrm{eff}}$</td><td>Blackwell 实测有效算力</td><td>必须用实测值而非峰值，峰值会低估三段时延</td></tr>\n</tbody></table>\n<p>取值纪律里最容易被忽视的是 $P_{\\mathrm{eff}}$。用峰值算力代入，$T_{\\mathrm{enc}}$ 与 $T_{\\mathrm{prefill}}$ 都会被压到不真实的水平，模型给出的结论会偏向“视觉段可以忽略”，从而掩盖重叠的必要性。反过来，若 $M_{\\mathrm{KV}}$ 只按理论字节数计而不含对齐与分页开销，$T_{\\mathrm{dec}}$ 会被低估，容量规划偏乐观。这两个方向的误差不会互相抵消，因为它们作用在不同段上。</p>\n<p>另一个纪律是 $N_{\\mathrm{vis}}$ 与 $N_{\\mathrm{txt}}$ 的可加性。prefill 项写成 $2(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\ell d/P_{\\mathrm{eff}}$，隐含假设视觉 token 与文本 token 在注意力计算中同构；若视觉侧采用了特殊的位置编码或跨模态注意力结构，这一项需要按实际算子重算，而不能直接套用文本 prefill 的系数。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-4\">四 · 常见误解：把串行和当成尾延迟</h3>\n<p>最常见误用是忽略排队时延，仅用三段串行和估计 SLO 尾延迟，实际调度器队列等待与抢占开销使 P99 显著高于模型值。这是模型定义域之外的部分：$T_{\\mathrm{e2e}}$ 描述的是请求一旦开始执行后的设备时间，而 P99 还包含它在队列里等待 batch 成形的时长、被更高优先级请求抢占后重新排队的时间、以及因显存不足被驱逐后重算的时间。工程判断上，尾延迟预算应当写成 $T_{\\mathrm{e2e}} + T_{\\mathrm{queue}} + T_{\\mathrm{preempt}}$，后两项由调度器策略与显存水位决定，不能由这个式子给出。</p>\n<p>第二个误解是在大 batch 下仍用带宽受限项，低估解码时延。解码段按带宽受限的 KV 读取建模，当 batch 大到转为算力受限时 $T_{\\mathrm{dec}}$ 需改用算力项，模型会低估大 batch 时延。机理很直接：单 token 时间写成 $M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$ 时，隐含假设 KV 读取是唯一瓶颈；当并发序列数上升，MMA 与注意力算子的算力需求随之上升，解码从带宽受限滑向算力受限，单 token 时间不再由 $M_{\\mathrm{KV}}$ 单独决定。此时若继续用带宽项做容量规划，会得出“batch 越大单位成本越低”的乐观曲线，而实际曲线在某个 batch 之后开始上翘。</p>\n<p>第三个误解是把“视觉编码很快”当成普适结论。$T_{\\mathrm{enc}}$ 正比于 $F_{\\mathrm{vis}}$，而 $F_{\\mathrm{vis}}$ 随视觉输入规模上升；对短图像请求，$T_{\\mathrm{enc}}$ 可能确实小于单 token 解码时间，但对长视频请求，$F_{\\mathrm{vis}}$ 可以远超 $N_{\\mathrm{out}}\\cdot M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$，此时视觉段成为端到端时延的主项。未实现视觉编码与解码的流水重叠，视觉段固定开销逐批串行累加，长视频请求下尾延迟被显著抬高。判断依据应当是 $T_{\\mathrm{enc}}$ 与 $T_{\\mathrm{dec}}$ 的量级比较，而不是对“视觉编码”这个阶段的笼统印象。</p>\n<p>第四个误解是把模型当成吞吐模型用。$T_{\\mathrm{e2e}}$ 是单请求时间，吞吐是批内请求数除以批周期时间；两者在 batch 增大时朝相反方向变化，用 $T_{\\mathrm{e2e}}$ 的下降去推断吞吐上升，会在解码转为算力受限后失效。调度器需要的是两个量分开算：单请求时延用于 SLO 判定，批周期时间用于吞吐与显存周转。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-5\">五 · 失效条件与它在调度决策中的位置</h3>\n<p>模型的适用边界必须写在调度器代码旁边，而不是写在文档里。解码段按带宽受限的 KV 读取建模，当 batch 大到转为算力受限时 $T_{\\mathrm{dec}}$ 需改用算力项，模型会低估大 batch 时延；假设视觉编码与 LLM prefill 串行执行；若采用分离式预填/解码或跨阶段并行（如 Nova 式流水），需减去重叠节省项；未建模排队时延，SLO 尾延迟需叠加调度器队列等待与抢占开销。这四条里，前两条影响数值，后两条影响结论方向。</p>\n<p>在调度决策中，这个式子的角色是“分段预算表”而非“总时延预测器”。工程做法是：先用 $T_{\\mathrm{enc}}$ 判断视觉段是否值得独立成流，再用 $T_{\\mathrm{prefill}}$ 判断视觉 token 与文本 token 合并批是否撑爆 prefill 窗口，最后用 $T_{\\mathrm{dec}}$ 判断解码 batch 是否已越过带宽受限区间。三个判断各自有独立的阈值，混在一起做单点优化会顾此失彼。举例：一个以图像问答为主、$N_{\\mathrm{out}}$ 很短的负载，$T_{\\mathrm{dec}}$ 占比小，优化重点应放在把 $T_{\\mathrm{enc}}$ 与上一批解码重叠；而一个以长视频描述为主、$N_{\\mathrm{out}}$ 较长的负载，$T_{\\mathrm{dec}}$ 主导，重点转为控制解码 batch 不越过带宽受限拐点，同时避免视觉段串行插入打断解码节奏。</p>\n<p>把这三段写成可观测的三个计时器——视觉段 kernel 时间、prefill kernel 时间、解码每 token 时间——并与模型预测逐批比对，是发现失效条件的最直接手段。当实测解码单 token 时间开始高于 $M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$ 的预测值，就是解码转入算力受限的信号；当实测端到端时间与三段和之差随并发上升而扩大，就是排队项开始主导的信号。这两个偏差方向不同，修正手段也不同：前者调 batch 上限，后者调调度器队列与优先级策略。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-6\">六 · 边界在哪里：串行三段和的成立条件与三类失效</h3>\n<p>这个时延模型的价值不在于“算得准”，而在于它把多模态请求拆成三段可独立归因的串行项：视觉编码的固定算力开销、prefill 的算力开销、解码的带宽开销。它的隐含前提是<strong>三段严格串行且互不重叠</strong>，并且每一段都落在各自的主导资源上——视觉段与 prefill 段按算力受限计，解码段按带宽受限计。一旦调度器把视觉编码放进独立 CUDA 流、与上一批的解码重叠（即事实中提到的 Nova 式流水），模型就必须减去重叠节省项，否则会把实际尾延迟估高；反过来，如果调度器根本没做这层重叠，视觉段的固定开销就会逐批串行累加，长视频请求下 P99 被显著抬高。换句话说，公式描述的是“无流水重叠的串行基线”，它既是容量规划的下界参照，也是判断“要不要上流水”的比较基准。</p>\n<p>第一类失效来自解码段的资源切换。单 token 时间被建模为 $M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$，本质是假设每步解码都在等 KV cache 从 HBM 读进来，算力有富余。当 batch 被连续批处理推到足够大、KV 读取与 MMA 计算开始争抢同一份有效算力时，解码转为算力受限，真实的单 token 时间随 batch 上升而抬升，而模型仍按常数估计，于是大 batch 下的解码总时延被系统性低估，容量规划偏乐观。工程判断很直接：把 batch 上限作为该模型的适用域边界写进调度器配置，超过边界就切换到算力项估算，或用实测的单 token 时间曲线做分段拟合。</p>\n<p>第二类失效来自排队。三段串行和只覆盖请求“被调度上之后”的执行时间，不含调度器队列等待与抢占开销。若直接用 $T_{\\mathrm{e2e}}$ 设定 SLO，上线后 P99 会系统性超标——因为尾延迟的构成里，队列等待往往与执行时间同量级，尤其在视觉段占住 SM 导致解码批被挤出的时刻。第三类失效更隐蔽：模型把视觉编码器前向浮点量 $F_{\\mathrm{vis}}$ 当作与分辨率、帧数线性相关的量，但真实视觉编码器在变长输入上的有效算力利用率并不恒定，padding 与分块策略会改变 $P_{\\mathrm{eff}}$ 的实际取值。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>模型偏差方向</th><th>系统代价</th></tr></thead><tbody><tr><td>大 batch 解码转算力受限</td><td>低估 $T_{\\mathrm{dec}}$</td><td>容量规划偏乐观，SLO 超标</td></tr><tr><td>未叠加队列等待与抢占</td><td>低估 P99</td><td>尾延迟系统性超标</td></tr><tr><td>已做视觉/解码流水重叠</td><td>高估 $T_{\\mathrm{e2e}}$</td><td>过度预留算力，吞吐浪费</td></tr></tbody></table>\n<p>因此这个模型的正确用法是“带条件的比较器”：在同一组 $(F_{\\mathrm{vis}}, N_{\\mathrm{vis}}, N_{\\mathrm{txt}}, N_{\\mathrm{out}}, M_{\\mathrm{KV}})$ 下比较“先编码后批 prefill”与“视觉段与解码段流水重叠”两种策略的尾延迟差，据差值决定是否把视觉编码放入独立 CUDA 流。它不适合直接当作 SLO 承诺值的计算器——那需要在三段和之上再叠加调度器队列等待项与抢占开销项，而这两项只能由调度器的实测队列深度与抢占频率给出，不能由公式本身推出。</p>\n<h3 id=\"th-vlm-batch-latency-sec-7\">七 · 三项各自的量纲与“谁除谁”</h3>\n<p>公式的三项不是随手拼出来的，每一项都对应一个可独立测量的物理过程，且量纲统一为秒。第一项 $F_{\\mathrm{vis}}/P_{\\mathrm{eff}}$ 是纯算力项：分子是视觉编码器前向的浮点运算次数（FLOPs），分母是 Blackwell 在目标精度下实测的有效算力（FLOP/s），商即时间。第二项 $2(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\ell d / P_{\\mathrm{eff}}$ 同样是算力项，分子是 prefill 阶段对视觉 token 与文本 token 合计做前向的乘加量——系数 2 来自每个权重参与一次乘与一次加，$\\ell$ 为层数、$d$ 为隐藏维，$(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})$ 为参与注意力的序列长度。第三项 $N_{\\mathrm{out}}\\cdot M_{\\mathrm{KV}}\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$ 的量纲需要特别小心：$M_{\\mathrm{KV}}$ 是字节，$\\mathrm{BW}_{\\mathrm{HBM}}$ 是字节/秒，二者相除得秒，再乘 $N_{\\mathrm{out}}$ 得解码总时间。注意这里 $\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$ 在形式上是一个“每 FLOP 对应的字节数”的倒数式比值，它把带宽与算力两个硬件参数压缩成一个可复用的单 token 时间尺度，这正是该式能被调度器直接调用的原因。</p>\n<p>三项相加的物理含义是“串行不重叠”。视觉编码在前，prefill 在中，解码在后，每一段都必须等前一段完全结束才能开始。这个假设在单请求、单流场景下成立，但在连续批处理下立刻失效——这正是后面要处理的离散化问题。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-8\">八 · 解码项为何按带宽受限推导</h3>\n<p>解码段的关键推导步是：自回归每生成一个 token，需要把该请求全部历史 KV 从 HBM 读回片上，参与一次注意力计算。此时计算量极小（一个 token 的 Q 只与历史 K/V 做点积），而数据搬运量是 $M_{\\mathrm{KV}}$ 字节，因此单 token 的耗时由“读 $M_{\\mathrm{KV}}$ 字节所需时间”主导，即 $M_{\\mathrm{KV}}\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$。写成伪代码思路：</p>\n<div class=\"formula\">$$\\text{for } t \\in [1, N_{\\mathrm{out}}]:\\quad t_{\\mathrm{token}} \\approx \\frac{\\text{bytes}(KV_{1:t})}{\\text{effective bandwidth}}$$</div>\n<p>把 $\\text{bytes}(KV_{1:t})$ 近似为常数 $M_{\\mathrm{KV}}$（即按最终 KV 规模计），就得到线性于 $N_{\\mathrm{out}}$ 的解码总时延。这个近似的代价是：早期 token 的实际 KV 更小，模型对短输出略微高估；但工程上关心的是长输出与尾延迟，取上界反而更安全。</p>\n<p>系统代价层面，这一项直接暴露了显存带宽是解码的硬约束。以 GB200 NVL72 单 GPU 的 HBM 带宽为量级参照，$M_{\\mathrm{KV}}$ 每增加一倍，单 token 时间近似翻倍；这就是为什么 KV cache 的字节数（见多模态 KV cache 显存式那一条）会直接进入时延公式，而不是只影响显存占用。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-9\">九 · 离散化：从“一个请求”到“一个 batch”</h3>\n<p>上面的公式是单请求连续时间模型。调度器真正操作的是离散的 batch step：每个 step 处理 $B$ 个请求、每个请求生成 1 个 token。离散化发生在两处。第一处是解码项：连续式中的 $N_{\\mathrm{out}}$ 乘以单 token 时间，在批处理下应改写为“每 step 时间 × step 数”，而每 step 时间不再由单请求 $M_{\\mathrm{KV}}$ 决定，而由 batch 内 KV 总字节数 $\\sum_i M_{\\mathrm{KV},i}$ 决定。于是解码段出现一个 batch 级带宽项：</p>\n<div class=\"formula\">$$T_{\\mathrm{dec}}^{\\mathrm{batch}} \\approx \\left\\lceil \\frac{N_{\\mathrm{out}}^{\\max}}{\\text{tokens per step}} \\right\\rceil \\cdot \\frac{\\sum_i M_{\\mathrm{KV},i}\\,\\mathrm{BW}_{\\mathrm{HBM}}}{P_{\\mathrm{eff}}}$$</div>\n<p>第二处是 prefill 项：连续式假设一次 prefill 处理全部 $(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})$，而 chunked prefill 会把长序列切成若干块，每块与解码 step 交错执行。离散化后 prefill 的算力项被摊到多个 step 上，单 step 的算力占用上升，但整体墙钟时间不一定下降——这正是 chunk 大小需要调参的原因。</p>\n<p>离散化带来的近似误差集中在两点：向上取整（$\\lceil\\cdot\\rceil$）使短输出请求的 step 数被高估；batch 内请求长度不齐时，$\\sum_i M_{\\mathrm{KV},i}$ 随 step 推进动态增长，用固定值代入会低估后段 step 的耗时。工程判断是：容量规划用最终 KV 规模代入求上界，在线调度用实时 $\\sum_i M_{\\mathrm{KV},i}$ 求即时 step 预算。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-10\">十 · 失效条件的数学来源</h3>\n<p>公式标注的失效条件不是经验之谈，每一条都能从推导假设反推。第一条“batch 大到转为算力受限”：解码项推导的前提是算术强度低于硬件拐点，即每字节搬运对应的 FLOP 数小于 $\\mathrm{Peff}/\\mathrm{BW}_{\\mathrm{HBM}}$。当 batch 增大，同一份权重被更多请求复用，算术强度上升，越过拐点后单 token 时间由算力而非带宽决定，此时应把 $M_{\\mathrm{KV}}\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$ 替换为 $2 N_{\\mathrm{ctx}} \\ell d / P_{\\mathrm{eff}}$ 形式的算力项。继续用带宽项会系统性低估大 batch 时延，容量规划偏乐观。</p>\n<p>第二条“视觉编码与 prefill 串行”：公式三项直接相加，隐含无重叠。若把视觉编码放进独立 CUDA 流、与上一批的解码 step 重叠（Nova 式流水），则实际时延需减去重叠节省项 $\\Delta_{\\mathrm{overlap}}$，其上限为 $\\min(T_{\\mathrm{enc}}, T_{\\mathrm{dec}}^{\\mathrm{batch}})$。不减这一项，模型会把流水带来的收益全部漏算，导致调度器误判“不值得做流水”。</p>\n<p>第三条“未建模排队时延”：三项串行和是服务时间，不是响应时间。SLO 尾延迟等于服务时间加队列等待加抢占开销。P99 场景下，队列等待往往与服务时间同量级，仅用三段和估 SLO 必然偏低——这是上线后 P99 系统性超标的最常见根因。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-11\">十一 · 一个具体例子：长视频请求的尾延迟拆解</h3>\n<p>设一个长视频请求产生大量视觉 token，$N_{\\mathrm{vis}}$ 远大于 $N_{\\mathrm{txt}}$，$N_{\\mathrm{out}}$ 中等。按公式拆解：$T_{\\mathrm{enc}}$ 由 $F_{\\mathrm{vis}}$ 决定，是固定开销，与 batch 无关；$T_{\\mathrm{prefill}}$ 中 $N_{\\mathrm{vis}}$ 主导，随视觉 token 数线性增长；$T_{\\mathrm{dec}}$ 随 $N_{\\mathrm{out}}$ 线性增长。若调度器把该请求与一批短文本请求混批，短请求的 prefill 很快完成，但长视频的视觉段仍在占用算力，短请求的解码 step 被迫等待——尾延迟被视觉段的固定开销抬高。此时正确的工程动作不是调大 batch，而是把视觉编码移出主批、放入独立流与上一批解码重叠，用 $\\Delta_{\\mathrm{overlap}}$ 抵掉 $T_{\\mathrm{enc}}$ 的一部分。模型给出的判断依据正是：当 $T_{\\mathrm{enc}}$ 在 $T_{\\mathrm{e2e}}$ 中占比显著时，流水重叠的收益大于增大 batch 的收益。</p>\n<p>反过来，若 $N_{\\mathrm{out}}$ 很大而 $N_{\\mathrm{vis}}$ 很小（长文本续写型多模态请求），$T_{\\mathrm{dec}}$ 主导，此时优化重点落在 KV 读取带宽与 batch 内 KV 总量上，视觉段流水几乎无收益。同一公式在不同请求形态下给出不同的优化排序，这是它作为调度决策工具的价值所在。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-12\">十二 · 近似边界与工程用法</h3>\n<p>该式的适用边界可以归纳为三条可检验的判据：其一，解码算术强度是否低于硬件拐点——低于则带宽项成立，高于则必须换算力项；其二，视觉段与解码段是否真的串行——若已实现跨流重叠，必须显式减去 $\\Delta_{\\mathrm{overlap}}$；其三，是否只估服务时间——若用于 SLO，必须叠加队列等待与抢占开销。三条判据中任何一条不满足，公式的输出就只能当作下界而非估计值。</p>\n<p>工程上把它当作“分段预算表”而非“端到端预测器”更稳妥：用 $T_{\\mathrm{enc}}$ 判断视觉段是否值得独立成流，用 $T_{\\mathrm{prefill}}$ 判断 chunk 切分与视觉 token 压缩的收益，用 $T_{\\mathrm{dec}}$ 判断 KV 规模与 batch 上限。三项各自对应一个可独立调优的旋钮，而三项之和只在串行假设成立时才等于真实时延。调度器的实际动作应落在“改变三项之间的重叠关系”上，而不是试图让公式精确预测每一个请求的墙钟时间。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-13\">十三 · 三段串行式的适用边界：从带宽受限到算力受限的切换点</h3>\n<p>公式把解码段写成 $N_{\\mathrm{out}}\\cdot M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$，这一步的物理含义是：每生成一个 token，SM 要把该请求全部 KV cache 从 HBM 读进片上，读取字节数 $M_{\\mathrm{KV}}$ 随上下文线性增长，而单 token 时间正比于这笔字节流量。这个建模只在<b>带宽受限</b>区成立——即 batch 内所有请求的 KV 读取总字节量尚未把 HBM 带宽打满、SM 的 MMA 单元处于等待供数状态。一旦连续批处理把 batch 推到足够大，KV 读取被多个请求分摊、权重与激活的复用率上升，解码段就翻入<b>算力受限</b>区，此时单 token 时间由 tcgen05 MMA 的吞吐与 TMEM 占用决定，而非由 $\\mathrm{BW}_{\\mathrm{HBM}}$ 决定。用带宽项外推大 batch 会系统性低估 $T_{\\mathrm{dec}}$：batch 越大，低估越严重，容量规划随之偏乐观。工程上的判断是给解码段加一个切换判据——比较每 token 的 KV 字节量与有效算力折算出的等价字节吞吐，取两者较大者作为 $T_{\\mathrm{dec}}$ 的单 token 代价，而不是无条件使用带宽项。</p>\n<p>第二个边界在串行假设。公式三项直接相加，隐含视觉编码与 LLM prefill 严格串行、且视觉段不与其他批次的解码重叠。真实调度器若把视觉编码放进独立 CUDA 流，让它与上一批的解码在时间上重叠，则端到端时延应减去重叠节省项：设视觉段时长为 $T_{\\mathrm{enc}}$、可被掩盖的比例为 $\\rho\\in[0,1]$，则修正为 $T_{\\mathrm{e2e}}' = T_{\\mathrm{e2e}} - \\rho\\,T_{\\mathrm{enc}}$。$\\rho$ 取决于视觉段与解码段对 SM、HBM 带宽与 TMEM 的争用程度：视觉编码器多为卷积/注意力混合负载，与解码的 KV 读取争抢 HBM 带宽，因此 $\\rho$ 不会接近 1；在分离式预填/解码或 Nova 式跨阶段流水中，重叠发生在不同 GPU 池之间，$\\rho$ 由阶段间传输时延与流水深度决定，需按实际流水配置测量而非套用固定值。这条修正项是调度器比较“先编码后批 prefill”与“视觉段与解码流水重叠”两种策略尾延迟差的唯一抓手。</p>\n<p>第三个边界是排队时延的缺位。公式描述的是单请求在资源空闲时的服务时间，而 SLO 关心的是 P99 端到端时延，其中包含调度器队列等待与抢占开销。多模态请求的视觉段时长方差大（图像分辨率、视频帧数差异），批调度器为保持解码段 batch 稳定，往往把长视觉请求推迟入批，队列等待被放大。设队列等待为 $W_q$、抢占重算开销为 $R_p$，则尾延迟估计应为 $T_{\\mathrm{e2e}}' + W_q + R_p$，而 $W_q$ 随到达率与视觉段方差非线性上升。仅用三段和设定 SLO 的典型失败模式是上线后 P99 系统性超标：模型值看似留有余量，实际被队列与抢占吃掉。</p>\n<table class=\"mini\"><thead><tr><th>建模项</th><th>成立条件</th><th>失效后的偏差方向</th><th>系统代价落点</th></tr></thead><tbody><tr><td>$T_{\\mathrm{dec}}$ 带宽项</td><td>batch 小、KV 读取未打满 HBM</td><td>大 batch 低估解码时延</td><td>容量规划偏乐观，吞吐承诺落空</td></tr><tr><td>三段直接相加</td><td>视觉与 prefill 串行、无跨批重叠</td><td>已做流水时高估时延</td><td>误判是否需要独立 CUDA 流</td></tr><tr><td>不含 $W_q$、$R_p$</td><td>低到达率、视觉段方差小</td><td>P99 系统性偏低</td><td>SLO 超标，尾延迟不可控</td></tr></tbody></table>\n<p>离散化与近似还藏在 $N_{\\mathrm{out}}$ 这一项里：解码是逐 token 迭代，$N_{\\mathrm{out}}$ 是离散计数而非连续量，公式把它当作可乘的标量，等价于假设每 token 代价恒定。实际中首个 token 之后存在 KV 增长导致的单 token 时间漂移，长输出请求的后段 token 更贵；把 $N_{\\mathrm{out}}$ 段拆成前段与后段两段线性近似，比单一斜率更贴近实测。同理，$F_{\\mathrm{vis}}$ 与 prefill 的 $2(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\ell d$ 都按稠密算力计，未扣除视觉 token 压缩、稀疏注意力等带来的实际算力节省，属于保守上界。调度器用该式做策略比较时，应把上述修正项作为可配置参数暴露出来，按模型形态与硬件实测标定，而不是把公式当作封闭的预测器直接喂给 SLO 判定。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-14\">十四 · 边界条件：公式在什么情况下会骗你</h3>\n<p>该式最脆弱的一环是解码项的建模前提。它把单 token 时间写成 $M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$，本质是假设解码阶段每个 token 的耗时由 KV cache 从 HBM 读回的时间主导，即带宽受限。这个假设在小 batch、长上下文时成立：此时每步要搬的 KV 字节远大于权重与激活，SM 大部分时间在等数据。但 batch 一旦增大到权重读取与 MMA 计算重新占据主导，单 token 时间就不再随 batch 线性摊薄，而是被算力项接管。此时若仍用带宽项外推，$T_{\\mathrm{dec}}$ 会被系统性低估，容量规划随之偏乐观。工程上的判别方法是看每步实际搬运字节与 tcgen05 MMA 有效算力之比：当 KV 字节数除以带宽已小于该步计算量除以 $P_{\\mathrm{eff}}$，就该切换到算力受限表达式。</p>\n<p>第二个边界是串行假设。公式把 $T_{\\mathrm{enc}}$、$T_{\\mathrm{prefill}}$、$T_{\\mathrm{dec}}$ 直接相加，隐含视觉编码器前向与 LLM prefill 不重叠。若部署采用分离式预填/解码，或把视觉编码放进独立 CUDA 流与上一批的解码步重叠（Nova 式流水），实际时延要减去重叠节省项，否则模型会高估。反过来，若未实现任何重叠，视觉段的固定开销会逐批串行累加，长视频请求下尾延迟被显著抬高——这正是公式在“先编码后批 prefill”策略下给出偏大 $T_{\\mathrm{e2e}}$、从而误导调度器放弃流式重叠的原因。</p>\n<div class=\"formula\">$$\\Delta_{\\mathrm{ovl}} = \\min\\!\\left(T_{\\mathrm{enc}},\\, N_{\\mathrm{out}}\\,T_{\\mathrm{dec}}\\right),\\quad T_{\\mathrm{e2e}}^{\\mathrm{pipe}} = T_{\\mathrm{e2e}} - \\Delta_{\\mathrm{ovl}}$$</div>\n<p>第三个边界是排队项缺失。公式只算单请求的服务时间，不含调度器队列等待与抢占开销。SLO 尾延迟必须叠加这部分：P99 由“三段串行和”与“排队+抢占”两部分共同决定，后者在高负载、长短请求混排时往往才是超标主因。只按串行三段和设定 SLO，上线后 P99 系统性超标的失败模式即源于此。因此该式的正确用法是作为服务时间的下界估计，用于比较策略差（如是否把视觉编码放入独立流），而不是直接当作 SLO 承诺值。</p>\n<table class=\"mini\"><thead><tr><th>建模项</th><th>成立前提</th><th>失效后的偏差方向</th></tr></thead><tbody><tr><td>$T_{\\mathrm{dec}}$ 带宽项</td><td>小 batch、KV 读取主导</td><td>大 batch 低估解码时延</td></tr><tr><td>三段串行相加</td><td>无跨阶段重叠</td><td>有流水时高估</td></tr><tr><td>无排队项</td><td>轻载、无抢占</td><td>P99 低估</td></tr></tbody></table>\n<h3 id=\"th-vlm-batch-latency-sec-15\">十五 · 串行三段假设的适用域</h3>\n<p>公式把 $T_{\\mathrm{enc}}$、$T_{\\mathrm{prefill}}$、$T_{\\mathrm{dec}}$ 三项直接相加，前提是这三段在同一请求内严格串行、且各段内部没有可被别的请求填充的空隙。这个前提在低并发、单请求、纯文本短 prompt 场景下成立得最好；一旦进入多模态批调度，它首先在视觉段失效。视觉编码器的 $F_{\\mathrm{vis}}$ 是固定开销，与 $N_{\\mathrm{out}}$ 无关，也不随 batch 线性摊薄——它更像一次性的入场费。当调度器把视觉编码放进独立 CUDA 流、与上一批的解码段重叠时，实际端到端时延是 $T_{\\mathrm{e2e}} - \\Delta_{\\mathrm{overlap}}$，其中 $\\Delta_{\\mathrm{overlap}} \\le \\min(T_{\\mathrm{enc}}, T_{\\mathrm{dec}}^{\\mathrm{prev}})$。公式本身不含这一项，所以它给出的是“无重叠”上界，而不是调度器实际能达到的值。判断公式是否适用的第一条准则：如果系统已经实现了视觉段与解码段的流水重叠，公式只能用来估算最坏情况，不能用来做容量规划。</p>\n<p>具体机制上，视觉编码与 LLM prefill 在 Blackwell 上共享同一批 SM 与 HBM 带宽。视觉段是算力密集的卷积/ViT 前向，prefill 是算力受限的 GEMM 加注意力，两者若并发执行会争抢 tcgen05 的 MMA 流水与 TMEM 容量，导致各自的 $P_{\\mathrm{eff}}$ 都低于单独实测值。公式用同一个 $P_{\\mathrm{eff}}$ 去除三段，隐含假设三段各自独占算力。工程上更稳妥的做法是给视觉段与 prefill 段分别标定 $P_{\\mathrm{eff}}^{\\mathrm{vis}}$ 与 $P_{\\mathrm{eff}}^{\\mathrm{llm}}$，并在并发时引入一个争抢折减系数。代价是标定工作量翻倍，收益是尾延迟估算不再系统性偏低。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-16\">十六 · 解码段带宽受限建模的失效点</h3>\n<p>公式的解码项 $N_{\\mathrm{out}} \\cdot M_{\\mathrm{KV}} \\cdot \\mathrm{BW}_{\\mathrm{HBM}} / P_{\\mathrm{eff}}$ 把每 token 时间写成 KV 读取字节数除以有效算力，本质是带宽受限近似：单请求解码时，GPU 每生成一个 token 要把整个 KV cache 读一遍，算术强度极低，时间由 HBM 带宽而非 MMA 吞吐决定。这个近似在小 batch 下很准，因为 batch 内的多个请求共享同一次权重读取，KV 读取量随 batch 线性增长，而算力利用率仍然很低。</p>\n<p>失效发生在 batch 增大到算术强度越过 roofline 拐点时。此时每 token 的 MMA 工作量随 batch 线性上升，$T_{\\mathrm{dec}}$ 转为算力受限，正确形式是 $N_{\\mathrm{out}} \\cdot \\max(M_{\\mathrm{KV}} \\cdot \\mathrm{BW}_{\\mathrm{HBM}},\\, 2 N_{\\mathrm{act}} \\ell d) / P_{\\mathrm{eff}}$，其中 $N_{\\mathrm{act}}$ 是参与计算的激活 token 规模。公式只保留了带宽项，在大 batch 下会低估单 token 时间，进而低估总时延。容量规划若按此公式反推“能塞多少并发”，会得到偏乐观的 batch 上限。判别方法很直接：用 profiler 看解码 kernel 的 HBM 吞吐是否已接近峰值、MMA 利用率是否已过半；两者同时逼近上限时，带宽项不再主导，公式失效。</p>\n<p>系统代价上，这个误判的后果是吞吐与延迟的双重错估：按带宽项算出的 batch 上限偏大，实际部署时解码段变成算力瓶颈，单 token 时间上升，P99 尾延迟超标，而调度器仍以为自己在带宽余量内。Blackwell 的 tcgen05 与 2-SM MMA 提高了单 SM 的算力密度，拐点比前代更早到来，也就是说大 batch 下带宽受限假设失效的 batch 阈值更低，公式的适用窗口更窄。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-17\">十七 · 未建模的排队与抢占开销</h3>\n<p>公式是“单请求在无竞争条件下的服务时间”，不含排队时延。真实调度器里，一个多模态请求到达后要等视觉编码槽位、等 prefill 批的空位、等解码步的调度令牌，连续批处理还会在 token 边界插入新请求、触发抢占与重算。SLO 尾延迟的正确表达是 $T_{\\mathrm{SLO}} = T_{\\mathrm{e2e}} + W_{\\mathrm{queue}} + W_{\\mathrm{preempt}}$，其中 $W_{\\mathrm{queue}}$ 是调度器队列等待，$W_{\\mathrm{preempt}}$ 是被抢占后重算的代价。公式只给了第一项。</p>\n<p>多模态场景下 $W_{\\mathrm{queue}}$ 尤其不可忽略，因为视觉段的固定开销会占住编码槽位，后续请求的视觉编码被迫排队，而这段等待不体现在任何一段的计算时间里。一个长视频请求携带大量视觉 token，它的 $T_{\\mathrm{enc}}$ 可能远超同批文本请求的 $T_{\\mathrm{prefill}}$，调度器若按 FIFO 把视觉段排在前，后面所有请求的 prefill 都被推迟。工程判断：只要系统里存在视觉 token 数方差大的请求混合，就必须把 $W_{\\mathrm{queue}}$ 单独建模，否则公式给出的 P99 会系统性偏低。常见失败模式正是“只按串行三段和设定 SLO，上线后 P99 系统性超标”。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-18\">十八 · 规模上限：batch、序列与显存三重约束</h3>\n<p>公式对 batch 规模没有任何显式约束，但它的每一项都隐含一个上限。prefill 项的 $2(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\ell d$ 随序列长度线性增长，当 $N_{\\mathrm{vis}}$ 很大时，prefill 的激活显存与注意力中间结果会挤压 KV cache 的可用空间；解码项的 $M_{\\mathrm{KV}}$ 随上下文线性增长，batch 乘以 $M_{\\mathrm{KV}}$ 就是解码阶段的常驻显存需求。三者叠加给出可行域：$B \\cdot M_{\\mathrm{KV}} + M_{\\mathrm{act}}^{\\mathrm{prefill}} \\le$ 可用 HBM。超过这个界，调度器要么降 batch，要么把请求溢出到别的实例，公式里的 $T_{\\mathrm{e2e}}$ 不再对应任何可执行的调度方案。</p>\n<p>规模上限还有一层来自并行策略。当模型跨多卡张量并行时，解码每 token 需要一次集合通信，$T_{\\mathrm{dec}}$ 里应加入通信项；NVL72 内的 NVLink 5 与 NCCL 集合通信下界决定了这一项的量级（详见通信下界条目）。公式没有这一项，所以在 TP 度较大时它低估解码时延。判断公式是否仍适用的规模准则：单卡或小 TP、batch 未越过 roofline 拐点、视觉 token 方差可控——三者同时满足时公式是可靠的容量规划工具；任一条件被打破，就需要在公式上叠加对应修正项，或改用分段实测的查找表。</p>\n<div class=\"formula\">$$T_{\\mathrm{e2e}}^{\\mathrm{valid}} = T_{\\mathrm{e2e}} - \\Delta_{\\mathrm{overlap}} + W_{\\mathrm{queue}} + W_{\\mathrm{preempt}} + T_{\\mathrm{comm}}$$</div>\n\n<h3 id=\"th-vlm-batch-latency-sec-19\">十九 · 失效条件的工程判别清单</h3>\n<p>把上述边界收敛成可操作的判别流程，调度器与容量规划团队可以在上线前逐条核对，而不是等 P99 超标后回头找原因。</p>\n<ul>\n<li>解码段是否已转为算力受限：看解码 kernel 的 HBM 吞吐与 MMA 利用率，两者同时接近峰值即公式失效，改用算力项。</li>\n<li>是否存在视觉段与解码段的流水重叠：若已实现独立 CUDA 流重叠，公式只作上界，实际值需减去 $\\Delta_{\\mathrm{overlap}}$。</li>\n<li>视觉 token 数方差是否大：方差大则 $W_{\\mathrm{queue}}$ 不可忽略，必须单独测量编码槽位的排队分布。</li>\n<li>是否跨卡张量并行：TP 度大于 1 时补通信项，量级参考 NVL72 集合通信下界。</li>\n<li>batch 是否逼近显存可行域边界：逼近时公式对应的调度方案已不可执行，需降 batch 或改分离式部署。</li>\n</ul>\n<p>这张清单的价值在于把“公式什么时候不能用”从定性直觉变成可测信号。每条都对应一个 profiler 指标或调度器计数器，不需要额外实验就能判断当前部署是否落在公式的适用域内。对于已经采用分离式预填/解码或 Nova 式流水的系统，公式的串行假设从根上不成立，此时应直接以分段实测的时延分布替代解析式，把公式降级为设计初期的量级估算工具。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-20\">二十 · 公式失效的四个断点：从带宽受限到算力受限、串行假设、重叠项与排队时延</h3>\n\n<p>该时延模型的可信区间，取决于三个建模假设是否同时成立：解码段带宽受限、三段严格串行、系统无排队。任一假设被打破，公式给出的就不再是上界而是乐观下界。最典型的断点是解码段从带宽受限转为算力受限。单 token 时间写作 $M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$ 的前提是：每步只搬 KV、算力富余。当 batch 增大，单步需要读取的 KV 总量随 batch 线性增长，而每 token 的 MMA 工作量（注意力打分与 MLP）也随之增长，但后者在 Blackwell 上受 tcgen05 与 2-SM MMA 的吞吐支撑，前者则被 HBM 带宽硬性封顶。一旦算术强度越过 roofline 拐点，单 token 时间由算力项而非带宽项决定，此时继续套用带宽项会系统性低估 $T_{\\mathrm{dec}}$。工程判断很简单：用 batch 内 KV 字节总量除以 $\\mathrm{BW}_{\\mathrm{HBM}}$ 得到带宽下界，再用 $2N_{\\mathrm{ctx}}\\ell d$ 量级的算力需求除以 $P_{\\mathrm{eff}}$ 得到算力下界，取二者较大值作为 $T_{\\mathrm{dec}}$ 的单步估计；容量规划若只取带宽项，在大 batch 高并发区间会给出偏乐观的吞吐上限。</p>\n\n<p>第二个断点是串行假设。公式把 $T_{\\mathrm{enc}}$ 与 $T_{\\mathrm{prefill}}$ 直接相加，隐含视觉编码器前向与 LLM prefill 在同一请求内不可重叠。实际部署中，视觉编码器（ViT 类）与 LLM 主干在算子形态、并行切分与显存占用上差异很大，把视觉段放进独立 CUDA 流、与上一批的解码步重叠，是压低 P99 的常规手段。此时端到端时延应减去重叠节省项：若视觉段耗时 $T_{\\mathrm{enc}}$ 完全被前一批解码窗口吸收，则该请求的 $T_{\\mathrm{e2e}}$ 中 $T_{\\mathrm{enc}}$ 项趋于零，只剩 prefill 与 decode。分离式预填/解码（PD 分离）与 Nova 式跨阶段流水同理——公式不再成立，需引入重叠系数 $\\alpha\\in[0,1]$，写成 $T_{\\mathrm{e2e}}=T_{\\mathrm{enc}}(1-\\alpha)+T_{\\mathrm{prefill}}+T_{\\mathrm{dec}}$。$\\alpha$ 的取值取决于视觉段与解码段的时长比：长视频请求 $F_{\\mathrm{vis}}$ 大、$T_{\\mathrm{enc}}$ 长，容易被解码窗口吸收，$\\alpha$ 接近 1；短图像请求 $T_{\\mathrm{enc}}$ 短，重叠收益有限。反过来，若未实现任何重叠，视觉段的固定开销会逐批串行累加，在长视频混合负载下把尾延迟显著抬高——这正是公式在“未重叠”配置下反而准确、在“已重叠”配置下反而高估的原因，调度器必须知道自己跑在哪种配置上。</p>\n\n<p>第三个断点最容易被忽视：公式完全没有排队项。$T_{\\mathrm{e2e}}$ 描述的是单请求从进入到离开计算资源的纯服务时间，而 SLO 尾延迟关心的是从请求到达到首 token 返回的墙钟时间，中间还夹着调度器队列等待、连续批处理的前向抢占、KV cache 显存不足导致的换入换出、以及多模态请求因视觉段占用 SM 而被迫延后进入解码批的等待。真实 P99 应写成 $T_{\\mathrm{P99}}\\approx T_{\\mathrm{e2e}}+W_{\\mathrm{queue}}+W_{\\mathrm{preempt}}$，其中 $W_{\\mathrm{queue}}$ 随到达率与批容量的比值非线性上升，$W_{\\mathrm{preempt}}$ 在 KV 显存逼近上限时出现阶跃。只按三段串行和设定 SLO 的失败模式非常固定：离线压测通过，上线后 P99 系统性超标，因为压测的到达率低、队列几乎为空，而生产流量的突发到达把 $W_{\\mathrm{queue}}$ 推到不可忽略的量级。</p>\n\n<p>规模上限还体现在两个隐性约束上。其一是视觉段的显存与算力争用：多模态请求在 prefill 前必须持有视觉特征，高分辨率图像与长视频使 $F_{\\mathrm{vis}}$ 与中间激活同步膨胀，batch 内视觉请求占比上升会挤压可用于 KV cache 的显存，使 $M_{\\mathrm{KV}}$ 的有效上限下降，公式中按单请求固定 $M_{\\mathrm{KV}}$ 的假设随之松动。其二是 $P_{\\mathrm{eff}}$ 本身的定义域：它是 Blackwell 实测有效算力，随精度路径（NVFP4/FP8）、是否启用 2-SM MMA、TMEM 占用率与功耗墙而变，把 $P_{\\mathrm{eff}}$ 当作常数代入跨配置比较，等于把不同精度与不同功耗状态下的时延混为一谈。适用边界的结论因此不是“公式对不对”，而是“公式在哪个配置区间内是紧的”：小 batch、纯解码、无重叠、低队列时它贴近实测；大 batch、PD 分离、视觉与解码流水、高突发到达时，它只剩量级参考价值，必须叠加算力项修正、重叠系数与排队项才能用于 SLO 承诺。</p>\n\n<table class=\"mini\">\n<thead><tr><th>假设</th><th>失效触发条件</th><th>修正方式</th><th>系统代价</th></tr></thead>\n<tbody>\n<tr><td>解码带宽受限</td><td>batch 增大、算术强度越过拐点</td><td>$T_{\\mathrm{dec}}$ 取带宽项与算力项的较大值</td><td>大 batch 吞吐被高估，容量规划偏乐观</td></tr>\n<tr><td>视觉段与 prefill 串行</td><td>独立 CUDA 流重叠、PD 分离、Nova 式流水</td><td>引入重叠系数 $\\alpha$ 减去节省项</td><td>未重叠时长视频请求尾延迟被抬高</td></tr>\n<tr><td>无排队</td><td>突发到达、KV 显存逼近上限触发抢占</td><td>叠加 $W_{\\mathrm{queue}}+W_{\\mathrm{preempt}}$</td><td>P99 系统性超标，离线压测失真</td></tr>\n</tbody>\n</table>\n<h3 id=\"th-vlm-batch-latency-sec-21\">二十一 · 从时延式反解批大小：带宽受限区的闭式解</h3>\n<p>把公式当作容量决策工具，第一步是把它对批大小 $B$ 求反。解码段在带宽受限区成立时，单 token 读取量随批线性增长，而读取带宽由 HBM 提供、与批大小无关，因此每 token 时间可写成 $B\\cdot M_{\\mathrm{KV}}\\cdot \\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$ 的形式——注意这里的 $\\mathrm{BW}_{\\mathrm{HBM}}$ 是每字节 KV 的搬运代价系数，批内所有请求的 KV 在同一个解码步里被一次性读出，故时间随 $B$ 线性上升。令 SLO 的 token 间隔预算为 $\\tau$（即解码阶段允许的单步耗时上限），则带宽受限区给出的批大小上界是</p>\n<div class=\"formula\">$$B_{\\mathrm{BW}} \\;\\le\\; \\frac{\\tau\\,P_{\\mathrm{eff}}}{M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}}$$</div>\n<p>这个式子的工程含义是：$B_{\\mathrm{BW}}$ 与单请求 KV 字节数成反比。多模态请求的 $M_{\\mathrm{KV}}$ 里既有文本 KV 也有视觉 KV，视觉 token 数量随图像分辨率或视频帧数上升，于是同一张 B200 上，纯文本请求能撑到的批大小与高分辨率图像请求能撑到的批大小不在一个量级。调度器若按文本请求标定批大小再混入视觉请求，解码步会突然越过 $\\tau$，表现为 P99 抖动。正确做法是把 $M_{\\mathrm{KV}}$ 作为请求级属性参与准入判断，而不是用全局固定批大小。</p>\n<p>代价面要同时看两侧：批大小压得过低，解码段带宽利用率不足，吞吐掉；压得过高，越过 $\\tau$ 后单步时延线性膨胀，尾延迟直接超标。这个区间在 Blackwell 上并不宽，因为 HBM 带宽虽高，但 $M_{\\mathrm{KV}}$ 在多模态场景下被视觉 token 显著放大。一个具体例子：同一批里混入若干长视频请求，其视觉 token 数远高于图像请求，若调度器只按请求数而非按总 KV 字节做批，实际解码步耗时会被最长的那条请求拖到 $\\tau$ 之外，而短请求并未获得任何加速。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-22\">二十二 · 定并行度：用 prefill 项切分 TP 与 PP</h3>\n<p>并行度决策看的是 prefill 项 $\\dfrac{2(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\,\\ell\\,d}{P_{\\mathrm{eff}}}$。这一项对 $P_{\\mathrm{eff}}$ 是线性的，意味着张量并行（TP）把 $P_{\\mathrm{eff}}$ 抬高后，prefill 时延近似按 TP 度数下降，但下降不是免费的：TP 每加一级就多一次集合通信，通信量与隐藏维度 $d$ 和层数 $\\ell$ 相关，且在多模态场景下视觉 token 使序列更长，集合通信的参与数据量更大。工程判断是：当 prefill 项在 $T_{\\mathrm{e2e}}$ 中占比高（长视觉序列、短输出），加 TP 收益明显；当解码项占主导（长输出、小 $M_{\\mathrm{KV}}$），加 TP 对解码段几乎无益，因为解码段受带宽而非算力约束，$P_{\\mathrm{eff}}$ 的提升换不来 KV 读取时间的下降。</p>\n<p>流水并行（PP）的作用不同：它把层切到不同设备，单设备上的 $\\ell$ 变小，prefill 与解码的每步时延都下降，但引入流水气泡，气泡大小与微批数量相关。对多模态请求，视觉编码段是独立项 $F_{\\mathrm{vis}}/P_{\\mathrm{eff}}$，它不随 LLM 的 PP 切分而变小，因此 PP 对含大视觉编码器的请求收益被视觉段稀释。判断准则可以写成：若 $T_{\\mathrm{enc}}$ 占 $T_{\\mathrm{e2e}}$ 的比例超过 prefill 与解码之和的某个阈值，优先把视觉编码器单独部署或做流水重叠，而不是继续加 LLM 侧的并行度。</p>\n<p>显存代价必须同步核算：TP 降低单卡权重占用但复制激活，PP 降低单卡层数但需要跨 stage 传递激活与 KV。多模态 KV 的显存式已在别处展开，此处只强调并行度选择会改变每卡 KV 预算的分配方式——TP 下 KV 按头切分到各卡，PP 下 KV 按层分布到各 stage，两种切法对 $M_{\\mathrm{KV}}$ 的每卡占用不同，直接影响第一节的 $B_{\\mathrm{BW}}$ 能否达到。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-23\">二十三 · 定 KV 预算：把 SLO 翻译成字节配额</h3>\n<p>KV 预算是容量规划的核心输出。把第一节的不等式反过来用：给定目标批大小 $B_{\\mathrm{target}}$ 与 SLO 的 $\\tau$，单请求允许的 KV 字节上限是</p>\n<div class=\"formula\">$$M_{\\mathrm{KV}} \\;\\le\\; \\frac{\\tau\\,P_{\\mathrm{eff}}}{B_{\\mathrm{target}}\\,\\mathrm{BW}_{\\mathrm{HBM}}}$$</div>\n<p>这条式子把 SLO 直接翻译成字节配额，而字节配额再翻译成视觉 token 上限——因为文本 KV 由 $N_{\\mathrm{txt}}$ 决定、相对固定，弹性几乎全在视觉侧。于是容量决策变成一个可执行的闭环：先定 $\\tau$ 与 $B_{\\mathrm{target}}$，算出 $M_{\\mathrm{KV}}$ 上限，减去文本 KV 的固定部分，剩余额度除以每视觉 token 的 KV 字节数，得到该 SLO 下允许的最大视觉 token 数。超过这个数的请求要么降分辨率、要么走分离式预填/解码把视觉段挪出解码关键路径、要么单独排队。</p>\n<p>这里有一个容易被忽略的耦合：$M_{\\mathrm{KV}}$ 的上限同时受显存容量约束。显存侧要求 $B_{\\mathrm{target}}\\cdot M_{\\mathrm{KV}}$ 不超过可用 KV 池，带宽侧要求它不超过 $\\tau P_{\\mathrm{eff}}/\\mathrm{BW}_{\\mathrm{HBM}}$。两个约束取小者才是真正的可行域。多模态请求的视觉 KV 往往使带宽侧先于容量侧成为瓶颈——因为解码每步都要把全部 KV 读一遍，而容量只在准入时检查一次。工程上表现为：显存明明还有余量，解码步却已经超时。这正是把带宽约束写进准入逻辑的理由。</p>\n<p>一个具体例子：同一 $B_{\\mathrm{target}}$ 下，若把视觉 token 预算翻倍，$M_{\\mathrm{KV}}$ 随之上升，带宽侧允许的批大小按反比下降，调度器必须在“更大批、更少视觉 token”与“更小批、更丰富视觉输入”之间取舍。这个取舍不是拍脑袋，而是上面两条不等式联立后的可行域边界。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-24\">二十四 · 定 SLO：串行和只是下界，尾延迟要加队列项</h3>\n<p>公式给出的 $T_{\\mathrm{e2e}}$ 是单请求无排队时的服务时间，SLO 定的是端到端含排队的尾延迟。两者之间差一个排队项。设到达率为 $\\lambda$、单请求平均服务时间为 $\\bar{T}$、服务台数为 $m$（可理解为并行执行的批槽），则尾延迟近似为 $\\bar{T}$ 加上排队等待。工程上不必套用精确排队公式，但必须承认：用三段串行和直接当 P99 设定 SLO，是前文列出的首要失效模式。调度器的队列等待与抢占开销在混合负载下会显著抬高尾延迟，尤其当长视觉请求占据批槽、短请求被迫等待时。</p>\n<p>因此定 SLO 的正确顺序是：先用公式算出服务时间下界，再叠加调度器实测的队列等待分布，得到 P99 估计，最后反推 $\\tau$ 与 $B_{\\mathrm{target}}$ 的可行组合。若实测 P99 系统性高于模型值，说明队列项不可忽略，此时应压缩批大小或引入优先级队列，而不是怀疑公式本身。另一个必须扣除的项是重叠节省：若视觉编码放入独立 CUDA 流并与上一批解码重叠，则 $T_{\\mathrm{e2e}}$ 中 $T_{\\mathrm{enc}}$ 的一部分被隐藏，尾延迟下降的量等于可重叠的视觉段时间。调度器可以用这个差值直接比较“先编码后批 prefill”与“视觉段与解码段流水重叠”两种策略的 P99，决定是否为视觉段单独开流。</p>\n<p>功耗与带宽也是 SLO 的隐含约束：解码段持续读 HBM 是功耗与带宽的双重压力点，长时间高批解码会让 HBM 带宽接近饱和，此时再增大批只会拉长单步时间而不提升吞吐。SLO 设定若只看 token 间隔不看带宽占用率，会在高负载段失守。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-25\">二十五 · 算例：一条长视频请求的容量决策链</h3>\n<p>设某多模态服务的目标是解码 token 间隔不超过 $\\tau$，批槽目标 $B_{\\mathrm{target}}$ 已由吞吐需求定下。按第三节的字节配额式，先算 $M_{\\mathrm{KV}}$ 上限；再减去文本 KV 的固定占用，得到视觉 KV 额度；除以每视觉 token 的 KV 字节数，得到视觉 token 上限。假设这条长视频请求的视觉 token 数超过该上限，则它在当前 SLO 与批大小下不可准入。三条出路：其一，降采样减少视觉 token，代价是视觉 token 率-失真界所描述的精度损失；其二，把该请求的视觉编码挪到独立流与上一批解码重叠，用重叠节省项抵消 $T_{\\mathrm{enc}}$，但 $M_{\\mathrm{KV}}$ 的带宽压力仍在解码段，重叠只解决编码段不解决解码段；其三，走分离式预填/解码，把视觉段与 prefill 放到预填池，解码池只承接已压缩的 KV，从而把 $M_{\\mathrm{KV}}$ 的读取压力从解码关键路径上部分转移。</p>\n<p>决策链的量化部分：用第一节的 $B_{\\mathrm{BW}}$ 检查当前 $B_{\\mathrm{target}}$ 是否越界；若越界，说明解码段已从带宽受限滑向算力受限或单纯超时，此时公式的带宽项低估时延，必须改用算力项重估，否则容量规划偏乐观——这是前文列出的第二条失效模式。若未越界但 P99 仍超标，则问题在队列项而非服务时间项，应调调度策略而非调批大小。</p>\n<p>算例的落点是：一条请求能否被接纳，取决于三个量同时满足——$M_{\\mathrm{KV}}$ 在字节配额内、$B_{\\mathrm{target}}$ 在 $B_{\\mathrm{BW}}$ 内、叠加队列项后的 P99 在 SLO 内。三者任一不满足，就要在降视觉 token、开重叠流、改分离式部署之间选一条，而每条选择都对应明确的时延项或显存项代价，不是定性权衡。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-26\">二十六 · 决策顺序与模型失效的自检</h3>\n<p>把上述用法固化成顺序：先由 SLO 与吞吐需求定 $\\tau$ 与 $B_{\\mathrm{target}}$；再由字节配额式定 $M_{\\mathrm{KV}}$ 上限并折算视觉 token 上限；再由 $B_{\\mathrm{BW}}$ 校验批大小是否落在带宽受限区；若落在算力受限区则切换 $T_{\\mathrm{dec}}$ 的建模项；最后叠加队列项与重叠节省项得到 P99 估计。任何一步的输入变化都会传导到后续步骤，因此这套顺序应作为容量评审的固定检查表，而不是一次性计算。</p>\n<p>自检要点有三：其一，$M_{\\mathrm{KV}}$ 是否按请求级而非全局均值参与准入，混合负载下这是尾延迟抖动的常见来源；其二，批大小是否已越过带宽受限边界，越过之后继续用带宽项会系统性低估时延；其三，视觉段是否真的与解码段重叠，若未重叠则 $T_{\\mathrm{enc}}$ 逐批串行累加，长视频请求下尾延迟被显著抬高。三条自检对应前文列出的三条失效模式，逐条核对即可判断当前容量决策是否建立在公式的适用边界之内。工程判断落在最后一条上：当视觉段占比高且未做重叠时，加并行度或加批都救不了尾延迟，唯一有效动作是把视觉编码移出解码关键路径。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-27\">二十七 · 把三段串行式当作容量决策工具时的边界与代价</h3>\n<p>该式进入调度器后，真正被消费的不是绝对值而是<b>可比较的差值</b>：给定 $F_{\\mathrm{vis}}$、$N_{\\mathrm{vis}}$、$N_{\\mathrm{out}}$ 与 $M_{\\mathrm{KV}}$，把视觉编码放进独立 CUDA 流、与上一批解码重叠，等价于从 $T_{\\mathrm{e2e}}$ 中减去 $T_{\\mathrm{enc}}$ 与上一批解码尾部的交集项；不重叠则 $T_{\\mathrm{enc}}$ 逐批串行累加。工程判断的落点是：当 $T_{\\mathrm{enc}}/T_{\\mathrm{e2e}}$ 足够大（长视频、高分辨率帧数多、$N_{\\mathrm{out}}$ 短），重叠收益才压得住 P99；反之短 prompt、长输出的文本主导请求，重叠几乎不改变尾延迟，却引入额外的流同步与显存驻留代价。定批大小时应把 $T_{\\mathrm{enc}}$ 视为<b>不可摊薄的固定开销</b>——增大 batch 只稀释 prefill 与 decode 项，视觉段按请求数线性增长，故批大小上限由视觉段占用的 SM 与显存决定，而非由 decode 的 KV 带宽决定。</p>\n<p>定并行度与 KV 预算时，$M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$ 只在<b>带宽受限区间</b>成立。batch 增大到算术强度越过 roofline 拐点后，单 token 时间转为算力受限，实际 $T_{\\mathrm{dec}}$ 高于模型值，容量规划会系统性偏乐观。可用如下判据切换：设单 token 计算量为 $2N_{\\mathrm{param}}$ 量级、KV 读取为 $M_{\\mathrm{KV}}$，当 $B\\cdot 2N_{\\mathrm{param}}/P_{\\mathrm{eff}} &gt; B\\cdot M_{\\mathrm{KV}}/\\mathrm{BW}_{\\mathrm{HBM}}$ 即 $2N_{\\mathrm{param}}/M_{\\mathrm{KV}} &gt; P_{\\mathrm{eff}}/\\mathrm{BW}_{\\mathrm{HBM}}$ 时进入算力受限，此时 $T_{\\mathrm{dec}}$ 应替换为算力项并按实测 $P_{\\mathrm{eff}}$ 打折。KV 预算因此不是“显存装得下多少请求”，而是“在带宽受限区内能维持多少并发解码流”，超出即需靠分离式预填/解码或降低 $N_{\\mathrm{out}}$ 上限来保 SLO。</p>\n<p>定 SLO 时最易失效的一环是排队项缺失：$T_{\\mathrm{e2e}}$ 只覆盖单请求三段，实际 P99 还叠加调度器队列等待、抢占与重调度开销。算例：某多模态服务以 $T_{\\mathrm{e2e}}$ 估算得单请求约数百毫秒级，据此设定 P99 目标并放开 batch，上线后长视频请求因 $T_{\\mathrm{enc}}$ 未重叠、且大 batch 下 decode 已转算力受限，尾延迟超出模型值——此时应做的是把视觉段独立成流、限制单批视觉请求数、并对超出带宽受限区的 batch 改用算力项重估，而不是继续加大 batch 摊薄 prefill。</p>\n<table class=\"mini\"><thead><tr><th>决策</th><th>模型给出的量</th><th>失效条件与代价</th></tr></thead><tbody><tr><td>批大小</td><td>稀释 prefill/decode 项</td><td>视觉段线性增长，SM/显存被占，尾延迟抬升</td></tr><tr><td>并行度</td><td>带宽受限区并发流数</td><td>越过拐点转算力受限，$T_{\\mathrm{dec}}$ 被低估</td></tr><tr><td>KV 预算</td><td>$M_{\\mathrm{KV}}$ 与带宽之比</td><td>仅覆盖解码，未计队列与抢占开销</td></tr></tbody></table>\n<h3 id=\"th-vlm-batch-latency-sec-28\">二十八 · 把串行三段和当成 SLO 承诺：排队项缺席的后果</h3>\n<p>最常见也最致命的误用，是把 $T_{\\mathrm{e2e}}$ 的三段串行和直接当作调度器可以承诺的尾延迟。公式里没有排队项，而生产环境的 P99 恰恰由排队项主导。识别方法很直接：拿线上 trace 的到达率 $\\lambda$ 与服务时间分布做对比，若模型给出的 $T_{\\mathrm{e2e}}$ 与实测 P50 吻合良好、但 P99 系统性高出，且高出量随并发上升而单调扩大，那就不是模型参数标定问题，而是漏掉了等待。工程上的判别式是：设调度器队列等待为 $W_q$、抢占与重排开销为 $W_p$，则真实尾延迟应写成</p>\n<div class=\"formula\">$$T_{\\mathrm{P99}} \\;\\approx\\; T_{\\mathrm{e2e}} + W_q^{(99)} + W_p^{(99)}$$</div>\n<p>其中 $W_q^{(99)}$ 由批窗口边界与连续批处理的重组节奏决定，$W_p^{(99)}$ 由高优先级请求插入、KV cache 抢占与重算引起。多模态请求的特殊之处在于视觉段的服务时间方差极大：一张 336×336 图与一段长视频的 $F_{\\mathrm{vis}}$ 相差数量级，而 LLM 解码段的服务时间相对稳定。这种“前段重尾、后段轻尾”的组合会让队列在视觉段堆积，形成队头阻塞——一个长视频请求占住视觉编码器，后面几十个短请求的 prefill 全部推迟。后果是容量规划偏乐观：按三段和算出的单卡 QPS 目标，在真实到达分布下根本达不到，扩容决策建立在错误的基线上。</p>\n<p>具体例子：某服务按三段和估算单请求 2 秒、单卡并发 8 路即得 4 QPS/卡，据此配置十卡集群承接 40 QPS 峰值。上线后发现峰值时段 P99 远超承诺值，排查发现视觉段的长尾请求把批窗口拉长，短请求在队列中等待的时间超过了它们自身的 $T_{\\mathrm{e2e}}$。修正方式不是加卡，而是把视觉编码拆入独立 CUDA 流、与上一批解码重叠，并对视觉段按 $F_{\\mathrm{vis}}$ 分桶调度，让重尾请求不与短请求共享同一批窗口。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-29\">二十九 · 大 batch 下沿用带宽受限解码项：容量规划的乐观偏差</h3>\n<p>公式把解码段写成 $N_{\\mathrm{out}} \\cdot M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$，这是带宽受限建模：每 token 读取 KV 的字节量固定，时间由带宽与有效算力之比决定。这个建模在单请求或小 batch 下成立，因为此时 HBM 带宽是瓶颈、SM 算力大量闲置。但 batch 增大后，KV 读取被摊薄到更多请求上，每 token 的矩阵乘工作量随 batch 线性增长，系统转入算力受限区。此时真实的单 token 时间应改用算力项，即与 $2\\,N_{\\mathrm{params}}$ 量级的浮点运算除以 $P_{\\mathrm{eff}}$ 成正比，而不再由 KV 字节数主导。</p>\n<p>识别信号有两个。其一是实测吞吐随 batch 增长的曲线出现拐点：在带宽受限区，吞吐随 batch 近似线性上升；一旦转入算力受限，斜率迅速压平，而模型仍预测线性。其二是 profiler 上 SM 占用率与 HBM 带宽利用率的关系反转——小 batch 时带宽接近饱和而算力利用率低，大 batch 时算力利用率逼近上限而带宽利用率回落。误用的后果是容量规划偏乐观：按带宽项外推大 batch 的解码时延，会低估单 token 时间，进而高估可持续的输出 token 速率，把 SLO 达标所需的卡数算少。对多模态尤为危险，因为视觉 token 让 $N_{\\mathrm{vis}}$ 抬高 prefill 成本，调度器倾向于用更大 batch 摊薄固定开销，恰好把系统推进算力受限区，而模型对此毫无察觉。</p>\n<p>工程判断：在调度器里维护一个分段判据，用 batch 内总 KV 字节量与总算力需求的比值判断当前处于哪一区，跨过阈值时切换解码时延模型。这个判据不需要精确，只需要单调——它的作用是防止容量规划在错误的区间外推。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-30\">三十 · 视觉段与解码段不重叠：固定开销逐批累加</h3>\n<p>公式假设视觉编码与 LLM prefill 串行执行，这在单请求语义下没错，但在批调度语义下是一个可以被消除的假设。若调度器把视觉编码放在与解码相同的串行路径上，每一批都要先等视觉段跑完才能开始解码，视觉段的固定开销就逐批累加，直接抬高尾延迟。长视频请求下这一项尤其显著：$F_{\\mathrm{vis}}$ 随帧数增长，而解码段的 $N_{\\mathrm{out}}$ 并不随之增长，于是视觉段在端到端时延中的占比被放大。</p>\n<p>正确的做法是把视觉编码放入独立 CUDA 流，与上一批的解码重叠，等价于在公式中减去重叠节省项：</p>\n<div class=\"formula\">$$T_{\\mathrm{e2e}}^{\\mathrm{overlap}} \\;=\\; T_{\\mathrm{e2e}} - \\min\\!\\left(T_{\\mathrm{enc}},\\, T_{\\mathrm{dec}}^{\\mathrm{prev}}\\right)$$</div>\n<p>识别误用的方法是看 GPU 时间线上的空洞：若视觉段与解码段之间出现 SM 空闲而 HBM 仍有带宽余量的区段，说明两段没有重叠，固定开销在裸奔。后果分两层：延迟上，P99 被视觉段固定开销抬高；吞吐上，视觉编码器在解码期间闲置，等于为视觉段付了两次钱——一次是它自己的时间，一次是它阻塞解码的机会成本。Nova 式流水正是针对这一点：把视觉编码、prefill、解码切成阶段并在不同请求间交错，使视觉段的算力占用与解码段的带宽占用在同一时间窗内并行，两类资源互不争抢。</p>\n<p>具体例子：一个以图像问答为主的服务，视觉段占单请求端到端时延的可观比例，且这部分时间在解码期间完全空转。改为独立流重叠后，视觉段的固定开销被上一批的解码时间吸收，尾延迟的改善不来自任何单段加速，而来自串行结构的消除。注意重叠的前提是资源不冲突：视觉段吃算力、解码段吃带宽，二者在同一 SM 上并行时需保证寄存器与 TMEM 占用不越界，否则重叠会退化为互相拖慢。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-31\">三十一 · 一个反例：把三段和当容量公式的调度器</h3>\n<p>构造一个具体的反例。某多模态推理服务用公式做容量决策，输入是平均图像尺寸、平均输出 token 数与目标 P99。调度器据此算出单卡可承载的并发请求数 $C$，并把连续批处理的最大批大小设为 $C$。运行时的行为如下：短图像请求与长视频请求混在同一批，视觉段被最长的那条请求决定，批内其余请求在视觉段空等；解码段因批大小被推到算力受限区，单 token 时间高于带宽项预测；队列中等待的请求既没进入视觉段也没进入解码段，其等待时间完全不在公式里。三个误差同向叠加，实测 P99 显著高于模型值，而运维的第一反应是加卡——加卡降低了排队，却让批大小继续增大，解码段更深地落入算力受限区，边际收益迅速衰减。</p>\n<p>这个反例的教训不是公式错了，而是公式的适用边界被越过了。正确的用法是把公式当作分段决策工具而非端到端容量公式：用 $T_{\\mathrm{enc}}$ 决定视觉段的分桶与独立流策略，用 $T_{\\mathrm{prefill}}$ 决定 prefill 批的切分，用分段判据决定解码段用带宽项还是算力项，再把 $W_q$ 与 $W_p$ 作为独立项叠加到 SLO 预算里。识别这类误用的通用手法是误差归因：把实测端到端时延按段拆开，与模型逐段对比，若某一段的偏差随并发单调增长，说明该段的建模区间被越过；若偏差与并发无关而是常数偏移，说明漏了固定开销项；若偏差集中在请求进入与离开调度器的时刻，说明漏了排队项。</p>\n<p>落到工程判断上：任何把 $T_{\\mathrm{e2e}}$ 直接写进 SLO 承诺或扩容公式的做法都应被拒绝，除非同时给出三项附加——分段判据的切换阈值、重叠节省项的实测标定、以及队列等待的分布估计。缺任何一项，模型在小规模测试中都会表现良好，而在生产峰值下系统性失效，且失效方向一致偏乐观，这正是最危险的一类误用。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-32\">三十二 · 把串行三段和当成 SLO 承诺：三类典型误用与一个反例</h3>\n<p>第一类误用是把三段串行和直接当作调度器的 SLO 承诺。公式里的 $T_{\\mathrm{e2e}}$ 只描述单请求在无争用条件下的执行时间，而真实调度器还要叠加队列等待与抢占开销：连续批处理下新请求要等当前批的 decode 步让出槽位，视觉编码任务若未放进独立 CUDA 流，还会与上一批解码争抢 SM 与 HBM 带宽。识别信号很直接——离线用该式算出的 P99 与线上实测 P99 出现系统性正偏差，且偏差随并发上升而扩大，而不是随模型规模变化。工程上应把模型值当作下界，SLO 预算里显式预留队列项，并用调度器埋点（入队时间戳、首次 prefill 时间戳、首 token 时间戳）把队列段单独测量出来，而不是让三段和吞掉全部误差。</p>\n<p>第二类误用是在大 batch 下仍沿用带宽受限的 $T_{\\mathrm{dec}}$。该式每 token 时间取 $M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$，前提是解码被 KV 读取带宽卡住；当 batch 增大到算力成为瓶颈，单 token 时间改由算力项主导，模型会系统性低估解码段。判别方法是看 batch 扩大时实测每 token 时间是否偏离线性：若偏离且随 batch 上升而抬升，说明已进入算力受限区。容量规划若继续用带宽项外推，会得出偏乐观的并发上限，上线后在高峰时段表现为吞吐不达标而非单请求变慢，这类失效更难在压测中被发现。</p>\n<p>第三类误用是未实现视觉段与解码段的流水重叠。视觉编码的固定开销 $F_{\\mathrm{vis}}/P_{\\mathrm{eff}}$ 与输出长度无关，长视频请求下这一项占比很高；若视觉编码与 LLM prefill 严格串行，每个新批次都要先付一次完整视觉开销，尾延迟被逐批累加抬高。识别方式是统计首 token 时延中视觉段占比，若该占比在高负载下不降反升，说明重叠没有生效。反之，若已采用分离式预填/解码或 Nova 式跨阶段流水，模型必须减去重叠节省项，否则会高估时延、错配资源。</p>\n<p>一个具体反例：某长视频问答服务按串行三段和设定 P99 目标，视觉编码未放入独立流，解码段一律按带宽项估算。上线后高峰时段 P99 超标，排查发现三处叠加——队列等待未计入、大 batch 下解码已转算力受限、视觉段与解码无重叠。修正路径是把视觉编码移入独立 CUDA 流与上一批解码重叠、按实测 batch 区间切换解码项、并在 SLO 预算中单列队列项，三者缺一都会让模型值与线上值脱节。</p>\n\n<h3 id=\"th-vlm-batch-latency-sec-33\">三十三 · 把串行和当 SLO：三类误用与一条反例</h3>\n<p>第一类误用是把三段串行和直接当成尾延迟承诺。$T_{\\mathrm{e2e}}$ 只描述单请求在无竞争条件下的服务时间，调度器队列等待与抢占开销不在式内；用它设定 SLO，等于默认请求到达即被调度、批内无插队、无高优先级抢占。识别方法很直接：对比模型值与调度器埋点中的 <code>queue_wait</code> 与 <code>preempt_count</code>，若 P99 的系统实测值系统性高于模型值且差值随并发上升，就不是 kernel 慢，而是排队项被漏掉。后果是容量规划按模型值反推并发上限，上线后 P99 超标而单请求延迟指标仍“正常”，排查方向被误导到算子层。</p>\n<p>第二类误用是在大 batch 下继续套用带宽受限解码项。式中单 token 时间取 $M_{\\mathrm{KV}}\\,\\mathrm{BW}_{\\mathrm{HBM}}/P_{\\mathrm{eff}}$，前提是解码受 KV 读取带宽约束；batch 增大到算力成为瓶颈时，该式不再成立，模型会低估 $T_{\\mathrm{dec}}$。识别信号是解码段实测吞吐随 batch 增长的斜率明显低于线性、而 SM 利用率与 tensor core 占用率同步抬升——此时应把解码项换成算力受限形式。后果是容量规划偏乐观，压测阶段 batch 拉满仍“达标”，真实负载下每 token 时间上升，输出长度一长尾延迟即失控。</p>\n<p>第三类误用是忽略视觉段与解码段的流水重叠。模型假设视觉编码与 LLM prefill 串行，若调度器已把视觉编码放入独立 CUDA 流与上一批解码重叠，实际时延应减去重叠节省项；反之，若声称做了流水却仍按串行和报数，就会把视觉段的固定开销逐批累加。长视频请求下 $F_{\\mathrm{vis}}$ 项占比上升，这一项被重复计入的代价最明显。识别方式是看视觉 kernel 与解码 kernel 在时间线上是否真正并发，而非仅看代码里是否分了流。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>失效条件</th><th>识别信号</th><th>系统代价</th></tr></thead><tbody><tr><td>串行和当 SLO</td><td>高并发、有抢占</td><td>模型值与 P99 差值随并发扩大</td><td>容量规划偏乐观，P99 系统性超标</td></tr><tr><td>大 batch 仍用带宽项</td><td>解码转为算力受限</td><td>吞吐斜率低于线性、算力占用抬升</td><td>低估 $T_{\\mathrm{dec}}$，长输出尾延迟失控</td></tr><tr><td>漏算或重复算重叠</td><td>分离式预填/解码、Nova 式流水</td><td>时间线上视觉与解码 kernel 未并发</td><td>视觉固定开销逐批累加，长视频受害</td></tr></tbody></table>\n<p>反例：某服务把 $T_{\\mathrm{e2e}}$ 串行和乘以一个安全系数当作 P99 承诺，压测在低并发下通过；上线后长视频请求与高优先级抢占同时出现，视觉段固定开销与队列等待叠加，P99 远超承诺，而单请求延迟监控仍显示健康。根因不是公式错，而是公式的适用边界被越过：排队项未叠加、重叠项未扣除、大 batch 下解码项未换形式。工程判断是——把这个式子当作<em>下界估计与策略比较工具</em>，用它比较“先编码后批 prefill”与“视觉段与解码段流水重叠”的尾延迟差，而不是当作 SLO 承诺值；任何对外承诺都必须叠加调度器队列等待与抢占开销后再定。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>F_{\\mathrm{vis}}</td><td>视觉编码器前向浮点运算量</td></tr><tr><td>N_{\\mathrm{out}}</td><td>生成输出 token 数</td></tr><tr><td>M_{\\mathrm{KV}}</td><td>单请求 KV cache 字节数</td></tr><tr><td>P_{\\mathrm{eff}}</td><td>Blackwell 实测有效算力</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-vlm-batch-latency · 共 5 个片段</p>\n"},{"id":"th-nvl72-collective-lower-bound","title":"NVL72 集合通信下界","direction":"dir-multimodal-batching","prereq":[],"plain":"GB200/GB300 NVL72 机柜内跨 GPU 的 all-reduce 时延下界由消息大小除以 NVLink 有效带宽决定，多模态并行中视觉编码器与 LLM 若分置不同 GPU，跨模态投影与 KV 传输必须计入该通信下界。","definition":"GB200/GB300 NVL72 机柜内跨 GPU 的 all-reduce 时延下界由消息大小除以 NVLink 有效带宽决定，多模态并行中视觉编码器与 LLM 若分置不同 GPU，跨模态投影与 KV 传输必须计入该通信下界。","formula":"$$T_{\\mathrm{comm}} \\;\\ge\\; \\frac{2\\,(N-1)}{N}\\,\\frac{S}{\\mathrm{BW}_{\\mathrm{NVLink}}} \\;+\\; \\alpha\\,\\log_2 N$$","variables":[{"sym":"N","meaning":"参与集合通信的 GPU 数"},{"sym":"S","meaning":"单次集合通信消息字节数（如视觉 token 激活或 KV 分片）"},{"sym":"\\mathrm{BW}_{\\mathrm{NVLink}}","meaning":"NVLink 有效单向带宽"},{"sym":"\\alpha","meaning":"单跳通信固定时延"}],"derivation":"推导关键一步：ring all-reduce 需经 $2(N-1)/N$ 倍消息量的带宽传输，叠加 $\\log_2 N$ 跳的固定时延项，得到带宽项与固定项之和的下界；消息越大带宽项越主导，消息越小固定项越主导。","example":"用途：在部署决策中，用该式判断视觉编码器与 LLM 是否值得分置不同 GPU：若跨模态投影与 KV 分片的 $S$ 使 $T_{\\mathrm{comm}}$ 超过流水重叠可隐藏的预算，则应改为同卡共置或减少分片数。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["假设 ring/tree all-reduce 且消息可完全流水，小消息时 α·log N 的固定时延项主导，带宽项失效","BW_NVLink 为实测有效带宽，NVLink 5 在 NVL72 内非全互联拓扑下跨域跳数会增加有效时延","未计入跨机柜（scale-out IB）场景，跨 NVL72 域通信需改用 IB 带宽与更陡的拓扑项"],"system_note":"常见误用：用小消息场景套用带宽项估算，忽略 $\\alpha\\log_2 N$ 固定时延主导，低估通信开销；把 NVL72 内 NVLink 当作全互联，忽略非全互联拓扑下跨域跳数带来的有效带宽下降。","papers":["paper-an-image-is-worth-16x16-words-transf-2020"],"facts":["直觉：GB200/GB300 NVL72 机柜内跨 GPU 的 all-reduce 时延下界由消息大小除以 NVLink 有效带宽决定，多模态并行中视觉编码器与 LLM 若分置不同 GPU，跨模态投影与 KV 传输必须计入该通信下界。","公式 $$T_{\\mathrm{comm}} \\ge \\frac{2\\,(N-1)}{N}\\,\\frac{S}{\\mathrm{BW}_{\\mathrm{NVLink}}} + \\alpha\\,\\log_2 N$$ 中，$N$ 为参与集合通信的 GPU 数，$S$ 为单次集合通信消息字节数（如视觉 token 激活或 KV 分片），$\\mathrm{BW}_{\\mathrm{NVLink}}$ 为 NVLink 有效单向带宽，$\\alpha$ 为单跳通信固定时延。","推导关键一步：ring all-reduce 需经 $2(N-1)/N$ 倍消息量的带宽传输，叠加 $\\log_2 N$ 跳的固定时延项，得到带宽项与固定项之和的下界；消息越大带宽项越主导，消息越小固定项越主导。","适用边界：假设 ring/tree all-reduce 且消息可完全流水，小消息时 $\\alpha\\log_2 N$ 的固定时延项主导，带宽项失效；$\\mathrm{BW}_{\\mathrm{NVLink}}$ 为实测有效带宽，NVLink 5 在 NVL72 内非全互联拓扑下跨域跳数会增加有效时延；未计入跨机柜（scale-out IB）场景，跨 NVL72 域通信需改用 IB 带宽与更陡的拓扑项。","用途：在部署决策中，用该式判断视觉编码器与 LLM 是否值得分置不同 GPU：若跨模态投影与 KV 分片的 $S$ 使 $T_{\\mathrm{comm}}$ 超过流水重叠可隐藏的预算，则应改为同卡共置或减少分片数。","常见误用：用小消息场景套用带宽项估算，忽略 $\\alpha\\log_2 N$ 固定时延主导，低估通信开销；把 NVL72 内 NVLink 当作全互联，忽略非全互联拓扑下跨域跳数带来的有效带宽下降。"],"anchors":["GB200","GB300","NVL72","NVLink 5"],"pitfalls":["按全互联拓扑估算 NVLink 有效带宽，忽略 NVL72 内跨域跳数，实际 all-reduce 时延高于下界估计。","在小消息（如单层 KV 分片）场景只用带宽项建模，忽略 $\\alpha\\log_2 N$ 固定时延主导，通信预算被低估。","把 NVL72 机柜内通信下界直接套用到跨机柜 scale-out 场景，未改用 IB 带宽与更陡拓扑项，容量规划失真。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-1\">一 · 一句话直觉：下界不是“能跑多快”，而是“至少得花多久”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-2\">二 · 严格定义：四个变量与一个不等式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-3\">三 · 为什么需要这个下界：三个决策场景</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-4\">四 · 常见误解之一：把带宽项当成全部</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-5\">五 · 常见误解之二：把机柜内下界套到机柜外</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-6\">六 · 下界的适用边界：什么情况下这条式子会失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-7\">七 · 带宽项：$2(N-1)/N$ 从哪来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-8\">八 · 固定项：$\\alpha\\log_2 N$ 的跳数账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-9\">九 · 两项相加为何仍是下界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-10\">十 · 离散化与近似清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-11\">十一 · 代入部署决策的算法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-12\">十二 · 下界公式的失效面：从流水假设到拓扑折算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-13\">十三 · 流水假设的物理前提</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-14\">十四 · 拓扑非全互联：有效带宽是变量而非常数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-15\">十五 · 规模上限：ring 结构自身的收敛点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-16\">十六 · 跨域失效：scale-out 场景不可套用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-17\">十七 · 失效条件的合并判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-18\">十八 · 边界之外：公式在什么拓扑、什么消息尺度上失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-19\">十九 · 下界在什么条件下失效：流水假设、拓扑跳数与 scale-out 边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-20\">二十 · 把下界改写成“每 token 通信税”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-21\">二十一 · 定批大小：带宽项随 batch 线性，固定项不动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-22\">二十二 · 定并行度：$N$ 的两个方向要分开算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-23\">二十三 · 定 KV 预算：分片数决定 $S$，$S$ 决定可承受的 KV 长度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-24\">二十四 · 定 SLO：把下界当可行性闸门而非性能预测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-25\">二十五 · 算例：一个分置方案的去留</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-26\">二十六 · 把通信下界折进批大小、并行度与 KV 预算的决策链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-27\">二十七 · 把下界塞进容量决策：批大小、并行度、KV 预算与 SLO 的联立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-28\">二十八 · 误用一：小消息套带宽项，固定时延被吃掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-29\">二十九 · 误用二：把 NVL72 当全互联，跳数被抹平</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-30\">三十 · 误用三：机柜内下界外推到 scale-out</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-31\">三十一 · 反例：一次被低估的解码步通信预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-32\">三十二 · 识别清单：把误用挡在建模阶段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-33\">三十三 · 下界不是承诺：三类误用如何把 NVL72 通信预算算反</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvl72-collective-lower-bound-sec-34\">三十四 · 下界失效的三种典型场景与识别方法</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：GB200/GB300 NVL72 机柜内跨 GPU 的 all-…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$T_{\\mathrm{comm}} \\;\\ge\\; \\frac…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：假设 ring/tree all-reduce 且消息可完全流水，…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-nvl72-collective-lower-bound-sec-1\">一 · 一句话直觉：下界不是“能跑多快”，而是“至少得花多久”</h3>\n<p>在 GB200/GB300 NVL72 机柜里，只要一次集合通信需要跨 GPU 搬运 S 字节，那么无论你的 kernel 写得多紧凑、SM 占用多满、流水排得多细，这次 all-reduce 的墙钟时延都不可能低于“消息量除以 NVLink 有效带宽”再加“拓扑跳数带来的固定开销”。这句话的重点在“不可能低于”——它是一个<strong>下界</strong>，不是性能预测，也不是调优目标。下界的作用是排除幻想：当你的推理流水线里视觉编码器与 LLM 分置不同 GPU，跨模态投影张量和 KV 分片必须过一次集合通信，那么这条链路上就存在一个由 N、S、BW_NVLink、α 四个量锁死的地板，任何调度技巧只能逼近它，不能穿透它。</p>\n<p>把这句话放进多模态推理的具体场景：视觉编码器产出的 patch 激活经投影后要送进 LLM 的 prefill 段，或者解码段要把 KV 分片在张量并行组间同步。这两类消息的 S 一旦确定，通信地板就确定了。工程判断因此变成一个非常朴素的问题——这条消息值不值得跨卡？如果跨卡的地板已经超过流水重叠能隐藏的预算，那分置就是错的，应该同卡共置或减少分片数。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-2\">二 · 严格定义：四个变量与一个不等式</h3>\n<p>本系列所说的“NVL72 集合通信下界”，严格指下面这个不等式所刻画的量：</p>\n<div class=\"formula\">$$T_{\\mathrm{comm}} \\;\\ge\\; \\frac{2\\,(N-1)}{N}\\,\\frac{S}{\\mathrm{BW}_{\\mathrm{NVLink}}} \\;+\\; \\alpha\\,\\log_2 N$$</div>\n<p>四个变量的含义必须钉死，否则后面所有推导都会漂移。<strong>N</strong> 是参与这次集合通信的 GPU 数，注意它是“参与者数”而非“机柜内 GPU 总数”——一个 8 卡张量并行组的 all-reduce，N 就是 8，哪怕机柜里有 72 颗 GPU。<strong>S</strong> 是单次集合通信的消息字节数，典型取值是视觉 token 激活张量的大小，或一层 KV 分片的字节数；它是“单次”而非“整个请求累计”，因为下界是按一次集合操作计的。<strong>BW_NVLink</strong> 是 NVLink 有效单向带宽，关键词是“有效”——它是实测值，已经含了协议开销与拓扑折损，不是理论峰值。<strong>α</strong> 是单跳通信固定时延，包含链路握手、路由、缓冲等与消息大小无关的部分。</p>\n<p>不等式右侧两项各有物理来源。带宽项系数 2(N−1)/N 来自 ring all-reduce 的经典结论：reduce-scatter 与 all-gather 两阶段合计，每个参与者需要搬运的消息量是原始消息的 2(N−1)/N 倍。固定项 α·log₂ N 来自 tree 型归约的跳数——N 个参与者做二叉树归约，深度是 log₂ N，每一跳都要付一次与 S 无关的固定代价。两项相加，就得到“带宽地板 + 时延地板”的复合下界。</p>\n<p>这个定义有两个必须说清的边界。第一，它假设消息可以完全流水，即带宽项与固定项可以部分重叠；若实现无法流水，实际时延只会更高，下界依然成立但更松。第二，它只覆盖 NVL72 机柜内的 NVLink 域，不含跨机柜 scale-out 的 IB 链路——跨域通信要换 IB 带宽并叠加更陡的拓扑项，那是另一条式子。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-3\">三 · 为什么需要这个下界：三个决策场景</h3>\n<p><strong>场景一：分置还是共置。</strong>多模态推理里最常见的架构问题是视觉编码器与 LLM 是否放不同 GPU。支持分置的理由是资源异构——视觉编码器吃激活和显存带宽，LLM 吃 KV 容量和矩阵算力，分开能让两类负载各得其所。但分置的代价是跨模态投影与 KV 分片必须走集合通信。用下界做判断：把投影张量的 S 和 KV 分片的 S 代入式子，得到 T_comm 的地板；再对照流水重叠能隐藏的时间预算。若地板已经超过预算，分置在时延上就是净亏，无论编码器侧省下多少。</p>\n<p><strong>场景二：分片数怎么定。</strong>张量并行度 N 直接进入式子：带宽项随 N 增大而趋近 2S/BW（因为 (N−1)/N → 1），但固定项 α·log₂ N 随 N 对数增长。这意味着小消息场景下，增大 N 会让固定项吃掉更多预算——把 KV 分片切得更细、参与者更多，单次 all-reduce 的固定开销反而上升。下界因此给出一个反直觉的判断：不是分片越多越快，消息小到一定程度时，固定项主导，加卡是负收益。</p>\n<p><strong>场景三：容量规划的地板。</strong>做 SLO 容量规划时，需要知道一条请求链路上通信占了多少不可压缩的时间。下界给出的是“不可压缩部分”的估计：即使你把计算 kernel 优化到极致、把批调度排到最紧，这部分时间仍然在。把 T_comm 从端到端时延预算里先扣掉，剩下的才是计算与调度可以争夺的空间。忽略这一步，容量规划会把通信开销当成“可以优化掉的软成本”，结果上线后时延打不满 SLO。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-4\">四 · 常见误解之一：把带宽项当成全部</h3>\n<p>最普遍的误用是拿小消息场景套带宽项。典型情形是单层 KV 分片的同步——一层 KV 的字节数在解码阶段并不大，此时 2(N−1)/N·S/BW_NVLink 算出来是个很小的数，工程师据此认为通信可忽略。但式子第二项 α·log₂ N 并没有随 S 缩小，它由跳数决定，与消息大小无关。小消息时固定项主导，带宽项失效，真实时延远高于带宽项的估算。</p>\n<p>这个误解的代价是可量化的：它让通信预算被系统性低估，进而让分置架构在纸面上显得可行，上线后才发现解码段被同步拖住。判断分界点的办法是令两项相等，解出临界消息大小 S*：当 S 远大于 S* 时带宽项主导，用带宽项估算尚可；当 S 接近或小于 S* 时，必须把 α·log₂ N 计入。工程上更稳妥的做法是两项都算，取和作为地板，不做单项近似。</p>\n<p>与之配套的第二个误解是把 NVL72 内的 NVLink 当成全互联。NVLink 5 在 NVL72 机柜内并非任意两卡等跳数直连，跨域通信要经过交换层级，跳数增加会抬高有效时延、压低有效带宽。按全互联拓扑估算 BW_NVLink，得到的下界偏乐观；实际 all-reduce 时延高于这个估计。这不是下界失效，而是代入的参数错了——BW_NVLink 必须是实测有效值，且要按实际拓扑的跨域跳数校正。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-5\">五 · 常见误解之二：把机柜内下界套到机柜外</h3>\n<p>第三个误解是把 NVL72 机柜内的这条式子直接搬到跨机柜 scale-out 场景。跨 NVL72 域的通信走 IB，带宽量级与 NVLink 不同，拓扑项也更陡——机柜内是 log₂ N 的树深，跨机柜往往要叠加多层交换，跳数与拥塞带来的固定开销显著上升。把机柜内的 BW_NVLink 和 α 代进跨域场景，容量规划会失真：算出来的地板远低于真实地板，规划出的副本数与并行度撑不住 SLO。</p>\n<p>正确做法是明确式子的适用域：它只回答“机柜内 NVLink 域”的问题。一旦通信路径跨出机柜，就要换用 IB 带宽与对应的拓扑项重新计算，两条式子不能混用。工程判断上，这意味着分离式预填/解码这类跨节点部署，其通信预算必须按 scale-out 链路单独核算，不能借用机柜内的乐观下界。</p>\n<table class=\"mini\"><thead><tr><th>误解</th><th>错在哪</th><th>后果</th><th>纠正</th></tr></thead><tbody><tr><td>小消息只用带宽项</td><td>忽略 α·log₂ N 固定项</td><td>通信预算低估，解码段被同步拖住</td><td>两项相加，或先算临界 S*</td></tr><tr><td>NVLink 当全互联</td><td>忽略跨域跳数折损</td><td>下界偏乐观，实际时延更高</td><td>BW_NVLink 用实测有效值并按拓扑校正</td></tr><tr><td>机柜内式子套跨机柜</td><td>带宽与拓扑项都不适用</td><td>容量规划失真，副本数撑不住 SLO</td><td>跨域改用 IB 带宽与更陡拓扑项</td></tr></tbody></table>\n<p>把这三个误解并排看，会发现它们共享同一个根源：把下界当成一个可以随手代入的公式，而不去检查它的假设是否成立。下界的价值恰恰在于它的假设是显式的——ring/tree all-reduce、消息可完全流水、机柜内 NVLink 域、有效带宽为实测值。任何一条假设被破坏，代入的数字就不再是下界，而是一个没有意义的数。工程上养成一个习惯：每次用这条式子之前，先问 N 是多少、S 是单次还是累计、BW 是实测还是峰值、路径有没有跨出机柜。这四个问题答完，式子才有资格进入决策。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-6\">六 · 下界的适用边界：什么情况下这条式子会失效</h3>\n<p>这条下界只回答一个问题：在 GB200/GB300 NVL72 机柜内，一次 all-reduce 至少需要多长时间。它的成立依赖三个前提——集合通信采用 ring 或 tree 结构、消息可以完全流水、参与通信的 GPU 全部落在同一 NVL72 域内。任何一个前提被打破，式子给出的就只是一个乐观参考值，而不是可以写进容量规划的硬约束。工程上真正危险的不是式子本身，而是把它的适用范围悄悄扩大：把机柜内下界当成跨机柜下界，把大消息结论套到小消息上，把标称带宽当成有效带宽。下面分别说明这三种失效条件及其系统代价。</p>\n<p>第一种失效来自消息尺寸。式子中带宽项与固定时延项的相对权重随 $S$ 变化：$S$ 越大，$2(N-1)/N \\cdot S/\\mathrm{BW}_{\\mathrm{NVLink}}$ 越主导；$S$ 越小，$\\alpha \\log_2 N$ 越主导。以单层 KV 分片为例，当分片只有数百字节量级时，带宽项几乎可以忽略，时延由跳数与单跳固定时延决定，此时增加带宽或减少消息量都不会改善时延，唯一有效的杠杆是压低 $N$ 或减少拓扑跳数。误用带宽项估算这类小消息，会系统性低估通信预算，导致流水重叠设计留出的隐藏窗口不足，解码阶段出现周期性停顿。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>主导项</th><th>有效优化手段</th><th>失效表现</th></tr></thead><tbody><tr><td>大消息（视觉 token 激活批量传输）</td><td>带宽项</td><td>提升有效带宽、减少冗余传输</td><td>按固定项估算会高估时延</td></tr><tr><td>小消息（单层 KV 分片）</td><td>$\\alpha\\log_2 N$ 固定项</td><td>减少 $N$、压缩跳数</td><td>按带宽项估算会低估时延</td></tr><tr><td>跨 NVL72 域</td><td>IB 带宽 + 更陡拓扑项</td><td>改用 IB 模型重新规划</td><td>套用机柜内下界，容量规划失真</td></tr></tbody></table>\n<p>第二种失效来自拓扑。$\\mathrm{BW}_{\\mathrm{NVLink}}$ 必须是实测有效单向带宽，而不是 NVLink 5 的标称值。NVL72 内部并非全互联，跨域通信需要经过额外跳数，每一跳都叠加固定时延并摊薄有效带宽。把 NVL72 当作全互联来估算，等价于假设任意两 GPU 之间都是单跳，实际 all-reduce 时延会高于下界估计，且偏差随 $N$ 增大而放大——因为 ring 的环长与跨域段数同时增加。这类误差在预填阶段表现为首 token 时延偏高，在解码阶段表现为 TP 组内同步抖动。</p>\n<p>第三种失效来自域边界。式子未计入跨机柜 scale-out 场景；一旦集合通信跨越 NVL72 域，必须改用 IB 带宽并引入更陡的拓扑项，此时下界的量级与机柜内完全不同。把机柜内下界直接用于跨域容量规划，会得出过于乐观的并行切分方案，实际部署时通信成为瓶颈。回到部署决策本身：用该式判断视觉编码器与 LLM 是否值得分置不同 GPU 时，若跨模态投影与 KV 分片的 $S$ 使 $T_{\\mathrm{comm}}$ 超过流水重叠可隐藏的预算，就应改为同卡共置或减少分片数；而这一判断只在机柜内、且 $S$ 足够大使带宽项主导时才成立。</p>\n<h3 id=\"th-nvl72-collective-lower-bound-sec-7\">七 · 带宽项：$2(N-1)/N$ 从哪来</h3>\n<p>公式里的带宽项不是凭空写下的系数，它来自 ring all-reduce 的两趟遍历结构。把参与通信的 $N$ 张 GPU 排成一个逻辑环，每个 rank 持有 $S$ 字节的待归约数据。第一趟 reduce-scatter：每张卡把自己的数据切成 $N$ 份，沿环向下游推 $N-1$ 步，每步发送 $S/N$ 字节，同时接收并累加上游来的分片；走完一圈后，每个 rank 恰好完整归约了其中一份分片。第二趟 all-gather：把各自持有的已归约分片再沿环推 $N-1$ 步，每步仍是 $S/N$ 字节，最终所有 rank 拼出完整结果。</p>\n<p>两趟合计，每个 rank 发出的字节数为 $2(N-1)\\cdot S/N$。这就是系数 $2(N-1)/N$ 的全部来历：$2$ 是两趟遍历，$(N-1)$ 是每趟绕环的步数，除以 $N$ 是分片。注意它是“每 rank 发送量”，不是“总发送量”——总线上流过的字节是它的 $N$ 倍，但因为 $N$ 条链路并行工作，决定时延的是单条链路要扛的量。当 $N$ 很大时系数趋近 $2$，即每卡大约搬运两倍消息量；当 $N=2$ 时系数为 $1$，两卡各发一份、各收一份，恰好是 $S$。这个渐近行为解释了为什么大 $N$ 下 all-reduce 的带宽代价不会随 $N$ 爆炸——它饱和在 $2S$。</p>\n<p>把发送量除以有效单向带宽，得到带宽项 $\\frac{2(N-1)}{N}\\cdot\\frac{S}{\\mathrm{BW}_{\\mathrm{NVLink}}}$。这里 $\\mathrm{BW}_{\\mathrm{NVLink}}$ 必须是实测有效单向带宽，而非链路标称速率：协议开销、流控、以及 NVL72 内非全互联拓扑带来的跨域跳数，都会把可用带宽压到标称值之下。工程上判断这一项是否主导，只需看 $S$ 与 $\\mathrm{BW}_{\\mathrm{NVLink}}\\cdot\\alpha\\log_2 N$ 的相对大小：前者远大于后者时，带宽项吃掉几乎全部时延预算。以跨模态投影为例，若把视觉编码器输出的一批 token 激活（$S$ 为数百 KB 量级）做一次 all-reduce 后再送入 LLM，带宽项随 $S$ 线性增长，此时压缩 token 数或改为同卡共置的收益直接体现在这一项上。</p>\n<div class=\"formula\">$$\\text{每 rank 发送量} = 2(N-1)\\cdot\\frac{S}{N},\\qquad T_{\\text{bw}} = \\frac{2(N-1)}{N}\\cdot\\frac{S}{\\mathrm{BW}_{\\mathrm{NVLink}}}$$</div>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-8\">八 · 固定项：$\\alpha\\log_2 N$ 的跳数账</h3>\n<p>带宽项只算了“搬运多少”，没算“启动多少次”。每一次沿环的转发都是一次独立的通信动作：写入发送缓冲、触发链路事务、对端轮询或中断、写入接收缓冲、再做归约累加。这一串动作的单次开销就是 $\\alpha$，它与消息大小基本无关，是纯粹的固定时延。ring all-reduce 的步数是 $2(N-1)$，看似线性于 $N$；但工程实现普遍采用递归倍增（recursive doubling）或树形归约，把步数压到 $\\log_2 N$ 量级——每一轮两两配对交换并归约，$N$ 个 rank 经 $\\log_2 N$ 轮收敛。于是固定项写成 $\\alpha\\log_2 N$。</p>\n<p>这里有一个必须讲清的离散化近似：$\\log_2 N$ 要求 $N$ 是 2 的幂。NVL72 的 $N$ 取 2、4、8、16、32、72 等值时，非 2 的幂的 $N$（如 72）无法整齐配对，实现上要么补齐到 128 个逻辑 rank 造成空转，要么退化为分段混合策略（先在小域内做 2 的幂归约，再跨域拼接），此时实际步数略高于 $\\log_2 N$，公式给出的是下界而非精确值。同理，$\\alpha$ 取的是单跳固定时延的均值，而 NVL72 内不同跳的物理距离不同——同 tray 内 NVLink 交换与跨 tray 跨域的跳，$\\alpha$ 并不相等。公式用一个标量 $\\alpha$ 折叠了这种异质性，代价是它只能当下界用，不能当预测值用。</p>\n<p>固定项主导的场景极其具体：单层 KV 分片的 all-reduce。一层 KV 分片只有几十 KB 甚至更小，带宽项算出来是纳秒级，而 $\\alpha\\log_2 N$ 是微秒级——差两到三个数量级。此时若只用带宽项做预算，会把一次跨卡 KV 同步估成“可忽略”，实际却在解码循环里每层都付一次固定时延，几十层叠加后直接吃掉 token 间时延预算。这就是把 $\\alpha\\log_2 N$ 写进下界的原因：它防止工程师在小消息 regime 里系统性低估。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-9\">九 · 两项相加为何仍是下界</h3>\n<p>把带宽项与固定项直接相加，隐含了一个乐观假设：带宽传输与固定时延完全流水重叠，即第 $k$ 跳的固定开销被第 $k-1$ 跳的数据搬运掩盖，于是总时延取两者中较慢者的累积。严格说，流水下的总时延应为 $\\max(T_{\\text{bw}}, \\alpha\\log_2 N)$ 加上首尾不可重叠的头尾开销；写成求和是一种保守的上界式表达，但作为“下界”它成立的方向是：任何真实实现都不可能低于 $\\frac{2(N-1)}{N}\\frac{S}{\\mathrm{BW}}+\\alpha\\log_2 N$ 中的带宽部分，而固定部分在无重叠时必然叠加。因此该式是“带宽下界 + 固定开销”的合成，其有效性依赖两个前提：消息可完全流水（无气泡），以及 ring/tree 拓扑的步数界。</p>\n<p>失效条件必须逐条点名。其一，小消息时 $\\alpha\\log_2 N$ 主导，带宽项失效——不是说带宽项算错了，而是它对总时延的贡献占比趋零，继续用它做容量规划会得出“通信免费”的错误结论。其二，$\\mathrm{BW}_{\\mathrm{NVLink}}$ 为实测有效带宽，NVLink 5 在 NVL72 内非全互联拓扑下跨域跳数会增加有效时延；按全互联假设代入标称带宽，得到的下界会低于真实值，估计偏乐观。其三，该式未计入跨机柜 scale-out IB 场景，跨 NVL72 域通信需改用 IB 带宽与更陡的拓扑项——IB 的带宽量级与拓扑跳数结构都不同，直接套用会令容量规划失真。</p>\n<p>一个具体判断例子：视觉编码器与 LLM 分置不同 GPU，跨模态投影的激活与逐层 KV 分片都要过 all-reduce。投影激活 $S$ 较大，带宽项主导，若流水重叠能把它藏进编码器计算窗口，则分置可行；但 KV 分片 $S$ 极小，每层固定项 $\\alpha\\log_2 N$ 无法被计算掩盖，分置后解码每步都付这笔钱。于是决策规则是：把两类消息分别代入，看固定项是否超过流水可隐藏预算——超过则改为同卡共置或减少分片数（降低 $N$，同时降低 $\\log_2 N$ 与跨域跳数）。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-10\">十 · 离散化与近似清单</h3>\n<p>公式在四个位置做了离散化或近似，工程上必须知道每一处的偏差方向。</p>\n<ul>\n<li><b>$N$ 取 2 的幂</b>：$\\log_2 N$ 的步数界只在 2 的幂下紧；$N=72$ 这类值需补齐或分段，实际步数偏高，公式偏乐观。</li>\n<li><b>$\\alpha$ 单一标量</b>：折叠了同 tray 与跨 tray 跳的时延差异，跨域跳多时真实固定开销高于 $\\alpha\\log_2 N$。</li>\n<li><b>$\\mathrm{BW}_{\\mathrm{NVLink}}$ 均匀</b>：假设所有链路有效带宽一致，忽略非全互联拓扑下跨域跳的带宽折损，代入标称值会低估时延。</li>\n<li><b>完全流水假设</b>：忽略归约计算与通信的串行段、缓冲同步气泡，真实实现的总时延不低于该式，但可能显著高于它。</li>\n</ul>\n<p>偏差方向的统一结论是：该式作为下界是可靠的（真实值不会低于它），但作为预测值系统性偏乐观，且偏乐观的程度随 $N$ 的非 2 幂性、跨域跳数、消息缩小而放大。容量规划时应把它当下限锚点，再乘一个由实测拓扑与消息分布决定的修正系数，而不是直接拿它当期望时延。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-11\">十一 · 代入部署决策的算法</h3>\n<p>把公式变成可执行的判定流程，而不是停留在纸面。伪代码思路如下：对每一种候选并行布局（视觉编码器与 LLM 同卡 / 分置同 tray / 分置跨 tray），枚举其产生的集合通信消息集合 $\\{S_i\\}$，对每条消息计算 $T_{\\text{comm},i}$，再与对应计算窗口 $T_{\\text{comp},i}$ 比较；若存在 $T_{\\text{comm},i} &gt; T_{\\text{comp},i}$ 且该消息处于解码关键路径（不可跨步重叠），则该布局不可行。</p>\n<div class=\"formula\">$$\\text{可行} \\iff \\forall i:\\; T_{\\text{comm},i} \\le T_{\\text{comp},i}\\ \\text{或}\\ \\text{该消息可跨步流水隐藏}$$</div>\n<p>这个判定的代价体现在三个系统指标上。延迟：固定项主导的 KV 分片同步直接抬升 token 间时延（TPOT），且随层数线性叠加。吞吐：带宽项主导的大消息 all-reduce 占用 NVLink 有效带宽，与同机柜内其他集合通信争抢，压低整体吞吐。显存与带宽：减少分片数（降 $N$）会降低通信量，但要求单卡容纳更多 KV，形成显存—通信的权衡；跨域跳数增加则同时抬高 $\\alpha$ 的有效值与带宽折损，是纯损失项，应优先通过布局消除。功耗层面，跨域长距离链路的事务次数增加，单位有效字节的能耗上升，这是分置方案在机柜级容量规划中常被忽略的一项。</p>\n<p>最终落到一个具体机制上：在 NVL72 内做多模态并行布局时，先把消息按 $S$ 排序，小消息集合（KV 分片、控制同步）走同域、低跳数路径以压 $\\alpha\\log_2 N$，大消息集合（投影激活、预填阶段批量激活）走带宽充裕路径并以流水重叠吸收带宽项；两类消息的路径选择不同，正是该下界公式两项分离的直接工程含义。任何试图用单一带宽数字统一估算两类消息的做法，都会在小消息侧低估、在大消息侧高估，最终把布局决策推向错误的一侧。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-12\">十二 · 下界公式的失效面：从流水假设到拓扑折算</h3>\n<p>该式的推导依赖一条关键近似：消息在 ring 或 tree 上可被完全流水，因而带宽项与固定项可以线性相加。真实流水并不完美——当 $S$ 小于单跳传输粒度（一个 NVLink 5 事务的有效载荷量级）时，每跳的启动开销无法被后续数据掩盖，$\\alpha\\log_2 N$ 不再是可叠加的常数项，而会与带宽项耦合放大。此时把两项简单相加得到的是乐观下界，实际时延可能显著高于估算。工程判断是：先按消息粒度把 $S$ 分成“大消息区间”与“小消息区间”，前者用带宽项定预算，后者直接用 $\\alpha\\log_2 N$ 定预算，不要对中间区间做线性外推。</p>\n<p>第二个近似在 $\\mathrm{BW}_{\\mathrm{NVLink}}$ 的取值上。NVL72 内 NVLink 5 并非全互联，跨域通信要经过交换芯片的多跳转发，有效单向带宽随跳数衰减，而公式把带宽视为与 $N$ 无关的标量。修正方式是引入拓扑折算因子 $\\eta(N)$，把带宽项改写为 $\\frac{2(N-1)}{N}\\cdot\\frac{S}{\\eta(N)\\,\\mathrm{BW}_{\\mathrm{NVLink}}}$，$\\eta$ 随参与 GPU 跨越的域数下降。代价体现在容量规划上：同一 $S$ 下，跨域 all-reduce 的时延下界被系统性抬高，若仍按全互联估算，KV 分片与跨模态投影的通信预算会被低估，进而错判“分置不同 GPU”是否可行。</p>\n<div class=\"formula\">$$T_{\\mathrm{comm}} \\;\\ge\\; \\frac{2\\,(N-1)}{N}\\,\\frac{S}{\\eta(N)\\,\\mathrm{BW}_{\\mathrm{NVLink}}} \\;+\\; \\alpha\\,\\log_2 N,\\qquad \\eta(N)\\le 1$$</div>\n<p>第三个边界是适用范围本身：该式只覆盖机柜内 scale-up 域。一旦视觉编码器与 LLM 分置于不同 NVL72 机柜，通信落到 scale-out IB，带宽量级与拓扑项形态都改变，$\\log_2 N$ 的树形项要让位于更陡的拓扑项，直接套用会失真。下表给出三种场景下公式各项的主导关系与代价落点。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>主导项</th><th>主要代价</th><th>公式可用性</th></tr></thead><tbody><tr><td>大消息、域内</td><td>带宽项</td><td>NVLink 带宽占用、流水重叠窗口</td><td>可用，需 $\\eta(N)$ 修正</td></tr><tr><td>小消息（单层 KV 分片）</td><td>$\\alpha\\log_2 N$</td><td>固定时延、启动开销</td><td>带宽项失效，仅固定项有效</td></tr><tr><td>跨机柜 scale-out</td><td>IB 带宽与拓扑项</td><td>IB 带宽、更陡拓扑项</td><td>不可直接套用</td></tr></tbody></table>\n<p>由此得到的工程判断是：该下界是“域内、可流水、已知拓扑”三条件下的判据，任一条不满足就必须替换对应项而非整体缩放。多模态并行决策中，若跨模态投影与 KV 分片的 $S$ 落在小消息区间，应优先减少分片数或改为同卡共置，而不是指望提高 NVLink 利用率来压缩时延——固定项不随带宽改善而下降。</p>\n<h3 id=\"th-nvl72-collective-lower-bound-sec-13\">十三 · 流水假设的物理前提</h3>\n<p>下界式成立的第一块基石是“消息可完全流水”。这句话在工程上等价于三个同时成立的条件：其一，集合通信被切成足够细的 chunk，使得任意时刻链路上都有字节在飞；其二，kernel 发射与通信发起之间没有同步气泡，即计算流与通信流真正异步；其三，chunk 数足够多以覆盖固定时延项，使带宽项不被启动开销吞掉。三者任一破缺，公式给出的就只是一个乐观的、不可达的参考值，而非可达下界。</p>\n<p>把流水条件写成约束更清楚。设消息被切成 <i>k</i> 个 chunk，单 chunk 传输时间为 <i>S</i>/(<i>k</i>·BW)，则流水要真正生效需满足</p>\n<div class=\"formula\">$$k \\;\\gg\\; \\frac{\\alpha\\,\\log_2 N \\cdot \\mathrm{BW}_{\\mathrm{NVLink}}}{S}$$</div>\n<p>右端是固定时延项折算成的“等效字节数”。当 <i>S</i> 小到与这个等效字节数同量级时，无论怎么切 chunk，链路都填不满，带宽项在总时延中退居次要。这就是小消息失效的定量刻画：不是带宽项“算错了”，而是它压根不主导。代价直接体现在延迟上——单层 KV 分片这类消息在 NVL72 内的实际 all-reduce 时延由 α·log₂N 撑起，按带宽项估出来的数字会系统性偏低，容量规划随之失真。</p>\n<p>具体例子：多模态并行中把视觉编码器与 LLM 分置不同 GPU，跨模态投影后的激活若按层切分下发，每层激活字节数远小于固定时延的等效字节数，此时 <i>T</i><sub>comm</sub> 几乎与 <i>S</i> 无关，只随 <i>N</i> 的对数缓慢上升。工程判断因此反转：减少分片数（降低 <i>N</i>）比压缩激活（降低 <i>S</i>）更有效，因为前者削减的是对数项的自变量，后者削减的是一个已经不主导的项。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-14\">十四 · 拓扑非全互联：有效带宽是变量而非常数</h3>\n<p>公式里 BW<sub>NVLink</sub> 写作一个符号，容易被误读为常量。在 NVL72 内它必须是实测有效单向带宽，且随通信对的拓扑距离变化。NVLink 5 在机柜内并非任意两 GPU 等距全互联，跨域跳数增加时，同一份字节要经过更多 hop，有效带宽按跳数折损，α 也随之从“单跳固定时延”变成“路径固定时延之和”。此时把 BW 当常数代入，等于假设了一个不存在的全互联拓扑。</p>\n<p>把拓扑折损写进式子，可得到一个修正形式：</p>\n<div class=\"formula\">$$T_{\\mathrm{comm}} \\;\\ge\\; \\frac{2\\,(N-1)}{N}\\,\\frac{S}{\\mathrm{BW}_{\\mathrm{eff}}(d)} \\;+\\; \\sum_{h=1}^{H}\\alpha_h,\\qquad \\mathrm{BW}_{\\mathrm{eff}}(d)=\\frac{\\mathrm{BW}_{\\mathrm{NVLink}}}{1+\\beta\\,(d-1)}$$</div>\n<p>其中 <i>d</i> 为平均跳数，<i>H</i> 为路径跳数，β 为每增一跳的带宽折损系数（由实测标定，不预设数值）。这个修正不改变下界的结构，但改变了它的数值含义：原来那个“机柜内下界”其实是“最优拓扑对的下界”，对跨域通信对并不成立。失败模式正是按全互联估算 BW，实际 all-reduce 时延高于估计值——不是公式错了，是代入的 BW 不属于那条路径。</p>\n<p>系统代价落在带宽与延迟的耦合上：跨域跳数增加既抬高固定项（多跳 α 累加），又压低带宽项分母，两个方向同时恶化，且恶化幅度随 <i>N</i> 增大而放大，因为大 <i>N</i> 的 ring 更容易跨越拓扑边界。工程含义是：<i>N</i> 的选择不能只看并行度收益，还要看参与集合通信的 GPU 集合是否落在同一拓扑域内；把一个跨域 GPU 拉进 ring，等于给整条 ring 的有效带宽打折。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-15\">十五 · 规模上限：ring 结构自身的收敛点</h3>\n<p>公式对 <i>N</i> 的依赖是 <i>N</i> 增大时带宽项系数 2(<i>N</i>−1)/<i>N</i> 单调趋近 2，固定项 α·log₂N 缓慢上升。表面看 <i>N</i> 越大越“摊薄”，但这只在 ring 能维持流水的前提下成立。ring all-reduce 的每一步依赖前一步的 chunk 到达，环长增大意味着单步传播时间线性增长，而 chunk 数受限于消息大小与最小可流水粒度。当环长使单步传播时间超过 chunk 计算时间，流水出现空洞，带宽项的实际系数高于 2(<i>N</i>−1)/<i>N</i>，公式从下界退化为乐观估计。</p>\n<p>规模上限可由一个比值判定：设单 chunk 在环上走一圈的时间为 <i>T</i><sub>ring</sub>，单 chunk 的本地处理时间为 <i>T</i><sub>chunk</sub>，则流水无空洞的条件近似为</p>\n<div class=\"formula\">$$\\frac{T_{\\mathrm{ring}}}{T_{\\mathrm{chunk}}} \\;\\le\\; k,\\qquad T_{\\mathrm{ring}} \\approx N\\cdot\\frac{S/k}{\\mathrm{BW}_{\\mathrm{eff}}}$$</div>\n<p>代入可见，<i>N</i> 增大时 <i>T</i><sub>ring</sub> 线性上升，而 <i>k</i> 受 <i>S</i> 限制不能无限增大，于是存在一个 <i>N</i><sub>max</sub>，超过它流水条件破缺。这就是本式的规模上限：它不是由公式的代数形式给出的，而是由 ring 的依赖链与 chunk 粒度共同给出的。对 NVL72 这类机柜级系统，<i>N</i> 的取值一旦跨过拓扑边界，<i>N</i><sub>max</sub> 还会因 BW<sub>eff</sub> 下降而进一步收缩。</p>\n<p>具体例子：视觉编码器与 LLM 共置时，若把视觉 token 激活的 all-reduce 扩到全机柜 <i>N</i>，而单次激活字节数不足以切出足够 chunk，则 <i>T</i><sub>ring</sub>/<i>T</i><sub>chunk</sub> 迅速超过 <i>k</i>，实际时延高于下界，且随 <i>N</i> 增大而恶化。此时正确做法是缩小参与集合通信的 GPU 集合，让 <i>N</i> 落在流水可维持的区间内，而不是继续扩大并行度。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-16\">十六 · 跨域失效：scale-out 场景不可套用</h3>\n<p>公式的适用域严格限定在 NVL72 机柜内。跨机柜走 scale-out IB 时，带宽量级与拓扑项形态都变了：IB 的有效带宽低于 NVLink 5，且跨机柜拓扑的跳数与拥塞行为使固定项不再是简单的 α·log₂N，而是更陡的拓扑项（多级交换、拥塞队列、路由非对称）。把机柜内下界直接套到跨域场景，等于用一条不存在的高带宽链路做容量规划，结果是低估时延、高估可承载的并行度。</p>\n<p>跨域的正确形态是分段建模：域内段用本式，域间段用 IB 带宽与更陡拓扑项，两段串联相加，且域间段的固定项不可用 log₂N 近似。系统代价体现在带宽与功耗两侧：跨域通信把数据搬出机柜，功耗从 NVLink 的短距链路转移到光模块与交换芯片，单位字节的能耗显著上升；延迟侧则因多级交换引入排队，尾延迟比均值更难约束。对 SLO 敏感的推理服务，跨域 all-reduce 的尾延迟往往成为瓶颈，而非均值。</p>\n<p>工程判断因此是二值的：若跨模态投影与 KV 分片的 <i>S</i> 使域内 <i>T</i><sub>comm</sub> 已在流水重叠预算之内，则不应把通信推向跨域；若必须跨域，则要按 IB 带宽重算下界并预留更陡的拓扑项余量，而不是沿用机柜内数字。这也是本式在部署决策中的原始用途——判断视觉编码器与 LLM 是否值得分置，判断依据必须是分段后的总时延，而非单段下界。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-17\">十七 · 失效条件的合并判据</h3>\n<p>把上述边界收拢成一条可操作的判据，避免逐条记忆。定义两个无量纲量：固定项占比 <i>r</i><sub>α</sub> = α·log₂N / <i>T</i><sub>comm</sub>，拓扑折损因子 <i>f</i><sub>d</sub> = BW<sub>NVLink</sub>/BW<sub>eff</sub>(<i>d</i>)。当 <i>r</i><sub>α</sub> 接近 1 时带宽项失效，公式退化为固定时延主导；当 <i>f</i><sub>d</sub> 明显大于 1 时全互联假设失效，代入的 BW 不属于实际路径；当 <i>N</i> 超过 <i>N</i><sub>max</sub> 时流水假设失效；当通信跨越机柜边界时适用域失效。四者可以同时发生，且互相放大——跨域既抬高 <i>f</i><sub>d</sub> 又抬高固定项，还压缩 <i>N</i><sub>max</sub>。</p>\n<p>判据的用途不是否定公式，而是标定它的可信区间。在可信区间内，公式给出的是可达下界，可用于部署决策与容量规划；在区间外，公式给出的是乐观参考，只能用于相对比较（例如比较两种分片方案的通信量比例），不能用于绝对时延预算。把这条区分写进工程流程，比反复修正公式系数更有效，因为失效的根源是假设而非代数。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-18\">十八 · 边界之外：公式在什么拓扑、什么消息尺度上失效</h3>\n<p>该下界成立的前提是 ring/tree all-reduce 且消息可完全流水。一旦消息小到带宽项不再主导，公式退化为固定时延的记账工具：$\\alpha\\log_2 N$ 项随 GPU 数对数增长，而 $2(N-1)/N$ 趋近 2 的带宽项几乎不随 $S$ 变化。以单层 KV 分片为例，若 $S$ 仅为数 KB 量级，带宽项贡献的传输时间远小于每一跳的固定开销，此时把 $S/\\mathrm{BW}_{\\mathrm{NVLink}}$ 当作主项来估算通信预算，会系统性低估实际时延。工程判断是：先比较 $\\frac{2(N-1)}{N}\\frac{S}{\\mathrm{BW}}$ 与 $\\alpha\\log_2 N$ 的量级，若后者占优，优化方向应转向减少参与集合通信的 GPU 数（缩小 $N$）或合并小消息成批发送，而不是继续压带宽。</p>\n<p>第二个失效点是拓扑假设。NVLink 5 在 NVL72 内并非全互联，跨域跳数会抬高有效时延，因此公式中的 $\\mathrm{BW}_{\\mathrm{NVLink}}$ 必须取实测有效单向带宽，而非端口峰值。按全互联估算带宽、忽略跨域跳数，是典型的失败模式：实际 all-reduce 时延高于下界估计，且偏差随 $N$ 增大而放大。多模态并行中视觉编码器与 LLM 分置不同 GPU 时，跨模态投影与 KV 传输的 $S$ 若落在跨域路径上，跳数带来的额外 $\\alpha$ 累加会直接吃掉流水重叠的余量。部署决策上，用该式判断是否值得分置：当跨模态投影与 KV 分片的 $S$ 使 $T_{\\mathrm{comm}}$ 超过可被计算流水隐藏的预算，应改为同卡共置或减少分片数，而不是指望带宽升级。</p>\n<p>第三个边界是规模上限与域边界。公式只覆盖单个 NVL72 机柜内的 NVLink 域，未计入跨机柜 scale-out 的 IB 场景。跨 NVL72 域通信需改用 IB 带宽与更陡的拓扑项，因为 IB 的有效带宽低于 NVLink 5，且拓扑层级更深、跳数更多，固定项与带宽项同时恶化。把机柜内下界直接套用到跨机柜容量规划，会得到过于乐观的时延与吞吐预期，导致 SLO 预算失真。可用下表快速判定公式是否仍适用：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>公式是否适用</th><th>应替换的项</th></tr></thead><tbody><tr><td>大消息、机柜内、可流水</td><td>适用，带宽项主导</td><td>—</td></tr><tr><td>小消息（单层 KV 分片）</td><td>带宽项失效</td><td>以 $\\alpha\\log_2 N$ 为主项，减少 $N$ 或合批</td></tr><tr><td>跨域跳数路径</td><td>需修正</td><td>$\\mathrm{BW}$ 取实测有效值，$\\alpha$ 按跳数累加</td></tr><tr><td>跨机柜 scale-out</td><td>不适用</td><td>改用 IB 带宽与更陡拓扑项</td></tr></tbody></table>\n<p>系统代价上，这三种失效各自对应不同的资源瓶颈：小消息场景下瓶颈是固定时延与发射开销，表现为 GPU 空转等待而非带宽饱和；跨域跳数场景下瓶颈是有效带宽下降与跳数延迟，表现为 all-reduce 尾部拉长、流水重叠窗口被压缩；跨机柜场景下瓶颈转为 IB 端口带宽与交换机层级，容量规划必须按 IB 有效带宽重算，否则机柜内算出的并行度在跨域部署时会直接违反时延 SLO。判断公式是否仍成立，本质上是在问：当前 $S$、$N$、拓扑跳数与互联介质是否仍落在推导假设内——任一项越界，下界就不再是下界，而只是一个偏低的乐观估计。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-19\">十九 · 下界在什么条件下失效：流水假设、拓扑跳数与 scale-out 边界</h3>\n<p>该下界成立的第一块基石是“消息可完全流水”。它隐含要求 $S$ 足够大、分块粒度足够细，使 ring 上每一跳的传输与下一块的启动重叠，带宽项 $\\frac{2(N-1)}{N}\\cdot\\frac{S}{\\mathrm{BW}}$ 才能被真正吃满。一旦消息被切成远小于单跳传播时延的分片，或集合通信被算子边界强行同步（例如视觉编码器输出必须等全部 token 就绪才能进入投影），流水被打断，实际时延退化为逐跳串行累加，下界不再是紧的估计而是乐观偏差。判断阈值应比较单块传输时间 $S_{\\text{chunk}}/\\mathrm{BW}$ 与单跳固定时延 $\\alpha$：前者小于后者时，增加分块数只增加启动开销，不增加有效带宽利用。</p>\n<p>第二块基石是“NVLink 5 在 NVL72 内可近似为高带宽直连”。实际拓扑并非全互联，跨域通信要经过多跳交换，跳数增加直接抬高 $\\alpha\\log_2 N$ 中的有效 $\\alpha$，同时多跳共享链路使有效 $\\mathrm{BW}_{\\mathrm{NVLink}}$ 低于单跳峰值。因此按全互联带宽代入公式会系统性低估时延，这是最常见的失败模式：估算值落在预算内，实测却突破 SLO。工程上应把 $\\mathrm{BW}$ 取为实测有效单向带宽、把 $\\alpha$ 取为该拓扑下的平均单跳时延，而不是器件规格值。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>主导项</th><th>公式是否适用</th></tr></thead><tbody><tr><td>大 $S$、可流水、机柜内</td><td>带宽项</td><td>适用，可作紧下界</td></tr><tr><td>小 $S$（单层 KV 分片）</td><td>$\\alpha\\log_2 N$</td><td>带宽项失效，须按固定项建模</td></tr><tr><td>跨 NVL72 域（scale-out IB）</td><td>IB 带宽 + 更陡拓扑项</td><td>不适用，须换模型</td></tr></tbody></table>\n<p>第三块基石是域边界。公式只覆盖单个 NVL72 机柜内的 NVLink 域；跨机柜走 scale-out IB 时，带宽量级与拓扑项形态都改变，把机柜内下界直接外推会使容量规划失真。多模态分置决策正是边界敏感的场景：视觉编码器与 LLM 分置不同 GPU 时，跨模态投影与 KV 分片的 $S$ 若使 $T_{\\mathrm{comm}}$ 超过流水可隐藏的预算，就应改为同卡共置或减少分片数——而这一判断只有在 $\\alpha$、$\\mathrm{BW}$ 按真实拓扑取值、且确认消息确实可流水时才成立。</p>\n<h3 id=\"th-nvl72-collective-lower-bound-sec-20\">二十 · 把下界改写成“每 token 通信税”</h3>\n<p>容量决策里直接套 $T_{\\mathrm{comm}}$ 的绝对值没有意义，因为一次集合通信的时延会被流水重叠吃掉大半。真正能进预算表的是把下界摊到每个输出 token 上：设一次前向在该并行组上触发 $k$ 次 all-reduce（张量并行每层两次、专家并行一次 all-to-all 折算、视觉侧投影一次），单次消息 $S$ 字节，则每 token 的通信下界为</p>\n<div class=\"formula\">$$T_{\\mathrm{comm/token}} \\;\\ge\\; k\\left[\\frac{2(N-1)}{N}\\cdot\\frac{S}{\\mathrm{BW}_{\\mathrm{NVLink}}} + \\alpha\\log_2 N\\right]$$</div>\n<p>这个量才是与 decode 步时（step time）同量纲、可加进 SLO 的东西。工程上把它和计算项并列：单 token 预算 $T_{\\mathrm{SLO}}/ \\mathrm{TPOT}$ 减去注意力与 FFN 的算力时延、减去 KV 读取的显存时延，剩下的余量必须大于 $T_{\\mathrm{comm/token}}$，否则并行度配置在数学上就不成立。注意 $k$ 与 $N$ 不是独立变量：$N$ 翻倍通常让 $k$ 不变但每层消息 $S$ 减半（张量并行切分隐藏维），带宽项按 $(N-1)/N$ 趋近 1 而固定项按 $\\log_2 N$ 增长——这正是“并行度不是越大越好”的定量来源，也是后文定并行度的抓手。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-21\">二十一 · 定批大小：带宽项随 batch 线性，固定项不动</h3>\n<p>批大小进入公式的方式是 $S$ 随 batch 线性增长（激活张量按 batch 维堆叠），而 $\\alpha\\log_2 N$ 与 batch 无关。于是每 token 通信税对 batch 的敏感度完全不同：</p>\n<div class=\"formula\">$$S(B) = S_1 \\cdot B,\\qquad T_{\\mathrm{comm/token}}(B) \\approx k\\left[\\frac{2(N-1)}{N}\\cdot\\frac{S_1 B}{\\mathrm{BW}} + \\alpha\\log_2 N\\right]$$</div>\n<p>小 batch 区间，第二项主导，增大 batch 几乎不增加每 token 通信成本，是纯赚的吞吐；当 $S_1 B$ 使带宽项追平固定项后，每 token 通信税开始随 batch 线性上升，继续加 batch 只是把通信压力转嫁给 NVLink。拐点条件可解出：$B^\\* = \\alpha\\log_2 N \\cdot \\mathrm{BW}_{\\mathrm{NVLink}} \\cdot N / [2(N-1)S_1]$。工程判断是：把常驻 batch 定在 $B^\\*$ 附近而不是盲目拉满，超过它之后吞吐增益被通信吃掉，且 decode 步时抖动变大、SLO 尾部变差。具体例子：视觉编码器与 LLM 分置时，跨模态投影的 $S$ 是每图一份而非每 token 一份，它的 $B^\\*$ 远高于 KV 分片那条路径——所以批大小应按“单位 token 消息量最大的那条集合通信”来定，而不是按总算力。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-22\">二十二 · 定并行度：$N$ 的两个方向要分开算</h3>\n<p>$N$ 同时出现在带宽系数 $(N-1)/N$ 和固定项 $\\log_2 N$ 里，前者随 $N$ 单调趋近饱和，后者单调上升，因此存在一个使 $T_{\\mathrm{comm/token}}$ 最小的 $N$，但它依赖 $S$ 与 $\\alpha$ 的比值。把每 token 消息量写成 $S = S_{\\mathrm{model}}/N_{\\mathrm{TP}}$（张量并行切分），代入后带宽项变成 $\\frac{2(N-1)}{N^2}\\cdot\\frac{S_{\\mathrm{model}}}{\\mathrm{BW}}$，在 $N=2$ 处取极大后随 $N$ 衰减，而 $\\alpha\\log_2 N$ 持续上升——两条曲线的交点就是并行度的经济上限。粗判据：当 $\\frac{S_{\\mathrm{model}}}{\\mathrm{BW}_{\\mathrm{NVLink}}}$ 显著大于 $\\alpha$ 时（大模型、宽隐藏维、大 batch），带宽项主导，加 TP 有效；当消息被切到很小（小 batch、窄层、MoE 单专家分片），固定项主导，此时加 TP 是负收益，应改用流水并行或减少分片数。这与前文“小消息时带宽项失效”的边界完全一致，落到决策上就是一句话：**先算 $\\alpha\\log_2 N$ 占 $T_{\\mathrm{comm/token}}$ 的比例，占比过半就别再加并行度。** 视觉侧同理：视觉编码器与 LLM 分置时，跨模态投影的 $S$ 若不足以让带宽项压过固定项，分置方案在时延上就站不住，应回到同卡共置。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-23\">二十三 · 定 KV 预算：分片数决定 $S$，$S$ 决定可承受的 KV 长度</h3>\n<p>KV cache 的并行切分直接改写 $S$：每层每步 all-reduce 的消息是 KV 分片字节数，$S_{\\mathrm{KV}} = 2 \\cdot L_{\\mathrm{ctx}} \\cdot d_{\\mathrm{head}} \\cdot n_{\\mathrm{head}}/N_{\\mathrm{TP}} \\cdot b_{\\mathrm{bytes}}$（K 与 V 各一份）。把它代入下界并令其等于 SLO 余量，可反解出该并行度下能承受的上下文长度上限：</p>\n<div class=\"formula\">$$L_{\\mathrm{ctx}}^{\\max} \\;\\le\\; \\frac{N_{\\mathrm{TP}}}{2\\,d_{\\mathrm{head}} n_{\\mathrm{head}} b_{\\mathrm{bytes}}}\\cdot\\frac{N}{2(N-1)}\\left[\\frac{T_{\\mathrm{reserve}}}{k}-\\alpha\\log_2 N\\right]\\mathrm{BW}_{\\mathrm{NVLink}}$$</div>\n<p>这个式子的工程含义是：KV 预算不是显存问题而是通信问题——当上下文拉长到 $S_{\\mathrm{KV}}$ 使带宽项压过固定项，每 token 通信税随 $L_{\\mathrm{ctx}}$ 线性增长，长上下文 SLO 首先被 NVLink 而不是 HBM 卡住。反过来，$N_{\\mathrm{TP}}$ 增大让 $S_{\\mathrm{KV}}$ 变小、$L_{\\mathrm{ctx}}^{\\max}$ 变大，但 $\\alpha\\log_2 N$ 项在括号里做减法，所以长上下文场景存在最优 TP 而非最大 TP。具体例子：GB200 NVL72 内做长上下文解码，若把 KV 分片数从 2 提到 8，$S_{\\mathrm{KV}}$ 降为 1/4，带宽项大幅缓解，但固定项从 $\\alpha\\log_2 2$ 涨到 $\\alpha\\log_2 8$，在短上下文、小 batch 的低消息量区间反而净亏——这就是同一机柜内“长上下文用大 TP、短请求用小 TP”的定量依据，也解释了连续批处理里按请求长度动态选并行度为何值得做。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-24\">二十四 · 定 SLO：把下界当可行性闸门而非性能预测</h3>\n<p>SLO 决策的正确用法是把 $T_{\\mathrm{comm/token}}$ 当作**必要条件**：任何配置若其通信下界已超过 TPOT 预算的通信配额，无论 kernel 怎么优化都不可能达标，直接淘汰，不必上机实测。配额划分建议按 decode 步时的构成比例给通信留出固定份额（注意力、FFN、KV 读取、通信四项），因为下界不可压缩。伪代码思路：</p>\n<ul>\n<li>对候选 (N_TP, batch, L_ctx, 是否分置视觉) 枚举，算 $S$ 与 $k$；</li>\n<li>若 $k[\\frac{2(N-1)}{N}\\frac{S}{\\mathrm{BW}} + \\alpha\\log_2 N] &gt; \\mathrm{quota}$，标记不可行；</li>\n<li>对可行集再按显存与算力排序，避免用通信下界做过细的性能预测。</li>\n</ul>\n<p>代价面要一起看：提高 $N$ 降低单卡显存压力但抬高固定项与功耗；提高 batch 摊薄固定项但抬高带宽项与显存；缩短 $L_{\\mathrm{ctx}}$ 直接砍带宽项但损失业务能力。三者构成一个受 $\\mathrm{BW}_{\\mathrm{NVLink}}$ 与 $\\alpha$ 约束的可行域，SLO 越紧可行域越小，最终往往收敛到“中等 TP + 中等 batch + 限制上下文”的角点。失效模式必须写进决策表：按全互联拓扑估 $\\mathrm{BW}_{\\mathrm{NVLink}}$ 会系统性低估时延，NVL72 内非全互联拓扑的跨域跳数让有效带宽下降，下界估计偏乐观，容量规划随之失真；把机柜内下界套到跨机柜 scale-out 更是直接错——那里要换 IB 带宽和更陡的拓扑项，$\\alpha\\log_2 N$ 的系数完全不同，跨域集合通信的固定项会吞掉大部分预算。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-25\">二十五 · 算例：一个分置方案的去留</h3>\n<p>设某多模态服务在 GB200 NVL72 的一个域内运行，视觉编码器与 LLM 分置两组 GPU，跨模态投影每图产生一份激活、KV 分片每步每层一份，TPOT 预算中划给通信的配额为定值 $\\mathrm{quota}$。按公式逐项代入：先算投影路径的 $S_{\\mathrm{proj}}$ 与 $k_{\\mathrm{proj}}=1$，再算 KV 路径的 $S_{\\mathrm{KV}}$ 与 $k_{\\mathrm{KV}}=2\\times$层数，两条路径的 $T_{\\mathrm{comm/token}}$ 相加后与 $\\mathrm{quota}$ 比较。判断分三步：</p>\n<ul>\n<li>若 KV 路径的 $\\alpha\\log_2 N$ 项已占该路径下界的一半以上，说明消息被切得太碎，减少分片数或改为同卡共置；</li>\n<li>若投影路径的带宽项主导且 $S_{\\mathrm{proj}}$ 无法通过 batch 摊薄（每图一份），则分置的通信税随图数线性上升，QPS 越高越不划算，应同卡共置；</li>\n<li>若两条路径都在配额内且带宽项主导，分置成立，此时再按 $B^\\*$ 定 batch、按第四节反解 $L_{\\mathrm{ctx}}^{\\max}$ 定上下文上限。</li>\n</ul>\n<p>算例的结论落在机制上：分置与否不取决于总算力是否够，而取决于跨模态投影与 KV 分片的 $S$ 是否让 $T_{\\mathrm{comm}}$ 超过流水可隐藏的预算——这正是公式在部署决策中的原始用途。工程上把这个判断做成容量规划表的一列，每次改并行度、改 batch、改上下文长度都重算一遍 $T_{\\mathrm{comm/token}}$，比事后调 kernel 便宜得多；而一旦发现某配置的通信下界贴着配额上限，就该预判它在负载抖动下必然破 SLO，提前把并行度或上下文预算让出来，而不是等 P99 超标再回滚。</p>\n\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-26\">二十六 · 把通信下界折进批大小、并行度与 KV 预算的决策链</h3>\n<p>这个下界在容量决策里的正确用法不是“算出一个数然后和实测比”，而是把它当成一条**可行性约束**去反解其他变量。给定单次集合通信消息 $S$、参与 GPU 数 $N$ 与实测有效带宽 $\\mathrm{BW}_{\\mathrm{NVLink}}$，先算出 $T_{\\mathrm{comm}}$ 的下界；再把它与单步计算时延 $T_{\\mathrm{compute}}$ 比较，得到可隐藏比例 $\\rho = T_{\\mathrm{compute}}/(T_{\\mathrm{compute}}+T_{\\mathrm{comm}})$。若 $\\rho$ 低于流水重叠所需的门槛，则该并行切分不可行，必须回到批大小或切分维度上改。工程上更实用的写法是反解批大小上限：把每 token 每层需集合通信的字节数记为 $s$，则 $S = B \\cdot s$，代入下界得 $B \\le \\dfrac{\\mathrm{BW}_{\\mathrm{NVLink}}}{2(N-1)/N \\cdot s}\\left(\\dfrac{T_{\\mathrm{comm}}^{\\mathrm{budget}}}{1} - \\alpha\\log_2 N\\right)$ 的可行域——注意括号内一旦为负，说明固定时延项已吃掉全部预算，此时**增大批大小毫无用处**，只能减小 $N$ 或改共置。这正是小消息场景的边界：单层 KV 分片、单 token 视觉激活这类 $S$ 极小的消息，$\\alpha\\log_2 N$ 主导，带宽项失效，用带宽反解批大小会得出荒谬的大值。</p>\n<p>并行度决策同理，但方向相反。张量并行度 $N$ 增大时带宽项系数 $2(N-1)/N$ 趋近 2 而固定项 $\\alpha\\log_2 N$ 单调上升，因此存在一个使 $T_{\\mathrm{comm}}$ 最小的 $N^\\*$；超过它，通信下界随 $N$ 上升而计算时延随 $N$ 下降，两条曲线的交点就是该模型该批大小下的最优并行度。GB200/GB300 NVL72 内 NVLink 5 的非全互联拓扑使这个交点比全互联假设下更靠左：跨域跳数抬高有效 $\\alpha$ 并压低实测 $\\mathrm{BW}_{\\mathrm{NVLink}}$，按全互联估算会把 $N^\\*$ 定得偏大，上线后 all-reduce 时延高于下界估计，SLO 直接失守。多模态分置场景是这条约束最尖锐的地方：视觉编码器与 LLM 分置不同 GPU 时，跨模态投影与 KV 传输都计入 $S$，若这部分 $S$ 使 $T_{\\mathrm{comm}}$ 超过流水可隐藏预算，正确动作是改为同卡共置或减少分片数，而不是加大批大小去“摊薄”通信——摊薄只对带宽项有效，对固定项无效。</p>\n<p>KV 预算的定法要把通信下界换算成等效显存代价。设每 token KV 字节为 $k$，批大小 $B$、上下文 $L$，则 KV 总量 $M_{\\mathrm{KV}} = B \\cdot L \\cdot k$；当 KV 按张量并行切分时，每卡持有 $M_{\\mathrm{KV}}/N$，但每次分片同步都要付一次 $S \\propto B \\cdot L \\cdot k / N$ 的集合通信，其下界随时延预算反向压缩了可用的 $B \\cdot L$ 乘积。于是容量规划变成三元约束：显存给 $B\\cdot L$ 上限，通信下界给 $B\\cdot L$ 的另一个上限，SLO 的 TTFT/TPOT 给第三个。三者取最小者才是真实可部署点。一个算例：某多模态服务把视觉编码器与 LLM 分置两组 GPU，跨模态 KV 分片每步 $S$ 落在小消息区间，$\\alpha\\log_2 N$ 项主导，此时即便显存允许把批大小翻倍，通信下界已使 TPOT 预算耗尽，正确判断是把两组共置以消掉跨模态集合通信，代价是单卡显存占用上升、可服务并发下降——这是用显存换 SLO 的典型交换。</p>\n<p>失效条件必须写进决策表，否则公式会被误用成“万能估算器”。三条硬边界：其一，ring/tree all-reduce 且消息可完全流水的前提不成立时（如依赖链上的串行归约），下界失去意义；其二，$\\mathrm{BW}_{\\mathrm{NVLink}}$ 必须是实测有效单向带宽，NVLink 5 在 NVL72 内非全互联拓扑下跨域跳数会拉低它，用理论峰值代入会系统性低估时延；其三，跨 NVL72 域的 scale-out 场景必须换用 IB 带宽与更陡的拓扑项，把机柜内下界直接套到跨机柜容量规划上会失真。把这三条做成部署前的检查项，比事后调参便宜得多。</p>\n<table class=\"mini\"><thead><tr><th>决策变量</th><th>受下界约束的方式</th><th>失效信号</th></tr></thead><tbody><tr><td>批大小 $B$</td><td>反解可行域，固定项为负则封顶</td><td>加大批大小 TPOT 不降反升</td></tr><tr><td>并行度 $N$</td><td>带宽项与固定项交点定 $N^*$</td><td>实测时延高于按全互联估的下界</td></tr><tr><td>KV 预算</td><td>与显存、SLO 三元取最小</td><td>显存够但 TPOT 超预算</td></tr><tr><td>分置/共置</td><td>跨模态 $S$ 是否可被流水隐藏</td><td>小消息场景通信预算被低估</td></tr></tbody></table>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-27\">二十七 · 把下界塞进容量决策：批大小、并行度、KV 预算与 SLO 的联立</h3>\n<p>这个下界在工程上的正确用法不是“算一个数看看”，而是把它当作约束不等式塞进容量方程组。给定 SLO 允许的单 token 时延预算 <span>T_slo</span>，减去计算时延与调度开销后剩下的部分就是通信预算 <span>T_comm^budget</span>；把公式反解，得到在给定 N 与 BW 下允许的最大消息字节数 <span>S_max ≈ (T_comm^budget − α·log₂N)·N·BW/(2(N−1))</span>。这个 S_max 直接决定三件事：批大小（每轮 all-reduce 的激活字节随 batch 线性增长，故 batch_max ∝ S_max）、张量并行度（N 增大使带宽项系数 2(N−1)/N 趋近 2 而固定项 log₂N 继续涨，存在一个使 T_comm 最小的 N*，超过它加卡只增时延不增吞吐）、以及 KV 预算（若 KV 分片要跨 GPU 汇聚，每层每头的分片字节必须落在 S_max 内，否则要么减分片数、要么退回共置）。三者的耦合点在于：调大 batch 提升吞吐却推高 S，调大 N 降低单卡显存却推高固定项，KV 分片粒度则是两者之间的第三个自由度。</p>\n<p>算例走一遍量级关系而不编造具体带宽：设 SLO 预算中划给 all-reduce 的部分为 T_comm^budget，单跳固定时延 α 与 log₂N 相乘后在小消息区已占去相当比例。取视觉编码器与 LLM 分置方案，跨模态投影张量尺寸为 S_proj，若 S_proj 落在“α·log₂N 与带宽项同量级”的过渡区，则 N 从 8 加到 16 时带宽项系数仅从 1.75 变到 1.875，而固定项翻倍——此时加卡是净亏。反之若 S_proj 远大于过渡点，带宽项主导，加卡摊薄单卡消息量才有收益。工程判断因此落在一条分界线上：先估出 α·log₂N 与 2(N−1)S/(N·BW) 谁大，再决定是“加并行度”还是“减分片/改共置”。KV 分片场景尤其危险，单层单头 KV 分片是小消息，误用带宽项会把通信开销低估一个量级，容量规划随之系统性偏乐观。</p>\n<table class=\"mini\"><thead><tr><th>决策变量</th><th>受下界约束的方式</th><th>越界后的系统代价</th></tr></thead><tbody><tr><td>批大小</td><td>batch 增大使 S 线性增，T_comm 带宽项同比增</td><td>吞吐看似涨，尾时延击穿 SLO，P99 抖动</td></tr><tr><td>并行度 N</td><td>固定项 α·log₂N 随 N 涨，存在 N*</td><td>加卡不加速，NVLink 带宽与功耗被空耗</td></tr><tr><td>KV 分片粒度</td><td>分片字节须 ≤ S_max</td><td>小消息区固定项主导，KV 汇聚成瓶颈</td></tr></tbody></table>\n<p>边界与失效条件必须写进决策表而非脚注。第一，公式假设 ring/tree 且消息可完全流水，一旦流水被计算-通信同步点打断（如视觉编码器输出必须等 LLM 首层注意力的跨模态投影完成），实际时延高于下界，此时应把重叠率作为折减因子乘进预算，而不是相信下界即实测。第二，BW 是实测有效单向带宽，NVL72 内非全互联拓扑下跨域跳数会拉低有效带宽，按全互联估算会把 S_max 估大，批大小与 KV 分片随之上调，上线后才发现 all-reduce 时延高于估计——这是最典型的容量规划失真路径。第三，公式不含跨机柜 scale-out，一旦并行度或 KV 分片跨越 NVL72 域，必须换成 IB 带宽与更陡的拓扑项重算，直接套用机柜内下界会低估跨域代价。第四，多模态分置方案中跨模态投影与 KV 传输都要计入同一个 S，若只算其中一项，预算被系统性低估。最终落到一个可执行的工程判据：先用 α·log₂N 与带宽项的比值判断当前消息处于哪个区，小消息区优先减 N、减分片或共置，大消息区才考虑加并行度；任何跨域或非全互联拓扑都必须重测 BW 后重解 S_max。</p>\n<h3 id=\"th-nvl72-collective-lower-bound-sec-28\">二十八 · 误用一：小消息套带宽项，固定时延被吃掉</h3>\n<p>下界公式里两项并置，工程上最容易犯的错是只盯着第一项。$2(N-1)/N \\cdot S/\\mathrm{BW}_{\\mathrm{NVLink}}$ 随 $S$ 线性增长，看起来\"可控\"；而 $\\alpha \\log_2 N$ 在 $S$ 很小时反而是主项。以单层 KV 分片为例：一个解码步里，若把每层 KV 按头切分到 $N$ 张 GPU 上做 all-reduce 归约注意力输出，单次消息 $S$ 往往只是几十 KB 量级。此时带宽项在 NVLink 5 的有效带宽下折算出的时间远小于单跳固定时延乘以 $\\log_2 N$ 的跳数项。用带宽项估算，会得出\"通信可忽略、完全能被计算重叠隐藏\"的结论；而真实时延由固定项主导，重叠窗口根本盖不住。</p>\n<p>识别方法很直接：把 $S$ 与 $\\mathrm{BW}_{\\mathrm{NVLink}} \\cdot \\alpha$ 这个\"特征消息量\"作比较。当 $S$ 显著小于该特征量时，公式退化为 $\\alpha \\log_2 N$ 主导，此时任何\"按字节数除以带宽\"的估算都系统性偏低。工程后果是解码阶段的 TPOT 预算被低估：连续批处理里每个 step 都要付一次这个固定时延，batch 再大也摊不薄它——固定项与 batch 无关，只与 $N$ 和拓扑跳数有关。于是容量规划给出的\"每 GPU 可承载并发数\"偏乐观，上线后 SLO 在长上下文、小 batch 的尾延迟上先崩。</p>\n<div class=\"formula\">$$S \\ll \\mathrm{BW}_{\\mathrm{NVLink}}\\cdot\\alpha \\;\\Rightarrow\\; T_{\\mathrm{comm}} \\approx \\alpha\\log_2 N$$</div>\n<p>正确的做法是把每个集合通信调用按 $S$ 分档：大消息（视觉 token 激活整块、大段 KV 预填）走带宽项估算，小消息（逐层 KV 分片、梯度式归约、路由 all-to-all 的小包）走固定项估算，两者取和而不是取其一。这也是为什么在 NVFP4/FP8 精度下把 KV 分片切得更细、把 TP 度推得更高，并不总是更快——切细降低单卡显存，却把通信推入固定项主导区。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-29\">二十九 · 误用二：把 NVL72 当全互联，跳数被抹平</h3>\n<p>公式中的 $\\mathrm{BW}_{\\mathrm{NVLink}}$ 是实测有效单向带宽，不是链路峰值。NVL72 机柜内 NVLink 5 的拓扑并非任意两 GPU 等距全互联，跨域通信要经交换层级，跳数增加会同时抬高固定项里的有效 $\\alpha$ 并压低有效带宽。把峰值带宽直接代入，等价于假设零跳数、零争用，得到的下界变成\"乐观下界\"，而容量决策需要的恰恰是\"可达下界\"。</p>\n<p>识别信号：当实测 all-reduce 时延随 $N$ 增长的斜率明显陡于 $\\log_2 N$，或同一 $S$ 在不同 GPU 对之间的时延出现分层（同域快、跨域慢），就说明拓扑项被漏掉了。工程后果体现在并行策略选择上：TP 度从 8 推到 16、32 时，若按全互联估算会认为时延只按 $\\log_2 N$ 缓慢上升，实际跨域跳数让有效带宽下降，时延抬升快于预期。对 GB200/GB300 NVL72 上的大模型推理，这意味着高 TP 度下的解码吞吐被高估，而预填阶段的大消息 all-reduce 又因带宽项主导而更敏感于有效带宽的折损。修正方式是把 $\\mathrm{BW}_{\\mathrm{NVLink}}$ 换成按域对实测的值，并在 $\\alpha$ 中计入平均跳数，而不是沿用单跳常数。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-30\">三十 · 误用三：机柜内下界外推到 scale-out</h3>\n<p>第三个误用是把 NVL72 机柜内的下界直接搬到跨机柜场景。公式的适用边界明确排除了 scale-out：跨 NVL72 域通信要走 IB，带宽量级与 NVLink 5 不同，拓扑项也更陡——跨域不再是 $\\log_2 N$ 量级的跳数，而是受 fabric 层级与拥塞影响的更复杂项。把机柜内公式套到多机柜部署，等于用最乐观的互联假设去规划最昂贵的资源。</p>\n<p>识别方法：看通信域是否跨越 NVL72 边界。一旦 $N$ 超过单机柜 GPU 数，或通信路径经过 IB 交换机，就必须切换带宽参数与拓扑项，而不是简单把 $N$ 代进原式。工程后果是分离式预填/解码（PD 分离）的部署判断失真：PD 分离的收益来自把预填与解码放到不同资源池，但跨池 KV 传输若走 IB，其下界远高于机柜内估算，KV 传输时间可能吃掉分离带来的流水收益。同理，专家并行（EP）的 all-to-all 一旦跨机柜，路由小包的固定项与 fabric 拥塞叠加，容量规划会明显偏离。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-31\">三十一 · 反例：一次被低估的解码步通信预算</h3>\n<p>设一个多模态推理部署：视觉编码器放在一组 GPU 上，LLM 放在另一组，两者在 NVL72 机柜内分置。跨模态投影后的视觉 token 激活需要送入 LLM，KV 分片在 LLM 的 TP 组内逐层归约。团队按带宽项估算：视觉激活块较大，带宽项算出可被预填计算重叠隐藏；KV 分片很小，直接按\"字节数除以带宽\"得出每步几微秒，判定可忽略。上线后解码 TPOT 超出预算，且 batch 越小越差。</p>\n<p>复盘：视觉激活那一侧带宽项估算基本成立，问题出在 KV 分片。逐层 KV 分片的 $S$ 落在固定项主导区，每个解码步、每一层都要付一次 $\\alpha \\log_2 N$，层数一乘就把\"几微秒\"放大成可观的每步固定开销；而 batch 增大并不能摊薄它，因为固定项与并发无关。更糟的是 TP 组跨了机柜内的域边界，有效带宽低于峰值、有效 $\\alpha$ 高于单跳常数，实际时延比按全互联估算的还高。正确的修正不是加大 batch，而是减少分片数、把 KV 归约合并成更大的消息（让带宽项重新主导），或把 LLM 的 TP 组约束在同一域内以压低跳数。这个反例说明：下界公式的两项必须同时代入，且 $\\mathrm{BW}_{\\mathrm{NVLink}}$ 与 $\\alpha$ 必须是实测有效值——任何一项被简化，容量决策就会朝乐观方向偏。</p>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-32\">三十二 · 识别清单：把误用挡在建模阶段</h3>\n<p>把上述三类误用收敛成可执行的检查项，放在容量规划与部署评审的入口处，比事后调参便宜得多。</p>\n<ul>\n<li>消息分档：对每个集合通信调用记录 $S$，与 $\\mathrm{BW}_{\\mathrm{NVLink}}\\cdot\\alpha$ 比较，标注\"带宽主导/固定主导\"，固定主导的调用单独计入每步固定开销预算。</li>\n<li>拓扑实测：$\\mathrm{BW}_{\\mathrm{NVLink}}$ 与 $\\alpha$ 按域对实测填入，禁止用链路峰值；跨域调用额外标注平均跳数。</li>\n<li>域边界检查：$N$ 超过单机柜 GPU 数或路径经 IB 时，强制切换参数集，原式不得直接外推。</li>\n<li>重叠核算：固定项主导的调用不可被计算重叠隐藏，须从\"可隐藏预算\"中剔除后再判断 PD 分离或高 TP 度是否划算。</li>\n<li>敏感度回看：对 TP 度、KV 分片粒度、batch 三个旋钮做扰动，若 TPOT 预测对分片粒度高度敏感，说明模型已进入固定项主导区，应回退粒度而非继续加并行。</li>\n</ul>\n<p>这套清单的落点是：下界公式不是一条用来\"算一个数\"的式子，而是一个判别器——它告诉你当前部署落在带宽项区还是固定项区，从而决定该加并行还是该合并消息、该同卡共置还是该分离。把判别做在建模阶段，比在 GB200/GB300 NVL72 上跑出尾延迟超标再回头找原因，代价低一个量级。</p>\n\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-33\">三十三 · 下界不是承诺：三类误用如何把 NVL72 通信预算算反</h3>\n<p>这套下界最危险的地方在于它长得像一条“性能承诺”。工程上真正会出事的，不是算错常数，而是把适用域悄悄换掉却仍沿用同一个式子。第一类误用是把 NVL72 内的 NVLink 5 当成全互联：在 NVL72 机柜里，参与 all-reduce 的 GPU 集合一旦跨越不同交换域，消息并非单跳直达，跨域跳数会抬高单跳固定时延 α 的有效值，也会让实测有效带宽 BW<sub>NVLink</sub> 低于同域内的值。此时仍按“同域全互联”代入公式，得到的 T<sub>comm</sub> 只是理想下界，真实 all-reduce 时延会高于估计。识别方法很直接：把参与集合的 GPU 按物理域分组，若 N 的取值使集合跨越域边界，就必须用实测的跨域有效带宽与跨域跳数重算，而不是沿用同域参数。系统代价体现在流水重叠预算上——预填阶段跨模态投影若被低估，调度器会把本应留出的隐藏窗口压缩掉，表现为解码侧 TPOT 抖动而非预填变慢，排查时极易误判为批调度问题。</p>\n<p>第二类误用是小消息场景只保留带宽项。公式中带宽项为 2(N−1)/N·S/BW<sub>NVLink</sub>，固定项为 α·log₂N；当 S 小到带宽项低于固定项时，α·log₂N 主导，带宽项事实上失效。典型触发场景是逐层 KV 分片传输、单层激活同步这类小消息集合通信：此时把 S 除以带宽得到的“理论时延”远小于真实值，通信预算被系统性低估。判别式可以写成两项之比：当 2(N−1)S/(N·BW<sub>NVLink</sub>) 小于 α·log₂N 时，继续用带宽项估算就是错的。工程后果是流水重叠设计失效——按带宽项算出的隐藏窗口装不下真实的固定时延，多模态并行中视觉编码器与 LLM 分置不同 GPU 时，跨模态投影的小消息同步会成为每层可见的停顿，而不是被掩盖的尾部。正确做法是把固定项当作不可压缩的底噪计入每层预算，再判断分片数 N 是否值得增大：N 增大时 log₂N 缓增而带宽项趋近 2S/BW，小消息下增大 N 几乎只增加固定开销。</p>\n<p>第三类误用是把机柜内下界直接搬到跨机柜 scale-out。该式未计入跨 NVL72 域的 IB 通信：跨域集合通信必须改用 IB 有效带宽，并叠加更陡的拓扑项，因为跨域路径的跳数与拥塞结构都与机柜内不同。把 NVLink 带宽代入跨域容量规划，会得出偏乐观的并行切分方案——例如把张量并行或专家并行跨域铺开，规划时以为通信可隐藏，上线后跨域 all-reduce 成为瓶颈。识别信号是：并行组的 GPU 分布跨越机柜边界，而容量模型里仍只有一项 NVLink 带宽。系统代价是容量规划失真与 SLO 违约，且这种失真不会在单机柜小规模压测中暴露。</p>\n<p>一个具体反例：某多模态服务把视觉编码器与 LLM 分置不同 GPU，跨模态投影按“全互联 NVLink、大消息带宽项”估算，认为投影与 KV 分片可被流水完全隐藏。实际投影消息 S 很小、参与集合跨域，固定项 α·log₂N 与跨域跳数共同抬高了 T<sub>comm</sub>，隐藏窗口装不下，解码侧出现周期性停顿。修正路径不是加大缓冲，而是按两项之比重新判断：小消息下减少分片数 N 以压低 log₂N，或改为同卡共置消除跨模态通信；只有当 S 足够大、带宽项重新主导时，分置才有意义。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>失效机制</th><th>识别信号</th><th>系统代价</th></tr></thead><tbody><tr><td>按全互联估带宽</td><td>跨域跳数抬高 α 有效值、压低 BW</td><td>集合跨交换域但参数未换</td><td>预填隐藏窗口不足，TPOT 抖动</td></tr><tr><td>小消息只用带宽项</td><td>α·log₂N 主导，带宽项失效</td><td>带宽项低于固定项</td><td>逐层同步停顿，分片数越大越糟</td></tr><tr><td>机柜内下界套跨机柜</td><td>未改用 IB 带宽与更陡拓扑项</td><td>并行组跨机柜而模型只有 NVLink 项</td><td>容量规划失真，SLO 违约</td></tr></tbody></table>\n\n<h3 id=\"th-nvl72-collective-lower-bound-sec-34\">三十四 · 下界失效的三种典型场景与识别方法</h3>\n<p>最常见的误用是把下界公式当成“任意规模都成立”的估算器。公式中的带宽项 $\\frac{2(N-1)}{N}\\frac{S}{\\mathrm{BW}_{\\mathrm{NVLink}}}$ 只有在消息足够大、流水充分时才主导；当 $S$ 缩小到单层 KV 分片或单个视觉 token 激活的量级时，$\\alpha\\log_2 N$ 的固定跳数项反而吃掉大部分预算。识别方法很直接：把两项分别算出量级，若 $\\alpha\\log_2 N$ 与带宽项同阶或更大，就说明当前工作点落在固定时延区，此时继续增大 $N$ 只会让 $\\log_2 N$ 缓慢上升而带宽项几乎不变，扩容收益被固定项吞掉。工程上应改为减少参与集合通信的 GPU 数、合并小消息，或把这类小分片通信移出关键路径。</p>\n<p>第二种误用是把 NVL72 机柜内的 NVLink 5 当成全互联。实际拓扑中跨域跳数会增加，$\\mathrm{BW}_{\\mathrm{NVLink}}$ 必须取实测有效单向带宽而非理论峰值，否则算出的下界系统性偏低。反例：某多模态服务把视觉编码器放在一组 GPU、LLM 放在另一组，跨模态投影与 KV 分片按全互联带宽估算通信预算，认为流水重叠足以隐藏；上线后发现跨域跳数使有效带宽下降，$T_{\\mathrm{comm}}$ 超出可隐藏预算，解码步被通信拖住，TPOT 抖动明显。正确做法是按实际放置计算跳数加权后的有效带宽，再代入公式判断是否值得分置——若 $S$ 与跳数共同导致 $T_{\\mathrm{comm}}$ 超过重叠预算，应改为同卡共置或减少分片数。</p>\n<p>第三种误用是跨边界套用：把机柜内下界直接搬到跨机柜 scale-out 场景。跨 NVL72 域通信走 IB，带宽更低且拓扑项更陡，公式中的 $\\mathrm{BW}_{\\mathrm{NVLink}}$ 与 $\\log_2 N$ 都不再适用，容量规划会明显失真。可用一张小表快速自查：</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>后果</th><th>识别信号</th></tr></thead><tbody><tr><td>小消息只用带宽项</td><td>通信预算低估</td><td>$\\alpha\\log_2 N$ 与带宽项同阶</td></tr><tr><td>按全互联取带宽</td><td>下界偏低、TPOT 抖动</td><td>跨域跳数使实测带宽下降</td></tr><tr><td>套用到 scale-out</td><td>容量规划失真</td><td>跨机柜走 IB、拓扑项更陡</td></tr></tbody></table>\n<p>识别这些失效的统一判据是：先确认消息是否可完全流水、拓扑是否在机柜内、$N$ 是否落在固定项主导区，三者任一不满足就应改写公式而非直接套用。系统代价体现在解码阶段的尾延迟与显存驻留——被低估的通信开销会迫使 KV 分片滞留更久，挤占本就紧张的 HBM 预算。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>N</td><td>参与集合通信的 GPU 数</td></tr><tr><td>S</td><td>单次集合通信消息字节数（如视觉 token 激活或 KV 分片）</td></tr><tr><td>\\mathrm{BW}_{\\mathrm{NVLink}}</td><td>NVLink 有效单向带宽</td></tr><tr><td>\\alpha</td><td>单跳通信固定时延</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-nvl72-collective-lower-bound · 共 5 个片段</p>\n"},{"id":"th-visual-encoder-roofline","title":"视觉编码器 Roofline 界","direction":"dir-multimodal-serving","prereq":[],"plain":"视觉编码器在 Blackwell 上的单图推理时间由算力峰值与 HBM 带宽共同决定：当视觉 token 数较少时受权重加载带宽约束，当分辨率与 token 数增大后转为受 Tensor Core 算力约束，二者交点决定最优 batch 与分辨率配置。","definition":"视觉编码器在 Blackwell 上的单图推理时间由算力峰值与 HBM 带宽共同决定：当视觉 token 数较少时受权重加载带宽约束，当分辨率与 token 数增大后转为受 Tensor Core 算力约束，二者交点决定最优 batch 与分辨率配置。","formula":"$$T_{\\mathrm{enc}} \\ge \\max\\left(\\frac{2\\,N_{\\mathrm{vis}}\\,d_{\\mathrm{enc}}\\,L_{\\mathrm{enc}}\\,P_{\\mathrm{enc}}}{F_{\\mathrm{peak}}\\,\\eta_{\\mathrm{comp}}},\\;\\frac{W_{\\mathrm{enc}}\\,B_{\\mathrm{bytes}}}{\\mathrm{BW}_{\\mathrm{HBM}}\\,\\eta_{\\mathrm{mem}}}\\right)$$","variables":[{"sym":"N_{\\mathrm{vis}}","meaning":"单张图像经 patch 化后的视觉 token 数"},{"sym":"d_{\\mathrm{enc}}","meaning":"视觉编码器隐藏维度"},{"sym":"L_{\\mathrm{enc}}","meaning":"视觉编码器 Transformer 层数"},{"sym":"P_{\\mathrm{enc}}","meaning":"视觉编码器参数量（含 patch embed 与位置编码）"},{"sym":"F_{\\mathrm{peak}}","meaning":"Blackwell SM 的 FP16/BF16 Tensor Core 峰值算力"},{"sym":"\\mathrm{BW}_{\\mathrm{HBM}}","meaning":"HBM3e 峰值带宽"},{"sym":"\\eta_{\\mathrm{comp}},\\eta_{\\mathrm{mem}}","meaning":"算力与带宽的实际可达效率因子"}],"derivation":"第二项 $$\\frac{W_{\\mathrm{enc}} B_{\\mathrm{bytes}}}{\\mathrm{BW}_{\\mathrm{HBM}}\\eta_{\\mathrm{mem}}}$$ 中，$$W_{\\mathrm{enc}}$$ 为编码器权重元素数，$$B_{\\mathrm{bytes}}$$ 为每元素字节数（BF16 为 2），乘积是单次前向必须从 HBM3e 搬入的权重字节量，除以峰值带宽与效率因子得到权重加载下界，代表带宽受限分支。","example":"适用边界：仅对稠密 Transformer 视觉编码器且序列长度足以让 GEMM 达到高利用率时成立；224×224、196 token 的小分辨率下 kernel 启动与固定开销占主导，roofline 会低估实际时延；假设权重与激活可完全重叠加载且无跨 stage 同步。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["仅当视觉编码器为稠密 Transformer 且序列长度足以让 GEMM 达到高利用率时成立；小分辨率（如 224×224、196 token）下 kernel 启动与固定开销占主导，roofline 会低估实际时延。","假设权重与激活可完全重叠加载且无跨 stage 同步；在 NVL72 多卡切分视觉编码器时，集合通信与流水气泡会破坏该下界。","未计入图像预处理（resize、normalize、patch embedding 的 layout 变换）开销，当输入为高分辨率视频帧流时预处理可能成为真正瓶颈。"],"system_note":"容量决策用途：给定目标分辨率与帧率，可用该界反推单卡可承载的最大并发图像数（batch 上限），并判断扩容应优先提升算力（换更高 F 的 SKU）还是带宽（更多 HBM 通道），避免盲目加卡。","papers":["paper-an-image-is-worth-16x16-words-transf-2020"],"facts":["直觉：视觉编码器单图时延取下界由两条曲线中较高者决定——权重加载的 HBM 带宽项与视觉 token 的 Tensor Core 算力项；交点即最优 batch/分辨率配置的切换点。","公式第一项 $$\\frac{2 N_{\\mathrm{vis}} d_{\\mathrm{enc}} L_{\\mathrm{enc}} P_{\\mathrm{enc}}}{F_{\\mathrm{peak}}\\eta_{\\mathrm{comp}}}$$ 中，分子近似为前向每 token 每层两次矩阵乘的乘加量（2 倍因子来自 MAC 计为 2 FLOP），分母是 Blackwell SM 的 FP16/BF16 峰值算力乘可达效率，量纲为秒，代表算力受限分支。","第二项 $$\\frac{W_{\\mathrm{enc}} B_{\\mathrm{bytes}}}{\\mathrm{BW}_{\\mathrm{HBM}}\\eta_{\\mathrm{mem}}}$$ 中，$$W_{\\mathrm{enc}}$$ 为编码器权重元素数，$$B_{\\mathrm{bytes}}$$ 为每元素字节数（BF16 为 2），乘积是单次前向必须从 HBM3e 搬入的权重字节量，除以峰值带宽与效率因子得到权重加载下界，代表带宽受限分支。","推导关键一步：把编码器前向拆成逐层 GEMM 的算力需求与权重流式加载需求，对每层取 max 后沿层累加；当 batch=1 且 token 少时权重项主导，随 $$N_{\\mathrm{vis}}$$ 线性增长的算力项最终反超，交点给出算力/带宽平衡的 token 数阈值。","适用边界：仅对稠密 Transformer 视觉编码器且序列长度足以让 GEMM 达到高利用率时成立；224×224、196 token 的小分辨率下 kernel 启动与固定开销占主导，roofline 会低估实际时延；假设权重与激活可完全重叠加载且无跨 stage 同步。","容量决策用途：给定目标分辨率与帧率，可用该界反推单卡可承载的最大并发图像数（batch 上限），并判断扩容应优先提升算力（换更高 F 的 SKU）还是带宽（更多 HBM 通道），避免盲目加卡。","常见误用：把该界当作实测时延而非下界，忽略预处理（resize、normalize、patch embedding 的 layout 变换）开销；在高分辨率视频帧流场景中预处理可能成为真正瓶颈，导致按 roofline 规划的 batch 在现场严重超时。","常见误用：在 NVL72 多卡切分视觉编码器时直接套用单卡公式，集合通信与流水气泡破坏该下界，实际吞吐远低于按公式推算值；应把通信项显式加入或改用单卡整编码器部署。"],"anchors":["224×224","196 token","NVL72","HBM3e","FP16/BF16"],"pitfalls":["把 roofline 下界当成实测时延做 SLA 承诺，未计入 resize、normalize 与 patch embedding 的 layout 变换开销，视频帧流场景下预处理反超编码器成为真瓶颈。","在 NVL72 多卡切分视觉编码器时直接套用单卡公式，忽略集合通信与流水气泡，按公式推算的并发数在现场无法达到，造成容量规划系统性高估。","在小分辨率（196 token）场景仍用 roofline 估算时延，kernel 启动与固定开销占主导，公式低估实际时延，导致 batch 配置过于激进而超时。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-1\">一 · 一句话直觉与它的物理来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-2\">二 · 严格定义：两项、四个效率因子、一个 max</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-3\">三 · 为什么需要这个界：三个决策场景</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-4\">四 · 常见误解之一：把下界当实测时延</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-5\">五 · 常见误解之二：小分辨率下界仍成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-6\">六 · 常见误解之三：多卡切分仍套单卡公式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-7\">七 · Roofline 的适用边界：它在哪里成立，又在哪里失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-8\">八 · 两项的分子从哪来：逐层 GEMM 的乘加账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-9\">九 · 第二项的字节账与“权重流式”假设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-10\">十 · 取 max 与沿层累加的推导关键步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-11\">十一 · 离散化与近似落在哪三处</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-12\">十二 · 用界反推 batch 上限与扩容方向</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-13\">十三 · 公式的适用域与不可外推之处</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-14\">十四 · 下界成立的四道门槛：重叠假设、切分代价、预处理与 kernel 启动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-15\">十五 · 两项取大的适用边界与失效路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-16\">十六 · 算力项成立的前提：GEMM 必须真的跑满</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-17\">十七 · 带宽项的三个隐含假设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-18\">十八 · 跨 stage 同步与多卡切分：下界被通信项击穿</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-19\">十九 · 预处理：公式之外的真正瓶颈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-20\">二十 · 规模上限：公式在哪个区间失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-21\">二十一 · 把边界写进容量模型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-22\">二十二 · 适用边界：假设、失效条件、规模上限；什么情况下公式不再成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-23\">二十三 · 从下界到批上限：把 T_enc 反解成 N_max</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-24\">二十四 · 定并行度：切分前先算通信项是否吃掉收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-25\">二十五 · 定 KV 预算：编码器输出如何折算成显存占用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-26\">二十六 · 定 SLO：下界与实测之间的安全裕度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-27\">二十七 · 算例：一条从分辨率到并发数的完整链路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-28\">二十八 · 把下界变成容量决策：批大小、并行度与 SLO 的换算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-29\">二十九 · 把下界当预算：批上限、并行度与 SLO 的换算口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-30\">三十 · 误用一：把下界当承诺——SLA 与预处理黑洞</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-31\">三十一 · 误用二：小分辨率场景套大公式——固定开销主导区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-32\">三十二 · 误用三：NVL72 多卡切分直接套单卡公式——通信项缺失</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-33\">三十三 · 反例：一次按 roofline 规划的容量事故复盘</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-34\">三十四 · 识别清单：什么时候不该信这个界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-35\">三十五 · 工程判断：把界用在决策上而非承诺上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-encoder-roofline-sec-36\">三十六 · 误用解剖：把下界当承诺、把单卡公式套到 NVL72、把 196 token 当成 roofline 的适用区</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:521px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 521.1 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"439.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"439.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：视觉编码器在 Blackwell 上的单图推理时间由算力峰值与 H…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"439.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$T_{\\mathrm{enc}} \\ge \\max\\left(…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"439.1\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：仅当视觉编码器为稠密 Transformer 且序列长度足以让 G…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-visual-encoder-roofline-sec-1\">一 · 一句话直觉与它的物理来源</h3>\n<p>视觉编码器在 Blackwell 上的单图时延，取下界时由两条曲线中较高的那条决定：一条是“把权重从 HBM3e 搬进来”的带宽曲线，另一条是“把视觉 token 送进 Tensor Core 做矩阵乘”的算力曲线。二者交点，就是最优 batch 与分辨率配置的切换点。这不是类比，而是把前向拆成逐层 GEMM 后，对每层取 max 再沿层累加的直接结果：每一层要么在等权重到位，要么在等 Tensor Core 排空，谁更慢谁定义该层的时间。</p>\n<p>物理来源很具体。权重是静态的，每跑一次前向就必须完整流过一遍 HBM；token 是动态的，随分辨率增长而线性膨胀。当 <span class=\"sym\">N</span><sub>vis</sub> 很小（例如 224×224 输入、196 token），算力项几乎可以忽略，时间被权重加载钉死；当分辨率抬高、token 数上千，算力项线性反超，编码器转为算力受限。这条“先带宽后算力”的转折，正是 roofline 在视觉编码器上的具体形态，也是容量规划里判断“该换更高 F 的 SKU 还是加 HBM 通道”的唯一依据。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-2\">二 · 严格定义：两项、四个效率因子、一个 max</h3>\n<p>把编码器前向视为 <span class=\"sym\">L</span><sub>enc</sub> 层稠密 Transformer，每层含注意力的 QKV 投影、输出投影与前馈网络，逐层 GEMM 的乘加量近似正比于 <span class=\"sym\">N</span><sub>vis</sub>·<span class=\"sym\">d</span><sub>enc</sub>·<span class=\"sym\">P</span><sub>enc</sub>。严格的下界写成：</p>\n<div class=\"formula\">$$T_{\\mathrm{enc}} \\ge \\max\\left(\\frac{2\\,N_{\\mathrm{vis}}\\,d_{\\mathrm{enc}}\\,L_{\\mathrm{enc}}\\,P_{\\mathrm{enc}}}{F_{\\mathrm{peak}}\\,\\eta_{\\mathrm{comp}}},\\;\\frac{W_{\\mathrm{enc}}\\,B_{\\mathrm{bytes}}}{\\mathrm{BW}_{\\mathrm{HBM}}\\,\\eta_{\\mathrm{mem}}}\\right)$$</div>\n<p>第一项的分子里，2 倍因子来自 MAC 计为 2 FLOP；分母是 Blackwell SM 的 FP16/BF16 Tensor Core 峰值算力乘以可达效率 <span class=\"sym\">η</span><sub>comp</sub>，量纲为秒，代表算力受限分支。第二项中 <span class=\"sym\">W</span><sub>enc</sub> 是编码器权重元素数，<span class=\"sym\">B</span><sub>bytes</sub> 是每元素字节数（BF16 为 2），乘积即单次前向必须从 HBM3e 搬入的权重字节量，除以峰值带宽与效率 <span class=\"sym\">η</span><sub>mem</sub>，得到权重加载下界。</p>\n<p>定义的关键不在公式本身，而在“逐层取 max 后沿层累加”这一步。单层内，权重加载与激活计算可以重叠，所以该层耗时是两者较大者；但层与层之间存在依赖，前一层的激活是后一层的输入，因此不能把整网的权重加载与整网的算力需求各自求和后取一次 max——那会低估时延。正确做法是逐层 max 再累加，公式中的 max 是这一累加在“每层瓶颈相同、参数均匀”假设下的闭式近似。这也解释了为什么该界对层结构不均衡的编码器（例如浅层宽、深层窄）会偏松。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-3\">三 · 为什么需要这个界：三个决策场景</h3>\n<p>第一是容量反推。给定目标分辨率与帧率，用该界可反推单卡能承载的最大并发图像数（batch 上限）：把 <span class=\"sym\">N</span><sub>vis</sub> 代入两项，取较大者作为单图时延下界，再用 SLO 时延预算除之。若算力项主导，扩容应优先换 <span class=\"sym\">F</span><sub>peak</sub> 更高的 SKU；若带宽项主导，加卡不如加 HBM 通道或改用更低位宽权重。没有这个界，工程上只能靠试跑，试跑又无法区分“慢在算力”还是“慢在带宽”，扩容方向就是盲的。</p>\n<p>第二是精度选择的代价评估。把权重从 BF16 换成 FP8 或 NVFP4，<span class=\"sym\">B</span><sub>bytes</sub> 下降，带宽项按比例缩小，但 <span class=\"sym\">F</span><sub>peak</sub> 与 <span class=\"sym\">η</span><sub>comp</sub> 的变化取决于 Tensor Core 在该精度下的实际可达率。roofline 让你在动手量化前就看清：当前配置若带宽受限，降位宽直接兑现时延收益；若已算力受限，降位宽只减少权重流量而不缩短关键路径，收益趋近于零。量化误差本身的传播界是另一条条目的主题，此处只谈它对两项的相对位移。</p>\n<p>第三是部署形态判断。单卡整编码器与 NVL72 多卡切分是两种截然不同的 regime。前者公式直接适用；后者引入集合通信与流水气泡，公式退化为一个偏乐观的下界。用界做决策时，必须先把“是否切分”作为前提写清楚，否则容量规划会系统性高估。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-4\">四 · 常见误解之一：把下界当实测时延</h3>\n<p>最普遍的误用是把 <span class=\"sym\">T</span><sub>enc</sub> 直接写进 SLA 承诺。该界只计权重加载与 GEMM 算力，未计入图像预处理：resize、normalize、patch embedding 的 layout 变换。当输入是单张 224×224 静态图时，预处理占比有限；但当输入变为高分辨率视频帧流，预处理可能反超编码器成为真正瓶颈，按 roofline 规划的 batch 在现场严重超时。</p>\n<p>机制上，预处理是访存密集且高度串行的操作，其吞吐由像素搬运与格式转换决定，与 Tensor Core 算力无关，也不随 <span class=\"sym\">N</span><sub>vis</sub> 以 GEMM 的方式扩展。因此它不在两项之内，却与两项串联在同一关键路径上。工程判断是：把预处理时延单独建模为 <span class=\"sym\">T</span><sub>pre</sub>，实际下界应为 <span class=\"sym\">T</span><sub>pre</sub> + <span class=\"sym\">T</span><sub>enc</sub>；当 <span class=\"sym\">T</span><sub>pre</sub> 与 <span class=\"sym\">T</span><sub>enc</sub> 同量级时，优化编码器 kernel 的边际收益被预处理吞掉。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-5\">五 · 常见误解之二：小分辨率下界仍成立</h3>\n<p>该界成立的隐含前提是序列长度足以让 GEMM 达到高利用率。224×224、196 token 的场景恰恰相反：kernel 启动开销、固定开销、以及小 GEMM 的形状低效占主导，roofline 会低估实际时延。此时公式给出的数字偏小，若据此把 batch 配得过于激进，现场就会超时。</p>\n<p>机制上，小 GEMM 的有效算力利用率 <span class=\"sym\">η</span><sub>comp</sub> 远低于大形状下的值，而公式把 <span class=\"sym\">η</span><sub>comp</sub> 当作常数。更准确的做法是让 <span class=\"sym\">η</span><sub>comp</sub> 成为 <span class=\"sym\">N</span><sub>vis</sub> 与 <span class=\"sym\">d</span><sub>enc</sub> 的函数，在小 token 数区间显著下调，或直接改用“固定开销 + 线性项”的分段模型。工程判断：196 token 量级不要用 roofline 定 batch，用实测的 kernel 启动开销做下限校正。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-6\">六 · 常见误解之三：多卡切分仍套单卡公式</h3>\n<p>在 NVL72 上把视觉编码器按层切到多卡时，单卡公式的两个假设同时失效：权重与激活可完全重叠加载、无跨 stage 同步。集合通信（层间激活的全收集或点对点传递）与流水气泡插入关键路径，实际吞吐远低于公式推算值。按公式反推的并发数在现场无法达到，容量规划系统性高估。</p>\n<p>机制上，切分把原本层内的“加载与计算重叠”变成跨卡的“计算与通信重叠”，而通信的启动延迟与带宽占用并不随 <span class=\"sym\">N</span><sub>vis</sub> 缩小。修正方式有两种：把通信项显式加入 max 内成为第三项，或改用单卡整编码器部署、把多卡留给解码侧。对视觉编码器这种层数有限、单层计算量不算巨大的模块，后一种往往更稳——切分带来的并行收益，常常抵不过流水气泡的代价。</p>\n<table class=\"mini\"><thead><tr><th>误解</th><th>失效机制</th><th>系统代价</th><th>校正方向</th></tr></thead><tbody><tr><td>下界当实测时延</td><td>预处理串联在关键路径</td><td>视频帧流场景 SLA 超时</td><td>加 <span class=\"sym\">T</span><sub>pre</sub> 项</td></tr><tr><td>小分辨率仍用公式</td><td>kernel 启动与固定开销主导</td><td>batch 过激、现场超时</td><td>分段模型或实测下限</td></tr><tr><td>多卡切分套单卡</td><td>集合通信与流水气泡</td><td>并发数高估</td><td>加通信项或单卡整部署</td></tr></tbody></table>\n<p>三个误解共享同一个根源：把 max 内的两项当成全集。真实的视觉编码器关键路径上还有预处理、启动开销、跨卡同步三类项，它们不随 token 数线性缩放，因此在小规模与多卡两种极端下最容易反超。判断一个 roofline 结论是否可用，先问三件事：输入是不是高分辨率帧流、token 数是否远离交点、编码器是否被切分。三者任一为真，公式就只能当方向性参考，不能当容量承诺。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-7\">七 · Roofline 的适用边界：它在哪里成立，又在哪里失效</h3>\n<p>把视觉编码器的单图时延写成两条曲线的上包络，前提是编码器前向能被拆成一批足够大的 GEMM，且每一层的权重流式加载与激活计算可以完全重叠。这个前提在稠密 Transformer 视觉编码器、且 <code>N_vis</code> 足够大使 GEMM 达到高利用率时成立；一旦序列变短，kernel 启动、launch 间隙与固定开销开始占据主导，公式给出的就不再是紧下界而是一个偏乐观的估计。224×224 输入、196 token 的场景是典型反例：此时算力项与带宽项都退到很小的量级，真正决定时延的是几十个 kernel 的调度与同步成本，roofline 会系统性低估实际时延，按它配置的 batch 往往在现场超时。判断是否落在适用区，可以看 GEMM 的有效 M 维（即 <code>N_vis</code> 与 batch 的乘积）是否足以填满 Tensor Core 的 tile 深度；填不满时，公式里的 <code>\\eta_{\\mathrm{comp}}</code> 不再是常数效率因子，而会随形状剧烈变化，此时应改用实测的 kernel 级模型而非解析下界。</p>\n<p>第二个边界来自并行切分。单卡公式隐含“权重与激活的加载无跨 stage 同步”这一假设，而把视觉编码器切到 NVL72 的多张 GPU 上时，层间的 all-reduce 或 all-gather 会插入流水气泡，集合通信的时间无法被算力项或带宽项吸收。此时真实下界应写成算力项、带宽项与通信项三者的最大值，通信项取决于切分维度、消息大小与 NVLink 5 的有效带宽；直接套用单卡公式会把并发上限估高，造成容量规划的系统性高估。工程上的取舍很直接：视觉编码器参数量相对 LLM 主干小得多，多数情况下单卡整编码器部署反而比多卡切分更接近 roofline 下界，切分只在单卡显存放不下或需要与主干共置时才有意义。</p>\n<div class=\"formula\">$$T_{\\mathrm{enc}} \\ge \\max\\left(\\frac{2\\,N_{\\mathrm{vis}}\\,d_{\\mathrm{enc}}\\,L_{\\mathrm{enc}}\\,P_{\\mathrm{enc}}}{F_{\\mathrm{peak}}\\,\\eta_{\\mathrm{comp}}},\\;\\frac{W_{\\mathrm{enc}}\\,B_{\\mathrm{bytes}}}{\\mathrm{BW}_{\\mathrm{HBM}}\\,\\eta_{\\mathrm{mem}}},\\;T_{\\mathrm{comm}}(S,\\,BW_{\\mathrm{NVLink}})\\right)$$</div>\n<p>第三个边界是预处理。公式从 patch embedding 之后算起，未计入 resize、normalize 与 layout 变换（如 NHWC 到 NCHW 的重排、patch 展平与位置编码拼接）。在单图、低帧率场景这些开销占比有限；但在高分辨率视频帧流下，每帧都要做双线性重采样与归一化，CPU 侧或独立 copy kernel 的吞吐可能反超编码器本身，成为真正的瓶颈。此时 roofline 规划的 batch 在现场严重超时，因为瓶颈根本不在 GPU 的算力或 HBM 带宽上。诊断方法是把端到端时延拆成预处理段与编码段分别计时，若预处理段占比随分辨率上升而增大，就应把预处理搬到 GPU 上用融合 kernel 完成，或改用支持原地 layout 的输入格式。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>主导项</th><th>roofline 是否紧</th><th>系统代价表现</th></tr></thead><tbody><tr><td>高分辨率、大 token 数、稠密 ViT</td><td>算力项</td><td>紧</td><td>受 Tensor Core 利用率与功耗墙约束</td></tr><tr><td>小分辨率 196 token、batch=1</td><td>固定开销</td><td>松，低估时延</td><td>kernel 启动与同步主导，显存带宽闲置</td></tr><tr><td>NVL72 多卡切分编码器</td><td>通信项</td><td>松，高估并发</td><td>集合通信与流水气泡吃掉吞吐</td></tr><tr><td>高分辨率视频帧流</td><td>预处理</td><td>松，瓶颈错位</td><td>resize/normalize 反超编码器</td></tr></tbody></table>\n<p>把这三条边界合起来看，roofline 界的正确用法是“筛选与反推”而非“承诺”：它适合在给定分辨率与帧率下反推单卡可承载的最大并发图像数，并判断扩容应优先换更高 <code>F_{\\mathrm{peak}}</code> 的 SKU 还是增加 HBM 通道；一旦落到 196 token 的小分辨率、多卡切分或视频帧流，就必须把固定开销、通信项与预处理显式加入模型，否则下界会变成对 SLA 的虚假承诺。真正的工程判断是：先用 roofline 定位瓶颈分支，再用实测确认该分支是否被其他开销遮蔽——遮蔽发生时，优化方向应从算力或带宽转向 kernel 融合、单卡整编码器部署与预处理下沉。</p>\n<h3 id=\"th-visual-encoder-roofline-sec-8\">八 · 两项的分子从哪来：逐层 GEMM 的乘加账</h3>\n<p>公式第一项的分子是 <span class=\"inline-math\">2 N_vis d_enc L_enc P_enc</span>。要理解它，必须把视觉编码器前向拆到逐层 GEMM 的粒度，而不是停留在“参数量乘 token 数”这种模糊说法。稠密 Transformer 的一层里，真正吃 Tensor Core 的是两类矩阵乘：注意力投影（QKV 与输出投影）和前馈网络（两层 MLP）。对单个 token，每层每类投影的乘加量正比于隐藏维度与权重矩阵规模，把所有层与所有 token 累加，得到的总乘加次数近似正比于 <span class=\"inline-math\">N_vis × d_enc × L_enc × P_enc</span>。这里的 <span class=\"inline-math\">P_enc</span> 已经含 patch embed 与位置编码，因此分子不是“纯 Transformer 块”的账，而是整编码器的账。</p>\n<p>2 倍因子的来源必须说清：一个 MAC（乘加）在 FLOP 计数里记为 2 次浮点运算。工程上这常被误当成“两次矩阵乘”，其实不是——它只是计数约定。分子除以 <span class=\"inline-math\">F_peak × η_comp</span> 后量纲为秒，代表“若算力被完全喂饱，这一批 token 至少要走多久”。<span class=\"inline-math\">η_comp</span> 不是常数，它随 GEMM 的 M/N/K 形状变化：当 <span class=\"inline-math\">N_vis</span> 小到 GEMM 的 M 维只有几十行时，Tensor Core 的 tile 填不满，<span class=\"inline-math\">η_comp</span> 会显著低于大 batch 下的值。这正是后面离散化误差的来源之一。</p>\n<p>具体例子：224×224 输入切成 196 个 patch token，<span class=\"inline-math\">N_vis=196</span>。此时注意力与 MLP 的 GEMM M 维只有 196 行，对 Blackwell 的 tcgen05 MMA 而言，单个 tile 的 K 维循环尚未展开充分，<span class=\"inline-math\">η_comp</span> 的实际可达值远低于峰值；分子算出的“理想秒数”与实测之间会出现系统性缺口。这不是公式错，而是 <span class=\"inline-math\">η_comp</span> 被当成常数用了。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-9\">九 · 第二项的字节账与“权重流式”假设</h3>\n<p>第二项 <span class=\"inline-math\">W_enc B_bytes / (BW_HBM η_mem)</span> 的分子是单次前向必须从 HBM3e 搬入的权重字节量。<span class=\"inline-math\">W_enc</span> 是权重元素数，<span class=\"inline-math\">B_bytes</span> 是每元素字节数，BF16 下取 2。这个乘积的物理含义是：在 batch=1、token 数很少时，激活量小到可以忽略，编码器前向的主要 HBM 流量就是把全部权重从 HBM 读进 SM 一次。分母是峰值带宽乘可达效率 <span class=\"inline-math\">η_mem</span>，得到权重加载下界。</p>\n<p>这里藏着一个强假设：权重与激活可以完全重叠加载，且没有跨 stage 同步。真实 kernel 里，权重加载与 GEMM 计算的重叠程度取决于流水深度与双缓冲策略；当层数多、每层权重块小，流水气泡会在层间累积，<span class=\"inline-math\">η_mem</span> 因此被拉低。公式把 <span class=\"inline-math\">η_mem</span> 写成单一因子，等于把“重叠良好”当成默认成立——这是近似，不是定理。</p>\n<p>推理系统代价的直接体现：在 batch=1、196 token 的场景，第二项往往主导。此时单图时延几乎等于“把整个编码器权重从 HBM3e 读一遍”的时间，算力项反而次要。工程判断因此变得清晰：小分辨率、低并发的视觉编码，瓶颈在带宽而非算力，换更高 <span class=\"inline-math\">F_peak</span> 的 SKU 收益有限，增加 HBM 通道或提高 <span class=\"inline-math\">η_mem</span>（更好的预取与双缓冲）才是正解。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-10\">十 · 取 max 与沿层累加的推导关键步</h3>\n<p>推导的核心不是“两项取大”，而是“逐层取 max 再沿层累加”。对第 <span class=\"inline-math\">l</span> 层，算力需求 <span class=\"inline-math\">t_comp,l</span> 与权重加载需求 <span class=\"inline-math\">t_mem,l</span> 各自给出该层的时间下界；该层的真实下界是 <span class=\"inline-math\">max(t_comp,l, t_mem,l)</span>。把所有层相加，得到整编码器下界。当每层的 max 都取同一分支时，沿层求和就退化为整编码器级的 max——这正是公式写成两项取大的前提。</p>\n<div class=\"formula\">$$T_{\\mathrm{enc}} \\ge \\sum_{l=1}^{L_{\\mathrm{enc}}} \\max\\left(t_{\\mathrm{comp},l},\\; t_{\\mathrm{mem},l}\\right) \\;\\approx\\; \\max\\left(\\sum_l t_{\\mathrm{comp},l},\\; \\sum_l t_{\\mathrm{mem},l}\\right)$$</div>\n<p>近似号那一步是推导的薄弱环节。只有当所有层的瓶颈分支一致时，求和与取 max 才能交换；若前半部分层受带宽约束、后半部分层受算力约束，逐层 max 的和会严格大于整级 max，公式会低估时延。这就是“交点”概念的真正含义：<span class=\"inline-math\">N_vis</span> 增大时，算力项随 token 数线性增长，带宽项基本不随 token 数变（权重字节量固定），两者相交的 token 数阈值就是分支切换点。越过交点后，逐层 max 的求和更接近算力项总和，公式的整级 max 形式才站得住。</p>\n<p>伪代码思路：对每层估算 <span class=\"inline-math\">t_comp,l = 2 N_vis d_l P_l / (F_peak η_comp,l)</span> 与 <span class=\"inline-math\">t_mem,l = W_l B_bytes / (BW_HBM η_mem,l)</span>，逐层取 max 累加，再与整级 max 比较，差值即为“分支不一致”带来的低估量。工程上这个差值就是容量规划的安全余量来源。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-11\">十一 · 离散化与近似落在哪三处</h3>\n<p>第一处是 <span class=\"inline-math\">η_comp</span> 与 <span class=\"inline-math\">η_mem</span> 被当作与形状无关的常数。真实效率随 GEMM 的 M/N/K、tile 尺寸、流水深度变化，尤其在小 token 数下 <span class=\"inline-math\">η_comp</span> 塌陷。第二处是“逐层 max 求和 ≈ 整级 max”的交换近似，只在分支一致时成立。第三处是公式完全不计预处理：resize、normalize、patch embedding 的 layout 变换都不在两项里。</p>\n<p>第三处的代价最容易被低估。高分辨率视频帧流场景下，每帧都要做 resize 与 normalize，patch embedding 还要把像素 layout 重排成 token 序列，这些操作的字节吞吐与 kernel 启动开销可能反超编码器本身。此时 roofline 给出的下界仍然“正确”，但它描述的是一个不存在的理想流水线——真实瓶颈在公式之外。224×224、196 token 的小分辨率场景同理：kernel 启动与固定开销占主导，公式低估实际时延，按它配 batch 会过于激进。</p>\n<p>离散化的另一个体现是 batch 维度。公式对 <span class=\"inline-math\">N_vis</span> 是线性的，但真实系统里 batch 增大后权重只需加载一次、激活量上升，第二项被摊薄，第一项线性上升——交点随 batch 移动。公式没有显式写 batch，读者必须自己把 <span class=\"inline-math\">N_vis</span> 理解为“单次前向的总 token 数”而非“单图 token 数”，否则会误判交点位置。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-12\">十二 · 用界反推 batch 上限与扩容方向</h3>\n<p>容量决策的用法是反解：给定目标分辨率与帧率，令 <span class=\"inline-math\">T_enc</span> 等于帧间隔预算，解出单卡可承载的最大并发图像数。若解出的 batch 落在带宽分支，扩容应优先加 HBM 通道或提升 <span class=\"inline-math\">η_mem</span>；若落在算力分支，才考虑换更高 <span class=\"inline-math\">F_peak</span> 的 SKU。这个判断的价值在于避免“盲目加卡”——加卡若不能同时提升带宽与算力，对瓶颈分支毫无帮助。</p>\n<p>失效条件必须写进决策流程：在 NVL72 多卡切分视觉编码器时直接套用单卡公式，集合通信与流水气泡会破坏该下界，实际吞吐远低于公式推算值。此时应把通信项显式加入，或改用单卡整编码器部署。把 roofline 下界当成实测时延做 SLA 承诺，是另一个系统性高估来源——下界只保证“不可能更快”，不保证“能达到”。</p>\n<p>具体工程判断：当 <span class=\"inline-math\">N_vis</span> 处于交点附近时，两项量级相当，<span class=\"inline-math\">η_comp</span> 与 <span class=\"inline-math\">η_mem</span> 的微小偏差都会翻转分支判断，此时容量规划应留出更大余量，而不是相信公式给出的锐利交点。交点不是一条线，而是一个效率因子主导的模糊带。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-13\">十三 · 公式的适用域与不可外推之处</h3>\n<p>公式成立的前提是稠密 Transformer 视觉编码器、序列长度足以让 GEMM 达到高利用率、权重与激活可完全重叠加载、无跨 stage 同步。四条前提缺一，公式就从“下界”退化为“乐观估计”。小分辨率 196 token 场景破坏第二条；NVL72 切分破坏第三条与第四条；视频帧流预处理破坏的是公式的覆盖范围而非前提本身。</p>\n<p>不可外推之处在于：公式对稀疏编码器、卷积主干、混合架构不成立，因为它们的算力项与权重项结构不同；对量化后的 NVFP4/FP8 权重，<span class=\"inline-math\">B_bytes</span> 需相应下调，但 <span class=\"inline-math\">η_comp</span> 也会因低精度 MMA 的吞吐特性而变化，两项不能独立调整。工程上把公式当作“分支判断器”而非“时延预测器”，才是它最稳的用法：它告诉你瓶颈在哪一侧，而不是告诉你具体多少毫秒。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-14\">十四 · 下界成立的四道门槛：重叠假设、切分代价、预处理与 kernel 启动</h3>\n<p>公式本身只是把两条曲线取 max，真正决定它能否用于容量决策的是四个隐含前提。第一道门槛是权重与激活的完全重叠：第二项 $$\\frac{W_{\\mathrm{enc}} B_{\\mathrm{bytes}}}{\\mathrm{BW}_{\\mathrm{HBM}}\\eta_{\\mathrm{mem}}}$$ 假设整层权重流式加载与上一层的 Tensor Core 计算在时间轴上无缝咬合，即编码器被组织成权重预取深度足够的流水。一旦层间存在跨 stage 同步（例如 patch embed 输出需等待 layout 变换完成才能进入第一个 attention block），重叠被打断，实际时延退化为两项之和而非取 max，公式给出的下界立刻失效。工程上判断重叠是否成立，看的是每层权重字节量与单层计算时间的比值：当 $$W_{\\mathrm{enc}}B_{\\mathrm{bytes}}/\\mathrm{BW}_{\\mathrm{HBM}}$$ 明显小于该层算力项时，带宽项被完全隐藏在计算背后，此时 max 退化为算力项，公式是紧的；反之权重项外露，任何同步都会直接加到关键路径上。</p>\n<p>第二道门槛是多卡切分。在 NVL72 上把视觉编码器按层或按张量切到多张 GPU 时，单卡公式中的 $$F_{\\mathrm{peak}}$$ 与 $$\\mathrm{BW}_{\\mathrm{HBM}}$$ 不再代表整条关键路径，集合通信（all-reduce、all-gather）与流水气泡必须显式进入分母之外的另一项。此时正确的下界应写成 $$T_{\\mathrm{enc}} \\ge \\max(\\text{算力项},\\ \\text{带宽项}) + T_{\\mathrm{comm}}$$，其中 $$T_{\\mathrm{comm}}$$ 随切分度与消息尺寸增长，在层数 $$L_{\\mathrm{enc}}$$ 较大而单层计算量偏小的视觉编码器上尤其显著——每层一次 all-reduce 意味着通信次数与层数成正比，而每层可重叠的计算窗口却被切分稀释。这正是“按公式推算的并发数在现场无法达到”的机制来源：公式低估的不是算力，而是被切分引入的串行段。</p>\n<p>第三道门槛是预处理。公式只覆盖 patch 化之后的编码器主体，而 resize、normalize 与 patch embedding 的 layout 变换发生在 HBM 与 SM 之间的另一条数据通路上，其代价与输入像素数成正比而非与 $$N_{\\mathrm{vis}}$$ 成正比。高分辨率视频帧流场景下，单帧像素量远大于 token 数所暗示的计算量，预处理的反向缩放、归一化与重排可能反超编码器本体成为真瓶颈。判断方法很直接：把预处理字节吞吐与 $$\\mathrm{BW}_{\\mathrm{HBM}}\\eta_{\\mathrm{mem}}$$ 对比，若预处理需要多次读写整帧张量，其带宽占用会挤占编码器的权重加载窗口，两项不再能独立取 max。</p>\n<p>第四道门槛是离散化与固定开销。公式是连续时间下的渐近下界，而实际执行被离散成 kernel 启动、grid 调度与尾部效应。224×224、196 token 的小分辨率输入下，$$N_{\\mathrm{vis}}$$ 很小，算力项分子缩水，编码器每层 GEMM 的 M 维不足以填满 Tensor Core 的 tile，$$\\eta_{\\mathrm{comp}}$$ 急剧下降；同时 kernel 启动与固定开销占据主导，公式系统性低估实际时延。可用的修正思路是把固定开销作为加性项并入：$$T_{\\mathrm{enc}} \\ge \\max(\\cdot,\\cdot) + N_{\\mathrm{kernel}}\\,t_{\\mathrm{launch}}$$，其中 $$N_{\\mathrm{kernel}}$$ 随层数与算子融合程度变化。这解释了为何小分辨率场景下按 roofline 配置的 batch 过于激进而超时——公式没有为每个 kernel 的启动与尾部买单。</p>\n<table class=\"mini\"><thead><tr><th>门槛</th><th>破坏的公式项</th><th>系统代价表现</th></tr></thead><tbody><tr><td>层间同步打断重叠</td><td>max 退化为求和</td><td>时延高于下界，带宽项外露</td></tr><tr><td>NVL72 多卡切分</td><td>需加 $$T_{\\mathrm{comm}}$$</td><td>通信次数随 $$L_{\\mathrm{enc}}$$ 增长，并发高估</td></tr><tr><td>预处理未计入</td><td>额外带宽占用</td><td>视频帧流下预处理反超本体</td></tr><tr><td>小分辨率固定开销</td><td>$$\\eta_{\\mathrm{comp}}$$ 塌陷</td><td>196 token 下时延被低估</td></tr></tbody></table>\n\n<h3 id=\"th-visual-encoder-roofline-sec-15\">十五 · 两项取大的适用边界与失效路径</h3>\n<p>该式是下界而非预测：$$T_{\\mathrm{enc}} \\ge \\max(\\cdot,\\cdot)$$ 的取大结构隐含一个前提——算力项与带宽项可以各自独立地跑满，即权重流式加载与激活计算在时间轴上完全重叠、层间无同步屏障。一旦这个重叠被打破，两项不再是“取大”而是“相加”。在 NVL72 上把视觉编码器按层切到多卡时，每层 GEMM 之后插入的 all-reduce 与流水气泡会把通信时间塞进原本被隐藏的空隙，此时真实时延近似为 $$\\max(\\text{算力项},\\text{带宽项})+\\sum_i T_{\\mathrm{comm},i}$$，公式推算的并发上限随之系统性偏高。工程判断很直接：视觉编码器参数量相对 LLM 主干小，切分收益有限，优先单卡整编码器部署；确需切分时把通信项显式写进容量模型，而不是继续套用单卡下界。</p>\n<p>第二个失效面在离散化。推导把前向拆成逐层 GEMM、对每层取 max 再沿层累加，这一步默认每层的 GEMM 形状都足够大、能让 Tensor Core 进入高利用率区间。224×224 输入只有 196 个视觉 token，单层 GEMM 的 M 维极小，kernel 启动、TMEM 分配与 tile 填充的固定开销占据主导，$$\\eta_{\\mathrm{comp}}$$ 实际远低于大分辨率下的取值，roofline 低估时延。此时正确的做法不是调低 $$\\eta_{\\mathrm{comp}}$$ 硬拟合，而是承认公式在该区间不适用，改用固定开销加线性项的混合模型做 batch 决策。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>被破坏的假设</th><th>系统代价表现</th></tr></thead><tbody><tr><td>196 token 小分辨率</td><td>GEMM 高利用率</td><td>kernel 启动开销主导，时延被低估，batch 配置过激</td></tr><tr><td>NVL72 多卡切分</td><td>无跨 stage 同步</td><td>集合通信与气泡，并发上限高估</td></tr><tr><td>高分辨率视频帧流</td><td>预处理可忽略</td><td>resize/normalize/layout 变换反超编码器</td></tr></tbody></table>\n<p>第三项代价来自公式之外：$$W_{\\mathrm{enc}} B_{\\mathrm{bytes}}$$ 只计权重搬运，未计图像预处理。视频帧流场景下 resize、normalize 与 patch embedding 的 layout 变换在 GPU 上串行执行，其耗时随帧率线性增长而不随 batch 摊薄，当分辨率抬高后这部分可能超过编码器本体，成为真正的 SLA 瓶颈。按 roofline 规划 batch 的团队在现场超时，多半是把下界当成了端到端时延。</p>\n<h3 id=\"th-visual-encoder-roofline-sec-16\">十六 · 算力项成立的前提：GEMM 必须真的跑满</h3>\n<p>公式第一项把每 token 每层的乘加量折算成 FLOP，再除以峰值算力与效率因子。这一步隐含了一个非常强的假设：视觉编码器里的每个 GEMM 都能把 Tensor Core 喂到接近饱和。对稠密 Transformer 的 qkv 投影、MLP 上投影这类形状规整的大矩阵，这个假设在 Blackwell 的 tcgen05 路径上基本站得住；但对 patch embedding 的卷积式投影、窗口注意力的局部重排、以及层数很浅的小型编码器，GEMM 的 M 维（token 数）会被切得很碎，MMA 指令的发射间隔里塞不满 operand，效率因子 η_comp 会从接近峰值掉到很低的水平。此时第一项不再是一个可达下界，而是一个乐观估计。</p>\n<p>判定标准可以写成一条形状约束：设单次 MMA 的有效 M 为 m，则要求 <span>N_vis</span> 至少是 m 的若干倍，且 d_enc 与中间维度都能被 tile 尺寸整除，否则尾部 tile 的浪费会直接乘进 η_comp。工程上更实用的做法是先用一个小规模 profile 反推 η_comp：固定 d_enc、L_enc，扫 N_vis 从 196 到数千，画出实测时延曲线，看它是否落在 max 两项构成的折线附近。若实测曲线在小 token 段明显高于折线，说明该编码器不满足“序列长度足以让 GEMM 达到高利用率”的前提，公式只能当趋势参考。</p>\n<p>代价落在延迟与吞吐两侧：小分辨率下 kernel 启动、grid 调度、TMEM 分配与 epilogue 写回的固定开销占主导，单图时延被这些常数项抬高，而 batch 增大时固定开销被摊薄，吞吐反而先升后平。一个具体例子是 224×224 输入、196 个视觉 token 的编码器：此时算力项数值很小，公式给出的下界远低于实测，按它去承诺 SLA 必然违约。反过来，若把分辨率提到每图数千 token，算力项随 N_vis 线性增长并反超带宽项，公式才重新变得可信。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-17\">十七 · 带宽项的三个隐含假设</h3>\n<p>第二项把权重字节量除以 HBM3e 带宽，前提是权重只被搬一次、且搬运与计算完全重叠。真实执行里这条链路有三处会漏。第一，权重在层间是流式加载的，若没有做双缓冲或跨层预取，每层结束时的同步会把带宽项从“流水”退化成“串行”，等效带宽被气泡吃掉。第二，激活、KV 中间结果、以及 attention 的 score 矩阵同样占用 HBM 带宽，公式只计了权重，当 N_vis 增大到激活量可比权重时，带宽项被低估。第三，η_mem 不是常数：HBM3e 的峰值带宽在长突发、连续地址访问下才接近标称值，权重按 tile 分块加载若地址跳变频繁，实际可达带宽会下降。</p>\n<div class=\"formula\">$$T_{\\text{mem,real}} \\ge \\frac{(W_{\\text{enc}} + A_{\\text{act}}(N_{\\text{vis}}))\\,B_{\\text{bytes}}}{\\mathrm{BW}_{\\text{HBM}}\\,\\eta_{\\text{mem}}}$$</div>\n<p>这条修正式的意义在于给出带宽项失效的判据：当 A_act 与 W_enc 同量级时，原公式的第二项不再能代表真实下界。工程判断是——在 batch=1、单图推理的部署里，权重项主导，公式够用；在连续批处理把多张图拼进同一前向时，激活与中间张量的带宽占比上升，必须把激活字节显式计入，否则容量规划会系统性高估并发数。显存侧还有一层：权重常驻显存意味着 W_enc·B_bytes 是硬占用，它与 KV cache、多模态缓存争抢同一池 HBM，公式本身不体现这种挤占，但在 NVL72 整机部署时它是决定单卡能放几个编码器副本的关键约束。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-18\">十八 · 跨 stage 同步与多卡切分：下界被通信项击穿</h3>\n<p>公式默认编码器是一个无跨 stage 同步的整体。一旦把视觉编码器按层切到多张 GPU 上，流水线气泡与集合通信就会插入关键路径，max 两项构成的折线不再是下界。设切分为 S 段，每段之间有一次 all-gather 或点对点激活传输，则实际时延至少是各段计算下界之和加上 (S−1) 次通信时延，而流水填充与排空又额外贡献气泡。NVL72 内的 NVLink 5 带宽虽高，但小消息的固定延迟与 kernel 级同步开销并不会因为链路快而消失，尤其在视觉编码器层数不多、每段计算量很小时，通信项可以直接压过计算项。</p>\n<p>判断是否该切分，可以用一个粗略的比较：单卡整编码器的下界为 T_single，切分后的估计为 T_single/S + T_comm·(S−1) + T_bubble。当 T_comm 与 T_bubble 之和接近 T_single/S 时，切分带来的收益被抵消。工程结论很直接——视觉编码器通常比语言主干小得多，优先单卡整放；只有在单卡显存放不下、或编码器本身极大时才考虑切分，且必须把通信项写进容量模型，而不是套用单卡公式再除以卡数。这条边界也是多卡部署时“按公式推算的并发数在现场达不到”的根因。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-19\">十九 · 预处理：公式之外的真正瓶颈</h3>\n<p>公式从 patch embedding 的输入开始算，完全不计 resize、normalize、颜色空间转换与 layout 变换（NHWC 到 NCHW、或到 tensor core 友好的分块布局）。这些操作在 CPU 或独立的 copy engine 上执行，单帧开销看似小，但在高分辨率视频帧流场景里，每帧的像素量随分辨率平方增长，预处理时间可以线性堆叠到超过编码器本身。此时 roofline 给出的编码器下界依然“正确”，但它描述的不是端到端时延，按它做 batch 规划会在现场严重超时。</p>\n<p>量化判据是：设单帧预处理时间为 T_pre，编码器下界为 T_enc，则端到端下界应为 T_pre + T_enc，且当 T_pre 与 T_enc 同量级时，优化重心应从编码器算子转向预处理流水线（GPU 侧 resize、融合 normalize、零拷贝 layout 变换、预处理与编码器 overlap）。显存与带宽代价也在这里体现：预处理若在 GPU 上做，会额外占用 HBM 读写带宽，与权重加载争抢；若留在 CPU，则受 PCIe 与主机内存带宽约束，成为另一条独立的 roofline。视频帧流场景的工程判断是先把预处理搬到与编码器同一张卡的 copy engine 或轻量 kernel 上做 overlap，再谈编码器本身的算力/带宽平衡。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-20\">二十 · 规模上限：公式在哪个区间失效</h3>\n<p>把两条曲线画在一起，公式的可信区间其实是一个中间带。左端是小 token 区（如 196 token），固定开销主导，公式低估时延；右端是大 token 区，激活与 attention 的二次项开始显形，公式只计了线性于 N_vis 的投影算力，漏掉 attention 里随 N_vis² 增长的 score 计算与 softmax，算力项被低估，同时激活带宽占比上升使带宽项也失真。中间带内，投影 GEMM 占主导、激活量相对权重可忽略，公式才是紧的下界。</p>\n<table class=\"mini\"><thead><tr><th>区间</th><th>主导因素</th><th>公式状态</th></tr></thead><tbody><tr><td>小分辨率（196 token）</td><td>kernel 启动、固定开销</td><td>低估时延，不可用于 SLA</td></tr><tr><td>中等分辨率、单卡整放</td><td>权重带宽 ↔ 投影算力</td><td>紧下界，可用于容量反推</td></tr><tr><td>高分辨率/视频帧流</td><td>attention 二次项、激活带宽、预处理</td><td>算力与带宽两项均偏低</td></tr><tr><td>多卡切分</td><td>集合通信、流水气泡</td><td>不再是下界</td></tr></tbody></table>\n<p>规模上限还有一条显存约束：给定目标分辨率与帧率，公式可反推单卡最大并发图像数，但这个反推只在权重与激活能同时驻留、且不与 KV cache 争抢的前提下成立。当并发数推高到激活池逼近显存容量时，分配器开始复用、同步增多，实际吞吐偏离线性，公式的 batch 上限失去意义。此时的工程动作不是继续加卡，而是先判断瓶颈在算力 SKU 还是 HBM 通道：若实测落在带宽项一侧，换更高 F 的 SKU 无益，应增加 HBM 通道或减少权重常驻副本；若落在算力项一侧，才考虑升 SKU。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-21\">二十一 · 把边界写进容量模型</h3>\n<p>可操作的写法是给公式加三个守卫条件，任一不满足就降级使用：其一，N_vis 需超过由 tile 尺寸与层数决定的阈值，否则标记为“固定开销区”；其二，A_act(N_vis) 需小于 W_enc 的某个比例，否则带宽项改用修正式；其三，部署拓扑为单卡整编码器且预处理已 overlap，否则在时延模型里显式加入 T_comm 与 T_pre。守卫条件不改变公式形式，只决定它在给定配置下是否可作为承诺依据。</p>\n<p>最终落到一个工程判断上：roofline 界的价值不在于给出一个可承诺的数字，而在于指出当前配置下哪一项在主导——是权重加载、是投影算力、是预处理、还是通信。主导项一旦识别，扩容与优化的方向就唯一确定；把界当实测值去签 SLA，等于把“哪一项主导”这个信息丢掉，剩下的只是一个在边界外必然失准的常数。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-22\">二十二 · 适用边界：假设、失效条件、规模上限；什么情况下公式不再成立</h3>\n<p>该下界成立的前提是视觉编码器为稠密 Transformer，且序列长度足以让逐层 GEMM 达到高利用率。此时把前向拆成逐层算力需求与权重流式加载需求、逐层取 max 再沿层累加，才等价于整体取 max。一旦序列短到 GEMM 的 K 维与 M 维都不足以填满 Tensor Core 的 tile，效率因子 η_comp 不再是常数而是 token 数的函数，公式第一项被系统性低估。224×224、196 token 是典型反例：此时 kernel 启动、固定开销与尾部效应占主导，roofline 给出的时间明显低于实测，按它配 batch 会过于激进。判断阈值不在公式里，而在实测的 GEMM 利用率曲线上——当单层 GEMM 的有效算力利用率随 N_vis 明显上升时，公式才进入可信区间。</p>\n<p>第二个失效条件是重叠假设。公式默认权重加载与激活计算可完全重叠、且无跨 stage 同步，这在单卡整编码器部署时接近成立；一旦在 NVL72 上把视觉编码器按层切分到多卡，集合通信与流水气泡就会破坏该下界。此时应把通信项显式写入：</p>\n<div class=\"formula\">$$T_{\\mathrm{enc}} \\ge \\max\\left(\\frac{2N_{\\mathrm{vis}}d_{\\mathrm{enc}}L_{\\mathrm{enc}}P_{\\mathrm{enc}}}{F_{\\mathrm{peak}}\\eta_{\\mathrm{comp}}},\\;\\frac{W_{\\mathrm{enc}}B_{\\mathrm{bytes}}}{\\mathrm{BW}_{\\mathrm{HBM}}\\eta_{\\mathrm{mem}}}\\right) + \\frac{L_{\\mathrm{enc}}}{S}\\,t_{\\mathrm{comm}}$$</div>\n<p>其中 S 为切分段数，t_comm 为每段边界的集合通信代价。工程判断很直接：视觉编码器参数量相对 LLM 主干小，切分收益有限而气泡代价确定，优先单卡整编码器部署；确需切分时按上式重算并发上限，否则容量规划会系统性高估。</p>\n<p>第三个边界是预处理未计入。resize、normalize 与 patch embedding 的 layout 变换发生在编码器之外，公式对此完全沉默。低分辨率单图时它们占比可观；高分辨率视频帧流场景下，预处理的数据搬运量与格式转换可能反超编码器本身成为真瓶颈，按 roofline 规划的 batch 在现场严重超时。规模上限因此不是由 F_peak 或 BW_HBM 单独决定，而是由三者中当前最紧的一环决定：小 token 数看固定开销，中等规模看带宽与算力交点，多卡切分看通信，视频流看预处理。用该界做容量决策时，先确认所处区间，再决定扩容是换更高 F 的 SKU、增加 HBM 通道，还是把预处理搬到独立流水线——把下界当实测时延去承诺 SLA，是这条公式最常见的误用。</p>\n<h3 id=\"th-visual-encoder-roofline-sec-23\">二十三 · 从下界到批上限：把 T_enc 反解成 N_max</h3>\n<p>容量决策的第一步不是算时延，而是把 roofline 下界当成约束不等式反解。给定 SLO 的单图时延预算 <span class=\"inline-math\">T_slo</span>（已扣除预处理与后处理余量），令 <span class=\"inline-math\">T_enc ≤ T_slo</span>，则算力分支给出视觉 token 数的上限：</p>\n<div class=\"formula\">$$N_{\\mathrm{vis}}^{\\max}=\\frac{T_{\\mathrm{slo}}\\,F_{\\mathrm{peak}}\\,\\eta_{\\mathrm{comp}}}{2\\,d_{\\mathrm{enc}}\\,L_{\\mathrm{enc}}\\,P_{\\mathrm{enc}}}$$</div>\n<p>注意分子里没有 batch。这是关键：roofline 的算力项对单图 token 数线性，但对 batch 并不线性——同一 batch 内 B 张图共享一次权重加载，算力项随 B 线性增长而带宽项不随 B 增长。因此正确的批上限推导要写成两条分支分别约束 B：</p>\n<div class=\"formula\">$$B\\le\\frac{T_{\\mathrm{slo}}\\,F_{\\mathrm{peak}}\\,\\eta_{\\mathrm{comp}}}{2\\,N_{\\mathrm{vis}}\\,d_{\\mathrm{enc}}\\,L_{\\mathrm{enc}}\\,P_{\\mathrm{enc}}}\\quad\\text{（算力约束）},\\qquad B\\le\\frac{T_{\\mathrm{slo}}\\,\\mathrm{BW}_{\\mathrm{HBM}}\\,\\eta_{\\mathrm{mem}}}{W_{\\mathrm{enc}}\\,B_{\\mathrm{bytes}}}\\quad\\text{（带宽约束）}$$</div>\n<p>取两者较小值即为单卡可承载的并发图像数。工程含义很直接：当 <span class=\"inline-math\">N_vis</span> 小（低分辨率、少 token），带宽约束那一项更紧，加 batch 几乎免费，因为每多一张图只多算力、不多权重流量；当 <span class=\"inline-math\">N_vis</span> 大（高分辨率、视频帧），算力约束反超，加 batch 线性吃时延，此时扩容只能靠加算力 SKU 或降 token 数。这条分界正是交点阈值，用它判断“该换卡还是该加卡”比拍脑袋可靠。</p>\n<p>代价侧要盯住一个陷阱：上述 B 是编码器阶段的批上限，不是端到端并发。VLM 的 KV cache 与解码阶段另有预算（见多模态 KV cache 显存式条目），编码器批上限只决定预填侧的吞吐天花板。若把编码器 B 直接当作系统并发去配置调度器，会在解码侧撞墙。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-24\">二十四 · 定并行度：切分前先算通信项是否吃掉收益</h3>\n<p>当单卡 B 上限低于目标 QPS 需求时，直觉是切分视觉编码器到多卡。但 roofline 的单卡形式在切分后失效：层内张量并行引入每层两次 all-reduce，流水并行引入气泡，二者都不在公式里。判断是否值得切的粗略准则是比较“切分后算力项缩短量”与“新增通信项”：</p>\n<div class=\"formula\">$$\\Delta T_{\\mathrm{comm}}\\approx\\frac{2\\,(P-1)}{P}\\cdot\\frac{S_{\\mathrm{act}}\\,B_{\\mathrm{bytes}}}{\\mathrm{BW}_{\\mathrm{NVLink}}\\,\\eta_{\\mathrm{link}}}$$</div>\n<p>其中 P 为切分度，<span class=\"inline-math\">S_act</span> 为单层激活元素数。只有当算力项从 <span class=\"inline-math\">T_comp</span> 降到 <span class=\"inline-math\">T_comp/P</span> 的收益大于 <span class=\"inline-math\">ΔT_comm</span> 时，切分才划算。对视觉编码器这种层数有限（相对 LLM 主干浅）、单层 GEMM 规模中等的结构，P=2 往往已是收益拐点；P 再大，all-reduce 与流水气泡把收益吃光。NVL72 内 NVLink 5 带宽充裕，但集合通信下界仍是硬约束（见 NVL72 通信下界条目），不能假设链路免费。</p>\n<p>更稳的工程判断是：优先单卡整编码器部署，把并行度留给解码侧或跨请求批处理。视觉编码器切分只在“单图 token 数极大、单卡算力项已成绝对瓶颈、且 B 已压到 1”三个条件同时成立时才考虑。否则切分带来的通信与气泡会让实际吞吐低于按单卡公式推算的 B×QPS，造成容量规划系统性高估——这是 roofline 在多卡场景最典型的失效路径。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-25\">二十五 · 定 KV 预算：编码器输出如何折算成显存占用</h3>\n<p>视觉编码器本身不产生自回归 KV，但它把图像压成 <span class=\"inline-math\">N_vis</span> 个视觉 token 注入解码器，这些 token 在预填阶段一次性写入 KV cache，并在整个解码过程中常驻。因此编码器的分辨率决策直接决定 KV 预算：</p>\n<div class=\"formula\">$$M_{\\mathrm{kv}}^{\\mathrm{vis}}=N_{\\mathrm{vis}}\\cdot L_{\\mathrm{dec}}\\cdot 2\\cdot d_{\\mathrm{kv}}\\cdot B_{\\mathrm{kv}}$$</div>\n<p>其中 <span class=\"inline-math\">L_dec</span> 为解码器层数，因子 2 为 K/V 两份，<span class=\"inline-math\">d_kv</span> 为 KV 头维度乘头数，<span class=\"inline-math\">B_kv</span> 为每元素字节（FP8 为 1，BF16 为 2）。这个式子说明：视觉 token 的 KV 成本与文本 token 同价，一张高分辨率图的 <span class=\"inline-math\">N_vis</span> 可能相当于数千文本 token 的常驻显存。容量规划时必须把 <span class=\"inline-math\">M_kv^vis</span> 从总显存中先扣除，剩余才给解码 KV 与权重。</p>\n<p>决策联动在这里：roofline 鼓励提高分辨率以换取质量，但每提高一档分辨率，<span class=\"inline-math\">N_vis</span> 上升，编码器算力项上升（压低 B 上限），同时 KV 预算上升（压低并发）。两个方向同向恶化，所以分辨率不是免费的旋钮。工程上应把“目标分辨率 → N_vis → 编码器 B 上限 → KV 占用 → 系统并发”串成一条链来算，而不是分别优化。若 KV 预算先耗尽，说明瓶颈已从编码器转移到解码侧显存，此时提升编码器算力 SKU 毫无收益。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-26\">二十六 · 定 SLO：下界与实测之间的安全裕度</h3>\n<p>roofline 是下界，SLO 承诺必须建立在实测之上。公式漏掉的三块开销在小分辨率下占主导：kernel 启动与固定开销、图像预处理（resize、normalize、patch embedding 的 layout 变换）、以及跨 stage 同步。224×224、196 token 的场景正是失效区——此时 GEMM 利用率低，公式会显著低估实际时延。因此 SLO 规划应写成：</p>\n<div class=\"formula\">$$T_{\\mathrm{slo}}\\ge T_{\\mathrm{enc}}^{\\mathrm{roofline}}\\cdot(1+\\alpha)+T_{\\mathrm{pre}}+T_{\\mathrm{post}}$$</div>\n<p><span class=\"inline-math\">α</span> 是实测与下界的偏离系数，需按分辨率档位分别标定，不能全场景共用一个值。视频帧流场景尤其危险：预处理可能反超编码器成为真瓶颈，按 roofline 规划的 batch 在现场严重超时。判断方法是分别测预处理与编码器耗时，若预处理占比超过编码器，则 roofline 已不是主导约束，扩容方向应转向预处理流水线（GPU 侧 resize、批量 layout 变换）而非编码器算力。</p>\n<p>另一个 SLO 维度是尾延迟。批上限 B 是按平均时延推的，但同一 batch 内不同图像 token 数可能不等（变分辨率输入），最慢那张决定整批完成时间。工程上要么按最大 <span class=\"inline-math\">N_vis</span> 定 B，要么做 token 数分桶批处理，把长图与短图分开成批，避免短图被长图拖尾。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-27\">二十七 · 算例：一条从分辨率到并发数的完整链路</h3>\n<p>设目标为 BF16 稠密视觉编码器，<span class=\"inline-math\">d_enc</span>、<span class=\"inline-math\">L_enc</span>、<span class=\"inline-math\">P_enc</span> 给定，单卡 Blackwell SM 的 <span class=\"inline-math\">F_peak</span> 与 <span class=\"inline-math\">BW_HBM</span> 取 HBM3e 规格，效率因子 <span class=\"inline-math\">η_comp</span>、<span class=\"inline-math\">η_mem</span> 按实测标定。取两档分辨率：224×224（196 token）与更高分辨率档（token 数显著增大）。</p>\n<ul>\n<li>低分辨率档：<span class=\"inline-math\">N_vis=196</span>，算力项分子小，带宽项 <span class=\"inline-math\">W_enc·2/BW_HBM·η_mem</span> 主导。此时 B 上限由带宽约束给出，加 batch 几乎不增时延，单卡可承载较大并发。但注意此档正落在 roofline 失效区，公式低估实际时延，实际 B 需按实测下调。</li>\n<li>高分辨率档：<span class=\"inline-math\">N_vis</span> 增大数倍，算力项反超带宽项成为主导。B 上限由算力约束给出，随 <span class=\"inline-math\">N_vis</span> 反比下降。此时扩容应优先换更高 <span class=\"inline-math\">F_peak</span> 的 SKU，而非加 HBM 通道。</li>\n<li>KV 折算：高分辨率档的 <span class=\"inline-math\">N_vis</span> 乘以解码器层数与 KV 维度，得到每图常驻显存；若该值已接近单卡显存的可分配余量，则系统并发被 KV 而非编码器算力卡住，编码器扩容无意义。</li>\n<li>SLO 校验：把两档的 <span class=\"inline-math\">T_enc^roofline</span> 加上预处理与偏离系数，与目标时延预算比对；若低分辨率档实测超预算而高分辨率档反而接近预算，说明预处理在小图场景占比过高，应优化预处理而非编码器。</li>\n</ul>\n<p>这条链路的价值在于把四个决策（批大小、并行度、KV 预算、SLO）统一到同一组变量上：分辨率改 <span class=\"inline-math\">N_vis</span>，<span class=\"inline-math\">N_vis</span> 同时进入算力项、B 上限与 KV 占用，三者联动。任何单点优化若不同时检查另外两条分支，都会在另一侧撞墙。最终落在工程判断上：先测预处理与编码器的实际占比，确认 roofline 是否仍是主导约束；若是，按交点阈值决定加算力还是加带宽；若不是，把预算投到预处理流水线与 token 压缩上，而不是继续按公式加卡。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-28\">二十八 · 把下界变成容量决策：批大小、并行度与 SLO 的换算</h3>\n<p>在容量规划里，这个界不是用来预测时延的，而是用来做“反向求解”的。给定目标分辨率与帧率，把 <span class=\"sym\">N<sub>vis</sub></span> 与 <span class=\"sym\">W<sub>enc</sub></span> 固定，令单卡可承载并发图像数为 <span class=\"sym\">b</span>，则单次前向的权重加载项与 batch 无关（权重只搬一次），而算力项随 <span class=\"sym\">b</span> 线性增长，于是有 <span class=\"formula\">$$b_{\\max}\\approx\\frac{F_{\\mathrm{peak}}\\eta_{\\mathrm{comp}}}{2N_{\\mathrm{vis}}d_{\\mathrm{enc}}L_{\\mathrm{enc}}}\\cdot\\frac{T_{\\mathrm{SLO}}}{1}-\\frac{W_{\\mathrm{enc}}B_{\\mathrm{bytes}}}{\\mathrm{BW}_{\\mathrm{HBM}}\\eta_{\\mathrm{mem}}}\\cdot\\frac{1}{T_{\\mathrm{SLO}}}\\cdot\\frac{F_{\\mathrm{peak}}\\eta_{\\mathrm{comp}}}{2N_{\\mathrm{vis}}d_{\\mathrm{enc}}L_{\\mathrm{enc}}}$$</span> 的平衡关系——工程上更实用的做法是直接解交点：令两项相等，得到算力/带宽切换的 token 阈值 <span class=\"sym\">N<sup>*</sup></span>，当实际 <span class=\"sym\">N<sub>vis</sub></span> 低于它时扩容应优先加带宽（更多 HBM 通道或更高带宽 SKU），高于它时优先换更高 <span class=\"sym\">F<sub>peak</sub></span> 的 SKU。这一步决定了采购方向，比盲目加卡省得多。</p>\n<p>并行度决策要更谨慎。NVL72 上把视觉编码器按层切到多卡，公式里的两项都不再成立：权重加载项被集合通信的 all-gather 取代，算力项被流水气泡稀释，实际下界应写成 <span class=\"formula\">$$T_{\\mathrm{enc}}^{\\mathrm{multi}}\\ge \\max\\left(\\frac{2N_{\\mathrm{vis}}d_{\\mathrm{enc}}L_{\\mathrm{enc}}P_{\\mathrm{enc}}}{kF_{\\mathrm{peak}}\\eta_{\\mathrm{comp}}},\\;\\frac{W_{\\mathrm{enc}}B_{\\mathrm{bytes}}}{\\mathrm{BW}_{\\mathrm{HBM}}\\eta_{\\mathrm{mem}}}\\right)+T_{\\mathrm{comm}}(k)$$</span> 其中 <span class=\"sym\">k</span> 为切分卡数，<span class=\"sym\">T<sub>comm</sub></span> 含每层边界的一次集合通信与流水填充/排空。当 <span class=\"sym\">k</span> 增大时第一项线性下降、第二项不变、第三项上升，存在一个最优 <span class=\"sym\">k</span>；对单图小分辨率场景，<span class=\"sym\">T<sub>comm</sub></span> 往往直接吃掉全部收益，结论是单卡整编码器部署反而更稳。这也是为什么在 196 token 这类输入上，多卡切分视觉编码器几乎从不划算。</p>\n<p>KV 预算与 SLO 的耦合点在于：视觉编码器本身不产生 KV，但它决定了每张图进入解码器前的 token 注入量，从而间接决定解码阶段的 KV 占用与首 token 时延。容量规划时应把 <span class=\"sym\">T<sub>enc</sub></span> 作为 TTFT 的固定分量计入，再叠加预填充与首解码步；若按 roofline 下界承诺 SLO，必须显式留出预处理余量。高分辨率视频帧流场景里，resize、normalize 与 patch embedding 的 layout 变换会反超编码器本身，此时真正的瓶颈不在公式覆盖范围内，按公式配出的 batch 在现场会系统性超时。</p>\n<table class=\"mini\"><thead><tr><th>决策项</th><th>依据的量</th><th>失效条件</th></tr></thead><tbody><tr><td>batch 上限</td><td>交点阈值 N*</td><td>小分辨率下固定开销主导</td></tr><tr><td>扩容方向</td><td>算力项 vs 带宽项</td><td>预处理成为真瓶颈</td></tr><tr><td>切分卡数 k</td><td>T_comm(k) 与两项的权衡</td><td>跨 stage 同步破坏下界</td></tr><tr><td>TTFT 承诺</td><td>T_enc 作为固定分量</td><td>把下界当实测时延</td></tr></tbody></table>\n<p>算例：设某稠密 ViT 编码器在 224×224 输入下 <span class=\"sym\">N<sub>vis</sub></span>=196，权重以 BF16 存放（<span class=\"sym\">B<sub>bytes</sub></span>=2），单卡部署。此时权重加载项与 batch 无关，而算力项在 <span class=\"sym\">b</span>=1 时远小于权重项，说明该配置下编码器完全受 HBM 带宽约束——增加 batch 几乎不增加时延，因此 batch 上限由显存与解码侧 KV 共同决定，而非编码器算力。反之把分辨率推高到 <span class=\"sym\">N<sub>vis</sub></span> 越过 <span class=\"sym\">N<sup>*</sup></span> 后，算力项反超，此时增大 batch 会线性拉长 <span class=\"sym\">T<sub>enc</sub></span>，SLO 约束开始咬住 batch 上限，扩容应转向更高 <span class=\"sym\">F<sub>peak</sub></span> 的 SKU 而非加卡。这个切换点的工程意义在于：它把“加卡还是换 SKU”从经验判断变成了可计算的阈值判断，前提是输入分辨率与帧率稳定、预处理开销已被单独测量并扣除。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-29\">二十九 · 把下界当预算：批上限、并行度与 SLO 的换算口径</h3>\n<p>这一节只谈一件事：<strong>这个 roofline 下界能拿来做什么决策，以及在哪些条件下它给出的数字会系统性偏乐观</strong>。工程上它的正确用法不是\"预测时延\"，而是\"给出时延的不可逾越下沿\"，再用实测的固定开销去补差值。给定目标分辨率与帧率，先算单图下界 $T_{\\mathrm{enc}}^{\\min}$，再乘一个由实测标定的开销系数 $k_{\\mathrm{ovh}}$（kernel 启动、预处理、layout 变换），得到可承诺的单图时延预算 $T_{\\mathrm{budget}}=k_{\\mathrm{ovh}}\\cdot T_{\\mathrm{enc}}^{\\min}$；批上限则由 $B_{\\max}=\\lfloor T_{\\mathrm{SLO}}/T_{\\mathrm{budget}}\\rfloor$ 反推。这个式子把 SLO 直接翻译成并发数，是容量规划里唯一能先于实测给出的定量口径。</p>\n<div class=\"formula\">$$B_{\\max}=\\left\\lfloor \\frac{T_{\\mathrm{SLO}}}{k_{\\mathrm{ovh}}\\cdot\\max\\left(\\dfrac{2N_{\\mathrm{vis}}d_{\\mathrm{enc}}L_{\\mathrm{enc}}P_{\\mathrm{enc}}}{F_{\\mathrm{peak}}\\eta_{\\mathrm{comp}}},\\ \\dfrac{W_{\\mathrm{enc}}B_{\\mathrm{bytes}}}{\\mathrm{BW}_{\\mathrm{HBM}}\\eta_{\\mathrm{mem}}}\\right)}\\right\\rfloor$$</div>\n<p>算例：224×224、196 token 的稠密视觉编码器，此时 $N_{\\mathrm{vis}}$ 很小，带宽项主导——单次前向必须把全部 $W_{\\mathrm{enc}}$ 权重从 HBM3e 搬入，$B_{\\max}$ 几乎与分辨率无关，只随权重字节数线性下降。这给出一个反直觉但可靠的判断：<strong>小分辨率场景下扩容应优先加 HBM 通道或换更高带宽 SKU，而不是换更高 F 的算力 SKU</strong>，因为交点尚未到来。反过来，高分辨率长 token 序列让算力项反超后，同样的 $B_{\\max}$ 公式对 $F_{\\mathrm{peak}}$ 敏感，此时换 SKU 才有意义。用一张小表把决策口径固定下来：</p>\n<table class=\"mini\"><thead><tr><th>主导分支</th><th>扩容优先级</th><th>并行度选择</th><th>KV 预算含义</th></tr></thead><tbody><tr><td>带宽项（小 token）</td><td>HBM 带宽 / 通道数</td><td>单卡整编码器，避免切分</td><td>视觉 KV 占比低，预算留给语言侧</td></tr><tr><td>算力项（大 token）</td><td>Tensor Core 峰值 F</td><td>可考虑 2-SM MMA 与切分</td><td>视觉 token 膨胀，需单独预留</td></tr></tbody></table>\n<p>失效条件必须写进规划文档，否则公式会变成 SLA 陷阱。第一，<strong>224×224、196 token 下 kernel 启动与固定开销占主导</strong>，roofline 低估实际时延，按它定的 $B_{\\max}$ 会过于激进而在现场超时；此时 $k_{\\mathrm{ovh}}$ 必须由实测标定，不能取 1。第二，公式假设权重与激活可完全重叠加载、无跨 stage 同步；<strong>在 NVL72 上把视觉编码器切到多卡时，集合通信与流水气泡直接破坏该下界</strong>，实际吞吐远低于按公式推算的并发数，容量规划会系统性高估。要么把通信项显式加进分母，要么退回单卡整编码器部署。第三，公式未计入 resize、normalize 与 patch embedding 的 layout 变换；<strong>高分辨率视频帧流场景中预处理可能反超编码器成为真瓶颈</strong>，此时 roofline 描述的根本不是端到端时延，按它规划的 batch 在现场必然超时。工程判断落在这一点上：把这个界当作\"下限 + 标定系数\"的双段口径使用，并在每次分辨率或部署拓扑变化时重新标定 $k_{\\mathrm{ovh}}$，而不是把公式输出直接写进 SLO。</p>\n<h3 id=\"th-visual-encoder-roofline-sec-30\">三十 · 误用一：把下界当承诺——SLA 与预处理黑洞</h3>\n<p>roofline 界的不等号方向是这套书里最容易被忽略的符号。公式给出的是 <em>下界</em>：<span class=\"formula-inline\">T<sub>enc</sub> ≥ max(算力项, 带宽项)</span>，它描述的是硬件在理想重叠、无同步、无固定开销时所能达到的最快时间。工程上把它当成实测时延去签 SLA，是把\"物理极限\"读成了\"性能预测\"，两者之间隔着预处理、kernel 启动、layout 变换三道沟。</p>\n<p>具体机制上，视觉编码器的真实前向链路是：图像解码 → resize → normalize → patch embedding（含 layout 变换，如 NHWC→NCHW 或展平为 token 序列）→ Transformer 层堆叠。roofline 公式只覆盖最后一段。前三段在 GPU 上由独立 kernel 完成，每个 kernel 都有启动延迟与固定开销，且 resize/normalize 是纯访存操作，其带宽需求与编码器权重加载争抢同一条 HBM3e 通路。识别方法是做一次分段计时：把 patch embedding 之前的耗时单独打点，若其占比超过编码器主体，则 roofline 已失效。</p>\n<p>代价是直接的：按公式推算的 batch 上限在视频帧流场景下无法兑现，现场表现为排队时延随帧率线性上升而吞吐不增。反例见本节末。工程判断：只有当预处理耗时被实测证明小于编码器主体的一个可忽略比例时，才允许用 roofline 做容量承诺；否则必须把预处理纳入时延模型，或把预处理下沉到独立的 CPU/解码卡流水线。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-31\">三十一 · 误用二：小分辨率场景套大公式——固定开销主导区</h3>\n<p>公式的推导前提是\"逐层 GEMM 达到高利用率\"。在 224×224、196 token 的输入下，这个前提不成立：单层 GEMM 的 M 维（token 数）只有 196，N 维为隐藏维度，K 维为隐藏维度，矩阵规模小到 kernel 启动延迟与尾效应（wave quantization）占主导。此时实测时延由固定开销决定，roofline 的两个分支都远低于真实值，公式系统性低估。</p>\n<p>识别信号很明确：把 batch 从 1 提到 2、4、8，若单图时延几乎不随 batch 增长而下降（即吞吐不随 batch 线性上升），说明系统处在固定开销区而非 roofline 描述的算力/带宽区。另一个信号是实测时延对分辨率不敏感——196 token 与更大 token 数的时延差异小于按公式推算的比例，同样指向开销主导。</p>\n<p>后果是 batch 配置过于激进：规划者以为还有大量算力余量，把并发数拉到公式给出的上限，实际每个请求都在等 kernel 启动与同步，尾时延（P99）被拉长，SLO 在低负载下反而更容易被击穿。工程判断：在小分辨率场景，容量决策应以实测的 batch-吞吐曲线为准，roofline 只用来判断\"是否已经远离算力受限\"，不能用来定 batch 上限。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-32\">三十二 · 误用三：NVL72 多卡切分直接套单卡公式——通信项缺失</h3>\n<p>公式假设权重与激活可完全重叠加载且无跨 stage 同步，这是单卡整编码器部署的假设。在 GB200/GB300 NVL72 上把视觉编码器按层切分到多张 GPU 时，每层边界都要插入集合通信（all-reduce 或 all-gather，视并行策略而定），流水线还会产生气泡。通信项不在公式里，于是公式给出的下界在多卡场景下不再是下界，而是不可达的乐观值。</p>\n<p>机制上，切分后单卡承担的算力项缩小为原来的 1/k（k 为切分数），但每层新增的通信时延与层数成正比，且通信与计算的重叠程度受限于 NVLink 5 的带宽与集合通信算法的启动开销。识别方法是做 scaling 测试：固定总 token 数，把切分数从 1 增到 2、4、8，若吞吐增长显著低于线性甚至出现回落，说明通信与气泡已经吃掉切分收益。此时按单卡公式反推的\"单卡可承载并发数 × 卡数\"会系统性高估集群容量。</p>\n<p>代价体现在容量规划上：按公式推算的并发数在现场达不到，扩容决策被误导——本该优先提升单卡效率（换更高 F 的 SKU 或改回单卡整编码器），却被引向继续加卡，而加卡进一步放大通信占比。工程判断：多卡切分视觉编码器时，必须把通信项显式加入时延模型，或直接采用单卡整编码器部署、把并行度留给解码侧；在视觉编码器参数量尚未大到单卡放不下时，后者的端到端收益通常更确定。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-33\">三十三 · 反例：一次按 roofline 规划的容量事故复盘</h3>\n<p>场景设定：某视频理解服务，输入为高分辨率帧流，视觉编码器为稠密 Transformer，部署在单张 Blackwell SM 上，规划者用 roofline 公式反推单卡最大并发图像数，并据此签下帧率 SLA。公式两项都算得漂亮：带宽项给出权重加载下界，算力项随 token 数线性增长，交点落在规划的分辨率附近，看起来\"刚好在算力受限区、余量充足\"。</p>\n<p>现场结果：并发数达到规划值的某个比例后，端到端时延开始超线性上升，帧率不达标。分段计时显示两个问题同时发作。其一，高分辨率帧流的 resize 与 normalize 在 GPU 上执行，其访存带宽与编码器权重加载争抢 HBM3e，实际可达带宽效率因子 <span class=\"formula-inline\">η<sub>mem</sub></span> 远低于公式假设值，带宽项被低估。其二，patch embedding 的 layout 变换引入了额外的 kernel 与同步点，破坏了\"权重与激活完全重叠\"的假设，算力项的实际效率因子 <span class=\"formula-inline\">η<sub>comp</sub></span> 同样被高估。两项同时偏低，公式给出的下界与实测之间出现稳定缺口，且缺口随帧率上升而扩大——因为预处理开销随帧数线性增长，而编码器主体的固定开销被摊薄。</p>\n<p>复盘结论不是\"公式错了\"，而是\"公式的适用边界被越过了\"：预处理未计入、重叠假设不成立、高分辨率帧流恰好落在公式明确标注的失效条件上。修正路径有两条：把预处理移出 GPU 关键路径（下沉到解码侧或独立流水线），使编码器主体重新独占 HBM 带宽；或改用单卡整编码器部署并重新实测 batch-吞吐曲线，用实测值而非公式值定并发上限。两条路径都指向同一个工程判断：roofline 是用来判断\"瓶颈在哪、扩容该加算力还是加带宽\"的定向工具，不是用来直接产出 SLA 数字的预测工具。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-34\">三十四 · 识别清单：什么时候不该信这个界</h3>\n<p>把上述误用收敛成可操作的识别清单，按检查顺序排列：</p>\n<ul>\n<li>预处理占比检查：分段计时，若 resize/normalize/patch embedding 的 layout 变换合计耗时超过编码器主体的一定比例，roofline 失效，先修流水线再谈容量。</li>\n<li>batch 扫描检查：batch 从 1 递增，若吞吐不随 batch 近似线性上升，系统处在固定开销区（典型为 196 token 小分辨率），公式低估时延，batch 上限以实测为准。</li>\n<li>scaling 检查：多卡切分时切分数翻倍，若吞吐增长显著低于线性，通信与流水气泡已破坏下界，需显式加入通信项或退回单卡整编码器。</li>\n<li>效率因子回填检查：用实测反推 <span class=\"formula-inline\">η<sub>comp</sub></span> 与 <span class=\"formula-inline\">η<sub>mem</sub></span>，若两者显著低于假设值，说明重叠假设或访存争抢已发生，公式两项同时被低估。</li>\n<li>分辨率敏感性检查：实测时延对 token 数的敏感度若低于公式推算的比例，同样指向开销主导或带宽争抢。</li>\n</ul>\n<p>这张清单的共同逻辑是：roofline 的两个分支各自对应一种瓶颈，误用的本质是把\"某一分支主导\"的结论外推到\"另一分支主导\"或\"两者都不主导\"的区域。识别方法就是通过扰动（batch、切分数、分辨率）观察系统响应是否与公式预测的方向一致；不一致处即为失效边界。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-35\">三十五 · 工程判断：把界用在决策上而非承诺上</h3>\n<p>正确的用法是把 roofline 当作<em>方向性决策工具</em>：给定目标分辨率与帧率，用公式判断当前配置落在带宽受限区还是算力受限区，从而决定扩容优先加 HBM 通道还是换更高 F 的 SKU。这个判断对扰动是稳健的——即使效率因子有偏差，两个分支的相对高低在交点附近之外仍然可信。而一旦要把公式输出转成对外承诺的数字（SLA、并发上限、帧率保证），就必须用实测曲线替换公式值，并把预处理、通信、固定开销三项显式纳入。</p>\n<p>落到具体机制上：在容量规划表里，roofline 只占\"瓶颈定位\"一列，其输出是\"当前受带宽约束/受算力约束\"的定性标签与交点附近的 token 数阈值；\"并发上限\"一列必须来自实测的 batch-吞吐曲线，\"时延承诺\"一列必须来自含预处理与通信的端到端打点。三列分离，误用就不会发生——因为公式的输出从来不会直接流进承诺列。这也是这套书反复强调的一点：界给出的是可行域的形状，不是可行域里某一个点的坐标。</p>\n\n<h3 id=\"th-visual-encoder-roofline-sec-36\">三十六 · 误用解剖：把下界当承诺、把单卡公式套到 NVL72、把 196 token 当成 roofline 的适用区</h3>\n\n<p>最常见的误用是把 <span class=\"formula\">$$T_{\\mathrm{enc}}$$</span> 这个下界直接写进 SLA 承诺。下界的语义是“任何实现都不可能快于它”，而工程交付需要的是“我的实现实际有多快”。两者之间夹着三类未被公式计入的开销：图像 resize 与 normalize 的逐像素算术、patch embedding 的 layout 变换（HWC→CHW→展平→GEMM 友好布局），以及跨 stage 的同步等待。识别方法很直接：在编码器前后各打一个 CUDA event，把端到端时延拆成预处理段、编码器段、后处理段三段计时。若预处理段占比超过编码器段，roofline 已经完全失去预测力，此时扩容算力或带宽都不会缩短端到端时延，真正的优化对象是预处理 kernel 的融合与布局变换的消除。视频帧流场景尤其危险——帧率越高，单位时间内需要 resize 的像素越多，预处理从配角变成主角，按 roofline 规划的 batch 在现场必然超时。</p>\n\n<p>第二类误用出现在 NVL72 上：把视觉编码器按层或按张量切到多卡，然后继续用单卡公式反推并发上限。公式的两项都假设权重与激活可以完全重叠加载、且不存在跨 stage 同步；一旦切分，每层边界处插入集合通信（AllReduce 或 AllGather），流水气泡随 stage 数增加而放大，实际吞吐远低于按公式推算值。识别信号是：实测吞吐随卡数增加不升反降，或升幅显著低于线性。此时正确做法是把通信项显式加入分母——将每层同步代价折算成等效时间并沿层累加，或干脆放弃切分、改用单卡整编码器部署，把多卡留给解码侧。容量规划阶段若忽略这一点，会系统性高估单机能承载的图像并发数，上线后表现为队列积压而非单请求超时，更难定位。</p>\n\n<p>第三类误用发生在小分辨率区间。224×224、196 token 时，GEMM 的 M 维极窄，kernel 启动延迟、固定开销与尾部效应占主导，两条 roofline 曲线都失去意义——公式给出的下界远低于实测，据此配置的 batch 过于激进，调度器以为还有余量而实际已经排队。判别阈值可以这样估：当单层 GEMM 的有效计算时间与 kernel 启动开销同量级时，roofline 失效。工程上的对策是把这一区间从 roofline 规划中划出去，改用实测的固定开销加线性项做经验模型，或者把小分辨率请求聚合成大 batch 以抬高 M 维、把 GEMM 重新推回高利用率区。</p>\n\n<table class=\"mini\"><thead><tr><th>误用</th><th>识别信号</th><th>系统代价</th></tr></thead><tbody><tr><td>下界当实测时延</td><td>预处理段计时占比超过编码器段</td><td>SLA 违约，扩容无效</td></tr><tr><td>单卡公式套 NVL72 切分</td><td>吞吐随卡数不升反降</td><td>并发容量系统性高估</td></tr><tr><td>196 token 仍用 roofline</td><td>实测远高于公式下界</td><td>batch 过激，排队积压</td></tr></tbody></table>\n\n<p>一个具体反例：某部署按 roofline 在单卡上反推出可承载的并发图像数，验收时单请求时延达标，但压测到规划并发时端到端时延翻倍。拆解后发现三段计时中预处理段占了近半，且 patch embedding 的 layout 变换未被融合，每次前向都要额外搬运一遍激活；同时该部署为省显存把编码器切到两卡，层间 AllGather 的气泡在高压并发下被放大。修正路径不是加卡，而是融合预处理 kernel、改回单卡整编码器、并把 batch 上限按实测固定开销重新标定——这正说明 roofline 的价值在于判断“该加算力还是加带宽”，而不在于给出可直接承诺的时延数字。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>N_{\\mathrm{vis}}</td><td>单张图像经 patch 化后的视觉 token 数</td></tr><tr><td>d_{\\mathrm{enc}}</td><td>视觉编码器隐藏维度</td></tr><tr><td>L_{\\mathrm{enc}}</td><td>视觉编码器 Transformer 层数</td></tr><tr><td>P_{\\mathrm{enc}}</td><td>视觉编码器参数量（含 patch embed 与位置编码）</td></tr><tr><td>F_{\\mathrm{peak}}</td><td>Blackwell SM 的 FP16/BF16 Tensor Core 峰值算力</td></tr><tr><td>\\mathrm{BW}_{\\mathrm{HBM}}</td><td>HBM3e 峰值带宽</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-visual-encoder-roofline · 共 5 个片段</p>\n"},{"id":"th-visual-token-compress-error","title":"视觉 token 压缩误差界","direction":"dir-crossmodal-alignment","prereq":[],"plain":"把 N 个视觉 token 压缩到 M 个（M<N）时，下游任务输出的偏差被压缩算子与任务相关权重的乘积上界约束；该界说明压缩率不能只看 token 保留比例，还要看被丢弃 token 在跨模态注意力中的有效权重，否则高压缩率会在细粒度定位任务上突然失效。","definition":"把 N 个视觉 token 压缩到 M 个（M<N）时，下游任务输出的偏差被压缩算子与任务相关权重的乘积上界约束；该界说明压缩率不能只看 token 保留比例，还要看被丢弃 token 在跨模态注意力中的有效权重，否则高压缩率会在细粒度定位任务上突然失效。","formula":"$$\\left\\|\\,f_{\\mathrm{VLM}}(X)-f_{\\mathrm{VLM}}(\\mathcal{C}(X))\\,\\right\\|_2 \\;\\le\\; \\sum_{i\\in\\mathcal{D}} \\alpha_i \\cdot \\left\\|x_i - \\Pi_{\\mathcal{K}}(x_i)\\right\\|_2 \\;+\\; \\frac{L_{\\mathrm{lip}}}{2}\\,\\left\\|\\mathcal{C}(X)-X\\right\\|_F^2$$","variables":[{"sym":"X","meaning":"原始视觉 token 序列（N×d 矩阵）"},{"sym":"\\mathcal{C}(X)","meaning":"压缩/合并后的视觉 token 序列（M×d）"},{"sym":"\\mathcal{D}","meaning":"被丢弃或合并的 token 索引集合"},{"sym":"\\alpha_i","meaning":"第 i 个视觉 token 在跨模态注意力中的有效权重（经校准估计）"},{"sym":"\\Pi_{\\mathcal{K}}","meaning":"向保留 token 子空间 K 的投影算子"},{"sym":"L_{\\mathrm{lip}}","meaning":"VLM 融合模块对视觉输入的 Lipschitz 常数"}],"derivation":"第二项 $$\\frac{L_{\\mathrm{lip}}}{2}\\|\\mathcal{C}(X)-X\\|_F^2$$ 中，$$L_{\\mathrm{lip}}$$ 是 VLM 融合模块对视觉输入的 Lipschitz 常数，Frobenius 范数度量压缩前后整矩阵的扰动能量；二次形式说明小扰动被平滑放大，大扰动则被 Lipschitz 常数硬性封顶。","example":"适用边界：仅对 L2 可度量的连续嵌入空间成立；压缩发生在离散 token id 或低比特量化表示时误差传播非线性，该二次界不再紧；且假设压缩算子与后续 LLM 解码解耦，若压缩后 token 顺序或位置编码被重排，跨模态注意力的位置偏置会引入额外不可忽略误差项。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["界中的 Lipschitz 常数 L_{\\mathrm{lip}} 与注意力权重 α_i 依赖具体输入，无法离线精确估计；用固定校准集估计的 α_i 在分布外图像（如文档 OCR、医学影像）上会严重低估误差。","仅对 L2 可度量的嵌入空间成立；当压缩发生在离散 token id 或量化后的低比特表示上时，误差传播是非线性的，该二次界不再紧。","假设压缩算子 C 与后续 LLM 解码解耦；若压缩后 token 顺序或位置编码被重排，跨模态注意力的位置偏置会引入额外不可忽略的误差项。"],"system_note":"容量决策用途：用该界在部署前为不同压缩率标定误差预算，决定细粒度定位任务（如文档 OCR、医学影像）可接受的最大压缩率，并据此选择保留 token 数 M 与显存/带宽节省的折中点。","papers":["paper-an-image-is-worth-16x16-words-transf-2020"],"facts":["直觉：压缩 N 个视觉 token 到 M 个时，下游 VLM 输出偏差被两项之和上界约束——被丢弃 token 的加权投影误差，加上压缩算子整体扰动的 Lipschitz 放大项；压缩率是否安全取决于被丢 token 在跨模态注意力中的有效权重而非保留比例。","公式第一项 $$\\sum_{i\\in\\mathcal{D}} \\alpha_i \\|x_i-\\Pi_{\\mathcal{K}}(x_i)\\|_2$$ 中，$$\\mathcal{D}$$ 是被丢弃或合并的 token 索引集，$$\\alpha_i$$ 是第 i 个 token 在跨模态注意力中的有效权重（经校准估计），$$\\Pi_{\\mathcal{K}}$$ 是向保留 token 子空间 K 的投影算子；该项度量被丢信息在注意力加权下的 L2 泄漏量。","第二项 $$\\frac{L_{\\mathrm{lip}}}{2}\\|\\mathcal{C}(X)-X\\|_F^2$$ 中，$$L_{\\mathrm{lip}}$$ 是 VLM 融合模块对视觉输入的 Lipschitz 常数，Frobenius 范数度量压缩前后整矩阵的扰动能量；二次形式说明小扰动被平滑放大，大扰动则被 Lipschitz 常数硬性封顶。","推导关键一步：将 VLM 融合视为 Lipschitz 连续映射，把压缩误差分解为被丢弃 token 的投影残差（经注意力权重加权）与保留 token 的表示扰动两部分，再用三角不等式合并得到可离线计算的保守上界。","适用边界：仅对 L2 可度量的连续嵌入空间成立；压缩发生在离散 token id 或低比特量化表示时误差传播非线性，该二次界不再紧；且假设压缩算子与后续 LLM 解码解耦，若压缩后 token 顺序或位置编码被重排，跨模态注意力的位置偏置会引入额外不可忽略误差项。","容量决策用途：用该界在部署前为不同压缩率标定误差预算，决定细粒度定位任务（如文档 OCR、医学影像）可接受的最大压缩率，并据此选择保留 token 数 M 与显存/带宽节省的折中点。","常见误用：用固定校准集估计的 $$\\alpha_i$$ 外推到分布外图像，严重低估误差，高压缩率在文档 OCR 或医学影像上突然失效；应在目标域重新校准注意力权重或对该域禁用激进压缩。"],"anchors":["未给出"],"pitfalls":["用固定校准集估计的注意力权重 α_i 外推到分布外图像（文档 OCR、医学影像），低估被丢 token 的有效权重，高压缩率在目标域突然失效且无法提前预警。","在量化后的低比特或离散 token id 表示上套用该二次界，误差传播非线性使界不再紧，按界设定的压缩率实际误差远超预算。","压缩后重排 token 顺序或改写位置编码，跨模态注意力的位置偏置引入界外误差项，公式给出的上界失效而工程上仍按它做容量决策。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-1\">一 · 一句话直觉与它为什么反直觉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-2\">二 · 严格定义：符号、两项、推导骨架</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-3\">三 · 为什么需要这个界：容量决策的锚点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-4\">四 · 常见误解之一：把保留比例当安全指标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-5\">五 · 常见误解之二：在离散或低比特表示上套用二次界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-6\">六 · 误差界管的是“丢了什么权重”，不是“留下多少比例”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-7\">七 · 第一项：加权投影残差的逐符号拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-8\">八 · 第二项：Lipschitz 放大与二次形式的来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-9\">九 · 推导关键步：三角不等式如何把两项拼起来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-10\">十 · 失效条件的数学定位：三处假设各自的破口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-11\">十一 · 用界做容量决策：把不等式反解成 M 的预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-12\">十二 · 常见误用的数学根源与修正路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-13\">十三 · 误差界的失效边界与容量决策代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-14\">十四 · 界成立的三条前提与它们的物理含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-15\">十五 · 失效条件一：α_i 的分布外漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-16\">十六 · 失效条件二：离散与低比特表示上的非线性传播</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-17\">十七 · 失效条件三：位置编码重排引入的界外项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-18\">十八 · 规模上限：界在什么尺寸区间才有决策价值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-19\">十九 · 边界不在公式里，而在 α_i 的来历与压缩发生的坐标上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-20\">二十 · 把误差界翻译成部署约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-21\">二十一 · 定 M：反解保留 token 数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-22\">二十二 · 定 KV 预算与批大小</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-23\">二十三 · 定并行度与 SLO 耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-24\">二十四 · 校准集外推的风险如何进入决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-25\">二十五 · 把误差界折进容量账本：批大小、并行度与 KV 预算的定法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-26\">二十六 · 误用的共同形状：把校准量当成常量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-27\">二十七 · 反例：固定校准集外推到文档 OCR</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-28\">二十八 · 第二类误用：在低比特与离散表示上套二次界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-29\">二十九 · 第三类误用：重排位置编码后仍沿用原界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-30\">三十 · 工程上的识别清单与处置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-visual-token-compress-error-sec-31\">三十一 · 误用与反例：当误差界变成容量决策的假依据</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:504px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 503.6 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"421.6\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"421.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：把 N 个视觉 token 压缩到 M 个（M&lt;N）时，下游任务输…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"421.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\left\\|\\,f_{\\mathrm{VLM}}(X)-f_…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"421.6\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：界中的 Lipschitz 常数 L_{\\mathrm{lip}}…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-visual-token-compress-error-sec-1\">一 · 一句话直觉与它为什么反直觉</h3>\n\n<p>把 N 个视觉 token 压到 M 个，直觉上人们看的是保留比例 M/N：保留 25% 似乎只丢四分之一信息，保留 10% 才该担心。这个直觉是错的。真正决定下游输出偏差的，是<strong>被丢弃的那批 token 在跨模态注意力里占多大权重</strong>。一句话：压缩 N→M 时，VLM 输出的偏差被两项之和封顶——被丢 token 的注意力加权投影残差，加上压缩算子整体扰动经融合模块 Lipschitz 放大后的项；压缩率是否安全取决于被丢 token 的有效权重而非保留比例。</p>\n\n<p>反直觉之处在于：一张 1024×1024 的文档扫描图切成 patch 后，绝大多数 token 是空白背景，注意力权重近乎为零，丢掉 90% 也几乎无损；而一张医学影像里，一个直径几十像素的病灶可能只占两三个 token，注意力权重却极高，丢掉它们等于把诊断依据扔掉。同样是 90% 压缩率，前者安全、后者灾难。保留比例是标量，有效权重是分布——用一个标量去管一个分布，必然在某些任务上突然失效。</p>\n\n<div class=\"formula\">$$\\left\\|\\,f_{\\mathrm{VLM}}(X)-f_{\\mathrm{VLM}}(\\mathcal{C}(X))\\,\\right\\|_2 \\;\\le\\; \\sum_{i\\in\\mathcal{D}} \\alpha_i \\cdot \\left\\|x_i - \\Pi_{\\mathcal{K}}(x_i)\\right\\|_2 \\;+\\; \\frac{L_{\\mathrm{lip}}}{2}\\,\\left\\|\\mathcal{C}(X)-X\\right\\|_F^2$$</div>\n\n<h3 id=\"th-visual-token-compress-error-sec-2\">二 · 严格定义：符号、两项、推导骨架</h3>\n\n<p>设原始视觉 token 序列为矩阵 X（N×d），压缩算子 C 把它映射为 M×d 的 C(X)，M&lt;N。D 是被丢弃或合并掉的 token 索引集合；α_i 是第 i 个 token 在跨模态注意力中的有效权重（经校准估计）；Π_K 是向保留 token 子空间 K 的投影算子；L_lip 是 VLM 融合模块对视觉输入的 Lipschitz 常数。f_VLM 表示从视觉 token 到下游任务输出的映射。</p>\n\n<p>第一项 $$\\sum_{i\\in\\mathcal{D}} \\alpha_i \\|x_i-\\Pi_{\\mathcal{K}}(x_i)\\|_2$$ 度量的是<strong>被丢信息在注意力加权下的 L2 泄漏量</strong>：每个被丢 token 先投影到保留子空间，残差是其不可恢复部分，再乘上它在跨模态注意力里的话语权。注意这不是简单的“丢了多少”，而是“丢的部分有多少被下游真正用到”。第二项 $$\\frac{L_{\\mathrm{lip}}}{2}\\|\\mathcal{C}(X)-X\\|_F^2$$ 用 Frobenius 范数度量压缩前后整矩阵的扰动能量，二次形式说明小扰动被平滑放大、大扰动被 Lipschitz 常数硬性封顶——融合模块本身是平滑的，误差不会指数爆炸，但也不会自动消失。</p>\n\n<p>推导骨架三步：把 VLM 融合视为 Lipschitz 连续映射；把压缩误差分解为被丢弃 token 的投影残差（经注意力权重加权）与保留 token 的表示扰动两部分；再用三角不等式合并，得到可离线计算的保守上界。关键在于“保守”——这个界不追求紧，追求的是<strong>部署前可算</strong>，从而把压缩率选择从拍脑袋变成有预算约束的工程决策。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-3\">三 · 为什么需要这个界：容量决策的锚点</h3>\n\n<p>没有这个界，压缩率只能靠试：压到 50% 跑一遍评测，不行退到 25%，再不行退到 12.5%。这在多模态推理服务里代价极高——视觉 token 直接吃 prefill 的算力和 KV cache 显存，一次全量评测的代价是整条链路重跑。更糟的是，评测集往往与线上分布不一致，离线通过的压缩率上线后照样翻车。</p>\n\n<p>这个界把问题转成预算分配：给定下游任务可容忍的输出偏差 ε，反解出允许的压缩强度，再据此选保留 token 数 M，以及对应的显存与带宽节省。视觉 token 数从 N 降到 M，prefill 阶段的自注意力计算量按 M² 量级下降、KV cache 占用按 M 线性下降，这两笔收益是压缩的全部动机；而界告诉你这笔收益能不能拿、能拿多少。对细粒度定位任务（文档 OCR、医学影像），α_i 分布长尾且集中，界会迅速收紧，逼迫你保留更多 token；对以整体语义为主的任务（场景分类、粗粒度检索），α_i 分布平坦，界宽松，激进压缩才划算。</p>\n\n<p>工程上的用法是：在目标域采样一批输入，校准 α_i 与 L_lip，对若干候选 M 算出上界曲线，取满足 ε 的最大压缩率作为默认档，同时保留一个更保守的档给分布外流量兜底。这把“压缩率”从一个全局超参变成了按任务、按域标定的预算项。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-4\">四 · 常见误解之一：把保留比例当安全指标</h3>\n\n<p>最普遍的误用是用固定校准集估计的 α_i 外推到分布外图像。校准集通常是自然图像，α_i 分布平坦，据此算出的界很松，于是工程上敢把压缩率推到很高。一旦流量里混入文档 OCR 或医学影像，这些域里少数 token 的 α_i 极高，而被丢弃的恰恰是它们——界严重低估误差，高压缩率在目标域突然失效，且事前没有任何预警信号。公式本身没错，错在 α_i 的域外外推。正确做法是在目标域重新校准注意力权重，或对该域直接禁用激进压缩，把压缩率锁在一个由该域 α_i 上界决定的保守值。</p>\n\n<p>第二个相关误解是把“合并”当成“丢弃”的同义词。合并（merge）把多个 token 平均成一个，投影残差被摊薄，第一项变小；但它同时改变了保留 token 的表示，第二项的 Frobenius 扰动变大。两者是此消彼长的关系，不能只盯第一项。工程判断是：当 α_i 高度集中时，合并优于丢弃（避免整块信息消失）；当 α_i 平坦时，丢弃更省（合并引入的表示扰动不划算）。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-5\">五 · 常见误解之二：在离散或低比特表示上套用二次界</h3>\n\n<p>该界仅对 L2 可度量的连续嵌入空间成立。当压缩发生在离散 token id 或量化后的低比特表示上时，误差传播是非线性的，二次界不再紧——按界设定的压缩率，实际误差会远超预算。原因很直接：低比特表示的舍入误差不是各向同性的 L2 扰动，它在码本边界附近会被放大成跳变，Lipschitz 常数无法刻画这种不连续。若你的流水线是“先量化视觉编码器输出、再压缩”，必须把量化误差单独计入预算，而不能把它塞进第二项的 Frobenius 范数里蒙混过关。</p>\n\n<p>第三个失效条件是位置偏置。界假设压缩算子 C 与后续 LLM 解码解耦；一旦压缩后 token 顺序被重排或位置编码被改写，跨模态注意力的位置偏置会引入公式之外的额外误差项，上界失效而工程上仍按它做容量决策。这在按显著性重排 token 的实现里尤其危险：重排本身不改变 token 内容，却改变了注意力看到的位置关系，误差不在两项之内。稳妥做法是压缩时保持相对顺序，或把重排带来的位置扰动作为独立项显式加进预算。</p>\n\n<table class=\"mini\"><thead><tr><th>误解</th><th>机制后果</th><th>系统代价</th><th>纠正</th></tr></thead><tbody><tr><td>用保留比例当安全指标</td><td>α_i 长尾被平均掉</td><td>细粒度任务上线后精度骤降，需回滚重跑 prefill</td><td>按域校准 α_i，取满足 ε 的最大 M</td></tr><tr><td>丢弃与合并混为一谈</td><td>第一项降、第二项升</td><td>合并档显存省了但输出偏差超预算</td><td>按 α_i 集中度选丢弃或合并</td></tr><tr><td>低比特上套二次界</td><td>舍入跳变非线性放大</td><td>实际误差远超预算，KV cache 省下的显存换不回精度</td><td>量化误差单列预算项</td></tr><tr><td>压缩后重排位置</td><td>位置偏置引入界外项</td><td>上界失效仍被用于容量决策</td><td>保序压缩或显式加位置扰动项</td></tr></tbody></table>\n\n<p>把这张表读成一句话：这个界是<strong>预算工具而非精度保证</strong>。它的价值在于把“能不能压到 M”变成“在目标域上 α_i 与 L_lip 标定后，ε 预算是否够”，从而让压缩率选择有据可依；它的危险在于被当成跨域通用的常数表。工程上真正要落地的机制是：每个目标域维护一组 (α_i 分布, L_lip) 标定值，压缩率随域切换，分布外流量走保守档——这一步做不做，决定了高压缩率是省钱还是事故。</p>\n\n\n<h3 id=\"th-visual-token-compress-error-sec-6\">六 · 误差界管的是“丢了什么权重”，不是“留下多少比例”</h3>\n<p>把这条界当作压缩器的验收口径，它的边界首先体现在<strong>它约束的对象是连续嵌入，而不是 token 计数</strong>。界写成两项之和：被丢弃索引集 <span>𝒟</span> 上按跨模态注意力有效权重 <span>α<sub>i</sub></span> 加权的投影残差，加上融合模块 Lipschitz 常数 <span>L<sub>lip</sub></span> 对整矩阵扰动能量的二次放大项。工程含义是：压缩率的安全性由“被丢掉的 token 在跨模态注意力里到底占多少权重”决定，而不是由保留比例 <span>M/N</span> 决定。一个把 90% token 合并掉的方案，如果丢的都是注意力权重接近零的背景 patch，界的第一项几乎为零；反过来，只丢 20% 却恰好丢掉 OCR 里承载字符笔画的那批 token，第一项会突然抬升，下游输出偏差随之上穿预算。这就是“高压缩率在细粒度定位任务上突然失效”的机制来源——失效不是渐进的，而是当 <span>𝒟</span> 开始覆盖高 <span>α<sub>i</sub></span> 区域时发生的相变。</p>\n<p>失效条件有三类，工程上必须分别设防。第一类是<strong>权重估计的域偏移</strong>：<span>α<sub>i</sub></span> 依赖具体输入，无法离线精确得到，只能用校准集估计；把自然图像校准出的 <span>α<sub>i</sub></span> 外推到文档 OCR 或医学影像，会系统性低估被丢 token 的有效权重，界看起来很松、实际误差早已越界，且没有任何在线信号预警。第二类是<strong>表示空间不匹配</strong>：二次界只在 L2 可度量的嵌入上成立，一旦压缩发生在离散 token id 或量化后的低比特表示上，误差传播是非线性的，按此界设定的压缩率实际误差远超预算。第三类是<strong>解耦假设被破坏</strong>：界假设压缩算子 <span>𝒞</span> 与后续 LLM 解码解耦；若压缩后重排 token 顺序或改写位置编码，跨模态注意力的位置偏置会引入一个界外误差项，公式上界失效而容量决策仍按它做，这是最隐蔽的一种。</p>\n<p>系统代价要按三项拆开看。第一项的计算代价是每个被丢 token 一次投影与一次加权求和，量级为 <span>|𝒟|·d</span>，相对注意力本身可忽略，但它要求保留 <span>α<sub>i</sub></span> 的校准表，这是一份按域维护的离线资产，域切换就要重校准，属于部署期人力成本而非运行时开销。第二项里的 <span>L<sub>lip</sub></span> 是融合模块的属性，可离线测量一次，但 Frobenius 范数要在压缩前后各算一次整矩阵差，对 <span>N×d</span> 的视觉序列是一次 <span>O(Nd)</span> 的带宽读取——在预填阶段这相当于把视觉嵌入多读一遍，对显存带宽是实打实的占用。真正的运行时代价则落在容量侧：为了把界压在预算内，往往要把 <span>M</span> 抬高，直接换算成 KV cache 与视觉嵌入的显存占用、以及每步解码要扫的跨模态注意力长度，吞吐随之下降。换言之，这条界不是免费的加速器，它是用显存与带宽换误差确定性的一张报价单。</p>\n<p>一个具体的工程判断：在文档 OCR 这类任务上，不要用自然图像校准出的 <span>α<sub>i</sub></span> 去定 <span>M</span>，而应在目标域重新校准，或对该域直接禁用激进压缩、退回按行/按块的保守合并。校准的做法是把目标域样本跑一遍完整注意力，统计每个视觉 token 收到的跨模态权重，取分位数作为 <span>α<sub>i</sub></span> 的保守估计，再代入界反解出满足误差预算的最大压缩率。表里给出三种典型域下界的行为差异，用于决定是否值得为压缩率冒险。</p>\n<table class=\"mini\"><thead><tr><th>目标域</th><th>α<sub>i</sub> 分布特征</th><th>界的第一项行为</th><th>工程取舍</th></tr></thead><tbody><tr><td>自然图像问答</td><td>权重集中于少数显著物体 token</td><td>丢背景 token 时近似为零</td><td>可激进压缩，M 取小</td></tr><tr><td>文档 OCR</td><td>权重弥散于字符笔画 token</td><td>丢字即抬升，界迅速收紧</td><td>目标域重校准或禁用激进压缩</td></tr><tr><td>医学影像</td><td>权重随病灶位置高度输入相关</td><td>校准集外推严重低估</td><td>保守 M，保留定位分辨率</td></tr></tbody></table>\n<p>最后落在机制上：这条界真正的用途不是给出一个可打印的数字，而是把“压缩率”这个标量替换成“被丢权重 × 投影残差”的向量式预算，让容量规划从拍保留比例转为按域标定 <span>α<sub>i</sub></span> 并反解 <span>M</span>。凡是在离散 id 或低比特表示上做压缩、或压缩后改动位置编码的路径，都应视为界外操作，不能拿这条二次界做容量决策的依据。</p>\n<h3 id=\"th-visual-token-compress-error-sec-7\">七 · 第一项：加权投影残差的逐符号拆解</h3>\n<p>第一项 $$\\sum_{i\\in\\mathcal{D}} \\alpha_i \\cdot \\left\\|x_i - \\Pi_{\\mathcal{K}}(x_i)\\right\\|_2$$ 不是对全部 N 个 token 求和，而是只对索引集 $$\\mathcal{D}$$ 求和——这一点决定了它的工程含义：它是“被丢掉的东西”的代价，而不是“压缩算子整体扰动”的代价。$$\\Pi_{\\mathcal{K}}$$ 是向保留 token 张成的子空间 K 的正交投影，因此 $$\\|x_i-\\Pi_{\\mathcal{K}}(x_i)\\|_2$$ 恰好是被丢 token $$x_i$$ 中无法由保留 token 线性表示的那部分能量，也就是“不可恢复分量”。若被丢 token 与保留 token 高度共线（例如大片纯色背景块），投影残差接近零，丢弃它几乎不产生误差；若被丢 token 携带保留集里没有的方向（细粒度文字笔画、病灶边缘），残差就是该方向的模长。</p>\n<p>$$\\alpha_i$$ 是跨模态注意力中该 token 获得的实际权重，它把几何残差换算成“对输出有影响的量”。关键在于 $$\\alpha_i$$ 与 $$\\|x_i-\\Pi_{\\mathcal{K}}(x_i)\\|$$ 并不独立：视觉编码器往往把高显著性区域编码成方向独特、范数偏大的 token，这类 token 同时具有大 $$\\alpha_i$$ 和大投影残差，乘积被双重放大。这就是“保留比例”指标失效的数学根源——按比例丢弃 90% 的 token，若被丢的恰是 $$\\alpha_i$$ 集中的那一小撮，第一项并不随 M/N 线性下降。工程上应把 $$\\alpha_i \\cdot \\|\\cdot\\|_2$$ 作为逐 token 的打分排序，而不是按位置或相似度聚类批量丢弃。</p>\n<p>代价面：第一项的计算需要一次投影（对每个被丢 token 求解其在 K 上的最小二乘表示），复杂度约为 $$O(|\\mathcal{D}|\\cdot M\\cdot d)$$，在 N 数千、d 数千的量级上属于毫秒级离线开销，可放在预填阶段之前一次性完成。但它依赖 $$\\alpha_i$$，而 $$\\alpha_i$$ 只能通过在校准集上跑一次前向、读取跨模态注意力图获得——这意味着该界天然带一次“校准前向”的延迟成本，且该成本随校准集规模线性增长。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-8\">八 · 第二项：Lipschitz 放大与二次形式的来源</h3>\n<p>第二项 $$\\frac{L_{\\mathrm{lip}}}{2}\\left\\|\\mathcal{C}(X)-X\\right\\|_F^2$$ 的二次形式来自融合模块的平滑性假设：把 VLM 的视觉-语言融合视作 Lipschitz 连续映射 $$f$$，则对扰动 $$\\delta=\\mathcal{C}(X)-X$$，有 $$\\|f(X+\\delta)-f(X)\\|_2 \\le L_{\\mathrm{lip}}\\|\\delta\\|_2$$。但界里出现的是 $$\\|\\delta\\|_F^2$$ 而非 $$\\|\\delta\\|_F$$，说明推导中额外用了一步“残差在融合模块内部被二次型能量范数度量”的展开——即把融合模块在参考点附近的局部行为近似为二次型，系数 $$L_{\\mathrm{lip}}/2$$ 是二次型上界的标准配平因子。其直接后果是：小扰动被平方压低（扰动减半，该项降到四分之一），大扰动则被 $$L_{\\mathrm{lip}}$$ 硬性封顶，不会无限增长。</p>\n<p>这一项与第一项的分工是清晰的：第一项管“丢掉了什么”，第二项管“保留下来的 token 被改动了多少”。合并 token 时，保留 token 的表示会被重写（均值池化、注意力合并都会改变其数值），这部分扰动不体现在 $$\\mathcal{D}$$ 上，而体现在 Frobenius 范数里。因此一个只做“丢弃”不做“合并”的压缩算子，第二项接近零；而任何做特征级合并的算子（如 token merging、可学习的压缩 query），第二项都不可忽略。</p>\n<p>代价面：$$L_{\\mathrm{lip}}$$ 是融合模块的全局属性，无法离线精确求得，只能通过在不同扰动幅度下探测输出变化来估计一个保守值。这个估计本身要跑多次前向，且估计出的常数偏保守会把界撑大，导致容量规划时过度保守、放弃本可安全的压缩率。工程折中是：只在目标域上估计一次 $$L_{\\mathrm{lip}}$$，并在压缩率扫描时把它当作固定系数，观察界随 $$\\|\\delta\\|_F^2$$ 的变化趋势而非绝对值。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-9\">九 · 推导关键步：三角不等式如何把两项拼起来</h3>\n<p>推导骨架是三步。第一步，把输出偏差写成“被丢 token 贡献的偏差”与“保留 token 表示扰动贡献的偏差”之和：</p>\n<div class=\"formula\">$$f(X)-f(\\mathcal{C}(X))=\\underbrace{\\sum_{i\\in\\mathcal{D}}\\alpha_i\\,(x_i-\\Pi_{\\mathcal{K}}(x_i))}_{\\text{丢弃项}}+\\underbrace{\\Delta_{\\mathcal{K}}}_{\\text{保留项扰动}}$$</div>\n<p>第二步，对右端取 L2 范数并用三角不等式拆开：$$\\|a+b\\|_2\\le\\|a\\|_2+\\|b\\|_2$$。第三步，对丢弃项逐项取范数（$$\\alpha_i$$ 为非负标量可提出），对保留项用 Lipschitz 平滑性把它压到 $$\\frac{L_{\\mathrm{lip}}}{2}\\|\\delta\\|_F^2$$。三步都是保守化操作，每一步都只放大不缩小，所以最终界是严格上界而非近似。</p>\n<p>离散化与近似发生在两处，必须点明。其一，$$\\Pi_{\\mathcal{K}}$$ 的“保留子空间”在实际实现中是离散的 token 集合张成的子空间，而非连续子空间；当保留 token 数 M 较小、集合近乎正交时，投影残差近似等于原始范数，此时第一项退化为“被丢 token 的加权范数和”，界变松。其二，$$\\alpha_i$$ 的校准是采样近似：用有限校准样本的注意力均值代替真实输入下的瞬时权重，这一步引入了分布依赖的近似误差，且该误差不进入公式右端——公式假装 $$\\alpha_i$$ 是精确的，实际它是估计量。这就是为什么界的“正确性”与“紧致性”是两件事：界在数学上成立，但在分布外输入上因 $$\\alpha_i$$ 低估而失去紧致性，工程上表现为“按界算安全、实测崩掉”。</p>\n<p>另一个近似点：融合模块被当作单一 Lipschitz 映射，而真实 VLM 的融合是“视觉投影层 + 多层交叉注意力 + FFN”的复合。复合映射的 Lipschitz 常数是各层常数之积，这个积通常远大于任何单层估计值，因此用单层探测估计出的 $$L_{\\mathrm{lip}}$$ 会系统性偏小——这与 $$\\alpha_i$$ 低估叠加，构成界在激进压缩下失效的两个独立来源。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-10\">十 · 失效条件的数学定位：三处假设各自的破口</h3>\n<p>第一处破口是 L2 可度量性。公式整体建立在嵌入空间的欧氏结构上，一旦压缩发生在离散 token id 或低比特量化表示上，$$x_i-\\Pi_{\\mathcal{K}}(x_i)$$ 不再有定义，误差传播经由查表与舍入变成非线性、非连续的，二次界不再紧。此时正确做法是把量化误差单独建模为均匀分布噪声的方差项，而不是塞进这个 L2 界。</p>\n<p>第二处破口是解耦假设。公式默认 $$\\mathcal{C}$$ 只改数值、不改顺序；一旦压缩后重排 token 或改写位置编码，跨模态注意力里的位置偏置会引入一个既不在 $$\\mathcal{D}$$ 上、也不在 Frobenius 扰动里的额外项。这个项的量级取决于位置编码方案（绝对位置编码比 RoPE 更敏感），且无法用现有两项吸收，公式给出的上界因此失效而工程上仍按它做容量决策——这是最危险的一类误用，因为界看起来仍然“成立”，只是不再覆盖真实误差。</p>\n<p>第三处破口是 $$\\alpha_i$$ 的分布依赖。用固定校准集估计的 $$\\alpha_i$$ 在文档 OCR、医学影像这类目标域上会严重低估被丢 token 的有效权重：文档里每个字符 token 的注意力权重都高且分散，医学影像里病灶边缘 token 的权重集中但校准集里没有同类样本。数学上这不是界的错误，而是估计量的偏差；工程判断是：对这类域，要么在目标域重新校准 $$\\alpha_i$$，要么直接禁用激进压缩，把 M 的下限锁在能覆盖细粒度结构的水平。</p>\n<table class=\"mini\"><thead><tr><th>假设</th><th>破口表现</th><th>工程对策</th></tr></thead><tbody><tr><td>L2 可度量</td><td>离散/低比特表示下界不紧</td><td>量化噪声单独建模，不套二次界</td></tr><tr><td>压缩与解码解耦</td><td>重排顺序/位置编码引入界外项</td><td>压缩算子保持顺序不变式</td></tr><tr><td>$$\\alpha_i$$ 可校准</td><td>分布外域低估权重</td><td>目标域重校准或锁 M 下限</td></tr></tbody></table>\n\n<h3 id=\"th-visual-token-compress-error-sec-11\">十一 · 用界做容量决策：把不等式反解成 M 的预算</h3>\n<p>容量决策的用法是把界当作误差预算约束反解 M。给定任务可容忍的输出偏差 $$\\varepsilon$$，要求 $$\\sum_{i\\in\\mathcal{D}}\\alpha_i\\|x_i-\\Pi_{\\mathcal{K}}(x_i)\\|_2+\\frac{L_{\\mathrm{lip}}}{2}\\|\\mathcal{C}(X)-X\\|_F^2\\le\\varepsilon$$。由于 $$\\mathcal{D}$$ 随 M 变化，工程做法是按 $$\\alpha_i\\cdot\\text{残差}$$ 从大到小排序 token，逐个尝试并入保留集，直到剩余被丢 token 的加权残差和落入预算；第二项则作为固定开销先从预算里扣除。这样得到的 M 是“按有效权重而非按比例”确定的，通常显著大于按保留比例拍脑袋得到的值，但换来的显存与带宽节省是真正安全的。</p>\n<p>代价换算：视觉 token 从 N 降到 M，多模态 KV cache 的视觉部分按 M/N 缩减，预填阶段视觉编码器的注意力计算量按 $$O(M^2)$$ 缩减，跨模态注意力的 QK 乘积按 M 线性缩减。但若 M 被界推高，这些节省同步缩水——界越保守，可兑现的显存/带宽收益越小。这正是该界的工程价值所在：它把“压缩率”从拍脑袋的比例变成一个带误差预算的优化变量，代价是必须接受一次校准前向和一次投影计算的开销。</p>\n<p>具体例子：文档 OCR 场景下，一页扫描件被编码成数千个视觉 token，字符笔画 token 的 $$\\alpha_i$$ 高且投影残差大（保留集里没有同方向的 token），按 90% 保留比例压缩会把这类 token 大批丢进 $$\\mathcal{D}$$，第一项迅速逼近甚至超过 $$\\varepsilon$$；而同一压缩率用在自然图像上，被丢的多是低频背景块，残差小、$$\\alpha_i$$ 低，界远低于预算。同一个 M 在两个域上的安全性完全不同，这就是“压缩率不能只看保留比例”的定量表达。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-12\">十二 · 常见误用的数学根源与修正路径</h3>\n<p>误用一：把 $$\\alpha_i$$ 当作与输入无关的常数。数学上 $$\\alpha_i$$ 是注意力 softmax 的输出，随输入变化；把它冻结成校准均值，等价于假设注意力分布在域内平稳。修正路径是在目标域上重跑校准前向，或对 $$\\alpha_i$$ 加一个按域估计的膨胀系数，把界撑到覆盖分布偏移。</p>\n<p>误用二：在量化后的低比特表示上直接套二次界。此时 $$x_i$$ 已是舍入后的值，$$\\Pi_{\\mathcal{K}}$$ 的投影在低比特格点上不封闭，残差计算本身失真。修正路径是把压缩误差拆成“结构压缩误差”（用本界）与“量化误差”（用独立的方差界），两者相加而非混用。</p>\n<p>误用三：压缩后重排 token 却仍按公式做容量决策。位置偏置项的量级与重排幅度成正比，工程上应把“压缩算子是否保持 token 顺序”作为硬约束写进实现，而不是事后用界去补。若必须重排，则需在界右端显式加一项位置偏置的上界估计，否则界不覆盖真实误差。</p>\n<p>这三类误用的共同点是：公式在数学上仍然成立，失效的是它的假设与估计量。工程判断应落在“先验证假设是否被实现破坏，再谈界的数值”——把压缩算子实现成保序、连续嵌入、目标域校准三件事都满足，界才有资格进入容量规划。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-13\">十三 · 误差界的失效边界与容量决策代价</h3>\n<p>该上界的第一项$$\\sum_{i\\in\\mathcal{D}} \\alpha_i \\|x_i-\\Pi_{\\mathcal{K}}(x_i)\\|_2$$决定了压缩率的安全区，但$$\\alpha_i$$只能在部署前用校准集估计，这使上界天然是“域内紧、域外松”的。固定校准集给出的$$\\alpha_i$$在分布外图像上会系统性低估被丢 token 的有效权重：文档 OCR 中一个被合并的字符块、医学影像中一处微小病灶对应的 token，在跨模态注意力里权重极高，而在通用校准集上几乎不被采样。工程后果是容量规划失真——按界标定的最大压缩率在目标域被突破，误差不是缓慢退化而是突然跳变，且部署侧没有任何预警信号。可行做法是对目标域重新校准$$\\alpha_i$$，或对细粒度定位类负载直接禁用激进压缩，把 M 固定在保守值。</p>\n<p>第二项$$\\frac{L_{\\mathrm{lip}}}{2}\\|\\mathcal{C}(X)-X\\|_F^2$$的二次形式只在连续嵌入空间成立。一旦压缩发生在离散 token id 或 NVFP4/FP8 量化后的低比特表示上，误差传播是非线性的，二次界不再紧：量化误差经反量化与层归一化后被放大，实际偏差可以远超按界推算的预算。此时用该界做显存/带宽折中点选择，会得到偏乐观的 M，KV cache 与视觉侧带宽节省看似可观，实际输出偏差却已越过任务容忍阈值。判断标准很直接——压缩算子若含取整、查表或离散合并，就不要把该界当作硬约束，只能当排序用的相对指标。</p>\n<p>推导中“压缩算子与 LLM 解码解耦”的假设同样脆弱。若压缩后重排 token 顺序或改写位置编码，跨模态注意力的位置偏置会引入界外的额外误差项，公式给出的上界失效，而工程上仍按它做容量决策。这类误差在长文档多页拼接、视频多帧时序压缩中尤其明显。系统代价上，重排带来的额外项无法离线估计，只能靠在线抽样比对原始与压缩输出的 L2 偏差做兜底监控；这笔监控开销本身要占推理延迟预算的一小部分，且需要保留原始 token 的旁路副本，抵消了一部分显存节省。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>界的行为</th><th>工程代价</th></tr></thead><tbody><tr><td>α_i 外推到分布外域</td><td>低估第一项，界偏松</td><td>目标域突然失效，需重校准或禁用压缩</td></tr><tr><td>离散/低比特压缩</td><td>二次界不再紧</td><td>M 取值偏大，偏差超预算</td></tr><tr><td>token 重排或位置编码改写</td><td>界外误差项</td><td>需旁路副本与在线偏差监控</td></tr></tbody></table>\n<h3 id=\"th-visual-token-compress-error-sec-14\">十四 · 界成立的三条前提与它们的物理含义</h3>\n<p>公式不是无条件成立的恒等式，而是一组前提推出来的保守上界。拆开看，它至少依赖三件事同时为真：其一，压缩前后都处在同一个 L2 可度量的连续嵌入空间里，$$\\mathcal{C}(X)$$ 与 $$X$$ 都是 N×d 与 M×d 的实矩阵，投影算子 $$\\Pi_{\\mathcal{K}}$$ 才有定义；其二，融合模块对视觉输入的响应可以被一个全局 Lipschitz 常数 $$L_{\\mathrm{lip}}$$ 封住，三角不等式合并两项时才不引入额外松弛；其三，压缩算子与后续 LLM 解码解耦，即压缩只改变喂给融合模块的视觉表示，不触碰位置编码、token 顺序与解码路径。这三条里任何一条被工程实现破坏，界就从“上界”退化为“一个与真实误差无单调关系的数”。在 Blackwell 上做部署决策时，真正要问的不是“公式写没写对”，而是“我这套压缩管线落在这三条前提的哪一侧”。</p>\n<p>前提的物理含义直接对应显存与带宽账本。连续嵌入空间意味着压缩在 HBM 里操作的是 bf16/fp8 的激活张量，一次压缩的搬运量约为 $$N \\cdot d \\cdot b$$ 字节（b 为每元素字节数），这是可以进 roofline 的；而一旦压缩发生在离散 token id 上，搬运的是索引而非嵌入，账本形态完全变了，界也随之失效。Lipschitz 前提则对应融合模块的算子结构：若融合是若干注意力和 MLP 的堆叠，$$L_{\\mathrm{lip}}$$ 是各层谱范数乘积的上界，工程上无法精确算出，只能用谱归一化或区间传播给一个保守估计——这本身就是一个代价：保守估计会把界抬高，进而把可接受压缩率压低，牺牲显存节省。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-15\">十五 · 失效条件一：α_i 的分布外漂移</h3>\n<p>第一项 $$\\sum_{i\\in\\mathcal{D}} \\alpha_i \\|x_i-\\Pi_{\\mathcal{K}}(x_i)\\|_2$$ 的全部有效性压在 $$\\alpha_i$$ 上。$$\\alpha_i$$ 是第 i 个视觉 token 在跨模态注意力中的有效权重，靠校准集估计。校准集是固定的一批图文对，估出来的是一组与输入分布绑定的数。换到文档 OCR 场景，被丢掉的往往是承载细小字形笔画的 token，它们在文本查询下的注意力权重远高于自然图像校准集里的统计值；换到医学影像，病灶边缘的高频 token 同理。此时 $$\\alpha_i$$ 被系统性低估，第一项算出来偏小，界给出的“安全压缩率”偏高，实际误差在目标域突然放大且没有预警信号。这不是数值误差，是权重估计的支撑集错配。</p>\n<p>工程上的判别方法不是去猜 $$\\alpha_i$$ 真值，而是做域内重校准：在目标域采一小批样本，前向一遍记录跨模态注意力对视觉 token 的归一化权重，重算 $$\\sum_{i\\in\\mathcal{D}} \\alpha_i \\|\\cdot\\|$$ 的量级。代价是每换一个域就要一次校准前向，占用预填算力；收益是避免在 OCR 上按自然图像标定的压缩率上线后精度崩塌。若无法重校准，正确做法是对该域禁用激进压缩，把 M 抬回接近 N，用显存换正确性——在 GB200 NVL72 这种单机显存充裕但跨机带宽紧张的形态里，这意味着把视觉 token 留在本地 HBM、只压 KV 的另一侧，而不是压视觉侧。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-16\">十六 · 失效条件二：离散与低比特表示上的非线性传播</h3>\n<p>第二项 $$\\frac{L_{\\mathrm{lip}}}{2}\\|\\mathcal{C}(X)-X\\|_F^2$$ 的二次形式来自“小扰动被平滑放大、大扰动被 Lipschitz 封顶”的连续映射假设。当压缩发生在量化后的低比特表示上——比如视觉侧已走 NVFP4/FP8 通路，压缩在低比特张量上做合并——误差传播不再满足这个二次律：量化是阶梯函数，舍入误差不随扰动能量二次增长，而是按量化步长做分段常值跳变，再经融合模块放大后呈现非单调、甚至阈值式的突变。此时按二次界设定的压缩率，实际误差可以远超预算，因为界低估了阶梯跳变的幅度。同理，压缩若发生在离散 token id 上（合并、去重、聚类到码本），投影残差 $$\\|\\cdot\\|_2$$ 本身就没有良好定义，第一项失去度量基础。</p>\n<p>判别标准很直接：压缩算子的输入输出是否为同精度的连续张量。若是，二次界可用；若压缩跨了精度边界或跨了连续/离散边界，界只能当定性参考，不能进容量决策。代价层面，低比特压缩的收益是显存与带宽双减（视觉 token 的字节数下降），但误差不可界意味着必须留出更大的精度余量，实际可用的压缩率反而低于连续域。在 tcgen05 与 TMEM 的流水里，这意味着压缩 kernel 要保持在 bf16 域完成合并、再统一降到低比特，而不是在低比特域里做合并——多一次域转换的搬运，换一个仍然成立的界。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-17\">十七 · 失效条件三：位置编码重排引入的界外项</h3>\n<p>公式假设压缩与解码解耦，但工程实现里最常见的加速手段恰恰是破坏这个假设：压缩后把保留 token 重新排布、重写位置编码以维持序列紧凑，或把二维位置索引压成一维。跨模态注意力带位置偏置，重排后同一视觉 token 对文本查询的注意力分布发生偏移，这部分误差不在 $$\\sum \\alpha_i \\|\\cdot\\|$$ 与 Lipschitz 项的任何一项里，是界外的加性项。它的量级与重排幅度、位置编码方案（绝对/相对/旋转）相关，无法从公式读出。结果是公式给出的上界在数值上仍然“成立”，但它约束的对象已经不是实际跑的管线——工程上按它做容量决策，等于用错误的模型做正确的算术。</p>\n<p>规避方式是把重排纳入压缩算子定义：若 $$\\mathcal{C}$$ 显式包含位置重写，则 $$\\|\\mathcal{C}(X)-X\\|_F$$ 必须把位置通道的扰动一起算进去，界才重新覆盖真实管线；否则应保持位置编码与 token 顺序不变，只做值域合并。代价是后者在序列紧凑性上吃亏，预填阶段的注意力计算量降不下来，但换来了界与实现的一一对应。在分离式预填/解码部署里，这个选择直接影响预填实例的算力配比：保位置的压缩让预填更重、解码更轻，重排压缩反之，但后者失去了可离线标定的误差预算。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-18\">十八 · 规模上限：界在什么尺寸区间才有决策价值</h3>\n<p>界是保守的，保守性随规模放大而累积。第一项对丢弃集合 $$\\mathcal{D}$$ 求和，$$|\\mathcal{D}|$$ 随压缩率上升而增大，求和项数增多；第二项的 Frobenius 范数随 N·d 增长。当 N 很大（高分辨率图像、多帧视频、长文档多页），两项都变大，界与真实误差的间隙被拉开，界从“可用的预算工具”退化为“只保证不出事”的粗约束。此时按界选 M 会过度保守，显存节省被吃掉。反过来，N 很小时界相对紧，决策价值最高。规模上限因此不是某个固定 token 数，而是“界间隙相对于可接受误差预算的比例”——当间隙已经接近预算本身，界就不再提供有效分辨率。</p>\n<div class=\"formula\">$$\\text{决策有效性} \\;\\propto\\; \\frac{\\text{界}-\\text{真实误差}}{\\text{误差预算}}$$</div>\n<p>工程判断落在具体机制上：在目标域用小规模校准样本实测真实误差，与界对比得到间隙比例；间隙比例低于预算的一个可接受份额时，用界做容量规划；高于时，改用实测误差曲线做分段标定，界只作为安全兜底。对文档 OCR 这类细粒度定位任务，正确做法是把 M 的下限锁死在该域实测误差曲线的拐点之上，而不是让公式去推一个它推不准的数。压缩率的安全性最终取决于被丢 token 在跨模态注意力中的有效权重，而不是保留比例——这句话在规模放大时尤其成立，因为保留比例掩盖的正是 $$\\alpha_i$$ 的分布。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-19\">十九 · 边界不在公式里，而在 α_i 的来历与压缩发生的坐标上</h3>\n\n<p>这个界之所以能被工程使用，是因为它把误差拆成了两项可分别归因的量：第一项 <span>∑_{i∈D} α_i‖x_i−Π_K(x_i)‖₂</span> 度量被丢弃 token 在跨模态注意力加权下的 L2 泄漏，第二项 <span>(L_lip/2)‖C(X)−X‖²_F</span> 度量压缩算子对整矩阵的扰动能量经融合模块 Lipschitz 放大后的封顶。但两项的可用性并不对称。第二项在部署前可以用一次前向的 Frobenius 范数差与融合模块的谱范数上界估出来，属于“可离线算的保守量”；第一项则完全取决于 α_i 的估计质量——α_i 是经校准得到的注意力有效权重，它不是一个模型常量，而是输入的函数。因此这个界的真实适用边界，首先不是数学上的，而是校准集与目标域之间的分布距离边界。当目标域图像（文档 OCR 的密集小字、医学影像的微小病灶）使跨模态注意力集中在少数细粒度 patch 上时，这些 patch 的 α_i 在校准集上被系统性低估，第一项随之被低估，界看起来仍然安全，实际误差却已越界。工程判断应当是：把 α_i 当作域内标定量，而不是模型属性；换域即重标定，或对该域直接禁用激进压缩。</p>\n\n<p>第二个失效条件来自压缩发生的坐标。公式的推导把融合视为 Lipschitz 连续映射，把压缩误差分解为被丢 token 的投影残差与保留 token 的表示扰动，再用三角不等式合并——整条链条默认 X 与 C(X) 都是 L2 可度量的连续嵌入。一旦压缩发生在离散 token id 选择或低比特量化表示上，误差传播就不再是线性的：量化误差经过后续层会被非线性激活与注意力 softmax 重新整形，二次形式的平滑放大假设失效，界不再紧。此时按界设定的压缩率，实测误差会明显超出预算，而界本身不会报警。可操作的判据是看压缩算子输出的表示类型：若 C(X) 的元素仍是连续浮点嵌入，界可用；若 C(X) 已经过 codebook 映射或 FP4/FP8 量化再进入融合，则必须改用经验误差曲线标定，不能拿这个二次界做容量决策。</p>\n\n<p>第三个失效条件最容易被忽视：解耦假设。公式隐含压缩算子与后续 LLM 解码相互独立，压缩只改变视觉侧输入，不改变跨模态注意力的结构。但工程上常见的“合并后重排 token 顺序”“为省显存改写位置编码”恰恰破坏这一假设——位置偏置会引入一个界外的额外误差项，该项不在求和里，也不被 L_lip 封顶，因为它来自注意力打分函数本身的改变而非输入扰动。表现是：公式给出的上界仍然成立地“算得出来”，但它约束的已经不是实际系统，容量决策据此做出的 M 选择会偏乐观。判断方法很直接：只要压缩管线里存在 token 重排或位置编码改写，就必须在界外单独加一项位置偏置误差的经验估计，或干脆把重排从压缩算子中剥离、保持顺序不变。</p>\n\n<table class=\"mini\"><thead><tr><th>失效来源</th><th>界的哪一项失真</th><th>系统代价表现</th><th>工程处置</th></tr></thead><tbody><tr><td>α_i 外推到分布外域</td><td>第一项被低估</td><td>细粒度定位任务精度骤降，显存节省换来返工</td><td>目标域重校准或禁用激进压缩</td></tr><tr><td>离散 id / 低比特量化</td><td>二次界不再紧</td><td>实测误差超预算，吞吐提升被精度回退抵消</td><td>改用经验曲线，不按界定 M</td></tr><tr><td>token 重排 / 位置编码改写</td><td>出现界外项</td><td>上界失效但决策仍按它做，容量规划偏乐观</td><td>剥离重排，或单独估位置偏置项</td></tr></tbody></table>\n\n<p>把这三条放在一起看，规模上限的含义就清楚了：这个界能支撑的决策是“在已校准域内、连续嵌入坐标上、不重排顺序的前提下，为不同压缩率标定误差预算并选 M”，它不能支撑跨域外推、不能支撑量化后压缩率的选取、不能支撑带重排的管线。它的价值在于把“保留比例”这个误导性指标替换成“被丢 token 的有效注意力权重”这一真正决定成败的量；它的风险在于 α_i 与 L_lip 都是输入相关的量，离线固定一次就外推，等于把界当成了常数。部署前的正确动作是：先在目标域采样一小批代表性输入重估 α_i，检查第一项是否仍被第二项主导；若第一项已接近或超过预算，则压缩率的安全上限由被丢 token 的权重分布决定，而非由 M/N 决定。</p>\n<h3 id=\"th-visual-token-compress-error-sec-20\">二十 · 把误差界翻译成部署约束</h3>\n<p>这个界在纸面上是一个不等式，落到部署里必须变成一条可执行的约束：给定目标域、给定任务，选一个压缩率，使得上界不超过任务允许的输出偏差预算 <span>ε</span>。工程上把它写成可行性判据：</p>\n<div class=\"formula\">$$\\sum_{i\\in\\mathcal{D}} \\alpha_i \\left\\|x_i-\\Pi_{\\mathcal{K}}(x_i)\\right\\|_2 + \\frac{L_{\\mathrm{lip}}}{2}\\left\\|\\mathcal{C}(X)-X\\right\\|_F^2 \\;\\le\\; \\varepsilon_{\\mathrm{task}}$$</div>\n<p>这条判据的价值不在于它紧，而在于它可以在没有真实标签的情况下离线算出：<span>α_i</span> 来自校准集上的跨模态注意力统计，<span>\\(L_{\\mathrm{lip}}\\)</span> 来自融合模块权重的谱范数估计，<span>Π_K</span> 与 <span>C</span> 由压缩算子本身决定。于是压缩率的选择从\"试出来\"变成\"算出来再验证\"。代价在于这条判据是保守的：它把被丢 token 的泄漏按最坏情况线性相加，实际误差通常小于上界，因此按界卡出来的 M 往往比真正需要的保留数更大，显存与带宽的节省被打折。这个折扣是必要的保险费——尤其当 <span>α_i</span> 的估计本身带系统性低估时。</p>\n<p>关键在于 <span>ε_task</span> 不是一个全局常数。同一个模型，做图像描述时允许的输出偏差远大于做表格单元格定位时允许的偏差。因此容量决策的第一步不是选 M，而是按任务把 <span>ε_task</span> 分档，再对每一档反解 M。这一步做错，后面所有批大小与并行度的计算都建立在错误的保留 token 数上。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-21\">二十一 · 定 M：反解保留 token 数</h3>\n<p>反解 M 的做法是：把 <span>D</span> 取为按 <span>α_i·‖x_i−Π_K(x_i)‖₂</span> 排序后尾部的那批 token，逐步增大 M（即缩小 <span>D</span>），直到第一项降到预算的某个份额（例如 70%），剩余 30% 留给第二项的 Lipschitz 放大。这个份额划分不是随意的：第二项随整矩阵扰动能量二次增长，压缩算子越激进，<span>‖C(X)−X‖_F</span> 越大，二次项吃掉的预算比例上升，第一项的可分配份额必须相应收缩。</p>\n<p>一个具体算例：某 VLM 预填充阶段每张图产生 N=1024 个视觉 token，嵌入维度 d=1024，目标域为文档 OCR，<span>ε_task</span> 按该域校准集上的输出 L2 偏差定为 0.8（归一化单位）。校准得到 <span>L_lip</span> 的估计使第二项在 M=256 时约占预算的 0.22；第一项预算余下 0.58。按 <span>α_i</span> 排序后发现，被丢弃的 768 个 token 中，前 200 个的加权投影残差合计已达 0.51，再丢更多就超预算。于是 M 的下限落在 300 附近，而不是按\"保留 25%\"直觉得到的 256。差别看似只有 44 个 token，但在 KV 与带宽上会被放大：视觉 token 的 KV 占用与 M 成正比，M 从 256 抬到 300 意味着视觉侧 KV 显存上升约 17%，同时每张图的预填充计算量同比上升。这就是保守界的直接代价，也是为什么必须按域校准而不是按保留比例拍板。</p>\n<p>反过来，若目标域是开放域图像描述，<span>α_i</span> 分布更平坦、尾部更轻，同样的 <span>ε_task</span> 下 M 可以压到 200 以下，视觉 KV 显存与预填充算力同步下降。同一套压缩算子、同一个模型，两个域的 M 相差近一倍——这正是\"压缩率不能只看保留比例\"在容量规划上的具体表现。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-22\">二十二 · 定 KV 预算与批大小</h3>\n<p>M 一旦确定，视觉侧 KV 预算就有了硬输入。单请求视觉 KV 字节数为 <span>2·M·d·n_layer·b</span>（K 与 V 各一份，b 为每元素字节数），文本侧 KV 随生成长度动态增长。批大小 B 的可行域由下式约束：</p>\n<div class=\"formula\">$$B \\cdot \\left(\\,2 M d\\, n_{\\mathrm{layer}}\\, b \\;+\\; \\overline{S}_{\\mathrm{txt}}\\, \\kappa_{\\mathrm{txt}}\\right) \\;\\le\\; \\mathrm{KV}_{\\mathrm{pool}}$$</div>\n<p>其中 <span>S̄_txt</span> 是文本侧平均上下文长度，<span>κ_txt</span> 是文本每 token 的 KV 字节系数。注意 M 出现在线性项里，因此压缩率对批大小的影响是直接乘性的：M 从 1024 压到 300，视觉 KV 降到约 29%，在视觉占主导的多图请求里，B 可以近似按同比例放大。但这条放大只在视觉 KV 占主导时成立；当文本上下文很长（例如多轮对话叠加长文档），文本项成为主项，压缩视觉 token 对 B 的边际贡献迅速衰减。容量规划时必须先算出视觉项与文本项在总 KV 中的占比，再判断压缩是否值得作为扩容手段。</p>\n<p>这里有一个容易踩的坑：按界算出的 M 是\"误差可接受\"的下限，但 KV 池的分配粒度、页对齐、以及并行策略对每卡 KV 的分片方式，都会让实际可容纳的 B 小于理论值。工程上应把理论 B 乘以一个由分片碎片与预留空间决定的有效系数，再与 SLO 要求的并发数比对。若有效 B 仍低于并发需求，优先考虑提高压缩率（若目标域允许）而不是加卡——因为加卡改变的是并行度，不改变单请求的 KV 占用。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-23\">二十三 · 定并行度与 SLO 耦合</h3>\n<p>压缩误差界还间接约束并行度选择。张量并行把每层的 KV 与权重切分到多卡，单卡 KV 容量随之上升，可容纳更大的 B；但 TP 引入的集合通信在解码步上叠加固定时延，而解码步的时延预算由 SLO 的 TPOT 上限倒推。设单步计算时延为 <span>t_comp(B)</span>、通信时延为 <span>t_comm(TP)</span>，则 TPOT 约束为：</p>\n<div class=\"formula\">$$t_{\\mathrm{comp}}(B) + t_{\\mathrm{comm}}(\\mathrm{TP}) \\;\\le\\; \\mathrm{TPOT}_{\\max}$$</div>\n<p>压缩在这里的作用是双向的：减小 M 降低了预填充阶段的计算量与视觉 KV，使同样的 TP 度下能塞进更大的 B，从而摊薄通信开销；但若为了满足误差界而不得不保留较大的 M，预填充时延上升，可能迫使提高 TP 度来压单步时延，而更高的 TP 又抬高 <span>t_comm</span>，形成\"误差预算紧 → M 大 → 时延高 → TP 高 → 通信贵\"的链条。因此在 SLO 规划中，压缩率、M、TP 度、B 四者必须联立求解，不能各自独立优化。</p>\n<p>具体做法：以目标域的 <span>ε_task</span> 反解出 M 的可行区间，取区间上界（最保守）与下界（最激进）分别代入 KV 与预填充时延模型，得到两组 (B, TP) 可行解；再检查两组解是否都满足 TPOT 与 TTFT 的 SLO。若只有保守组满足，说明该域的误差预算不允许激进压缩，容量规划应按大 M 做；若两组都满足，则可以取激进组换取更高吞吐，但必须保留按域重新校准 <span>α_i</span> 的回退开关。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-24\">二十四 · 校准集外推的风险如何进入决策</h3>\n<p>上述所有计算都依赖 <span>α_i</span> 的估计，而 <span>α_i</span> 是输入相关的。用固定校准集估出的 <span>α_i</span> 在分布外图像上会低估被丢 token 的有效权重，导致按界算出的 M 偏小、实际误差超出预算且无法提前预警。工程上不能假设校准集覆盖目标域，必须把这一风险显式写进决策：</p>\n<ul>\n<li>按域分桶校准：为文档 OCR、医学影像等细粒度域单独估计 <span>α_i</span> 分布，不与开放域共用一套权重；跨域请求走各自的 M。</li>\n<li>在线哨兵：在解码输出上挂一个轻量的偏差探针（例如与未压缩路径的抽样比对），一旦超出预算即触发该请求回退到更大 M 或禁用压缩；哨兵本身的算力开销要计入 SLO 预算。</li>\n<li>保守裕度：对无法确认域归属的请求，按最细粒度域的 <span>α_i</span> 上界取 M，牺牲吞吐换稳定。</li>\n</ul>\n<p>这三条都增加成本：分桶校准需要额外的离线标定与存储，在线哨兵占用解码算力并增加尾延迟，保守裕度直接压低 B。但它们把\"高压缩率在目标域突然失效\"这一不可预警的失败模式，转化为可预算的容量折损。对 SLO 敏感的生产系统，这个交换通常是值得的；对离线批处理，可以只保留分桶校准而省掉哨兵。</p>\n<p>最后一条工程判断：当压缩发生在低比特量化表示或离散 token id 上时，二次界不再紧，按界设定的压缩率实际误差可能远超预算。此时不应把该界当作容量决策的唯一依据，而应把它降级为排序工具——用它比较不同压缩算子在同一域上的相对保守程度，绝对 M 则靠目标域的小规模实测确定。界的正确用法是缩小搜索空间，不是替代验证。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-25\">二十五 · 把误差界折进容量账本：批大小、并行度与 KV 预算的定法</h3>\n\n<p>这个界在工程上不是拿来做精确预测的，而是拿来做<strong>预算切分</strong>的。做法是把界右端当作一个可分配的误差预算 <code>E_budget</code>，再把它拆成两笔账：一笔给被丢弃 token 的加权泄漏 <code>E_drop = Σ_{i∈D} α_i·‖x_i − Π_K(x_i)‖₂</code>，一笔给压缩算子整体扰动 <code>E_lip = (L_lip/2)·‖C(X) − X‖²_F</code>。定容量时先固定 <code>E_budget</code>（由任务精度要求倒推，例如细粒度定位任务给得紧、粗粒度检索给得松），然后反解 <code>M</code>：由于 <code>E_drop</code> 随 <code>M</code> 减小而单调上升，<code>M</code> 的下界就是让 <code>E_drop + E_lip ≤ E_budget</code> 成立的最小保留数。这一步必须在目标域校准集上做，因为 <code>α_i</code> 是输入相关的——同一张图在 OCR 域里表格线的 token 权重远高于自然图像里的背景 token，用自然图像校准出来的 <code>α_i</code> 去定 OCR 的 <code>M</code>，会把 <code>E_drop</code> 低估到预算之外。</p>\n\n<p>批大小与并行度的定法要顺着这个 <code>M</code> 往下推。视觉 token 数从 <code>N</code> 压到 <code>M</code> 后，每请求的视觉侧显存与预填算力大致按 <code>M/N</code> 缩放，但误差界并不随 <code>M/N</code> 线性放松——第一项里 <code>α_i</code> 的分布决定了曲线的拐点：当 <code>M</code> 降到某个阈值以下，被丢集合 <code>D</code> 开始包含高 <code>α_i</code> 的 token，<code>E_drop</code> 陡增，此时再靠增大批大小摊薄单请求成本就失去意义，因为精度预算已经被击穿。工程判断是：把 <code>M</code> 钉在拐点之上，用批大小去吃吞吐，而不是用压缩率去吃吞吐。并行度方面，<code>M</code> 变小会让单请求的视觉侧张量变窄，张量并行在视觉编码器上的收益随之下降，切分点应更多落在 LLM 解码侧；而 <code>E_lip</code> 项与并行度无关，它只随压缩算子的扰动能量走，所以跨设备切分压缩算子（例如把 token 合并分散到多卡）不会改变界，却会引入额外的通信与同步代价，属于纯系统开销。</p>\n\n<p>KV 预算的定法要区分视觉 token 与文本 token 的账。压缩后的 <code>M</code> 个视觉 token 进入跨模态注意力后占据的 KV 槽位按 <code>M</code> 计，但误差界提醒：<code>M</code> 不能只为省 KV 而压。设单请求 KV 预算为 <code>B_kv</code>，文本侧占用 <code>B_txt</code>，则视觉侧可用 <code>B_vis = B_kv − B_txt</code>，对应 <code>M ≤ B_vis / s</code>（<code>s</code> 为每 token KV 字节数）。这个上界与误差界给出的下界 <code>M_min</code> 之间必须留出可行区间；若 <code>B_vis/s &lt; M_min</code>，说明该 SLO 下这个压缩方案不可行，要么放宽精度预算、要么改用不丢 token 的合并式压缩（让 <code>D</code> 为空、只留 <code>E_lip</code> 项）、要么把长文档拆成多请求。SLO 层面，<code>E_budget</code> 应与首 token 延迟和吞吐目标一起进容量表，形成三维约束：延迟压 <code>M</code> 上限（预填变短），吞吐抬批大小，精度压 <code>M</code> 下限。三者冲突时，优先保 <code>M_min</code>，因为界失效的代价是任务级错误而非性能退化。</p>\n\n<table class=\"mini\"><thead><tr><th>决策量</th><th>由界导出的约束</th><th>系统代价</th></tr></thead><tbody><tr><td>保留数 M</td><td>M ≥ M_min，使 E_drop+E_lip ≤ E_budget</td><td>M 越小预填越短、KV 越省，但过拐点后精度陡降</td></tr><tr><td>批大小</td><td>在 M 固定于拐点之上后放大</td><td>吞吐上升，单请求视觉显存按 M/N 缩放</td></tr><tr><td>并行度</td><td>视觉侧切分收益随 M 变窄而下降</td><td>切分压缩算子只增通信，不改界</td></tr><tr><td>KV 预算</td><td>B_vis/s ≥ M_min 才可行</td><td>不足则需拆请求或改合并式压缩</td></tr></tbody></table>\n\n<p>算例：某文档 OCR 服务，单请求 <code>B_kv</code> 给定、文本侧占用固定，视觉侧只剩能放 <code>M = 256</code> 个 token 的槽位；用自然图像校准集估出的 <code>α_i</code> 显示 256 已满足 <code>E_budget</code>，但换到目标域校准后发现表格线 token 的 <code>α_i</code> 被低估，实际 <code>E_drop</code> 超预算，<code>M_min</code> 抬到 512，此时 <code>B_vis/s &lt; M_min</code>，方案不可行——正确处置不是硬压到 256，而是对该域禁用激进压缩、改用合并式压缩把 <code>D</code> 清空，只承担 <code>E_lip</code>，代价是 KV 占用回升、批大小下调、吞吐下降。这条路径的边界很硬：界只对 L2 可度量的连续嵌入成立，若压缩发生在量化后的低比特表示或离散 token id 上，二次项不再紧，按界定的 <code>M</code> 会系统性偏乐观；若压缩后重排了 token 顺序或改写位置编码，位置偏置引入界外误差项，公式上界失效而容量表仍按它排——这类失效不会在压测里以延迟或吞吐的形式暴露，只会以目标域任务错误率的形式出现，因此校准必须绑定目标域，且每次更换压缩算子或位置编码方案都要重标 <code>α_i</code> 与 <code>L_lip</code>。</p>\n<h3 id=\"th-visual-token-compress-error-sec-26\">二十六 · 误用的共同形状：把校准量当成常量</h3>\n<p>这个界在工程上被误用，几乎都源于同一个动作：把界里两个依赖输入的标量——注意力有效权重 α_i 与 Lipschitz 常数 L_lip——当成部署前一次性标定好的常量，然后拿它去做跨域、跨压缩算子、跨表示精度的容量决策。界本身没错，错的是把\"在某校准集上估计出的 α_i\"当成\"任意输入下的 α_i\"。前文已经给出推导与适用边界，这里只处理误用形态、后果与识别手段。</p>\n<p>把界写成决策形式会更清楚它被误用的位置。工程上真正被使用的是反解出来的压缩率约束：</p>\n<div class=\"formula\">$$M \\;=\\; \\max\\left\\{\\,m \\;\\middle|\\; \\sum_{i\\in\\mathcal{D}_m}\\hat{\\alpha}_i\\,\\|x_i-\\Pi_{\\mathcal{K}}(x_i)\\|_2 \\;+\\; \\frac{\\hat{L}_{\\mathrm{lip}}}{2}\\|\\mathcal{C}(X)-X\\|_F^2 \\;\\le\\; \\epsilon_{\\mathrm{budget}}\\,\\right\\}$$</div>\n<p>其中带帽的量是校准估计值，ε_budget 是任务允许的输出偏差预算。误用的本质是：左边两项在目标域的真实值远大于带帽估计值，而工程侧仍按这个 M 分配显存与带宽。注意这个反解式里没有任何一项能自我纠错——界是保守上界，一旦估计偏低，它就变成了乐观下界，而系统没有任何在线信号能发现这一点。</p>\n<p>识别这类误用的第一个信号是\"预算与任务粒度不匹配\"。细粒度定位任务（文档 OCR 的行级框、医学影像的病灶边界）对单个被丢 token 的敏感度远高于图像描述类任务，因为它们的输出直接依赖被丢 token 的空间位置信息。若容量规划里 ε_budget 是从图像描述类校准集上反推的，那么它在 OCR 上必然偏松。第二个信号是压缩率与保留比例脱钩：当压缩算子从\"按注意力分数 top-k 保留\"换成\"局部窗口合并\"时，被丢集合 D 的构成完全改变，α_i 的分布也随之改变，而 M 却没变。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-27\">二十七 · 反例：固定校准集外推到文档 OCR</h3>\n<p>构造一个具体的反例。设某 VLM 在自然图像校准集上标定：压缩算子为按跨模态注意力分数保留 top-M 的视觉 token，校准得到的 α_i 在自然图像上高度集中于少数显著物体对应的 token，被丢 token 的 α_i 普遍很小，于是第一项 Σ_{i∈D} α_i‖x_i−Π_K(x_i)‖_2 在校准集上被压得很低，反解出的安全压缩率很高，工程侧据此把 M 定得很小以节省 KV cache 与预填带宽。</p>\n<p>把同一套 M 与同一套 α_i 用到文档 OCR 输入上，失效链条是这样的：文档图像的视觉 token 在空间上高度均匀，每一行文字、每一个表格线都携带独立的字符信息，跨模态注意力在解码每个字符时会把权重分散到该字符所在的一小片 token 上，而不是集中在少数显著区域。于是被丢弃集合 D 中大量 token 的真实 α_i 远高于校准估计值，第一项被严重低估；同时文档图像的压缩算子若采用窗口合并，合并后的 token 表示扰动 ‖C(X)−X‖_F 也更大，第二项同步上升。两项同时被低估，界给出的 ε 与真实偏差之间出现数量级差距，表现为行级识别错误率在某个压缩率阈值处突然跳升——不是渐变，而是跳变，因为字符级信息一旦被合并就不可恢复。</p>\n<p>这个反例的工程代价是可量化的：预填阶段视觉 token 数从 N 降到 M 节省的显存与带宽是线性的，但解码阶段因 OCR 输出变长、重试与后处理校正带来的额外解码步数是超线性的；在分离式预填/解码部署里，预填侧省下的带宽会被解码侧因错误重试拉长的 KV 驻留时间抵消，端到端吞吐反而下降。更麻烦的是这种下降在压测里不出现——压测用的校准集正是自然图像。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-28\">二十八 · 第二类误用：在低比特与离散表示上套二次界</h3>\n<p>第二项 L_lip/2·‖C(X)−X‖_F² 的二次形式成立的前提是融合模块对视觉输入 Lipschitz 连续且扰动连续可度量。当压缩发生在量化后的低比特表示（NVFP4/FP8 的视觉侧激活）或离散 token id 上时，误差传播不再满足这个二次关系：量化误差经过非线性激活与注意力 softmax 后被重新分配，小的表示扰动可能被放大成大的输出翻转，也可能被量化格点吸收而消失。此时按二次界反解出的压缩率会把预算算得过于宽松，因为二次项在小扰动下增长慢，而真实的量化-压缩耦合误差增长更快。</p>\n<p>识别手段是检查压缩算子作用点的表示类型。若压缩发生在连续嵌入上（合并、投影、池化），二次界可用；若压缩发生在已经量化或离散化的 token 上，界只能作为方向性参考，不能进入容量反解式。工程判断是：在低比特视觉通路上，压缩率应由目标域上的端到端误差扫描确定，而不是由解析界反解。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-29\">二十九 · 第三类误用：重排位置编码后仍沿用原界</h3>\n<p>公式的推导假设压缩算子与后续 LLM 解码解耦，即压缩只改变 token 内容、不改变跨模态注意力的位置结构。一旦压缩后对保留 token 重排顺序或改写位置编码（例如把二维视觉 token 压成一维序列后重新编号），跨模态注意力的位置偏置会引入一个界外误差项，这一项不在 Σ_{i∈D} α_i‖·‖ 与 L_lip 项之内。工程上仍按原界做容量决策，就会出现\"界满足但输出错位\"的现象：模型能认出文字内容，但行序、表格结构、空间关系错乱，而误差范数指标看起来仍在预算内。</p>\n<p>识别这类误用的方法是把位置一致性作为独立检查项：压缩前后对同一批 token 做位置敏感探针（例如询问相对位置、计数、表格行列），若探针误差与范数误差不同步上升，说明位置偏置项已经主导，原界失效。此时要么在压缩算子中保留位置编码映射，要么把位置误差单独计入预算。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-30\">三十 · 工程上的识别清单与处置</h3>\n<p>把上述三类误用收敛成可执行的检查清单，每条对应一个具体机制与一个代价判断：</p>\n<ul>\n<li>域一致性检查：校准集与目标域的注意力权重分布是否同形。用目标域少量样本重估 α_i，若重估后反解出的 M 显著小于当前部署值，说明原 M 是乐观的。代价：重校准需要目标域标注或至少无标注探针，但远小于线上失效后的回滚成本。</li>\n<li>表示类型检查：压缩作用点是否为连续嵌入。低比特或离散通路上禁用解析界反解，改用端到端扫描。代价：扫描需要额外的离线推理预算。</li>\n<li>位置结构检查：压缩是否重排顺序或改写位置编码。若是，把位置误差单列预算，不并入 L2 界。代价：位置探针增加评测工作量，但能提前暴露结构性错位。</li>\n<li>压缩算子族一致性：更换算子（top-k 保留 → 窗口合并 → 投影池化）后必须重估 α_i 与 ‖C(X)−X‖_F 的分布，不能沿用旧 M。代价：每次算子迭代都要重跑标定，属于常规工程开销。</li>\n</ul>\n<p>最后落到一个工程判断上：这个界在容量决策中的正确用法是\"在目标域上标定、在连续嵌入上使用、在位置结构不变时反解\"，三者缺一，界就从保守上界退化为乐观下界。真正稳健的做法是把界当作压缩率的上限护栏而非精确预算器——先用界圈定一个不可能安全的压缩率区间，再在区间内用目标域端到端扫描确定实际 M，把显存与带宽的折中点放在扫描结果上，而不是放在反解式的输出上。</p>\n\n<h3 id=\"th-visual-token-compress-error-sec-31\">三十一 · 误用与反例：当误差界变成容量决策的假依据</h3>\n<p>最常见的误用不是把公式算错，而是把 <span class=\"sym\">α_i</span> 当成模型的固有属性。校准集上估计出的注意力权重只对那一批图像分布成立：文档 OCR 里一个页眉 token 可能承载整行文字的定位信息，医学影像里一个边缘 token 可能对应病灶边界，这些 token 在自然图像校准集上的 <span class=\"sym\">α_i</span> 接近零，于是压缩算子放心地把它们合并掉。工程上的后果是容量规划直接失真——按校准集界标定出的最大压缩率被写进部署配置，显存与带宽预算按这个 M 值切分，上线后遇到目标域图像，被丢 token 的加权投影误差项 <span class=\"sym\">∑_{i∈D} α_i‖x_i−Π_K(x_i)‖₂</span> 突然放大，输出偏差越过 SLO，而系统没有任何前置信号，因为界本身在离线阶段是“满足”的。识别方法很直接：对目标域抽样一批输入，重算 <span class=\"sym\">α_i</span> 的分布并与校准集比对，若目标域的注意力质量集中在少数被丢弃索引上，就说明该压缩率不可外推；此时要么在目标域重新校准，要么对该域禁用激进压缩，把 M 抬回安全区。</p>\n<p>第二个反例发生在量化表示上。界的第一项依赖 L2 可度量的连续嵌入，第二项 <span class=\"sym\">(L_lip/2)‖C(X)−X‖_F²</span> 的二次形式成立的前提是压缩扰动足够小、融合模块近似线性放大。一旦压缩发生在低比特量化后的表示或离散 token id 上，误差传播经过舍入与查表，是非线性的，二次界不再紧——按界算出的误差预算看起来宽松，实际误差远超预算。系统代价体现在两个方向：为了守住界而过度保守地保留 token，显存与 KV cache 带宽白花；或者按界激进压缩，解码阶段出现成片的语义漂移，而吞吐收益被重试与回退吃掉。工程判断是：在 NVFP4/FP8 视觉前端做压缩时，不要拿连续嵌入的界直接换算成低比特配置的压缩率，应把量化噪声单独作为一项扰动预算计入，并对量化后的压缩路径做端到端偏差抽检，而不是只信离线界。</p>\n<p>第三个失效条件是解耦假设被打破。界假设压缩算子 <span class=\"sym\">C</span> 与后续 LLM 解码解耦，压缩只改变 token 内容、不改变其顺序与位置语义。但工程实现里为了凑齐 M 个 token，常伴随重排、按显著性排序或改写位置编码，跨模态注意力的位置偏置会引入界外的额外误差项，公式给出的上界失效，而容量决策仍按它做。这类误用最难识别，因为偏差不体现在单 token 的 L2 距离上，而体现在需要空间顺序的任务里——细粒度定位、表格结构还原、多页文档的阅读顺序。识别手段是把位置扰动作为独立变量做消融：固定 M 与压缩算子，只切换是否重排，观察下游定位指标的变化；若重排带来的退化与压缩本身同量级，就说明位置偏置项不可忽略，界不能单独用于定 M。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>失效机制</th><th>系统代价</th><th>识别信号</th></tr></thead><tbody><tr><td>校准集 α_i 外推</td><td>目标域被丢 token 有效权重被低估</td><td>显存/带宽按错误 M 切分，SLO 越界无预警</td><td>目标域注意力质量集中于被丢索引</td></tr><tr><td>低比特/离散表示套用二次界</td><td>误差传播非线性，界不紧</td><td>过度保留浪费带宽，或激进压缩引发解码漂移</td><td>离线界宽松但端到端偏差抽检超标</td></tr><tr><td>压缩后重排/改位置编码</td><td>位置偏置引入界外误差项</td><td>定位类任务退化，容量决策失真</td><td>仅切换重排即出现同量级退化</td></tr></tbody></table>\n<p>把这三类误用放在一起看，共同点是界被当成了与输入分布无关的常数。实际上 <span class=\"sym\">α_i</span> 与 <span class=\"sym\">L_lip</span> 都依赖具体输入，无法离线精确估计，界只能作为部署前的保守标定工具，不能替代目标域的在线抽检。真正稳的做法是把界拆成可复算的分项：在目标域上重估 <span class=\"sym\">α_i</span>、把量化噪声单列、把位置扰动单列，三项各自设预算，再决定 M 与显存/带宽的折中点；任何一项在目标域上无法被界覆盖时，压缩率就必须回退，而不是继续按离线界推进。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>X</td><td>原始视觉 token 序列（N×d 矩阵）</td></tr><tr><td>\\mathcal{C}(X)</td><td>压缩/合并后的视觉 token 序列（M×d）</td></tr><tr><td>\\mathcal{D}</td><td>被丢弃或合并的 token 索引集合</td></tr><tr><td>\\alpha_i</td><td>第 i 个视觉 token 在跨模态注意力中的有效权重（经校准估计）</td></tr><tr><td>\\Pi_{\\mathcal{K}}</td><td>向保留 token 子空间 K 的投影算子</td></tr><tr><td>L_{\\mathrm{lip}}</td><td>VLM 融合模块对视觉输入的 Lipschitz 常数</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-visual-token-compress-error · 共 5 个片段</p>\n"},{"id":"th-multimodal-prefill-decode-split","title":"多模态预填/解码分离时延","direction":"dir-visual-token-compression","prereq":[],"plain":"多模态请求的端到端时延由视觉编码+预填阶段与自回归解码阶段串行叠加，分离部署后两阶段可在不同 GPU 池并行，但 KV cache 跨池传输与视觉 token 膨胀会引入额外带宽项；该模型用于决定视觉编码器与 LLM 解码器是否应分池、以及图像 token 压缩比该压到多少才能满足 SLO。","definition":"多模态请求的端到端时延由视觉编码+预填阶段与自回归解码阶段串行叠加，分离部署后两阶段可在不同 GPU 池并行，但 KV cache 跨池传输与视觉 token 膨胀会引入额外带宽项；该模型用于决定视觉编码器与 LLM 解码器是否应分池、以及图像 token 压缩比该压到多少才能满足 SLO。","formula":"$$T_{\\mathrm{e2e}} \\;=\\; \\underbrace{\\frac{N_{\\mathrm{vis}}\\,d\\,L_{\\mathrm{vis}}}{F_{\\mathrm{vis}}\\,\\eta}}_{\\text{视觉编码}} \\;+\\; \\underbrace{\\frac{(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\,P_{\\mathrm{llm}}}{F_{\\mathrm{llm}}\\,\\eta}}_{\\text{多模态预填}} \\;+\\; \\underbrace{\\frac{S_{\\mathrm{kv}}\\,B_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}}_{\\text{KV 跨池传输}} \\;+\\; \\underbrace{N_{\\mathrm{out}}\\cdot t_{\\mathrm{dec}}(B)}_{\\text{自回归解码}}$$","variables":[{"sym":"N_{\\mathrm{vis}}","meaning":"每请求视觉 token 数（压缩后）"},{"sym":"N_{\\mathrm{txt}}","meaning":"每请求文本 prompt token 数"},{"sym":"N_{\\mathrm{out}}","meaning":"生成输出 token 数"},{"sym":"S_{\\mathrm{kv}}","meaning":"每 token 的 KV cache 字节数（含 KV 头数与层数）"},{"sym":"B_{\\mathrm{kv}}","meaning":"跨池传输的 KV 块数"},{"sym":"\\mathrm{BW}_{\\mathrm{link}}","meaning":"prefill 池与 decode 池之间的互联带宽（NVLink 或 RDMA）"},{"sym":"t_{\\mathrm{dec}}(B)","meaning":"批大小为 B 时单步解码时延"}],"derivation":"第二项 $$\\frac{(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\,P_{\\mathrm{llm}}}{F_{\\mathrm{llm}}\\,\\eta}$$ 把视觉 token 与文本 prompt token 合并计入预填长度：$P_{\\mathrm{llm}}$ 为每 token 预填计算量，$F_{\\mathrm{llm}}$ 为 LLM 池算力；关键含义是视觉 token 压缩比直接线性缩放预填时间，压缩比每降一半，预填项近似减半。","example":"第四项 $$N_{\\mathrm{out}}\\cdot t_{\\mathrm{dec}}(B)$$ 中 $N_{\\mathrm{out}}$ 为生成输出 token 数，$t_{\\mathrm{dec}}(B)$ 为批大小 $B$ 时单步解码时延；解码项与批大小强相关，分池后解码池可独立加大 $B$ 提升吞吐，但单步时延随 $B$ 上升，需在 SLO 约束下选批大小。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["假设预填与解码完全串行、无 chunked prefill 重叠；实际框架中 continuous batching 会让解码 token 与后续请求的预填交错，该串行模型会高估时延。","KV 跨池传输项仅在分离式部署（prefill 池与 decode 池物理分离）时存在；同池部署时该项为零，但解码阶段会受预填请求的显存与算力争抢，需改用排队模型。","未建模视觉编码器与 LLM 预填之间的流水并行；当视觉编码器被切分到多卡时，编码阶段内部还存在集合通信时延，需叠加通信下界项。"],"system_note":"适用边界：该式假设预填与解码完全串行、无 chunked prefill 重叠，且未建模视觉编码器与 LLM 预填间的流水并行；实际 continuous batching 会让解码 token 与后续请求预填交错，串行模型会高估时延；同池部署时传输项为零，但解码会受预填请求的显存与算力争抢，应改用排队模型。","papers":["paper-an-image-is-worth-16x16-words-transf-2020"],"facts":["直觉：多模态请求的端到端时延是视觉编码、多模态预填、KV 跨池传输、自回归解码四项的串行叠加；分离部署让预填池与解码池各自独立扩缩容，但跨池 KV 传输与视觉 token 膨胀会新增带宽项，因此该式用于判断视觉编码器与 LLM 解码器是否值得分池。","公式第一项 $$\\frac{N_{\\mathrm{vis}}\\,d\\,L_{\\mathrm{vis}}}{F_{\\mathrm{vis}}\\,\\eta}$$ 中，$N_{\\mathrm{vis}}$ 是压缩后每请求视觉 token 数，$d$ 为视觉编码器隐藏维，$L_{\\mathrm{vis}}$ 为编码器层数，$F_{\\mathrm{vis}}$ 为视觉池算力，$\\eta$ 为算力利用率；分子是视觉编码所需的总乘加量级，分母是有效算力，比值即编码墙钟时间。","第二项 $$\\frac{(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\,P_{\\mathrm{llm}}}{F_{\\mathrm{llm}}\\,\\eta}$$ 把视觉 token 与文本 prompt token 合并计入预填长度：$P_{\\mathrm{llm}}$ 为每 token 预填计算量，$F_{\\mathrm{llm}}$ 为 LLM 池算力；关键含义是视觉 token 压缩比直接线性缩放预填时间，压缩比每降一半，预填项近似减半。","第三项 $$\\frac{S_{\\mathrm{kv}}\\,B_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}$$ 只在物理分离部署时非零：$S_{\\mathrm{kv}}$ 是每 token KV cache 字节数（含 KV 头数与层数），$B_{\\mathrm{kv}}$ 是需跨池搬运的 KV 块数，$\\mathrm{BW}_{\\mathrm{link}}$ 为 NVLink 或 RDMA 互联带宽；该项是分池决策的隐性成本，视觉 token 越多、$S_{\\mathrm{kv}}$ 越大，传输项越可能吃掉分池收益。","第四项 $$N_{\\mathrm{out}}\\cdot t_{\\mathrm{dec}}(B)$$ 中 $N_{\\mathrm{out}}$ 为生成输出 token 数，$t_{\\mathrm{dec}}(B)$ 为批大小 $B$ 时单步解码时延；解码项与批大小强相关，分池后解码池可独立加大 $B$ 提升吞吐，但单步时延随 $B$ 上升，需在 SLO 约束下选批大小。","适用边界：该式假设预填与解码完全串行、无 chunked prefill 重叠，且未建模视觉编码器与 LLM 预填间的流水并行；实际 continuous batching 会让解码 token 与后续请求预填交错，串行模型会高估时延；同池部署时传输项为零，但解码会受预填请求的显存与算力争抢，应改用排队模型。","用途：给定 SLO 与各池算力，可反解出满足时延的最大 $N_{\\mathrm{vis}}$，即视觉 token 压缩比下限；也可比较分池与同池两种拓扑的 $T_{\\mathrm{e2e}}$，若传输项超过分池带来的解码批处理收益，则不应分池。","误用：把该式当作精确预测器而不校正 continuous batching 重叠，会系统性高估时延、误判分池必要；或在视觉编码器多卡切分时忽略集合通信下界项，低估编码阶段时延。"],"anchors":[],"pitfalls":["把串行叠加模型直接用于 continuous batching 生产环境，未扣除预填与解码重叠，导致 SLO 评估偏保守、错误扩容解码池。","分池时只算解码池吞吐收益，忽略 KV 跨池传输项随视觉 token 数与 KV 头数线性增长，结果带宽成为瓶颈、端到端时延反超同池部署。","视觉编码器切分到多卡后仍按单卡 $F_{\\mathrm{vis}}$ 估算编码时间，漏掉集合通信下界，编码阶段实际时延被低估。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-1\">一 · 一句话直觉与它的工程含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-2\">二 · 为什么需要这个模型：分池决策没有第二条可算的路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-3\">三 · 常见误解之一：把串行叠加当成精确预测器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-4\">四 · 常见误解之二：分池只看解码吞吐收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-5\">五 · 适用边界与决策流程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-6\">六 · 串行叠加模型的适用边界与三类失效路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-7\">七 · 视觉编码项的分子结构与推导起点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-8\">八 · 多模态预填项的线性缩放与合并假设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-9\">九 · KV 跨池传输项：分池决策的隐性成本与离散化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-10\">十 · 解码项与批大小的耦合：$t_{\\mathrm{dec}}(B)$ 的非线性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-11\">十一 · 串行叠加的失效边界与反解压缩比下限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-12\">十二 · 串行叠加式的适用边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-13\">十三 · 串行假设的成立条件与重叠修正</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-14\">十四 · 传输项非零的边界：物理分离才计费</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-15\">十五 · 视觉编码多卡切分时漏掉的通信项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-16\">十六 · 反解压缩比下限时的假设脆弱性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-17\">十七 · 规模上限：批大小与池容量的饱和点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-18\">十八 · 失效条件的工程清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-19\">十九 · 边界条件：串行假设、传输项与多卡切分的三重失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-20\">二十 · 从公式到决策变量：把四项拆成四个可调的旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-21\">二十一 · 定批大小：用解码项反解 $B$ 的上界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-22\">二十二 · 定并行度：分池拓扑的比较判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-23\">二十三 · 定 KV 预算：显存约束与传输块数的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-24\">二十四 · 定 SLO 与算例：反解压缩比下限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-25\">二十五 · 反解压缩比与分池判据：公式在容量决策中的三个用法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-26\">二十六 · 误用一：把串行式当预测器，忽略 continuous batching 重叠</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-27\">二十七 · 误用二：分池只算解码收益，漏掉 KV 传输项的增长阶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-28\">二十八 · 误用三：视觉编码器多卡切分仍按单卡算力估算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-29\">二十九 · 反例：一次把串行式当精确预测器的分池扩容</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-30\">三十 · 识别清单：把误用挡在决策之前</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-prefill-decode-split-sec-31\">三十一 · 把串行式当预言机：三类误用与一个带宽反例</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:591px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 591.3 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"509.3\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"509.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：多模态请求的端到端时延由视觉编码+预填阶段与自回归解码阶段串行叠加…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"509.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$T_{\\mathrm{e2e}} \\;=\\; \\underbr…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"509.3\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：假设预填与解码完全串行、无 chunked prefill 重叠；…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-multimodal-prefill-decode-split-sec-1\">一 · 一句话直觉与它的工程含义</h3>\n<p>多模态请求的端到端时延，是一条由四段墙钟时间首尾相接组成的链：视觉编码器把图像压成 token 序列，LLM 预填把这些 token 连同文本 prompt 一次性吃进并生成 KV cache，若预填池与解码池物理分离则 KV 块要跨池搬运，最后解码器自回归吐出输出 token。写成一行就是 <span class=\"formula-inline\">$T_{\\mathrm{e2e}} = T_{\\mathrm{vis}} + T_{\\mathrm{prefill}} + T_{\\mathrm{kv\\_xfer}} + T_{\\mathrm{dec}}$</span>。这句话的工程价值不在于“四段相加”这个显然的事实，而在于四项的量纲各不相同：前两项是算力受限（FLOPs / 有效算力），第三项是带宽受限（字节 / 互联带宽），第四项是批大小与显存带宽共同决定的解码步数乘以单步时延。分离式部署改变的不是这四项的存在性，而是它们的系数——它把前两项挪到独立扩缩容的池子里，同时把第三项从零变成非零。因此“要不要分池”本质上是一道比较题：分池带来的解码批处理收益，是否大于新增的跨池传输项加上视觉 token 膨胀带来的预填项增长。</p>\n<p>严格定义如下。给定一个多模态请求，记压缩后视觉 token 数为 <span class=\"formula-inline\">$N_{\\mathrm{vis}}$</span>、文本 prompt token 数为 <span class=\"formula-inline\">$N_{\\mathrm{txt}}$</span>、输出 token 数为 <span class=\"formula-inline\">$N_{\\mathrm{out}}$</span>，则端到端时延模型为：</p>\n<div class=\"formula\">$$T_{\\mathrm{e2e}} \\;=\\; \\underbrace{\\frac{N_{\\mathrm{vis}}\\,d\\,L_{\\mathrm{vis}}}{F_{\\mathrm{vis}}\\,\\eta}}_{\\text{视觉编码}} \\;+\\; \\underbrace{\\frac{(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\,P_{\\mathrm{llm}}}{F_{\\mathrm{llm}}\\,\\eta}}_{\\text{多模态预填}} \\;+\\; \\underbrace{\\frac{S_{\\mathrm{kv}}\\,B_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}}_{\\text{KV 跨池传输}} \\;+\\; \\underbrace{N_{\\mathrm{out}}\\cdot t_{\\mathrm{dec}}(B)}_{\\text{自回归解码}}$$</div>\n<p>四项的分子分母各自对应一个物理资源：第一项分子 <span class=\"formula-inline\">$N_{\\mathrm{vis}} d L_{\\mathrm{vis}}$</span> 是视觉编码器的总乘加量级，分母 <span class=\"formula-inline\">$F_{\\mathrm{vis}}\\eta$</span> 是视觉池的有效算力；第二项把视觉 token 与文本 token 合并成预填长度，乘以每 token 预填计算量 <span class=\"formula-inline\">$P_{\\mathrm{llm}}$</span>，除以 LLM 池有效算力；第三项是 KV 字节总量除以互联带宽；第四项是输出长度乘以批大小 <span class=\"formula-inline\">$B$</span> 下的单步解码时延。注意第二项里 <span class=\"formula-inline\">$N_{\\mathrm{vis}}$</span> 与 <span class=\"formula-inline\">$N_{\\mathrm{txt}}$</span> 是相加关系而非并列，这意味着视觉 token 压缩比直接线性缩放预填时间——压缩比每降一半，预填项近似减半，这是该式最容易被低估的一条杠杆。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-2\">二 · 为什么需要这个模型：分池决策没有第二条可算的路</h3>\n<p>多模态推理的负载结构与纯文本推理有本质差异：视觉编码是“每请求一次性的重计算”，预填是“一次性的大矩阵乘”，解码是“每 token 一次的显存带宽受限小步”。这三段对硬件的要求互相冲突——视觉编码器偏好高算力低显存占用，解码偏好大显存带宽与大批大小，预填偏好高算力与长序列。同池部署时，一个长视觉序列的预填会把解码请求的显存与算力挤占，表现为解码 token 间隔抖动；分池部署则让两类资源各自独立扩缩容。但没有免费的分池：KV cache 必须从预填池搬到解码池，而多模态请求的 KV 体积被视觉 token 数直接放大。于是工程上必须回答两个定量问题：视觉编码器与 LLM 解码器是否值得分池？图像 token 压缩比该压到多少才能满足 SLO？</p>\n<p>该式的用途正是反解这两个问题。给定 SLO 上限 <span class=\"formula-inline\">$T_{\\mathrm{SLO}}$</span> 与各池算力，把不等式 <span class=\"formula-inline\">$T_{\\mathrm{e2e}} \\le T_{\\mathrm{SLO}}$</span> 对 <span class=\"formula-inline\">$N_{\\mathrm{vis}}$</span> 求解，得到满足时延的最大视觉 token 数，即压缩比下限；把分池拓扑（第三项非零、解码池可独立加大 <span class=\"formula-inline\">$B$</span>）与同池拓扑（第三项为零、但解码受预填争抢）分别代入，比较两者 <span class=\"formula-inline\">$T_{\\mathrm{e2e}}$</span>，若传输项超过分池带来的解码批处理收益，则不应分池。举一个具体例子：某请求 <span class=\"formula-inline\">$N_{\\mathrm{vis}}$</span> 较大、<span class=\"formula-inline\">$S_{\\mathrm{kv}}$</span> 因 KV 头数多而偏大，即使 <span class=\"formula-inline\">$\\mathrm{BW}_{\\mathrm{link}}$</span> 是 NVLink 级别，第三项仍可能随 <span class=\"formula-inline\">$B_{\\mathrm{kv}}$</span> 线性增长到与解码项同量级——此时分池的收益被带宽吃掉，正确判断是同池部署并用 chunked prefill 压制争抢，而不是继续扩容解码池。</p>\n<p>代价维度必须逐项核对：视觉编码项是纯算力代价，压缩 <span class=\"formula-inline\">$N_{\\mathrm{vis}}$</span> 同时降低第一、第二、第三项，是唯一同时作用于三个正项的杠杆；预填项随 <span class=\"formula-inline\">$N_{\\mathrm{vis}}+N_{\\mathrm{txt}}$</span> 线性增长，长文本与高分辨率图像叠加时该项主导；传输项是纯带宽代价，且随 KV 头数与层数（藏在 <span class=\"formula-inline\">$S_{\\mathrm{kv}}$</span> 里）线性放大；解码项是显存带宽与批大小的折中，<span class=\"formula-inline\">$t_{\\mathrm{dec}}(B)$</span> 随 <span class=\"formula-inline\">$B$</span> 上升，吞吐上升但单请求时延上升，SLO 约束下 <span class=\"formula-inline\">$B$</span> 有上界。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-3\">三 · 常见误解之一：把串行叠加当成精确预测器</h3>\n<p>该式最危险的误用是把它当作生产环境的精确时延预测器。它的推导前提是预填与解码完全串行、无 chunked prefill 重叠。实际框架中 continuous batching 会让解码 token 与后续请求的预填交错执行：当批内已有请求在解码时，新请求的预填被切成 chunk 插入解码步之间的空隙，两阶段在时间轴上重叠。此时真实时延小于串行模型给出的值，串行模型系统性高估时延。后果是 SLO 评估偏保守，运维按高估值扩容解码池，容量被过度预留。正确的用法是把该式当作上界与决策工具：用它比较拓扑优劣、反解压缩比下限，而不是用它逐请求预测墙钟时间；进入容量规划时必须换成排队模型或带重叠修正的批调度时延模型。</p>\n<p>与之配套的第二个误解是忽略视觉编码器多卡切分时的集合通信。第一项分母写的是 <span class=\"formula-inline\">$F_{\\mathrm{vis}}\\eta$</span>，隐含假设视觉编码器在单卡或单池内以近线性效率运行。当编码器被切分到多卡（例如高分辨率图像需要跨卡分块编码），编码阶段内部出现 all-reduce 或 all-gather，其代价由集合通信下界决定，不能简单按单卡 <span class=\"formula-inline\">$F_{\\mathrm{vis}}$</span> 折算。漏掉这一项会低估编码阶段时延，尤其在高分辨率、多图输入的请求上，编码项本身占比不小，低估会直接传导到压缩比决策——把 <span class=\"formula-inline\">$N_{\\mathrm{vis}}$</span> 上限算得过大，压缩不足，预填项与传输项随之膨胀。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-4\">四 · 常见误解之二：分池只看解码吞吐收益</h3>\n<p>分池决策最常见的错误是只算解码池的吞吐收益，忽略第三项随视觉 token 数与 KV 头数线性增长。一个典型失效模式：团队看到解码池独立后可以加大 <span class=\"formula-inline\">$B$</span>、吞吐提升，于是把视觉编码器与 LLM 解码器分到两个池，结果跨池 KV 传输的带宽成为瓶颈，端到端时延反超同池部署。原因在于 <span class=\"formula-inline\">$S_{\\mathrm{kv}}$</span> 含 KV 头数与层数，多模态请求的 <span class=\"formula-inline\">$N_{\\mathrm{vis}}$</span> 又把 <span class=\"formula-inline\">$B_{\\mathrm{kv}}$</span> 抬高，两项相乘使传输字节量远超纯文本请求；<span class=\"formula-inline\">$\\mathrm{BW}_{\\mathrm{link}}$</span> 即使是 NVLink 5 级别也有上限，传输项一旦与解码项同量级，分池的净收益转负。</p>\n<p>另一个方向性误解是认为“同池部署时传输项为零所以同池一定更快”。传输项确实为零，但同池部署下解码阶段会受预填请求的显存与算力争抢，表现为解码步被预填打断、<span class=\"formula-inline\">$t_{\\mathrm{dec}}(B)$</span> 的实际有效值上升，串行模型无法刻画这种争抢，必须改用排队模型。因此同池与分池的比较不是“零传输 vs 有传输”的单项比较，而是“争抢导致的解码退化”与“传输项加独立扩缩容收益”的整体比较。该式的正确读法是：它给出分池的必要条件（传输项不得超过分池收益），而非充分条件；同池是否更优要看争抢强度。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-5\">五 · 适用边界与决策流程</h3>\n<p>把上述边界收拢成一条可执行的判断链。第一步，按请求画像（<span class=\"formula-inline\">$N_{\\mathrm{vis}}$</span>、<span class=\"formula-inline\">$N_{\\mathrm{txt}}$</span>、<span class=\"formula-inline\">$N_{\\mathrm{out}}$</span>）与硬件参数（<span class=\"formula-inline\">$F_{\\mathrm{vis}}$</span>、<span class=\"formula-inline\">$F_{\\mathrm{llm}}$</span>、<span class=\"formula-inline\">$\\mathrm{BW}_{\\mathrm{link}}$</span>、<span class=\"formula-inline\">$S_{\\mathrm{kv}}$</span>）代入四项，得到串行上界。第二步，对 <span class=\"formula-inline\">$N_{\\mathrm{vis}}$</span> 反解 SLO 不等式，得到压缩比下限；若该下限低于视觉编码器可达到的压缩能力，说明 SLO 在当前拓扑下不可达，需改拓扑而非继续压 token。第三步，分别计算分池与同池的 <span class=\"formula-inline\">$T_{\\mathrm{e2e}}$</span>：分池时第三项非零但 <span class=\"formula-inline\">$B$</span> 可独立放大，同池时第三项为零但需叠加争抢修正。第四步，若视觉编码器多卡切分，在第一项上叠加集合通信下界项再比较。整个流程中，串行模型只承担“上界与反解”的角色，重叠修正与争抢修正必须由批调度时延模型与排队模型补上——这两者的具体形式属于本模块其他部分，此处只指路。</p>\n<p>最后落到一个具体机制上：压缩比是唯一同时压低第一、第二、第三项的旋钮，而 <span class=\"formula-inline\">$N_{\\mathrm{vis}}$</span> 在第二项中与 <span class=\"formula-inline\">$N_{\\mathrm{txt}}$</span> 相加、在第三项中通过 <span class=\"formula-inline\">$B_{\\mathrm{kv}}$</span> 线性传导，因此当请求同时具备长文本与高分辨率图像时，压缩视觉 token 的边际收益高于压缩文本（文本 token 只进第二项）。工程判断应据此排序优化动作：先压 <span class=\"formula-inline\">$N_{\\mathrm{vis}}$</span>，再评估分池，最后才调 <span class=\"formula-inline\">$B$</span>——因为 <span class=\"formula-inline\">$B$</span> 只作用于第四项且受 SLO 上界约束，而 <span class=\"formula-inline\">$N_{\\mathrm{vis}}$</span> 作用于三个正项。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-6\">六 · 串行叠加模型的适用边界与三类失效路径</h3>\n<p>该式把端到端时延写成四项串行相加，其价值不在预测精度，而在暴露分池决策的隐性成本项：第三项 KV 跨池传输。视觉 token 数 $N_{\\mathrm{vis}}$ 同时出现在第一项（编码）、第二项（预填）与第三项（传输）中，这意味着压缩视觉 token 的收益是三重线性的——编码墙钟时间、预填时间与跨池搬运量同时下降。反过来，若视觉 token 膨胀而 $S_{\\mathrm{kv}}$ 又随 KV 头数与层数走高，传输项 $\\frac{S_{\\mathrm{kv}}B_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}$ 会以乘积形式吃掉分池收益。工程判断因此落在一条不等式上：分池带来的解码批处理吞吐增益折算成时延节省，是否大于传输项加上池间调度开销。当视觉 token 压缩比不足、互联带宽受限（例如 decode 池与 prefill 池跨机架走 RDMA 而非 NVLink），传输项往往反超同池部署。</p>\n<p>第一个失效条件是串行假设本身。生产框架的 continuous batching 会让解码 token 与后续请求的预填交错执行，预填与解码在时间轴上重叠，串行叠加模型因此系统性高估时延。用高估值做容量规划，会得出“解码池不够、必须扩容”的错误结论，而真实瓶颈可能只是调度策略未开 chunked prefill。判断方法很直接：若实测端到端时延明显低于该式预测，且 GPU 利用率显示预填与解码在同一时间窗内共存，则应以排队模型替代串行式，把预填到达率与解码服务率作为输入。</p>\n<p>第二个失效条件是拓扑误用。同池部署时传输项为零，但解码阶段会与预填请求争抢显存与算力——预填的长序列会瞬时抬高 KV cache 占用，挤压解码批大小 $B$，使 $t_{\\mathrm{dec}}(B)$ 因批被压缩而恶化。此时该式给出的是“无争抢的理想下界”，真实时延需叠加排队等待项。分池部署则相反：解码池可独立加大 $B$ 提升吞吐，但 $t_{\\mathrm{dec}}(B)$ 随批大小上升，必须在 SLO 约束下选批，不能只按吞吐最大化选点。</p>\n<p>第三个失效条件是视觉编码器多卡切分。第一项分母 $F_{\\mathrm{vis}}$ 若仍按单卡算力代入，会漏掉编码阶段内部的集合通信下界——切分到多卡后，每层编码后需做 all-reduce 或 all-gather，其耗时与切分度、互联带宽相关，且在小 batch 下通信占比更高。正确做法是在编码项后叠加一个通信下界项，其量级由切分数与单次集合通信时延决定。多模态请求的视觉输入往往 batch 较小（图像分辨率与数量不一），编码器切分度越高，通信下界越不可忽略，此时压缩 $N_{\\mathrm{vis}}$ 的收益会被通信开销稀释。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>模型偏差方向</th><th>工程后果</th></tr></thead><tbody><tr><td>忽略 continuous batching 重叠</td><td>高估时延</td><td>误判分池必要、过度扩容解码池</td></tr><tr><td>分池只算吞吐收益</td><td>低估传输项</td><td>带宽成瓶颈，时延反超同池</td></tr><tr><td>多卡编码按单卡算力估算</td><td>低估编码时延</td><td>SLO 评估偏乐观，编码阶段超时</td></tr></tbody></table>\n<h3 id=\"th-multimodal-prefill-decode-split-sec-7\">七 · 视觉编码项的分子结构与推导起点</h3>\n<p>第一项 <span class=\"inline-math\">$$\\frac{N_{\\mathrm{vis}}\\,d\\,L_{\\mathrm{vis}}}{F_{\\mathrm{vis}}\\,\\eta}$$</span> 的分子不是“视觉 token 数乘一个常数”，而是把编码器的计算量拆成三层可验证的量：每请求视觉 token 数 $N_{\\mathrm{vis}}$（压缩后的值，不是原始 patch 数）、隐藏维 $d$、层数 $L_{\\mathrm{vis}}$。三者相乘得到的是每请求在编码器前向中需要处理的激活元素总量级；之所以说“量级”而非精确 FLOPs，是因为真实编码器每层还含注意力矩阵乘与 MLP 扩维比，$d\\cdot L_{\\mathrm{vis}}$ 只捕捉了 token 维与深度维的主项，把每层内部常数吸收进 $\\eta$。推导的关键一步是把“每请求工作量”除以“池的有效算力”：$F_{\\mathrm{vis}}$ 是视觉池的峰值算力，$\\eta$ 是算力利用率，二者相乘才是可持续吞吐意义上的分母。这一步隐含一个近似——把编码器的墙钟时间当作纯计算受限，忽略了权重加载与激活搬运的带宽项；当 $N_{\\mathrm{vis}}$ 很小而 $d$、$L_{\\mathrm{vis}}$ 很大时，编码器实际落在带宽受限区，此时该式会低估时间，需要换用 Roofline 形式的界（视觉编码器 Roofline 界已在别处展开，此处只指路）。工程代价上，这一项直接决定视觉池的 GPU 数量：$N_{\\mathrm{vis}}$ 翻倍，编码时间线性翻倍，若 SLO 卡在编码段，扩容视觉池是唯一手段，而压缩 $N_{\\mathrm{vis}}$ 是等效的“免费扩容”。具体例子：一个请求压缩后 $N_{\\mathrm{vis}}$ 从 1024 降到 512，其余不变，编码项减半，视觉池可少配一半卡——但压缩带来的失真代价要由质量约束承担，这正是后文反解压缩比下限的入口。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-8\">八 · 多模态预填项的线性缩放与合并假设</h3>\n<p>第二项 <span class=\"inline-math\">$$\\frac{(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\,P_{\\mathrm{llm}}}{F_{\\mathrm{llm}}\\,\\eta}$$</span> 的核心是把视觉 token 与文本 prompt token 直接相加当作预填长度。这个合并假设成立的前提是：视觉 token 进入 LLM 后与文本 token 走同一条注意力路径，每 token 的预填计算量 $P_{\\mathrm{llm}}$ 对两者相同。推导上，$P_{\\mathrm{llm}}$ 本身是“每 token 预填计算量”的聚合量，随序列长度二次增长的注意力项被折叠进 $P_{\\mathrm{llm}}$ 的取值里——这意味着 $P_{\\mathrm{llm}}$ 不是常数，而是 $N_{\\mathrm{vis}}+N_{\\mathrm{txt}}$ 的函数；公式把它写成符号常量，是一种分段线性化近似：在给定 SLO 对应的序列长度区间内，把 $P_{\\mathrm{llm}}$ 当作该区间的平均斜率。这个近似的失效点在长序列端：当视觉 token 膨胀把总长推过注意力二次项主导的拐点，线性外推会低估预填时间。工程含义非常直接：压缩比每降一半，$N_{\\mathrm{vis}}$ 减半，预填项近似减半，这是全式里对压缩比最敏感的项，也是“压到多少才满足 SLO”反解的主战场。代价侧，预填项是显存与算力双消耗：预填池的显存要容纳长序列激活，算力要支撑 $P_{\\mathrm{llm}}$ 的矩阵乘；分离部署时预填池可按 $N_{\\mathrm{vis}}+N_{\\mathrm{txt}}$ 的分布独立扩缩容，同池部署时它直接与解码争抢。例子：$N_{\\mathrm{txt}}$ 固定、$N_{\\mathrm{vis}}$ 占预填长度七成时，压缩视觉 token 的边际收益远大于优化文本侧，容量规划应优先投在视觉 token 压缩上。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-9\">九 · KV 跨池传输项：分池决策的隐性成本与离散化</h3>\n<p>第三项 <span class=\"inline-math\">$$\\frac{S_{\\mathrm{kv}}\\,B_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}$$</span> 是全式唯一“只在物理分离时非零”的项，也是分池收益的抵消项。逐项看：$S_{\\mathrm{kv}}$ 是每 token KV cache 字节数，含 KV 头数与层数——它随模型结构固定，但随 $N_{\\mathrm{vis}}$ 线性放大总字节；$B_{\\mathrm{kv}}$ 是需跨池搬运的 KV 块数，这里出现第一个离散化：KV cache 以块（block）为单位分配与传输，$B_{\\mathrm{kv}}=\\lceil (N_{\\mathrm{vis}}+N_{\\mathrm{txt}})/b \\rceil$，$b$ 为块大小，向上取整使传输量呈阶梯状而非连续；$\\mathrm{BW}_{\\mathrm{link}}$ 是 NVLink 或 RDMA 的有效带宽。推导关键步是把“总字节除以带宽”当作传输墙钟时间，这隐含两个近似：其一，假设传输与计算不重叠，实际流水线中预填池可在生成 KV 的同时启动传输，重叠后有效传输时间小于该比值；其二，假设带宽是稳定值，而 NVLink 与 RDMA 在不同消息大小下的有效带宽不同，小块传输的协议开销会让实际时间高于理论值。代价上，这一项是带宽受限的：视觉 token 越多、KV 头数越多，$S_{\\mathrm{kv}}B_{\\mathrm{kv}}$ 越大，传输项越可能吃掉分池带来的解码批处理收益。工程判断由此而来——比较分池与同池两种拓扑时，若传输项超过解码池因独立加大 $B$ 获得的吞吐折算收益，就不应分池。例子：$S_{\\mathrm{kv}}$ 随 KV 头数翻倍时，传输项翻倍，原本分池划算的配置可能反转为同池更优；这正是“只算解码收益、忽略传输项”这一失败模式的数学根源。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-10\">十 · 解码项与批大小的耦合：$t_{\\mathrm{dec}}(B)$ 的非线性</h3>\n<p>第四项 <span class=\"inline-math\">$$N_{\\mathrm{out}}\\cdot t_{\\mathrm{dec}}(B)$$</span> 看似最简单，实则藏着一个非线性函数。$t_{\\mathrm{dec}}(B)$ 是批大小为 $B$ 时的单步解码时延，它不是常数：解码阶段每步要读全部权重与 KV cache，$B$ 增大时权重读取被摊薄、单步时延增长慢于线性，但 KV cache 读取随 $B$ 线性增长，超过某点后单步时延转为带宽受限而快速上升。推导上，$N_{\\mathrm{out}}$ 步串行相乘，意味着解码项对 $N_{\\mathrm{out}}$ 完全线性——输出越长，解码段越主导端到端时延，此时预填与编码的优化边际收益递减。离散化在这里体现为“步”：自回归按 token 逐步生成，每步之间无法并行，$N_{\\mathrm{out}}$ 是整数步数，不能连续缩放；这也解释了为什么投机解码能改变这一项——它把多步合并为一次验证，等效于降低有效步数（投机解码的机制在别处展开，此处只指路）。工程代价是吞吐与延迟的权衡：分池后解码池可独立加大 $B$ 提升吞吐，但单步时延随 $B$ 上升，必须在 SLO 约束下选批大小，而不是无脑加大。例子：SLO 给定单请求端到端上限，$N_{\\mathrm{out}}$ 较大时解码项占主导，此时加大 $B$ 换吞吐会推高单步时延、击穿 SLO，正确做法是限制 $B$ 或改用更快的解码内核，而非扩容预填池。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-11\">十一 · 串行叠加的失效边界与反解压缩比下限</h3>\n<p>四项相加成立的前提是“预填与解码完全串行、无 chunked prefill 重叠”。真实 continuous batching 会让解码 token 与后续请求的预填交错执行，串行模型因此系统性高估时延——这是该式最重要的近似失效点。修正方向不是改公式结构，而是引入重叠因子：把预填项与解码项中可并行的部分按重叠比例折减，或用排队模型替代串行叠加（同池部署时传输项为零但解码受预填争抢，必须改用排队模型，多模态批调度时延模型已在别处展开）。另一个失效点是视觉编码器多卡切分：此时 $F_{\\mathrm{vis}}$ 不再是单卡算力，编码阶段内部还有集合通信时延，需叠加通信下界项，否则低估编码时间。用途上，该式可反解：给定 SLO 与各池算力，令 $T_{\\mathrm{e2e}}\\le T_{\\mathrm{SLO}}$，对 $N_{\\mathrm{vis}}$ 求解，得到满足时延的最大视觉 token 数，即压缩比下限。反解时要注意 $N_{\\mathrm{vis}}$ 同时出现在第一、二、三项中，且第三项含向上取整的离散块数，解析解只在连续松弛下成立，工程上应做离散搜索而非直接套公式。例子：当传输项随 $N_{\\mathrm{vis}}$ 线性增长而预填项也线性增长时，反解出的 $N_{\\mathrm{vis}}$ 上限由“编码+预填+传输”三项斜率之和决定，压缩比必须压到该上限以下才可能满足 SLO——这把“压到多少”从经验判断变成了可计算的容量约束。</p>\n\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-12\">十二 · 串行叠加式的适用边界与失效条件</h3>\n<p>四项串行叠加的时延式之所以能作为分池决策的判据，前提是它把每个阶段都当成独占资源的墙钟时间：视觉编码项 $\\frac{N_{\\mathrm{vis}}dL_{\\mathrm{vis}}}{F_{\\mathrm{vis}}\\eta}$ 的分子是编码器所需乘加量级，分母是视觉池的有效算力；预填项 $\\frac{(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})P_{\\mathrm{llm}}}{F_{\\mathrm{llm}}\\eta}$ 把压缩后的视觉 token 与文本 token 合并计入预填长度，因此压缩比每降一半，预填项近似减半；传输项 $\\frac{S_{\\mathrm{kv}}B_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}$ 只在 prefill 池与 decode 池物理分离时非零，$S_{\\mathrm{kv}}$ 含 KV 头数与层数，视觉 token 越多、头数越多，这一项越容易吃掉分池收益；解码项 $N_{\\mathrm{out}}t_{\\mathrm{dec}}(B)$ 则与批大小强耦合。四项相加成立的条件是四段互不重叠——这正是该式最脆弱的地方。</p>\n<p>第一个失效条件是串行假设本身。生产框架的 continuous batching 会让解码 token 与后续请求的预填交错执行，解码池在生成当前请求的同时吸收新请求的预填，串行模型因此系统性高估时延。误用的后果不是数字偏差，而是决策偏差：SLO 评估偏保守，运维侧按高估的时延扩容解码池，扩容后实际时延并未改善，因为瓶颈根本不在解码池容量。校正方式是在预填项与解码项之间引入重叠因子，把两项按实际交错比例折减，而不是简单相加；重叠比例取决于批调度器的 token 预算分配，属于需要实测标定的量，不能从公式内部推出。</p>\n<p>第二个失效条件是同池部署下传输项归零的误读。传输项为零不等于分池无成本：同池时解码请求与预填请求争抢同一份显存与算力，预填的长序列会挤占 KV cache 空间并拉长解码步的调度延迟，此时串行式完全失效，必须换成排队模型——把预填视为到达率为 $\\lambda$ 的服务请求、解码视为长驻服务，用 M/G/1 类的等待时间刻画争抢代价。判断分池是否值得，本质是比较“传输项”与“同池争抢的排队等待项”哪个更小，而不是看传输项是否为零。</p>\n<p>第三个失效条件是视觉编码器多卡切分。式中的 $F_{\\mathrm{vis}}$ 是单池算力，一旦编码器按层或按 patch 切到多卡，编码阶段内部就出现集合通信，实际墙钟时间需叠加通信下界项，量级由切分维度上的 all-reduce/all-gather 数据量与互联带宽决定。仍按单卡 $F_{\\mathrm{vis}}$ 估算会低估编码时间，在视觉 token 膨胀、编码器层数深的场景下偏差被放大。同理，视觉编码与 LLM 预填之间的流水并行未被建模，若两者被安排成流水，串行式会把本可重叠的两段重复计入。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>被破坏的项</th><th>系统代价表现</th><th>校正手段</th></tr></thead><tbody><tr><td>continuous batching 交错</td><td>预填项 + 解码项</td><td>时延高估，误扩解码池</td><td>引入重叠折减因子</td></tr><tr><td>同池部署争抢</td><td>传输项置零的误判</td><td>解码步被预填挤占，尾延迟抬升</td><td>改用排队模型</td></tr><tr><td>编码器多卡切分</td><td>视觉编码项</td><td>编码墙钟被低估，通信成隐性瓶颈</td><td>叠加集合通信下界项</td></tr></tbody></table>\n<p>由此，该式的正确用法是反解而非正算：给定 SLO 与各池算力，反解满足时延的最大 $N_{\\mathrm{vis}}$，得到视觉 token 压缩比的下限；再分别代入分池与同池两种拓扑，若传输项随 $N_{\\mathrm{vis}}$ 与 KV 头数线性增长后超过分池带来的解码批处理收益，则不应分池。压缩比的选择因此不是图像质量的独立参数，而是被带宽项与预填项共同夹逼出的工程区间。</p>\n<h3 id=\"th-multimodal-prefill-decode-split-sec-13\">十三 · 串行假设的成立条件与重叠修正</h3>\n<p>公式四项相加的前提是“视觉编码 → 多模态预填 → KV 跨池传输 → 自回归解码”严格首尾相接，任一时刻只有一个阶段占用关键路径。这个假设在两种部署下才近似成立：其一，请求以极低并发逐个到达，批内没有第二个请求可插队；其二，框架显式关闭 chunked prefill，预填以整块方式独占 SM。一旦进入 continuous batching，解码步与后续请求的预填会被调度器交错排入同一迭代，串行式把两段墙钟时间直接相加，等于假设它们互不遮挡，于是系统性高估 $T_{\\mathrm{e2e}}$。</p>\n<p>修正方式不是给公式乘一个拍脑袋的系数，而是把重叠量写成可计算的项。设一个解码迭代周期为 $t_{\\mathrm{iter}}$，其中用于预填的 SM 时间片占比为 $\\rho$，则预填项的有效墙钟时间近似为</p>\n<div class=\"formula\">$$T_{\\mathrm{pre}}^{\\mathrm{eff}} \\;\\approx\\; \\frac{(N_{\\mathrm{vis}}+N_{\\mathrm{txt}})\\,P_{\\mathrm{llm}}}{F_{\\mathrm{llm}}\\,\\eta}\\cdot(1-\\rho)$$</div>\n<p>$\\rho$ 由调度器的 chunk 大小与解码批的 token 预算共同决定，工程上可从框架的 profiler 里直接读出每迭代的 prefill token 数与 decode token 数之比。代价在于：$\\rho$ 越大，预填被摊薄得越厉害，但解码步的 $t_{\\mathrm{dec}}(B)$ 会因为 SM 被预填切走而上升，解码项反而变长。因此重叠不是免费的，它把时延从预填项搬到了解码项，SLO 评估必须同时看两段。</p>\n<p>具体例子：一个图像问答请求 $N_{\\mathrm{vis}}$ 较大、$N_{\\mathrm{out}}$ 只有几十个 token 时，串行式给出的预填项占主导；但在 continuous batching 下，该请求的预填被切成多个 chunk 与在途解码交错，实际端到端时延由“最后一个 chunk 完成时刻 + 剩余解码步”决定，而不是预填总时间加解码总时间。此时若仍按串行式扩容预填池，容量会被高估。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-14\">十四 · 传输项非零的边界：物理分离才计费</h3>\n<p>第三项 $\\frac{S_{\\mathrm{kv}}\\,B_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}$ 是分池决策的隐性成本，它的适用边界非常硬：只有当 prefill 池与 decode 池在物理上分离、KV cache 必须经 NVLink 或 RDMA 搬运时才非零。同池部署时该项恒为零，但代价换了形式——解码请求与预填请求争抢同一批 SM 与 HBM 带宽，公式失效，需改用排队模型描述显存与算力的争用。</p>\n<p>即便物理分离，传输项也不是常数。$B_{\\mathrm{kv}}$ 随视觉 token 数线性增长，$S_{\\mathrm{kv}}$ 随 KV 头数与层数线性增长，两者相乘意味着视觉 token 膨胀会以二次方式放大传输字节量。判定分池是否划算的工程判据是：把传输项与“分池后解码池因独立加大 $B$ 而获得的单步时延摊薄收益”做对比。设同池解码批为 $B_0$、分池后为 $B_1$，则分池的净收益为</p>\n<div class=\"formula\">$$\\Delta T \\;=\\; N_{\\mathrm{out}}\\bigl[t_{\\mathrm{dec}}(B_0)-t_{\\mathrm{dec}}(B_1)\\bigr] \\;-\\; \\frac{S_{\\mathrm{kv}}\\,B_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}$$</div>\n<p>$\\Delta T&gt;0$ 才值得分池。注意 $t_{\\mathrm{dec}}(B)$ 随 $B$ 上升，所以 $B_1$ 不能无限加大，分池收益存在上限；而传输项随 $N_{\\mathrm{vis}}$ 增长没有上限，因此高视觉 token 负载天然偏向同池。</p>\n<p>具体例子：一个高分辨率文档理解请求，压缩后视觉 token 仍达数千，其 KV cache 字节数与块数都很大；在 NVLink 域内传输尚可接受，一旦跨节点走 RDMA，$\\mathrm{BW}_{\\mathrm{link}}$ 下降一个量级，传输项迅速吃掉分池收益，此时应把视觉编码器与 LLM 解码器留在同一超节点内，仅做逻辑上的池划分。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-15\">十五 · 视觉编码多卡切分时漏掉的通信项</h3>\n<p>第一项 $\\frac{N_{\\mathrm{vis}}\\,d\\,L_{\\mathrm{vis}}}{F_{\\mathrm{vis}}\\,\\eta}$ 把 $F_{\\mathrm{vis}}$ 当作单卡有效算力。当视觉编码器被切分到多卡（张量并行或序列并行）时，编码阶段内部每层都存在集合通信，公式漏掉了这一项，导致编码时间被低估。修正后的编码项应叠加通信下界：</p>\n<div class=\"formula\">$$T_{\\mathrm{vis}} \\;\\approx\\; \\frac{N_{\\mathrm{vis}}\\,d\\,L_{\\mathrm{vis}}}{F_{\\mathrm{vis}}^{\\mathrm{multi}}\\,\\eta} \\;+\\; L_{\\mathrm{vis}}\\cdot t_{\\mathrm{comm}}$$</div>\n<p>$t_{\\mathrm{comm}}$ 是每层一次 all-reduce 或 all-gather 的墙钟时间，取决于切分维度、消息大小与互联带宽。切分卡数越多，$F_{\\mathrm{vis}}^{\\mathrm{multi}}$ 越大但 $t_{\\mathrm{comm}}$ 也越大，存在一个使 $T_{\\mathrm{vis}}$ 最小的切分度；超过该点，通信项主导，加卡不再缩短编码时间。这正是视觉编码器 Roofline 界在多卡情形下的延伸，此处只指出公式的漏项，不重复其推导。</p>\n<p>具体例子：把视觉编码器切到 8 卡做张量并行，单层 all-reduce 的消息量随隐藏维 $d$ 增长，若互联为跨节点 RDMA 而非 NVLink，$t_{\\mathrm{comm}}$ 会显著抬高 $T_{\\mathrm{vis}}$，此时公式按单卡 $F_{\\mathrm{vis}}$ 估算出的编码时间可能只有实际值的一半量级，分池决策会因此误判视觉侧不是瓶颈。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-16\">十六 · 反解压缩比下限时的假设脆弱性</h3>\n<p>公式的一个核心用途是给定 SLO 反解满足时延的最大 $N_{\\mathrm{vis}}$，即视觉 token 压缩比下限。这个反解在数学上干净，但它继承了全部串行假设，且对 $N_{\\mathrm{vis}}$ 的依赖是非线性的：$N_{\\mathrm{vis}}$ 同时出现在预填项与传输项中，前者线性、后者经 $B_{\\mathrm{kv}}$ 线性放大。把 $T_{\\mathrm{e2e}}\\le T_{\\mathrm{SLO}}$ 对 $N_{\\mathrm{vis}}$ 求解，得到的是</p>\n<div class=\"formula\">$$N_{\\mathrm{vis}}^{\\max} \\;=\\; \\frac{T_{\\mathrm{SLO}}-N_{\\mathrm{out}}t_{\\mathrm{dec}}(B)-N_{\\mathrm{txt}}P_{\\mathrm{llm}}/(F_{\\mathrm{llm}}\\eta)}{P_{\\mathrm{llm}}/(F_{\\mathrm{llm}}\\eta)+S_{\\mathrm{kv}}k_{\\mathrm{blk}}/\\mathrm{BW}_{\\mathrm{link}}}$$</div>\n<p>其中 $k_{\\mathrm{blk}}$ 是每视觉 token 对应的 KV 块数系数。分母中传输系数与预填系数并列，说明在分离式部署下压缩比下限被传输项拉低——同样的 SLO 要求更激进的压缩。若实际运行在 continuous batching 下，预填项被重叠摊薄，反解出的 $N_{\\mathrm{vis}}^{\\max}$ 偏小，压缩比被压得比必要更狠，视觉信息损失超出需求。</p>\n<p>具体例子：SLO 要求端到端时延在一个交互式阈值内，反解给出压缩比需压到四分之一；但生产环境开启 chunked prefill 后预填实际只占部分关键路径，真实可承受的 $N_{\\mathrm{vis}}$ 是反解值的数倍，此时按反解值压缩会白白牺牲图像细节，问答准确率下降而时延并未逼近 SLO。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-17\">十七 · 规模上限：批大小与池容量的饱和点</h3>\n<p>公式在规模上有明确上限。解码项 $N_{\\mathrm{out}}\\cdot t_{\\mathrm{dec}}(B)$ 中 $t_{\\mathrm{dec}}(B)$ 随 $B$ 上升，当 $B$ 增大到解码从算力受限转为带宽受限（每步需读取全部 KV cache），$t_{\\mathrm{dec}}(B)$ 的斜率改变，公式仍形式成立但参数含义漂移。更关键的是分池拓扑的规模上限：prefill 池与 decode 池各自独立扩缩容的前提是两池之间的 $\\mathrm{BW}_{\\mathrm{link}}$ 不成为共享瓶颈。当并发请求数上升，跨池 KV 传输的总字节量按请求数线性叠加，$\\mathrm{BW}_{\\mathrm{link}}$ 被多请求分摊，第三项的有效带宽下降，传输时间超线性增长。</p>\n<p>设并发请求数为 $R$，则聚合传输时间为</p>\n<div class=\"formula\">$$T_{\\mathrm{kv}}^{\\mathrm{agg}} \\;=\\; \\frac{R\\cdot S_{\\mathrm{kv}}\\,B_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}$$</div>\n<p>只要 $T_{\\mathrm{kv}}^{\\mathrm{agg}}$ 逼近甚至超过解码池的单步迭代时间，传输就从“每请求一次性开销”变成“持续占用互联的稳态负载”，此时公式把每请求传输当作独立项的假设失效，必须把互联当作排队资源建模。规模上限的工程判据是：互联利用率超过某个阈值后，分池不再带来吞吐增益，反而因传输排队拉长尾延迟。</p>\n<p>具体例子：NVL72 域内 NVLink 带宽充裕，单请求传输项可忽略；但当 decode 池跨出该域、走 RDMA 与 prefill 池相连，聚合传输随并发上升迅速逼近链路容量，尾请求的 KV 传输排队时间成为端到端时延的主要成分，公式给出的均值时延严重低估 P99。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-18\">十八 · 失效条件的工程清单</h3>\n<p>把上述边界收敛成可操作的判断清单，用于在拿到一个新负载时先问“公式还成不成立”：</p>\n<ul>\n<li>调度器是否开启 chunked prefill 或 continuous batching？开启则串行叠加高估时延，须引入重叠因子 $\\rho$ 并同步修正解码项。</li>\n<li>prefill 池与 decode 池是否物理分离？同池则传输项归零，但须改用排队模型描述显存与算力争抢，公式的加法结构不再适用。</li>\n<li>视觉编码器是否多卡切分？是则补 $L_{\\mathrm{vis}}\\cdot t_{\\mathrm{comm}}$，并按切分度寻找 $T_{\\mathrm{vis}}$ 的最小点，而非盲目加卡。</li>\n<li>并发是否已使聚合 KV 传输逼近 $\\mathrm{BW}_{\\mathrm{link}}$？是则互联成为排队资源，每请求独立传输项的假设失效，尾延迟不可由均值公式预测。</li>\n<li>解码批 $B$ 是否已越过带宽受限拐点？是则 $t_{\\mathrm{dec}}(B)$ 的参数含义漂移，分池收益上限被封顶。</li>\n</ul>\n<p>这张清单的用途不是否定公式，而是界定它的有效域：在低并发、同池、单卡编码、无重叠的“干净”场景下，四项串行式是可靠的容量规划工具；一旦任一条件被打破，就必须替换对应项而非整体弃用。工程判断的落点是：先确认负载落在哪个失效条件上，再决定是修正单项、切换排队模型，还是干脆放弃分池拓扑——传输项随视觉 token 与 KV 头数线性增长这一事实，使得高视觉负载场景下同池部署往往是更稳的默认选择。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-19\">十九 · 边界条件：串行假设、传输项与多卡切分的三重失效</h3>\n<p>该式的第一个隐含前提是四项严格串行：视觉编码结束才启动 LLM 预填，预填全部完成才开始逐 token 解码。这个假设在单请求冷启动、批内无其他流量时接近成立，但在 continuous batching 的生产环境里必然被打破——调度器会在解码步的间隙插入后续请求的预填块，解码 token 与预填 token 在同一时间片上交错占用 SM 与显存带宽。此时把四项直接相加会系统性高估端到端时延，误差量级取决于重叠深度：预填块越小、批内解码请求越多，重叠越充分，串行模型越保守。工程后果不是精度问题而是决策问题——按高估的时延做 SLO 评估，会得出解码池算力不足的结论并触发错误扩容，而真实瓶颈可能根本不在解码侧。判断方法很直接：若实测 P99 与串行式预测值出现稳定正偏差且偏差随批内并发上升而扩大，就说明重叠已经在起作用，应改用带服务台的排队模型而非闭式串行叠加。</p>\n<p>第二重失效来自 KV 跨池传输项的非线性。传输项写作 $\\frac{S_{\\mathrm{kv}}\\,B_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}$，看似与视觉 token 数线性相关，但 $S_{\\mathrm{kv}}$ 本身随 KV 头数与层数增长，而 $B_{\\mathrm{kv}}$ 在多请求并发分池时会按在途请求数成倍累积——分池收益来自解码池独立加大批大小 $B$，可批大小越大，同时在 decode 池等待的请求越多，需要跨池搬运的 KV 块总量越大。于是出现一个反直觉的拐点：当视觉 token 膨胀使 $N_{\\mathrm{vis}}$ 抬高、KV 头数又偏大时，传输项的增长速度可能超过解码批处理带来的吞吐收益，端到端时延反超同池部署。这正是分池决策必须显式比较两种拓扑 $T_{\\mathrm{e2e}}$ 的原因，而不是只看解码池的吞吐数字。可用一张小表刻画判据：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>传输项量级</th><th>分池判断</th></tr></thead><tbody><tr><td>$N_{\\mathrm{vis}}$ 小、KV 头数少、$\\mathrm{BW}_{\\mathrm{link}}$ 为 NVLink</td><td>可忽略</td><td>分池收益占优</td></tr><tr><td>$N_{\\mathrm{vis}}$ 大、KV 头数多、互联为 RDMA</td><td>与解码收益同量级或更高</td><td>同池更稳</td></tr><tr><td>并发在途请求数高、$B_{\\mathrm{kv}}$ 累积</td><td>随并发线性上升</td><td>需按峰值并发重算</td></tr></tbody></table>\n<p>第三重失效发生在视觉编码器被切分到多卡时。式中的 $F_{\\mathrm{vis}}$ 是单池有效算力，分母只体现本地乘加吞吐，未包含编码阶段内部的集合通信下界。一旦编码器按层或按头切分到多卡，每层前后都要插入 all-reduce 或 all-gather，其耗时由单层激活字节数与互联带宽决定，与计算时间串行叠加而非重叠。此时仍按单卡 $F_{\\mathrm{vis}}$ 估算编码墙钟，会低估编码阶段时延，且低估幅度随切分卡数上升——卡越多，单卡计算量越小，通信占比越高，最终编码时间被通信下界主导，继续加卡不再缩短时延。这与 LLM 侧张量并行的通信-计算比规律同源，处理方式也一致：把通信下界作为独立项叠加进第一项，而不是折进 $\\eta$ 里含糊掉。规模上限由此显现——当 $N_{\\mathrm{vis}}$ 经压缩后已很小、编码计算本身不再是瓶颈时，多卡切分视觉编码器只增加通信开销，此时应回到单卡或减少切分度，把省下的卡投入解码池扩容。</p>\n<p>三项失效共同指向一个工程判断：该式的正确用法是作为分池决策与压缩比反解的比较工具，而非生产环境的时延预测器。给定 SLO 反解最大 $N_{\\mathrm{vis}}$ 时，必须把传输项与通信下界项一并纳入约束，否则解出的压缩比下限偏松，实际部署仍会超时；比较分池与同池时，需按峰值并发而非均值并发计算 $B_{\\mathrm{kv}}$，因为传输项在并发峰值处的非线性放大正是分池方案最容易被忽略的代价。</p>\n<h3 id=\"th-multimodal-prefill-decode-split-sec-20\">二十 · 从公式到决策变量：把四项拆成四个可调的旋钮</h3>\n<p>在容量决策里，$T_{\\mathrm{e2e}}$ 不是用来“预测”的，而是用来“反解”的。工程上把它看成四个可独立调节的旋钮之和：$N_{\\mathrm{vis}}$ 由视觉 token 压缩比控制（图像分辨率、patch 合并、token 剪枝），$B$ 由解码池的批调度策略控制，$F_{\\mathrm{vis}}$ 与 $F_{\\mathrm{llm}}$ 由分池拓扑与卡数分配控制，$\\mathrm{BW}_{\\mathrm{link}}$ 由互联选型（NVLink 域内 vs RDMA 跨节点）控制。决策顺序应当是：先由 SLO 定出时延预算，再按各项对预算的边际贡献分配资源，而不是先买卡再算时延。</p>\n<p>关键在于四项的缩放律不同。视觉编码项与预填项对 $N_{\\mathrm{vis}}$ 都是线性的，压缩比减半则两项同时近似减半；KV 传输项对 $N_{\\mathrm{vis}}$ 也是线性的（$B_{\\mathrm{kv}}$ 正比于序列长度），但它除以的是带宽而非算力，因此对互联选型极度敏感；解码项对 $B$ 是次线性的——$t_{\\mathrm{dec}}(B)$ 在批大小较小时近似常数（权重加载主导、算力未饱和），超过某个拐点后转为近似线性（算力或 KV 带宽主导）。这个拐点就是解码池的容量边界，也是 SLO 约束下批大小的上界。</p>\n<p>由此得到一条实用的判断：若某项在总时延中占比超过其资源占比的两倍，说明该项是瓶颈项，应优先调整对应旋钮。例如视觉编码项占比高而 $F_{\\mathrm{vis}}$ 只占卡数的两成，则应扩视觉池或提高压缩比，而不是加解码池。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-21\">二十一 · 定批大小：用解码项反解 $B$ 的上界</h3>\n<p>设 SLO 给出端到端时延上限 $T_{\\mathrm{SLO}}$，前三项（编码、预填、传输）在给定 $N_{\\mathrm{vis}}$、$N_{\\mathrm{txt}}$、拓扑下是确定的，记为 $T_{\\mathrm{pre}}$。则解码阶段可用预算为 $T_{\\mathrm{dec}}^{\\max}=T_{\\mathrm{SLO}}-T_{\\mathrm{pre}}$，批大小必须满足：</p>\n<div class=\"formula\">$$N_{\\mathrm{out}}\\cdot t_{\\mathrm{dec}}(B)\\;\\le\\;T_{\\mathrm{SLO}}-T_{\\mathrm{pre}}\\quad\\Longrightarrow\\quad t_{\\mathrm{dec}}(B)\\;\\le\\;\\frac{T_{\\mathrm{SLO}}-T_{\\mathrm{pre}}}{N_{\\mathrm{out}}}$$</div>\n<p>右侧是单步解码时延的允许上限。由于 $t_{\\mathrm{dec}}(B)$ 随 $B$ 单调上升，这个不等式给出 $B$ 的上界 $B_{\\max}$。吞吐则近似为 $B/t_{\\mathrm{dec}}(B)$，在 $B_{\\max}$ 附近通常已接近饱和，因此工程上直接把批大小钉在 $B_{\\max}$，而不是追求更大批。注意 $N_{\\mathrm{out}}$ 出现在分母：长输出请求对单步时延的要求更严，同一 SLO 下长输出的 $B_{\\max}$ 显著小于短输出，这正是按输出长度分桶调度的依据。</p>\n<p>代价侧要看清：$B$ 增大提升的是解码池吞吐（token/s），但单请求时延线性变差；在分离式部署中，解码池独立扩缩容意味着可以用“多副本 × 小 $B$”换时延、用“少副本 × 大 $B$”换吞吐，两者在给定 QPS 与 SLO 下等价于一条容量-时延曲线。若 SLO 是首 token 时延（TTFT）而非端到端，则约束落在 $T_{\\mathrm{pre}}$ 上，$B$ 只受显存约束（KV 块数），此时解码池应按 KV 预算而非时延定批。</p>\n<p>例子：一个请求 $N_{\\mathrm{out}}=512$，SLO 端到端 2 s 量级，前三项合计已占去大半预算，则留给解码的单步时延上限被压到毫秒级的几分之一，$B_{\\max}$ 只能取较小值；若把 $N_{\\mathrm{out}}$ 降到 128，同样的 $T_{\\mathrm{pre}}$ 下 $B_{\\max}$ 可放大约四倍，解码池副本数可相应减少。这就是输出长度分布直接决定解码池规模的原因。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-22\">二十二 · 定并行度：分池拓扑的比较判据</h3>\n<p>分池与同池的比较不是定性讨论，而是把两种拓扑各自代入 $T_{\\mathrm{e2e}}$ 后比较。同池时传输项为零，但解码与预填共享 $F_{\\mathrm{llm}}$，实际预填与解码争抢算力与显存带宽，串行模型失效，需改用排队模型估计等待时间；分池时传输项非零，但 $F_{\\mathrm{vis}}$、$F_{\\mathrm{llm}}$ 可独立分配，解码池可独立加大 $B$。</p>\n<p>判据可写成：分池的净收益 = 解码批处理收益 − KV 传输代价。解码收益体现在 $t_{\\mathrm{dec}}(B_{\\mathrm{split}})$ 相对同池受争抢时的有效解码时延的下降；传输代价即 $\\dfrac{S_{\\mathrm{kv}}B_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}$。当视觉 token 多、$S_{\\mathrm{kv}}$ 大（KV 头数多、层数深）、互联带宽有限（跨节点 RDMA 而非 NVLink 域内）时，传输项随 $N_{\\mathrm{vis}}$ 线性增长，很容易吃掉分池收益。反之，若视觉编码器算力需求相对 LLM 很小、且 $N_{\\mathrm{vis}}$ 经压缩后已很小，传输项可忽略，分池几乎总是更优。</p>\n<p>并行度还包含池内并行：视觉编码器切分到多卡时，$F_{\\mathrm{vis}}$ 不能简单按卡数线性相加，编码阶段内部存在集合通信，需叠加通信下界项（该下界的形式见 NVL72 通信下界条目）。工程判断是：视觉编码器的张量并行度超过单机 NVLink 域时，通信开销会侵蚀编码加速比，此时宁可增加副本数（数据并行）而非加大单请求的切分度。</p>\n<p>例子：若某部署中视觉池 4 卡、LLM 池 16 卡，分池后解码池可把 $B$ 从同池争抢下的有效值提升数倍，但每请求需搬运的 KV 块数随 $N_{\\mathrm{vis}}+N_{\\mathrm{txt}}$ 增长；若互联是跨节点 RDMA，传输项可能达到与预填项同量级，此时应优先提高视觉 token 压缩比以同时压低预填项与传输项，而不是继续扩解码池。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-23\">二十三 · 定 KV 预算：显存约束与传输块数的耦合</h3>\n<p>KV 预算有两个面：解码池的驻留显存，和跨池传输的搬运量。驻留侧，解码池需容纳 $B$ 个并发请求的 KV，每请求字节数为 $(N_{\\mathrm{vis}}+N_{\\mathrm{txt}}+N_{\\mathrm{out}})\\cdot S_{\\mathrm{kv}}$，因此并发上限为：</p>\n<div class=\"formula\">$$B_{\\mathrm{mem}}\\;=\\;\\left\\lfloor\\frac{M_{\\mathrm{kv}}^{\\mathrm{pool}}}{(N_{\\mathrm{vis}}+N_{\\mathrm{txt}}+N_{\\mathrm{out}})\\,S_{\\mathrm{kv}}}\\right\\rfloor$$</div>\n<p>其中 $M_{\\mathrm{kv}}^{\\mathrm{pool}}$ 是解码池可用于 KV 的显存总量（扣除权重与激活）。实际批大小取 $\\min(B_{\\max},B_{\\mathrm{mem}})$：短请求时延约束更紧，长请求时显存约束更紧。这解释了为什么长上下文多模态请求的吞吐瓶颈往往不在算力而在 KV 显存，压缩 $N_{\\mathrm{vis}}$ 同时放松了两个约束——既减小时延项，又增大 $B_{\\mathrm{mem}}$。</p>\n<p>传输侧，$B_{\\mathrm{kv}}$ 是需跨池搬运的 KV 块数，正比于预填序列长度。分池部署时若逐请求搬运，传输量与并发预填请求数成正比，带宽成为共享资源；当预填池吞吐上升时，传输项的有效带宽被摊薄，端到端时延的非线性上升就出现在这里。工程手段是让预填池与解码池的吞吐匹配：预填池的请求产出率不应超过 $\\mathrm{BW}_{\\mathrm{link}}/(S_{\\mathrm{kv}}\\cdot\\overline{B_{\\mathrm{kv}}})$，否则传输队列积压，串行模型低估的正是这部分排队时延。</p>\n<p>例子：一个 $S_{\\mathrm{kv}}$ 较大的模型（KV 头数多）配高分辨率图像，$N_{\\mathrm{vis}}$ 未压缩时单请求 KV 搬运量可达文本请求的数倍；此时即便 NVLink 域内带宽充裕，并发预填数一多，传输项也会成为时延主项。把视觉 token 压缩比提高一倍，预填项与传输项同时减半，是这类部署中性价比最高的动作。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-24\">二十四 · 定 SLO 与算例：反解压缩比下限</h3>\n<p>给定 SLO 与各池算力，最有用的反解是求满足时延的最大 $N_{\\mathrm{vis}}$，即视觉 token 压缩比的下限。把公式中与 $N_{\\mathrm{vis}}$ 相关的三项合并（编码项、预填项、传输项均线性于 $N_{\\mathrm{vis}}$），得到：</p>\n<div class=\"formula\">$$N_{\\mathrm{vis}}\\left(\\frac{d\\,L_{\\mathrm{vis}}}{F_{\\mathrm{vis}}\\eta}+\\frac{P_{\\mathrm{llm}}}{F_{\\mathrm{llm}}\\eta}+\\frac{S_{\\mathrm{kv}}\\,b_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}\\right)\\;\\le\\;T_{\\mathrm{SLO}}-T_{\\mathrm{fixed}}$$</div>\n<p>其中 $b_{\\mathrm{kv}}$ 是每视觉 token 对应的 KV 搬运块数，$T_{\\mathrm{fixed}}$ 是文本预填项与解码项之和。括号内三项分别是“每视觉 token 的编码代价、预填代价、传输代价”，三者相加就是单个视觉 token 的边际时延成本。这个量是压缩比决策的核心：压缩比每提高一倍（$N_{\\mathrm{vis}}$ 减半），时延按该边际成本线性下降；当某一项在括号中占主导时，压缩带来的收益主要来自那一项。</p>\n<p>算例（定性量级，不引用具体实验数）：设某多模态服务 SLO 为端到端数百毫秒级，$N_{\\mathrm{txt}}$ 中等、$N_{\\mathrm{out}}$ 较小，文本预填与解码合计占预算约一半，剩余预算由视觉相关三项分摊。若视觉编码项与预填项量级相当、传输项因跨节点 RDMA 而不可忽略，则括号内三项各占约三分之一。此时若把 $N_{\\mathrm{vis}}$ 减半，视觉相关时延整体减半，端到端时延下降约预算的四分之一；若只优化其中一项（例如换 NVLink 域内互联把传输项压到近零），端到端仅下降约预算的六分之一。结论：在这种配比下，提高压缩比是首选，互联升级是次选；反之若传输项占比过半，则应先解决拓扑（把预填与解码放进同一 NVLink 域，或改为同池部署）。</p>\n<p>算例的第二层是容量规划：由 $B_{\\max}$ 与 $B_{\\mathrm{mem}}$ 取小得到单副本并发，乘以副本数得解码池吞吐上限；再用预填池产出率与之匹配，得到整条服务链的 QPS 上限。若 QPS 需求超过该上限，扩池前必须先确认瓶颈项——若瓶颈是传输带宽，扩解码池无效；若瓶颈是 $B_{\\mathrm{mem}}$，扩显存或提压缩比有效；若瓶颈是 $t_{\\mathrm{dec}}(B)$ 的算力拐点，扩解码池副本有效。这个“先定位瓶颈项再扩容”的顺序，正是把 $T_{\\mathrm{e2e}}$ 用作决策工具而非预测工具的全部意义。</p>\n<p>最后落到工程判断：串行模型在 continuous batching 下会高估时延，因此用它定出的 $B_{\\max}$ 与压缩比下限偏保守；正确的用法是把它当作“上界估计器”——先据此定出资源下界与压缩比下限，再用实测的 chunked prefill 重叠率修正，把保守量折算成可接受的超额配置。压缩比与分池决策一旦按边际成本排序，扩容顺序就不再依赖经验。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-25\">二十五 · 反解压缩比与分池判据：公式在容量决策中的三个用法</h3>\n<p>给定 SLO 上限 $T_{\\mathrm{SLO}}$ 与两池算力，把公式对 $N_{\\mathrm{vis}}$ 反解，得到视觉 token 压缩比的下限：令视觉编码项与预填项中所有含 $N_{\\mathrm{vis}}$ 的系数合并为 $a=\\frac{d L_{\\mathrm{vis}}}{F_{\\mathrm{vis}}\\eta}+\\frac{P_{\\mathrm{llm}}}{F_{\\mathrm{llm}}\\eta}$，传输项系数为 $b=\\frac{S_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}$（按每视觉 token 对应一个 KV 块的搬运量计），则 $N_{\\mathrm{vis}}\\le\\frac{T_{\\mathrm{SLO}}-T_{\\mathrm{fixed}}}{a+b}$，其中 $T_{\\mathrm{fixed}}$ 是文本预填、解码与固定开销之和。这个式子的工程含义是：分母里 $a$ 与 $b$ 谁占主导，决定了压缩比该往哪个方向压——若 $b$ 已与 $a$ 同量级，说明跨池搬运 KV 的代价已与算视觉 token 本身相当，此时继续压 $N_{\\mathrm{vis}}$ 的边际收益被带宽项稀释，应当先改拓扑而不是改压缩比。算例：某请求 $N_{\\mathrm{txt}}=2\\mathrm{k}$、$N_{\\mathrm{out}}=256$，解码池在满足单步时延约束下取批大小 $B$，$t_{\\mathrm{dec}}(B)$ 随 $B$ 上升；若视觉编码项与预填项合计已占 SLO 的七成，则留给传输与解码的余量只剩三成，此时把 $N_{\\mathrm{vis}}$ 从高位压到低位带来的预填项近似减半，是唯一能在不动拓扑前提下把时延拉回 SLO 内的手段。</p>\n<p>分池判据不能只看解码池吞吐，而要把传输项与批处理收益放在同一量纲上比较。分池后解码池可独立加大 $B$，单请求解码时间从 $N_{\\mathrm{out}}t_{\\mathrm{dec}}(B_{\\mathrm{同池}})$ 降为 $N_{\\mathrm{out}}t_{\\mathrm{dec}}(B_{\\mathrm{分池}})$，收益为 $\\Delta_{\\mathrm{dec}}=N_{\\mathrm{out}}[t_{\\mathrm{dec}}(B_{\\mathrm{同池}})-t_{\\mathrm{dec}}(B_{\\mathrm{分池}})]$；代价是传输项 $\\frac{S_{\\mathrm{kv}}B_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}$ 从零变为正，且该项随 $N_{\\mathrm{vis}}$ 与 KV 头数线性增长。判据即 $\\Delta_{\\mathrm{dec}}&gt;\\frac{S_{\\mathrm{kv}}B_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}$。失效条件很具体：当视觉 token 膨胀使 $B_{\\mathrm{kv}}$ 变大、或模型 KV 头数多使 $S_{\\mathrm{kv}}$ 偏大时，传输项会吃掉全部分池收益，端到端时延反超同池部署，带宽成为瓶颈而非算力。此时正确的动作是回到同池，接受预填请求对解码的显存与算力争抢，改用排队模型评估而非继续扩容解码池。</p>\n<p>KV 预算的定法同样由该式给出边界。跨池传输要求 prefill 池在解码开始前把整段 KV 写出、decode 池读入，峰值显存占用约为 $2S_{\\mathrm{kv}}B_{\\mathrm{kv}}$（发送缓冲与接收缓冲各一份），这笔预算必须从 decode 池的 KV 池中预留，否则解码批大小 $B$ 会被压缩、$t_{\\mathrm{dec}}(B)$ 反而恶化。工程判断是：先按 SLO 定 $N_{\\mathrm{out}}$ 与 $t_{\\mathrm{dec}}(B)$ 的目标值，反推 decode 池可容纳的并发序列数，再扣除传输缓冲占用，剩余部分才是可用于 continuous batching 的 KV 预算；若扣除后并发数低于维持吞吐所需，说明该模型不该分池，或应降低 $N_{\\mathrm{vis}}$ 以减少单请求 KV 体积。</p>\n<table class=\"mini\"><thead><tr><th>决策项</th><th>由公式导出的约束</th><th>失效信号</th></tr></thead><tbody><tr><td>批大小 $B$</td><td>$N_{\\mathrm{out}}t_{\\mathrm{dec}}(B)$ 不超 SLO 余量</td><td>解码项随 $B$ 上升吞掉全部余量</td></tr><tr><td>并行度（是否分池）</td><td>$\\Delta_{\\mathrm{dec}}&gt;$ 传输项</td><td>传输项随 $N_{\\mathrm{vis}}$、KV 头数线性增长后反超</td></tr><tr><td>KV 预算</td><td>预留 $2S_{\\mathrm{kv}}B_{\\mathrm{kv}}$ 后仍够并发</td><td>缓冲挤占 KV 池致 $B$ 下降</td></tr><tr><td>压缩比下限</td><td>$N_{\\mathrm{vis}}\\le(T_{\\mathrm{SLO}}-T_{\\mathrm{fixed}})/(a+b)$</td><td>$b$ 与 $a$ 同量级，压缩边际收益被稀释</td></tr></tbody></table>\n<p>该式用于容量规划时必须显式标注其串行假设的偏差方向：continuous batching 让解码 token 与后续请求预填交错，串行叠加会系统性高估时延，据此扩容解码池属于过度配置；反之，视觉编码器多卡切分时若仍按单卡 $F_{\\mathrm{vis}}$ 估算，漏掉集合通信下界项，编码阶段时延被低估。两个偏差方向相反，工程上应把该式当作分池与否的判据与压缩比的反解工具，而不是精确预测器——用它定拓扑与压缩比，用实测或排队模型定批大小与池容量。</p>\n<h3 id=\"th-multimodal-prefill-decode-split-sec-26\">二十六 · 误用一：把串行式当预测器，忽略 continuous batching 重叠</h3>\n<p>最普遍的一类误用，是把四项串行叠加的 $T_{\\mathrm{e2e}}$ 直接当作生产环境的时延预测器。该式的结构决定了它天然假设“预填阶段完整结束后，解码阶段才开始”，而真实框架里 continuous batching 会把新请求的预填 token 与在途请求的解码 token 编入同一批次，两者在时间轴上交错而非串行。于是串行式给出的时延是上界，不是期望值。工程后果是系统性的：SLO 评估偏保守，容量规划把解码池按最坏串行时延扩容，而实际重叠后的时延远低于此，扩容预算被浪费在并不存在的瓶颈上。</p>\n<p>识别方法很直接：在目标框架里打开 chunked prefill，采集同一批请求的预填完成时刻与首 token 时刻，若首 token 时刻显著早于“预填项+传输项”之和，说明重叠已经发生，串行式不再适用。此时应把预填项与解码项合并为一个受批调度约束的排队模型，而不是继续相加。一个具体例子：视觉 token 压缩后 $N_{\\mathrm{vis}}$ 较大、$N_{\\mathrm{txt}}$ 较短的图文问答请求，串行式会把预填项算成一段独立墙钟时间，但在 chunked prefill 下这段计算被切块插入解码步之间的空隙，实际首 token 时延由解码步节奏而非预填总量决定。误用者据此判定“预填池是瓶颈、必须分池”，而真实瓶颈可能只是解码批大小选得过大导致 $t_{\\mathrm{dec}}(B)$ 偏高。</p>\n<p>代价落在吞吐与显存两侧：错误扩容解码池意味着更多 GPU 被闲置在低利用率区间，同时分池引入的 KV 传输项被无谓地激活。判断准则应写成条件式而非等式——串行式用于给出时延上界与分池必要性的保守判据，一旦实测首 token 时延低于上界某个显著比例，就必须切换到含重叠的模型，否则后续所有容量决策都建立在错误的基数上。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-27\">二十七 · 误用二：分池只算解码收益，漏掉 KV 传输项的增长阶</h3>\n<p>第二类误用出现在分池决策本身。工程师比较同池与分池两种拓扑时，往往只把解码池独立扩缩容带来的批处理收益计入分子，却把第三项 $\\frac{S_{\\mathrm{kv}}\\,B_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}$ 当作常数或可忽略的小量。问题在于这一项随视觉 token 数与 KV 头数线性增长：$N_{\\mathrm{vis}}$ 越大，需跨池搬运的 KV 块数 $B_{\\mathrm{kv}}$ 越多；模型 KV 头数越多，每 token 的 $S_{\\mathrm{kv}}$ 越大。两项相乘，传输项在长视觉上下文场景下会迅速吃掉分池收益。</p>\n<p>后果是带宽成为瓶颈、端到端时延反超同池部署。识别信号是：分池后解码池的 GPU 利用率上升但端到端时延没有下降，甚至上升；链路带宽利用率接近饱和而解码池算力利用率仍有富余。这说明瓶颈已从算力转移到互联。此时应做的不是加大解码池，而是回退到同池部署，或先把视觉 token 压缩比调低以缩小 $B_{\\mathrm{kv}}$。</p>\n<p>一个具体例子：高分辨率文档理解请求，压缩后 $N_{\\mathrm{vis}}$ 仍显著高于纯文本 prompt，分池部署下每个请求的 KV 块需要经 NVLink 或 RDMA 从预填池搬到解码池。若链路带宽被多个并发请求的 KV 传输共享，单请求传输时间随并发度上升，串行式里那个看似固定的第三项实际上是被低估的。工程判断应写成：只有当解码池批处理收益的增量大于传输项在目标并发度下的实测值，分池才成立；而这个比较必须在峰值并发而非单请求条件下做。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-28\">二十八 · 误用三：视觉编码器多卡切分仍按单卡算力估算</h3>\n<p>第三类误用针对第一项。视觉编码器被切分到多卡时，编码阶段内部存在集合通信，串行式只除以单卡 $F_{\\mathrm{vis}}$，漏掉了通信下界。后果是编码阶段时延被系统性低估，进而把预填池规模估小、把分池收益估大。识别方法：对比单卡与多卡切分下视觉编码的实测墙钟时间，若多卡加速比明显低于卡数，差额即为通信开销；此时第一项应改写为算力项与通信下界项的叠加，而非单纯缩小分母。</p>\n<p>代价体现在预填池的容量规划上：低估编码时间意味着预填池被配置得过小，在视觉请求占比高的负载下预填池成为排队瓶颈，端到端时延的长尾被拉长。一个具体例子：把视觉编码器按层切到多卡，层间需传递隐藏状态，隐藏维 $d$ 越大、切分越细，通信量越大；当 $d$ 与 $L_{\\mathrm{vis}}$ 的组合使通信时间与单层计算时间同量级时，增加卡数不再缩短编码墙钟时间。此时正确的动作是减少切分粒度或改用单卡大 batch，而不是继续加卡。</p>\n<p>该误用与第一类误用叠加时最危险：串行式高估整体时延，编码项又被低估，两个误差方向相反，使分池决策的符号判断失去意义。工程上应把编码项单独标定——用实测的编码墙钟时间替换公式第一项，再代入其余三项做拓扑比较。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-29\">二十九 · 反例：一次把串行式当精确预测器的分池扩容</h3>\n<p>构造一个反例说明误用链条如何闭合。场景是图文混合负载，视觉请求占比不低，团队按串行式算出 $T_{\\mathrm{e2e}}$ 超出 SLO，判定预填池是瓶颈，决定把视觉编码器与 LLM 解码器分池，并为解码池扩容以提升批大小 $B$。三步误用依次发生：第一，串行式未扣除 chunked prefill 重叠，预填项被高估，分池必要性被夸大；第二，分池后未把 KV 传输项按峰值并发重新标定，$B_{\\mathrm{kv}}$ 随并发线性上升，链路带宽饱和；第三，视觉编码器已切分到多卡，第一项仍按单卡算力估算，预填池实际能力低于账面。</p>\n<p>结果是解码池扩容后 GPU 利用率上升、吞吐名义上提高，但端到端时延不降反升：KV 传输在链路上排队，首 token 时延的长尾被拉长，SLO 违约率上升。此时团队的直觉反应是继续扩容解码池，而这只会加剧传输拥塞，形成正反馈式的错误扩容。</p>\n<p>正确的诊断顺序是反向的：先测首 token 时延与串行式上界的比值，确认重叠程度；再测链路带宽利用率与解码池算力利用率，判断瓶颈位置；最后用实测编码墙钟时间替换第一项。若链路利用率高而算力有富余，回退同池或降低视觉 token 压缩比；若编码项被低估，减少视觉编码器切分粒度。反例的教训不是“不要分池”，而是分池决策必须建立在标定过的四项之上，任何一项用未校正的公式值代入，都会让拓扑比较的符号翻转。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-30\">三十 · 识别清单：把误用挡在决策之前</h3>\n<p>把上述三类误用收敛成可执行的识别清单，每条对应一个可观测信号与一个纠正动作。</p>\n<ul>\n<li>信号：实测首 token 时延显著低于串行式预填项与传输项之和。纠正：启用含重叠的排队模型，串行式仅保留为上界判据。</li>\n<li>信号：分池后链路带宽利用率接近饱和而解码池算力利用率有富余。纠正：按峰值并发重算 $B_{\\mathrm{kv}}$，比较传输项与批处理收益，必要时回退同池。</li>\n<li>信号：视觉编码器多卡加速比明显低于卡数。纠正：用实测编码墙钟时间替换第一项，或降低切分粒度。</li>\n<li>信号：视觉 token 压缩比下调后预填项未按比例下降。纠正：检查是否把 $N_{\\mathrm{vis}}$ 的压缩后值误用为压缩前值，压缩比直接线性缩放预填项，误用会使压缩收益被低估。</li>\n<li>信号：解码池批大小 $B$ 上调后单步时延 $t_{\\mathrm{dec}}(B)$ 超出 SLO 余量。纠正：在 SLO 约束下反解最大 $B$，而非按吞吐最大化选批。</li>\n</ul>\n<p>清单的共同点是：每条都要求用实测值替换公式中的某一项，而不是在公式内部做代数变形。公式的价值在于给出各项的量级与增长阶，误用的根源在于把量级估计当成精确预测。工程判断应落在“哪一项需要标定、标定后符号是否翻转”上，而不是追求公式本身的数值精度。</p>\n\n<h3 id=\"th-multimodal-prefill-decode-split-sec-31\">三十一 · 把串行式当预言机：三类误用与一个带宽反例</h3>\n<p>最常见的误用是把四项串行叠加当成生产环境的时延预言机。该式的适用边界写得很清楚：它假设预填与解码完全串行、无 chunked prefill 重叠，也未建模视觉编码器与 LLM 预填之间的流水并行。而实际框架的 continuous batching 会让解码 token 与后续请求的预填交错执行，解码池在等待 KV 到达的间隙里并非空转。于是串行式系统性高估 <span class=\"inline-math\">$T_{\\mathrm{e2e}}$</span>，工程上表现为 SLO 评估偏保守、误判分池必要性，进而错误扩容解码池——扩容本身不缩短单请求时延，只是把批大小 <span class=\"inline-math\">$B$</span> 抬高，而 <span class=\"inline-math\">$t_{\\mathrm{dec}}(B)$</span> 随 <span class=\"inline-math\">$B$</span> 上升，单步时延反而变差。识别方法很直接：拿线上 trace 的预填完成时刻与首 token 发出时刻做差，若实测首 token 时延显著低于公式给出的“编码+预填”两项之和，说明重叠已经发生，此时应改用排队模型而非串行式做容量判断。</p>\n<p>第二类误用发生在视觉编码器多卡切分时：仍按单卡 <span class=\"inline-math\">$F_{\\mathrm{vis}}$</span> 估算第一项 <span class=\"inline-math\">$\\frac{N_{\\mathrm{vis}}\\,d\\,L_{\\mathrm{vis}}}{F_{\\mathrm{vis}}\\,\\eta}$</span>。切分后编码阶段内部存在集合通信，分子不变而有效算力被通信下界截断，实际编码墙钟时间被低估。第三类误用是分池决策只算收益不算成本：只看到解码池可独立加大 <span class=\"inline-math\">$B$</span> 提升吞吐，却忽略第三项 <span class=\"inline-math\">$\\frac{S_{\\mathrm{kv}}\\,B_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}$</span> 随视觉 token 数与 KV 头数线性增长。下面这个反例把三类误用叠在一起。</p>\n<table class=\"mini\"><thead><tr><th>反例环节</th><th>误用做法</th><th>系统代价</th></tr></thead><tbody><tr><td>时延预测</td><td>串行式直接套 continuous batching 生产流量</td><td>高估时延，误扩解码池，单步时延随 <span class=\"inline-math\">$B$</span> 恶化</td></tr><tr><td>编码估算</td><td>视觉编码器 4 卡切分仍按单卡 <span class=\"inline-math\">$F_{\\mathrm{vis}}$</span> 计</td><td>编码阶段漏算集合通信下界，首 token 时延被低估</td></tr><tr><td>分池决策</td><td>只计解码吞吐收益，不计 KV 跨池传输</td><td>带宽成为瓶颈，端到端时延反超同池部署</td></tr></tbody></table>\n<p>反例的具体形态：某多模态服务把视觉编码器与 LLM 解码器物理分池，视觉 token 压缩比设得偏松，<span class=\"inline-math\">$N_{\\mathrm{vis}}$</span> 较大，KV 头数也多，于是 <span class=\"inline-math\">$S_{\\mathrm{kv}}\\,B_{\\mathrm{kv}}$</span> 随请求量线性膨胀，<span class=\"inline-math\">$\\mathrm{BW}_{\\mathrm{link}}$</span> 在 NVLink 或 RDMA 上被打满。此时解码池虽然批大小更大、吞吐账面更好，但每个请求都要等 KV 块搬运完成才能起步，第三项吃掉了分池带来的批处理收益，端到端时延反超同池部署。工程判断应落在不等式上：分池收益 ≈ 解码池吞吐提升带来的排队时延下降，只有当它大于传输项 <span class=\"inline-math\">$\\frac{S_{\\mathrm{kv}}\\,B_{\\mathrm{kv}}}{\\mathrm{BW}_{\\mathrm{link}}}$</span> 与编码集合通信下界之和时才值得分池；否则应回到同池部署，用排队模型处理预填与解码的显存、算力争抢。反过来，若给定 SLO，可由该式反解满足时延的最大 <span class=\"inline-math\">$N_{\\mathrm{vis}}$</span>，得到视觉 token 压缩比下限——压缩比每降一半，预填项近似减半，这是比分池更可靠的杠杆。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>N_{\\mathrm{vis}}</td><td>每请求视觉 token 数（压缩后）</td></tr><tr><td>N_{\\mathrm{txt}}</td><td>每请求文本 prompt token 数</td></tr><tr><td>N_{\\mathrm{out}}</td><td>生成输出 token 数</td></tr><tr><td>S_{\\mathrm{kv}}</td><td>每 token 的 KV cache 字节数（含 KV 头数与层数）</td></tr><tr><td>B_{\\mathrm{kv}}</td><td>跨池传输的 KV 块数</td></tr><tr><td>\\mathrm{BW}_{\\mathrm{link}}</td><td>prefill 池与 decode 池之间的互联带宽（NVLink 或 RDMA）</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-multimodal-prefill-decode-split · 共 5 个片段</p>\n"},{"id":"th-multimodal-quant-error-bound","title":"多模态量化误差传播界","direction":"dir-vision-encoder-latency","prereq":[],"plain":"视觉编码器与 LLM 分别量化时，视觉侧量化误差会经跨模态投影放大后注入语言模型，总输出误差由视觉量化噪声、投影矩阵增益与 LLM 量化噪声三项叠加；该界说明不能对视觉编码器和 LLM 独立选比特宽，视觉侧往往需要更高精度或保留异常值通道，否则语言侧再省也补不回来。","definition":"视觉编码器与 LLM 分别量化时，视觉侧量化误差会经跨模态投影放大后注入语言模型，总输出误差由视觉量化噪声、投影矩阵增益与 LLM 量化噪声三项叠加；该界说明不能对视觉编码器和 LLM 独立选比特宽，视觉侧往往需要更高精度或保留异常值通道，否则语言侧再省也补不回来。","formula":"$$\\left\\|\\,\\hat{y}-y\\,\\right\\|_2 \\;\\le\\; \\left\\|W_{\\mathrm{proj}}\\right\\|_2\\cdot\\left\\|\\Delta_{\\mathrm{vis}}\\right\\|_2 \\;+\\; \\left\\|\\Delta_{\\mathrm{llm}}\\right\\|_2\\cdot\\left\\|h_{\\mathrm{vis}}\\right\\|_2 \\;+\\; \\frac{\\Delta_q^2}{12}\\cdot\\mathrm{tr}\\!\\left(W_{\\mathrm{proj}}^{\\top}W_{\\mathrm{proj}}\\right)$$","variables":[{"sym":"\\Delta_{\\mathrm{vis}}","meaning":"视觉编码器输出量化误差向量"},{"sym":"\\Delta_{\\mathrm{llm}}","meaning":"LLM 权重/激活量化误差"},{"sym":"W_{\\mathrm{proj}}","meaning":"视觉到语言空间的投影矩阵"},{"sym":"h_{\\mathrm{vis}}","meaning":"投影后的视觉嵌入"},{"sym":"\\Delta_q","meaning":"量化步长"},{"sym":"\\hat{y},y","meaning":"量化后与全精度输出"}],"derivation":"第二项 $$\\|\\Delta_{\\mathrm{llm}}\\|_2\\cdot\\|h_{\\mathrm{vis}}\\|_2$$ 中，$\\Delta_{\\mathrm{llm}}$ 为 LLM 权重/激活量化误差，$h_{\\mathrm{vis}}$ 为投影后的视觉嵌入；含义是 LLM 量化噪声与视觉嵌入幅值相乘，视觉 token 激活幅值越大，同等 LLM 量化误差造成的绝对偏差越大。","example":"推导关键一步：把视觉量化误差经线性投影传播到语言空间，用算子范数界定最坏放大，再叠加 LLM 侧量化噪声与均匀量化方差项；该界仅对线性投影后的嵌入误差成立，当跨模态融合使用 cross-attention 的 softmax 门控时，注意力归一化会非线性放大或抑制误差，线性界不再直接适用。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["该界基于均匀量化噪声方差 Δ_q²/12 的假设；AWQ/GPTQ 等权重量化会保留显著通道，实际噪声非均匀，界会偏保守。","仅对线性投影后的嵌入误差成立；当跨模态融合使用 cross-attention 的 softmax 门控时，量化误差会被注意力归一化非线性放大或抑制，线性界不再直接适用。","未建模激活量化（如 SmoothQuant 的通道缩放）对视觉 token 动态范围的影响；视觉 token 的激活异常值远大于文本 token，独立校准的激活量化误差可能超出该界。"],"system_note":"失效条件：AWQ/GPTQ 等权重量化保留显著通道，噪声非均匀，均匀方差界偏保守；未建模激活量化（如 SmoothQuant 通道缩放）对视觉 token 动态范围的影响，视觉 token 激活异常值远大于文本 token，独立校准的激活量化误差可能超出该界。","papers":["paper-an-image-is-worth-16x16-words-transf-2020"],"facts":["直觉：视觉编码器与 LLM 分别量化时，视觉侧误差会经跨模态投影矩阵放大后注入语言模型，总输出误差由视觉量化噪声、投影增益与 LLM 量化噪声三项叠加；因此不能对两侧独立选比特宽，视觉侧常需更高精度或保留异常值通道。","第一项 $$\\|W_{\\mathrm{proj}}\\|_2\\cdot\\|\\Delta_{\\mathrm{vis}}\\|_2$$ 中，$\\Delta_{\\mathrm{vis}}$ 是视觉编码器输出量化误差向量，$\\|W_{\\mathrm{proj}}\\|_2$ 是视觉到语言空间投影矩阵的谱范数，即最大增益方向；含义是视觉误差按投影矩阵最坏增益放大后进入语言空间，投影权重越大视觉侧越不能省比特。","第二项 $$\\|\\Delta_{\\mathrm{llm}}\\|_2\\cdot\\|h_{\\mathrm{vis}}\\|_2$$ 中，$\\Delta_{\\mathrm{llm}}$ 为 LLM 权重/激活量化误差，$h_{\\mathrm{vis}}$ 为投影后的视觉嵌入；含义是 LLM 量化噪声与视觉嵌入幅值相乘，视觉 token 激活幅值越大，同等 LLM 量化误差造成的绝对偏差越大。","第三项 $$\\frac{\\Delta_q^2}{12}\\cdot\\mathrm{tr}\\!\\left(W_{\\mathrm{proj}}^{\\top}W_{\\mathrm{proj}}\\right)$$ 来自均匀量化噪声方差 $\\Delta_q^2/12$ 假设，$\\Delta_q$ 为量化步长，迹项是投影矩阵各方向增益平方和；含义是量化噪声在投影后各通道上的总功率，步长减半该项降为四分之一。","推导关键一步：把视觉量化误差经线性投影传播到语言空间，用算子范数界定最坏放大，再叠加 LLM 侧量化噪声与均匀量化方差项；该界仅对线性投影后的嵌入误差成立，当跨模态融合使用 cross-attention 的 softmax 门控时，注意力归一化会非线性放大或抑制误差，线性界不再直接适用。","失效条件：AWQ/GPTQ 等权重量化保留显著通道，噪声非均匀，均匀方差界偏保守；未建模激活量化（如 SmoothQuant 通道缩放）对视觉 token 动态范围的影响，视觉 token 激活异常值远大于文本 token，独立校准的激活量化误差可能超出该界。","用途：在给定总误差预算下分配比特宽——先看 $\\|W_{\\mathrm{proj}}\\|_2$ 与迹项决定视觉侧最低比特，再看 $\\|h_{\\mathrm{vis}}\\|_2$ 决定 LLM 侧激活量化是否需保留异常值通道；也可用于判断视觉编码器是否必须保留 FP16 异常值通道而非统一 INT8。","误用：对视觉编码器与 LLM 独立选比特宽、各自按文本校准集调参，忽略投影增益与视觉激活动态范围，导致语言侧再省也补不回视觉侧误差。"],"anchors":[],"pitfalls":["视觉编码器与 LLM 分别独立量化并各自用文本校准集调参，忽略投影矩阵谱范数放大，最终输出误差被视觉侧主导。","把均匀量化方差界当作精确误差预测，在 AWQ/GPTQ 保留显著通道的非均匀噪声下过度保守，错失可省的比特宽。","对视觉 token 沿用文本 token 的激活量化校准，未处理其远大于文本的异常值动态范围，激活量化误差超出该界、跨模态对齐退化。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-1\">一 · 一句话直觉：误差不是相加，是被投影&quot;称重&quot;后相加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-2\">二 · 严格定义：三项各自的来源与量纲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-3\">三 · 为什么需要这个界：比特宽分配不能靠试</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-4\">四 · 常见误解：独立选比特宽、把界当预测、沿用文本校准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-5\">五 · 失效条件的工程读法：什么时候不该信这个界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-6\">六 · 误差界的适用边界：从线性投影到非均匀噪声</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-7\">七 · 三项的物理量纲与叠加结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-8\">八 · 从线性传播到算子范数：推导的关键一步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-9\">九 · Δ_q²/12 从哪来，离散化在哪一步发生</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-10\">十 · 失效条件的数学根源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-11\">十一 · 用界做比特分配的推导顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-12\">十二 · 三条假设：界成立的前提被逐条钉死</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-13\">十三 · 失效条件一：softmax 门控把线性界撕开</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-14\">十四 · 失效条件二：激活异常值让独立校准失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-15\">十五 · 规模上限：什么时候界随规模失去约束力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-16\">十六 · 工程判定：把界当筛选器而非预测器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-17\">十七 · 边界之外：线性界在何处失效，以及工程上如何兜底</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-18\">十八 · 把界拆成可分配的三份预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-19\">十九 · 用第一项定视觉侧最低比特与并行度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-20\">二十 · 用第二项与第三项定 KV 预算与批大小</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-21\">二十一 · 把界接到 SLO 上：误差预算与时延预算的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-22\">二十二 · 界的保守性与决策中的修正项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-23\">二十三 · 把误差界换算成容量决策：批大小、并行度与 KV 预算的取舍边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-24\">二十四 · 误用的共同结构：把界当成可分解的独立预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-25\">二十五 · 反例：视觉 INT8 统一量化 + 语言侧激进低比特</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-26\">二十六 · 第二类误用：把均匀方差界当精确预测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-27\">二十七 · 第三类误用：线性界套到 softmax 门控融合上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-28\">二十八 · 识别清单与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-multimodal-quant-error-bound-sec-29\">二十九 · 当界被当成开关：三类误用、一个反例与识别信号</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:568px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 567.9 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"485.9\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"485.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：视觉编码器与 LLM 分别量化时，视觉侧量化误差会经跨模态投影放大…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"485.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\left\\|\\,\\hat{y}-y\\,\\right\\|_2 …</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"485.9\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：该界基于均匀量化噪声方差 Δ_q²/12 的假设；AWQ/GPTQ…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-multimodal-quant-error-bound-sec-1\">一 · 一句话直觉：误差不是相加，是被投影\"称重\"后相加</h3>\n<p>把视觉编码器和 LLM 看成两级串联的放大器：视觉侧量化产生的扰动 <code>Δ_vis</code> 不会原样进入语言模型，它必须先穿过跨模态投影矩阵 <code>W_proj</code>。投影矩阵的谱范数 <code>‖W_proj‖₂</code> 就是这条通路上的最大增益方向——视觉侧一个单位的误差，到了语言空间可能被放大成 <code>‖W_proj‖₂</code> 个单位。与此同时，LLM 自身的量化噪声 <code>Δ_llm</code> 也不是孤立起作用的，它乘在视觉嵌入 <code>h_vis</code> 的幅值上：视觉 token 的激活越\"响\"，同样的权重扰动造成的绝对偏差越大。所以总误差界不是一个\"视觉误差 + 语言误差\"的简单和，而是三项各自带不同权重的叠加：视觉噪声被投影增益加权、语言噪声被视觉嵌入幅值加权、再加上量化步长在投影各通道上的功率积分。一句话直觉的工程含义是：<strong>两侧的比特宽不是两个独立旋钮，而是一根被投影矩阵耦合起来的杠杆</strong>。</p>\n<p>这个直觉直接推翻了一种常见的省法：把视觉编码器压到 INT8、LLM 也压到 INT8，各自用文本校准集调好参数，看起来两边都省了。但只要 <code>‖W_proj‖₂</code> 较大，视觉侧的量化噪声就会在进入语言空间时被放大，语言侧再怎么精细量化也补不回来——因为误差已经在上游被\"称\"过一次了。推理系统上，这表现为一个反直觉的显存账：视觉编码器的权重占比通常远小于 LLM，省它的比特宽带来的显存收益有限，但它对输出误差的边际贡献却可能被投影增益放大到主导地位。于是\"省小头、赔大头\"成为多模态量化最典型的代价结构。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-2\">二 · 严格定义：三项各自的来源与量纲</h3>\n<p>把输出误差定义为量化后输出与全精度输出的 L2 距离 <code>‖ŷ − y‖₂</code>，则该界写成：</p>\n<div class=\"formula\">$$\\left\\|\\,\\hat{y}-y\\,\\right\\|_2 \\;\\le\\; \\left\\|W_{\\mathrm{proj}}\\right\\|_2\\cdot\\left\\|\\Delta_{\\mathrm{vis}}\\right\\|_2 \\;+\\; \\left\\|\\Delta_{\\mathrm{llm}}\\right\\|_2\\cdot\\left\\|h_{\\mathrm{vis}}\\right\\|_2 \\;+\\; \\frac{\\Delta_q^2}{12}\\cdot\\mathrm{tr}\\!\\left(W_{\\mathrm{proj}}^{\\top}W_{\\mathrm{proj}}\\right)$$</div>\n<p>逐项拆开看量纲与来源。第一项 <code>‖W_proj‖₂·‖Δ_vis‖₂</code>：<code>Δ_vis</code> 是视觉编码器输出端的量化误差向量，<code>‖W_proj‖₂</code> 是投影矩阵的谱范数（最大奇异值），即最坏情况下的增益。这一项回答的是\"视觉误差最坏能被放大多少倍后注入语言空间\"。第二项 <code>‖Δ_llm‖₂·‖h_vis‖₂</code>：<code>Δ_llm</code> 是 LLM 权重或激活的量化误差，<code>h_vis</code> 是投影后的视觉嵌入，两者相乘意味着语言侧的相对扰动被视觉嵌入的绝对幅值放大。第三项 <code>(Δ_q²/12)·tr(W_projᵀW_proj)</code>：来自均匀量化噪声方差 <code>Δ_q²/12</code> 的假设，迹项是投影矩阵各方向增益平方和，度量量化噪声在投影后所有通道上的总功率。注意第三项对步长是二次依赖——步长减半，该项降为四分之一，这解释了为什么把视觉侧从 INT8 提到 FP8/FP16 的收益是非线性的。</p>\n<p>推导的关键一步是把视觉量化误差经线性投影传播到语言空间，用算子范数界定最坏放大，再叠加 LLM 侧噪声与均匀量化方差项。这个结构决定了界的适用边界：它只对<strong>线性投影后的嵌入误差</strong>成立。一旦跨模态融合改用 cross-attention 的 softmax 门控，注意力归一化会对误差做非线性放大或抑制，线性界不再直接适用——这是定义层面就必须记住的适用范围，而不是事后补丁。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-3\">三 · 为什么需要这个界：比特宽分配不能靠试</h3>\n<p>没有这个界，多模态量化的比特宽选择只能靠网格搜索：视觉侧试 INT8/FP8/FP16，语言侧试 INT4/INT8，组合爆炸且每个组合都要跑端到端评测。有了界，分配问题变成一个有结构的优化：给定总误差预算 <code>ε</code>，先看 <code>‖W_proj‖₂</code> 与迹项决定视觉侧的最低比特，再看 <code>‖h_vis‖₂</code> 决定 LLM 侧激活量化是否需要保留异常值通道。这是一个\"先定上游、再定下游\"的顺序，而不是两侧并行调参。</p>\n<p>具体例子：某 VLM 的投影矩阵谱范数明显大于 1（跨模态对齐时视觉特征被放大到语言嵌入空间），此时第一项主导。若视觉编码器统一压到 INT8，<code>‖Δ_vis‖₂</code> 随步长线性增长，再乘上谱范数，误差预算很快被吃光；而把 LLM 从 INT8 降到 INT4 省下的显存，远不足以抵消视觉侧误差的放大。反过来，如果 <code>‖h_vis‖₂</code> 很大（视觉 token 激活幅值高），第二项主导，此时该优先在 LLM 激活量化上保留异常值通道，而不是继续压视觉侧。这个界给出的正是这种\"哪一项在主导\"的判断依据，把调参从盲试变成看项定策。</p>\n<p>系统代价上，这个界直接影响显存与带宽的分配决策：视觉编码器保留 FP16 异常值通道意味着它的权重与激活占用翻倍，但相比 LLM 的 KV cache 与权重，这部分增量通常可控；而如果误判导致视觉侧误差主导，端到端质量退化无法通过增加语言侧精度挽回，等于白白多花了语言侧的高精度显存。吞吐侧同理：视觉侧高精度带来的算力开销集中在预填阶段，而语言侧解码阶段的比特宽才是持续吞吐的关键——界帮助判断哪一侧的精度投入能真正换回质量。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-4\">四 · 常见误解：独立选比特宽、把界当预测、沿用文本校准</h3>\n<p>误解一：<strong>对视觉编码器与 LLM 独立选比特宽</strong>。这是最普遍的误用——两侧各自按文本校准集调参，忽略投影增益与视觉激活动态范围。后果是输出误差被视觉侧主导，语言侧再省也补不回。界的结构本身就在说：<code>W_proj</code> 把两侧耦合在一起，独立优化等于忽略了第一项里的谱范数乘子。</p>\n<p>误解二：<strong>把均匀量化方差界当作精确误差预测</strong>。第三项建立在 <code>Δ_q²/12</code> 的均匀噪声假设上，但 AWQ/GPTQ 等权重量化会保留显著通道，实际噪声是非均匀的。此时界会偏保守——它给出的是上界而非估计值。把上界当预测会导致过度保守，错失本可省的比特宽。正确用法是把它当\"最坏情况护栏\"，在非均匀量化下用它判断哪一项仍占主导，而不是用它精确反推每层比特。</p>\n<p>误解三：<strong>对视觉 token 沿用文本 token 的激活量化校准</strong>。视觉 token 的激活异常值远大于文本 token，独立校准的激活量化误差可能超出该界。界里没有显式建模激活量化（如 SmoothQuant 的通道缩放）对视觉 token 动态范围的影响，这意味着当视觉激活异常值未被处理时，实际误差会突破界的预测——界失效不是因为公式错，而是因为假设被违反。工程判断是：视觉 token 的激活校准必须单独做，不能复用文本校准集。</p>\n<table class=\"mini\"><thead><tr><th>误解</th><th>违反的界假设</th><th>系统后果</th></tr></thead><tbody><tr><td>两侧独立选比特宽</td><td>忽略 <code>‖W_proj‖₂</code> 耦合项</td><td>视觉侧误差主导，语言侧高精度显存白花</td></tr><tr><td>把界当精确预测</td><td>均匀噪声假设 vs 非均匀保留通道</td><td>过度保守，错失可省比特宽</td></tr><tr><td>沿用文本激活校准</td><td>未建模视觉激活异常值</td><td>激活量化误差超界，跨模态对齐退化</td></tr></tbody></table>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-5\">五 · 失效条件的工程读法：什么时候不该信这个界</h3>\n<p>界有三条明确的失效条件，每一条都对应一种具体的推理形态。第一条：AWQ/GPTQ 保留显著通道导致噪声非均匀，均匀方差界偏保守——这在 LLM 侧权重量化中几乎必然发生，所以第三项只能当护栏用。第二条：仅对线性投影后的嵌入误差成立，cross-attention 的 softmax 门控会非线性放大或抑制误差——采用 cross-attention 融合的 VLM（而非简单线性投影拼接）不能直接套用此界，需要重新界定门控对误差的传递。第三条：未建模激活量化对视觉 token 动态范围的影响，视觉 token 激活异常值远大于文本 token，独立校准的激活量化误差可能超出该界——这是视觉侧特有的风险，也是\"视觉侧往往需要更高精度或保留异常值通道\"这一结论的直接来源。</p>\n<p>工程上判断是否该信这个界，看三个信号：投影是否为线性、量化是否为均匀、激活校准是否与文本分离。三者都满足时，界是可靠的比特宽分配依据；任一不满足时，界退化为定性指引——它仍能告诉你\"视觉侧误差会被投影放大\"这个方向性事实，但不能用来精确反推每层比特。这种\"方向可信、数值存疑\"的读法，比把界当万能公式更符合它在推理系统中的实际角色。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-6\">六 · 误差界的适用边界：从线性投影到非均匀噪声</h3>\n\n<p>这个界真正有用的地方不在于给出一个精确误差预测，而在于它把“视觉侧能不能省比特”变成可判定的工程问题。三项中第一项 <span>\\(\\|W_{\\mathrm{proj}}\\|_2\\cdot\\|\\Delta_{\\mathrm{vis}}\\|_2\\)</span> 由投影矩阵谱范数决定最坏增益方向，第三项 <span>\\(\\frac{\\Delta_q^2}{12}\\cdot\\mathrm{tr}(W_{\\mathrm{proj}}^{\\top}W_{\\mathrm{proj}})\\)</span> 则把步长与各方向增益平方和绑定：步长减半，该项降为四分之一。这意味着视觉编码器量化步长的选择不是与 LLM 并列的自由参数，而是被投影矩阵的增益结构锁定——投影权重越大，视觉侧越不能省比特。代价上，视觉侧每多保留一档精度，视觉编码器前向的显存带宽与算力占用随之上升，而这段开销发生在预填阶段、直接计入首 token 延迟，无法靠解码侧的连续批处理摊薄。</p>\n\n<p>失效条件必须写清楚，否则这个界会被当成通用误差预测使用。其一，界建立在均匀量化噪声方差 <span>\\(\\Delta_q^2/12\\)</span> 的假设上；AWQ/GPTQ 一类权重量化保留显著通道，噪声分布非均匀，此时界偏保守，会高估视觉侧所需比特宽，让本可省的通道被白白保留。其二，界只对线性投影后的嵌入误差成立；一旦跨模态融合走 cross-attention 的 softmax 门控，注意力归一化会非线性地放大或抑制误差，线性界不再直接适用，此时需要按融合层的实际门控行为重新界定。其三，界未建模激活量化（如 SmoothQuant 通道缩放）对视觉 token 动态范围的影响——视觉 token 的激活异常值远大于文本 token，沿用文本校准集独立调参，激活量化误差会超出该界，表现为跨模态对齐退化而非单纯数值偏差。</p>\n\n<p>工程判断落在比特宽分配的顺序上。给定总误差预算，先由 <span>\\(\\|W_{\\mathrm{proj}}\\|_2\\)</span> 与迹项确定视觉侧最低比特，再由 <span>\\(\\|h_{\\mathrm{vis}}\\|_2\\)</span> 判断 LLM 侧激活量化是否需要保留异常值通道：视觉嵌入幅值越大，同等 LLM 量化误差造成的绝对偏差越大，第二项 <span>\\(\\|\\Delta_{\\mathrm{llm}}\\|_2\\cdot\\|h_{\\mathrm{vis}}\\|_2\\)</span> 随之抬升。典型误用是对视觉编码器与 LLM 各自按文本校准集独立选比特宽，忽略投影增益与视觉激活动态范围，结果是输出误差被视觉侧主导，语言侧再省也补不回来。反过来，若把该界当作精确预测、在非均匀噪声下过度保守，则会错失可省的比特宽，付出不必要的显存与带宽代价。判断准则应是把界当作上界筛子：用它排除明显不可行的比特组合，再用实测校准集在剩余组合中定档。</p>\n\n<table class=\"mini\"><thead><tr><th>项</th><th>主导变量</th><th>系统代价落点</th><th>失效触发</th></tr></thead><tbody><tr><td>投影放大项</td><td>\\(\\|W_{\\mathrm{proj}}\\|_2\\)</td><td>视觉侧精度→预填首 token 延迟</td><td>投影增益被低估</td></tr><tr><td>LLM 噪声项</td><td>\\(\\|h_{\\mathrm{vis}}\\|_2\\)</td><td>激活异常值通道→解码显存带宽</td><td>视觉嵌入幅值被忽略</td></tr><tr><td>均匀方差项</td><td>\\(\\Delta_q\\)、迹</td><td>步长减半→该项四分之一</td><td>AWQ/GPTQ 非均匀噪声</td></tr></tbody></table>\n<h3 id=\"th-multimodal-quant-error-bound-sec-7\">七 · 三项的物理量纲与叠加结构</h3>\n<p>把界写成三项相加的形式，本身就是一次建模决策：它假定视觉侧误差与语言侧误差在输出空间近似正交叠加，取的是最坏情况下的三角不等式放缩，而非统计意义上的方差合成。三项各自带不同的量纲来源，读公式时先分清谁乘谁，才能判断哪一项在实际部署中主导。</p>\n<p>第一项 ‖W_proj‖₂·‖Δ_vis‖₂ 是“增益×源噪声”：Δ_vis 活在视觉编码器的输出空间（patch 嵌入维度），W_proj 把它搬到语言嵌入空间，谱范数给出该线性映射在所有方向上的最大拉伸倍数。第二项 ‖Δ_llm‖₂·‖h_vis‖₂ 是“噪声×信号幅值”：Δ_llm 是 LLM 权重或激活的量化扰动，作用在已经投影后的视觉嵌入 h_vis 上，因此绝对偏差随 h_vis 的幅值线性增长——视觉 token 的激活幅值天然高于文本 token，这一项对视觉 token 格外不利。第三项 (Δ_q²/12)·tr(W_projᵀW_proj) 是“噪声功率×总增益功率”：迹项等于 W_proj 全部奇异值的平方和，即 Frobenius 范数的平方，衡量的是各通道量化噪声投影后的功率总和，而非最坏方向。</p>\n<p>工程含义直接：第一项与第三项都由 W_proj 的谱性质决定，但一个是 max 型（最坏方向），一个是 sum 型（平均功率）。当 W_proj 的奇异值谱平坦时两者接近；当谱严重倾斜（少数方向增益极大）时，第一项远大于按平均功率估算的第三项，此时按迹项做比特分配会低估视觉侧需求。判断投影矩阵是否“病态放大”，看谱范数与 Frobenius 范数之比即可，比值越大越不能只信迹项。</p>\n<div class=\"formula\">$$\\kappa_{\\mathrm{gain}}=\\frac{\\|W_{\\mathrm{proj}}\\|_2}{\\|W_{\\mathrm{proj}}\\|_F},\\qquad \\|W_{\\mathrm{proj}}\\|_F^2=\\mathrm{tr}\\!\\left(W_{\\mathrm{proj}}^{\\top}W_{\\mathrm{proj}}\\right)$$</div>\n<p>κ_gain 越小（趋近于 1/√r，r 为有效秩），谱越平坦；κ_gain 越接近 1，说明能量集中在单一方向，最坏增益与平均增益差距越大。这个比值不增加任何测量成本，却决定了你该用第一项还是第三项来定视觉侧比特宽。代价面上：视觉侧每降一档比特，Δ_vis 大致按步长比例增长，第一项随之线性放大；而第三项按步长平方变化，步长减半降为四分之一——两条曲线斜率不同，交叉点就是“再省就亏”的位置。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-8\">八 · 从线性传播到算子范数：推导的关键一步</h3>\n<p>推导的骨架只有三步，但每一步都埋了近似。第一步，把视觉编码器输出的量化误差写成加性扰动：x̂_vis = x_vis + Δ_vis，并假定该扰动已经过编码器全部非线性层、落在最终输出嵌入上。这一步跳过了编码器内部各层对量化噪声的逐层放大或衰减，等价于把整个视觉塔折叠成一个“误差源”，其幅度由末层输出直接测得。第二步，线性投影：h_vis = W_proj·x̂_vis，于是投影后误差为 W_proj·Δ_vis，取算子 2-范数得 ‖W_proj·Δ_vis‖₂ ≤ ‖W_proj‖₂·‖Δ_vis‖₂，这是最坏方向放缩，对任意 Δ_vis 方向都成立但通常偏松。第三步，LLM 侧扰动叠加：输出 y = f_llm(h_vis)，量化后 ŷ = f_llm(h_vis + W_proj Δ_vis) + 由 Δ_llm 引起的扰动，用一阶展开把两部分线性相加，得到三项界。</p>\n<p>关键近似集中在第三步：把 LLM 对输入扰动的响应当作恒等映射（或至少是 1-Lipschitz），即认为视觉嵌入上的偏差会原样传递到输出。真实 LLM 的注意力与 MLP 层会重新归一化和缩放，视觉嵌入偏差在深层可能被放大也可能被吸收。界取的是“不放大也不吸收”的中性假设，因此对深层吸收型网络偏保守，对放大型网络偏乐观。这也是为什么失效条件里点名 cross-attention 的 softmax 门控：softmax 的归一化使输出对输入扰动的敏感度依赖当前注意力分布，线性界无法覆盖。</p>\n<p>伪代码层面，验证这个界只需三行测量：分别跑全精度、仅视觉量化、仅 LLM 量化、双量化四次前向，取输出差的 2-范数，与三项计算值对比。若实测显著低于界，说明网络在吸收误差；若实测高于界，说明存在未建模的非线性放大路径（典型是激活异常值触发的 clamp 或饱和）。代价上，这个验证本身要四次完整前向，对长视觉序列意味着四倍视觉编码器算力与 KV 写入，通常只在离线标定时做，线上靠标定出的缩放系数修正界。</p>\n<ul>\n<li>机制：算子范数放缩把方向无关的最坏增益提取出来，代价是丢失 Δ_vis 的实际方向信息。</li>\n<li>公式：‖W_proj Δ_vis‖₂ ≤ ‖W_proj‖₂‖Δ_vis‖₂，等号仅在 Δ_vis 对齐最大奇异向量时取到。</li>\n<li>系统代价：最坏方向放缩使界在高维（视觉 token 数大）时明显偏松，导致比特分配过度保守、视觉侧算力与显存带宽浪费。</li>\n<li>例子：视觉塔输出 1024 维、投影到 4096 维语言空间时，W_proj 的最大奇异向量通常不对应单个 patch 的误差方向，实测误差往往落在界的几分之一，此时按界满额分配比特会多留一档精度。</li>\n</ul>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-9\">九 · Δ_q²/12 从哪来，离散化在哪一步发生</h3>\n<p>第三项的系数 1/12 是均匀量化器在量化步长 Δ_q 下的噪声方差，前提是输入在该步长区间内近似均匀分布、且量化误差与信号不相关。推导路径：设量化误差 e = Q(x) − x 在 [−Δ_q/2, Δ_q/2] 上均匀分布，则 E[e²] = Δ_q²/12。乘以投影矩阵后，每个输出通道收到的噪声功率是该通道对应权重列向量的加权和，对所有通道求和即得 tr(W_projᵀW_proj)·Δ_q²/12。这里有两个离散化近似：其一，把连续分布的量化误差当作均匀分布，实际激活分布（尤其视觉 token 的重尾分布）在步长内并不均匀，靠近分布峰值的区间误差偏小、尾部偏大；其二，假定各通道量化误差相互独立，而实际权重量化中同一权重的多个输出通道共享同一量化误差，相关性使功率求和偏大或偏小取决于分组方式。</p>\n<p>步长与比特宽的关系是 Δ_q = range/2^b，range 由校准集的最大绝对值决定。视觉 token 的激活异常值远大于文本 token，若沿用文本校准集定 range，range 被低估、clamp 截断产生额外误差，这部分不在 Δ_q²/12 模型内；若用视觉校准集定 range，range 被异常值撑大，步长变大，第三项按平方增长。这正是“视觉侧保留异常值通道”的经济学来源：把少数异常值剥离到高精度通道，主通道 range 收窄、步长变小，第三项显著下降，而异常值通道的额外显存与带宽开销有限。</p>\n<div class=\"formula\">$$\\Delta_q=\\frac{\\mathrm{range}}{2^{b}},\\qquad \\mathbb{E}\\!\\left[\\|\\Delta_{\\mathrm{vis}}\\|_2^2\\right]\\approx \\frac{\\Delta_q^2}{12}\\cdot d_{\\mathrm{vis}}$$</div>\n<p>d_vis 为视觉嵌入维度，此式给出 Δ_vis 的期望平方范数，用于把第一项与第三项统一到同一量纲上比较。系统代价：range 收窄一半等价于多出一位比特的精度而不增加位宽，但异常值通道要走独立的 kernel 路径，Triton/CUTLASS 实现上意味着混合精度 GEMM 的分支，吞吐损失取决于异常值比例；比例低于千分之一时开销可忽略，高于百分之一时分支发散开始吃掉 tensor core 利用率。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-10\">十 · 失效条件的数学根源</h3>\n<p>三条失效条件不是经验观察，各自对应推导中被省略的一项。AWQ/GPTQ 保留显著通道，等价于把量化误差从“全通道均匀”改成“按通道重要性加权的不均匀分布”，此时 E[ΔΔᵀ] 不再是对角阵乘 Δ_q²/12，第三项的迹公式失效；正确的替代是逐通道方差加权求和，界的形式变为 Σ_i σ_i²·‖W_proj[:,i]‖₂²，σ_i² 为该通道实际噪声方差。均匀界在这个和式上偏保守的程度取决于显著通道被保护得有多好——保护越彻底，实际噪声越小，界越松。</p>\n<p>激活量化的缺失项更隐蔽：SmoothQuant 式通道缩放把激活异常值从激活搬到权重，视觉 token 的动态范围问题被转移到权重侧，而界里 Δ_llm 只笼统表示“LLM 权重/激活量化误差”，没有区分两者对视觉嵌入的不同敏感度。视觉 token 激活幅值大意味着第二项 ‖Δ_llm‖₂·‖h_vis‖₂ 中的 ‖h_vis‖₂ 大，同等权重扰动造成的绝对偏差被放大；若激活量化独立校准且未处理异常值，实际 Δ_llm 远超按文本校准估计的值，界低估。</p>\n<p>cross-attention 门控的失效是结构性的：softmax 输出对输入扰动的雅可比不是常数，而是依赖注意力 logits 的矩阵，其谱范数可大于 1（尖锐注意力分布下放大）也可小于 1（平坦分布下抑制）。线性界相当于假定该雅可比为恒等，因此既不能预测放大也不能预测抑制。工程判断：融合方式为线性投影（如 LLaVA 式 MLP projector）时界可直接用；融合走 cross-attention 时，界只能作为下界参考，实际误差需用注意力熵做修正因子——熵低（分布尖锐）时放大风险高，应提高视觉侧精度。</p>\n<table class=\"mini\"><thead><tr><th>失效来源</th><th>被省略的项</th><th>界的方向</th><th>工程动作</th></tr></thead><tbody><tr><td>显著通道保护</td><td>逐通道噪声方差</td><td>偏保守</td><td>按通道方差加权重算，释放比特</td></tr><tr><td>视觉激活异常值</td><td>激活量化对动态范围的敏感度</td><td>偏乐观</td><td>异常值通道 + 视觉校准集</td></tr><tr><td>softmax 门控</td><td>注意力雅可比谱</td><td>方向不定</td><td>按注意力熵加修正因子</td></tr></tbody></table>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-11\">十一 · 用界做比特分配的推导顺序</h3>\n<p>界的三项给出一个明确的决策顺序，而不是一个待验证的数字。先算 ‖W_proj‖₂ 与迹项：这两个量只依赖投影矩阵本身，离线一次算完，给出视觉侧误差进入语言空间的最坏与平均增益。若谱范数远大于按维度平均的增益（κ_gain 接近 1），视觉侧比特宽由第一项锁定，此时降视觉比特的边际代价最高。再算 ‖h_vis‖₂ 的分布：它决定第二项中 LLM 量化噪声被放大的倍数，视觉 token 幅值若显著高于文本 token，LLM 侧激活量化必须保留异常值通道，否则第二项主导。</p>\n<p>把总误差预算记为 ε，三项各自的预算分配不是均分，而是按当前配置下哪项最大来削。伪代码思路：固定 LLM 比特宽，扫描视觉比特宽 b_vis，对每个 b_vis 用 Δ_q = range/2^b 算第一、三项，取和与 ε 比较，得到视觉侧最低可行比特；再固定 b_vis，扫描 LLM 激活比特宽，用实测 ‖h_vis‖₂ 算第二项，判断是否需要异常值通道。这个扫描只需投影矩阵统计量与校准集上的 ‖h_vis‖₂ 分布，不需要反复跑完整推理，代价是离线标定的一次性算力。</p>\n<p>系统代价的落点很具体：视觉侧多留一档比特，视觉编码器 GEMM 的 tensor core 吞吐按位宽比例下降，同时视觉 token 的 KV 写入带宽同比增加；LLM 侧保留异常值通道，则是混合精度 GEMM 的分支开销与额外显存。两者相权，当第一项主导时视觉侧加比特是唯一有效手段，因为语言侧再省也补不回被投影放大的源噪声——这正是界要传达的不可交换性。反过来，当第二项主导时，省视觉比特换 LLM 激活精度可能划算，前提是 ‖h_vis‖₂ 的分布允许异常值通道把有效步长压下来。</p>\n<p>最后落在机制上：这个界真正的用处不是预测一个误差数值，而是把“视觉侧与语言侧能否独立选比特”这个问题转化为对 W_proj 谱性质与 ‖h_vis‖₂ 分布的两次离线测量。谱倾斜则视觉侧锁定，幅值失衡则语言侧激活锁定，两者都不倾斜时才有独立调参的空间。任何跳过这两次测量、直接按文本校准集给两侧分配比特的做法，都是在界失效的那一侧下注。</p>\n<h3 id=\"th-multimodal-quant-error-bound-sec-12\">十二 · 三条假设：界成立的前提被逐条钉死</h3>\n<p>这条界不是无条件成立的恒等式，它的推导链上钉着三条假设，任何一条松动，不等式右侧就不再是上界。第一条是<strong>线性传播假设</strong>：视觉量化误差 $\\Delta_{\\mathrm{vis}}$ 必须经一个固定的线性映射 $W_{\\mathrm{proj}}$ 进入语言空间，界的第一项 $\\|W_{\\mathrm{proj}}\\|_2\\cdot\\|\\Delta_{\\mathrm{vis}}\\|_2$ 本质上是算子范数对最坏方向增益的界定。只要投影是线性的，误差向量的范数就被谱范数封顶；一旦融合路径上出现 softmax 归一化、门控乘性交互或动态路由，误差不再是线性叠加，算子范数界定失效。第二条是<strong>噪声均匀性假设</strong>：第三项 $\\frac{\\Delta_q^2}{12}\\cdot\\mathrm{tr}(W_{\\mathrm{proj}}^{\\top}W_{\\mathrm{proj}})$ 直接来自均匀量化噪声方差 $\\Delta_q^2/12$，迹项把投影矩阵各方向的增益平方和累加成总功率。第三条是<strong>误差可加性假设</strong>：视觉侧噪声与 LLM 侧噪声被视为独立叠加，第二项 $\\|\\Delta_{\\mathrm{llm}}\\|_2\\cdot\\|h_{\\mathrm{vis}}\\|_2$ 把 LLM 量化误差乘上视觉嵌入幅值，隐含了“视觉嵌入幅值放大同等 LLM 噪声”的线性关系。工程上判断这条界是否可用，第一步就是核对这三条假设在目标模型里是否同时近似成立——多数 VLM 的视觉塔到语言塔之间恰好是线性 projector，所以第一、三条通常成立，而第二条几乎从不严格成立。</p>\n<p>代价层面要看清假设的“价格”。均匀噪声假设让界变成一个闭式表达式，可以在比特宽分配时直接求导；代价是它对非均匀量化器系统性偏保守。以 AWQ/GPTQ 为例，它们按通道显著性保留异常值，等效噪声方差在显著通道远低于 $\\Delta_q^2/12$、在次要通道高于该值，加权后总功率通常低于均匀假设给出的迹项。这意味着按此界选比特宽，会在视觉侧多留比特，直接换来显存与带宽开销：视觉塔权重每多留一档精度，编码器前向的权重带宽占用上升，长视觉序列下预填阶段的 HBM 读取时间被拉长。具体例子：一个视觉塔输出 1024 维、投影到 4096 维语言空间，$\\mathrm{tr}(W_{\\mathrm{proj}}^{\\top}W_{\\mathrm{proj}})$ 由 4096 个输出方向的增益平方和构成；若按均匀假设把视觉侧定在 INT8，而实际 AWQ 已把显著通道压到 4 bit，界给出的预算就高估了噪声，工程上会错失一档可省的比特。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-13\">十三 · 失效条件一：softmax 门控把线性界撕开</h3>\n<p>cross-attention 融合是这条界最典型的失效场景。线性界假定误差经 $W_{\\mathrm{proj}}$ 后原样进入语言空间，但 cross-attention 里视觉嵌入先参与 $QK^{\\top}$ 打分，再经 softmax 归一化加权求和。softmax 的归一化分母对视觉侧扰动是<strong>非线性响应</strong>：视觉 token 的量化误差既改变注意力权重分布（分子扰动），又改变归一化因子（分母扰动），两者相除后误差既可能被放大也可能被抑制，取决于当前注意力分布的尖锐程度。分布平坦时，分母扰动与分子扰动同阶，误差被稀释；分布尖锐时，微小打分扰动即可翻转 argmax 附近的权重分配，误差被放大到远超线性界预测的水平。此时 $\\|W_{\\mathrm{proj}}\\|_2$ 不再是有效增益上界，界的第一项失去意义。</p>\n<p>伪代码层面，判断是否落入失效区可以这样做：对每个视觉 token 计算量化前后注意力权重的 $L_1$ 距离，若该距离相对权重本身的比值超过阈值，说明 softmax 已进入非线性敏感区，线性界不可用；否则仍可按界分配比特。工程代价体现在调度上：一旦判定失效，比特宽分配不能再走闭式求导，必须回退到逐层敏感度扫描或校准集上的经验搜索，编译期成本上升，且搜索出的配置在不同输入分布间迁移性差。具体例子：一个使用 cross-attention 融合的 VLM，视觉 token 数远大于文本 token 数时，softmax 分母由大量视觉 token 共同贡献，单个 token 的量化扰动被平均稀释，线性界偏保守；反之视觉 token 极少、注意力高度集中时，界会低估误差，此时若仍按界把视觉侧压到低比特，跨模态对齐会明显退化。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-14\">十四 · 失效条件二：激活异常值让独立校准失效</h3>\n<p>界里没有显式建模激活量化，第二项只把 $\\Delta_{\\mathrm{llm}}$ 当作已给定的 LLM 量化误差。但视觉 token 的激活动态范围与文本 token 不在一个量级：视觉特征在通道维度上存在远大于文本的异常值，若沿用文本校准集统计出的激活量化步长，视觉 token 的量化误差会超出界所假设的 $\\Delta_{\\mathrm{llm}}$。SmoothQuant 式的通道缩放能把异常值从激活搬到权重，但对视觉 token 而言，缩放系数的校准必须基于视觉校准集，否则缩放后残余异常值仍会撑大量化步长。此时界的第二项低估了实际误差，$\\|h_{\\mathrm{vis}}\\|_2$ 与 $\\|\\Delta_{\\mathrm{llm}}\\|_2$ 的乘积不再是有效上界。</p>\n<p>量化判断可以写成：设视觉激活第 $j$ 通道的最大幅值为 $a_j^{\\max}$、文本校准集给出的步长为 $\\Delta_q^{\\text{text}}$，若 $a_j^{\\max}/\\Delta_q^{\\text{text}}$ 超过量化器可表示的动态范围，则该通道必然削顶，误差不再服从均匀分布假设。工程代价直接落在显存与带宽：为避免削顶，视觉侧激活需保留 FP16 异常值通道或采用分组量化，激活显存占用上升，解码阶段每步读取的 KV 与激活带宽增加，长上下文下吞吐下降。具体例子：视觉塔输出经 projector 后的嵌入若含少量幅值极大的通道，独立按文本校准的 INT8 激活量化会把这些通道削平，语言侧再省比特也补不回跨模态语义损失——这正是界所警告的“视觉侧主导误差”的激活版本。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-15\">十五 · 规模上限：什么时候界随规模失去约束力</h3>\n<p>界的三项都随规模以不同速率增长，规模一大，主导项切换，界的约束力随之变化。第一项随 $\\|W_{\\mathrm{proj}}\\|_2$ 与视觉误差范数增长，与视觉 token 数无直接关系；第二项随 $\\|h_{\\mathrm{vis}}\\|_2$ 增长，而 $\\|h_{\\mathrm{vis}}\\|_2$ 随视觉 token 数增加而增大（嵌入向量堆叠后范数上升）；第三项的迹项与投影维度成正比，与 token 数无关。因此当视觉 token 数增大时，第二项逐渐主导，界从“视觉投影增益主导”切换到“LLM 噪声乘视觉幅值主导”。这个切换点决定了比特宽分配的重心：小规模下省视觉侧比特收益最大，大规模下省 LLM 侧激活比特更关键。</p>\n<div class=\"formula\">$$\\text{主导项切换：}\\;\\|W_{\\mathrm{proj}}\\|_2\\|\\Delta_{\\mathrm{vis}}\\|_2 \\;\\gtrless\\; \\|\\Delta_{\\mathrm{llm}}\\|_2\\|h_{\\mathrm{vis}}\\|_2$$</div>\n<p>规模上限的另一面是界的<strong>紧致性衰减</strong>。三项叠加是三角不等式的结果，当三项量级相近时，界相对实际误差的松弛度最大；当某一项压倒性主导时，界反而更紧。工程含义是：在视觉 token 数与语言 token 数相当的均衡配置下，界最保守，按界分配比特宽会系统性多留精度、浪费显存；而在视觉 token 远多于文本（高分辨率图像、视频帧序列）的偏斜配置下，界更紧、更可信。具体例子：视频输入下视觉 token 数可达文本 token 的数十倍，$\\|h_{\\mathrm{vis}}\\|_2$ 显著抬升，第二项主导，此时界的预测更接近实际，可用于判断 LLM 激活量化是否必须保留异常值通道；而单图短问答场景三项量级接近，界偏保守，应结合校准集实测再定比特。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-16\">十六 · 工程判定：把界当筛选器而非预测器</h3>\n<p>正确的用法是把这条界当作<strong>比特宽分配的筛选器</strong>：先用 $\\|W_{\\mathrm{proj}}\\|_2$ 与迹项定出视觉侧的最低比特下界，再用 $\\|h_{\\mathrm{vis}}\\|_2$ 判断 LLM 侧激活量化是否需要异常值通道，最后用校准集实测校正均匀假设带来的保守量。判定流程可以写成三步伪代码：第一步，测投影矩阵谱范数与迹，若谱范数相对迹项均值偏高，说明存在强增益方向，视觉侧不能统一低比特；第二步，测视觉嵌入范数与视觉激活异常值比例，若异常值比例超过文本校准集可覆盖范围，激活量化必须分组或保留高精度通道；第三步，在目标输入分布上跑量化前后输出误差，与界预测比对，若实测显著低于界，按实测收紧比特，若实测高于界，说明已落入 softmax 非线性或激活削顶失效区，回退到敏感度扫描。代价是这套流程需要校准集与额外的前向比对，编译期与调优期成本上升，但换来的是避免“语言侧再省也补不回视觉侧误差”的结构性浪费。</p>\n<p>具体例子：给定总误差预算，若第一步测得谱范数主导，则把视觉侧定在 FP8 并保留异常值通道、LLM 侧可压到更低比特；若第二步测得视觉激活异常值比例高，则 LLM 侧激活量化改用分组方案而非统一 INT8；若第三步实测低于界预测，说明 AWQ/GPTQ 的非均匀噪声已让界偏保守，可安全收紧视觉侧一档。最终判断落在具体机制上：这条界只在“线性 projector + 均匀噪声 + 独立可加”三假设同时近似成立时给出可信上界，一旦 cross-attention 门控或视觉激活异常值进入，界退化为保守筛选器，比特宽决策必须让位于逐层敏感度实测。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-17\">十七 · 边界之外：线性界在何处失效，以及工程上如何兜底</h3>\n<p>该界的三项叠加结构依赖一个强假设：视觉量化误差只经一次线性投影进入语言空间，且噪声在投影后各通道上均匀铺开。一旦跨模态融合改用 cross-attention 的 softmax 门控，这条链路就断了——注意力归一化对误差的作用是乘性的、依赖当前 query 的，误差大的 token 可能被门控压下去，也可能被放大到远超 <span>‖W_proj‖₂</span> 所刻画的谱增益。此时线性界既不是上界也不是近似，只能当作量级参考。工程判断是：融合方式为 cross-attention 时，误差预算必须靠端到端校准或逐层敏感度实测来定，不能拿投影矩阵范数直接换算比特宽。</p>\n<p>第二类失效来自噪声分布假设。第三项的 <span>Δ_q²/12</span> 是均匀量化的方差，而 AWQ/GPTQ 保留显著通道后噪声呈重尾、非均匀分布，实际误差功率低于该式预测，界偏保守。保守本身不致命，致命的是把它当精确预测去做比特分配：按界算出的视觉侧最低比特会系统性偏高，白白放弃可省的位宽。更隐蔽的是激活侧——视觉 token 的异常值动态范围远大于文本 token，若沿用文本校准集独立标定激活量化（如 SmoothQuant 的通道缩放系数），视觉激活量化误差会直接突破该界所覆盖的范围，表现为跨模态对齐退化而非单纯的数值偏差。</p>\n<div class=\"formula\">$$\\text{可用性判据：}\\;\\frac{\\|W_{\\mathrm{proj}}\\|_2\\cdot\\|\\Delta_{\\mathrm{vis}}\\|_2}{\\|\\Delta_{\\mathrm{llm}}\\|_2\\cdot\\|h_{\\mathrm{vis}}\\|_2}\\;\\gg\\;1\\;\\Rightarrow\\;\\text{视觉侧主导，独立选比特宽失效}$$</div>\n<p>规模上限同样存在。该界对单个投影层成立，层数堆叠后误差并非简单相加：视觉 token 数随分辨率增长，<span>‖h_vis‖₂</span> 随嵌入幅值与 token 数共同抬升，第二项在长视觉序列下迅速吃掉预算；而投影矩阵的迹项随隐藏维线性增长，第三项在大宽度模型上不可忽略。系统代价上，这意味着视觉侧保留 FP16 异常值通道带来的显存与带宽开销必须与语言侧省下的比特权衡——视觉编码器参数量远小于 LLM，保留高精度通道的显存代价有限，但视觉 token 的激活存储与跨模态传输带宽会随序列长度放大，成为分离式预填/解码部署中的实际瓶颈。判断准则很直接：先测投影谱范数与视觉激活异常值比例，若前者大或后者重尾，视觉侧就不能与语言侧共用一套比特决策。</p>\n<table class=\"mini\"><thead><tr><th>失效来源</th><th>界的行为</th><th>系统后果</th></tr></thead><tbody><tr><td>softmax 门控融合</td><td>不再成立</td><td>需端到端校准定预算</td></tr><tr><td>非均匀权重量化</td><td>偏保守</td><td>错失可省位宽</td></tr><tr><td>视觉激活异常值</td><td>覆盖不到</td><td>跨模态对齐退化</td></tr></tbody></table>\n<h3 id=\"th-multimodal-quant-error-bound-sec-18\">十八 · 把界拆成可分配的三份预算</h3>\n<p>在容量决策里，这个界的第一价值不是“预测误差”，而是把总误差预算切成三份可独立采购的额度。工程上先固定一个可接受的总偏差上限 <span>ε</span>（由下游任务决定：检索对齐、OCR 字段、图表数值读取，各自容忍度不同），然后令三项分别不超过 <span>αε</span>、<span>βε</span>、<span>γε</span>，且 <span>α+β+γ=1</span>。三项的物理含义不同，采购方式也不同：第一项买的是视觉侧比特宽与异常值通道，第二项买的是 LLM 侧激活量化的通道保留策略，第三项买的是投影矩阵本身的量化步长（即投影层是否也量化、以什么粒度量化）。</p>\n<p>关键在于三项对资源的敏感度不对称。第一项随 <span>‖Δ_vis‖₂</span> 线性变化，比特宽每降一档，误差近似翻倍，是硬杠杆；第三项随 <span>Δ_q²</span> 二次变化，步长减半即降为四分之一，是软杠杆——这意味着在预算紧张时，优先把投影层留在高精度（甚至不量化），比死抠视觉编码器更划算。第二项则与 <span>‖h_vis‖₂</span> 相乘，视觉嵌入幅值越大，同样的 LLM 量化噪声造成的绝对偏差越大，因此视觉 token 数增多、嵌入范数抬升时，LLM 侧激活量化的通道保留必须同步加严。</p>\n<p>一个具体做法：把三项写成约束表，逐项标注“可控变量”与“代价科目”。第一项的可控变量是视觉编码器权重/激活位宽与是否保留 FP16 异常值通道，代价是视觉编码器显存与编码时延；第二项的可控变量是 LLM 激活量化的分组粒度与异常值通道数，代价是解码吞吐与显存带宽；第三项的可控变量是投影层量化步长，代价极小（投影层参数量相对整网可忽略），因此它应当是全表中最先被“买满”的一项。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-19\">十九 · 用第一项定视觉侧最低比特与并行度</h3>\n<p>第一项 <span>‖W_proj‖₂·‖Δ_vis‖₂</span> 直接给出视觉侧比特宽的下界。给定预算 <span>αε</span>，要求 <span>‖Δ_vis‖₂ ≤ αε/‖W_proj‖₂</span>。谱范数 <span>‖W_proj‖₂</span> 是投影矩阵的最大增益方向，它决定了“最坏情况下视觉误差被放大多少倍”。工程上不必精确求谱范数，用幂迭代几次即可得到稳定上界估计；真正要盯的是这个值在不同 VLM 之间的量级差异——投影层把视觉特征映射到语言嵌入空间，若两侧维度差异大、映射陡峭，谱范数就大，视觉侧就必须更早地保留高精度。</p>\n<p>由此派生的是并行度决策。视觉编码器在预填阶段是计算密集的，若为了满足第一项而必须保留 FP16 异常值通道或更高位宽，视觉编码器的算力需求上升，此时张量并行度不能按“纯吞吐最优”来定，而要按“单卡显存能否容纳高精度视觉权重 + 激活峰值”来定。反过来，如果谱范数很小、第一项预算宽松，视觉侧可以走低位宽，编码器显存下降，并行度可以退到更小的切分，减少跨卡通信。也就是说，<span>‖W_proj‖₂</span> 是连接“数值精度选择”和“并行切分”的中间变量：它把误差预算翻译成显存约束，再翻译成并行度。</p>\n<p>算例：设总预算 <span>ε</span> 归一化为 1，取 <span>α=0.5</span>，测得 <span>‖W_proj‖₂≈8</span>（量级示意，非实测），则 <span>‖Δ_vis‖₂ ≤ 0.0625</span>。若视觉编码器输出通道的动态范围要求步长不超过某值才能满足该范数，则统一 INT8 不达标，必须保留异常值通道或部分层留在 FP16。此时视觉编码器显存按“混合精度”估算，单卡放不下就切 2 路张量并行；若强行统一 INT8 以满足显存，第一项就会吃掉全部预算，第二、三项无额度可用——这正是“语言侧再省也补不回来”的定量版本。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-20\">二十 · 用第二项与第三项定 KV 预算与批大小</h3>\n<p>第二项 <span>‖Δ_llm‖₂·‖h_vis‖₂</span> 决定 LLM 侧激活量化的严格程度，而激活量化的严格程度又反过来影响 KV cache 的可行位宽。多模态场景下视觉 token 的嵌入幅值显著高于文本 token，<span>‖h_vis‖₂</span> 大，同样的 <span>‖Δ_llm‖₂</span> 产生更大绝对偏差，因此视觉 token 的 KV 不能与文本 token 共用一套校准参数。工程判断是：KV cache 的量化位宽按 token 类型分档，视觉 token 走更高位宽或保留异常值通道，文本 token 走低位宽。这直接改变 KV 预算：设序列中视觉 token 占比 <span>ρ</span>，视觉 KV 位宽 <span>b_v</span>、文本 <span>b_t</span>，则等效平均位宽 <span>b̄ = ρb_v + (1−ρ)b_t</span>，KV 显存按 <span>b̄</span> 线性缩放。ρ 越大，KV 预算越吃紧，批大小上限随之下降。</p>\n<div class=\"formula\">$$\\text{batch}_{\\max} \\;\\approx\\; \\frac{M_{\\mathrm{kv}}}{\\,L\\cdot H\\cdot d\\cdot \\bar{b}/8\\,}$$</div>\n<p>其中 <span>M_kv</span> 为分配给 KV 的显存额度，<span>L</span> 为层数，<span>H</span> 为 KV 头数，<span>d</span> 为头维。这个式子的用法不是精确算批大小，而是看敏感度：<span>b̄</span> 从 8 降到 4，批大小理论上翻倍，但若第二项预算不允许视觉 KV 降到 4，则实际 <span>b̄</span> 只降一点点，批大小收益远小于预期。这就是“量化省显存”在多模态上常被高估的原因——省下来的位宽被视觉 token 的高精度要求吃掉了。</p>\n<p>第三项则给出一个几乎免费的额度：<span>Δ_q²/12·tr(W_projᵀW_proj)</span>。迹项是投影矩阵各方向增益平方和，它通常远小于谱范数的平方乘以维度，因此第三项在总预算中占比小。工程结论是：投影层量化步长减半的代价（几乎为零的额外显存）能换来该项降至四分之一，应优先做；而不要为了省投影层的几个比特去挤压视觉侧预算。把第三项买满之后，剩下的预算才在第一批和第二项之间分配，分配比例由 <span>‖W_proj‖₂</span> 与 <span>‖h_vis‖₂</span> 的相对大小决定：谱范数主导则偏视觉侧，嵌入幅值主导则偏 LLM 激活侧。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-21\">二十一 · 把界接到 SLO 上：误差预算与时延预算的耦合</h3>\n<p>SLO 决策不能只看误差，还要看误差约束如何反推时延。三条耦合路径：其一，视觉侧为满足第一项保留高精度，视觉编码器算力上升，预填时延增加；其二，LLM 激活侧为满足第二项保留异常值通道，解码时激活量化的反量化开销与通道选择开销增加，单 token 时延上升；其三，KV 位宽分档使 KV 读写带宽需求上升，长上下文下解码带宽成为瓶颈。因此 SLO 的可行域是“误差预算 × 时延预算”的二维区域，而不是各自独立设定。</p>\n<p>具体机制：把三项预算作为约束，把批大小 <span>B</span>、视觉并行度 <span>P_v</span>、KV 平均位宽 <span>b̄</span> 作为决策变量，构造一个可行性检查——对每组 <span>(B, P_v, b̄)</span>，先算三项误差是否都在各自额度内，再算预填时延与解码 TPOT 是否满足 SLO，两者同时满足才进入候选。这个检查的计算量很小（几个范数与迹），可以在容量规划阶段对参数网格扫一遍，得到可行域边界。边界上通常会出现“误差额度用尽但时延还有余”或“时延卡死但误差额度富余”两类点，前者说明该加精度，后者说明该加并行或加批。</p>\n<p>算例：某部署要求 TPOT 不超过给定阈值、总误差预算为 1。扫格点发现：当 <span>B</span> 增大时，KV 显存压力迫使 <span>b̄</span> 下降，视觉 KV 位宽被压到与文本同档，第二项误差抬升并越过 <span>βε</span>，可行性丧失。此时有两条路：降低 <span>ρ</span>（减少视觉 token 数，属视觉 token 压缩的范畴，本片段不展开）或提高视觉 KV 位宽并相应减小 <span>B</span>。后者牺牲吞吐换 SLO 达标，前者牺牲对齐质量换吞吐——决策依据正是三项预算中哪一项先被击穿。若击穿的是第二项，说明瓶颈在 LLM 激活侧而非视觉侧，此时应优先调整 LLM 激活量化的分组策略，而不是去动视觉编码器。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-22\">二十二 · 界的保守性与决策中的修正项</h3>\n<p>把这个界用于容量决策时，必须带一个修正方向：界在 AWQ/GPTQ 类保留显著通道的非均匀量化下偏保守，因为均匀方差 <span>Δ_q²/12</span> 高估了实际噪声功率。保守意味着按界算出的比特宽比实际需要的更宽，容量规划会偏紧——这在 SLO 场景下是安全方向，但在成本场景下是浪费。工程判断是：用界做“下界可行性”筛选（不满足界的方案直接淘汰），再用少量实测校准做“上界放宽”（满足界的方案中，允许在非关键路径上试探更低比特）。</p>\n<p>另一处修正来自失效条件：当跨模态融合走 cross-attention 的 softmax 门控时，线性界不再直接适用，注意力归一化会非线性放大或抑制误差。此时不能把三项预算直接套用，而应把门控视为一个额外的增益因子，在预算分配时预留一块“非线性余量”，其大小由门控饱和程度决定——门控越接近均匀分布，非线性放大越弱，余量可小；门控越尖锐，误差越可能被放大，余量须留足。视觉 token 激活异常值远大于文本 token 这一事实，也要求激活量化校准按模态分开做，否则第二项的实际值会超出界所描述的范围，使预算表失真。</p>\n<p>最终落到一个可执行的工程动作：在容量规划表里，为每个候选配置同时记录三项的预算占用率与实测抽样误差，占用率接近 1 的项标红，作为下一轮调参的首要目标；投影层量化步长作为第一优先买满项，视觉侧比特宽作为第二优先，LLM 激活通道保留作为第三优先，KV 位宽分档作为批大小的联动变量。这个顺序不是理论推导的结果，而是三项对资源敏感度不对称的直接推论——二次项先买、线性项后买、乘积项随嵌入幅值动态调整。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-23\">二十三 · 把误差界换算成容量决策：批大小、并行度与 KV 预算的取舍边界</h3>\n\n<p>这个界在容量决策里只承担一件事：把「视觉侧比特宽」换算成可支付的系统预算。做法是把三项误差按目标 SLO 拆成预算份额，先由第一项 <span class=\"formula-inline\">‖W_proj‖₂·‖Δ_vis‖₂</span> 反解视觉侧可容忍的量化步长，再由第二项 <span class=\"formula-inline\">‖Δ_llm‖₂·‖h_vis‖₂</span> 判断语言侧激活是否需要保留异常值通道。批大小并不直接出现在界里，但它通过 <span class=\"formula-inline\">‖h_vis‖₂</span> 的批内最大值起作用：连续批处理把多图拼进同一前向时，视觉 token 幅值取批内上界，第二项随之抬升，因此「批越大越省」在视觉侧并不成立，批大小必须与视觉精度档位联合确定，而不是先定吞吐再补精度。并行度同理——张量并行切分投影矩阵会改变 <span class=\"formula-inline\">‖W_proj‖₂</span> 的实际有效增益与迹项求和路径，切分后各 rank 的局部迹相加才等于全局迹，跨 rank 归约引入的额外舍入会挤占误差预算，故并行度提升换来的是显存与带宽余量，代价是误差界收紧、视觉侧可省的比特变少。</p>\n\n<p>KV 预算的定法要绕开一个常见误判：视觉 token 的 KV 只占序列一小段，却携带最大的激活异常值。若按文本 token 的校准统计去定 KV 量化档位（例如统一 INT8），第三项 <span class=\"formula-inline\">Δ_q²/12·tr(W_projᵀW_proj)</span> 会被低估——迹项是投影各方向增益平方和，视觉通道恰好落在高增益方向上，步长减半该项降为四分之一，但前提是步长按视觉动态范围而非文本动态范围选取。工程判断是：KV 预算先按文本 token 定容量，再为视觉 token 单独留出高精度通道或异常值旁路，这部分额外显存要用「视觉 token 数 × 通道数 × 精度差」显式计入容量规划，不能靠语言侧量化省回来。</p>\n\n<table class=\"mini\"><thead><tr><th>决策项</th><th>界中起作用的分项</th><th>系统代价</th></tr></thead><tbody><tr><td>批大小</td><td>第二项，批内 max‖h_vis‖₂</td><td>吞吐升、误差预算降</td></tr><tr><td>张量并行度</td><td>第一项谱范数、第三项迹求和</td><td>显存降、归约舍入占预算</td></tr><tr><td>KV 精度档</td><td>第三项，按视觉动态范围取 Δ_q</td><td>显存升、跨模态对齐稳</td></tr></tbody></table>\n\n<p>算例：设总误差预算为 E，投影谱范数给定，视觉侧候选两档步长 Δ_q 与 Δ_q/2。按第三项，后者把该分项压到四分之一，若第一项与第二项合计已占预算大头，则减半步长换来的余量不足以抵消视觉编码器升档带来的显存与带宽开销——此时正确动作是保留视觉侧 FP16 异常值通道而非整体升精度，因为异常值通道只增加少量通道的存储，却直接压低 <span class=\"formula-inline\">‖Δ_vis‖₂</span> 的最大分量。反过来，若第一项在预算中占比小、第二项主导，则说明瓶颈在语言侧激活幅值，应优先处理视觉 token 的动态范围而非继续给视觉编码器加比特。</p>\n\n<p>失效边界必须写进决策流程：AWQ/GPTQ 保留显著通道后噪声非均匀，均匀方差界偏保守，据此定的比特宽会系统性高估所需精度、错失可省档位；cross-attention 的 softmax 门控使线性界不再直接适用，此时界只能当上界护栏而非预算分配依据；未建模的激活量化（如通道缩放）在视觉 token 上误差可能超出该界，容量规划须留出未建模余量。最危险的失败模式是两侧独立量化、各自用文本校准集调参——界的第一项被忽略，输出误差由视觉侧主导，语言侧再省也补不回。</p>\n<h3 id=\"th-multimodal-quant-error-bound-sec-24\">二十四 · 误用的共同结构：把界当成可分解的独立预算</h3>\n<p>这个界最容易被误读成一张“分账单”：视觉侧一项、语言侧一项、量化方差一项，三项相加即总误差，于是工程上自然滑向“两侧各自选比特宽、各自校准、各自验收”。误用的根子不在算术，而在把三项当成了可独立支配的预算。三项之间由 <span>W</span><sub>proj</sub> 与 <span>h</span><sub>vis</sub> 耦合：第一项由投影矩阵谱范数给视觉噪声定放大倍数，第二项由视觉嵌入幅值给语言噪声定绝对尺度。任一侧单独调参时，另一侧的乘子被冻结在旧值上，预算分配就失去意义。识别这种误用的第一个信号是校准流程：若视觉编码器与 LLM 的量化参数分别来自两套互不通信的校准集，且视觉侧用的是文本校准集，那么界的三项从未在同一组样本上被同时求值，所谓“总误差达标”只是两个局部指标的拼接。</p>\n<p>代价落在系统层面而非单点精度上。视觉侧被压到低比特后，<span>‖Δ</span><sub>vis</sub><span>‖</span><sub>2</sub> 上升，经谱范数放大进入语言空间，表现为跨模态对齐退化：模型对图像中细粒度属性、空间关系、文字区域的描述开始漂移，而纯文本基准几乎不掉。此时运维侧的典型反应是继续压语言侧比特宽以“找回”吞吐，结果是第二项在视觉嵌入幅值大的 token 上被放大，误差反而更集中于多模态输入。显存账面上省了，SLO 上却出现多模态请求的尾延迟与重试率上升——因为对齐退化触发更长的输出、更多的自我修正式解码，解码 token 数增加直接吃掉连续批处理带来的吞吐收益。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-25\">二十五 · 反例：视觉 INT8 统一量化 + 语言侧激进低比特</h3>\n<p>设一个典型部署：视觉编码器输出统一 INT8 对称量化，LLM 权重走 4 bit 权重量化并保留显著通道，激活量化沿用文本校准得到的步长。按“独立选比特宽”的逻辑，这套组合看起来合理——语言侧已经是成熟方案，视觉侧 INT8 也不算激进。但把三项逐一代入就会发现结构性问题。视觉编码器输出的动态范围由图像内容决定，统一 INT8 的步长 <span>Δ</span><sub>q</sub> 由整层最大幅值定，绝大多数通道的有效位数被少数异常值通道挤掉，<span>‖Δ</span><sub>vis</sub><span>‖</span><sub>2</sub> 被异常值通道主导。第三项 <span>Δ</span><sub>q</sub><sup>2</sup>/12·tr(<span>W</span><sub>proj</sub><sup>T</sup><span>W</span><sub>proj</sub>) 随步长平方增长，步长由异常值撑大时这一项迅速吃掉误差预算。</p>\n<p>更关键的是第一项：<span>‖W</span><sub>proj</sub><span>‖</span><sub>2</sub> 是最大增益方向，视觉噪声在最坏方向上被放大后注入语言空间，而语言侧的 4 bit 权重并不能“吸收”这部分误差——它只改变 <span>Δ</span><sub>llm</sub>，不改变已经进入 <span>h</span><sub>vis</sub> 的偏差。于是第二项 <span>‖Δ</span><sub>llm</sub><span>‖</span><sub>2</sub>·<span>‖h</span><sub>vis</sub><span>‖</span><sub>2</sub> 在视觉嵌入幅值大的 token 上继续叠加，两项同向。工程后果是可观测的：多模态输入的激活异常值远大于文本 token，沿用文本校准的激活步长在这些 token 上系统性偏大，量化误差超出界所预测的范围；跨模态对齐在需要精确引用图像细节的任务上先崩，而纯文本任务指标不动，掩盖了问题。此时再降语言侧比特宽，只会让第二项在剩余预算里占比更高，视觉侧误差依旧主导，形成“越省越补不回”的死循环。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-26\">二十六 · 第二类误用：把均匀方差界当精确预测</h3>\n<p>第三项建立在均匀量化噪声方差 <span>Δ</span><sub>q</sub><sup>2</sup>/12 的假设上。AWQ/GPTQ 一类权重量化保留显著通道，噪声分布非均匀，实际误差方差低于均匀假设，界因此偏保守。误用方式是把界当作逐层误差预测器：拿它去反推“这一层还能不能再降一档”，得到的结论系统性偏悲观，于是错失本可省下的比特宽。识别信号是校准残差——若实测逐层输出误差长期显著低于界值且比例稳定，说明该层噪声已非均匀，界不再是紧的约束，此时应改用实测噪声协方差替代 <span>Δ</span><sub>q</sub><sup>2</sup>/12 项，而不是继续用界做比特分配。</p>\n<p>代价是容量规划上的保守浪费：显存与带宽预算被过度预留，批大小上不去，吞吐被压在低于硬件能力的水平。这在 NVL72 这类以显存容量换并发的系统上尤其明显——每层多留的比特宽乘以层数与副本数，直接压缩可容纳的 KV cache 块数，连续批处理的并发上限随之下降。反过来，若把界当成精确预测而在非均匀噪声下按界值“卡线”分配，则会在显著通道被保留、其余通道噪声抬升的组合上低估尾部误差，多模态请求的长尾延迟重新出现。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-27\">二十七 · 第三类误用：线性界套到 softmax 门控融合上</h3>\n<p>该界仅对线性投影后的嵌入误差成立。当跨模态融合走 cross-attention 的 softmax 门控时，注意力归一化对误差的作用是非线性的：门控权重对量化扰动敏感时误差被放大，权重饱和时误差被抑制，线性界既不给上界也不给下界。误用方式是拿这个界去论证“cross-attention 融合架构下视觉侧比特宽可以照此分配”，把线性推导的结论平移到一个非线性环节。识别信号是融合层的注意力熵：若量化前后注意力分布显著偏移，说明门控处于敏感区，线性界失效；若分布几乎不变，说明门控饱和，界的预测与实测脱节但方向偏保守。</p>\n<p>系统代价体现在调度层：融合环节误差不可预测时，无法给出可靠的多模态请求时延上界，SLO 只能靠实测分位数兜底，容量规划从“按界推算”退化为“按压测留裕量”。在分离式预填/解码部署中，预填阶段的多模态编码与解码阶段的融合分处不同资源池，融合侧误差放大意味着预填产出的 KV 在解码侧被更频繁地修正，跨池传输的 KV 数据有效利用率下降，NIXL 传输带宽被无效重算挤占。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-28\">二十八 · 识别清单与工程判断</h3>\n<p>把误用识别压缩成可执行的检查项，比记住公式更有用。以下四条按触发顺序排列，任一命中即应停止用该界做比特分配：</p>\n<ul>\n<li>校准集同源检查：视觉侧与语言侧的量化校准样本是否来自同一多模态分布，视觉侧是否混用了文本校准集。不同源则三项从未联合求值。</li>\n<li>谱范数实测检查：<span>‖W</span><sub>proj</sub><span>‖</span><sub>2</sub> 是否按实际投影权重求得，而非沿用文本侧经验值；投影权重越大，视觉侧最低比特宽的下限越高。</li>\n<li>激活异常值检查：视觉 token 的激活动态范围是否单独统计，是否沿用了文本 token 的步长；异常值通道是否保留高精度。</li>\n<li>融合非线性检查：融合是否为 softmax 门控；若是，线性界只能作为保守参考，不能作为分配依据。</li>\n</ul>\n<p>工程判断落在一点上：这个界是分配比特宽的下限约束，不是误差预测器。它的正确用法是先由 <span>‖W</span><sub>proj</sub><span>‖</span><sub>2</sub> 与迹项定出视觉侧不可再降的比特下限，再由 <span>‖h</span><sub>vis</sub><span>‖</span><sub>2</sub> 判断语言侧激活量化是否需要保留异常值通道，两侧在同一组多模态校准样本上联合求值。一旦融合走 softmax 门控或权重噪声已非均匀，界退化为保守参考，此时应以实测噪声协方差替换均匀方差项、以注意力熵监控融合敏感区，把比特分配的依据从解析式切换到“界定下限、实测定余量”的双轨机制——视觉侧保留异常值通道的 FP16 路径往往比在语言侧多省一档更能守住多模态 SLO。</p>\n\n<h3 id=\"th-multimodal-quant-error-bound-sec-29\">二十九 · 当界被当成开关：三类误用、一个反例与识别信号</h3>\n<p>最常见的误用是把这条不等式当作“可以独立调两侧比特宽”的许可证：视觉编码器按文本校准集压到 INT8，LLM 侧再压到 INT4，两侧各自调参、互不通气。后果直接体现在第一项 <span>‖W_proj‖₂·‖Δ_vis‖₂</span> 上——投影矩阵的谱范数是最坏增益方向，视觉侧量化噪声沿该方向被放大后注入语言空间，语言侧再怎么省也补不回。系统代价是双向的：显存账面上视觉塔省下的权重字节远小于 LLM 权重，但输出误差被视觉侧主导，表现为跨模态对齐退化（图像描述中的属性错配、计数错误、空间关系颠倒），而困惑度指标几乎不动，于是团队误判“量化无损”，继续压比特，直到下游任务崩掉才回头。识别信号很明确：把视觉侧单独切回 FP16、LLM 侧保持量化，若输出质量显著回升，说明误差由第一项主导，独立选比特宽就是误用。</p>\n<p>第二类误用是把均匀量化方差界当作精确误差预测。第三项 <span>(Δ_q²/12)·tr(W_projᵀW_proj)</span> 建立在噪声均匀、各通道等方差的假设上；AWQ/GPTQ 保留显著通道后噪声是非均匀的，该界偏保守，团队据此拒绝把某些层降到更低比特，错失可省带宽。反过来也有危险的一面：若把该界当“上界即实际值”，在非均匀噪声下实际误差可能在某些通道集中爆发，界给不出通道级定位。代价是显存与带宽的浪费——保守估计让本可 INT4 的投影层停留在 INT8，权重带宽翻倍，解码阶段每 token 的访存时间上升。</p>\n<p>第三类误用最隐蔽：对视觉 token 沿用文本 token 的激活量化校准。视觉 token 的激活异常值远大于文本 token，SmoothQuant 式通道缩放若按文本动态范围定标，视觉侧激活量化误差会超出该界，且这种误差不体现在权重项里，前两项看起来都很小。系统代价是 prefill 阶段视觉 token 的激活显存峰值被低估，连续批处理下视觉请求与文本请求混批时，视觉样本把整批的激活尺度拉爆，拖累同批文本请求的数值稳定性。识别方法是分别统计视觉与文本 token 的激活最大值分布，若视觉侧超出校准范围一个数量级以上，就该为视觉 token 单独保留异常值通道或独立校准。</p>\n<p>反例：某系统把视觉编码器量化到 INT8、LLM 量化到 INT4，两侧都用纯文本校准集调参，投影层保持 FP16。按公式估算，第二项 <span>‖Δ_llm‖₂·‖h_vis‖₂</span> 因 h_vis 幅值不大而显得可控，团队判定总误差可接受。但实际部署中图像问答准确率明显下滑，而纯文本困惑度不变。逐项拆解发现：投影矩阵谱范数较大，第一项被低估；同时视觉 token 激活异常值超出文本校准范围，激活量化误差未被建模。修复动作不是把 LLM 升回 FP8，而是给视觉编码器保留 FP16 异常值通道、为视觉 token 单独校准激活，并把投影层纳入量化感知评估。这个反例的教训是：界的三项必须同时估，任何一项被“文本经验”替代，界就失效；而失效时最贵的代价往往不是精度，是排障时间——因为困惑度这个代理指标完全不报警。工程判断应落在：先用 <span>‖W_proj‖₂</span> 与迹项定视觉侧最低比特，再用 <span>‖h_vis‖₂</span> 判断 LLM 侧激活是否需保留异常值通道，两侧比特宽由同一个误差预算联合求解，而非各自独立拍板。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>\\Delta_{\\mathrm{vis}}</td><td>视觉编码器输出量化误差向量</td></tr><tr><td>\\Delta_{\\mathrm{llm}}</td><td>LLM 权重/激活量化误差</td></tr><tr><td>W_{\\mathrm{proj}}</td><td>视觉到语言空间的投影矩阵</td></tr><tr><td>h_{\\mathrm{vis}}</td><td>投影后的视觉嵌入</td></tr><tr><td>\\Delta_q</td><td>量化步长</td></tr><tr><td>\\hat{y},y</td><td>量化后与全精度输出</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-multimodal-quant-error-bound · 共 5 个片段</p>\n"}];})();
